    // بارگذاری وضعیت حساب‌ها
    loadCashboxesSummary();
    // رسم نمودار مقایسه امروز/دیروز
    loadComparisonChart(todayIncome, todaySales, todayExpenses, yesterdayIncome);
    // رسم نمودار آمار پیشرفته
    if (typeof initAdvStatsChart === 'function') initAdvStatsChart();
