// فیلتر اشخاص

// فیلتر محصولات
// تابع برای بستن همه زیرمنوها
function closeAllSubmenus() {
    const sections = document.querySelectorAll('.menu-section.open');
    sections.forEach(section => {
        section.classList.remove('open');
        const submenu = section.querySelector('.submenu');
        if (submenu) {
            submenu.style.maxHeight = '0';
        }
    });
}

// فیلتر مصارف — نسخهٔ جدید: کارت‌ردیف‌ها بازطراحی‌شده را حفظ می‌کند و فقط
// ردیف‌های غیرمطابق را پنهان می‌کند (به‌جای بازسازی با ساختار قدیمی جدول).
function filterExpenses() {
    try {
        loadExpensesList(); // اطمینان از وجود کارت‌ردیف‌ها با dataset
        const categoryFilter = (document.getElementById('filter-expense-category') || {}).value || 'all';
        const fromDate = (document.getElementById('filter-expense-from') || {}).value || '';
        const toDate = (document.getElementById('filter-expense-to') || {}).value || '';
        const rows = document.querySelectorAll('#expenses-table tbody tr.product-card-row');
        const f = _normJalaliCmp(fromDate);
        const t = _normJalaliCmp(toDate);
        rows.forEach(row => {
            let show = true;
            if (categoryFilter !== 'all' && (row.dataset.category || '') !== categoryFilter) show = false;
            const d = _normJalaliCmp(row.dataset.date || '');
            if (show && f && d && d < f) show = false;
            if (show && t && d && d > t) show = false;
            row.style.display = show ? '' : 'none';
        });
    } catch (error) {
        console.error('خطا در فیلتر مصارف:', error);
    }
}

// ───────── جستجو/مرتب‌سازی صفحهٔ مصارفات و کارمندان (فقط UI، بدون منطق جدید) ─────────
function _pageRowSearch(rowsSelector, q) {
    var query = (q || '').trim().toLowerCase();
    document.querySelectorAll(rowsSelector).forEach(function (row) {
        var hay = row.dataset.search || row.textContent.toLowerCase();
        row.style.display = (!query || hay.indexOf(query) !== -1) ? '' : 'none';
    });
}
function searchExpensesList(q) { _pageRowSearch('#expenses-table tbody tr.product-card-row', q); }
function searchEmployeesList(q) { _pageRowSearch('#employees-table tbody tr.product-card-row', q); }

function _pageRowSort(tbodySelector, rowsSelector, getKey, asc) {
    var tbody = document.querySelector(tbodySelector);
    if (!tbody) return;
    var rows = Array.prototype.slice.call(document.querySelectorAll(rowsSelector));
    rows.sort(function (a, b) {
        var ka = getKey(a), kb = getKey(b);
        if (ka < kb) return asc ? -1 : 1;
        if (ka > kb) return asc ? 1 : -1;
        return 0;
    });
    rows.forEach(function (r) { tbody.appendChild(r); });
}
function sortExpensesList(mode) {
    if (mode === 'amount-desc') _pageRowSort('#expenses-table tbody', '#expenses-table tbody tr.product-card-row', function(r){return parseFloat(r.dataset.amount||0)||0;}, false);
    else if (mode === 'amount-asc') _pageRowSort('#expenses-table tbody', '#expenses-table tbody tr.product-card-row', function(r){return parseFloat(r.dataset.amount||0)||0;}, true);
    else if (mode === 'date-asc') _pageRowSort('#expenses-table tbody', '#expenses-table tbody tr.product-card-row', function(r){return _normJalaliCmp(r.dataset.date||'');}, true);
    else _pageRowSort('#expenses-table tbody', '#expenses-table tbody tr.product-card-row', function(r){return _normJalaliCmp(r.dataset.date||'');}, false);
}
function sortEmployeesList(mode) {
    if (mode === 'salary-desc') _pageRowSort('#employees-table tbody', '#employees-table tbody tr.product-card-row', function(r){return parseFloat(r.dataset.salary||0)||0;}, false);
    else if (mode === 'salary-asc') _pageRowSort('#employees-table tbody', '#employees-table tbody tr.product-card-row', function(r){return parseFloat(r.dataset.salary||0)||0;}, true);
    else if (mode === 'name-desc') _pageRowSort('#employees-table tbody', '#employees-table tbody tr.product-card-row', function(r){return (r.dataset.name||'');}, false);
    else _pageRowSort('#employees-table tbody', '#employees-table tbody tr.product-card-row', function(r){return (r.dataset.name||'');}, true);
}

// فیلتر تراکنش‌های حساب
function filterCashboxTransactions() {
    try {
        const cashboxId = document.getElementById('cashbox-transaction-filter').value;
        const transactions = db.getTransactions();
        const expenses = db.getExpenses();
        
        // ترکیب تراکنش‌ها و مصارف
        const allTransactions = [
            ...transactions.map(t => ({...t, source: 'transaction'})),
            ...expenses.map(e => ({...e, source: 'expense', type: 'مصرف'}))
        ];
        
        let filtered = allTransactions;
        if (cashboxId !== 'all') {
            filtered = allTransactions.filter(t => t.cashboxId == cashboxId);
        }
        
        // نمایش نتایج
        const tbody = document.querySelector('#cashbox-transactions-table tbody');
        if (!tbody) return;
        
        tbody.innerHTML = '';
        
        filtered.forEach(trans => {
            const row = document.createElement('tr');
            // برای فروش و خرید: مبلغ واقعی دریافتی/پرداختی در حساب (نه مبلغ کل بل)
            var _trCur = trans.currency || _baseCur();
            var _trAmount = parseFloat(trans.totalAmount || trans.amount || 0);
            if (trans.type === 'فروش') {
                _trAmount = _trCur === 'USD'
                    ? parseFloat(trans.cashUsd || 0)
                    : parseFloat(trans.cashAfn || 0);
            } else if (trans.type === 'خرید') {
                _trAmount = _trCur === 'USD'
                    ? parseFloat(trans.paidUsd || trans.cashUsd || 0)
                    : parseFloat(trans.paidAfn || trans.cashAfn || 0);
            }
            row.innerHTML = `
                <td>${formatAfghanDateTime(trans.date, trans.createdAt)}</td>
                <td>${trans.cashboxId || '---'}</td>
                <td>${trans.type}</td>
                <td>${formatCurrency(_trAmount)}</td>
                <td><span class="badge badge-secondary">${trans.currency || _baseCur()}</span></td>
                <td>${trans.description || trans.notes || trans.title || '---'}</td>
            `;
            tbody.appendChild(row);
        });
    } catch (error) {
        console.error('خطا در فیلتر تراکنش‌های حساب:', error);
    }
}
// تابع کمکی برای تبدیل اعداد فرمت شده به عدد
function parseFormattedNumber(formattedNum) {
    if (!formattedNum) return 0;
    // تبدیل ارقام فارسی/عربی به انگلیسی
    var numStr = formattedNum.toString()
        .replace(/[۰٠]/g, '0').replace(/[۱١]/g, '1').replace(/[۲٢]/g, '2')
        .replace(/[۳٣]/g, '3').replace(/[۴٤]/g, '4').replace(/[۵٥]/g, '5')
        .replace(/[۶٦]/g, '6').replace(/[۷٧]/g, '7').replace(/[۸٨]/g, '8')
        .replace(/[۹٩]/g, '9')
        .replace(/[٫]/g, '.')
        .replace(/[^\d.\-]/g, ''); // حذف همه چیز به جز اعداد، نقطه و منفی
    return parseFloat(numStr) || 0;
}

// محاسبه باقی‌مانده واقعی هر معامله از روی داده‌ها (نه از مقدار ذخیره شده)
//  چند-ارزی: پرداختیِ هر ارز از نگاشتِ cashAmounts/paidAmounts خوانده می‌شود و برای
//  تبدیلِ ارزهای دیگر به ارزِ سند، «نرخِ ثبت‌شدهٔ همان سند» (rateUsed/exchangeRateSnapshot)
//  استفاده می‌شود — تا با تغییرِ نرخِ روز در آینده، باقی‌ماندهٔ اسنادِ قدیمی تغییر نکند.
function _txPaidInDocCurrency(tx, isPurchase) {
    var docCur = tx.currency || _baseCur();
    var map = isPurchase ? tx.paidAmounts : tx.cashAmounts;
    // نرخِ USD→AFN معتبر برای همین سند (اولویت: نرخِ ثبت‌شده روی سند)
    var usdToAfn = 0;
    if (docCur === 'USD' && parseFloat(tx.rateUsed) > 0) usdToAfn = parseFloat(tx.rateUsed);
    if (!usdToAfn && tx.exchangeRateSnapshot && tx.exchangeRateSnapshot.currency === 'USD' &&
        parseFloat(tx.exchangeRateSnapshot.rate) > 0) usdToAfn = parseFloat(tx.exchangeRateSnapshot.rate);
    if (!usdToAfn) {
        try {
            if (typeof CurrencySystem !== 'undefined' && CurrencySystem.rateValue) {
                var _r = CurrencySystem.rateValue('USD', 'AFN', 'rate');
                if (_r != null && _r > 0) usdToAfn = _r;
            }
        } catch (e) {}
    }
    // اصلاحِ باگ: نرخِ جعلیِ ثابتِ «۸۰» حذف شد. اگر نه نرخِ سند و نه نرخِ روز موجود
    // نباشد، هیچ نرخی جعل نمی‌شود؛ تبدیلِ آن جزء از مسیرِ موتور انجام و در نبودِ نرخ
    // نادیده گرفته می‌شود (به‌جای عددِ اشتباه). usdToAfn فقط وقتی نرخِ معتبر دارد.

    // تبدیلِ یک مبلغ از ارزِ c به ارزِ سند — همیشه از موتورِ مرکزی، بدونِ نرخِ ثابت.
    var _toDoc = function (v, fromCur) {
        v = parseFloat(v) || 0;
        if (!v || fromCur === docCur) return v;
        // AFN↔USD: اگر نرخِ سند/روزِ معتبر داریم، همان؛ وگرنه از موتور.
        if (usdToAfn > 0) {
            if (docCur === 'AFN' && fromCur === 'USD') return v * usdToAfn;
            if (docCur === 'USD' && fromCur === 'AFN') return v / usdToAfn;
        }
        try {
            if (typeof CurrencySystem !== 'undefined' && CurrencySystem.convert) {
                var cv = CurrencySystem.convert(v, fromCur, docCur, 'rate');
                if (cv != null) return cv;
            }
        } catch (e) {}
        return 0;   // بدونِ نرخِ معتبر، به‌جای نرخِ جعلی، این جزء لحاظ نمی‌شود
    };

    // ۱) نگاشتِ چند-ارزی (اسنادِ جدید)
    if (map && typeof map === 'object' && !Array.isArray(map)) {
        var sum = 0;
        Object.keys(map).forEach(function (c) {
            var v = parseFloat(map[c]) || 0;
            if (!v) return;
            if (c === docCur) { sum += v; return; }
            sum += _toDoc(v, c);
        });
        return sum;
    }

    // ۲) اسنادِ قدیمی — فیلدهای دوتایی + فیلدِ ارزِ سوم
    var a = parseFloat(isPurchase ? (tx.paidAfn != null ? tx.paidAfn : tx.cashAfn) : tx.cashAfn) || 0;
    var u = parseFloat(isPurchase ? (tx.paidUsd != null ? tx.paidUsd : tx.cashUsd) : tx.cashUsd) || 0;
    var f = parseFloat(isPurchase ? tx.paidForeign : tx.cashForeign) || 0;
    if (docCur === 'USD') return u + _toDoc(a, 'AFN');
    if (docCur === 'AFN') return a + _toDoc(u, 'USD');
    // ارزِ سوم: فیلدِ اختصاصیِ همان ارز (قبلاً کاملاً نادیده گرفته می‌شد)
    return f;
}

function calculateTxRemaining(tx) {
    if (!tx) return 0;
    var totalAmount = parseFloat(tx.totalAmount || tx.amount || 0);
    if (tx.type === 'فروش' || tx.type === 'پیش‌فاکتور') {
        return totalAmount - _txPaidInDocCurrency(tx, false);
    } else if (tx.type === 'خرید') {
        return totalAmount - _txPaidInDocCurrency(tx, true);
    }
    // برای دریافت/پرداخت، باقی‌مانده ندارند
    return parseFloat(tx.remaining || 0);
}

