function saveCashbox() {
    const name = document.getElementById('cashbox-name').value;
    const currency = document.getElementById('cashbox-currency').value;
    const initialBalance = parseFloat(document.getElementById('cashbox-initial-balance').value) || 0;
    const location = document.getElementById('cashbox-location').value;
    const description = document.getElementById('cashbox-description').value;
    var _cbTypeEl = document.getElementById('cashbox-type');
    const cbType = _cbTypeEl ? (_cbTypeEl.value || 'خزانه') : 'خزانه';
    
    if (!name) { showMessage('خطا', 'لطفاً نام حساب را وارد کنید.'); return; }
    // اگر موجودی اولیه وارد شده، ارزِ آن الزامی است تا در ارزِ درست ثبت شود
    if (initialBalance > 0 && !currency) { showMessage('خطا', 'لطفاً ارزِ موجودی اولیه را انتخاب کنید (از کارت نرخ ارز).'); return; }
    
    const editId = document.getElementById('cashboxForm').dataset.editId;
    // حساب دیگر «ارزِ حساب» ندارد؛ همهٔ ارزها را می‌پذیرد و موجودیِ هر ارز در balances نگه داشته می‌شود.
    const cashbox = { name, currency: currency || '', location, description, type: cbType };
    
    // مقدار موجودی قبلی حساب (برای محاسبه اختلاف هنگام ویرایش)
    var _oldCashboxBalance = 0;
    if (editId) {
        cashbox.id = parseInt(editId);
        // ====== اصلاح ریشه‌ای: در ویرایش، تغییر «موجودی اولیه/فعلی» باید روی موجودی حساب اعمال شود ======
        // فیلد فرم در editCashbox با cashbox.balance (موجودی منبعِ حقیقت) پر می‌شود؛ پس همان مقدار
        // باید دوباره به balance نوشته شود تا ویرایش اثر کند. balance منبع حقیقت است و همهٔ محاسبات
        // سراسری (سرمایه، گزارش‌ها، موجودی اولیهٔ معکوس) از روی آن مشتق می‌شوند، پس هماهنگی حفظ می‌شود.
        try {
            var _existingCb = (db.getCashboxes() || []).find(function(c){ return c.id == cashbox.id; });
            _oldCashboxBalance = _existingCb ? (parseFloat(_existingCb.balance) || 0) : 0;
        } catch (e) { _oldCashboxBalance = 0; }
        cashbox.balance = initialBalance;
    } else {
        cashbox.balance = initialBalance;
    }
    
    const result = db.saveCashbox(cashbox);
    if (!result.success) { showMessage('خطا', result.error || 'خطا در ذخیره حساب'); return; }
    
    // ====== درخواست کاربر: مبلغ اولیه حساب در فهرست معاملات حساب ثبت شود ======
    if (!editId && initialBalance > 0 && result.data && result.data.id) {
        try {
            if (typeof _logCashboxTransaction === 'function') {
                _logCashboxTransaction(result.data.id, {
                    type: 'deposit_external',
                    amount: initialBalance,
                    currency: currency,
                    notes: 'موجودی اولیه صندوق هنگام ایجاد',
                    description: 'موجودی اولیه صندوق'
                });
            }
        } catch (e) { console.warn('initial balance log failed:', e); }
    }
    
    // ====== اصلاح ریشه‌ای: هماهنگ‌سازی فهرست معاملات حساب با موجودی جدید هنگام ویرایش ======
    // موجودیِ اولیه به‌صورت معکوس (initial = balance − totalEffect تراکنش‌ها) محاسبه می‌شود.
    // برای آنکه فهرست معاملات با balanceِ جدید هماهنگ بماند، رکوردِ لاگِ «موجودی اولیه صندوق»
    // را به اندازهٔ اختلاف تنظیم می‌کنیم (نه ساخت تراکنش جدید). اگر چنین لاگی نباشد، یکی می‌سازیم.
    if (editId && result.data && result.data.id) {
        try {
            var _cbDiff = initialBalance - _oldCashboxBalance;
            if (_cbDiff !== 0) {
                var _cbKey = 'cashboxTransactions';
                var _cbList = [];
                try { _cbList = JSON.parse(localStorage.getItem(_cbKey) || '[]'); } catch (e) { _cbList = []; }
                if (!Array.isArray(_cbList)) _cbList = [];
                // یافتن رکورد موجودی اولیهٔ همین حساب
                var _openIdx = _cbList.findIndex(function(l){
                    return l && l.cashboxId == result.data.id
                        && l.type === 'deposit_external'
                        && typeof l.notes === 'string'
                        && l.notes.indexOf('موجودی اولیه صندوق') !== -1;
                });
                if (_openIdx !== -1) {
                    var _curOpen = parseFloat(_cbList[_openIdx].amount || 0) + _cbDiff;
                    _cbList[_openIdx].amount = _curOpen;
                    _cbList[_openIdx].currency = currency;
                    localStorage.setItem(_cbKey, JSON.stringify(_cbList));
                } else if (typeof _logCashboxTransaction === 'function') {
                    // لاگ موجودی اولیه وجود نداشت (حساب قدیمی) — اختلاف را به‌عنوان ردیف موجودی اولیه ثبت کن
                    _logCashboxTransaction(result.data.id, {
                        type: 'deposit_external',
                        amount: _cbDiff,
                        currency: currency,
                        notes: 'موجودی اولیه صندوق (اصلاح هنگام ویرایش)',
                        description: 'موجودی اولیه صندوق'
                    });
                }
            }
        } catch (e) { console.warn('cashbox edit balance sync failed:', e); }
    }
    
    showMessage('موفقیت', 'حساب با موفقیت ذخیره شد.'); addChangelog(editId ? 'ویرایش' : 'ثبت', 'صندوق', cashbox, (editId ? 'ویرایش' : 'ثبت') + ' حساب');
    
    // ریست فرم و برگشت به تب حساب‌ها
    document.getElementById('cashboxForm').reset();
    var _ibReset = document.getElementById('cashbox-initial-balance'); if (_ibReset) _ibReset.value = '';
    delete document.getElementById('cashboxForm').dataset.editId;
    const formTitle = document.querySelector('#cashbox-form .jf-title');
    if (formTitle) formTitle.textContent = 'ایجاد حساب جدید';
    
    showSection('financial');
    setTimeout(() => { switchFinancialTab('cashbox'); }, 100);
}
// ================ توابع ذخیره سازی (Save Functions) ================

// ذخیره شخص
function savePerson() {
    const editId = document.getElementById('personForm').dataset.editId;
    
    // ====== درخواست کاربر: اگر حساب قبلی > 0 باشد، نوع حساب اجباری است ======
    var _prevAccountVal = parseFloat(document.getElementById('person-previous-account').value) || 0;
    var _accountTypeVal = document.getElementById('person-account-type').value;
    if (_prevAccountVal > 0 && (!_accountTypeVal || _accountTypeVal === 'بدون حساب')) {
        showMessage('خطا', 'وقتی حساب قبلی وارد می‌شود، انتخاب نوع حساب (بدهکار یا طلبکار) اجباری است.');
        return;
    }
    
    const personData = {
        name: document.getElementById('person-name').value,
        category: document.getElementById('person-category').value,
        phone: document.getElementById('person-phone').value,
        idNumber: document.getElementById('person-id').value,
        address: document.getElementById('person-address').value,
        accountType: document.getElementById('person-account-type').value,
        currency: document.getElementById('person-currency').value,
        previousAccount: parseFloat(document.getElementById('person-previous-account').value) || 0,
        notes: document.getElementById('person-notes').value
    };
    
    if (editId) {
        personData.id = parseInt(editId);
    }
    
    // ====== درخواست کاربر: وقتی شخص ویرایش می‌شود و از حساب قبلی پرداخت می‌کند،
    // باید یک معامله «پرداخت از حساب قبلی» در فهرست معاملات شخص ثبت شود ======
    var _prevAccountSnapshot = null;
    if (editId) {
        try {
            var _existingPersons = (db.getPersons && db.getPersons()) || [];
            var _existingPerson = _existingPersons.find(function(p) { return p.id == editId; });
            if (_existingPerson) {
                _prevAccountSnapshot = {
                    previousAccount: parseFloat(_existingPerson.previousAccount) || 0,
                    accountType: _existingPerson.accountType || 'بدون حساب',
                    currency: _existingPerson.currency || _baseCur()
                };
            }
        } catch (e) { _prevAccountSnapshot = null; }
    }
    
    const result = db.savePerson(personData);
    
    if (result.success) {
        // ====== اصلاح ریشه‌ای: حذف تراکنش تکراری «پرداخت از حساب قبلی» هنگام ویرایش ======
        // مشکل قبلی: هنگام ویرایش مبلغِ «حساب قبلی»، خودِ person.previousAccount به مقدار جدید
        // UPDATE می‌شود و همیشه به‌عنوان «ردیف اول مانده» در محاسبهٔ حساب لحاظ می‌گردد. اما کد
        // علاوه بر آن، یک تراکنشِ جداگانهٔ «پرداخت از حساب قبلی» به اندازهٔ اختلاف ثبت می‌کرد.
        // در نتیجه اختلاف دو بار اعمال می‌شد:
        //   • کاهش بدهکار ۱۰۰۰۰→۸۰۰۰ : ردیف حساب قبلی = ۸۰۰۰، تراکنش اضافی = −۲۰۰۰ → ۶۰۰۰ (غلط)
        //   • افزایش طلب ۱۰۰۰۰→۲۰۰۰۰ : رکورد اصلی UPDATE می‌شد ولی یک تراکنش اضافیِ ۱۰۰۰۰ هم می‌ماند
        // راه‌حل ریشه‌ای: چون previousAccount خودش به‌روزرسانی (UPDATE) می‌شود و منبعِ حقیقتِ
        // مانده است، نباید هیچ تراکنشِ INSERTِ جداگانه‌ای ساخته شود. اختلاف فقط یک‌بار (از طریق
        // همان رکوردِ UPDATE‌شده) اعمال می‌گردد. _prevAccountSnapshot صرفاً برای ثبت در تاریخچهٔ
        // تغییرات (changelog) نگه داشته می‌شود و دیگر هیچ تراکنشی تولید نمی‌کند.
        
        showMessage('موفقیت', 'اطلاعات فرد با موفقیت ذخیره شد.'); addChangelog(editId ? 'ویرایش' : 'ثبت', 'شخص', personData, (editId ? 'ویرایش' : 'ثبت') + ' شخص');
        // ذخیره و هدایت فوری بدون تأخیر
        delete document.getElementById('personForm').dataset.editId;
        if (typeof resetPersonForm === 'function') resetPersonForm();
        // اگر در حالت انتخاب (picker) هستیم، شخص جدید را مستقیم انتخاب کن
        if (_personPickerCallback && result.data) {
            _personPickerCallback(result.data);
            _personPickerCallback = null;
            _personPickerCategory = null;
            var ret = _personPickerReturnSection;
            if (ret) {
                showSection(ret);
                _personPickerReturnSection = null;
            } else {
                _personPickerReturnSection = null;
                showSection('persons-list');
                if (typeof loadPersonsList === 'function') loadPersonsList();
            }
        } else if (_personDetailReturnForForm != null) {
            // اگر از «مشخصات شخص» ویرایش شده بود، به همان مشخصات با ارقام تازه برگرد
            var _retPersonId = _personDetailReturnForForm;
            _personDetailReturnForForm = null;
            if (typeof loadPersonsList === 'function') loadPersonsList();
            if (typeof showPersonDetail === 'function') showPersonDetail(_retPersonId);
        } else {
            showSection('persons-list');
            if (typeof loadPersonsList === 'function') loadPersonsList();
        }
    } else {
        showMessage('خطا', result.error || 'خطا در ذخیره اطلاعات');
    }
}

// ذخیره جنس
// نگه‌داری base64 عکس انتخاب‌شدهٔ جنس تا هنگام ذخیره (فقط وقتی عکس جدید انتخاب شده باشد)
var _pendingProductImageData = null;
function saveProduct() {
    const editId = document.getElementById('productForm').dataset.editId;
    
    // نرمال‌سازی ارقام به انگلیسی برای کد محصول (تا در ذخیره و بازیابی هماهنگ بماند)
    var _toEnP = (typeof toEnglishDigits === 'function') ? toEnglishDigits : function(x){ return x; };
    
    // ارزهای اضافیِ فرم جنس (پویا) — قبل از ساختِ productData جمع‌آوری می‌شوند
    var _extraPrices = (typeof _collectExtraCurrencyPrices === 'function') ? _collectExtraCurrencyPrices() : {};

    const productData = {
        name: document.getElementById('product-name').value,
        code: _toEnP(document.getElementById('product-code').value),
        categoryMain: document.getElementById('product-category-main').value,
        categorySub: document.getElementById('product-category-sub').value,
        unit: document.getElementById('product-unit').value,
        hasSecondaryUnit: (function(){ var el = document.getElementById('product-has-secondary-unit'); return !!(el && el.checked); })(),
        secondaryUnit: (function(){ var el = document.getElementById('product-secondary-unit'); return el ? (el.value || '') : ''; })(),
        secondaryUnitFactor: (function(){ var el = document.getElementById('product-secondary-unit-factor'); var v = el ? parseFloat(el.value) : 0; return (isNaN(v) || v <= 0) ? 0 : v; })(),
        secondaryPurchasePriceAFN: (function(){ var el = document.getElementById('product-secondary-purchase-price-afn'); var v = el ? el.value : ''; return v === '' ? 0 : (parseFloat(v) || 0); })(),
        secondaryPurchasePriceUSD: (function(){ var el = document.getElementById('product-secondary-purchase-price-usd'); var v = el ? el.value : ''; return v === '' ? 0 : (parseFloat(v) || 0); })(),
        secondarySalePriceAFN:     (function(){ var el = document.getElementById('product-secondary-sale-price-afn');     var v = el ? el.value : ''; return v === '' ? 0 : (parseFloat(v) || 0); })(),
        secondarySalePriceUSD:     (function(){ var el = document.getElementById('product-secondary-sale-price-usd');     var v = el ? el.value : ''; return v === '' ? 0 : (parseFloat(v) || 0); })(),
        secondaryInitialStock:     (function(){ var el = document.getElementById('product-secondary-initial-stock');     var v = el ? el.value : ''; return v === '' ? 0 : (parseFloat(v) || 0); })(),
        initialStock: parseFloat(document.getElementById('product-initial-stock').value) || 0,
        // expiryDate — تاریخ انقضاء جنس (به فرمت شمسی YYYY/MM/DD یا میلادی YYYY/MM/DD م)
        // این مقدار از فیلد product-min-expiry-days خوانده می‌شود (که با picker تاریخ پر می‌شود)
        // در فورم خرید فوری، در صورت ورود تاریخ انقضاء جدید، همین فیلد به‌روزرسانی می‌شود
        expiryDate: (function(){
            var _el = document.getElementById('product-min-expiry-days');
            var _v = _el ? String(_el.value || '').trim() : '';
            return _v;
        })(),
        purchasePriceAFN: (function(){ var v = document.getElementById('product-purchase-price-afn').value; return v === '' ? 0 : (parseFloat(v) || 0); })(),
        purchasePriceUSD: (function(){ var v = document.getElementById('product-purchase-price-usd').value; return v === '' ? 0 : (parseFloat(v) || 0); })(),
        salePriceAFN:     (function(){ var v = document.getElementById('product-sale-price-afn').value;     return v === '' ? 0 : (parseFloat(v) || 0); })(),
        salePriceUSD:     (function(){ var v = document.getElementById('product-sale-price-usd').value;     return v === '' ? 0 : (parseFloat(v) || 0); })(),
        description: document.getElementById('product-description').value,
        supplierId: (document.getElementById('product-supplier') ? document.getElementById('product-supplier').value : null) || null
    };
    
    // ادغامِ قیمت‌ها در نقشه‌های چند-ارزی. فیلدِ ثابتِ HTML به «ارزِ پایهٔ فعلی» نسبت
    // داده می‌شود (نه AFN ثابت)؛ بقیهٔ ارزها از ردیف‌های پویا می‌آیند. آینه‌های قدیمیِ
    // purchasePriceAFN/USD صرفاً برای سازگاریِ عقب‌روی کدِ قدیمی نگه داشته می‌شوند.
    var _pBaseCode = _baseCur();
    productData.purchasePrices = Object.assign({}, (_extraPrices.purchase || {}));
    productData.purchasePrices[_pBaseCode] = productData.purchasePriceAFN;
    productData.salePrices = Object.assign({}, (_extraPrices.sale || {}));
    productData.salePrices[_pBaseCode] = productData.salePriceAFN;
    productData.secondaryPurchasePrices = Object.assign({}, (_extraPrices.secPurchase || {}));
    productData.secondaryPurchasePrices[_pBaseCode] = productData.secondaryPurchasePriceAFN;
    productData.secondarySalePrices = Object.assign({}, (_extraPrices.secSale || {}));
    productData.secondarySalePrices[_pBaseCode] = productData.secondarySalePriceAFN;

    if (editId) {
        productData.id = parseInt(editId);
    }

    // ====== حالتِ «ویرایش موجودی اولیه» ======
    // قیمتِ واردشده = قیمتِ خریدِ سری اول (موجودی اولیه). فقط _batchInitialCostAFN/USD به‌روزرسانی
    // می‌شود تا موتورِ FIFO مفادِ همان موجودی اولیه را با قیمت جدید حساب کند و روی خریدهای بعدی
    // (که قیمت خریدِ مستقلِ خود را دارند) اثری نگذارد. اگر برای این جنس خریدی ثبت شده باشد،
    // «قیمت خریدِ فعلی/آخرین» دست‌نخورده می‌ماند (حذف از productData ⇒ ادغامِ dbساز مقدارِ قبلی را حفظ می‌کند).
    if (_editingInitialStock && editId) {
        var _pidEdit = parseInt(editId);
        productData._batchInitialCostAFN = productData.purchasePriceAFN;
        productData._batchInitialCostUSD = productData.purchasePriceUSD;

        // اصلاحِ ریشه‌ای: نگاشتِ «بهای موجودیِ اولیه» (_batchInitialCosts) هم باید با قیمتِ واردشده
        // به‌روز شود. همهٔ readerها (ردیفِ «موجودی اولیه»، میانگینِ موزونِ کارتِ مشخصات، موتورِ FIFO،
        // سرمایه و گزارش‌ها) این نگاشت را مقدم بر اسکالرها می‌خوانند؛ اگر فقط اسکالر به‌روز شود، برای
        // جنسی که خرید دارد و نگاشتش «منجمد» است، ویرایشِ قیمتِ موجودی اولیه در هیچ‌کجا دیده نمی‌شد
        // (علتِ اصلیِ «برای دیتای Import‌شده کار نمی‌کند» — چون اغلبِ آن اجناس خرید دارند).
        // روی نگاشتِ فعلیِ جنس ادغام می‌شود تا ارزهایی که در فرم نیستند حذف نشوند.
        try {
            var _curBIC = null;
            try {
                var _cpEdit = (typeof db !== 'undefined' && db.getAllProducts) ? (db.getAllProducts() || []).find(function (x) { return x.id == _pidEdit; }) : null;
                if (_cpEdit && _cpEdit._batchInitialCosts && typeof _cpEdit._batchInitialCosts === 'object' && !Array.isArray(_cpEdit._batchInitialCosts)) _curBIC = _cpEdit._batchInitialCosts;
            } catch (e) {}
            productData._batchInitialCosts = Object.assign({}, _curBIC || {},
                (productData.purchasePrices && typeof productData.purchasePrices === 'object' && !Array.isArray(productData.purchasePrices)) ? productData.purchasePrices : {});
        } catch (e) {}

        var _hasPurchase = false;
        try {
            var _allTxEdit = (typeof db !== 'undefined' && db.getTransactions) ? (db.getTransactions() || []) : [];
            _hasPurchase = _allTxEdit.some(function(t) {
                return t && t.type === 'خرید' && Array.isArray(t.items) && t.items.some(function(it) { return it && it.productId == _pidEdit; });
            });
        } catch (e) {}
        if (_hasPurchase) {
            // برای جنسِ دارای خرید، «قیمتِ خریدِ فعلی/آخرین» نباید با بهای موجودیِ اولیه عوض شود؛
            // پس نگاشت/اسکالرِ purchasePrice از productData حذف می‌شود تا ادغامِ dbساز مقدارِ قبلی را
            // حفظ کند. (بهای موجودیِ اولیه بالاتر جداگانه در _batchInitialCosts ثبت شد.)
            delete productData.purchasePriceAFN;
            delete productData.purchasePriceUSD;
            delete productData.purchasePrices;
        }
    }

    // عکس جنس: فقط اگر عکس جدیدی انتخاب شده باشد ذخیره می‌شود؛
    // در ویرایش، نفرستادن این فیلد باعث حفظ عکس قبلی می‌شود (db.saveProduct ادغام می‌کند)
    if (_pendingProductImageData) {
        productData.image = _pendingProductImageData;
    }

    const result = db.saveProduct(productData);
    _editingInitialStock = false;
    
    if (result.success) {
        showMessage('موفقیت', 'اطلاعات جنس با موفقیت ذخیره شد.'); addChangelog(editId ? 'ویرایش' : 'ثبت', 'جنس', productData, (editId ? 'ویرایش' : 'ثبت') + ' جنس');
        // ذخیره و هدایت فوری بدون تأخیر
        // پاک‌سازی editId و فرم
        delete document.getElementById('productForm').dataset.editId;
        _pendingProductImageData = null;
        if (typeof resetProductForm === 'function') resetProductForm();
        if (_productPickerInput && result.data) {
            // در حالت picker: جنس جدید را مستقیم انتخاب کن
            _selectProductForPicker(result.data);
        } else if (_productDetailReturnForForm != null) {
            // اگر از «مشخصات جنس» ویرایش شده بود، به همان مشخصات با ارقام تازه برگرد
            var _retDetailId = _productDetailReturnForForm;
            _productDetailReturnForForm = null;
            if (typeof loadProductsList === 'function') loadProductsList();
            if (typeof showProductDetail === 'function') showProductDetail(_retDetailId);
        } else {
            showSection('products-list');
            if (typeof loadProductsList === 'function') loadProductsList();
        }
    } else {
        showMessage('خطا', result.error || 'خطا در ذخیره اطلاعات');
    }
}

// ذخیره فروش
// ذخیره فروش - جایگزین تابع saveSale فعلی
// ==========================================================================
// توابع اصلاح شده ثبت دکمه‌های سریع (خرید، فروش، دریافت و پرداخت)
// ==========================================================================

function saveSale() {
    const customerId = document.getElementById('qs-customer').value;
    const customerInput = document.getElementById('qs-customer-search');
    const customerName = (customerInput && customerInput.value) ? customerInput.value : 'مشتری عمومی';
    
    // نرمال‌سازی ارقام به انگلیسی برای تاریخ و شماره بل (تا در ذخیره و بازیابی هماهنگ بمانند)
    var _toEn = (typeof toEnglishDigits === 'function') ? toEnglishDigits : function(x){ return x; };
    const date = _toEn(document.getElementById('sales-date').value);
    const billNumber = _toEn(document.getElementById('sales-bill-number').value);
    const currency = document.getElementById('sales-currency').value;
    const type = document.getElementById('sales-type').value;
    const notes = document.getElementById('sales-notes').value;
    
    if (!customerId) {
        showMessage('خطا', 'لطفاً مشتری را از جستجو انتخاب کنید.');
        return;
    }
    
    // ====== درخواست کاربر: بدون انتخاب حساب نباید فروش صورت گیرد ======
    var _cashboxIdCheck = document.getElementById('sales-cashbox')?.value || '';
    if (!_cashboxIdCheck) {
        showMessage('خطا', 'لطفاً حساب را انتخاب کنید. بدون اتصال به حساب، فروش امکان‌پذیر نیست.');
        return;
    }
    
    const items = [];
    const _prodsAtSale = (typeof db !== 'undefined' && db.getProducts) ? (db.getProducts() || []) : [];
    const rows = document.querySelectorAll('#sales-items-body .item-row');
    let hasError = false;
    
    rows.forEach(row => {
        const productSelect = row.querySelector('.item-product');
        const productId = productSelect.value;
        if (!productId) return;

        let productName = 'جنس نامشخص';
        if(productSelect.options && productSelect.selectedIndex >= 0 && productSelect.options.length > 0) {
            productName = productSelect.options[productSelect.selectedIndex].text.split(' (')[0];
        } else {
            const searchInput = row.querySelector('.product-search-input');
            if(searchInput) productName = searchInput.value;
        }

        const quantity = parseFloat(row.querySelector('.item-quantity').value) || 0;
        const unit = row.querySelector('.item-unit').textContent;
        const price = parseFloat(row.querySelector('.item-price').value) || 0;
        const discount = parseFloat(row.querySelector('.item-discount').value) || 0;
        const total = parseFloat(row.querySelector('.item-total').textContent.replace(/,/g, '')) || 0;
        var _unitType = row.dataset.unitType || 'primary';
        var _secFactor = parseFloat(row.dataset.secondaryFactor) || 0;
        
        if (quantity > 0 && price > 0) {
            // تشخیص خدمت از جنس: اگر productId با SVC- شروع شود، خدمت است
            var isService = (typeof productId === 'string') && productId.indexOf('SVC-') === 0;
            // اجازه فروش حتی اگر موجودی کافی نباشد — موجودی منفی می‌شود (بدهی انبار)
            var _saleItm = {
                productId: isService ? productId : parseInt(productId),
                productName: isService ? productName : productName,
                isService: isService,
                quantity: quantity, unit: unit, price: price, discount: discount, total: total,
                unitType: _unitType, secondaryFactor: _secFactor
            };
            // قفل‌کردن قیمت خریدِ مبنای مفاد روی لحظهٔ فروش (فقط برای فروشِ غیرکسری)
            if (!isService && typeof _saleCostSnapshot === 'function') {
                var _snapProd = _prodsAtSale.find(function(p){ return p.id == parseInt(productId); });
                var _snap = _saleCostSnapshot(_snapProd, quantity, _unitType, _secFactor);
                if (_snap) { _saleItm.purchasePriceAFN = _snap.purchasePriceAFN; _saleItm.purchasePriceUSD = _snap.purchasePriceUSD; }
            }
            items.push(_saleItm);
        }
    });
    
    if (hasError) return;
    if (items.length === 0) {
        showMessage('خطا', 'لطفاً حداقل یک جنس به فاکتور اضافه کنید.');
        return;
    }
    
    const subTotal = items.reduce((sum, item) => sum + (item.quantity * item.price), 0);
    // تخفیف کل = تخفیف اقلام + تخفیف کلیِ بل (مقدارِ نمایش‌داده‌شده در فرم شامل هر دو است)
    var _perItemDisc = items.reduce((sum, item) => sum + item.discount, 0);
    var _sDiscEl = document.getElementById('sales-total-discount');
    var _sDomDisc = (_sDiscEl && _sDiscEl.dataset && _sDiscEl.dataset.raw !== undefined) ? parseFloat(_sDiscEl.dataset.raw) : NaN;
    const totalDiscount = (!isNaN(_sDomDisc) && _sDomDisc >= _perItemDisc) ? _sDomDisc : _perItemDisc;
    const totalAmount = subTotal - totalDiscount;

    // ── مدلِ پویا: فیلدِ اصلی = ارزِ پایه، فیلدِ foreign = هر ارزِ غیرپایه ──
    var _baseSale = _baseCur();
    var _isForeignSale = (currency !== _baseSale);   // «غیرپایه» جای «غیرِ AFN/USD»
    const cashAfn = _isForeignSale ? 0 : (parseFloat((document.getElementById('sales-cash-afn') || {}).value) || 0);
    const cashUsd = 0; // فیلدِ USD قدیمی در مدلِ جدید نقشی ندارد (سازگاریِ عقب‌رو فقط در خواندنِ اسناد)
    var cashForeign = 0;
    if (_isForeignSale) {
        cashForeign = parseFloat((document.getElementById('sales-cash-foreign') || {}).value) || 0;
    }
    const remainingInput = document.getElementById('sales-remaining');
    const remaining = remainingInput ? (parseFormattedNumber(remainingInput.value)) : 0;
    const cashboxId = document.getElementById('sales-cashbox')?.value || '';
    
    // محاسبه سود فروش = مجموع (قیمت فروش - قیمت خرید) × تعداد
    const _allProducts = (typeof db !== 'undefined' && db.getProducts) ? (db.getProducts() || []) : [];
    var profit = 0;
    items.forEach(function(it) {
        if (it.isService) return; // خدمات سود ندارند (یا کل قیمت سود است — منطق ساده)
        var prod = _allProducts.find(function(p){ return p.id == it.productId; });
        if (!prod) return;
        var purchasePrice;
        // بهای تمام‌شده از حل‌کنندهٔ مرکزی — برای هر ارز (شاملِ ارزِ سوم) یکسان عمل می‌کند
        var _cr = _resolveProductPrice(prod, currency, 'purchase', (it.unitType === 'secondary') ? 'secondary' : 'primary');
        purchasePrice = _cr.price || 0;
        if (!purchasePrice) {
            // fallback از حل‌کنندهٔ مرکزیِ دیتابیس — یکسان برای هر ارز، بدونِ هاردکدِ AFN/USD.
            purchasePrice = (typeof db !== 'undefined' && db.getPurchasePrice) ? (parseFloat(db.getPurchasePrice(prod, currency)) || 0) : 0;
        }
        var lineProfit = ((parseFloat(it.price) || 0) - purchasePrice) * (parseFloat(it.quantity) || 0) - (parseFloat(it.discount) || 0);
        profit += lineProfit;
    });
    
    const editId = document.getElementById('salesForm')?.dataset?.editId;
    
    if (editId) {
        // حالت ویرایش - بروزرسانی معامله موجود
        const transaction = {
            id: parseInt(editId),
            type: 'فروش', customerId: parseInt(customerId), customerName, date, billNumber, currency, saleType: type,
            items, subTotal, totalDiscount, totalAmount, cashAfn, cashUsd, cashForeign, cashForeignCurrency: (_isForeignSale ? currency : null), remaining, notes,
            // نگاشتِ نقدیِ چند-ارزی + نرخِ لحظهٔ ثبت (تا گزارش‌های گذشته با تغییرِ نرخ خراب نشوند)
            cashAmounts: _buildCashAmounts(currency, cashAfn, cashUsd, cashForeign),
            rateUsed: _dayRateFor(currency),
            baseCurrency: (typeof CurrencySystem !== 'undefined' && CurrencySystem.getBaseCode) ? CurrencySystem.getBaseCode() : 'AFN',
            profit: profit,
            cashboxId: cashboxId ? parseInt(cashboxId) : null,
            status: remaining > 0 ? 'باقی‌مانده' : 'تسویه‌شده'
        };
        
        const result = db.saveTransaction(transaction);
        if (result.success !== false) {
            showMessage('موفقیت', 'فاکتور فروش با موفقیت ویرایش شد.'); addChangelog('ویرایش', 'فروش', transaction, 'ویرایش فاکتور فروش');
            delete document.getElementById('salesForm').dataset.editId;
            if (typeof resetSalesForm === 'function') resetSalesForm();
            // اگر از لیستِ معاملاتِ فرد (یا داشبورد) آمده، به همان‌جا برگردد؛ وگرنه لیستِ فروش
            if (!_consumeFormReturn()) {
                showSection('sales-list');
                if (typeof loadSalesList === 'function') loadSalesList();
            }
        } else {
            showMessage('خطا', result.error || 'خطا در ویرایش فاکتور');
        }
    } else {
        // حالت جدید — ثبت فروش واقعی (نه پیش‌فاکتور — پیش‌فاکتور دکمه‌ی جداگانه دارد)
        const transaction = {
            type: 'فروش', customerId: parseInt(customerId), customerName, date, billNumber, currency, saleType: type,
            items, subTotal, totalDiscount, totalAmount, cashAfn, cashUsd, cashForeign, cashForeignCurrency: (_isForeignSale ? currency : null), remaining, notes,
            // نگاشتِ نقدیِ چند-ارزی + نرخِ لحظهٔ ثبت (تا گزارش‌های گذشته با تغییرِ نرخ خراب نشوند)
            cashAmounts: _buildCashAmounts(currency, cashAfn, cashUsd, cashForeign),
            rateUsed: _dayRateFor(currency),
            baseCurrency: (typeof CurrencySystem !== 'undefined' && CurrencySystem.getBaseCode) ? CurrencySystem.getBaseCode() : 'AFN',
            profit: profit,
            cashboxId: cashboxId ? parseInt(cashboxId) : null,
            status: remaining > 0 ? 'باقی‌مانده' : 'تسویه‌شده',
            createdAt: new Date().toISOString()
        };

        const result = db.saveTransaction(transaction);
        if (result.success !== false) {
            // ثبت در لاگ معاملات حساب (بدون updateCashboxBalance مجدد — database.js این کار را کرده)
            if (typeof _logCashboxTransaction === 'function' && cashboxId && (cashAfn > 0 || cashUsd > 0 || cashForeign > 0)) {
                var paidAmount = _isForeignSale ? cashForeign : cashAfn;
                if (paidAmount > 0) {
                    _logCashboxTransaction(parseInt(cashboxId), {
                        type: 'sale',
                        amount: paidAmount,
                        currency: currency,
                        datetime: date,
                        notes: notes,
                        description: 'فروش — بل ' + billNumber + (customerName ? ' — ' + customerName : '')
                    });
                }
            }
            showMessage('موفقیت', 'فروش با موفقیت ثبت شد.'); addChangelog('ثبت', 'فروش', transaction, 'ثبت فروش جدید');
            if (typeof resetSalesForm === 'function') resetSalesForm();
            // اگر از دکمهٔ سریعِ داشبورد آمده، به داشبورد برگردد؛ وگرنه لیستِ فروش
            if (!_consumeFormReturn()) {
                if (typeof loadSalesList === 'function') loadSalesList();
                showSection('sales-list');
            }
        } else {
            showMessage('خطا', result.error || 'خطا در ثبت فروش');
        }
    }
    if (typeof refreshOpenReport === 'function') refreshOpenReport();
}

// ========================================================================
// «هزینه حمل و نقل» بل خرید: از مبلغِ خرید (و بدهیِ تأمین‌کننده) مستثناست و فقط مستقیماً از
// «موجودیِ حساب» کسر می‌شود و در «لاگِ تراکنش‌های حساب» با علتِ «هزینه حمل و نقل» نمایش
// داده می‌شود. هیچ «مصرف» ساخته نمی‌شود؛ بنابراین در هیچ محاسبه‌ای (از جمله مفاد و تب مصارفات)
// وارد نمی‌گردد. این تابع ابتدا اثرِ قبلیِ هزینه حمل‌ونقلِ همین بل را (چه نسخهٔ قدیمیِ «مصرف» و
// چه نسخهٔ لاگِ حساب) با برگشتِ اثرِ حساب پاک می‌کند، سپس در صورت وجود مبلغ، نسخهٔ جدید را ثبت
// می‌نماید. با shipping = 0 فقط حذف انجام می‌شود (هنگام حذف بل خرید).
// ========================================================================
function _syncPurchaseShippingExpense(purchaseId, shipping, currency, cashboxId, date, billNumber) {
    try {
        if (typeof db === 'undefined') return;
        if (purchaseId == null) return;

        // (الف) پاکسازیِ نسخهٔ قدیمیِ «مصرفِ حمل و نقل» (مهاجرت از روش قبلی) — با برگشتِ اثرِ حساب
        if (db.getExpenses) {
            var expenses = db.getExpenses() || [];
            var isExp = function (e) { return e && e.isShippingExpense && e.relatedPurchaseId != null && e.relatedPurchaseId == purchaseId; };
            var oldExp = expenses.filter(isExp);
            if (oldExp.length) {
                oldExp.forEach(function (e) { if (e.cashboxId) db.updateCashboxBalance(e.cashboxId, parseFloat(e.amount || 0), 'in', e.currency || _baseCur()); });
                localStorage.setItem('expenses', JSON.stringify(expenses.filter(function (e) { return !isExp(e); })));
            }
        }

        // (ب) پاکسازیِ نسخهٔ لاگِ حسابِ هزینه حمل و نقلِ همین بل — با برگشتِ اثرِ حساب
        var key = 'cashboxTransactions';
        var list = [];
        try { list = JSON.parse(localStorage.getItem(key) || '[]'); } catch (e) { list = []; }
        if (!Array.isArray(list)) list = [];
        var isLog = function (t) { return t && t.isShippingCharge && t.relatedPurchaseId != null && t.relatedPurchaseId == purchaseId; };
        var oldLog = list.filter(isLog);
        if (oldLog.length) {
            oldLog.forEach(function (t) { if (t.cashboxId != null) db.updateCashboxBalance(t.cashboxId, parseFloat(t.amount || 0), 'in', t.currency || _baseCur()); });
            list = list.filter(function (t) { return !isLog(t); });
            localStorage.setItem(key, JSON.stringify(list));
        }

        // (ج) ثبتِ هزینه حمل و نقلِ جدید: فقط کسر از حساب + لاگِ تراکنش حساب (بدون ساختِ مصرف)
        var ship = parseFloat(shipping) || 0;
        if (ship > 0 && cashboxId) {
            db.updateCashboxBalance(parseInt(cashboxId), ship, 'out', currency || _baseCur());
            if (typeof _logCashboxTransaction === 'function') {
                _logCashboxTransaction(parseInt(cashboxId), {
                    type: 'shipping_charge',
                    amount: ship,
                    currency: currency || _baseCur(),
                    datetime: date || '',
                    notes: '',
                    description: 'هزینه حمل و نقل' + (billNumber ? ' — بل ' + billNumber : ''),
                    isShippingCharge: true,
                    relatedPurchaseId: purchaseId
                });
            }
        }
    } catch (e) { console.error('syncPurchaseShipping:', e); }
}
if (typeof window !== 'undefined') window._syncPurchaseShippingExpense = _syncPurchaseShippingExpense;

// مهاجرتِ یک‌بارهٔ «مصرفِ حمل و نقل»های قدیمی (روشِ قبلی) به «لاگِ تراکنش حساب» (shipping_charge):
// رکورد از فهرستِ مصارف خارج می‌شود تا دیگر در مفاد و تب مصارفات وارد نباشد و فقط در لاگِ
// تراکنش‌های حساب با علتِ «هزینه حمل و نقل» دیده شود. موجودیِ حساب تغییر نمی‌کند چون مبلغ
// قبلاً به‌درستی کسر شده است. تابع idempotent است (در صورت نبودِ مصرفِ حمل، کاری نمی‌کند).
function _migrateShippingExpensesToCashboxLog() {
    try {
        if (typeof db === 'undefined' || !db.getExpenses) return;
        var expenses = db.getExpenses() || [];
        var ship = expenses.filter(function (e) { return e && e.isShippingExpense; });
        if (!ship.length) return;
        var key = 'cashboxTransactions';
        var list = [];
        try { list = JSON.parse(localStorage.getItem(key) || '[]'); } catch (e) { list = []; }
        if (!Array.isArray(list)) list = [];
        ship.forEach(function (e) {
            var exists = list.some(function (t) {
                return t && t.isShippingCharge && t.relatedPurchaseId != null && e.relatedPurchaseId != null && t.relatedPurchaseId == e.relatedPurchaseId;
            });
            if (exists) return;
            list.push({
                id: Date.now() + Math.floor(Math.random() * 100000),
                cashboxId: e.cashboxId,
                createdAt: e.createdAt || new Date().toISOString(),
                type: 'shipping_charge',
                amount: parseFloat(e.amount || 0),
                currency: e.currency || _baseCur(),
                datetime: e.date || '',
                notes: '',
                description: e.title || 'هزینه حمل و نقل',
                isShippingCharge: true,
                relatedPurchaseId: (e.relatedPurchaseId != null ? e.relatedPurchaseId : null)
            });
        });
        localStorage.setItem(key, JSON.stringify(list));
        // حذفِ مصارفِ حمل و نقل (بدون برگشتِ حساب — مبلغ قبلاً کسر شده است)
        localStorage.setItem('expenses', JSON.stringify(expenses.filter(function (e) { return !(e && e.isShippingExpense); })));
    } catch (e) { console.error('migrate shipping expenses:', e); }
}
if (typeof window !== 'undefined') window._migrateShippingExpensesToCashboxLog = _migrateShippingExpensesToCashboxLog;

// مهاجرتِ یک‌بارهٔ «قیمت خریدِ موجودیِ اولیه» (_batchInitialCostAFN/USD) برای تمام اجناسِ
// قبلی که این فیلد را ندارند، تا موتورِ مفادِ سری خرید (FIFO) برای همهٔ دیتای قبلیِ بازیابی‌شده
// نیز قیمتِ «سری اول» (موجودی اولیه) را داشته باشد. مقدار = قیمت خریدِ فعلیِ همان جنس. این تابع
// idempotent است: اگر فیلد از قبل موجود باشد دست نمی‌زند، پس بارها اجرا شدنش بی‌ضرر است و
// هر بار دیتای قدیمی بازیابی شود، در بارگذاریِ بعدی روی همان اعمال می‌گردد.
function _migrateBatchInitialCost() {
    try {
        var raw = (typeof localStorage !== 'undefined') ? localStorage.getItem('products') : null;
        if (!raw) return;
        var prods = JSON.parse(raw);
        if (!Array.isArray(prods) || !prods.length) return;
        // مجموعهٔ شناسهٔ اجناسی که «خرید» ثبت‌شده دارند. فقط برای این اجناس، «بهای موجودیِ اولیه»
        // باید منجمد بماند (چون خرید، purchasePrice را بازنویسی می‌کند و بهای سریِ اول نباید با آن
        // عوض شود). برای جنسی که هیچ خریدی ندارد، تنها ورودیِ آن «موجودی اولیه» است و بهای آن دقیقاً
        // برابرِ «قیمتِ خریدِ فعلیِ جنس» است؛ پس اسنپ‌شات باید با آن هم‌گام بماند. (خواندنِ خام؛ بدونِ
        // تغییرِ هیچ منطقِ دیگر — فقط تشخیصِ وجود/عدمِ خرید.)
        var _purchasedIds = {};
        try {
            var _txRawMB = (typeof localStorage !== 'undefined') ? localStorage.getItem('transactions') : null;
            var _txsMB = _txRawMB ? JSON.parse(_txRawMB) : [];
            if (Array.isArray(_txsMB)) {
                _txsMB.forEach(function (t) {
                    if (t && t.type === 'خرید' && Array.isArray(t.items)) {
                        t.items.forEach(function (it) { if (it && it.productId != null) _purchasedIds[it.productId] = true; });
                    }
                });
            }
        } catch (e) { _purchasedIds = {}; }

        var changed = false;
        prods.forEach(function (p) {
            if (!p) return;
            if (p._batchInitialCostAFN === undefined || p._batchInitialCostAFN === null) {
                p._batchInitialCostAFN = parseFloat(p.purchasePriceAFN) || 0;
                p._batchInitialCostUSD = parseFloat(p.purchasePriceUSD) || 0;
                changed = true;
            }
            // نگاشتِ پویای «بهای موجودیِ اولیه» برای هر ارز — تا موتورِ FIFO برای ارزهای
            // سوم به بعد هم سریِ اول را بابها ببیند (اصلاحِ هم‌راستا با migrateProductCurrencyModel).
            if (!p._batchInitialCosts || typeof p._batchInitialCosts !== 'object' || Array.isArray(p._batchInitialCosts)) {
                p._batchInitialCosts = {}; changed = true;
            }

            // آیا این جنس خریدِ ثبت‌شده دارد؟ اگر نه، «بهای موجودیِ اولیه» = «قیمتِ خریدِ فعلی» است.
            var _hasPurchaseMB = !!_purchasedIds[p.id];

            // نگاشتِ purchasePrices منبعِ اصلیِ حقیقت است و بر آینه‌های اسکالر مقدم؛
            // سپس آینه‌های AFN/USD فقط اگر نگاشت آن کلید را نداشت پر می‌شوند.
            if (p.purchasePrices && typeof p.purchasePrices === 'object') {
                Object.keys(p.purchasePrices).forEach(function (code) {
                    var v = parseFloat(p.purchasePrices[code]);
                    if (isNaN(v)) return;
                    var _cur = p._batchInitialCosts[code];
                    if (_cur === undefined || _cur === null) {
                        // کلیدِ غایب → همیشه پر می‌شود (رفتارِ قبلی، حفظ‌شده).
                        p._batchInitialCosts[code] = v; changed = true;
                    } else if (!_hasPurchaseMB && (parseFloat(_cur) || 0) !== v) {
                        // اصلاحِ ریشه‌ای (خودترمیم‌گر برای دیتای قدیمی/ویرایش‌شده): جنسِ بدونِ خرید،
                        // اگر اسنپ‌شاتش کهنه/صفر مانده و با قیمتِ خریدِ فعلی نمی‌خوانَد، هم‌راستا می‌شود.
                        // نتیجه: قیمتِ ردیفِ «موجودی اولیه» و محاسباتِ میانگینِ موزون/FIFO/سرمایه دقیقاً
                        // مطابقِ قیمتی می‌شود که کاربر روی فورم وارد/ویرایش کرده است. برای جنسِ دارای
                        // خرید هرگز اجرا نمی‌شود تا مقدارِ منجمد و صحتِ محاسبهٔ FIFO دست‌نخورده بماند.
                        p._batchInitialCosts[code] = v; changed = true;
                    }
                });
            }

            // آینه‌های اسکالرِ AFN/USD هم برای جنسِ بدونِ خرید با قیمتِ فعلی هم‌گام شوند (هماهنگ با بالا).
            if (!_hasPurchaseMB) {
                var _aNowMB = parseFloat(p.purchasePriceAFN) || 0;
                var _uNowMB = parseFloat(p.purchasePriceUSD) || 0;
                if ((parseFloat(p._batchInitialCostAFN) || 0) !== _aNowMB) { p._batchInitialCostAFN = _aNowMB; changed = true; }
                if ((parseFloat(p._batchInitialCostUSD) || 0) !== _uNowMB) { p._batchInitialCostUSD = _uNowMB; changed = true; }
            }

            if (p._batchInitialCosts.AFN === undefined && p._batchInitialCostAFN != null) { p._batchInitialCosts.AFN = parseFloat(p._batchInitialCostAFN) || 0; changed = true; }
            if (p._batchInitialCosts.USD === undefined && p._batchInitialCostUSD != null) { p._batchInitialCosts.USD = parseFloat(p._batchInitialCostUSD) || 0; changed = true; }
        });
        if (changed) localStorage.setItem('products', JSON.stringify(prods));
    } catch (e) { console.error('migrate batch initial cost:', e); }
}
if (typeof window !== 'undefined') window._migrateBatchInitialCost = _migrateBatchInitialCost;

// ========================================================================
// چارچوبِ عمومیِ «بازسازیِ داده» (General Data Rebuild) روی سیستم Migration
// ------------------------------------------------------------------------
// هدف: هر زمان منطقِ محاسباتیِ برنامه تغییر کرد، بتوان بدونِ وابستگی به مقادیرِ ذخیره‌شدهٔ
// قدیمی، آن بخش را فقط از روی «دادهٔ خام» با منطقِ فعلی از ابتدا دوباره ساخت. این چارچوب
// عمومی است و مخصوصِ یک فیلدِ خاص (مثل tx.profit) نیست؛ هر بخشِ محاسبه‌شده — مفاد، موجودی،
// خرید، فروش، حساب، هزینهٔ حمل، بدهکار/طلبکار، گزارش‌های مالی و ... — را می‌توان به‌صورت یک
// «Rebuilder» ثبت و از طریقِ یک Migrationِ نسخه‌دار اجرا کرد.
//
// ساختارِ هر Rebuilder:
//   {
//     name:        'شناسهٔ یکتا',
//     description: 'توضیح کوتاه',
//     canRebuild:  function () { return true/false; }
//                  // آیا دادهٔ خامِ کافی برای بازسازیِ این بخش وجود دارد؟ اگر نه → بدون تغییر رد شود.
//     rebuild:     function () { ...; return { changed, count }; }
//                  // فقط از دادهٔ خام بخوان، مقادیرِ محاسبه‌شدهٔ قدیمی را کنار بگذار، با منطقِ
//                  // فعلیِ برنامه از ابتدا محاسبه کن و نتیجه را بنویس.
//   }
//
// قواعدِ سخت:
//   • rebuild هرگز یک مقدارِ محاسبه‌شدهٔ قدیمی را مبنای کار قرار نمی‌دهد؛ تنها مبنا دادهٔ خام است
//     (اقلام، قیمت‌ها، تعدادها، تاریخ‌ها، تراکنش‌ها، انتقال‌ها و ...).
//   • اگر canRebuild نادرست بود (دادهٔ خامِ کافی نیست)، بازسازی اجرا نمی‌شود و آن بخش بدونِ تغییر
//     عبور می‌کند (skip)؛ Migration بدونِ خطا از آن می‌گذرد.
//   • هر Rebuilder از طریقِ یک Migration نسخه‌دار اجرا می‌شود، پس فقط یک‌بار اجرا می‌گردد و نسخه
//     ثبت می‌شود.
//
// افزودنِ بازسازیِ جدید در آینده (مثلاً «موجودی» یا «حساب» یا «بدهکار/طلبکار»):
//   ۱) با registerDataRebuilder({...}) یک Rebuilder با canRebuild و rebuild ثبت کنید که فقط از
//      دادهٔ خام کار کند.
//   ۲) یک Migration جدید با version بالاتر بسازید که در up() آن rebuildData('نامِ_جدید') را صدا بزند.
//   ۳) DB_CURRENT_SCHEMA_VERSION را زیاد کنید.
// ========================================================================
var DATA_REBUILDERS = {};

function registerDataRebuilder(rb) {
    try { if (rb && rb.name) DATA_REBUILDERS[rb.name] = rb; } catch (e) {}
}

// اجرای یک Rebuilder با رعایتِ گیتِ canRebuild. اگر دادهٔ خام کافی نباشد، بدونِ تغییر رد می‌شود.
function rebuildData(name) {
    var rb = DATA_REBUILDERS[name];
    if (!rb) { console.warn('Data Rebuild: Rebuilder یافت نشد → ' + name); return { ran: false, skipped: true, reason: 'not_found' }; }
    try {
        if (typeof rb.canRebuild === 'function' && !rb.canRebuild()) {
            console.log('Data Rebuild رد شد (دادهٔ خامِ ناکافی) → ' + name);
            return { ran: false, skipped: true, reason: 'insufficient_raw_data' };
        }
        var res = (typeof rb.rebuild === 'function') ? rb.rebuild() : { changed: false, count: 0 };
        console.log('Data Rebuild انجام شد → ' + name + ':', res);
        return { ran: true, skipped: false, result: res };
    } catch (e) {
        console.error('خطا در Data Rebuild → ' + name + ':', e);
        return { ran: false, skipped: true, reason: 'error' };
    }
}
if (typeof window !== 'undefined') { window.rebuildData = rebuildData; window.registerDataRebuilder = registerDataRebuilder; window.DATA_REBUILDERS = DATA_REBUILDERS; }

// ---- Rebuilderِ «مفادِ فروش» (نمونهٔ پیاده‌سازی‌شدهٔ این چارچوب) ----
// مفادِ هر فاکتورِ فروش (tx.profit) را فقط از روی اقلام/قیمت‌ها و سری‌های خرید با منطقِ فعلیِ
// FIFO از نو می‌سازد و مقدارِ ذخیره‌شدهٔ قدیمی را دور می‌اندازد. (منطقِ FIFO به «قیمت خریدِ
// موجودیِ اولیه» نیاز دارد که Rebuild/Migration نسخهٔ ۲ آن را آماده می‌کند.)
registerDataRebuilder({
    name: 'sale_profit',
    description: 'بازسازیِ مفادِ ذخیره‌شدهٔ هر فروش (tx.profit) از روی اقلام و سری‌های خرید با منطقِ FIFO',
    canRebuild: function () {
        try {
            if (typeof db === 'undefined' || typeof _getFifoMaps !== 'function') return false;
            var raw = (typeof localStorage !== 'undefined') ? localStorage.getItem('transactions') : null;
            if (!raw) return false;
            var txs = JSON.parse(raw);
            if (!Array.isArray(txs)) return false;
            // حداقل یک فروشِ دارای اقلام (دادهٔ خام) لازم است تا بازسازی معنا داشته باشد
            return txs.some(function (t) { return t && t.type === 'فروش' && Array.isArray(t.items) && t.items.length > 0; });
        } catch (e) { return false; }
    },
    rebuild: function () {
        var maps = _getFifoMaps();
        if (!maps || !maps.saleMap) return { changed: false, count: 0 };
        var txs = JSON.parse(localStorage.getItem('transactions'));
        if (!Array.isArray(txs)) return { changed: false, count: 0 };
        var changed = false, count = 0;
        txs.forEach(function (t) {
            if (!t || t.type !== 'فروش' || t.id == null) return;
            if (Object.prototype.hasOwnProperty.call(maps.saleMap, t.id)) {
                var np = maps.saleMap[t.id];
                if (t.profit !== np) { t.profit = np; changed = true; count++; }
            }
        });
        if (changed) localStorage.setItem('transactions', JSON.stringify(txs));
        return { changed: changed, count: count };
    }
});


// ════════════════════════════════════════════════════════════════════════
//  موتورِ واحدِ بازسازیِ داده‌های مشتق‌شده  (Unified Derived-Data Engine)
//  ──────────────────────────────────────────────────────────────────────
//  «منبعِ یگانهٔ حقیقت» (Single Source of Truth) برای تمام محاسباتِ بازسازی.
//
//  هدف معماری: هر «مقدارِ مشتق‌شده» (موجودیِ انبار، قیمتِ خریدِ واقعی، موجودیِ
//  حساب، مفادِ فروش، …) باید فقط از روی «دادهٔ خامِ منبع» (موجودیِ اولیهٔ جنس،
//  قیمت‌های پایه، تراکنش‌های خام، لاگ‌های خامِ حساب، مصارف) و فقط در «یک محل»
//  محاسبه شود. هر مسیرِ بارگذاریِ داده — اجرای برنامه (initApp)، واردکردنِ JSON
//  (db.importData)، بازیابیِ بکاپ (db.restoreBackup) و هر Migration — همگی همین
//  موتور را صدا می‌زنند. بنابراین وقتی منطقِ یک محاسبه را اینجا اصلاح کنید، تمامِ
//  داده‌های قدیمی نیز در نخستین بارگذاری خودکار با همان منطقِ جدید بازسازی می‌شوند
//  و دیگر نیازی به ثبتِ مجددِ دستی نیست.
//
//  قاعدهٔ طلایی: همان فرمول‌هایی که «مسیرِ نوشتن» (saveTransaction /
//  updateProductStock / _applyPurchasePriceFromItems / updateCashboxBalance)
//  استفاده می‌کند، اینجا نیز عیناً به‌کار می‌رود — هیچ محاسبه‌ای دوبار و با دو
//  فرمولِ متفاوت نوشته نمی‌شود. این بلوک همان قواعد را روی «کلِ دادهٔ خام» بازپخش
//  می‌کند (Replay) تا نتیجهٔ نهایی دقیقاً مثل آن باشد که گویی همهٔ رکوردها امروز و
//  با آخرین نسخهٔ برنامه ثبت شده‌اند.
//
//  افزودنِ یک محاسبهٔ جدید در آینده:
//    ۱) یک Rebuilder با registerDataRebuilder({ name, canRebuild, rebuild }) ثبت
//       کنید که فقط از دادهٔ خام بخواند و idempotent باشد.
//    ۲) نامش را به آرایهٔ REBUILD_PIPELINE (به‌ترتیبِ وابستگی) اضافه کنید.
//    ۳) تمام؛ روی هر بارگذاری/وارد/بازیابی خودکار اجرا می‌شود.
// ════════════════════════════════════════════════════════════════════════

// ——— ابزارهای مشترکِ خام (Shared Raw Helpers) — تنها تعریفِ این قواعد ———

// مقدارِ معادلِ «واحد اصلی» برای موجودی (آیتم‌های واحد فرعی × ضریب تبدیل تبدیل می‌شوند).
// عیناً همان _qtyForStock در saveTransaction و recalculateAllProductsStock.
function _engQtyForStock(it) {
    var q = parseFloat(it && it.quantity) || 0;
    if (it && it.unitType === 'secondary') {
        var f = parseFloat(it.secondaryFactor) || 0;
        if (f > 0) return q / f;
    }
    return q;
}

// خواندنِ آرایهٔ خام از localStorage با هندلِ امن.
function _engRaw(key) {
    try { var v = JSON.parse(localStorage.getItem(key) || '[]'); return Array.isArray(v) ? v : []; }
    catch (e) { return []; }
}

// طبقه‌بندیِ نوعِ اثر بر حساب (ورودی/خروجی) — عیناً همان قواعدِ نمایشِ حساب و مسیرِ نوشتن.
function _engCashboxIsIncome(t) {
    return (t === 'فروش' || t === 'دریافت' || t === 'اضافه به صندوق' || t === 'ورود مبلغ خارجی' ||
            t === 'انتقال ورودی' || t === 'deposit_in' || t === 'deposit_external' || t === 'transfer_in');
}
function _engCashboxIsExpense(t) {
    return (t === 'خرید' || t === 'پرداخت' || t === 'مصرف' || t === 'برداشت از حساب' ||
            t === 'برداشت مبلغ از حساب' || t === 'انتقال خروجی' || t === 'deposit_out' ||
            t === 'withdraw_external' || t === 'transfer_out' || t === 'shipping_charge');
}

// مبلغِ نقدیِ یک تراکنش برای هر ارز — عیناً منطقِ پویای _cashPaidFor در saveTransaction.
//  اصلاحِ ج-۴: پیش‌تر فقط cashAfn/cashUsd خوانده می‌شد و نگاشتِ پویای cashAmounts/paidAmounts
//  نادیده گرفته می‌شد، ضمناً ارزِ اثر برنگردانده می‌شد؛ پس بازسازی موجودیِ ارزهای سوم را
//  از دست می‌داد و همه را در یک اسکالر قاطی می‌کرد.
function _engCashPaidFor(t, kind) {
    var _base = (typeof CurrencySystem !== 'undefined' && CurrencySystem.getBaseCode) ? CurrencySystem.getBaseCode() : 'AFN';
    var cur = t.currency || _base;
    var mapKey = (kind === 'paid') ? 'paidAmounts' : 'cashAmounts';
    if (t[mapKey] && typeof t[mapKey] === 'object' && t[mapKey][cur] != null) {
        return parseFloat(t[mapKey][cur]) || 0;
    }
    if (kind === 'paid') {
        if (cur === 'USD') return parseFloat(t.paidUsd) || parseFloat(t.cashUsd) || 0;
        if (cur === 'AFN') return parseFloat(t.paidAfn) || parseFloat(t.cashAfn) || 0;
        return parseFloat(t.paidForeign) || 0;
    } else {
        if (cur === 'USD') return parseFloat(t.cashUsd) || 0;
        if (cur === 'AFN') return parseFloat(t.cashAfn) || 0;
        return parseFloat(t.cashForeign) || 0;
    }
}

// اثرِ یک تراکنش بر حساب، به تفکیکِ ارز. خروجی: آرایه‌ای از { amount, dir, cur } — چون
//  «صرافی» هم‌زمان دو ارز را جابه‌جا می‌کند (خروجِ یک ارز، ورودِ ارزِ دیگر).
//  عیناً همان قواعدِ مسیرِ نوشتن (saveTransaction._cashboxEffect + شاخهٔ صرافی).
function _engTxCashboxEffects(t) {
    if (!t) return [];
    var _base = (typeof CurrencySystem !== 'undefined' && CurrencySystem.getBaseCode) ? CurrencySystem.getBaseCode() : 'AFN';
    var cur = t.currency || _base;
    if (t.type === 'صرافی') {
        var fromCur = t.fromCurrency || cur;
        var toCur   = t.toCurrency   || cur;
        var fromAmt = parseFloat(t.fromAmount || 0) || 0;
        var toAmt   = parseFloat(t.toAmount   || 0) || 0;
        var out = [];
        if (fromAmt > 0) out.push({ amount: fromAmt, dir: 'out', cur: fromCur });
        if (toAmt   > 0) out.push({ amount: toAmt,   dir: 'in',  cur: toCur });
        return out;
    }
    var amt = 0, dir = null;
    if (t.type === 'فروش') { amt = _engCashPaidFor(t, 'cash'); dir = 'in'; }
    else if (t.type === 'خرید') { amt = _engCashPaidFor(t, 'paid'); dir = 'out'; }
    else if (t.type === 'دریافت') { amt = parseFloat(t.amount) || 0; dir = 'in'; }
    else if (t.type === 'پرداخت') { amt = parseFloat(t.amount) || 0; dir = 'out'; }
    else if (t.type === 'برگشت') {
        amt = parseFloat(t.totalAmount || t.amount) || 0;
        if (t.returnType === 'فروش') dir = 'out';
        else if (t.returnType === 'خرید') dir = 'in';
    }
    if (!dir || !(amt > 0)) return [];
    return [{ amount: amt, dir: dir, cur: cur }];
}

// سازگارِ عقب‌رو: امضای قدیمیِ تک‌مقداری هنوز کار می‌کند (برای هر فراخوانِ احتمالیِ دیگر).
//  فقط اثرِ ارزِ خودِ سند را برمی‌گرداند.
function _engTxCashboxEffect(t) {
    var _base = (typeof CurrencySystem !== 'undefined' && CurrencySystem.getBaseCode) ? CurrencySystem.getBaseCode() : 'AFN';
    var cur = (t && t.currency) || _base;
    var effs = _engTxCashboxEffects(t);
    for (var i = 0; i < effs.length; i++) { if (effs[i].cur === cur) return { amount: effs[i].amount, dir: effs[i].dir }; }
    return effs.length ? { amount: effs[0].amount, dir: effs[0].dir } : { amount: 0, dir: null };
}

// ════════════════════════════════════════════════════════════════════════
//  Rebuilder ۱ — موجودیِ انبار (Stock)
//  بازسازیِ stock هر جنس = موجودیِ اولیه + Σ(خرید) − Σ(فروش) + Σ(برگشت از فروش) − Σ(برگشت از خرید)
//  + انتقال‌های میان گدام. برگشت‌ها با تأییدِ صریحِ کاربر روی موجودیِ فیزیکی اعمال می‌شوند
//  (هم‌جهت با موتورِ FIFO/ارزشِ انبار و طبقه‌بندیِ ورودی/خروجی). idempotent.
// ════════════════════════════════════════════════════════════════════════
registerDataRebuilder({
    name: 'stock',
    description: 'بازسازیِ موجودیِ انبار هر جنس از موجودیِ اولیه و تراکنش‌های خرید/فروشِ خام',
    canRebuild: function () {
        // برای بازسازیِ موجودی فقط به وجودِ اجناس نیاز داریم (حتی بدون تراکنش، stock = initialStock صحیح است)
        return _engRaw('products').length > 0;
    },
    rebuild: function () {
        var products = _engRaw('products');
        var transactions = _engRaw('transactions');
        var changed = false, count = 0;

        // گام ۱) بازنشانی به موجودیِ اولیه
        products.forEach(function (p) {
            if (!p) return;
            var init = parseFloat(p.initialStock) || 0;
            if (p.stock !== init) { changed = true; }
            p.stock = init;
        });

        // گام ۲) اعمالِ اثرِ خرید (+) و فروش (−) — تبدیلِ واحد فرعی به اصلی
        transactions.forEach(function (tx) {
            if (!tx || !Array.isArray(tx.items)) return;
            if (tx.type !== 'فروش' && tx.type !== 'خرید') return;
            tx.items.forEach(function (it) {
                var idx = products.findIndex(function (p) { return p.id == it.productId; });
                if (idx === -1) return;
                var qty = _engQtyForStock(it);
                if (tx.type === 'فروش') products[idx].stock -= qty;
                else products[idx].stock += qty;
            });
        });

        // گام ۲-ب) اعمالِ اثرِ «برگشت» روی موجودیِ فیزیکی (با تأییدِ صریحِ کاربر):
        //   برگشت از فروش → کالا به انبار بازمی‌گردد (+) ؛ برگشت از خرید → کالا از انبار خارج می‌شود (−).
        //   دقیقاً هم‌جهت با طبقه‌بندیِ موجود (خط ~۳۸۵۲–۳۸۵۵) و موتورِ FIFO/ارزشِ انبار. idempotent.
        transactions.forEach(function (tx) {
            if (!tx || tx.type !== 'برگشت' || !Array.isArray(tx.items)) return;
            var _retIn = (tx.returnType === 'فروش');   // فروش→ورود(+) ، خرید→خروج(−)
            tx.items.forEach(function (it) {
                if (!it || it.isService || it.productId == null) return;
                var idx = products.findIndex(function (p) { return p.id == it.productId; });
                if (idx === -1) return;
                var qty = _engQtyForStock(it);
                if (!qty) return;
                products[idx].stock = (parseFloat(products[idx].stock) || 0) + (_retIn ? qty : -qty);
                changed = true;
            });
        });

        // گام ۳) اعمالِ انتقال‌های میان گدام‌ها: خروج از مبدأ (−) و ورود به مقصد (+)
        // بدونِ این گام، Rebuilder موجودی را فقط از خرید/فروش می‌سازد و انتقال‌ها پس از
        // بارگذاری برمی‌گردند (مبدأ به مقدارِ قبل، مقصد صفر). با اعمالِ انتقال‌ها، نتیجه
        // روی دادهٔ موجودِ کاربران هم دقیق و پایدار می‌ماند.
        try {
            var _transfers = [];
            try { _transfers = (typeof db !== 'undefined' && db.getTransfers) ? db.getTransfers() : (JSON.parse(localStorage.getItem('warehouseTransfers')) || []); }
            catch (e) { _transfers = []; }
            _transfers.forEach(function (tr) {
                if (!tr || !Array.isArray(tr.items)) return;
                tr.items.forEach(function (it) {
                    var q = parseFloat(it.quantity) || 0;
                    if (!q) return;
                    if (it.srcProductId != null) {
                        var _si = products.findIndex(function (p) { return p.id == it.srcProductId; });
                        if (_si !== -1) { products[_si].stock = (parseFloat(products[_si].stock) || 0) - q; changed = true; }
                    }
                    if (it.destProductId != null) {
                        var _di = products.findIndex(function (p) { return p.id == it.destProductId; });
                        if (_di !== -1) { products[_di].stock = (parseFloat(products[_di].stock) || 0) + q; changed = true; }
                    }
                });
            });
        } catch (e) {}

        count = products.length;
        // همیشه می‌نویسیم تا نتیجهٔ بازپخش قطعی و هماهنگ باشد (idempotent)
        localStorage.setItem('products', JSON.stringify(products));
        return { changed: changed, count: count };
    }
});

// ════════════════════════════════════════════════════════════════════════
//  Rebuilder ۲ — قیمتِ خریدِ واقعیِ جنس (Purchase Price)
//  بازپخشِ تراکنش‌های «خرید» به‌ترتیبِ زمانی و اعمالِ همان منطقِ
//  _applyPurchasePriceFromItems (آخرین خریدِ معتبر برنده است؛ تبدیلِ واحد فرعی به
//  اصلی؛ تفکیکِ ارز؛ حفظِ «قیمتِ خریدِ موجودیِ اولیه» در _batchInitialCost). این کار
//  purchasePriceAFN/USD هر جنس را دقیقاً مطابقِ آخرین وضعیتِ خریدها بازسازی می‌کند.
// ════════════════════════════════════════════════════════════════════════
registerDataRebuilder({
    name: 'purchase_price',
    description: 'بازسازیِ قیمتِ خریدِ واقعیِ هر جنس از روی تراکنش‌های خریدِ خام (آخرین خریدِ معتبر)',
    canRebuild: function () {
        if (_engRaw('products').length === 0) return false;
        // حداقل یک خریدِ دارای اقلام لازم است تا بازسازی معنا داشته باشد
        return _engRaw('transactions').some(function (t) {
            return t && t.type === 'خرید' && Array.isArray(t.items) && t.items.length > 0;
        });
    },
    rebuild: function () {
        var products = _engRaw('products');
        var transactions = _engRaw('transactions');

        // پیش‌نیاز: «قیمتِ خریدِ موجودیِ اولیه» باید پیش از نخستین بازنویسی توسط خرید نگه داشته شود
        // (دقیقاً مثل _applyPurchasePriceFromItems). اگر ثبت نشده، از قیمتِ فعلیِ همان جنس مقداردهی می‌شود.
        var _base = (typeof CurrencySystem !== 'undefined' && CurrencySystem.getBaseCode) ? CurrencySystem.getBaseCode() : 'AFN';
        products.forEach(function (p) {
            if (!p) return;
            if (p._batchInitialCostAFN === undefined || p._batchInitialCostAFN === null) {
                p._batchInitialCostAFN = parseFloat(p.purchasePriceAFN) || 0;
                p._batchInitialCostUSD = parseFloat(p.purchasePriceUSD) || 0;
            }
            // نگاشتِ قیمتِ خرید باید موجود باشد تا ارزهای سوم هم بازسازی شوند.
            if (!p.purchasePrices || typeof p.purchasePrices !== 'object' || Array.isArray(p.purchasePrices)) {
                p.purchasePrices = {};
                if (p.purchasePriceAFN != null) p.purchasePrices.AFN = parseFloat(p.purchasePriceAFN) || 0;
                if (p.purchasePriceUSD != null) p.purchasePrices.USD = parseFloat(p.purchasePriceUSD) || 0;
            }
        });

        // بازپخشِ خریدها به‌ترتیبِ زمانی (createdAt، سپس id) — تا «آخرین خرید» واقعاً آخرین باشد
        var purchases = transactions.filter(function (t) {
            return t && t.type === 'خرید' && Array.isArray(t.items) && t.items.length > 0;
        }).slice().sort(function (a, b) {
            var ca = a.createdAt || '', cb = b.createdAt || '';
            if (ca !== cb) return ca < cb ? -1 : 1;
            return (a.id || 0) - (b.id || 0);
        });

        var changed = false, count = 0;
        purchases.forEach(function (tx) {
            var cur = tx.currency || _base;
            tx.items.forEach(function (it) {
                if (!it || it.productId == null) return;
                var price = parseFloat(it.price) || 0;
                if (price <= 0) return; // فقط خریدِ دارای قیمتِ معتبر اعمال می‌شود (آخرین معتبر)
                var unitPrice = price;
                if (it.unitType === 'secondary') {
                    var f = parseFloat(it.secondaryFactor) || 0;
                    if (f > 0) unitPrice = price * f;
                }
                var idx = products.findIndex(function (p) { return p.id == it.productId; });
                if (idx === -1) return;
                var P = products[idx];
                if (!P.purchasePrices || typeof P.purchasePrices !== 'object') P.purchasePrices = {};
                // اصلاحِ ج-۴: قیمت در «همان ارزِ خرید» ثبت می‌شود — خریدِ یورو دیگر در
                // purchasePriceAFN نمی‌نشیند. نگاشتِ پویا منبعِ حقیقت است؛ آینه‌های
                // AFN/USD فقط برای سازگاریِ کدِ قدیمی به‌روز می‌شوند.
                if (P.purchasePrices[cur] !== unitPrice) { P.purchasePrices[cur] = unitPrice; changed = true; count++; }
                if (cur === 'AFN') P.purchasePriceAFN = unitPrice;
                else if (cur === 'USD') P.purchasePriceUSD = unitPrice;
            });
        });

        localStorage.setItem('products', JSON.stringify(products));
        return { changed: changed, count: count };
    }
});

// ════════════════════════════════════════════════════════════════════════
//  Rebuilder ۳ — موجودیِ حساب (Cashbox Balance)
//  بازسازیِ balance هر حساب = Σ(اثرِ ورودی) − Σ(اثرِ خروجی) روی «کلِ دادهٔ خام»:
//  تراکنش‌ها (مبلغِ نقدیِ واقعی)، مصارف، و لاگ‌های خامِ حساب (موجودیِ اولیه/واریز/
//  برداشت/انتقال/حملِ بار). همان قواعدِ updateCashboxBalance در مسیرِ نوشتن.
//
//  گیتِ ایمنی (canRebuild): لاگ‌های حساب (cashboxTransactions) همیشه در همهٔ بکاپ‌ها
//  نبوده‌اند؛ اگر این لاگ‌ها در دسترس نباشند، خودِ فیلدِ balance (که در زمانِ صادرات
//  محاسبه و ذخیره شده) معتبر است و نباید با بازپخشِ ناقص خراب شود. پس بازسازی فقط
//  وقتی اجرا می‌شود که «ردِ موجودیِ اولیهٔ حساب» در لاگ‌ها موجود باشد یا اصلاً
//  حسابی با موجودیِ اولیه وجود نداشته باشد — در غیرِ این صورت balance دست‌نخورده می‌ماند.
// ════════════════════════════════════════════════════════════════════════
registerDataRebuilder({
    name: 'cashbox_balance',
    description: 'بازسازیِ موجودیِ هر حساب از تراکنش‌ها، مصارف و لاگ‌های خامِ حساب (ایمنِ هر حساب)',
    canRebuild: function () {
        // فقط به وجودِ حساب نیاز داریم؛ ایمنیِ داده‌های ناقص در سطحِ «هر حساب» داخلِ rebuild
        // اعمال می‌شود (حسابی که هیچ اثرِ خامی ندارد، موجودیِ ذخیره‌شده‌اش دست‌نخورده می‌ماند).
        return _engRaw('cashboxes').length > 0;
    },
    rebuild: function () {
        var boxes = _engRaw('cashboxes');
        var transactions = _engRaw('transactions');
        var expenses = _engRaw('expenses');
        var logs = _engRaw('cashboxTransactions');

        var _base = (typeof CurrencySystem !== 'undefined' && CurrencySystem.getBaseCode) ? CurrencySystem.getBaseCode() : 'AFN';
        var _money = function (v, code) {
            if (typeof CurrencySystem !== 'undefined' && CurrencySystem.round) return CurrencySystem.round(v, (CurrencySystem.getDecimals ? CurrencySystem.getDecimals(code) : 2));
            var n = parseFloat(v) || 0, sg = n < 0 ? -1 : 1, a = Math.abs(n) * 100; return sg * Math.round(a + Number.EPSILON) / 100;
        };
        // اصلاحِ ج-۴: بازسازی به تفکیکِ ارز (نگاشتِ balances)، نه یک اسکالرِ درهم.
        //   bal[id] = { [کد ارز]: مبلغ } ؛ balNative[id] = مجموعِ ارزِ بومیِ حساب (برای آینهٔ balance)
        var bal = {};        // id → { cur: amount }
        var hasRaw = {};     // id → آیا این حساب حتی یک اثرِ خام دارد؟
        boxes.forEach(function (c) { if (c && c.id != null) { bal[c.id] = {}; hasRaw[c.id] = false; } });
        var _add = function (id, cur, amt) {
            if (!bal[id]) bal[id] = {};
            bal[id][cur] = (bal[id][cur] || 0) + amt;
            hasRaw[id] = true;
        };

        // (الف) اثرِ تراکنش‌ها — به تفکیکِ ارز (شاملِ صرافیِ دو-ارزی)
        transactions.forEach(function (t) {
            if (!t || t.cashboxId == null || !(t.cashboxId in bal)) return;
            var effs = _engTxCashboxEffects(t);
            effs.forEach(function (eff) {
                if (!eff.dir || !(eff.amount > 0)) return;
                _add(t.cashboxId, eff.cur || _base, eff.dir === 'in' ? eff.amount : -eff.amount);
            });
        });

        // (ب) اثرِ مصارف — همیشه خروجی، به ارزِ خودِ مصرف
        expenses.forEach(function (e) {
            if (!e || e.cashboxId == null || !(e.cashboxId in bal)) return;
            var amt = parseFloat(e.amount) || 0;
            if (!(amt > 0)) return;
            _add(e.cashboxId, e.currency || _base, -amt);
        });

        // (ج) اثرِ لاگ‌های خامِ حساب — واریز/برداشت/انتقال/موجودیِ اولیه/حملِ بار.
        //  ارزِ هر لاگ: g.currency، سپس ارزِ بومیِ حساب به‌عنوان پیش‌فرض.
        var _boxCur = {};
        boxes.forEach(function (c) { if (c && c.id != null) _boxCur[c.id] = c.currency || _base; });
        logs.forEach(function (g) {
            if (!g || g.cashboxId == null || !(g.cashboxId in bal)) return;
            var amt = parseFloat(g.amount) || 0;
            if (!(amt > 0)) return;
            var lc = g.currency || _boxCur[g.cashboxId] || _base;
            if (_engCashboxIsIncome(g.type)) _add(g.cashboxId, lc, amt);
            else if (_engCashboxIsExpense(g.type)) _add(g.cashboxId, lc, -amt);
        });

        var changed = false, count = 0, preserved = 0;
        boxes.forEach(function (c) {
            if (!c || c.id == null) return;
            var native = c.currency || _base;
            // ایمنیِ هر حساب: حسابی که هیچ اثرِ خامی ندارد ولی موجودیِ ذخیره‌شده دارد،
            // دست‌نخورده می‌ماند تا موجودیِ درستش صفر/خراب نشود (نگاشت و اسکالر هر دو).
            var storedNative = parseFloat(c.balance) || 0;
            var hadStoredMap = (c.balances && typeof c.balances === 'object' && !Array.isArray(c.balances) && Object.keys(c.balances).length > 0);
            if (!hasRaw[c.id] && (storedNative !== 0 || hadStoredMap)) { preserved++; return; }

            // نگاشتِ بازسازی‌شده (گرد‌شده به ازای هر ارز)
            var m = bal[c.id] || {};
            var newMap = {};
            Object.keys(m).forEach(function (code) {
                var v = _money(m[code], code);
                if (v !== 0) newMap[code] = v;   // صفرها حذف می‌شوند تا نگاشت تمیز بماند
            });
            // اسکالرِ آینه = موجودیِ ارزِ بومیِ حساب (سازگاریِ کدِ قدیمی که c.balance می‌خواند)
            var nativeBal = _money(m[native] || 0, native);

            var beforeMap = JSON.stringify(c.balances || {});
            c.balances = newMap;
            if (JSON.stringify(newMap) !== beforeMap) { changed = true; count++; }
            if ((parseFloat(c.balance) || 0) !== nativeBal) { c.balance = nativeBal; changed = true; }
            else c.balance = nativeBal;
        });
        localStorage.setItem('cashboxes', JSON.stringify(boxes));
        return { changed: changed, count: count, preserved: preserved };
    }
});

// ════════════════════════════════════════════════════════════════════════
//  Rebuilder ۴ — پاک‌سازیِ «حساب قبلیِ» شخص (Person Previous-Account Cleanup)
//  ──────────────────────────────────────────────────────────────────────
//  ریشهٔ مشکلِ داده‌های قدیمی: در نسخهٔ قبلیِ برنامه، هنگام ویرایشِ «حساب قبلی» شخص،
//  علاوه بر به‌روزرسانیِ person.previousAccount یک «تراکنشِ جداگانه» با نوعِ
//  'پرداخت از حساب قبلی' هم ثبت می‌شد. در منطقِ جدید، خودِ previousAccount تنها
//  منبعِ حقیقتِ «موجودیِ اولیهٔ حساب» است و همیشه به‌عنوان ردیفِ اولِ مانده لحاظ
//  می‌شود؛ پس آن تراکنش‌های اضافی باعثِ «دوبار حساب‌شدنِ» اختلاف و اشتباهیِ مانده
//  می‌شوند (مثلاً بدهکار ۱۰۰۰۰→۸۰۰۰ روی کارت ۶۰۰۰ نشان می‌داد).
//
//  نکتهٔ ایمنیِ قطعی: نسخهٔ فعلیِ برنامه «هرگز» تراکنشی با نوعِ 'پرداخت از حساب قبلی'
//  نمی‌سازد (سازندهٔ آن حذف شده است). بنابراین وجودِ هر تراکنشِ این‌نوع در دیتابیس
//  قطعاً «دادهٔ قدیمیِ یتیم» است و حذفِ آن، مانده را دقیقاً با منطقِ جدید هماهنگ
//  می‌کند (چون previousAccount در هر ذخیره به مقدارِ نهایی UPDATE می‌شود و ردیفِ
//  اولِ مانده را می‌سازد). این Rebuilder idempotent است: پس از نخستین پاک‌سازی،
//  دفعاتِ بعدی چیزی برای حذف نمی‌یابند.
// ════════════════════════════════════════════════════════════════════════
registerDataRebuilder({
    name: 'person_previous_account_cleanup',
    description: 'حذفِ تراکنش‌های قدیمیِ «پرداخت از حساب قبلی» که در منطقِ جدید با previousAccount دوبار حساب می‌شدند',
    canRebuild: function () {
        var txs = _engRaw('transactions');
        // فقط وقتی اجرا می‌شود که حداقل یک تراکنشِ یتیمِ این‌نوع وجود داشته باشد
        return txs.some(function (t) { return t && t.type === 'پرداخت از حساب قبلی'; });
    },
    rebuild: function () {
        var txs = _engRaw('transactions');
        var before = txs.length;
        var kept = txs.filter(function (t) { return !(t && t.type === 'پرداخت از حساب قبلی'); });
        var removed = before - kept.length;
        if (removed > 0) localStorage.setItem('transactions', JSON.stringify(kept));
        return { changed: removed > 0, count: removed };
    }
});

// ════════════════════════════════════════════════════════════════════════
//  ارکستریتورِ بازسازیِ کامل  (Single Entry Point)
//  ترتیبِ وابستگی مهم است:
//    person_previous_account_cleanup → batch_initial_cost → stock → purchase_price
//      → cashbox_balance → sale_profit
//  (ابتدا تراکنش‌های یتیمِ «حساب قبلی» پاک می‌شوند تا مانده‌ها با منطقِ جدید هماهنگ
//   شوند؛ سپس مفادِ FIFO که به قیمتِ خرید و موجودیِ اولیه وابسته است، آخر اجرا می‌گردد.)
//  این تابع روی «هر» بارگذاری/وارد/بازیابی صدا زده می‌شود و ungated است؛ هر Rebuilder
//  خودش با canRebuild تصمیم می‌گیرد که آیا دادهٔ خامِ کافی دارد یا نه.
// ════════════════════════════════════════════════════════════════════════
var REBUILD_PIPELINE = ['person_previous_account_cleanup', 'stock', 'purchase_price', 'cashbox_balance', 'sale_profit'];

function rebuildAllDerivedData() {
    var summary = {};
    try {
        // پیش‌نیازِ ساختاری: «قیمتِ خریدِ موجودیِ اولیه» برای FIFO (idempotent)
        try { if (typeof _migrateBatchInitialCost === 'function') _migrateBatchInitialCost(); } catch (e) {}

        REBUILD_PIPELINE.forEach(function (name) {
            try { summary[name] = rebuildData(name); }
            catch (e) { summary[name] = { ran: false, error: String(e) }; console.error('rebuildAllDerivedData → ' + name, e); }
        });

        // پاک‌سازیِ کشِ FIFO تا محاسباتِ بعدی از دادهٔ تازه بخوانند
        try { if (typeof _fifoProfitCache !== 'undefined') { _fifoProfitCache.sig = null; _fifoProfitCache.maps = null; } } catch (e) {}

        // به‌روزرسانیِ شمارندهٔ کمبودِ موجودی پس از بازسازیِ stock
        try { if (typeof db !== 'undefined' && db.updateLowStockCount) db.updateLowStockCount(); } catch (e) {}

        console.log('Unified Rebuild کامل شد:', summary);
    } catch (e) {
        console.error('rebuildAllDerivedData error:', e);
    }
    return summary;
}
if (typeof window !== 'undefined') {
    window.rebuildAllDerivedData = rebuildAllDerivedData;
    window.REBUILD_PIPELINE = REBUILD_PIPELINE;
}

// ========================================================================
// سیستم «مهاجرتِ نسخه‌بندی‌شدهٔ دیتابیس» (Versioned Database Migration)
// ------------------------------------------------------------------------
// هر بار برنامه اجرا می‌شود (initApp) یا یک بکاپ بازیابی/وارد می‌گردد (db.restoreBackup /
// db.importData)، نسخهٔ شِمای دیتابیس بررسی شده و تمام Migrationهای لازم به‌ترتیبِ نسخه اجرا
// می‌شوند تا داده‌های قدیمی با جدیدترین فیلدها/ساختار/منطق و محاسبات سازگار شوند.
// نسخهٔ فعلی در localStorage['db_schema_version'] نگه‌داری می‌شود و در بکاپ‌ها هم ذخیره می‌گردد
// (بکاپ‌های قدیمی این فیلد را ندارند → از نسخهٔ 0 شروع و همهٔ Migrationها اجرا می‌شوند).
//
// افزودنِ یک تغییرِ ساختاریِ جدید در آینده:
//   ۱) یک تابعِ idempotent برای آن تغییر بنویسید.
//   ۲) عضوی جدید با version بالاتر به DB_MIGRATIONS اضافه کنید که در up() آن تابع را صدا بزند.
//   ۳) DB_CURRENT_SCHEMA_VERSION را برابرِ بزرگ‌ترین version کنید.
// تمام up()ها باید idempotent باشند (اجرای چندباره نباید داده را خراب کند).
// ========================================================================
var DB_SCHEMA_VERSION_KEY = 'db_schema_version';
var DB_CURRENT_SCHEMA_VERSION = 3;

var DB_MIGRATIONS = [
    { version: 1, name: 'shipping_expense_to_cashbox_log', up: function () { _migrateShippingExpensesToCashboxLog(); } },
    { version: 2, name: 'product_batch_initial_cost',       up: function () { _migrateBatchInitialCost(); } },
    { version: 3, name: 'rebuild_sale_profit',             up: function () { rebuildData('sale_profit'); } }
];

function getDbSchemaVersion() {
    try {
        var v = parseInt(localStorage.getItem(DB_SCHEMA_VERSION_KEY), 10);
        return isNaN(v) ? 0 : v;
    } catch (e) { return 0; }
}

function setDbSchemaVersion(v) {
    try { localStorage.setItem(DB_SCHEMA_VERSION_KEY, String(parseInt(v, 10) || 0)); } catch (e) {}
}

// اجرای همهٔ Migrationهای معلق تا رسیدن به آخرین نسخه. idempotent و version-gated است.
function runDatabaseMigrations() {
    try {
        var current = getDbSchemaVersion();

        // ── بخشِ ۱) مهاجرت‌های ساختاری (Schema Migrations) — فقط یک‌بار و version-gated ──
        // این‌ها تغییرِ «ساختار/شکلِ داده» هستند (نه محاسبه) و نباید هر بار تکرار شوند.
        if (current < DB_CURRENT_SCHEMA_VERSION) {
            var pending = DB_MIGRATIONS.slice().sort(function (a, b) { return a.version - b.version; });
            pending.forEach(function (m) {
                if (m && m.version > current && m.version <= DB_CURRENT_SCHEMA_VERSION && typeof m.up === 'function') {
                    try { m.up(); console.log('Migration اجرا شد → v' + m.version + ' (' + (m.name || '') + ')'); }
                    catch (e) { console.error('خطا در Migration v' + m.version + ':', e); }
                }
            });
            setDbSchemaVersion(DB_CURRENT_SCHEMA_VERSION);
        }

        // ── بخشِ ۲) بازسازیِ کاملِ داده‌های مشتق‌شده — «همیشه» و ungated ──
        // هستهٔ معماریِ خواسته‌شده: صرف‌نظر از نسخهٔ شِما، در «هر» بارگذاری/وارد/بازیابی تمامِ
        // مقادیرِ مشتق‌شده (موجودی، قیمتِ خرید، حساب، مفاد) از روی دادهٔ خام با آخرین منطق
        // دوباره ساخته می‌شوند. بنابراین وقتی منطقِ یک محاسبه را اصلاح می‌کنید، داده‌های قدیمی
        // در نخستین بارگذاری خودکار با همان منطقِ جدید هماهنگ می‌شوند — بدونِ ثبتِ مجددِ دستی.
        // (هر Rebuilder خودش با canRebuild از دادهٔ خامِ ناکافی محافظت می‌کند و idempotent است.)
        try {
            if (typeof rebuildAllDerivedData === 'function') rebuildAllDerivedData();
        } catch (e) { console.error('unified rebuild in migrations:', e); }

        return DB_CURRENT_SCHEMA_VERSION;
    } catch (e) { console.error('runDatabaseMigrations:', e); return getDbSchemaVersion(); }
}
if (typeof window !== 'undefined') {
    window.runDatabaseMigrations = runDatabaseMigrations;
    window.getDbSchemaVersion = getDbSchemaVersion;
    window.setDbSchemaVersion = setDbSchemaVersion;
    window.DB_CURRENT_SCHEMA_VERSION = DB_CURRENT_SCHEMA_VERSION;
}

function savePurchase() {
    const supplierId = document.getElementById('qp-supplier').value;
    const supplierInput = document.getElementById('qp-supplier-search');
    const supplierName = (supplierInput && supplierInput.value) ? supplierInput.value : 'فروشنده نامشخص';
    
    // نرمال‌سازی ارقام به انگلیسی برای تاریخ و شماره بل
    var _toEn2 = (typeof toEnglishDigits === 'function') ? toEnglishDigits : function(x){ return x; };
    const date = _toEn2(document.getElementById('purchase-date').value);
    const billNumber = _toEn2(document.getElementById('purchase-bill-number').value);
    const currency = document.getElementById('purchase-currency').value;
    const type = document.getElementById('purchase-type').value;
    const shipping = parseFloat(document.getElementById('purchase-shipping').value) || 0;
    const notes = document.getElementById('purchase-notes').value;
    
    if (!supplierId) {
        showMessage('خطا', 'لطفاً تامین‌کننده را انتخاب کنید.');
        return;
    }

    const items = [];
    const rows = document.querySelectorAll('#purchase-items-body .purchase-item-row');
    let hasError = false;
    
    rows.forEach(row => {
        const productSelect = row.querySelector('.purchase-item-product');
        const productId = productSelect.value;
        
        let productName = 'جنس نامشخص';
        if(productSelect.options && productSelect.selectedIndex >= 0 && productSelect.options.length > 0) {
            productName = productSelect.options[productSelect.selectedIndex].text;
        } else {
            const searchInput = row.querySelector('.product-search-input');
            if(searchInput) productName = searchInput.value;
        }

        const quantity = parseFloat(row.querySelector('.purchase-item-quantity').value) || 0;
        const unit = row.querySelector('.purchase-item-unit').value;
        const price = parseFloat(row.querySelector('.purchase-item-price').value) || 0;
        const discountInput = row.querySelector('.purchase-item-discount');
        const discount = discountInput ? (parseFloat(discountInput.value) || 0) : 0;
        const totalSpan = row.querySelector('.purchase-item-total');
        const total = totalSpan ? (parseFloat(totalSpan.textContent.replace(/,/g, '')) || 0) : 0;
        var _unitType = row.dataset.unitType || 'primary';
        var _secFactor = parseFloat(row.dataset.secondaryFactor) || 0;
        
        if (productId && productId !== 'new' && quantity > 0 && price > 0) {
            items.push({ productId: parseInt(productId), productName, quantity, unit, price, discount, total, unitType: _unitType, secondaryFactor: _secFactor });
        } else if (productId === 'new') {
            showMessage('توجه', 'لطفاً جنس جدید را از مدیریت اجناس ثبت کنید.');
            hasError = true;
        }
    });
    
    if (hasError) return;
    if (items.length === 0) {
        showMessage('خطا', 'لطفاً حداقل یک جنس اضافه کنید.');
        return;
    }
    
    // ── مدلِ پویا: فیلدِ اصلی = ارزِ پایه، فیلدِ foreign = هر ارزِ غیرپایه ──
    var _basePur = _baseCur();
    var _isForeignPur = (currency !== _basePur);
    const paidAfn = _isForeignPur ? 0 : (parseFloat((document.getElementById('purchase-paid-afn') || {}).value) || 0);
    const paidUsd = 0; // فیلدِ USD قدیمی در مدلِ جدید نقشی ندارد
    var paidForeign = 0;
    if (_isForeignPur) {
        paidForeign = parseFloat((document.getElementById('purchase-paid-foreign') || {}).value) || 0;
    }
    const remainingInput = document.getElementById('purchase-remaining');
    const remaining = remainingInput ? (parseFormattedNumber(remainingInput.value)) : 0;
    
    const cashboxId = document.getElementById('purchase-cashbox')?.value || '';
    
    // ====== هشدار کمبود موجودی حساب (با اجازه ادامه و منفی شدن) ======
    if (cashboxId && !document.getElementById('purchaseForm')?.dataset?.editId) {
        var _purchaseCashbox = db.getCashboxes().find(c => c.id == cashboxId);
        var _purchasePaid = _isForeignPur ? paidForeign : paidAfn;
        if (_purchaseCashbox && _purchasePaid > 0 && parseFloat(_purchaseCashbox.balance || 0) < _purchasePaid) {
            if (!_confirmNegBalance('موجودی حساب «' + (_purchaseCashbox.name || '') + '» کافی نیست.\nموجودی فعلی: ' + formatNumber(parseFloat(_purchaseCashbox.balance || 0)) + '\nمبلغ پرداخت: ' + formatNumber(_purchasePaid) + '\n\nآیا می‌خواهید با وجود کمبود موجودی، خرید را ثبت کنید؟ (موجودی حساب منفی خواهد شد)', savePurchase)) return;
        }
    }
    
    // ===== محاسبه دقیق مبلغ کل بر اساس بل خرید =====
    // subTotal = جمع (تعداد × قیمت) برای همه آیتم‌ها
    // totalDiscount = جمع تخفیف آیتم‌ها
    // totalAmount = subTotal - totalDiscount  (هزینه حمل و نقل در مبلغِ خرید لحاظ نمی‌شود؛
    // به‌جای آن به‌صورت یک مصرفِ جداگانه از حساب کسر می‌گردد — _syncPurchaseShippingExpense)
    const subTotal = items.reduce((s, i) => s + (parseFloat(i.quantity || 0) * parseFloat(i.price || 0)), 0);
    // تخفیف کل = تخفیف اقلام + تخفیف کلیِ بل (مقدارِ نمایش‌داده‌شده در فرم شامل هر دو است)
    var _pPerItemDisc = items.reduce((s, i) => s + (parseFloat(i.discount || 0)), 0);
    var _pDiscEl = document.getElementById('purchase-total-discount');
    var _pDomDisc = (_pDiscEl && _pDiscEl.dataset && _pDiscEl.dataset.raw !== undefined) ? parseFloat(_pDiscEl.dataset.raw) : NaN;
    const totalDiscount = (!isNaN(_pDomDisc) && _pDomDisc >= _pPerItemDisc) ? _pDomDisc : _pPerItemDisc;
    const grandTotal = (subTotal - totalDiscount);
    
    // خواندن تاریخ انقضاء از فرم خرید فوری (در صورت وجود)
    var _purchaseExpiryDate = _toEn2((document.getElementById('purchase-expiry-date') || {}).value || '');

    // ===== تقسیمِ هزینه حمل و نقل بینِ اقلام بر اساسِ روشِ انتخاب‌شده =====
    // فقط داده‌های تقسیم روی هر قلم ذخیره می‌شود (سهم/هزینهٔ واحد/قیمت تمام‌شده) + روشِ انتخاب‌شده
    // روی تراکنش، تا در ویرایش/حذف/بازیابی/مهاجرت قابلِ بازسازی باشد. این کار هیچ اثری روی
    // مبلغِ بل، حساب، موجودی، FIFO یا مفاد ندارد (مبلغِ بل همان قیمتِ خرید بدونِ حمل است).
    var _shipMethod = (typeof _getShippingMethod === 'function') ? _getShippingMethod() : 'value';
    try {
        var _shipDist = _computeShippingDistribution(items, shipping, _shipMethod);
        for (var _si = 0; _si < items.length; _si++) {
            if (_shipDist[_si]) {
                items[_si].shippingShare = _shipDist[_si].shippingShare;
                items[_si].shippingUnitCost = _shipDist[_si].shippingUnitCost;
                items[_si].landedUnitCost = _shipDist[_si].landedUnitCost;
            }
        }
    } catch (_shpErr) { console.warn('shipping distribution:', _shpErr); }
    
    const transaction = {
        type: 'خرید', supplierId: parseInt(supplierId), supplierName, date, billNumber, currency,
        purchaseType: type, items, shipping, shippingMethod: _shipMethod, paidAfn, paidUsd, paidForeign, paidForeignCurrency: (_isForeignPur ? currency : null), remaining, 
        // نگاشتِ پرداختیِ چند-ارزی + نرخِ لحظهٔ ثبت (قفلِ نرخِ تاریخیِ سند)
        paidAmounts: _buildCashAmounts(currency, paidAfn, paidUsd, paidForeign),
        rateUsed: _dayRateFor(currency),
        baseCurrency: (typeof CurrencySystem !== 'undefined' && CurrencySystem.getBaseCode) ? CurrencySystem.getBaseCode() : 'AFN',
        cashboxId: cashboxId ? parseInt(cashboxId) : null, notes,
        subTotal: subTotal,
        totalDiscount: totalDiscount,
        totalAmount: grandTotal,
        amount: grandTotal,
        expiryDate: _purchaseExpiryDate,
        status: remaining > 0 ? 'باقی‌مانده' : 'تسویه‌شده'
    };
    
    // ====== به‌روزرسانی تاریخ انقضاء اجناس از فهرست اجناس انبار ======
    // اگر در فرم خرید فوری تاریخ انقضاء جدید درج شده باشد، تاریخ انقضاء همان اجناس
    // در فهرست اجناس انبار نیز به همین تاریخ جدید آپدیت می‌شود
    var _updateProductsExpiry = function() {
        if (!_purchaseExpiryDate) return;
        if (!Array.isArray(items) || items.length === 0) return;
        if (typeof db === 'undefined' || !db.getProducts || !db.saveProduct) return;
        var _allProducts = db.getProducts() || [];
        items.forEach(function(it) {
            if (!it.productId) return;
            var prod = _allProducts.find(function(p) { return p.id == it.productId; });
            if (!prod) return;
            prod.expiryDate = _purchaseExpiryDate;
            db.saveProduct(prod);
        });
    };
    
    const editId = document.getElementById('purchaseForm')?.dataset?.editId;
    if (editId) {
        transaction.id = parseInt(editId);
        const result = db.saveTransaction(transaction);
        if (result.success !== false) {
            _updateProductsExpiry();
            // هزینه حمل و نقل به‌عنوان مصرفِ جداگانه (خارج از مبلغِ خرید) — هم‌گام‌سازی روی ویرایش
            _syncPurchaseShippingExpense(parseInt(editId), shipping, currency, transaction.cashboxId, date, billNumber);
            showMessage('موفقیت', 'فاکتور خرید با موفقیت ویرایش شد.'); addChangelog('ویرایش', 'خرید', transaction, 'ویرایش فاکتور خرید');
            delete document.getElementById('purchaseForm').dataset.editId;
            if (typeof resetPurchaseForm === 'function') resetPurchaseForm();
            if (!_consumeFormReturn()) {
                showSection('purchases-list');
                if (typeof loadPurchasesList === 'function') loadPurchasesList();
            }
        } else {
            showMessage('خطا', result.error || 'خطا در ویرایش فاکتور خرید');
        }
    } else {
        var _purRes = db.saveTransaction(transaction);
        _updateProductsExpiry();
        // هزینه حمل و نقل به‌عنوان مصرفِ جداگانه (از حساب کسر می‌شود، خارج از مبلغِ خرید)
        if (_purRes && _purRes.success !== false && _purRes.data) {
            _syncPurchaseShippingExpense(_purRes.data.id, shipping, currency, transaction.cashboxId, date, billNumber);
        }
        // ثبت در لاگ معاملات حساب (بدون updateCashboxBalance مجدد — database.js این کار را کرده)
        if (typeof _logCashboxTransaction === 'function' && transaction.cashboxId) {
            var paidPurchase;
            if (_isForeignPur) paidPurchase = transaction.paidForeign || 0;
            else paidPurchase = (typeof _engCashPaidFor === 'function')
                ? _engCashPaidFor(transaction, 'paid')
                : (transaction.paidAfn || 0);
            if (paidPurchase > 0) {
                _logCashboxTransaction(parseInt(transaction.cashboxId), {
                    type: 'purchase',
                    amount: paidPurchase,
                    currency: transaction.currency,
                    datetime: transaction.date,
                    notes: transaction.notes || '',
                    description: 'خرید — بل ' + (transaction.billNumber || '') + (transaction.supplierName ? ' — ' + transaction.supplierName : '')
                });
            }
        }
        showMessage('موفقیت', 'فاکتور خرید با موفقیت ثبت شد.'); addChangelog('ثبت', 'خرید', transaction, 'ثبت فاکتور خرید جدید');
        // ذخیره و هدایت فوری بدون تأخیر
        if (typeof resetPurchaseForm === 'function') resetPurchaseForm();
        if (typeof loadDashboard === 'function') loadDashboard();
        if (!_consumeFormReturn()) {
            if (typeof loadPurchasesList === 'function') loadPurchasesList();
            showSection('purchases-list');
        }
    }
    if (typeof refreshOpenReport === 'function') refreshOpenReport();
}

// حذفِ پسوندهای خودکارِ توضیحات («| انتقال به: …»، «| انتقال از: …»، «| تأمینِ مصرف: …»)
// تا هنگامِ ویرایش و ثبتِ دوباره، جهتِ «از/به» تکرار/مخلوط نشود و همیشه پسوندِ درست ساخته شود.
function _stripReceiptAutoNote(s) {
    return String(s == null ? '' : s)
        .replace(/\s*\|\s*انتقال\s*(?:به|از)\s*:\s*[^|]*/g, '')
        .replace(/\s*\|\s*تأمین[ِ]?\s*مصرف\s*:\s*[^|]*/g, '')
        .trim();
}

function saveReceipt() {
    const personId = document.getElementById('receive-from').value;
    const personInput = document.getElementById('receive-from-search');
    const personName = (personInput && personInput.value) ? personInput.value : 'فرستنده نامشخص';
    
    const date = document.getElementById('receipt-date').value;
    const amount = parseFloat(document.getElementById('receipt-amount').value) || 0;
    const currency = document.getElementById('receipt-currency').value;
    const type = document.getElementById('receipt-type').value;
    const cashboxId = document.getElementById('receipt-cashbox').value;
    const reference = document.getElementById('receipt-reference').value;
    // پاک‌سازیِ پسوندهای خودکارِ قبلی (انتقال به/از، تأمینِ مصرف) تا در ویرایش، «از/به» تکرار/مخلوط نشود
    const description = _stripReceiptAutoNote(document.getElementById('receipt-description').value);
    
    const destTab = (typeof _receiptDestTab !== 'undefined' && _receiptDestTab) ? _receiptDestTab : 'cashbox';
    const destPersonId = (document.getElementById('receipt-dest-person') || {}).value || '';
    const destPersonName = (document.getElementById('receipt-dest-person-search') || {}).value || '';
    const expenseCategory = (document.getElementById('receipt-expense-category') || {}).value || '';
    const noTrack = !!(document.getElementById('receipt-notrack') && document.getElementById('receipt-notrack').checked);
    const _baseC = (typeof CurrencySystem !== 'undefined' && CurrencySystem.getBaseCode) ? CurrencySystem.getBaseCode() : 'AFN';

    if (amount <= 0) { showMessage('خطا', 'مبلغ معتبر وارد کنید.'); return; }

    // ویرایشِ دریافتِ گروهی (اشخاص/مصارف): رکوردهای قبلیِ گروه حذف و سپس تازه ساخته می‌شوند تا
    // همهٔ بخش‌های مرتبط (تراکنشِ طرفِ مقابل و ردیفِ مصرف) دقیقاً هماهنگ به‌روز شوند.
    var _rFormEl = document.getElementById('receiptForm');
    var _editGroupKey = _rFormEl && _rFormEl.dataset ? _rFormEl.dataset.editGroupKey : '';
    var _editGroupId = _rFormEl && _rFormEl.dataset ? _rFormEl.dataset.editGroupId : '';
    if (_editGroupKey && _editGroupId) {
        try {
            var _allTxE = db.getTransactions();
            localStorage.setItem('transactions', JSON.stringify(_allTxE.filter(function (t) { return t[_editGroupKey] !== _editGroupId; })));
            if (_editGroupKey === 'expenseGroup') {
                var _allExpE = db.getExpenses();
                localStorage.setItem('expenses', JSON.stringify(_allExpE.filter(function (e) { return e.expenseGroup !== _editGroupId; })));
            }
        } catch (e) {}
        if (_rFormEl) { delete _rFormEl.dataset.editGroupKey; delete _rFormEl.dataset.editGroupId; delete _rFormEl.dataset.editId; }
    }

    // ── دریافت بدون پیگیری: فقط ماندهٔ حساب شخص تعدیل می‌شود ──
    // (cashboxId=null ⇒ db.saveTransaction هیچ حساب/صندوقی را تغییر نمی‌دهد؛
    //  اما اثرِ «دریافت» روی دفترِ شخص همچنان اعمال می‌شود.)
    if (noTrack) {
        if (!personId) { showMessage('خطا', 'لطفاً شخص را انتخاب کنید.'); return; }
        var _txNT = {
            type: 'دریافت', personId: parseInt(personId), personName, date, amount, currency,
            receiptType: type, cashboxId: null, noTrack: true, reference, description, status: 'انجام شد',
            rateUsed: _dayRateFor(currency), baseCurrency: _baseC
        };
        var _ntEditId = document.getElementById('receiptForm')?.dataset?.editId;
        if (_ntEditId) _txNT.id = parseInt(_ntEditId);
        db.saveTransaction(_txNT);
        var _ntForm = document.getElementById('receiptForm'); if (_ntForm) delete _ntForm.dataset.editId;
        showMessage('موفقیت', 'دریافتِ بدون پیگیری ثبت شد (فقط ماندهٔ حساب شخص تعدیل شد).');
        addChangelog('ثبت', 'دریافت', _txNT, 'دریافت بدون پیگیری');
        if (typeof resetReceiptForm === 'function') resetReceiptForm();
        if (typeof loadDashboard === 'function') loadDashboard();
        if (!_consumeFormReturn()) { if (typeof loadReceiptsList === 'function') loadReceiptsList(); showSection('receipts-list'); }
        if (typeof refreshOpenReport === 'function') refreshOpenReport();
        return;
    }

    // ── تبِ مصارف: ثبتِ قطعیِ دوطرفهٔ مرتبط — پرداختِ شخصِ A + ردیفِ مصرف با کتگوری ──
    if (destTab === 'expense') {
        if (!personId) { showMessage('خطا', 'پرداخت‌کننده را انتخاب کنید.'); return; }
        if (!expenseCategory) { showMessage('خطا', 'کتگوری مصرف را انتخاب کنید.'); return; }
        var _egrp = 'rex_' + Date.now();
        // لِنگِ حسابِ شخص A: «دریافت» (طلبکار، −M) — A هزینه را تأمین کرده و سیستم به او بدهکار است.
        // (توازن دوطرفه: مصرفِ +M در برابرِ بدهیِ سیستم به A؛ بدون این، ۲M دوبار شمرده می‌شد.)
        db.saveTransaction({
            type: 'دریافت', personId: parseInt(personId), personName, date, amount, currency,
            receiptType: type, reference, expenseGroup: _egrp, category: expenseCategory,
            description: (description || '') + ' | تأمینِ مصرف: ' + expenseCategory, status: 'انجام شد',
            rateUsed: _dayRateFor(currency), baseCurrency: _baseC
        });
        // ردیفِ مصرف در امور مالی/مصارف با همان کتگوری — مرتبط با همان گروه و همان شخص
        try {
            db.saveExpense({
                title: 'مصرف: ' + expenseCategory, category: expenseCategory,
                amount: amount, currency: currency, date: date, cashboxId: null,
                personId: parseInt(personId), cashboxName: '',
                notes: (description || '') + ' | پرداخت‌کننده: ' + personName, type: 'مصرف', expenseGroup: _egrp
            });
        } catch (e) {}
        var _rf1 = document.getElementById('receiptForm'); if (_rf1) delete _rf1.dataset.editId;
        showMessage('موفقیت', 'ثبت شد: ' + personName + ' مصرفِ «' + expenseCategory + '» را تأمین کرد (به مبلغ در حسابش طلبکار شد).');
        addChangelog('ثبت', 'دریافت', { category: expenseCategory, amount: amount, currency: currency, personId: personId }, 'مصرف: ' + expenseCategory + ' (پرداخت‌کننده: ' + personName + ')');
        if (typeof resetReceiptForm === 'function') resetReceiptForm();
        if (typeof loadDashboard === 'function') loadDashboard();
        if (!_consumeFormReturn()) { if (typeof loadReceiptsList === 'function') loadReceiptsList(); showSection('receipts-list'); }
        if (typeof refreshOpenReport === 'function') refreshOpenReport();
        return;
    }

    // ── تبِ اشخاص: انتقالِ قطعیِ دوطرفهٔ مرتبط — پرداختِ A + دریافتیِ B (هر دو با یک گروه) ──
    if (destTab === 'person') {
        if (!personId) { showMessage('خطا', 'پرداخت‌کننده را انتخاب کنید.'); return; }
        if (!destPersonId) { showMessage('خطا', 'شخصِ دریافت‌کننده را انتخاب کنید.'); return; }
        if (parseInt(personId) === parseInt(destPersonId)) { showMessage('خطا', 'پرداخت‌کننده و دریافت‌کننده نباید یکی باشند.'); return; }
        var _tgrp = 'rtx_' + Date.now();
        // لِنگِ پرداخت‌کننده A: «پرداخت» (اثرِ خروجِ مبلغ از A)
        db.saveTransaction({
            type: 'پرداخت', personId: parseInt(personId), personName, date, amount, currency,
            receiptType: type, reference, transferGroup: _tgrp, counterpartyId: parseInt(destPersonId), counterpartyName: destPersonName,
            description: (description || '') + ' | انتقال به: ' + destPersonName, status: 'انجام شد',
            rateUsed: _dayRateFor(currency), baseCurrency: _baseC
        });
        // لِنگِ دریافت‌کننده B: «دریافتی» (اثرِ ورودِ مبلغ به B)
        db.saveTransaction({
            type: 'دریافت', personId: parseInt(destPersonId), personName: destPersonName, date, amount, currency,
            receiptType: type, reference, transferGroup: _tgrp, counterpartyId: parseInt(personId), counterpartyName: personName,
            description: (description || '') + ' | انتقال از: ' + personName, status: 'انجام شد',
            rateUsed: _dayRateFor(currency), baseCurrency: _baseC
        });
        var _rf2 = document.getElementById('receiptForm'); if (_rf2) delete _rf2.dataset.editId;
        showMessage('موفقیت', 'انتقال ثبت شد: پرداختِ ' + personName + ' → دریافتیِ ' + destPersonName + '.');
        addChangelog('ثبت', 'دریافت', { fromId: personId, toId: destPersonId, amount: amount, currency: currency }, 'انتقال از ' + personName + ' به ' + destPersonName);
        if (typeof resetReceiptForm === 'function') resetReceiptForm();
        if (typeof loadDashboard === 'function') loadDashboard();
        if (!_consumeFormReturn()) { if (typeof loadReceiptsList === 'function') loadReceiptsList(); showSection('receipts-list'); }
        if (typeof refreshOpenReport === 'function') refreshOpenReport();
        return;
    }

    // ── تبِ حساب‌ها (پیش‌فرض): دریافتی به حساب ──
    let transaction;
    {
        if (!personId) { showMessage('خطا', 'لطفاً شخص را انتخاب کنید.'); return; }
        if (!cashboxId) { showMessage('خطا', 'حساب را مشخص کنید.'); return; }
        transaction = {
            type: 'دریافت', personId: parseInt(personId), personName, date, amount, currency,
            receiptType: type, cashboxId: parseInt(cashboxId), reference, description, status: 'انجام شد',
            rateUsed: _dayRateFor(currency), baseCurrency: _baseC
        };
    }

    const editId = document.getElementById('receiptForm')?.dataset?.editId;
    if (editId) {
        transaction.id = parseInt(editId);
    }
    
    db.saveTransaction(transaction);
    // پاک کردن editId بلافاصله پس از ذخیره — تا دریافت بعدی به‌اشتباه روی همین معامله بازنویسی نشود
    var _recForm = document.getElementById('receiptForm');
    if (_recForm) delete _recForm.dataset.editId;
    
    // ثبت کمیشن حواله به عنوان هزینه در مصارف
    if (type === 'حواله' && cashboxId) {
        const commissionAmount = parseFloat(document.getElementById('receipt-hawala-commission').value) || 0;
        if (commissionAmount > 0) {
            const cashboxes = db.getCashboxes();
            const cashbox = cashboxes.find(c => c.id == parseInt(cashboxId));
            const expense = {
                title: 'کمیشن حواله',
                category: 'کمیشن حواله',
                amount: commissionAmount,
                currency: currency,
                date: date,
                cashboxId: parseInt(cashboxId),
                cashboxName: cashbox ? cashbox.name : '',
                personId: personId ? parseInt(personId) : null,
                notes: description || '',
                type: 'مصرف'
            };
            db.saveExpense(expense);
        }
    }
    
    showMessage('موفقیت', 'دریافت با موفقیت ثبت شد.'); addChangelog('ثبت', 'دریافت', transaction, 'ثبت دریافت جدید');
    // ذخیره و هدایت فوری بدون تأخیر
    if (typeof resetReceiptForm === 'function') resetReceiptForm();
    if (typeof loadDashboard === 'function') loadDashboard();
    if (!_consumeFormReturn()) {
        if (typeof loadReceiptsList === 'function') loadReceiptsList();
        showSection('receipts-list');
    }
    if (typeof refreshOpenReport === 'function') refreshOpenReport();
}

function savePayment() {
    const personId = document.getElementById('pay-to').value;
    const personInput = document.getElementById('pay-to-search');
    const personName = (personInput && personInput.value) ? personInput.value : 'گیرنده نامشخص';
    
    const date = document.getElementById('payment-date').value;
    const amount = parseFloat(document.getElementById('payment-amount').value) || 0;
    const currency = document.getElementById('payment-currency').value;
    const type = document.getElementById('payment-type').value;
    const cashboxId = document.getElementById('payment-cashbox').value;
    const reference = document.getElementById('payment-reference').value;
    const description = document.getElementById('payment-description').value;
    const noTrack = !!(document.getElementById('payment-notrack') && document.getElementById('payment-notrack').checked);

    if (!personId) { showMessage('خطا', 'لطفاً گیرنده را انتخاب کنید.'); return; }
    if (amount <= 0) { showMessage('خطا', 'مبلغ معتبر وارد کنید.'); return; }
    if (!noTrack && !cashboxId) { showMessage('خطا', 'حساب را مشخص کنید.'); return; }

    const cashboxes = db.getCashboxes();
    const cashbox = noTrack ? null : cashboxes.find(c => c.id == cashboxId);
    // ====== هشدار کمبود موجودی حساب (با اجازه ادامه و منفی شدن) ======
    // موجودیِ همان ارزِ تراکنش (نه ماندهٔ تک‌ارزیِ حساب) — جلوگیری از تداخلِ بینِ ارزها
    // در حالتِ «بدون پیگیری» هیچ حساب/صندوقی درگیر نیست، پس این هشدار اجرا نمی‌شود.
    var _cbBal = (cashbox && typeof db.getCashboxBalance === 'function')
        ? db.getCashboxBalance(cashbox, currency) : (cashbox ? parseFloat(cashbox.balance || 0) : 0);
    if (!noTrack && cashbox && _cbBal < amount) {
        if (!_confirmNegBalance('موجودی حساب «' + (cashbox.name || '') + '» در ارز ' + getCurrencyLabel(currency) + ' کافی نیست.\nموجودی فعلی: ' + formatNumber(_cbBal) + '\nمبلغ پرداخت: ' + formatNumber(amount) + '\n\nآیا می‌خواهید با وجود کمبود موجودی، پرداخت را ثبت کنید؟ (موجودی حساب منفی خواهد شد)', savePayment)) return;
    }

    const transaction = {
        type: 'پرداخت', personId: parseInt(personId), personName, date, amount, currency,
        paymentType: type, cashboxId: noTrack ? null : parseInt(cashboxId), noTrack: noTrack, reference, description, status: 'انجام شد',
        // نرخِ قفل‌شدهٔ لحظهٔ ثبت (Snapshot Rate) — برای گزارشِ تجمیعیِ دقیق
        rateUsed: _dayRateFor(currency),
        baseCurrency: (typeof CurrencySystem !== 'undefined' && CurrencySystem.getBaseCode) ? CurrencySystem.getBaseCode() : 'AFN'
    };
    
    const editId = document.getElementById('paymentForm')?.dataset?.editId;
    if (editId) {
        transaction.id = parseInt(editId);
    }
    
    db.saveTransaction(transaction);
    // پاک کردن editId بلافاصله پس از ذخیره — تا پرداخت بعدی به‌اشتباه روی همین معامله بازنویسی نشود
    var _payForm = document.getElementById('paymentForm');
    if (_payForm) delete _payForm.dataset.editId;
    
    // توجه: db.saveTransaction برای نوع «پرداخت» داخلاً updateCashboxBalance را صدا می‌زند
    // پس کسر مجدد اینجا لازم نیست و حذف شده است تا از کسر دوگانه جلوگیری شود
    
    // ثبت کمیشن حواله به عنوان هزینه در مصارف
    // (در حالتِ «بدون پیگیری» حسابی درگیر نیست، پس کمیشنِ صندوقی هم ثبت نمی‌شود)
    if (type === 'حواله' && !noTrack) {
        const commissionAmount = parseFloat(document.getElementById('payment-hawala-commission').value) || 0;
        if (commissionAmount > 0) {
            const expense = {
                title: 'کمیشن حواله',
                category: 'کمیشن حواله',
                amount: commissionAmount,
                currency: currency,
                date: date,
                cashboxId: parseInt(cashboxId),
                cashboxName: cashbox ? cashbox.name : '',
                personId: personId ? parseInt(personId) : null,
                notes: description || '',
                type: 'مصرف'
            };
            db.saveExpense(expense);
        }
    }
    
    showMessage('موفقیت', noTrack ? 'پرداختِ بدون پیگیری ثبت شد (فقط ماندهٔ حساب شخص تعدیل شد).' : 'پرداخت با موفقیت ثبت شد.'); addChangelog('ثبت', 'پرداخت', transaction, noTrack ? 'پرداخت بدون پیگیری' : 'ثبت پرداخت جدید');
    // ذخیره و هدایت فوری بدون تأخیر
    if (typeof resetPaymentForm === 'function') resetPaymentForm();
    if (typeof loadDashboard === 'function') loadDashboard();
    if (!_consumeFormReturn()) {
        if (typeof loadPaymentsList === 'function') loadPaymentsList();
        showSection('payments-list');
    }
    if (typeof refreshOpenReport === 'function') refreshOpenReport();
}

// ذخیره مصرف
// ذخیره مصرف
function saveExpense() {
    const title = document.getElementById('expense-title').value;
    // ... بقیه کدهای دریافت مقادیر مثل قبل ...
    const category = document.getElementById('expense-category').value;
    const amount = parseFloat(document.getElementById('expense-amount').value) || 0;
    const currency = document.getElementById('expense-currency').value;
    const date = document.getElementById('expense-date').value;
    const cashboxId = document.getElementById('expense-cashbox').value;
    const personId = (function(){ var el = document.getElementById('expense-person'); return el ? el.value : ''; })();
    const notes = document.getElementById('expense-notes').value;
    
    if (!title) { showMessage('خطا', 'لطفاً عنوان را وارد کنید.'); return; }
    // دسته‌بندی اختیاری است
    if (amount <= 0) { showMessage('خطا', 'لطفاً مبلغ معتبر وارد کنید.'); return; }
    if (!cashboxId) { showMessage('خطا', 'لطفاً حساب را انتخاب کنید.'); return; }
    
    const cashboxes = db.getCashboxes();
    const cashbox = cashboxes.find(c => c.id == cashboxId);
    // ====== هشدار کمبود موجودی حساب (با اجازه ادامه و منفی شدن) ======
    var _cbBalE = (cashbox && typeof db.getCashboxBalance === 'function')
        ? db.getCashboxBalance(cashbox, currency) : (cashbox ? parseFloat(cashbox.balance || 0) : 0);
    if (cashbox && _cbBalE < amount) {
        if (!_confirmNegBalance('موجودی حساب «' + (cashbox.name || '') + '» در ارز ' + getCurrencyLabel(currency) + ' کافی نیست.\nموجودی فعلی: ' + formatNumber(_cbBalE) + '\nمبلغ مصرف: ' + formatNumber(amount) + '\n\nآیا می‌خواهید با وجود کمبود موجودی، مصرف را ثبت کنید؟ (موجودی حساب منفی خواهد شد)', saveExpense)) return;
    }
    
    const expense = {
        title, category, amount, currency, date,
        cashboxId: parseInt(cashboxId),
        cashboxName: cashbox ? cashbox.name : '',
        personId: personId ? parseInt(personId) : null,
        notes,
        type: 'مصرف'
    };
    
    const editId = document.getElementById('expenseForm').dataset.editId;
    if (editId) {
        expense.id = parseInt(editId);
    }
    
    db.saveExpense(expense);
    
    // توجه: db.saveExpense داخلاً updateCashboxBalance را صدا می‌زند
    // پس کسر مجدد اینجا لازم نیست و حذف شده است تا از کسر دوگانه جلوگیری شود
    
    // ثبت در لاگ معاملات حساب (بدون updateCashboxBalance مجدد — تنها برای نمایشگر لاگ خام)
    if (typeof _logCashboxTransaction === 'function') {
        _logCashboxTransaction(parseInt(cashboxId), {
            type: 'expense',
            amount: amount,
            currency: currency,
            datetime: date,
            notes: notes,
            description: 'مصرف: ' + title + (category ? ' (' + category + ')' : '')
        });
    }
    
    showMessage('موفقیت', 'مصرف با موفقیت ثبت شد.'); addChangelog(editId ? 'ویرایش' : 'ثبت', 'مصرف', expense, (editId ? 'ویرایش' : 'ثبت') + ' مصرف');
    
    // بازگشت به تب مصارف در امور مالی (یا داشبورد اگر از دکمهٔ سریع آمده)
    resetExpenseForm();
    if (!_consumeFormReturn()) {
        showSection('financial');
        setTimeout(() => {
            switchFinancialTab('expenses');
        }, 100);
    }
    if (typeof refreshOpenReport === 'function') refreshOpenReport();
}
