function showPersonForm(personId = null, opts = null) {
    // اگر از «مشخصات شخص» باز شده باشد، پس از برگشت/ثبت به همان مشخصات برگردد؛
    // در غیر این‌صورت پرچم پاک می‌شود تا رفتار پیش‌فرض (برگشت به لیست اشخاص) اجرا شود.
    _personDetailReturnForForm = (opts && opts.fromDetail) ? personId : null;
    const form = document.getElementById('person-form');
    const formTitle = form.querySelector('#person-form-title') || form.querySelector('h2') || form.querySelector('h3');
    const submitButton = form.querySelector('button[type="submit"]');
    
    // بارگذاری کتگوری‌های سفارشی افراد
    const personCatSelect = document.getElementById('person-category');
    if (personCatSelect) {
        const defaultPersonCats = ['مشتری', 'فروشنده', 'کارمند', 'تامین کننده'];
        const customPersonCats = JSON.parse(localStorage.getItem('customPersonCategories') || '[]');
        const allPersonCats = [...new Set([...defaultPersonCats, ...customPersonCats])];
        const currentVal = personCatSelect.value;
        personCatSelect.innerHTML = '<option value="">کتگوری شخص</option>';
        allPersonCats.forEach(cat => {
            const option = document.createElement('option');
            option.value = cat;
            option.textContent = cat;
            personCatSelect.appendChild(option);
        });
        if (currentVal) personCatSelect.value = currentVal;
        // افزودن کتگوری از داخل خود دراپ‌داون (مثل فرم ثبت جنس) — بدون دکمهٔ + جداگانه
        setupProductAddSelect(personCatSelect, 'customPersonCategories', 'کتگوری شخص');
    }
    
    if (personId) {
        if (formTitle) formTitle.textContent = 'ویرایش شخص';
        if (submitButton) submitButton.innerHTML = '<i class="fas fa-folder"></i> ذخیره تغییرات';
        loadPersonData(personId);
    } else {
        if (formTitle) formTitle.textContent = 'ثبت شخص';
        if (submitButton) submitButton.innerHTML = '<i class="fas fa-folder"></i> ذخیره فرد';
        resetPersonForm();
    }
    
    showSection('person-form');
}

