// توابع مدیریت داشبورد
// [loadDashboard تابع اصلی در ابتدای فایل با محاسبات کامل تعریف شده است]

function formatCurrency(amount, currencyCode) {
    var sys = (typeof getNumberSystem === 'function') ? getNumberSystem() : 'fa';
    var locale = (sys === 'en') ? 'en-US' : 'fa-IR';
    // برچسبِ ارز: کدِ داده‌شده، وگرنه ارزِ پایهٔ فعلیِ سیستم (نه «افغانی» ثابت)
    var lbl = (typeof getCurrencyLabel === 'function') ? getCurrencyLabel(currencyCode) : 'افغانی';
    return new Intl.NumberFormat(locale).format(amount || 0) + ' ' + lbl;
}

// تبدیل کد ارز به نام فارسی
function getCurrencyLabel(code) {
    const map = { 'AFN': 'افغانی', 'USD': 'دالر', 'PKR': 'روپیه', 'EUR': 'یورو', 'IRR': 'تومان' };
    // منبعِ واحدِ حقیقت: نامِ محلیِ ارزی که کاربر در سیستم تعریف کرده
    try {
        if (code && typeof CurrencySystem !== 'undefined' && CurrencySystem.getCurrency) {
            var c = CurrencySystem.getCurrency(code);
            // اگر نامِ محلی ثبت نشده باشد، نامِ فارسیِ شناخته‌شده جایگزین می‌شود
            if (c) return c.nameLocal || map[c.code || code] || c.code || code;
        }
    } catch (e) {}
    if (code) return map[code] || code;
    // بدونِ کد → نامِ ارزِ پایهٔ فعلی (نه «افغانی» ثابت)
    try {
        if (typeof CurrencySystem !== 'undefined' && CurrencySystem.getBaseCode) {
            var b = CurrencySystem.getBaseCode();
            var bc = CurrencySystem.getCurrency ? CurrencySystem.getCurrency(b) : null;
            return (bc && bc.nameLocal) ? bc.nameLocal : (map[b] || b);
        }
    } catch (e) {}
    return 'افغانی';
}

// فرمت مبلغ نظر به ارز
function formatAmountWithCurrency(amount, currencyCode) {
    return new Intl.NumberFormat((typeof getNumberSystem === 'function' && getNumberSystem() === 'en') ? 'en-US' : 'fa-IR').format(amount || 0) + ' ' + getCurrencyLabel(currencyCode);
}

/* ---------- 1) کاهش تعداد نمایش در داشبورد به 5 --------- */
function loadRecentTransactions() {
    try {
        const transactions = db.getTransactions();
        // فقط 5 تراکنش آخر
        const recentTransactions = transactions.slice(-5).reverse();
        const tbody = document.querySelector('#recent-transactions-table tbody');
        
        if (!tbody) return;
        
        tbody.innerHTML = '';
        
        recentTransactions.forEach(transaction => {
            let icon = '', typeClass = '', typeText = '';
            switch(transaction.type) {
                case 'فروش': 
                    icon = '<i class="fas fa-shopping-cart text-success"></i>'; 
                    typeClass = 'success'; 
                    typeText = 'فروش'; 
                    break;
                case 'خرید': 
                    icon = '<i class="fas fa-truck-loading text-primary"></i>'; 
                    typeClass = 'primary'; 
                    typeText = 'خرید'; 
                    break;
                case 'دریافت': 
                    icon = '<i class="fas fa-money-bill-wave text-success"></i>'; 
                    typeClass = 'success'; 
                    typeText = 'دریافت'; 
                    break;
                case 'پرداخت': 
                    icon = '<i class="fas fa-money-check-alt text-danger"></i>'; 
                    typeClass = 'danger'; 
                    typeText = 'پرداخت'; 
                    break;
            }
            
            const row = document.createElement('tr');
            row.innerHTML = `
                <td>${transaction.date || transaction.createdAt || '---'}</td>
                <td><span class="badge badge-${typeClass}">${icon} ${typeText}</span></td>
                <td>${transaction.customerName || transaction.personName || '---'}</td>
                <td>${formatCurrency(transaction.totalAmount || transaction.amount || 0)}</td>
                <td><span class="badge badge-success">انجام شد</span></td>
            `;
            tbody.appendChild(row);
        });
    } catch (error) {
        console.error('خطا در بارگذاری تراکنش‌های اخیر:', error);
    }
}
function createSalesChart(days = 7) {
    const canvas = document.getElementById('sales-chart');
    if (!canvas) return;
    
    const ctx = canvas.getContext('2d');
    
    // پاک کردن canvas قبلی
    if (window.salesChart instanceof Chart) {
        window.salesChart.destroy();
    }
    
    // داده‌های 7 روز اخیر
    const salesData = getSalesDataLastNDays(days);
    
    window.salesChart = new Chart(ctx, {
        type: 'line',
        data: {
            labels: salesData.labels,
            datasets: [{
                label: 'فروش (افغانی)',
                data: salesData.amounts,
                borderColor: 'var(--secondary-color)',
                backgroundColor: 'rgba(255, 127, 80, 0.1)',
                borderWidth: 2,
                fill: true,
                tension: 0.4
            }]
        },
        options: {
            responsive: true,
            maintainAspectRatio: false,
            plugins: {
                legend: {
                    display: false
                },
                tooltip: {
                    rtl: true,
                    titleFont: {
                        family: 'Vazirmatn'
                    },
                    bodyFont: {
                        family: 'Vazirmatn'
                    },
                    callbacks: {
                        label: function(context) {
                            return formatNumber(context.raw) + ' ' + ((typeof getCurrencyLabel === 'function') ? getCurrencyLabel(null) : 'افغانی');
                        }
                    }
                }
            },
            scales: {
                x: {
                    grid: {
                        display: false
                    },
                    ticks: {
                        font: {
                            family: 'Vazirmatn'
                        }
                    }
                },
                y: {
                    beginAtZero: true,
                    grid: {
                        color: 'rgba(0,0,0,0.05)'
                    },
                    ticks: {
                        font: {
                            family: 'Vazirmatn'
                        },
                        callback: function(value) {
                            return formatNumber(value) + ' ' + ((typeof getCurrencyLabel === 'function') ? getCurrencyLabel(null) : 'افغانی');
                        }
                    }
                }
            }
        }
    });
}

function getSalesDataLastNDays(days) {
    const transactions = db.getTransactions();
    const sales = transactions.filter(t => t.type === 'فروش');
    const labels = [];
    const amounts = [];
    
    for (let i = days - 1; i >= 0; i--) {
        const date = new Date();
        date.setDate(date.getDate() - i);
        const dateString = formatDateToJalali(date);
        labels.push(dateString);
        
        const daySales = sales.filter(s => {
            const saleDate = s.date || s.createdAt;
            return saleDate === dateString;
        });
        
        const total = daySales.reduce((sum, sale) => sum + (sale.totalAmount || 0), 0);
        amounts.push(total);
    }
    
    return { labels, amounts };
}

function formatDateToJalali(date) {
    const persianDate = new PersianDate(date);
    return persianDate.format('YYYY/MM/DD');
}

function updateSalesChart(days) {
    createSalesChart(parseInt(days));
}


/* ===== نمودار آمار پیشرفته داشبورد (روزانه / ماهانه / سالانه) ===== */
window._advChartMode = 'week';
window._advStatsChart = null;

function switchAdvChart(mode) { switchWeeklyChart(mode); }

function switchWeeklyChart(mode) {
    window._advChartMode = mode;
    ['week','month','year'].forEach(m => {
        const btn = document.getElementById('wk-btn-' + m);
        if (btn) btn.classList.toggle('active', m === mode);
    });
    renderWeeklySalesChart(mode);
}

function renderWeeklySalesChart(mode) {
    const canvas = document.getElementById('weekly-sales-chart');
    if (!canvas || !window.Chart) return;

    if (window._advStatsChart instanceof Chart) {
        window._advStatsChart.destroy();
        window._advStatsChart = null;
    }

    const transactions = (db.getTransactions ? db.getTransactions() : []) || [];
    const dayNames = ['شنبه','یک‌شنبه','دوشنبه','سه‌شنبه','چهارشنبه','پنج‌شنبه','جمعه'];

    let labels = [], currentData = [], prevData = [];

    // محاسبه فروش برای یک بازه زمانی (با امکان فیلتر بر اساس ارز)
    function getSalesForDate(dateStr, currencyFilter) {
        return transactions
            .filter(tx => tx.type === 'فروش' &&
                          (tx.date || tx.createdAt || '').split(' ')[0] === dateStr &&
                          (currencyFilter ? (tx.currency || _baseCur()) === currencyFilter : true))
            .reduce((s, tx) => s + parseFloat(tx.totalAmount || tx.amount || 0), 0);
    }
    function getSalesForMonthStr(monthPrefix) {
        return transactions
            .filter(tx => tx.type === 'فروش' && (tx.date || tx.createdAt || '').startsWith(monthPrefix))
            .reduce((s, tx) => s + parseFloat(tx.totalAmount || tx.amount || 0), 0);
    }
    function getSalesForYearStr(yearPrefix) {
        return transactions
            .filter(tx => tx.type === 'فروش' && (tx.date || tx.createdAt || '').startsWith(yearPrefix + '/'))
            .reduce((s, tx) => s + parseFloat(tx.totalAmount || tx.amount || 0), 0);
    }

    if (mode === 'week') {
        // ۷ روزِ اخیر (هفتهٔ جاری) و ۷ روزِ هفتهٔ قبل — با ترتیبِ درست.
        // برچسبِ هر نقطه = نامِ روزِ هفتهٔ همان تاریخِ واقعی (نه نام‌های ثابت)، تا محور با داده
        // هماهنگ باشد. داده به‌ترتیبِ i=6..0 چیده می‌شود، پس «امروز» در آخرین اندیس (سمتِ راستِ
        // نمودار، مطابقِ تقویمِ افغانستان/راست‌به‌چپ) و «۶ روز قبل» در نخستین اندیس (سمتِ چپ) قرار می‌گیرد.
        // نگاشتِ getDay(): 0=یک‌شنبه ... 6=شنبه
        const _wd = ['یک‌شنبه','دوشنبه','سه‌شنبه','چهارشنبه','پنج‌شنبه','جمعه','شنبه'];
        labels = [];
        for (let i = 6; i >= 0; i--) {
            const dCur = new PersianDate().subtract('days', i);
            const dPrev = new PersianDate().subtract('days', i + 7);
            let _dayName = '';
            try { _dayName = _wd[dCur.toDate().getDay()] || ''; } catch (e) { _dayName = ''; }
            labels.push(_dayName);
            currentData.push(getSalesForDate(dCur.format('YYYY/MM/DD')));
            prevData.push(getSalesForDate(dPrev.format('YYYY/MM/DD')));
        }
    } else if (mode === 'month') {
        // ۱۲ ماه سال جاری و سال قبلی
        const pNow = new PersianDate();
        const curYear = parseInt(pNow.format('YYYY'));
const monthNames = ['حمل','ثور','جوزا','سرطان','اسد','سنبله','میزان','عقرب','قوس','جدی','دلو','حوت'];    
    labels = monthNames;
        for (let m = 1; m <= 12; m++) {
            const mPad = String(m).padStart(2,'0');
            currentData.push(getSalesForMonthStr(curYear + '/' + mPad));
            prevData.push(getSalesForMonthStr((curYear-1) + '/' + mPad));
        }
    } else if (mode === 'year') {
        // ۵ سال اخیر
        const curYear = parseInt(new PersianDate().format('YYYY'));
        for (let i = 4; i >= 0; i--) {
            labels.push(String(curYear - i));
            currentData.push(getSalesForYearStr(String(curYear - i)));
            prevData.push(getSalesForYearStr(String(curYear - i - 1)));
        }
    }

    // مقادیر امروز/دیروز برای footer — کاملاً پویا (ارزِ پایه + اولین ارزِ غیرپایه)
    const todayStr = new PersianDate().format('YYYY/MM/DD');
    const yesterdayStr = new PersianDate().subtract('days',1).format('YYYY/MM/DD');
    var _wkBase = _baseCur();
    // یافتنِ اولین ارزِ غیرپایه که امروز یا دیروز فروش داشته
    var _wkCol2 = null;
    try {
        var _wkCurs = (typeof CurrencySystem !== 'undefined' && CurrencySystem.getCurrencies) ? CurrencySystem.getCurrencies() : [];
        for (var _wi = 0; _wi < _wkCurs.length; _wi++) {
            var _wc = _wkCurs[_wi] && _wkCurs[_wi].code;
            if (!_wc || _wc === _wkBase) continue;
            if ((getSalesForDate(todayStr, _wc) || 0) || (getSalesForDate(yesterdayStr, _wc) || 0)) { _wkCol2 = _wc; break; }
        }
    } catch (e) {}
    const todaySaleAFN     = getSalesForDate(todayStr, _wkBase);
    const yesterdaySaleAFN = getSalesForDate(yesterdayStr, _wkBase);
    const todaySaleUSD     = _wkCol2 ? getSalesForDate(todayStr, _wkCol2) : 0;
    const yesterdaySaleUSD = _wkCol2 ? getSalesForDate(yesterdayStr, _wkCol2) : 0;
    const _baseLbl = (typeof getCurrencyLabel === 'function') ? getCurrencyLabel(_wkBase) : 'افغانی';
    const _col2Lbl = _wkCol2 ? ((typeof getCurrencyLabel === 'function') ? getCurrencyLabel(_wkCol2) : _wkCol2) : '';
    const _numFmt = v => new Intl.NumberFormat((typeof getNumberSystem === 'function' && getNumberSystem() === 'en') ? 'en-US' : 'fa-IR').format(Math.round(v));
    const fmtAFN = v => _numFmt(v) + ' ' + _baseLbl;
    const fmtUSD = v => _numFmt(v) + (_col2Lbl ? (' ' + _col2Lbl) : '');
    const el = id => document.getElementById(id);
    if (el('wk-today-val'))         el('wk-today-val').textContent         = fmtAFN(todaySaleAFN);
    if (el('wk-yesterday-val'))     el('wk-yesterday-val').textContent     = fmtAFN(yesterdaySaleAFN);
    // خانهٔ دوم فقط اگر ارزِ غیرپایه‌ای فروش داشته باشد نمایش داده می‌شود
    if (el('wk-today-val-usd'))     el('wk-today-val-usd').textContent     = _wkCol2 ? fmtUSD(todaySaleUSD) : '';
    if (el('wk-yesterday-val-usd')) el('wk-yesterday-val-usd').textContent = _wkCol2 ? fmtUSD(yesterdaySaleUSD) : '';

    window._advStatsChart = new Chart(canvas.getContext('2d'), {
        type: 'line',
        data: {
            labels: labels,
            datasets: [
                {
                    label: mode === 'year' ? 'سال جاری' : (mode === 'month' ? 'سال جاری' : 'هفته جاری'),
                    data: currentData,
                    borderColor: '#FF7F50',
                    backgroundColor: 'transparent',
                    borderWidth: 2,
                    pointBackgroundColor: '#FF7F50',
                    pointRadius: 4,
                    pointHoverRadius: 6,
                    tension: 0.3,
                    fill: false
                },
                {
                    label: mode === 'year' ? 'سال قبلی' : (mode === 'month' ? 'سال قبلی' : 'هفته قبلی'),
                    data: prevData,
                    borderColor: '#94a3b8',
                    backgroundColor: 'transparent',
                    borderWidth: 2,
                    pointBackgroundColor: '#94a3b8',
                    pointRadius: 4,
                    pointHoverRadius: 6,
                    tension: 0.3,
                    borderDash: [4, 3],
                    fill: false
                }
            ]
        },
        options: {
            responsive: true,
            maintainAspectRatio: false,
            interaction: { mode: 'index', intersect: false },
            onClick: function (evt, elements, chart) {
                // با کلیک روی یک نقطه، کارتِ خلاصهٔ همان بازه باز می‌شود
                try {
                    var pts = chart.getElementsAtEventForMode(evt, 'index', { intersect: false }, true);
                    if (pts && pts.length) {
                        var idx = pts[0].index;
                        if (typeof _openDaySummaryCard === 'function') {
                            _openDaySummaryCard(window._advChartMode || 'week', idx);
                        }
                    }
                } catch (e) { console.warn('day summary open failed:', e); }
            },
            plugins: {
                legend: { display: false },
                tooltip: {
                    rtl: true,
                    backgroundColor: 'rgba(30,41,59,0.92)',
                    titleFont: { family: 'Vazirmatn', size: 12 },
                    bodyFont: { family: 'Vazirmatn', size: 11 },
                    padding: 10,
                    callbacks: {
                        label: ctx => ' ' + ctx.dataset.label + ': ' + (typeof formatCurrencyAFN === 'function' ? formatCurrencyAFN(ctx.raw) : (typeof formatNumber === 'function' ? formatNumber(ctx.raw) : ctx.raw))
                    }
                }
            },
            scales: {
                x: {
                    ticks: { font: { family: 'Vazirmatn', size: 10 }, color: '#94a3b8' },
                    grid: { color: 'rgba(148,163,184,0.10)', drawBorder: false }
                },
                y: {
                    beginAtZero: true,
                    ticks: {
                        font: { family: 'Vazirmatn', size: 10 },
                        color: '#94a3b8',
                        callback: v => new Intl.NumberFormat((typeof getNumberSystem === 'function' && getNumberSystem() === 'en') ? 'en-US' : 'fa-IR').format(v)
                    },
                    grid: { color: 'rgba(148,163,184,0.12)', drawBorder: false }
                }
            }
        }
    });
}

function initAdvStatsChart() {
    renderWeeklySalesChart(window._advChartMode || 'week');
}

// ════════════════════════════════════════════════════════════════════════
//  کارتِ «خلاصهٔ معاملاتِ روز» — با کلیک روی نقاطِ نمودارِ داشبورد
//  ──────────────────────────────────────────────────────────────────────
//  وقتی کاربر روی یک نقطه (یک روز/ماه/سال) از نمودارِ فروشِ داشبورد کلیک می‌کند،
//  یک کارتِ شناور با ارقامِ دقیقِ همان بازه نمایش داده می‌شود: فروش، خرید، دریافتی،
//  پرداختی، برگشت از فروش، برگشت ازخرید، مصارفات و فایدهٔ همان بازه.
//  آیکنِ تعویض، ارقام را بین «افغانی» و «دالر» جابه‌جا می‌کند. با کلیک روی هر
//  جای دیگرِ صفحه کارت بسته می‌شود.
//
//  تمام محاسبات از همان توابع/فرمول‌های موجودِ برنامه استفاده می‌کنند
//  (computeSaleProfit + computeDeficitProfitAdjustment برای فاید، همان قواعدِ
//  loadDashboard برای فروش/خرید/دریافت/پرداخت/مصارف، و همان قاعدهٔ برگشت‌ها) تا
//  ارقام دقیقاً با بقیهٔ برنامه هماهنگ و بدونِ نقض باشند.
// ════════════════════════════════════════════════════════════════════════

// وضعیتِ ارزِ نمایشِ کارت (بین بازکردن‌ها حفظ می‌شود)
// ارزِ فعالِ کارتِ خلاصهٔ معاملات — پیش‌فرض: ارزِ پایهٔ سیستم (نه AFN ثابت)
var _daySummaryCurrency = (function () {
    try {
        if (typeof CurrencySystem !== 'undefined' && CurrencySystem.getBaseCode) return CurrencySystem.getBaseCode();
    } catch (e) {}
    return 'AFN';
})();
var _daySummaryLastKey = null; // کلیدِ بازهٔ انتخاب‌شده (برای بازمحاسبه هنگام تعویضِ ارز)

// محاسبهٔ برچسبِ عنوانِ کارت و مجموعهٔ تاریخ‌هایی که در بازهٔ کلیک‌شده می‌گنجند.
// خروجی: { title, matches(dateStr) } — matches تعیین می‌کند یک تراکنش در بازه هست یا نه.
function _daySummaryRangeForIndex(mode, index) {
    if (mode === 'week') {
        // اندیس ۰..۶ متناظرِ ۶..۰ روز قبل (همان ترتیبِ renderWeeklySalesChart)
        var i = 6 - index;
        var d = new PersianDate().subtract('days', i);
        var ds = d.format('YYYY/MM/DD');
        // نامِ روزِ هفته از روی تاریخِ واقعی — نگاشتِ getDay(): 0=یک‌شنبه ... 6=شنبه
        var _wd = ['یک‌شنبه','دوشنبه','سه‌شنبه','چهارشنبه','پنج‌شنبه','جمعه','شنبه'];
        var _dayName = '';
        try { _dayName = _wd[d.toDate().getDay()] || ''; } catch (e) { _dayName = ''; }
        return { title: 'خلاصه معاملات ' + _dayName, key: 'w:' + ds,
                 matches: function (s) { return (s || '').split(' ')[0] === ds; } };
    } else if (mode === 'month') {
        // اندیس ۰..۱۱ متناظرِ ماه‌های ۱..۱۲ سالِ جاری
        var curYear = parseInt(new PersianDate().format('YYYY'));
        var mPad = String(index + 1).padStart(2, '0');
        var prefix = curYear + '/' + mPad;
        var monthNames = ['حمل','ثور','جوزا','سرطان','اسد','سنبله','میزان','عقرب','قوس','جدی','دلو','حوت'];
        return { title: 'خلاصه معاملات ' + (monthNames[index] || ''), key: 'm:' + prefix,
                 matches: function (s) { return (s || '').split(' ')[0].startsWith(prefix); } };
    } else { // year
        var cy = parseInt(new PersianDate().format('YYYY'));
        var yr = String(cy - (4 - index));
        return { title: 'خلاصه معاملات سال ' + yr, key: 'y:' + yr,
                 matches: function (s) { return (s || '').split(' ')[0].startsWith(yr + '/'); } };
    }
}

// محاسبهٔ ارقامِ یک بازه در هر دو ارز. خروجی: {AFN:{...}, USD:{...}}
function _computeDaySummary(matches) {
    var txs = (db.getTransactions ? db.getTransactions() : []) || [];
    var exps = (db.getExpenses ? db.getExpenses() : []) || [];
    var prods = ((db.getAllProducts && db.getAllProducts()) || (db.getProducts && db.getProducts())) || [];

    function _emptyBucket() {
        return { sales:0, purchases:0, received:0, paid:0, retSale:0, retPurchase:0, expenses:0, profit:0, cashIn:0, cashOut:0, shipping:0, recvFromBills:0, paidFromBills:0, totalIn:0, totalOut:0 };
    }
    var out = {};
    function _bucket(cur) {
        cur = cur || _baseCur();
        if (!out[cur]) out[cur] = _emptyBucket();
        return out[cur];
    }
    // AFN/USD همیشه حاضر باشند (سازگاریِ کاملِ نمایش) + هر ارزی که در سیستم تعریف شده
    _bucket('AFN'); _bucket('USD');
    try {
        if (typeof CurrencySystem !== 'undefined' && CurrencySystem.getCurrencies) {
            CurrencySystem.getCurrencies().forEach(function (c) { if (c && c.code) _bucket(c.code); });
        }
    } catch (e) {}

    var salesInRange = [];
    var grossMap = {}, discMap = {};
    function _add(map, k, v) { map[k] = (map[k] || 0) + v; }

    txs.forEach(function (t) {
        var d = (t.date || t.createdAt || '');
        if (!matches(d)) return;
        var cur = t.currency || _baseCur();            // ← ارزِ واقعیِ تراکنش (بدونِ نگاشت به AFN)
        var b = _bucket(cur);
        var total = parseFloat(t.totalAmount || t.amount || 0) || 0;
        if (t.type === 'فروش') {
            b.sales += total;
            salesInRange.push(t);
            var disc = parseFloat(t.totalDiscount || 0) || 0;
            var gross = computeSaleProfit(t, prods) + disc;
            _add(grossMap, cur, gross); _add(discMap, cur, disc);
            // دریافتیِ نقدیِ داخلِ بلِ فروش (پویا برای هر ارز)
            var _rcv = (t.cashAmounts && t.cashAmounts[cur] != null)
                ? (parseFloat(t.cashAmounts[cur]) || 0)
                : (cur === 'USD' ? (parseFloat(t.cashUsd||0)||0) : (cur === 'AFN' ? (parseFloat(t.cashAfn||0)||0) : (parseFloat(t.cashForeign||0)||0)));
            if (_rcv > 0) b.recvFromBills += _rcv;
        } else if (t.type === 'خرید') {
            b.purchases += total;
            // پرداختیِ نقدیِ داخلِ بلِ خرید (پویا برای هر ارز)
            var _pd = (t.paidAmounts && t.paidAmounts[cur] != null)
                ? (parseFloat(t.paidAmounts[cur]) || 0)
                : (cur === 'USD' ? (parseFloat(t.paidUsd||t.cashUsd||0)||0) : (cur === 'AFN' ? (parseFloat(t.paidAfn||t.cashAfn||0)||0) : (parseFloat(t.paidForeign||0)||0)));
            if (_pd > 0) b.paidFromBills += _pd;
        } else if (t.type === 'دریافت') {
            b.received += total;
        } else if (t.type === 'پرداخت') {
            b.paid += total;
        } else if (t.type === 'برگشت') {
            if (t.returnType === 'فروش') b.retSale += total;
            else if (t.returnType === 'خرید') b.retPurchase += total;
        }
    });

    // تعدیلِ مفادِ فروشِ کسری — تابعِ مرجعِ برنامه (فعلاً AFN/USD)
    var adj = { afn: 0, usd: 0 };
    try { if (typeof computeDeficitProfitAdjustment === 'function') adj = computeDeficitProfitAdjustment(salesInRange, prods) || adj; } catch (e) {}
    _add(grossMap, 'AFN', (adj.afn || 0)); _add(grossMap, 'USD', (adj.usd || 0));

    // مصارف (پویا برای هر ارز)
    exps.forEach(function (e) {
        var d = (e.date || e.createdAt || '');
        if (!matches(d)) return;
        var amt = parseFloat(e.amount || 0) || 0;
        var ec = e.currency || _baseCur();
        _bucket(ec).expenses += amt;
    });

    // ===== عملیاتِ «اضافه/برداشتِ مبلغ» و «هزینهٔ حمل» از لاگِ حساب‌ها (پویا) =====
    var _cbLogs = [];
    try { _cbLogs = JSON.parse(localStorage.getItem('cashboxTransactions') || '[]'); } catch (e) { _cbLogs = []; }
    if (Array.isArray(_cbLogs)) {
        _cbLogs.forEach(function (log) {
            if (!log) return;
            var d = (log.datetime || log.date || log.createdAt || '');
            if (!matches(d)) return;
            var amt = parseFloat(log.amount || 0) || 0;
            if (!(amt > 0)) return;
            var cur = log.currency || _baseCur();
            var b = _bucket(cur);
            var _isInitial = (typeof log.notes === 'string' && log.notes.indexOf('موجودی اولیه صندوق') !== -1);
            if (log.type === 'deposit_external' && !_isInitial) b.cashIn += amt;
            else if (log.type === 'withdraw_external') b.cashOut += amt;
            else if (log.type === 'shipping_charge') b.shipping += amt;
        });
    }

    // نهایی‌سازیِ هر سطل — فایده، دریافتی/پرداختیِ نمایشی و مجموعِ آمد/رفت (برای هر ارز)
    Object.keys(out).forEach(function (cur) {
        var b = out[cur];
        // فایده خالص = gross − disc − expenses (همان فرمولِ گزارشِ سود/کارتِ داشبورد)
        b.profit = (grossMap[cur] || 0) - (discMap[cur] || 0) - (b.expenses || 0);
        b.receivedDisplay = b.received + b.recvFromBills;
        b.paidDisplay = b.paid + b.paidFromBills;
        b.totalIn  = b.receivedDisplay + b.cashIn;
        b.totalOut = b.paidDisplay + b.expenses + b.cashOut + b.shipping;
    });

    return out;
}

// فرمتِ عدد مطابقِ سیستمِ اعدادِ برنامه (بدون واحد، واحد جدا نمایش داده می‌شود)
function _daySummaryFmt(v) {
    var sys = (typeof getNumberSystem === 'function') ? getNumberSystem() : 'fa';
    return new Intl.NumberFormat(sys === 'en' ? 'en-US' : 'fa-IR').format(Math.round(parseFloat(v) || 0));
}

// بستنِ کارت و پاک‌سازیِ شنودگرها
function _closeDaySummaryCard() {
    var overlay = document.getElementById('day-summary-overlay');
    if (overlay && overlay.parentNode) overlay.parentNode.removeChild(overlay);
    document.removeEventListener('keydown', _daySummaryEscHandler);
}
function _daySummaryEscHandler(e) { if (e.key === 'Escape') _closeDaySummaryCard(); }

// رندرِ محتویاتِ کارت با ارزِ جاری
function _renderDaySummaryBody(title) {
    var range = _daySummaryLastKey;
    if (!range) return;
    var data = _computeDaySummary(range.matches);
    var cur = _daySummaryCurrency;
    var d = data[cur] || data['AFN'] || {};
    var unit = (function () {
        try {
            if (typeof CurrencySystem !== 'undefined' && CurrencySystem.getCurrency) {
                var c = CurrencySystem.getCurrency(cur);
                if (c) return c.nameLocal || c.code;
            }
        } catch (e) {}
        return getCurrencyLabel(cur);
    })();

    var rows = [
        { label: 'فروش',          val: d.sales,       icon: 'fa-cart-plus',        color: '#22c55e' },
        { label: 'خرید',          val: d.purchases,   icon: 'fa-shopping-basket',  color: '#3b82f6' },
        { label: 'دریافتی',       val: (d.receivedDisplay != null ? d.receivedDisplay : d.received), icon: 'fa-hand-holding-usd', color: '#10b981' },
        { label: 'پرداختی',       val: (d.paidDisplay != null ? d.paidDisplay : d.paid),             icon: 'fa-money-check-alt',  color: '#6366f1' },
        { label: 'برگشت از فروش', val: d.retSale,     icon: 'fa-rotate-left',      color: '#f59e0b' },
        { label: 'فروش خالص',     val: (d.sales - d.retSale), icon: 'fa-equals',    color: '#22c55e' },
        { label: 'برگشت ازخرید',  val: d.retPurchase, icon: 'fa-rotate-right',     color: '#ef4444' },
        { label: 'مصارفات',       val: d.expenses,    icon: 'fa-receipt',          color: '#ec4899' },
        { label: 'فاید امروز',    val: d.profit,      icon: 'fa-chart-simple',     color: (d.profit >= 0 ? '#22c55e' : '#ef4444') },
        { label: 'مجموعه آمد',    val: d.totalIn,     icon: 'fa-arrow-down',       color: '#16a34a', sep: true },
        { label: 'مجموعه رفت',    val: d.totalOut,    icon: 'fa-arrow-up',         color: '#dc2626' }
    ];

    var rowsHtml = rows.map(function (r) {
        // چیدمانِ راست‌به‌چپ: ابتدا آیکن، سپس نام، و در سمتِ چپ رقم
        return '<div class="dsc-row' + (r.sep ? ' dsc-row-sep' : '') + '">' +
                    '<span class="dsc-label">' +
                        '<i class="fas ' + r.icon + '" style="color:' + r.color + '"></i>' +
                        '<span class="dsc-name">' + r.label + '</span>' +
                    '</span>' +
                    '<span class="dsc-val">' + _daySummaryFmt(r.val) + '</span>' +
                '</div>';
    }).join('');

    return '<div class="dsc-head">' +
                '<span class="dsc-title-group">' +
                    '<i class="fas fa-chart-column dsc-title-icon"></i>' +
                    '<span class="dsc-title">' + title + '</span>' +
                '</span>' +
                '<button type="button" class="dsc-toggle" id="dsc-currency-toggle" title="تغییر ارز (افغانی/دالر)">' +
                    '<i class="fas fa-arrows-rotate"></i>' +
                '</button>' +
            '</div>' +
            '<div class="dsc-unit-badge">' + unit + '</div>' +
            rowsHtml;
}

// بازکردنِ کارت برای بازهٔ کلیک‌شده
function _openDaySummaryCard(mode, index) {
    _closeDaySummaryCard(); // اگر کارتِ قبلی باز است بسته شود
    var range = _daySummaryRangeForIndex(mode, index);
    _daySummaryLastKey = range;

    var overlay = document.createElement('div');
    overlay.id = 'day-summary-overlay';
    overlay.className = 'day-summary-overlay';

    var card = document.createElement('div');
    card.id = 'day-summary-card';
    card.className = 'day-summary-card';
    card.innerHTML = _renderDaySummaryBody(range.title);

    overlay.appendChild(card);
    document.body.appendChild(overlay);

    // کلیک روی هر جای بیرونِ کارت → بستن
    overlay.addEventListener('click', function (e) {
        if (e.target === overlay) _closeDaySummaryCard();
    });
    // کلیکِ داخلِ کارت نباید بسته کند
    card.addEventListener('click', function (e) { e.stopPropagation(); });

    // فهرستِ ارزهای قابلِ‌نمایش در کارت: AFN و USD همیشه + هر ارزی که فعالیتِ غیرصفر دارد
    function _daySummaryCycleCurrencies() {
        // ══ همهٔ ارزهای تعریف‌شده در سیستم ══
        //  ترتیب: ارزِ پایه اول، سپس بقیهٔ ارزها به ترتیبِ ثبت. ارزی که در سیستم
        //  تعریف شده اما امروز معامله‌ای نداشته هم در چرخه می‌آید و صفر نشان می‌دهد
        //  (تا کاربر بداند آن ارز فعالیتی نداشته، نه اینکه اصلاً وجود ندارد).
        var base = 'AFN';
        try {
            if (typeof CurrencySystem !== 'undefined' && CurrencySystem.getBaseCode) base = CurrencySystem.getBaseCode();
        } catch (e) {}
        var codes = [base];
        try {
            if (typeof CurrencySystem !== 'undefined' && CurrencySystem.getCurrencies) {
                CurrencySystem.getCurrencies().forEach(function (c) {
                    if (c && c.code && codes.indexOf(c.code) === -1) codes.push(c.code);
                });
            }
        } catch (e) {}
        // ارزهای قدیمیِ داخلِ داده که شاید در فهرستِ ارزها ثبت نشده باشند
        try {
            var data = _computeDaySummary(range.matches);
            Object.keys(data).forEach(function (code) {
                if (codes.indexOf(code) === -1) codes.push(code);
            });
        } catch (e) {}
        if (codes.indexOf('AFN') === -1) codes.push('AFN');
        if (codes.indexOf('USD') === -1) codes.push('USD');
        return codes;
    }
    // اتصالِ دکمهٔ تعویضِ ارز (پس از هر بازنویسیِ محتوا دوباره متصل می‌شود)
    function _bindDaySummaryToggle() {
        var toggle = card.querySelector('#dsc-currency-toggle');
        if (!toggle) return;
        toggle.addEventListener('click', function (e) {
            e.stopPropagation();
            var codes = _daySummaryCycleCurrencies();
            var i = codes.indexOf(_daySummaryCurrency);
            _daySummaryCurrency = codes[(i + 1) % codes.length] || _baseCur();
            card.innerHTML = _renderDaySummaryBody(range.title);
            _bindDaySummaryToggle();
        });
    }
    _bindDaySummaryToggle();

    document.addEventListener('keydown', _daySummaryEscHandler);
}

if (typeof window !== 'undefined') {
    window._openDaySummaryCard = _openDaySummaryCard;
    window._closeDaySummaryCard = _closeDaySummaryCard;
}



// تابع فرمت کردن اعداد به فارسی
function formatNumber(number) {
    if (number === undefined || number === null) {
        return (typeof getNumberSystem === 'function' && getNumberSystem() === 'en') ? '0' : '۰';
    }
    const num = parseFloat(number);
    if (isNaN(num)) {
        return (typeof getNumberSystem === 'function' && getNumberSystem() === 'en') ? '0' : '۰';
    }
    var sys = (typeof getNumberSystem === 'function') ? getNumberSystem() : 'fa';
    if (sys === 'en') {
        return new Intl.NumberFormat('en-US').format(num);
    }
    return new Intl.NumberFormat('fa-IR').format(num);
}
// توابع مدیریت اشخاص
// محاسبهٔ دقیق مانده دو-ارزی یک شخص (همان منطق صفحهٔ معاملات شخص)
// ═══════════════════════ ابزارِ مرکزیِ چند-ارزی ═══════════════════════
// برچسبِ هر ارز از سیستمِ مرکزی (نماد → نام محلی → کد). منبعِ واحدِ حقیقت.
function _curLabelGlobal(code) {
    try {
        if (typeof CurrencySystem !== 'undefined' && CurrencySystem.getCurrency) {
            var c = CurrencySystem.getCurrency(code);
            if (c) return c.symbol || c.nameLocal || code;
        }
    } catch (e) {}
    return code || _baseCur();
}
// نمادِ هر ارز برای صورتحساب/چاپ (AFN→؋ ، USD→$ ، بقیه از سیستمِ مرکزی یا کد)
function _curSymGlobal(code) {
    if (code === 'USD') return '$';
    if (code === 'AFN') return '؋';
    try {
        if (typeof CurrencySystem !== 'undefined' && CurrencySystem.getCurrency) {
            var c = CurrencySystem.getCurrency(code);
            if (c && c.symbol) return c.symbol;
        }
    } catch (e) {}
    return code || '؋';
}
// الحاقِ ارزهای سوم‌به‌بعدِ غیرصفر به یک رشتهٔ نمایشِ موجود (AFN/USD از قبل در رشته هستند)
function _appendForeignBalances(baseStr, map, fmtFn) {
    if (!map || typeof map !== 'object') return baseStr;
    var f = fmtFn || function (v) { return Math.abs(parseFloat(v) || 0); };
    var s = baseStr;
    Object.keys(map).forEach(function (code) {
        if (code === 'AFN' || code === 'USD') return;
        var v = parseFloat(map[code]) || 0;
        if (!v) return;
        s += '-' + f(v) + '(' + _curLabelGlobal(code) + ')';
    });
    return s;
}
// ═══════════ ردیف‌های پویای قیمت در فرم ثبت جنس (برای هر ارزِ تعریف‌شده) ═══════════
// فیلدهای ثابتِ HTML به «ارزِ پایهٔ فعلی» اختصاص دارند (هر چه باشد). هر ارزِ دیگری که
// کاربر در سیستم تعریف کند — شاملِ USD اگر پایه نباشد — اینجا به‌صورت ردیفِ پویا
// ظاهر می‌شود. هیچ ارزی (AFN/USD) دیگر «ویژه» نیست؛ فقط ارزِ پایه فیلدِ ثابت دارد.

// ارزهایی که فیلدِ ثابت ندارند (یعنی هر ارزِ غیرِ پایه)
function _extraCurrencyList() {
    try {
        if (typeof CurrencySystem === 'undefined' || !CurrencySystem.getCurrencies) return [];
        var _base = _baseCur();
        return CurrencySystem.getCurrencies().filter(function (c) {
            return c && c.code && c.code !== _base;
        });
    } catch (e) { return []; }
}

// ساختِ یک ردیفِ قیمت برای یک ارز (خرید یا فروش، اصلی + فرعی)
function _buildCurrencyPriceRow(code, label, kind) {
    var isSale = (kind === 'sale');
    var idMain = 'product-' + (isSale ? 'sale' : 'purchase') + '-price-x-' + code;
    var idSec  = 'product-secondary-' + (isSale ? 'sale' : 'purchase') + '-price-x-' + code;
    var ph = (isSale ? 'قیمت فروش(' : 'قیمت خرید(') + label + ')';
    var wrap = document.createElement('div');
    wrap.className = 'mc-price-row';
    wrap.dataset.curCode = code;
    wrap.dataset.kind = kind;
    wrap.style.cssText = 'display:contents;';
    wrap.innerHTML =
        '<div class="bill-field bill-field-icononly product-main-cell mc-price-cell">' +
            '<i class="fas fa-coins bill-field-icon"></i>' +
            '<input type="number" id="' + idMain + '" class="mc-price-input" data-cur="' + code + '" data-kind="' + kind + '" data-unit="primary" step="0.01" placeholder="' + ph + '">' +
            '<button type="button" class="mc-price-del" title="حذف ارز ' + label + '" onclick="_removeCurrencyPriceRow(\'' + code + '\')"><i class="fas fa-times"></i></button>' +
        '</div>' +
        '<div class="bill-field bill-field-icononly product-sec-cell mc-price-cell">' +
            '<i class="fas fa-coins bill-field-icon"></i>' +
            '<input type="number" id="' + idSec + '" class="mc-price-input" data-cur="' + code + '" data-kind="' + kind + '" data-unit="secondary" step="0.01" placeholder="' + ph + '">' +
        '</div>';
    return wrap;
}

// رندرِ همهٔ ردیف‌های ارزهای اضافی داخل فرم جنس
function _renderExtraCurrencyPriceRows(activeCodes) {
    var anchorSale = document.getElementById('product-sale-price-usd');
    if (!anchorSale) return;
    var grid = anchorSale.closest('.product-main-cell');
    grid = grid ? grid.parentNode : null;
    if (!grid) return;

    // پاک‌سازیِ ردیف‌های قبلی
    grid.querySelectorAll('.mc-price-row').forEach(function (n) { n.remove(); });
    _injectMcPriceStyles();

    var list = _extraCurrencyList();
    var active = activeCodes || _mcActiveCurrencyCodes;
    list.forEach(function (c) {
        if (active.indexOf(c.code) === -1) return;
        var lbl = c.symbol || c.nameLocal || c.code;
        grid.appendChild(_buildCurrencyPriceRow(c.code, lbl, 'purchase'));
        grid.appendChild(_buildCurrencyPriceRow(c.code, lbl, 'sale'));
    });
    _renderAddCurrencyButton(grid);
}

// دکمهٔ «افزودن ارز» (هم‌سبک با افزودن کتگوری)
function _renderAddCurrencyButton(grid) {
    var old = grid.querySelector('.mc-add-cur-wrap');
    if (old) old.remove();
    var remaining = _extraCurrencyList().filter(function (c) {
        return _mcActiveCurrencyCodes.indexOf(c.code) === -1;
    });
    if (!remaining.length) return;
    var wrap = document.createElement('div');
    wrap.className = 'mc-add-cur-wrap';
    wrap.style.cssText = 'grid-column:1 / -1;display:flex;gap:8px;align-items:center;flex-wrap:wrap;margin-top:4px;';
    var sel = '<select id="mc-add-cur-select" class="mc-add-cur-select">' +
        remaining.map(function (c) {
            return '<option value="' + c.code + '">' + c.code + ' - ' + (c.nameLocal || c.code) + '</option>';
        }).join('') + '</select>';
    wrap.innerHTML = sel +
        '<button type="button" class="mc-add-cur-btn" onclick="_addCurrencyPriceRow()">' +
        '<i class="fas fa-plus"></i> افزودن قیمت به ارز دیگر</button>';
    grid.appendChild(wrap);
}

// ارزهای فعالِ فعلی در فرم (کدهایی که ردیف دارند)
var _mcActiveCurrencyCodes = [];

function _addCurrencyPriceRow() {
    var sel = document.getElementById('mc-add-cur-select');
    if (!sel || !sel.value) return;
    if (_mcActiveCurrencyCodes.indexOf(sel.value) === -1) _mcActiveCurrencyCodes.push(sel.value);
    _renderExtraCurrencyPriceRows();
}
function _removeCurrencyPriceRow(code) {
    var i = _mcActiveCurrencyCodes.indexOf(code);
    if (i >= 0) _mcActiveCurrencyCodes.splice(i, 1);
    _renderExtraCurrencyPriceRows();
}
window._addCurrencyPriceRow = _addCurrencyPriceRow;
window._removeCurrencyPriceRow = _removeCurrencyPriceRow;

// جمع‌آوریِ مقادیرِ ردیف‌های ارزهای اضافی هنگام ذخیره
function _collectExtraCurrencyPrices() {
    var out = { purchase: {}, sale: {}, secPurchase: {}, secSale: {} };
    document.querySelectorAll('.mc-price-input').forEach(function (el) {
        var code = el.dataset.cur, kind = el.dataset.kind, unit = el.dataset.unit;
        if (!code) return;
        var v = el.value === '' ? 0 : (parseFloat(el.value) || 0);
        if (unit === 'secondary') {
            if (kind === 'sale') out.secSale[code] = v; else out.secPurchase[code] = v;
        } else {
            if (kind === 'sale') out.sale[code] = v; else out.purchase[code] = v;
        }
    });
    return out;
}

// پرکردنِ ردیف‌ها هنگامِ ویرایشِ یک جنس (ارزهایی که قیمت دارند خودکار نمایش داده می‌شوند)
function _fillExtraCurrencyPrices(product) {
    _mcActiveCurrencyCodes = [];
    if (product) {
        _extraCurrencyList().forEach(function (c) {
            var has = false;
            ['purchasePrices', 'salePrices', 'secondaryPurchasePrices', 'secondarySalePrices'].forEach(function (k) {
                var m = product[k];
                if (m && typeof m === 'object' && m[c.code] != null && parseFloat(m[c.code])) has = true;
            });
            if (has) _mcActiveCurrencyCodes.push(c.code);
        });
    }
    _renderExtraCurrencyPriceRows();
    if (!product) return;
    var pairs = [
        ['purchasePrices', 'purchase', 'primary'],
        ['salePrices', 'sale', 'primary'],
        ['secondaryPurchasePrices', 'purchase', 'secondary'],
        ['secondarySalePrices', 'sale', 'secondary']
    ];
    pairs.forEach(function (p) {
        var map = product[p[0]];
        if (!map || typeof map !== 'object') return;
        Object.keys(map).forEach(function (code) {
            if (code === _baseCur()) return;  // ارزِ پایه فیلدِ ثابتِ خود را دارد
            var id = (p[2] === 'secondary' ? 'product-secondary-' : 'product-') +
                     (p[1] === 'sale' ? 'sale' : 'purchase') + '-price-x-' + code;
            var el = document.getElementById(id);
            if (el) { var v = parseFloat(map[code]); el.value = (isNaN(v) || v === 0) ? '' : v; }
        });
    });
}
window._fillExtraCurrencyPrices = _fillExtraCurrencyPrices;

function _injectMcPriceStyles() {
    if (document.getElementById('mc-price-styles')) return;
    var st = document.createElement('style');
    st.id = 'mc-price-styles';
    st.textContent =
        '.mc-price-cell { position:relative; }' +
        '.mc-price-del { position:absolute; inset-inline-end:6px; top:50%; transform:translateY(-50%);' +
        ' background:transparent; border:none; color:#ef4444; cursor:pointer; font-size:12px; padding:2px 4px; }' +
        '.mc-price-del:hover { color:#b91c1c; }' +
        '.mc-add-cur-select { padding:8px 10px; border:1px solid #d1d5db; border-radius:8px;' +
        ' font-family:inherit; font-size:.85rem; background:#fff; }' +
        '.mc-add-cur-btn { background:#1e3a5f; color:#fff; border:none; padding:8px 14px; border-radius:8px;' +
        ' font-family:inherit; font-size:.85rem; font-weight:700; cursor:pointer; display:inline-flex;' +
        ' align-items:center; gap:6px; }' +
        '.mc-add-cur-btn:hover { background:#2c4f7c; }' +
        'body.dark-mode .mc-add-cur-select { background:#0f172a; color:#e2e8f0; border-color:#334155; }';
    document.head.appendChild(st);
}

// ═════════════ حل‌کنندهٔ مرکزیِ قیمتِ چند-ارزی (پیشنهاددهنده، نه اجبارکننده) ═════════════
// منطق: اگر برای همان ارز قیمتِ صریح ثبت شده باشد → همان استفاده می‌شود.
// در غیر این صورت → قیمتِ ارزِ پایه با «نرخِ روز» تبدیل و به‌عنوان پیشنهاد برگردانده می‌شود.
//   خروجی: { price, source:'explicit'|'converted'|'none', rate, fromCurrency }
//   مثال سناریو: لپ‌تاپ ۷۰٬۰۰۰ AFN و نرخ ۱$=۷۰ ⇒ فروش به USD پیشنهاد ۱۰۰۰ می‌دهد.
function _resolveProductPrice(product, currency, kind, unitType) {
    var res = { price: 0, source: 'none', rate: null, fromCurrency: null };
    if (!product) return res;
    var code = currency || _baseCur();
    var isSale = (kind === 'sale');
    var isSec = (unitType === 'secondary');

    function _read(cur) {
        try {
            if (typeof db === 'undefined') return null;
            var v;
            if (isSec) {
                if (typeof db.getSecondaryPrice === 'function') v = db.getSecondaryPrice(product, cur, isSale ? 'sale' : 'purchase');
            } else if (isSale) {
                v = (typeof db.getSalePrice === 'function') ? db.getSalePrice(product, cur) : null;
            } else {
                v = (typeof db.getPurchasePrice === 'function') ? db.getPurchasePrice(product, cur) : null;
            }
            v = parseFloat(v);
            return (isNaN(v) || v <= 0) ? null : v;
        } catch (e) { return null; }
    }

    // ۱) قیمتِ صریحِ همان ارز
    var direct = _read(code);
    if (direct != null) { res.price = direct; res.source = 'explicit'; return res; }

    var base = null;
    try {
        if (typeof CurrencySystem !== 'undefined' && CurrencySystem.getBaseCode) base = CurrencySystem.getBaseCode();
    } catch (e) {}

    // ۲) تبدیلِ «قیمتِ همان نوع» (فروش برای فروش، خرید برای خرید) از ارزِ پایه با نرخِ روز.
    //    این مرحله باید *پیش از* بازگشت به قیمتِ خرید بیاید؛ وگرنه در فرمِ فروش
    //    به‌جای قیمتِ فروشِ تبدیل‌شده، قیمتِ خرید پر می‌شود (تداخلِ محاسباتی).
    if (base && base !== code) {
        var samePriceInBase = _read(base);
        if (samePriceInBase != null) {
            try {
                var conv0 = CurrencySystem.convert(samePriceInBase, base, code, isSale ? 'sell' : 'buy');
                if (conv0 == null) conv0 = CurrencySystem.convert(samePriceInBase, base, code, 'rate');
                if (conv0 != null) {
                    res.price = Math.round((conv0 + Number.EPSILON) * 100) / 100;
                    res.source = 'converted';
                    res.fromCurrency = base;
                    var br0 = CurrencySystem.baseRate(code, 'rate');
                    res.rate = (br0 == null) ? null : br0;
                    return res;
                }
            } catch (e) {}
        }
    }

    // ۲.۵) تبدیل از «هر ارزی که این جنس در آن قیمت دارد» به ارزِ درخواستی، با نرخِ روز.
    //    این همان سناریوی واقعیِ چندارزی است: جنس فقط قیمتِ USD دارد و کاربر می‌خواهد
    //    به AFN بفروشد/بخرد؛ حتی اگر هیچ‌کدام ارزِ پایه نباشند. از نقشهٔ قیمتِ همان نوع
    //    (فروش برای فروش، خرید برای خرید) هر ارزِ موجود امتحان می‌شود.
    try {
        var _priceMap = null;
        if (isSec) _priceMap = isSale ? product.secondarySalePrices : product.secondaryPurchasePrices;
        else       _priceMap = isSale ? product.salePrices : product.purchasePrices;
        if (_priceMap && typeof _priceMap === 'object') {
            var _srcCodes = Object.keys(_priceMap).filter(function (c) {
                return c !== code && c !== base && parseFloat(_priceMap[c]) > 0;
            });
            for (var _si = 0; _si < _srcCodes.length; _si++) {
                var _fromCur = _srcCodes[_si];
                var _fromVal = parseFloat(_priceMap[_fromCur]) || 0;
                if (!_fromVal) continue;
                var convX = CurrencySystem.convert(_fromVal, _fromCur, code, isSale ? 'sell' : 'buy');
                if (convX == null) convX = CurrencySystem.convert(_fromVal, _fromCur, code, 'rate');
                if (convX != null) {
                    res.price = Math.round((convX + Number.EPSILON) * 100) / 100;
                    res.source = 'converted';
                    res.fromCurrency = _fromCur;
                    // نرخِ نمایشی: ۱ واحدِ code چند واحدِ _fromCur است
                    var _rX = null;
                    try { _rX = CurrencySystem.rateValue(code, _fromCur, 'rate'); } catch (e) {}
                    res.rate = _rX;
                    return res;
                }
            }
        }
    } catch (e) {}

    // ۳) برای فروش: اگر هیچ قیمتِ فروشی (نه در این ارز نه در پایه) نبود، قیمتِ خریدِ
    //    همان ارز به‌عنوان آخرین گزینه (رفتارِ قبلیِ سیستم برای اجناسِ بدونِ قیمتِ فروش)
    if (isSale) {
        var pp = null;
        try {
            if (isSec && typeof db.getSecondaryPrice === 'function') pp = db.getSecondaryPrice(product, code, 'purchase');
            else if (!isSec && typeof db.getPurchasePrice === 'function') pp = db.getPurchasePrice(product, code);
            pp = parseFloat(pp);
            if (!isNaN(pp) && pp > 0) { res.price = pp; res.source = 'explicit'; return res; }
        } catch (e) {}
    }

    // ۴) آخرین گزینه: تبدیلِ قیمتِ خریدِ ارزِ پایه (برای فروشِ اجناسِ بدونِ قیمتِ فروش)
    try {
        if (!base) return res;
        if (base === code) return res;
        var basePrice = null;
        if (isSale) {
            try {
                var bpp = isSec ? db.getSecondaryPrice(product, base, 'purchase') : db.getPurchasePrice(product, base);
                bpp = parseFloat(bpp);
                if (!isNaN(bpp) && bpp > 0) basePrice = bpp;
            } catch (e) {}
        }
        if (basePrice == null) return res;
        var conv = CurrencySystem.convert(basePrice, base, code, isSale ? 'sell' : 'buy');
        if (conv == null) conv = CurrencySystem.convert(basePrice, base, code, 'rate');
        if (conv == null) return res;
        res.price = Math.round((conv + Number.EPSILON) * 100) / 100;
        res.source = 'converted';
        res.fromCurrency = base;
        var br = CurrencySystem.baseRate(code, 'rate');
        res.rate = (br == null) ? null : br;
    } catch (e) {}
    return res;
}

// نشانگرِ «قیمتِ پیشنهادی از نرخِ روز» کنارِ فیلدِ قیمت.
//  فیلد هرگز قفل نمی‌شود؛ کاربر می‌تواند ۱۰۰۰ را به ۹۹۵ یا ۱۰۱۰ تغییر دهد.
//  با تغییرِ دستیِ کاربر، برچسب به «قیمتِ دستی» تبدیل می‌شود.
function _markSuggestedPrice(inputEl, resolved, currency) {
    if (!inputEl) return;
    var host = inputEl.parentNode;
    if (!host) return;
    var badge = host.querySelector('.mc-rate-badge');
    if (resolved && resolved.source === 'converted') {
        if (!badge) {
            badge = document.createElement('span');
            badge.className = 'mc-rate-badge';
            badge.style.cssText = 'display:block;font-size:10px;color:#b45309;margin-top:2px;line-height:1.4;';
            host.appendChild(badge);
        }
        var rt = (resolved.rate != null) ? formatNumber(resolved.rate) : '—';
        badge.innerHTML = '<i class="fas fa-bolt"></i> پیشنهاد از نرخ روز (۱ ' + currency + ' = ' + rt + ' ' + (resolved.fromCurrency || '') + ')';
        badge.dataset.suggested = String(resolved.price);
        // با تغییرِ دستی، برچسب به‌روز شود
        if (!inputEl._mcRateBound) {
            inputEl._mcRateBound = true;
            inputEl.addEventListener('input', function () {
                var b = inputEl.parentNode && inputEl.parentNode.querySelector('.mc-rate-badge');
                if (!b) return;
                var sug = parseFloat(b.dataset.suggested || 'NaN');
                var cur = parseFloat(inputEl.value);
                if (!isNaN(sug) && !isNaN(cur) && Math.abs(sug - cur) > 0.004) {
                    b.innerHTML = '<i class="fas fa-pen"></i> قیمت دستی (پیشنهاد: ' + formatNumber(sug) + ')';
                    b.style.color = '#2563eb';
                } else {
                    b.innerHTML = '<i class="fas fa-bolt"></i> پیشنهاد از نرخ روز';
                    b.style.color = '#b45309';
                }
            });
        }
    } else if (badge) {
        badge.remove();
    }
}

// ساختِ نگاشتِ نقدیِ چند-ارزی برای ذخیره روی سند: { [کد ارز]: مبلغ }
//  هر تراکنش با ارزِ واقعیِ خودش ذخیره می‌شود و هرگز به اجبار تبدیل نمی‌گردد.
function _buildCashAmounts(currency, cashBase, cashLegacyUsd, cashForeign) {
    // نگاشتِ نقدیِ چند-ارزی، کاملاً پویا و بدونِ هیچ ارزِ ویژه.
    //  - cashBase       : مبلغِ واردشده در فیلدِ اصلی (همیشه به «ارزِ پایهٔ فعلی» سیستم)
    //  - cashLegacyUsd  : فقط برای سازگاریِ عقب‌رو با فیلدِ قدیمیِ USD (در فرم‌های مهاجرت‌نشده)
    //  - cashForeign    : مبلغِ واردشده در فیلدِ ارزِ غیرپایه (هر ارزی که کاربر انتخاب کرده)
    var m = {};
    var base = (typeof CurrencySystem !== 'undefined' && CurrencySystem.getBaseCode)
        ? CurrencySystem.getBaseCode() : null;
    var b = parseFloat(cashBase) || 0;
    var u = parseFloat(cashLegacyUsd) || 0;
    var f = parseFloat(cashForeign) || 0;
    // مبلغِ فیلدِ اصلی → به ارزِ پایه نسبت داده می‌شود (نه AFN ثابت)
    if (b && base) m[base] = (m[base] || 0) + b;
    // سازگاریِ عقب‌رو: فیلدِ USD قدیمی، فقط اگر واقعاً مقداری داشته باشد و USD خودش پایه نباشد
    if (u && base !== 'USD') m.USD = (m.USD || 0) + u;
    // ارزِ جاریِ فرم (هر ارزی، از جمله ارزِ سوم به بعد) اگر با پایه فرق داشته باشد
    if (f && currency && currency !== base) m[currency] = (m[currency] || 0) + f;
    return m;
}

// نرخِ روزِ یک ارز نسبت به پایه (برای نمایش کنارِ فیلدِ قیمت و مُهر زدن روی سند)
// نرخِ «مؤثرِ» یک ارز نسبت به پایه، برای Snapshot روی سند.
//  مشکلِ ریشه‌ای: کاربر ممکن است در کارتِ نرخ فقط «خرید/فروش» را پر کند و فیلدِ
//  «نرخ» (rate) را خالی یا ۱ بگذارد. اگر کورکورانه rate خوانده شود، Snapshot=۱
//  ثبت می‌شد و بهای تمام‌شده بدونِ تبدیل کم می‌گشت (باگِ ۴۸۹۳). این تابع نرخِ
//  واقعی را انتخاب می‌کند: rate معتبر → همان؛ در غیر آن میانگینِ buy/sell؛ سپس هرکدام.
//  mode اختیاری: 'buy' برای خرید، 'sell' برای فروش — تا نرخِ سمتِ درست به‌کار رود.
function _effectiveRate(currency, mode) {
    try {
        if (typeof CurrencySystem === 'undefined') return null;
        var base = CurrencySystem.getBaseCode();
        if (currency === base) return 1;
        var rObj = CurrencySystem.getRate ? CurrencySystem.getRate(currency, base) : null;
        if (!rObj) {
            // شاید فقط نرخِ مرجع تعریف شده باشد
            var rv = CurrencySystem.rateValue ? CurrencySystem.rateValue(currency, base, 'rate') : null;
            return (rv && rv > 0) ? rv : null;
        }
        var rate = parseFloat(rObj.rate) || 0;
        var buy  = parseFloat(rObj.buy)  || 0;
        var sell = parseFloat(rObj.sell) || 0;
        // اگر mode مشخص است و آن سمت مقدار دارد، همان
        if (mode === 'buy'  && buy  > 0) return buy;
        if (mode === 'sell' && sell > 0) return sell;
        // نرخِ مرجع اگر معتبر و «تنها ۱ نباشد در حالی که خرید/فروش مقدارِ بزرگ‌تری دارند»
        var _sideAvg = (buy > 0 && sell > 0) ? (buy + sell) / 2 : (sell > 0 ? sell : buy);
        if (rate > 0) {
            // اگر rate برابرِ ۱ است ولی خرید/فروش مقدارِ واقعیِ متفاوت دارند، rate را نامعتبر بدان
            if (rate === 1 && _sideAvg > 0 && Math.abs(_sideAvg - 1) > 0.0001) return _sideAvg;
            return rate;
        }
        if (_sideAvg > 0) return _sideAvg;
        return null;
    } catch (e) { return null; }
}
window._effectiveRate = _effectiveRate;

function _dayRateFor(currency, mode) {
    try {
        if (typeof CurrencySystem === 'undefined' || !CurrencySystem.baseRate) return null;
        if (currency === CurrencySystem.getBaseCode()) return 1;
        // نرخِ مؤثر (rate معتبر یا میانگینِ خرید/فروش) — نه rate خامِ ممکناً ۱
        var eff = _effectiveRate(currency, mode);
        if (eff != null && eff > 0) return eff;
        return CurrencySystem.baseRate(currency, 'rate');
    } catch (e) { return null; }
}

// ══════════════════════════════════════════════════════════════════════════
//  موتورِ مرکزیِ دفترِ معینِ اشخاص (Customer Ledger Engine) — منبعِ واحدِ حقیقت
//  ---------------------------------------------------------------------------
//  اصلِ معماری: حسابِ هر شخص «یک عددِ مانده» نیست؛ یک نگاشتِ مستقل به تفکیکِ هر ارز
//  است. تراکنش‌های یک ارز هرگز ماندهٔ ارزِ دیگر را تغییر نمی‌دهند (بدونِ تداخل).
//    خروجی: { balances:{AFN:…, USD:…, EUR:…}, rows:[…], byCurrency:{cur:{…}} }
//    قراردادِ علامت: مثبت = شخص بدهکارِ ماست ، منفی = شخص طلبکار است.
// ══════════════════════════════════════════════════════════════════════════
function buildPersonLedger(person, opts) {
    opts = opts || {};
    var out = { balances: {}, rows: [], byCurrency: {} };
    if (!person) return out;

    function _bucket(cur) {
        cur = cur || _baseCur();
        if (!out.byCurrency[cur]) {
            out.byCurrency[cur] = {
                currency: cur, sales: 0, purchases: 0, received: 0, paid: 0,
                returnsSale: 0, returnsPurchase: 0, opening: 0, balance: 0
            };
        }
        if (out.balances[cur] == null) out.balances[cur] = 0;
        return out.byCurrency[cur];
    }
    function _apply(cur, effect) {
        _bucket(cur);
        out.balances[cur] += effect;
        out.byCurrency[cur].balance += effect;
    }

    // ---- ۱) حسابِ قبلی (Opening Balance) — به ارزِ خودِ شخص ----
    var prev = parseFloat(person.previousAccount) || 0;
    if (prev) {
        var prevCur = person.currency || _baseCur();
        var sign = (person.accountType === 'طلبکار') ? -1 : 1;
        var _openEff = sign * prev;
        _bucket(prevCur).opening = _openEff;
        _apply(prevCur, _openEff);
        out.rows.push({
            kind: 'opening', date: person.createdAt || '', currency: prevCur,
            label: 'حساب قبلی', amount: prev, effect: _openEff,
            balanceAfter: out.balances[prevCur], rateUsed: null
        });
    }

    // ---- ۲) تراکنش‌ها — هرکدام با ارزِ واقعیِ خودش ----
    var all = (typeof db !== 'undefined' && db.getTransactions) ? (db.getTransactions() || []) : [];
    var mine = all.filter(function (t) {
        return t && (t.personId == person.id || t.customerId == person.id || t.supplierId == person.id);
    });
    // ترتیبِ زمانی برای «ماندهٔ در جریان» درست
    mine.sort(function (a, b) {
        var da = String(a.createdAt || a.date || ''), db_ = String(b.createdAt || b.date || '');
        return da.localeCompare(db_);
    });

    mine.forEach(function (tx) {
        var cur = tx.currency || _baseCur();
        var total = parseFloat(tx.totalAmount || tx.amount || 0) || 0;
        var remaining = (typeof calculateTxRemaining === 'function')
            ? calculateTxRemaining(tx) : (parseFloat(tx.remaining) || 0);
        var b = _bucket(cur);
        var effect = 0, label = tx.type;

        // ---- تبدیل ارز (صرافی) روی حسابِ شخص: دو-ارزی، بدونِ تداخل ----
        // fromCurrency/-fromAmount  و  toCurrency/+toAmount  را روی همان شخص اعمال می‌کند.
        // (برای «داخل حساب مشتری» هر دو لِنگ در یک سند؛ برای «بین حساب اشخاص» هر شخص یک لِنگ.)
        if (tx.type === 'صرافی') {
            var _fc = tx.fromCurrency || cur, _tc = tx.toCurrency || cur;
            var _fa = parseFloat(tx.fromAmount || 0) || 0, _ta = parseFloat(tx.toAmount || 0) || 0;
            var _cs = (tx.convSign != null ? tx.convSign : 1);   // علامتِ حساب: حفظِ ماهیتِ طلبکار/بدهکار
            if (_fa) {
                _apply(_fc, -_cs * _fa);
                out.rows.push({ kind: 'tx', id: tx.id, date: tx.date || tx.createdAt || '', currency: _fc,
                    label: 'تبدیل ارز رفت', type: 'صرافی', billNumber: '', amount: _fa, remaining: 0, effect: -_cs * _fa,
                    balanceAfter: out.balances[_fc], rateUsed: _txStoredRate(tx), tx: opts.includeTx ? tx : undefined });
            }
            if (_ta) {
                _apply(_tc, +_cs * _ta);
                out.rows.push({ kind: 'tx', id: tx.id, date: tx.date || tx.createdAt || '', currency: _tc,
                    label: 'تبدیل ارز آمد', type: 'صرافی', billNumber: '', amount: _ta, remaining: 0, effect: +_cs * _ta,
                    balanceAfter: out.balances[_tc], rateUsed: _txStoredRate(tx), tx: opts.includeTx ? tx : undefined });
            }
            return;
        }

        switch (tx.type) {
            case 'فروش':
                effect = remaining;
                b.sales += total;
                b.received += Math.max(0, total - remaining); // نقدِ داخلِ بل
                break;
            case 'خرید':
                effect = -remaining;
                b.purchases += total;
                b.paid += Math.max(0, total - remaining);
                break;
            case 'دریافت':
                effect = -total; b.received += total; break;
            case 'پرداخت':
                effect = total; b.paid += total; break;
            case 'پرداخت از حساب قبلی':
                effect = (person.accountType === 'طلبکار') ? total : -total; break;
            case 'برگشت':
                if (tx.returnType === 'فروش') { effect = -(tx.remaining != null ? parseFloat(tx.remaining) : total); b.returnsSale += total; label = 'برگشت از فروش'; }
                else if (tx.returnType === 'خرید') { effect = (tx.remaining != null ? parseFloat(tx.remaining) : total); b.returnsPurchase += total; label = 'برگشت از خرید'; }
                break;
            default: effect = 0;
        }

        _apply(cur, effect);
        out.rows.push({
            kind: 'tx', id: tx.id, date: tx.date || tx.createdAt || '', currency: cur,
            label: label, type: tx.type, billNumber: tx.billNumber || '',
            amount: total, remaining: remaining, effect: effect,
            balanceAfter: out.balances[cur],
            // نرخِ قفل‌شدهٔ لحظهٔ ثبتِ همین سند (برای گزارشِ تجمیعی)
            rateUsed: _txStoredRate(tx),
            tx: opts.includeTx ? tx : undefined
        });
    });

    return out;
}
if (typeof window !== 'undefined') window.buildPersonLedger = buildPersonLedger;

// نرخِ ثبت‌شدهٔ یک سند نسبت به ارزِ پایه (Snapshot Rate) — با Fallback امن
function _txStoredRate(tx) {
    if (!tx) return null;
    var r = parseFloat(tx.rateUsed);
    if (r > 0) return r;
    if (tx.exchangeRateSnapshot && parseFloat(tx.exchangeRateSnapshot.rate) > 0) {
        return parseFloat(tx.exchangeRateSnapshot.rate);
    }
    return null;
}
if (typeof window !== 'undefined') window._txStoredRate = _txStoredRate;

// تبدیلِ یک مبلغ به ارزِ پایه با «نرخِ زمانِ معامله» (نه نرخِ امروز).
//  اگر سند نرخِ ثبت‌شده نداشته باشد (اسنادِ قدیمی)، به نرخِ جاری برمی‌گردد.
function convertAtDocRate(amount, currency, tx) {
    var amt = parseFloat(amount) || 0;
    if (!amt) return 0;
    var base = 'AFN';
    try {
        if (typeof CurrencySystem !== 'undefined' && CurrencySystem.getBaseCode) base = CurrencySystem.getBaseCode();
    } catch (e) {}
    var cur = currency || base;
    if (cur === base) return amt;
    var r = _txStoredRate(tx);
    // نرخِ ثبت‌شده فقط وقتی معتبر است که ارزِ سند با ارزِ موردِ تبدیل یکی باشد
    var snapCur = tx && (tx.rateUsed != null ? (tx.currency || cur)
                 : (tx.exchangeRateSnapshot ? tx.exchangeRateSnapshot.currency : null));
    if (r > 0 && (!snapCur || snapCur === cur)) return amt * r;
    try {
        if (typeof CurrencySystem !== 'undefined' && CurrencySystem.convert) {
            var cv = CurrencySystem.convert(amt, cur, base, 'rate');
            if (cv != null) return cv;
        }
    } catch (e) {}
    return amt;
}
if (typeof window !== 'undefined') window.convertAtDocRate = convertAtDocRate;

// ══════════════════════════════════════════════════════════════════════════
//  موتورِ گزارش‌گیریِ چند-ارزی (Reports Engine)
//  ---------------------------------------------------------------------------
//  دو حالت:
//   ۱) تفکیکی (By Currency)   → هر ارز جدا، بدونِ هیچ تبدیلی
//   ۲) تجمیعی (Consolidated)  → تبدیل به ارزِ پایه با «نرخِ زمانِ معامله»، نه نرخِ امروز
// ══════════════════════════════════════════════════════════════════════════
function buildCurrencyReport(opts) {
    opts = opts || {};
    var filterFn = opts.filter || function () { return true; };
    var txs = (typeof db !== 'undefined' && db.getTransactions) ? (db.getTransactions() || []) : [];
    var exps = (typeof db !== 'undefined' && db.getExpenses) ? (db.getExpenses() || []) : [];
    var base = 'AFN';
    try { if (typeof CurrencySystem !== 'undefined' && CurrencySystem.getBaseCode) base = CurrencySystem.getBaseCode(); } catch (e) {}

    var out = {
        base: base,
        byCurrency: {},      // گزارشِ تفکیکی
        consolidated: {       // گزارشِ تجمیعی (به ارزِ پایه، با نرخِ زمانِ معامله)
            sales: 0, purchases: 0, received: 0, paid: 0,
            expenses: 0, returnsSale: 0, returnsPurchase: 0,
            receivable: 0, payable: 0, profit: 0
        },
        missingRateDocs: 0    // تعدادِ اسنادی که نرخِ ثبت‌شده نداشتند (شفافیتِ گزارش)
    };

    function _b(cur) {
        cur = cur || base;
        if (!out.byCurrency[cur]) {
            out.byCurrency[cur] = {
                currency: cur, sales: 0, purchases: 0, received: 0, paid: 0,
                expenses: 0, returnsSale: 0, returnsPurchase: 0,
                receivable: 0, payable: 0, profit: 0, count: 0
            };
        }
        return out.byCurrency[cur];
    }
    function _toBase(amount, cur, tx) {
        if (cur === base) return parseFloat(amount) || 0;
        if (tx && !_txStoredRate(tx)) out.missingRateDocs++;
        return convertAtDocRate(amount, cur, tx);
    }

    txs.forEach(function (tx) {
        if (!tx || !filterFn(tx)) return;
        var cur = tx.currency || base;
        var b = _b(cur);
        var total = parseFloat(tx.totalAmount || tx.amount || 0) || 0;
        var remaining = (typeof calculateTxRemaining === 'function')
            ? calculateTxRemaining(tx) : (parseFloat(tx.remaining) || 0);
        b.count++;

        switch (tx.type) {
            case 'فروش':
                b.sales += total;
                b.received += Math.max(0, total - remaining);
                if (remaining > 0) b.receivable += remaining;
                out.consolidated.sales += _toBase(total, cur, tx);
                out.consolidated.received += _toBase(Math.max(0, total - remaining), cur, tx);
                if (remaining > 0) out.consolidated.receivable += _toBase(remaining, cur, tx);
                // مفادِ همان سند (به ارزِ خودش) — سپس تجمیع با نرخِ همان سند
                var pf = 0;
                try { if (typeof computeSaleProfit === 'function') pf = computeSaleProfit(tx) || 0; } catch (e) {}
                b.profit += pf;
                out.consolidated.profit += _toBase(pf, cur, tx);
                break;
            case 'خرید':
                b.purchases += total;
                b.paid += Math.max(0, total - remaining);
                if (remaining > 0) b.payable += remaining;
                out.consolidated.purchases += _toBase(total, cur, tx);
                out.consolidated.paid += _toBase(Math.max(0, total - remaining), cur, tx);
                if (remaining > 0) out.consolidated.payable += _toBase(remaining, cur, tx);
                break;
            case 'دریافت':
                b.received += total;
                out.consolidated.received += _toBase(total, cur, tx);
                break;
            case 'پرداخت':
                b.paid += total;
                out.consolidated.paid += _toBase(total, cur, tx);
                break;
            case 'برگشت':
                if (tx.returnType === 'فروش') {
                    b.returnsSale += total;
                    out.consolidated.returnsSale += _toBase(total, cur, tx);
                } else if (tx.returnType === 'خرید') {
                    b.returnsPurchase += total;
                    out.consolidated.returnsPurchase += _toBase(total, cur, tx);
                }
                break;
        }
    });

    exps.forEach(function (e) {
        if (!e || !filterFn(e)) return;
        var cur = e.currency || base;
        var amt = parseFloat(e.amount || 0) || 0;
        _b(cur).expenses += amt;
        out.consolidated.expenses += _toBase(amt, cur, e);
    });

    // مفادِ خالصِ تجمیعی = مفادِ ناخالص − مصارف
    out.consolidated.netProfit = out.consolidated.profit - out.consolidated.expenses;
    Object.keys(out.byCurrency).forEach(function (c) {
        var b = out.byCurrency[c];
        b.netProfit = b.profit - b.expenses;
    });
    return out;
}
if (typeof window !== 'undefined') window.buildCurrencyReport = buildCurrencyReport;

// گزارشِ دفترِ معینِ همهٔ اشخاص به تفکیکِ ارز + جمعِ تجمیعی به ارزِ پایه
function getLedgerReport(opts) {
    opts = opts || {};
    var persons = (typeof db !== 'undefined' && db.getPersons) ? (db.getPersons() || []) : [];
    var base = 'AFN';
    try { if (typeof CurrencySystem !== 'undefined' && CurrencySystem.getBaseCode) base = CurrencySystem.getBaseCode(); } catch (e) {}
    var rows = [], totals = {}, consolidated = { receivable: 0, payable: 0, net: 0 };

    persons.forEach(function (p) {
        var led = buildPersonLedger(p);
        var any = false;
        Object.keys(led.balances).forEach(function (cur) {
            var v = parseFloat(led.balances[cur]) || 0;
            if (!v) return;
            any = true;
            totals[cur] = (totals[cur] || 0) + v;
            // تبدیلِ تجمیعی با نرخِ جاری (ماندهٔ باز، نه سندِ منفرد)
            var inBase = v;
            if (cur !== base) {
                try {
                    if (typeof CurrencySystem !== 'undefined' && CurrencySystem.convert) {
                        var cv = CurrencySystem.convert(v, cur, base, 'rate');
                        if (cv != null) inBase = cv;
                    }
                } catch (e) {}
            }
            if (v > 0) consolidated.receivable += inBase; else consolidated.payable += Math.abs(inBase);
            consolidated.net += inBase;
        });
        if (any || opts.includeZero) {
            rows.push({ personId: p.id, personName: p.name, balances: led.balances, byCurrency: led.byCurrency });
        }
    });
    return { base: base, rows: rows, totalsByCurrency: totals, consolidated: consolidated };
}
if (typeof window !== 'undefined') window.getLedgerReport = getLedgerReport;

// آیا در میانِ همهٔ ارزها (نه فقط AFN/USD) ماندهٔ مثبتی هست؟
function _anyPositiveBalance(afn, usd, map) {
    if ((parseFloat(afn) || 0) > 0 || (parseFloat(usd) || 0) > 0) return true;
    if (map) return Object.keys(map).some(function (k) { return (parseFloat(map[k]) || 0) > 0; });
    return false;
}

function _computePersonBalance(person) {
    // منبعِ واحدِ حقیقت: موتورِ مرکزیِ دفترِ معین (بدونِ تداخلِ بینِ ارزها)
    var led = buildPersonLedger(person);
    var balances = led.balances || {};
    return {
        afn: parseFloat(balances.AFN) || 0,
        usd: parseFloat(balances.USD) || 0,
        balances: balances,
        byCurrency: led.byCurrency
    };
}

function loadPersonsList() {
    const persons = db.getPersons();
    const tbody = document.querySelector('#persons-table tbody');
    tbody.innerHTML = '';

    var _fnum = function (v) { return (typeof formatNumber === 'function') ? formatNumber(Math.abs(parseFloat(v) || 0)) : Math.abs(parseFloat(v) || 0); };
    // برچسبِ هر ارزِ اضافی از سیستمِ مرکزیِ ارزها (در نبودِ آن، خودِ کد)
    var _curLabel = function (code) {
        try {
            if (typeof CurrencySystem !== 'undefined' && CurrencySystem.getCurrency) {
                var c = CurrencySystem.getCurrency(code);
                if (c) return c.symbol || c.nameLocal || code;
            }
        } catch (e) {}
        return code;
    };
    // متن دو-ارزی مانند تصویر: 85405($)-9403(AFN) + الحاقِ ارزهای سوم به بعد (اگر غیرصفر بود)
    var _dual = function (afn, usd, balances) {
        var s = _fnum(usd) + '($)-' + _fnum(afn) + '(AFN)';
        if (balances && typeof balances === 'object') {
            Object.keys(balances).forEach(function (code) {
                if (code === 'AFN' || code === 'USD') return;
                var v = parseFloat(balances[code]) || 0;
                if (!v) return;
                s += '-' + _fnum(v) + '(' + _curLabel(code) + ')';
            });
        }
        return s;
    };

    persons.forEach(person => {
        var bal = _computePersonBalance(person);
        // باقیداری = مانده فعلی، طلب = مبلغ بدهکاری/طلبکاری (همان مانده)
        var baqi = _dual(bal.afn, bal.usd, bal.balances);
        var talab = _dual(bal.afn, bal.usd, bal.balances);
        // وضعیت برای رنگ متن «طلب» (شاملِ هر ارزِ غیرصفر)
        var _anyPositive = (bal.afn > 0 || bal.usd > 0);
        if (!_anyPositive && bal.balances) {
            _anyPositive = Object.keys(bal.balances).some(function (k) { return (parseFloat(bal.balances[k]) || 0) > 0; });
        }
        var isDebt = _anyPositive;

        const row = document.createElement('tr');
        row.className = 'person-card-row';
        row.innerHTML = `
            <td class="person-card-cell">
                <div class="person-card">
                    <div class="person-card-main">
                        <span class="person-card-avatar"><i class="fas fa-user"></i></span>
                        <span class="person-card-name">${person.name}</span>
                    </div>
                    <div class="person-card-balance">باقیداری: <span>${baqi}</span></div>
                    <div class="person-card-debt ${isDebt ? 'is-debt' : ''}">طلب: <span>${talab}</span></div>
                    <div class="person-card-actions">
                        <button type="button" class="person-card-kebab" onclick="togglePersonRowMenu(this, event)" title="عملیات"><i class="fas fa-ellipsis-v"></i></button>
                        <div class="person-row-menu">
                            <button type="button" onclick="showPersonTransactions(${person.id})"><i class="fas fa-list"></i> معاملات</button>
                            <button type="button" onclick="showPersonForm(${person.id})"><i class="fas fa-edit"></i> ویرایش</button>
                            <button type="button" onclick="openCurrencyConversion('inside_person', {personId: ${person.id}})"><i class="fas fa-right-left"></i> تبدیل ارز داخل حساب مشتری</button>
                            <button type="button" class="danger" onclick="deletePerson(${person.id})"><i class="fas fa-trash"></i> حذف</button>
                        </div>
                    </div>
                </div>
            </td>
        `;
        tbody.appendChild(row);
    });
}

// باز/بستن منوی سه‌نقطهٔ ردیف شخص
function togglePersonRowMenu(btn, ev) {
    if (ev) { ev.stopPropagation(); }
    var menu = btn.parentElement.querySelector('.person-row-menu');
    if (!menu) return;
    var isOpen = menu.classList.contains('open');
    // بستن سایر منوها
    document.querySelectorAll('.person-row-menu.open').forEach(function (m) { m.classList.remove('open'); });
    if (!isOpen) {
        menu.classList.add('open');
        var _close = function () { menu.classList.remove('open'); document.removeEventListener('click', _close); };
        setTimeout(function () { document.addEventListener('click', _close); }, 0);
    }
}

function resetPersonForm() {
    document.getElementById('personForm').reset();
    document.getElementById('person-previous-account').value = '';
    delete document.getElementById('personForm').dataset.editId;
}

function loadPersonData(personId) {
    const persons = db.getPersons();
    const person = persons.find(p => p.id == personId);
    
    if (person) {
        document.getElementById('person-name').value = person.name || '';
        document.getElementById('person-category').value = person.category || '';
        document.getElementById('person-phone').value = person.phone || '';
        document.getElementById('person-id').value = person.idNumber || '';
        document.getElementById('person-address').value = person.address || '';
        document.getElementById('person-previous-account').value = person.previousAccount || '';
        document.getElementById('person-account-type').value = person.accountType || 'بدون حساب';
        document.getElementById('person-currency').value = person.currency || _baseCur();
        document.getElementById('person-notes').value = person.notes || '';
        document.getElementById('personForm').dataset.editId = personId;
    }
}
