// ==================== گزارش معاملات فرد ====================
function generatePersonReport(personId) {
    const person = db.getPersons().find(p => p.id == personId);
    if (!person) { showMessage('خطا', 'شخص یافت نشد'); return; }

    // ---- تنظیمات بل: رنگ/فونت/مشخصاتِ بالا دقیقاً از بل خوانده می‌شود ----
    const settings = db.getSettings() || {};
    var S = settings;
    var navy = S.billPrimaryColor || '#1b2a4a';
    var gold = S.billAccentColor || '#c8963c';
    var _contrastOn = function (hex) {
        try {
            var h = String(hex || '').replace('#', '');
            if (h.length === 3) h = h[0] + h[0] + h[1] + h[1] + h[2] + h[2];
            var r = parseInt(h.substr(0, 2), 16), g = parseInt(h.substr(2, 2), 16), b = parseInt(h.substr(4, 2), 16);
            if (isNaN(r) || isNaN(g) || isNaN(b)) return '#ffffff';
            var lum = (0.299 * r + 0.587 * g + 0.114 * b) / 255;
            return lum > 0.6 ? '#1a2533' : '#ffffff';
        } catch (e) { return '#ffffff'; }
    };
    var _shade = function (hex, percent) {
        try {
            var h = String(hex || '').replace('#', '');
            if (h.length === 3) h = h[0] + h[0] + h[1] + h[1] + h[2] + h[2];
            var r = parseInt(h.substr(0, 2), 16), g = parseInt(h.substr(2, 2), 16), b = parseInt(h.substr(4, 2), 16);
            if (isNaN(r) || isNaN(g) || isNaN(b)) return hex;
            var t = percent < 0 ? 0 : 255, p = Math.abs(percent) / 100;
            var nr = Math.round((t - r) * p) + r, ng = Math.round((t - g) * p) + g, nb = Math.round((t - b) * p) + b;
            return '#' + ((1 << 24) + (nr << 16) + (ng << 8) + nb).toString(16).slice(1);
        } catch (e) { return hex; }
    };
    var onPrimary = _contrastOn(navy);
    var navyDark = _shade(navy, -18);
    var _fontMap = {
        vazirmatn: "'Vazirmatn', Tahoma, Arial, sans-serif",
        tahoma: "Tahoma, 'Vazirmatn', Arial, sans-serif",
        arial: "Arial, 'Vazirmatn', Helvetica, sans-serif",
        times: "'Times New Roman', 'Vazirmatn', serif",
        courier: "'Courier New', 'Vazirmatn', monospace",
        nazanin: "'B Nazanin', 'Nazanin', 'Vazirmatn', Tahoma, serif"
    };
    var fontFamily = _fontMap[S.billFontFamily] || _fontMap.vazirmatn;
    var baseFont = parseFloat(S.billBaseFontSize) || 12;
    var titleFont = parseFloat(S.billTitleFontSize) || 26;
    var fEnName = Math.max(10, Math.round(titleFont * 0.55));

    const storeName = S.billStoreName || S.storeName || 'نام دوکان شما';
    const storeNameEn = S.billStoreNameEn || '';
    const storeSlogan = S.billSlogan || S.invoiceHeader || 'عرضه کننده انواع کالا های با کیفیت';
    const storePhone = S.billPhone || S.storePhone || '';
    const storePhone2 = S.storePhone2 || '';
    const storeAddress = S.billAddress || S.storeAddress || '';
    const storeWebsite = S.storeWebsite || '';
    const footerTitle = S.billFooterTitle || 'از اعتماد شما سپاسگزاریم';
    const footerSubtitle = (S.billFooterSubtitle != null) ? S.billFooterSubtitle : (S.invoiceFooter || 'کیفیت بهتر، قیمت مناسب، خدمت صادقانه');
    const logoSrc = S.billLogo || S.storeLogo || '';
    const logoHtml = logoSrc
        ? `<img src="${logoSrc}" alt="لوگو" style="max-height:80px;max-width:100px;object-fit:contain;">`
        : `<div class="rep-logo-ph"><i class="fas fa-store"></i></div>`;

    const fn = (v) => {
        const n = parseFloat(v) || 0;
        return new Intl.NumberFormat((typeof getNumberSystem === 'function' && getNumberSystem() === 'en') ? 'en-US' : 'fa-IR').format(n);
    };
    const esc = (s) => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');

    const allTx = db.getTransactions() || [];
    const personTxs = allTx.filter(t => t.personId == person.id || t.customerId == person.id || t.supplierId == person.id);
    personTxs.sort(function(a, b) {
        var da = a.createdAt || a.date || '';
        var db_ = b.createdAt || b.date || '';
        return da.localeCompare(db_);
    });

    let balanceAFN = 0, balanceUSD = 0;
    var balMap = {};  // ماندهٔ در جریان به تفکیک هر ارز (شاملِ ارزِ سوم)
    function _prBal(cur, val) { balMap[cur] = (balMap[cur] || 0) + val; }
    if (person.previousAccount) {
        const prev = parseFloat(person.previousAccount) || 0;
        const prevCur = person.currency || _baseCur();
        if (person.accountType === 'بدهکار') { _prBal(prevCur, prev); }
        else if (person.accountType === 'طلبکار') { _prBal(prevCur, -prev); }
    }

    // ---- ساخت رکوردهای ردیف (منبع واحد برای جدول HTML و اکسل) ----
    const records = [];

    if (person.previousAccount && parseFloat(person.previousAccount) !== 0) {
        const prevAmount = parseFloat(person.previousAccount) || 0;
        const prevCur = person.currency || _baseCur();
        const prevSym = _curSymGlobal(prevCur);
        let currentBal = (balMap[prevCur] || 0);
        let balColor = currentBal > 0 ? '#ef4444' : (currentBal < 0 ? '#10b981' : '#64748b');
        let balLabel = currentBal > 0 ? 'بدهکار' : (currentBal < 0 ? 'طلبکار' : 'تسویه');
        records.push({
            kind: 'prev',
            idx: '—',
            dateStr: person.createdAt || '---',
            billNumber: '—',
            typeLabel: 'حساب قبلی',
            typeBg: '#0ea5e9',
            desc: (person.accountType === 'بدهکار' ? 'بدهی شخص' : 'طلب شخص'),
            items: [],
            amountStr: fn(prevAmount) + ' ' + prevSym,
            balStr: fn(Math.abs(currentBal)) + ' ' + prevSym,
            balColor: balColor,
            balLabel: balLabel,
            more: '—'
        });
    }

    let totalSalesAFN = 0, totalSalesUSD = 0;
    let totalPurchasesAFN = 0, totalPurchasesUSD = 0;
    let totalReceiptsAFN = 0, totalReceiptsUSD = 0;
    let totalPaymentsAFN = 0, totalPaymentsUSD = 0;
    let totalReturnsAFN = 0, totalReturnsUSD = 0;
    // نقشه‌های پویا برای هر ارز (شاملِ ارزِ سوم) — نمایش‌های AFN/USD مثل قبل حفظ می‌شوند
    var salesMap = {}, purchasesMap = {}, receiptsMap = {}, paymentsMap = {}, returnsMap = {};
    function _addTo(map, cur, v) { map[cur] = (map[cur] || 0) + v; }
    let idx = 1;

    personTxs.forEach(tx => {
        const totalAmount = parseFloat(tx.totalAmount || tx.amount || 0);
        const remaining = (typeof calculateTxRemaining === 'function') ? calculateTxRemaining(tx) : (parseFloat(tx.remaining) || 0);
        const currency = tx.currency || _baseCur();
        let effect = 0;

        switch(tx.type) {
            case 'فروش': {
                effect = remaining;
                // نقدِ دریافت‌شده روی بلِ فروش هم جزوِ «مجموع دریافتی» است (نه فقط دکمهٔ سریع دریافت)
                var _rcvSale = Math.max(0, totalAmount - remaining);
                _addTo(salesMap, currency, totalAmount); _addTo(receiptsMap, currency, _rcvSale);
                break;
            }
            case 'خرید': {
                effect = -remaining;
                // نقدِ پرداخت‌شده روی بلِ خرید هم جزوِ «مجموع پرداختی» است (نه فقط دکمهٔ سریع پرداخت)
                var _pdBuy = Math.max(0, totalAmount - remaining);
                _addTo(purchasesMap, currency, totalAmount); _addTo(paymentsMap, currency, _pdBuy);
                break;
            }
            case 'دریافت': effect = -totalAmount; _addTo(receiptsMap, currency, totalAmount); break;
            case 'پرداخت': effect = totalAmount; _addTo(paymentsMap, currency, totalAmount); break;
            case 'برگشت':
                if (tx.returnType === 'فروش') { effect = -(tx.remaining != null ? parseFloat(tx.remaining) : totalAmount); _addTo(returnsMap, currency, totalAmount); }
                else if (tx.returnType === 'خرید') { effect = (tx.remaining != null ? parseFloat(tx.remaining) : totalAmount); _addTo(returnsMap, currency, totalAmount); }
                break;
            default: effect = 0;
        }

        _prBal(currency, effect);

        let currentBalance = (balMap[currency] || 0);
        let balColor = currentBalance > 0 ? '#ef4444' : (currentBalance < 0 ? '#10b981' : '#64748b');
        let balLabel = currentBalance > 0 ? 'بدهکار' : (currentBalance < 0 ? 'طلبکار' : 'تسویه');
        let sym = _curSymGlobal(currency);

        // اقلامِ بل (تعداد و قیمت واحد از خودِ بل خرید/فروش)
        let items = [];
        if (tx.items && Array.isArray(tx.items)) {
            items = tx.items.map(function(it) {
                return {
                    name: it.name || it.productName || '-',
                    qty: parseFloat(it.quantity != null ? it.quantity : (it.qty || 0)) || 0,
                    price: parseFloat(it.price || 0) || 0,
                    unit: it.unit || ''
                };
            }).filter(function(x) { return x.name && x.name !== '-'; });
        }
        let descFallback = tx.description || tx.notes || '-';

        // رنگ نوع معامله (ثابت — با تغییرِ رنگِ بل تغییر نمی‌کند)
        let typeBg = '#64748b';
        if (tx.type === 'فروش') typeBg = '#10b981';
        else if (tx.type === 'خرید') typeBg = '#3b82f6';
        else if (tx.type === 'دریافت') typeBg = '#8b5cf6';
        else if (tx.type === 'پرداخت') typeBg = '#f59e0b';
        else if (tx.type === 'برگشت') typeBg = '#ef4444';

        // اطلاعات بیشتر
        const paid = totalAmount - remaining;
        const disc = parseFloat(tx.totalDiscount != null ? tx.totalDiscount : (tx.discount || 0)) || 0;
        const notes = tx.notes || tx.description || '';
        const cashboxName = tx.cashboxName || '';
        let moreLines = [];
        if (tx.type === 'فروش' || tx.type === 'خرید') {
            moreLines.push('پرداخت‌شده: ' + fn(paid) + ' ' + sym);
            moreLines.push('باقی‌مانده: ' + fn(remaining) + ' ' + sym);
        }
        if (disc > 0) moreLines.push('تخفیف: ' + fn(disc) + ' ' + sym);
        if (cashboxName) moreLines.push('حساب: ' + cashboxName);
        if (notes) moreLines.push('یادداشت: ' + notes);
        const moreText = moreLines.length ? moreLines.join('\n') : '—';

        records.push({
            kind: 'tx',
            idx: idx++,
            dateStr: (typeof formatAfghanDateTime === 'function' ? formatAfghanDateTime(tx.date, tx.createdAt) : tx.date) || '---',
            billNumber: tx.billNumber || '—',
            typeLabel: tx.type + (tx.returnType ? ' (' + tx.returnType + ')' : ''),
            typeBg: typeBg,
            desc: descFallback,
            items: items,
            amountStr: fn(totalAmount) + ' ' + sym,
            balStr: fn(Math.abs(currentBalance)) + ' ' + sym,
            balColor: balColor,
            balLabel: balLabel,
            moreLines: moreLines,
            more: moreText
        });
    });

    // ---- ردیف‌های جدول HTML ----
    let txRowsHTML = '';
    records.forEach(function(rec) {
        const rowBg = rec.kind === 'prev' ? 'background:#f0fdf4;font-weight:600;' : '';
        const itemCount = (rec.items && rec.items.length) ? rec.items.length : 1;
        const span = itemCount;
        const moreHTML = (rec.moreLines && rec.moreLines.length)
            ? rec.moreLines.map(function(l) { return '<div class="more-line">' + esc(l) + '</div>'; }).join('')
            : esc(rec.more);

        // سلولِ اقلام: هر قلم یک ردیفِ داخلی با شرح/تعداد/قیمت واحد
        let descCells = '';
        if (rec.items && rec.items.length) {
            descCells =
                '<td class="c-desc">' + esc(rec.items[0].name) + '</td>' +
                '<td class="c-qty">' + fn(rec.items[0].qty) + (rec.items[0].unit ? ' <span class="u">' + esc(rec.items[0].unit) + '</span>' : '') + '</td>' +
                '<td class="c-price">' + fn(rec.items[0].price) + '</td>';
        } else {
            descCells = '<td class="c-desc" colspan="3" style="text-align:right;">' + esc(rec.desc || '-') + '</td>';
        }

        // هر معامله در یک <tbody> جدا تا در چاپ/PDF بینِ صفحات نصف نشود و هیچ ردیفی حذف نگردد
        txRowsHTML += '<tbody class="tx-group">';
        txRowsHTML += '<tr style="' + rowBg + '">' +
            '<td class="c-num" rowspan="' + span + '">' + rec.idx + '</td>' +
            '<td class="c-date" rowspan="' + span + '">' + esc(rec.dateStr) + '</td>' +
            '<td class="c-bill" rowspan="' + span + '">' + esc(rec.billNumber) + '</td>' +
            '<td class="c-type" rowspan="' + span + '"><span class="type-badge" style="background:' + rec.typeBg + ';">' + esc(rec.typeLabel) + '</span></td>' +
            descCells +
            '<td class="c-amount" rowspan="' + span + '">' + esc(rec.amountStr) + '</td>' +
            '<td class="c-bal" rowspan="' + span + '" style="color:' + rec.balColor + ';font-weight:700;">' + esc(rec.balStr) + '<br><small>' + esc(rec.balLabel) + '</small></td>' +
            '<td class="c-more" rowspan="' + span + '">' + moreHTML + '</td>' +
        '</tr>';

        // ردیف‌های اقلامِ بعدی (فقط شرح/تعداد/قیمت واحد)
        if (rec.items && rec.items.length > 1) {
            for (var k = 1; k < rec.items.length; k++) {
                txRowsHTML += '<tr style="' + rowBg + '">' +
                    '<td class="c-desc">' + esc(rec.items[k].name) + '</td>' +
                    '<td class="c-qty">' + fn(rec.items[k].qty) + (rec.items[k].unit ? ' <span class="u">' + esc(rec.items[k].unit) + '</span>' : '') + '</td>' +
                    '<td class="c-price">' + fn(rec.items[k].price) + '</td>' +
                '</tr>';
            }
        }
        txRowsHTML += '</tbody>';
    });

    // ردیف نهایی مانده
    // مشتق‌سازیِ اسکالرهای نمایشیِ ثابتِ افغانی/دالر از نگاشت‌ها (نقشه‌ها منبعِ حقیقت‌اند).
    // هیچ انباشتِ ثابت‌ارزی در حلقه نمی‌ماند، ولی خروجیِ AFN/USD عیناً یکسان است.
    balanceAFN = balMap['AFN'] || 0; balanceUSD = balMap['USD'] || 0;
    totalSalesAFN = salesMap['AFN'] || 0; totalSalesUSD = salesMap['USD'] || 0;
    totalPurchasesAFN = purchasesMap['AFN'] || 0; totalPurchasesUSD = purchasesMap['USD'] || 0;
    totalReceiptsAFN = receiptsMap['AFN'] || 0; totalReceiptsUSD = receiptsMap['USD'] || 0;
    totalPaymentsAFN = paymentsMap['AFN'] || 0; totalPaymentsUSD = paymentsMap['USD'] || 0;
    totalReturnsAFN = returnsMap['AFN'] || 0; totalReturnsUSD = returnsMap['USD'] || 0;

    let finalRowsHTML = '';
    // ── سطرِ ماندهٔ نهایی برای هر ارزِ دارای بلانس — کاملاً پویا (ارزِ پایه اول) ──
    var _prBase = _baseCur();
    var _allBalCodes = Object.keys(balMap).filter(function (cc) { return Math.abs(balMap[cc] || 0) > 1e-7; });
    _allBalCodes.sort(function (a, b) { if (a === _prBase) return -1; if (b === _prBase) return 1; return 0; });
    _allBalCodes.forEach(function (cc) {
        var bv = balMap[cc] || 0;
        var c = bv > 0 ? '#ef4444' : '#10b981';
        var l = bv > 0 ? 'بدهکار' : 'طلبکار';
        var sym = (typeof _curSymGlobal === 'function') ? _curSymGlobal(cc) : cc;
        var lbl = (typeof getCurrencyLabel === 'function') ? getCurrencyLabel(cc) : cc;
        finalRowsHTML += '<tr class="final-row" style="background:' + (bv>0?'#fef2f2':'#f0fdf4') + ';border-top:2px solid ' + c + ';">' +
            '<td colspan="7" style="text-align:left;color:' + c + ';padding:8px;font-weight:bold;">مانده نهایی حساب ' + lbl + ' (' + l + ')</td>' +
            '<td style="color:' + c + ';text-align:center;padding:8px;font-weight:bold;">' + fn(Math.abs(bv)) + ' ' + sym + '</td>' +
            '<td style="color:' + c + ';text-align:center;padding:8px;font-weight:900;">' + fn(Math.abs(bv)) + ' ' + sym + '</td>' +
            '<td style="padding:8px;">—</td>' +
        '</tr>';
    });
    if (_allBalCodes.length === 0 && personTxs.length > 0) {
        finalRowsHTML += '<tr class="final-row" style="background:#f0fdf4;border-top:2px solid #10b981;">' +
            '<td colspan="7" style="text-align:left;color:#10b981;padding:8px;font-weight:bold;">مانده نهایی حساب</td>' +
            '<td colspan="3" style="color:#10b981;text-align:center;padding:8px;font-weight:bold;">تسویه شده ✅</td>' +
        '</tr>';
    }

    const reportDate = (typeof db.getCurrentDate === 'function') ? db.getCurrentDate() : new Date().toLocaleDateString('fa-IR');
    const reportTime = (function(){ const n=new Date(); return String(n.getHours()).padStart(2,'0')+' : '+String(n.getMinutes()).padStart(2,'0'); })();
    const currencyLabel = (typeof getCurrencyLabel === 'function' ? getCurrencyLabel(person.currency || _baseCur()) : (person.currency || _baseCur()));

    // ---- بیلانس نهایی (به‌روزِ محاسبه‌شده از تمام معاملات) ----
    var _balAfnColor = balanceAFN > 0 ? '#ef4444' : (balanceAFN < 0 ? '#10b981' : '#64748b');
    var _balAfnLabel = balanceAFN > 0 ? 'بدهکار' : (balanceAFN < 0 ? 'طلبکار' : 'تسویه');
    var _balUsdColor = balanceUSD > 0 ? '#ef4444' : (balanceUSD < 0 ? '#10b981' : '#64748b');
    var _balUsdLabel = balanceUSD > 0 ? 'بدهکار' : (balanceUSD < 0 ? 'طلبکار' : 'تسویه');

    // ---- ساخت قالبِ اکسل (راست‌به‌چپِ منظم) از همان رکوردها ----
    function buildExcelHtml() {
        var tdH = 'style="background:' + navy + ';color:#fff;font-weight:bold;border:1px solid ' + navy + ';padding:5px;text-align:center;"';
        var e = '<html xmlns:o="urn:schemas-microsoft-com:office:office" xmlns:x="urn:schemas-microsoft-com:office:excel" xmlns="http://www.w3.org/TR/REC-html40">';
        e += '<head><meta charset="UTF-8">';
        e += '<!--[if gte mso 9]><xml><x:ExcelWorkbook><x:ExcelWorksheets><x:ExcelWorksheet><x:Name>گزارش معاملات</x:Name>';
        e += '<x:WorksheetOptions><x:DisplayRightToLeft/></x:WorksheetOptions></x:ExcelWorksheet></x:ExcelWorksheets></x:ExcelWorkbook></xml><![endif]-->';
        e += '<style>td,th{font-family:Tahoma,sans-serif;font-size:12px;vertical-align:middle;}</style>';
        e += '</head><body dir="rtl">';
        e += '<table dir="rtl" border="1" cellspacing="0" cellpadding="4">';
        // سربرگ فروشگاه
        e += '<tr><td colspan="10" style="background:' + navy + ';color:#fff;font-size:16px;font-weight:bold;text-align:center;padding:8px;">' + esc(storeName) + '</td></tr>';
        e += '<tr><td colspan="10" style="text-align:center;color:' + navy + ';font-weight:bold;padding:4px;">' + esc(storeSlogan) + '</td></tr>';
        e += '<tr><td colspan="10" style="text-align:center;padding:3px;">گزارش معاملات شخص &nbsp;|&nbsp; تاریخ: ' + esc(reportDate) + ' &nbsp;|&nbsp; ساعت: ' + esc(reportTime) + '</td></tr>';
        e += '<tr><td colspan="10"></td></tr>';
        // اطلاعات شخص
        function infoRow(l1, v1, l2, v2) {
            return '<tr><td style="background:#eef3fb;font-weight:bold;">' + esc(l1) + '</td><td colspan="4">' + esc(v1) + '</td>' +
                   '<td style="background:#eef3fb;font-weight:bold;">' + esc(l2) + '</td><td colspan="4">' + esc(v2) + '</td></tr>';
        }
        e += infoRow('نام شخص', person.name || '---', 'دسته بندی', person.category || '---');
        e += infoRow('شماره تماس', person.phone || '---', 'شماره تذکره/شناسایی', person.idNumber || '---');
        e += infoRow('آدرس', person.address || '---', 'ارز', currencyLabel);
        e += infoRow('وضعیت حساب اولیه', person.accountType || 'بدون حساب', 'حساب قبلی', person.previousAccount ? (fn(person.previousAccount) + ' ' + _curSymGlobal(person.currency || _baseCur())) : '---');
        e += infoRow('تاریخ ثبت', person.createdAt || '---', 'یادداشت', person.notes || person.description || '---');
        e += '<tr><td colspan="10"></td></tr>';
        // خلاصهٔ معاملات (مطابق کارت‌های پیش‌نمایش) — شاملِ بیلانس نهایی
        function sumRow(l1, v1, l2, v2) {
            return '<tr><td style="background:#eef3fb;font-weight:bold;">' + esc(l1) + '</td><td colspan="4" style="text-align:center;font-weight:bold;">' + esc(v1) + '</td>' +
                   '<td style="background:#eef3fb;font-weight:bold;">' + esc(l2) + '</td><td colspan="4" style="text-align:center;font-weight:bold;">' + esc(v2) + '</td></tr>';
        }
        e += '<tr><td colspan="10" style="background:' + navy + ';color:#fff;font-weight:bold;text-align:center;padding:5px;">خلاصهٔ معاملات</td></tr>';
        e += sumRow('تعداد کل معاملات', String(personTxs.length), 'مجموع فروش', fn(totalSalesAFN) + ' ؋ / ' + fn(totalSalesUSD) + ' $');
        e += sumRow('مجموع خرید', fn(totalPurchasesAFN) + ' ؋ / ' + fn(totalPurchasesUSD) + ' $', 'مجموع دریافتی', fn(totalReceiptsAFN) + ' ؋ / ' + fn(totalReceiptsUSD) + ' $');
        e += sumRow('مجموع پرداختی', fn(totalPaymentsAFN) + ' ؋ / ' + fn(totalPaymentsUSD) + ' $', 'بیلانس نهایی افغانی', fn(Math.abs(balanceAFN)) + ' ؋ (' + _balAfnLabel + ')');
        e += sumRow('بیلانس نهایی دالر', fn(Math.abs(balanceUSD)) + ' $ (' + _balUsdLabel + ')', '', '');
        // ارزهای سوم به بعد — یک سطرِ بیلانسِ نهایی برای هر ارز (پویا)
        Object.keys(balMap).forEach(function (cc) {
            if (cc === 'AFN' || cc === 'USD') return;
            var bv = balMap[cc] || 0;
            if (Math.abs(bv) <= 1e-7) return;
            var sym = (typeof _curSymGlobal === 'function') ? _curSymGlobal(cc) : cc;
            var lbl = (typeof getCurrencyLabel === 'function') ? getCurrencyLabel(cc) : cc;
            var lx = bv > 0 ? 'بدهکار' : (bv < 0 ? 'طلبکار' : 'تسویه');
            e += sumRow('بیلانس نهایی ' + lbl, fn(Math.abs(bv)) + ' ' + sym + ' (' + lx + ')', '', '');
        });
        e += '<tr><td colspan="10"></td></tr>';
        // سرستون جدول
        e += '<tr>' +
            '<td ' + tdH + '>ردیف</td>' +
            '<td ' + tdH + '>تاریخ</td>' +
            '<td ' + tdH + '>شماره بل</td>' +
            '<td ' + tdH + '>نوع</td>' +
            '<td ' + tdH + '>شرح</td>' +
            '<td ' + tdH + '>تعداد</td>' +
            '<td ' + tdH + '>قیمت واحد</td>' +
            '<td ' + tdH + '>مبلغ</td>' +
            '<td ' + tdH + '>مانده حساب</td>' +
            '<td ' + tdH + '>اطلاعات بیشتر</td>' +
        '</tr>';
        // ردیف‌ها — بدونِ rowspan (اکسل با merge عمودیِ HTML دچار خطای «مشکل در محتوا» و حذفِ ردیف می‌شود)
        // هر قلم یک ردیفِ کامل و مستقل؛ سلول‌های مشترک فقط در ردیفِ نخستِ هر معامله پر می‌شوند.
        records.forEach(function(rec) {
            var moreCell = (rec.moreLines && rec.moreLines.length) ? rec.moreLines.join(' — ') : (rec.more || '—');
            var balCell = esc(rec.balStr) + ' (' + esc(rec.balLabel) + ')';
            if (rec.items && rec.items.length) {
                for (var i = 0; i < rec.items.length; i++) {
                    var first = (i === 0);
                    e += '<tr>' +
                        '<td style="text-align:center;">' + (first ? rec.idx : '') + '</td>' +
                        '<td style="text-align:center;">' + (first ? esc(rec.dateStr) : '') + '</td>' +
                        '<td style="text-align:center;">' + (first ? esc(rec.billNumber) : '') + '</td>' +
                        '<td style="text-align:center;">' + (first ? esc(rec.typeLabel) : '') + '</td>' +
                        '<td style="text-align:right;">' + esc(rec.items[i].name) + '</td>' +
                        '<td style="text-align:center;">' + fn(rec.items[i].qty) + (rec.items[i].unit ? ' ' + esc(rec.items[i].unit) : '') + '</td>' +
                        '<td style="text-align:center;">' + fn(rec.items[i].price) + '</td>' +
                        '<td style="text-align:center;">' + (first ? esc(rec.amountStr) : '') + '</td>' +
                        '<td style="text-align:center;color:' + rec.balColor + ';font-weight:bold;">' + (first ? balCell : '') + '</td>' +
                        '<td style="text-align:right;">' + (first ? esc(moreCell) : '') + '</td>' +
                    '</tr>';
                }
            } else {
                e += '<tr>' +
                    '<td style="text-align:center;">' + rec.idx + '</td>' +
                    '<td style="text-align:center;">' + esc(rec.dateStr) + '</td>' +
                    '<td style="text-align:center;">' + esc(rec.billNumber) + '</td>' +
                    '<td style="text-align:center;">' + esc(rec.typeLabel) + '</td>' +
                    '<td style="text-align:right;">' + esc(rec.desc || '-') + '</td>' +
                    '<td></td>' +
                    '<td></td>' +
                    '<td style="text-align:center;">' + esc(rec.amountStr) + '</td>' +
                    '<td style="text-align:center;color:' + rec.balColor + ';font-weight:bold;">' + balCell + '</td>' +
                    '<td style="text-align:right;">' + esc(moreCell) + '</td>' +
                '</tr>';
            }
        });
        // مانده نهایی — کاملاً پویا برای هر ارزِ دارای بلانس (ارزِ پایه اول)
        var _pdfBase = _baseCur();
        var _pdfXtra = Object.keys(balMap).filter(function (cc) { return Math.abs(balMap[cc] || 0) > 1e-7; });
        _pdfXtra.sort(function (a, b) { if (a === _pdfBase) return -1; if (b === _pdfBase) return 1; return 0; });
        _pdfXtra.forEach(function (cc) {
            var bv = balMap[cc] || 0;
            var lx = bv > 0 ? 'بدهکار' : 'طلبکار';
            var sym = (typeof _curSymGlobal === 'function') ? _curSymGlobal(cc) : cc;
            var lbl = (typeof getCurrencyLabel === 'function') ? getCurrencyLabel(cc) : cc;
            e += '<tr><td colspan="7" style="text-align:left;font-weight:bold;background:#f1f5f9;">مانده نهایی حساب ' + lbl + ' (' + lx + ')</td>' +
                 '<td colspan="3" style="text-align:center;font-weight:bold;background:#f1f5f9;">' + fn(Math.abs(bv)) + ' ' + sym + '</td></tr>';
        });
        if (_pdfXtra.length === 0 && personTxs.length > 0) {
            e += '<tr><td colspan="10" style="text-align:center;font-weight:bold;background:#f0fdf4;color:#10b981;">مانده نهایی حساب: تسویه شده</td></tr>';
        }
        e += '</table></body></html>';
        return e;
    }
    const excelHtml = buildExcelHtml();
    const excelName = 'گزارش-معاملات-' + (person.name || 'شخص');

    // مسیرِ پایه برای بارگذاریِ فونت و آیکن‌ها در پنجرهٔ گزارش
    var baseHref = '';
    try { baseHref = (location && location.href) ? location.href.replace(/[?#].*$/, '').replace(/[^\/]*$/, '') : ''; } catch (e) { baseHref = ''; }

    const html = `<!DOCTYPE html>
<html dir="rtl" lang="fa">
<head>
    <meta charset="UTF-8">
    <title>گزارش معاملات - ${esc(person.name)}</title>
    ${baseHref ? `<base href="${baseHref}">` : ''}
    <link rel="stylesheet" href="assets/css/all.min.css">
    <link rel="stylesheet" href="assets/fonts/vazirmatn.css">
    <style>
        * { box-sizing: border-box; margin: 0; padding: 0; }
        @page { size: A4 landscape; margin: 8mm; }
        @media print {
            body { margin: 0; padding: 0; background: #fff; -webkit-print-color-adjust: exact; print-color-adjust: exact; }
            .no-print { display: none !important; }
            /* جلوگیری از بریده‌شدنِ ردیف‌ها در چاپ/PDF: کانتینر نباید محتوای صفحاتِ بعد را قیچی کند */
            .bill-wrap { overflow: visible !important; border: none !important; border-radius: 0 !important; max-width: 100% !important; box-shadow: none !important; }
            .items-table thead { display: table-header-group; }
            .items-table tbody { page-break-inside: avoid; }
            .items-table tr { page-break-inside: avoid; }
        }
        body {
            font-family: ${fontFamily};
            font-size: ${baseFont}px;
            color: #1a2533;
            background: #eceff3;
            direction: rtl;
            padding: 6mm;
            -webkit-print-color-adjust: exact;
            print-color-adjust: exact;
        }
        .bill-wrap {
            width: 100%;
            max-width: 285mm;
            margin: 0 auto;
            background: #fff;
            border: 1px solid ${navy};
            border-radius: 8px;
            overflow: hidden;
        }
        /* هدر — دقیقاً از بل: پس‌زمینهٔ سفید، خط طلاییِ پایین، نامِ سرمه‌ای */
        .rep-hdr {
            position: relative;
            display: flex;
            align-items: stretch;
            gap: 12px;
            padding: 14px 18px;
            background: #fff;
            border-bottom: 3px solid ${gold};
        }
        .rep-hdr::after {
            content: ""; position: absolute; top: 0; right: 0; width: 42%; height: 100%;
            background: ${navy}; clip-path: polygon(18% 0, 100% 0, 100% 100%, 0 100%); z-index: 0; opacity: 0.06;
        }
        .rep-logo { flex: 0 0 auto; width: 110px; display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 4px; z-index: 1; }
        .rep-logo-ph { width: 62px; height: 62px; border-radius: 10px; background: ${navy}; color: ${gold}; display: flex; align-items: center; justify-content: center; font-size: 26px; }
        .rep-center { flex: 1; text-align: center; z-index: 1; display: flex; flex-direction: column; justify-content: center; gap: 3px; }
        .rep-name { font-size: ${titleFont}px; font-weight: 900; color: ${navy}; letter-spacing: 0.5px; }
        .rep-name-en { font-size: ${fEnName}px; font-weight: 700; color: ${gold}; letter-spacing: 0.5px; }
        .rep-diamond { color: ${gold}; font-size: 9px; margin: 2px 0; }
        .rep-slogan { font-size: ${Math.max(9, baseFont - 1)}px; color: #55606e; display: flex; align-items: center; justify-content: center; gap: 6px; }
        .rep-slogan i { color: ${gold}; }
        .rep-label {
            flex: 0 0 auto; z-index: 1; align-self: center;
            background: ${navy}; color: ${onPrimary};
            border: 2px solid ${gold}; border-radius: 8px;
            padding: 10px 16px; text-align: center; min-width: 120px;
        }
        .rep-label .lbl { font-size: 12px; font-weight: bold; letter-spacing: 2px; color: ${gold}; }
        .rep-label .val { font-size: 14px; font-weight: 900; margin-top: 3px; color: ${onPrimary}; }
        .datetime-row {
            background: #f0f3f7; border-bottom: 1px solid #c8d0da;
            display: flex; justify-content: flex-end; gap: 26px; padding: 6px 18px; font-size: 11px;
        }
        .datetime-row .dt-item { display: flex; align-items: center; gap: 6px; }
        .datetime-row .dt-item i { color: ${navy}; }
        .person-info-section { border-bottom: 1px solid #c8d0da; padding: 12px 18px; }
        .person-info-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 8px 24px; font-size: 11px; line-height: 2; }
        .person-info-grid .field-line { display: flex; align-items: center; gap: 6px; }
        .field-line .fi-ico { width: 22px; height: 22px; border-radius: 50%; background: ${navy}; color: ${onPrimary}; display: inline-flex; align-items: center; justify-content: center; font-size: 10px; flex: 0 0 auto; }
        .person-info-grid .field-label { font-weight: bold; white-space: nowrap; color: ${navy}; }
        .person-info-grid .field-val { border-bottom: 1px dotted #888; flex: 1; min-width: 80px; padding-bottom: 1px; }
        .summary-section { border-bottom: 1px solid #c8d0da; padding: 10px 18px; }
        .summary-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 8px; font-size: 11px; }
        .summary-card { background: #f8fafc; border: 1px solid #e2e8f0; border-radius: 6px; padding: 8px 10px; text-align: center; }
        .summary-card .s-label { font-size: 10px; color: #64748b; margin-bottom: 3px; display: flex; align-items: center; justify-content: center; gap: 5px; }
        .summary-card .s-value { font-size: 13px; font-weight: 700; }
        .items-table { width: 100%; border-collapse: collapse; font-size: 10.5px; }
        .items-table thead tr { background: ${navy}; color: #fff; }
        .items-table thead th { padding: 7px 4px; text-align: center; border: 1px solid ${navy}; font-weight: bold; }
        .items-table thead th i { margin-inline-end: 4px; opacity: 0.9; }
        .items-table tbody tr:nth-child(even) { background: #f4f6fa; }
        .items-table tbody td { border: 1px solid #b0bbcc; padding: 5px 4px; text-align: center; vertical-align: middle; }
        .items-table .c-desc { text-align: right; }
        .items-table .c-qty .u { color: #6b7688; font-size: 0.85em; }
        .items-table .c-more { text-align: right; font-size: 9.5px; color: #44506a; }
        .items-table .c-more .more-line { padding: 1px 0; }
        .type-badge { color: #fff; padding: 2px 8px; border-radius: 4px; font-size: 10px; display: inline-block; }
        .bill-ft {
            display: flex; align-items: center; justify-content: space-between;
            background: ${navy}; color: ${onPrimary}; padding: 10px 18px; gap: 12px;
        }
        .bill-ft .ft-thanks .t1 { font-size: 14px; font-weight: 800; }
        .bill-ft .ft-thanks .t2 { font-size: 11px; color: ${gold}; margin-top: 2px; }
        .bill-ft .ft-contact { display: flex; flex-direction: column; gap: 4px; font-size: 11px; }
        .bill-ft .ft-line { display: flex; align-items: center; gap: 7px; }
        .bill-ft .ft-line i { color: ${onPrimary}; width: 22px; height: 22px; border-radius: 50%; background: rgba(255,255,255,0.14); display: inline-flex; align-items: center; justify-content: center; font-size: 10px; }
        /* نوار دکمه‌ها — مدرن، الگو از دکمه‌های ذخیره تغییرات */
        .rep-actions { display: flex; justify-content: center; align-items: center; gap: 14px; padding: 18px 12px 8px; }
        .rep-btn {
            border: none; border-radius: 9px; padding: 11px 24px; font-size: 14px; font-weight: 700;
            cursor: pointer; font-family: inherit; color: #fff; display: inline-flex; align-items: center; gap: 8px;
            box-shadow: 0 2px 8px rgba(0,0,0,0.16); transition: transform .12s, box-shadow .12s, filter .12s;
        }
        .rep-btn:hover { transform: translateY(-1px); box-shadow: 0 4px 14px rgba(0,0,0,0.22); filter: brightness(1.05); }
        .rep-btn-print { background: ${navy}; }
        .rep-share-wrap { position: relative; display: inline-block; }
        .rep-btn-share { background: linear-gradient(135deg, ${navy} 0%, ${navyDark} 100%); border: 1px solid ${gold}; }
        .rep-share-menu {
            display: none; position: absolute; top: calc(100% + 8px); left: 50%; transform: translateX(-50%);
            background: #fff; border: 1px solid #d0d5dd; border-radius: 12px; box-shadow: 0 10px 28px rgba(0,0,0,0.22);
            padding: 10px; z-index: 100000; min-width: 220px; flex-direction: column; gap: 8px;
        }
        .rep-share-menu.open { display: flex; }
        .rep-menu-item {
            border: none; border-radius: 8px; padding: 11px 14px; font-size: 13px; font-weight: 700; cursor: pointer;
            font-family: inherit; color: #fff; display: flex; align-items: center; gap: 9px; text-align: right; width: 100%;
        }
        .rep-menu-item i { font-size: 16px; }
        .rep-menu-pdf { background: #b91c1c; }
        .rep-menu-excel { background: #15803d; }
        .rep-menu-item:hover { filter: brightness(1.08); }
    </style>
</head>
<body>
<div class="rep-actions no-print">
    <button type="button" class="rep-btn rep-btn-print" onclick="window.print()"><i class="fas fa-print"></i> چاپ گزارش</button>
    <span class="rep-share-wrap">
        <button type="button" id="rep-share-btn" class="rep-btn rep-btn-share" onclick="__repToggleShare(event)"><i class="fas fa-share-alt"></i> اشتراک‌گذاری</button>
        <div id="rep-share-menu" class="rep-share-menu">
            <button type="button" class="rep-menu-item rep-menu-pdf" onclick="__repDownloadPdf()"><i class="fas fa-file-pdf"></i> دانلود PDF</button>
            <button type="button" class="rep-menu-item rep-menu-wa" onclick="__repShareWa()"><i class="fab fa-whatsapp"></i> ارسال به واتساپ</button>
            <div style="font-size:10.5px;color:#64748b;text-align:right;line-height:1.7;padding:2px 8px;">پس از ذخیرهٔ PDF، واتساپِ کامپیوتر باز می‌شود؛ مخاطب را انتخاب و فایلِ PDF را پیوست و ارسال کنید.</div>
            <button type="button" class="rep-menu-item rep-menu-excel" onclick="__repDownloadExcel()"><i class="fas fa-file-excel"></i> دانلود اکسل</button>
        </div>
    </span>
</div>

<div class="bill-wrap">
    <div class="rep-hdr">
        <div class="rep-logo">${logoHtml}</div>
        <div class="rep-center">
            <div class="rep-name">${esc(storeName)}</div>
            ${storeNameEn ? `<div class="rep-name-en">${esc(storeNameEn)}</div>` : ''}
            <div class="rep-diamond">◆</div>
            <div class="rep-slogan"><i class="fas fa-gem"></i> ${esc(storeSlogan)} <i class="fas fa-gem"></i></div>
        </div>
        <div class="rep-label">
            <div class="lbl">گزارش</div>
            <div class="val">معاملات شخص</div>
        </div>
    </div>

    <div class="datetime-row">
        <div class="dt-item"><i class="fas fa-clock"></i> ساعت : <span>${reportTime}</span></div>
        <div class="dt-item"><i class="fas fa-calendar-alt"></i> تاریخ گزارش : <span>${reportDate}</span></div>
    </div>

    <div class="person-info-section">
        <div class="person-info-grid">
            <div class="field-line"><span class="fi-ico"><i class="fas fa-user"></i></span><span class="field-label">نام شخص :</span> <span class="field-val">${esc(person.name || '---')}</span></div>
            <div class="field-line"><span class="fi-ico"><i class="fas fa-tags"></i></span><span class="field-label">دسته بندی :</span> <span class="field-val">${esc(person.category || '---')}</span></div>
            <div class="field-line"><span class="fi-ico"><i class="fas fa-phone"></i></span><span class="field-label">شماره تماس :</span> <span class="field-val">${esc(person.phone || '---')}</span></div>
            <div class="field-line"><span class="fi-ico"><i class="fas fa-id-card"></i></span><span class="field-label">شماره تذکره/شناسایی :</span> <span class="field-val">${esc(person.idNumber || '---')}</span></div>
            <div class="field-line"><span class="fi-ico"><i class="fas fa-map-marker-alt"></i></span><span class="field-label">آدرس :</span> <span class="field-val">${esc(person.address || '---')}</span></div>
            <div class="field-line"><span class="fi-ico"><i class="fas fa-coins"></i></span><span class="field-label">ارز :</span> <span class="field-val">${esc(currencyLabel)}</span></div>
            <div class="field-line"><span class="fi-ico"><i class="fas fa-balance-scale"></i></span><span class="field-label">وضعیت حساب اولیه :</span> <span class="field-val">${esc(person.accountType || 'بدون حساب')}</span></div>
            <div class="field-line"><span class="fi-ico"><i class="fas fa-wallet"></i></span><span class="field-label">حساب قبلی :</span> <span class="field-val">${person.previousAccount ? (fn(person.previousAccount) + ' ' + _curSymGlobal(person.currency || _baseCur())) : '---'}</span></div>
            <div class="field-line"><span class="fi-ico"><i class="fas fa-calendar-plus"></i></span><span class="field-label">تاریخ ثبت :</span> <span class="field-val">${esc(person.createdAt || '---')}</span></div>
            <div class="field-line"><span class="fi-ico"><i class="fas fa-sticky-note"></i></span><span class="field-label">یادداشت :</span> <span class="field-val">${esc(person.notes || person.description || '---')}</span></div>
        </div>
    </div>

    <div class="summary-section">
        <div class="summary-grid">
            <div class="summary-card">
                <div class="s-label"><i class="fas fa-exchange-alt"></i> تعداد کل معاملات</div>
                <div class="s-value">${personTxs.length}</div>
            </div>
            <div class="summary-card">
                <div class="s-label"><i class="fas fa-arrow-up"></i> مجموع فروش (؋)</div>
                <div class="s-value" style="color:#10b981;">${fn(totalSalesAFN)}</div>
            </div>
            <div class="summary-card">
                <div class="s-label"><i class="fas fa-arrow-up"></i> مجموع فروش ($)</div>
                <div class="s-value" style="color:#10b981;">${fn(totalSalesUSD)}</div>
            </div>
            <div class="summary-card">
                <div class="s-label"><i class="fas fa-arrow-down"></i> مجموع خرید (؋)</div>
                <div class="s-value" style="color:#3b82f6;">${fn(totalPurchasesAFN)}</div>
            </div>
            <div class="summary-card">
                <div class="s-label"><i class="fas fa-arrow-down"></i> مجموع خرید ($)</div>
                <div class="s-value" style="color:#3b82f6;">${fn(totalPurchasesUSD)}</div>
            </div>
            <div class="summary-card">
                <div class="s-label"><i class="fas fa-hand-holding-usd"></i> مجموع دریافتی (؋)</div>
                <div class="s-value" style="color:#8b5cf6;">${fn(totalReceiptsAFN)}</div>
            </div>
            <div class="summary-card">
                <div class="s-label"><i class="fas fa-hand-holding-usd"></i> مجموع دریافتی ($)</div>
                <div class="s-value" style="color:#8b5cf6;">${fn(totalReceiptsUSD)}</div>
            </div>
            <div class="summary-card">
                <div class="s-label"><i class="fas fa-money-check-alt"></i> مجموع پرداختی (؋)</div>
                <div class="s-value" style="color:#f59e0b;">${fn(totalPaymentsAFN)}</div>
            </div>
            <div class="summary-card">
                <div class="s-label"><i class="fas fa-money-check-alt"></i> مجموع پرداختی ($)</div>
                <div class="s-value" style="color:#f59e0b;">${fn(totalPaymentsUSD)}</div>
            </div>
            <div class="summary-card" style="border:1.5px solid ${navy};background:#eef3fb;">
                <div class="s-label" style="color:${navy};font-weight:700;"><i class="fas fa-balance-scale"></i> بیلانس نهایی افغانی</div>
                <div class="s-value" style="color:${_balAfnColor};">${fn(Math.abs(balanceAFN))} ؋ <small style="font-size:9px;">(${_balAfnLabel})</small></div>
            </div>
            <div class="summary-card" style="border:1.5px solid ${navy};background:#eef3fb;">
                <div class="s-label" style="color:${navy};font-weight:700;"><i class="fas fa-balance-scale"></i> بیلانس نهایی دالر</div>
                <div class="s-value" style="color:${_balUsdColor};">${fn(Math.abs(balanceUSD))} $ <small style="font-size:9px;">(${_balUsdLabel})</small></div>
            </div>
            ${(function(){
                var extra = '', seen = { AFN:1, USD:1 }, codes = {};
                [salesMap, purchasesMap, receiptsMap, paymentsMap, returnsMap, balMap].forEach(function(m){ Object.keys(m||{}).forEach(function(c){ codes[c]=1; }); });
                Object.keys(codes).forEach(function(c){
                    if (seen[c]) return;
                    var sy = _curSymGlobal(c);
                    var s = salesMap[c]||0, p = purchasesMap[c]||0, r = receiptsMap[c]||0, pm = paymentsMap[c]||0, b = balMap[c]||0;
                    if (!(s||p||r||pm||b)) return;
                    var bColor = b>0?'#ef4444':(b<0?'#10b981':'#64748b');
                    var bLabel = b>0?'بدهکار':(b<0?'طلبکار':'تسویه');
                    extra += '<div class="summary-card"><div class="s-label"><i class="fas fa-arrow-up"></i> مجموع فروش ('+sy+')</div><div class="s-value" style="color:#10b981;">'+fn(s)+'</div></div>'
                        + '<div class="summary-card"><div class="s-label"><i class="fas fa-arrow-down"></i> مجموع خرید ('+sy+')</div><div class="s-value" style="color:#3b82f6;">'+fn(p)+'</div></div>'
                        + '<div class="summary-card"><div class="s-label"><i class="fas fa-hand-holding-usd"></i> مجموع دریافتی ('+sy+')</div><div class="s-value" style="color:#8b5cf6;">'+fn(r)+'</div></div>'
                        + '<div class="summary-card"><div class="s-label"><i class="fas fa-money-check-alt"></i> مجموع پرداختی ('+sy+')</div><div class="s-value" style="color:#f59e0b;">'+fn(pm)+'</div></div>'
                        + '<div class="summary-card" style="border:1.5px solid '+navy+';background:#eef3fb;"><div class="s-label" style="color:'+navy+';font-weight:700;"><i class="fas fa-balance-scale"></i> بیلانس نهایی '+_curLabelGlobal(c)+'</div><div class="s-value" style="color:'+bColor+';">'+fn(Math.abs(b))+' '+sy+' <small style="font-size:9px;">('+bLabel+')</small></div></div>';
                });
                return extra;
            })()}
        </div>
    </div>

    <table class="items-table">
        <thead>
            <tr>
                <th style="width:4%">ردیف</th>
                <th style="width:11%"><i class="fas fa-calendar-alt"></i>تاریخ</th>
                <th style="width:8%"><i class="fas fa-hashtag"></i>شماره بل</th>
                <th style="width:9%"><i class="fas fa-exchange-alt"></i>نوع</th>
                <th style="width:20%"><i class="fas fa-box"></i>شرح</th>
                <th style="width:7%"><i class="fas fa-sort-numeric-up"></i>تعداد</th>
                <th style="width:9%"><i class="fas fa-tag"></i>قیمت واحد</th>
                <th style="width:9%"><i class="fas fa-coins"></i>مبلغ</th>
                <th style="width:9%"><i class="fas fa-balance-scale"></i>مانده حساب</th>
                <th style="width:14%"><i class="fas fa-info-circle"></i>اطلاعات بیشتر</th>
            </tr>
        </thead>
        ${txRowsHTML}
        <tbody class="final-group">
            ${finalRowsHTML}
        </tbody>
    </table>

    <div class="bill-ft">
        <div class="ft-thanks">
            <div class="t1">${esc(footerTitle)}</div>
            ${footerSubtitle ? `<div class="t2">${esc(footerSubtitle)}</div>` : ''}
        </div>
        <div class="ft-contact">
            ${storePhone ? `<div class="ft-line"><i class="fas fa-phone-alt"></i><span>${esc(storePhone)}${storePhone2 ? ' - ' + esc(storePhone2) : ''}</span></div>` : ''}
            ${storeAddress ? `<div class="ft-line"><i class="fas fa-map-marker-alt"></i><span>${esc(storeAddress)}</span></div>` : ''}
            ${storeWebsite ? `<div class="ft-line"><i class="fas fa-globe"></i><span>${esc(storeWebsite)}</span></div>` : ''}
        </div>
    </div>
</div>
</body>
</html>`;

    // اسکریپتِ پنجرهٔ گزارش: منوی اشتراک‌گذاری + دانلود PDF/اکسل (بدون template literal تا از تداخل جلوگیری شود)
    var scriptBlock = '<scr' + 'ipt>'
        + 'var __EXCEL_HTML=' + JSON.stringify(excelHtml) + ';'
        + 'var __EXCEL_NAME=' + JSON.stringify(excelName) + ';'
        + 'function __repToggleShare(ev){ if(ev){ev.stopPropagation();} var m=document.getElementById("rep-share-menu"); if(m){ m.classList.toggle("open"); } }'
        + 'function __repCloseShare(){ var m=document.getElementById("rep-share-menu"); if(m){ m.classList.remove("open"); } }'
        + 'function __repDownloadPdf(){ __repCloseShare(); try{ document.title=__EXCEL_NAME; }catch(e){} window.print(); }'
        + 'function __repShareWa(){ __repCloseShare(); try{ if(typeof __EXCEL_NAME!=="undefined" && __EXCEL_NAME) document.title=__EXCEL_NAME; }catch(e){} try{ if(window.opener && typeof window.opener.__jouyaSharePdfToWhatsApp==="function"){ window.opener.__jouyaSharePdfToWhatsApp("<!DOCTYPE html>"+document.documentElement.outerHTML, (typeof __EXCEL_NAME!=="undefined" && __EXCEL_NAME ? __EXCEL_NAME : (document.title||"report"))); return; } }catch(e){} window.print(); try{ var a=document.createElement("a"); a.href="whatsapp://send"; document.body.appendChild(a); a.click(); document.body.removeChild(a); }catch(e){} }'
        + 'function __repDownloadExcel(){ __repCloseShare(); try {'
        +   'var blob=new Blob(["\\ufeff"+__EXCEL_HTML],{type:"application/vnd.ms-excel;charset=utf-8"});'
        +   'var url=URL.createObjectURL(blob); var a=document.createElement("a"); a.href=url; a.download=__EXCEL_NAME+".xls";'
        +   'document.body.appendChild(a); a.click(); document.body.removeChild(a); setTimeout(function(){URL.revokeObjectURL(url);},1500);'
        + ' } catch(e){ alert("خطا در ساخت فایل اکسل"); } }'
        + 'document.addEventListener("click",function(ev){ var m=document.getElementById("rep-share-menu"); var b=document.getElementById("rep-share-btn"); if(!m||!m.classList.contains("open")) return; if(m.contains(ev.target)) return; if(b&&b.contains(ev.target)) return; m.classList.remove("open"); });'
        + '</scr' + 'ipt>';

    // موبایل: به‌جای پنجرهٔ جدا، در اورلیِ درون‌برنامه (اشتراکِ فایلِ سالم)
    if (__jouyaMaybeMobilePreview(html, excelName)) return;

    var finalHtml = html.replace('</body>', scriptBlock + '</body>');

    var w = window.open('', '_blank', 'width=1150,height=880');
    if (!w) {
        try { showMessage('خطا', 'پنجره گزارش مسدود شد. لطفاً pop-up را در مرورگر مجاز کنید.'); }
        catch (e) { alert('پنجره گزارش مسدود شد. لطفاً pop-up را مجاز کنید.'); }
        return;
    }
    w.document.write(finalHtml);
    w.document.close();
    w.focus();
}

// ==================== گزارش معاملات حساب ====================
function generateCashboxReport(cashboxId) {
    const cashbox = db.getCashboxes().find(c => c.id == cashboxId);
    if (!cashbox) { showMessage('خطا', 'حساب یافت نشد'); return; }

    // ---- تنظیمات بل: رنگ/فونت/مشخصاتِ بالا و پایین دقیقاً از بل خوانده می‌شود (یکنواخت با گزارشِ شخص) ----
    const settings = db.getSettings() || {};
    var S = settings;
    var navy = S.billPrimaryColor || '#1b2a4a';
    var gold = S.billAccentColor || '#c8963c';
    var _contrastOn = function (hex) {
        try {
            var h = String(hex || '').replace('#', '');
            if (h.length === 3) h = h[0] + h[0] + h[1] + h[1] + h[2] + h[2];
            var r = parseInt(h.substr(0, 2), 16), g = parseInt(h.substr(2, 2), 16), b = parseInt(h.substr(4, 2), 16);
            if (isNaN(r) || isNaN(g) || isNaN(b)) return '#ffffff';
            var lum = (0.299 * r + 0.587 * g + 0.114 * b) / 255;
            return lum > 0.6 ? '#1a2533' : '#ffffff';
        } catch (e) { return '#ffffff'; }
    };
    var _shade = function (hex, percent) {
        try {
            var h = String(hex || '').replace('#', '');
            if (h.length === 3) h = h[0] + h[0] + h[1] + h[1] + h[2] + h[2];
            var r = parseInt(h.substr(0, 2), 16), g = parseInt(h.substr(2, 2), 16), b = parseInt(h.substr(4, 2), 16);
            if (isNaN(r) || isNaN(g) || isNaN(b)) return hex;
            var t = percent < 0 ? 0 : 255, p = Math.abs(percent) / 100;
            var nr = Math.round((t - r) * p) + r, ng = Math.round((t - g) * p) + g, nb = Math.round((t - b) * p) + b;
            return '#' + ((1 << 24) + (nr << 16) + (ng << 8) + nb).toString(16).slice(1);
        } catch (e) { return hex; }
    };
    var onPrimary = _contrastOn(navy);
    var navyDark = _shade(navy, -18);
    var _fontMap = {
        vazirmatn: "'Vazirmatn', Tahoma, Arial, sans-serif",
        tahoma: "Tahoma, 'Vazirmatn', Arial, sans-serif",
        arial: "Arial, 'Vazirmatn', Helvetica, sans-serif",
        times: "'Times New Roman', 'Vazirmatn', serif",
        courier: "'Courier New', 'Vazirmatn', monospace",
        nazanin: "'B Nazanin', 'Nazanin', 'Vazirmatn', Tahoma, serif"
    };
    var fontFamily = _fontMap[S.billFontFamily] || _fontMap.vazirmatn;
    var baseFont = parseFloat(S.billBaseFontSize) || 12;
    var titleFont = parseFloat(S.billTitleFontSize) || 26;
    var fEnName = Math.max(10, Math.round(titleFont * 0.55));

    const storeName = S.billStoreName || S.storeName || 'نام دوکان شما';
    const storeNameEn = S.billStoreNameEn || '';
    const storeSlogan = S.billSlogan || S.invoiceHeader || 'عرضه کننده انواع کالا های با کیفیت';
    const storePhone = S.billPhone || S.storePhone || '';
    const storePhone2 = S.storePhone2 || '';
    const storeAddress = S.billAddress || S.storeAddress || '';
    const storeWebsite = S.storeWebsite || '';
    const footerTitle = S.billFooterTitle || 'از اعتماد شما سپاسگزاریم';
    const footerSubtitle = (S.billFooterSubtitle != null) ? S.billFooterSubtitle : (S.invoiceFooter || 'کیفیت بهتر، قیمت مناسب، خدمت صادقانه');
    const logoSrc = S.billLogo || S.storeLogo || '';
    const logoHtml = logoSrc
        ? `<img src="${logoSrc}" alt="لوگو" style="max-height:80px;max-width:100px;object-fit:contain;">`
        : `<div class="rep-logo-ph"><i class="fas fa-store"></i></div>`;

    const fn = (v) => {
        const n = parseFloat(v) || 0;
        return new Intl.NumberFormat((typeof getNumberSystem === 'function' && getNumberSystem() === 'en') ? 'en-US' : 'fa-IR').format(n);
    };
    const esc = (s) => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');

    const transactions = db.getTransactions().filter(t => t.cashboxId == cashboxId);
    const expenses = db.getExpenses().filter(e => e.cashboxId == cashboxId);

    var cashboxTxLogs = [];
    try { cashboxTxLogs = JSON.parse(localStorage.getItem('cashboxTransactions') || '[]'); } catch(e) { cashboxTxLogs = []; }
    if (!Array.isArray(cashboxTxLogs)) cashboxTxLogs = [];
    var relatedLogs = cashboxTxLogs.filter(function(log){ return log.cashboxId == cashboxId; });

    const allItems = [
        ...transactions.map(t => {
            var _txCur = t.currency || _baseCur();
            var _txAmount = parseFloat(t.totalAmount || t.amount || 0);
            if (t.type === 'فروش') {
                _txAmount = (typeof _engCashPaidFor === 'function') ? _engCashPaidFor(t, 'cash') : parseFloat(t.cashAfn || 0);
            } else if (t.type === 'خرید') {
                _txAmount = ((typeof _engCashPaidFor === 'function') ? _engCashPaidFor(t, 'paid') : parseFloat(t.paidAfn || t.cashAfn || 0)) || parseFloat(t.totalAmount || t.amount || 0);
            }
            return {
                date: t.date || '',
                createdAt: t.createdAt || '',
                type: t.type,
                person: t.customerName || t.supplierName || t.personName || '-',
                amount: _txAmount,
                currency: _txCur,
                desc: t.billNumber || t.notes || '-',
                billNumber: t.billNumber || '-'
            };
        }),
        ...expenses.map(e => ({
            date: e.date || '',
            createdAt: e.createdAt || '',
            type: 'مصرف',
            person: '-',
            amount: parseFloat(e.amount || 0),
            currency: e.currency || _baseCur(),
            desc: e.title || e.notes || '-',
            billNumber: '-'
        })),
        ...relatedLogs.filter(function(log){
            return log.type === 'deposit_in' || log.type === 'deposit_out' || log.type === 'deposit_external'
                || log.type === 'withdraw_external' || log.type === 'shipping_charge'
                || log.type === 'transfer_in' || log.type === 'transfer_out';
        }).map(function(log){
            var typeLabel = ({
                'deposit_in': 'اضافه به صندوق',
                'deposit_out': 'برداشت از حساب',
                'deposit_external': 'ورود مبلغ خارجی',
                'withdraw_external': 'برداشت مبلغ از حساب',
                'shipping_charge': 'هزینه حمل و نقل',
                'transfer_in': 'انتقال ورودی',
                'transfer_out': 'انتقال خروجی'
            })[log.type] || log.type;
            return {
                date: log.datetime || log.date || '',
                createdAt: log.createdAt || log.datetime || '',
                type: typeLabel,
                person: log.relatedCashboxName || '-',
                amount: parseFloat(log.amount || 0),
                currency: log.currency || _baseCur(),
                desc: log.description || log.notes || '-',
                billNumber: '-'
            };
        })
    ];

    allItems.sort(function(a, b) {
        var da = a.createdAt || a.date || '';
        var db_ = b.createdAt || b.date || '';
        return da.localeCompare(db_);
    });

    let txRowsHTML = '';
    // مانده و مجموع‌ها به تفکیکِ هر ارز (گزارشِ چند-ارزی مانندِ گزارشِ شخص)
    var _runByCur = {};
    var _inByCur = {}, _outByCur = {};

    allItems.forEach((item, idx) => {
        var _ic = item.currency || _baseCur();
        var _icLbl = (typeof getCurrencyLabel === 'function') ? getCurrencyLabel(_ic) : _ic;
        let isIncome = false;
        if (item.type === 'فروش' || item.type === 'دریافت' || item.type === 'اضافه به صندوق' || item.type === 'ورود مبلغ خارجی' || item.type === 'انتقال ورودی') {
            isIncome = true;
            _runByCur[_ic] = (_runByCur[_ic] || 0) + item.amount;
            _inByCur[_ic] = (_inByCur[_ic] || 0) + item.amount;
        } else {
            _runByCur[_ic] = (_runByCur[_ic] || 0) - item.amount;
            _outByCur[_ic] = (_outByCur[_ic] || 0) + item.amount;
        }
        var _rowRun = _runByCur[_ic];

        let typeBgColor = '#64748b';
        if (item.type === 'فروش') typeBgColor = '#10b981';
        else if (item.type === 'خرید') typeBgColor = '#3b82f6';
        else if (item.type === 'دریافت') typeBgColor = '#8b5cf6';
        else if (item.type === 'پرداخت') typeBgColor = '#f59e0b';
        else if (item.type === 'مصرف') typeBgColor = '#ef4444';
        else if (item.type.indexOf('انتقال') >= 0) typeBgColor = '#0ea5e9';
        else if (item.type.indexOf('اضافه') >= 0 || item.type.indexOf('ورود') >= 0) typeBgColor = '#10b981';
        else if (item.type.indexOf('برداشت') >= 0) typeBgColor = '#ef4444';

        let balColor = _rowRun >= 0 ? '#10b981' : '#ef4444';

        txRowsHTML += `<tr>
            <td style="text-align:center;padding:5px;">${idx + 1}</td>
            <td style="text-align:center;padding:5px;font-size:10px;">${(typeof formatAfghanDateTime === 'function' ? formatAfghanDateTime(item.date, item.createdAt) : item.date) || '---'}</td>
            <td style="text-align:center;padding:5px;"><span style="background:${typeBgColor};color:#fff;padding:2px 8px;border-radius:4px;font-size:10px;">${item.type}</span></td>
            <td style="text-align:right;padding:5px;font-size:10px;">${item.person}</td>
            <td style="text-align:right;padding:5px;font-size:10px;">${item.desc}</td>
            <td style="text-align:center;padding:5px;color:${isIncome?'#10b981':'#ef4444'};font-weight:600;">${isIncome?'+':'-'}${fn(item.amount)} ${_icLbl}</td>
            <td style="text-align:center;padding:5px;color:${balColor};font-weight:700;">${fn(Math.abs(_rowRun))} ${_icLbl}</td>
        </tr>`;
    });

    // خلاصهٔ چند-ارزی: مجموعِ ورودی/خروجی و موجودیِ نهایی به تفکیکِ هر ارز
    var _allRepCurs = {};
    Object.keys(_inByCur).forEach(function(c){ _allRepCurs[c]=1; });
    Object.keys(_outByCur).forEach(function(c){ _allRepCurs[c]=1; });
    var _cbBalMap = (cashbox.balances && typeof cashbox.balances === 'object' && !Array.isArray(cashbox.balances)) ? cashbox.balances : {};
    Object.keys(_cbBalMap).forEach(function(c){ if (Math.abs(parseFloat(_cbBalMap[c])||0)>0.0001) _allRepCurs[c]=1; });
    var _repCurList = Object.keys(_allRepCurs);
    if (!_repCurList.length) _repCurList = [_baseCur()];
    var _lblOf = function(c){ return (typeof getCurrencyLabel === 'function') ? getCurrencyLabel(c) : c; };
    var _totalInHtml  = _repCurList.map(function(c){ return fn(_inByCur[c]||0) + ' ' + _lblOf(c); }).join('<br>');
    var _totalOutHtml = _repCurList.map(function(c){ return fn(_outByCur[c]||0) + ' ' + _lblOf(c); }).join('<br>');
    var _finalBalHtml = _repCurList.map(function(c){
        var _bv = (_cbBalMap[c] != null) ? parseFloat(_cbBalMap[c]) : (_runByCur[c]||0);
        return fn(_bv||0) + ' ' + _lblOf(c);
    }).join('<br>');
    var _curListHtml = _repCurList.map(_lblOf).join('، ');

    const currLabel = (typeof getCurrencyLabel === 'function') ? getCurrencyLabel(cashbox.currency) : (cashbox.currency || _baseCur());
    const reportDate = (typeof db.getCurrentDate === 'function') ? db.getCurrentDate() : new Date().toLocaleDateString('fa-IR');
    const reportTime = (function(){ const n=new Date(); return String(n.getHours()).padStart(2,'0')+' : '+String(n.getMinutes()).padStart(2,'0'); })();

    const html = `<!DOCTYPE html>
<html dir="rtl" lang="fa">
<head>
    <meta charset="UTF-8">
    <title>گزارش معاملات حساب - ${esc(cashbox.name || '')}</title>
    <link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.4.0/css/all.min.css">
    <style>
        * { box-sizing: border-box; margin: 0; padding: 0; }
        @page { size: A4 landscape; margin: 8mm; }
        @media print {
            body { margin: 0; padding: 0; background: #fff; -webkit-print-color-adjust: exact; print-color-adjust: exact; }
            .no-print { display: none !important; }
            .bill-wrap { overflow: visible !important; border: none !important; border-radius: 0 !important; max-width: 100% !important; box-shadow: none !important; }
            .items-table thead { display: table-header-group; }
            .items-table tbody { page-break-inside: avoid; }
            .items-table tr { page-break-inside: avoid; }
        }
        body {
            font-family: ${fontFamily};
            font-size: ${baseFont}px;
            color: #1a2533;
            background: #eceff3;
            direction: rtl;
            padding: 6mm;
            -webkit-print-color-adjust: exact;
            print-color-adjust: exact;
        }
        .bill-wrap {
            width: 100%;
            max-width: 285mm;
            margin: 0 auto;
            background: #fff;
            border: 1px solid ${navy};
            border-radius: 8px;
            overflow: hidden;
        }
        .rep-hdr {
            position: relative;
            display: flex;
            align-items: stretch;
            gap: 12px;
            padding: 14px 18px;
            background: #fff;
            border-bottom: 3px solid ${gold};
        }
        .rep-hdr::after {
            content: ""; position: absolute; top: 0; right: 0; width: 42%; height: 100%;
            background: ${navy}; clip-path: polygon(18% 0, 100% 0, 100% 100%, 0 100%); z-index: 0; opacity: 0.06;
        }
        .rep-logo { flex: 0 0 auto; width: 110px; display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 4px; z-index: 1; }
        .rep-logo-ph { width: 62px; height: 62px; border-radius: 10px; background: ${navy}; color: ${gold}; display: flex; align-items: center; justify-content: center; font-size: 26px; }
        .rep-center { flex: 1; text-align: center; z-index: 1; display: flex; flex-direction: column; justify-content: center; gap: 3px; }
        .rep-name { font-size: ${titleFont}px; font-weight: 900; color: ${navy}; letter-spacing: 0.5px; }
        .rep-name-en { font-size: ${fEnName}px; font-weight: 700; color: ${gold}; letter-spacing: 0.5px; }
        .rep-diamond { color: ${gold}; font-size: 9px; margin: 2px 0; }
        .rep-slogan { font-size: ${Math.max(9, baseFont - 1)}px; color: #55606e; display: flex; align-items: center; justify-content: center; gap: 6px; }
        .rep-slogan i { color: ${gold}; }
        .rep-label {
            flex: 0 0 auto; z-index: 1; align-self: center;
            background: ${navy}; color: ${onPrimary};
            border: 2px solid ${gold}; border-radius: 8px;
            padding: 10px 16px; text-align: center; min-width: 120px;
        }
        .rep-label .lbl { font-size: 12px; font-weight: bold; letter-spacing: 2px; color: ${gold}; }
        .rep-label .val { font-size: 14px; font-weight: 900; margin-top: 3px; color: ${onPrimary}; }
        .datetime-row {
            background: #f0f3f7; border-bottom: 1px solid #c8d0da;
            display: flex; justify-content: flex-end; gap: 26px; padding: 6px 18px; font-size: 11px;
        }
        .datetime-row .dt-item { display: flex; align-items: center; gap: 6px; }
        .datetime-row .dt-item i { color: ${navy}; }
        .person-info-section { border-bottom: 1px solid #c8d0da; padding: 12px 18px; }
        .person-info-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 8px 24px; font-size: 11px; line-height: 2; }
        .person-info-grid .field-line { display: flex; align-items: center; gap: 6px; }
        .field-line .fi-ico { width: 22px; height: 22px; border-radius: 50%; background: ${navy}; color: ${onPrimary}; display: inline-flex; align-items: center; justify-content: center; font-size: 10px; flex: 0 0 auto; }
        .person-info-grid .field-label { font-weight: bold; white-space: nowrap; color: ${navy}; }
        .person-info-grid .field-val { border-bottom: 1px dotted #888; flex: 1; min-width: 80px; padding-bottom: 1px; }
        .summary-section { border-bottom: 1px solid #c8d0da; padding: 10px 18px; }
        .summary-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 8px; font-size: 11px; }
        .summary-card { background: #f8fafc; border: 1px solid #e2e8f0; border-radius: 6px; padding: 8px 10px; text-align: center; }
        .summary-card .s-label { font-size: 10px; color: #64748b; margin-bottom: 3px; display: flex; align-items: center; justify-content: center; gap: 5px; }
        .summary-card .s-value { font-size: 13px; font-weight: 700; }
        .items-table { width: 100%; border-collapse: collapse; font-size: 10.5px; }
        .items-table thead tr { background: ${navy}; color: #fff; }
        .items-table thead th { padding: 7px 4px; text-align: center; border: 1px solid ${navy}; font-weight: bold; }
        .items-table thead th i { margin-inline-end: 4px; opacity: 0.9; }
        .items-table tbody tr:nth-child(even) { background: #f4f6fa; }
        .items-table tbody td { border: 1px solid #b0bbcc; padding: 5px 4px; text-align: center; vertical-align: middle; }
        .bill-ft {
            display: flex; align-items: center; justify-content: space-between;
            background: ${navy}; color: ${onPrimary}; padding: 10px 18px; gap: 12px;
        }
        .bill-ft .ft-thanks .t1 { font-size: 14px; font-weight: 800; }
        .bill-ft .ft-thanks .t2 { font-size: 11px; color: ${gold}; margin-top: 2px; }
        .bill-ft .ft-contact { display: flex; flex-direction: column; gap: 4px; font-size: 11px; }
        .bill-ft .ft-line { display: flex; align-items: center; gap: 7px; }
        .bill-ft .ft-line i { color: ${onPrimary}; width: 22px; height: 22px; border-radius: 50%; background: rgba(255,255,255,0.14); display: inline-flex; align-items: center; justify-content: center; font-size: 10px; }
        .rep-actions { display: flex; justify-content: center; align-items: center; gap: 14px; padding: 18px 12px 8px; }
        .rep-btn {
            border: none; border-radius: 9px; padding: 11px 24px; font-size: 14px; font-weight: 700;
            cursor: pointer; font-family: inherit; color: #fff; display: inline-flex; align-items: center; gap: 8px;
            box-shadow: 0 2px 8px rgba(0,0,0,0.16); transition: transform .12s, box-shadow .12s, filter .12s;
        }
        .rep-btn:hover { transform: translateY(-1px); box-shadow: 0 4px 14px rgba(0,0,0,0.22); filter: brightness(1.05); }
        .rep-btn-print { background: ${navy}; }
        .rep-share-wrap { position: relative; display: inline-block; }
        .rep-btn-share { background: linear-gradient(135deg, ${navy} 0%, ${navyDark} 100%); border: 1px solid ${gold}; }
        .rep-share-menu {
            display: none; position: absolute; top: calc(100% + 8px); left: 50%; transform: translateX(-50%);
            background: #fff; border: 1px solid #d0d5dd; border-radius: 12px; box-shadow: 0 10px 28px rgba(0,0,0,0.22);
            padding: 10px; z-index: 100000; min-width: 220px; flex-direction: column; gap: 8px;
        }
        .rep-share-menu.open { display: flex; }
        .rep-menu-item {
            border: none; border-radius: 8px; padding: 11px 14px; font-size: 13px; font-weight: 700; cursor: pointer;
            font-family: inherit; color: #fff; display: flex; align-items: center; gap: 9px; text-align: right; width: 100%;
        }
        .rep-menu-item i { font-size: 16px; }
        .rep-menu-pdf { background: #b91c1c; }
        .rep-menu-excel { background: #15803d; }
        .rep-menu-item:hover { filter: brightness(1.08); }
    </style>
</head>
<body>
<div class="rep-actions no-print">
    <button type="button" class="rep-btn rep-btn-print" onclick="window.print()"><i class="fas fa-print"></i> چاپ گزارش</button>
    <span class="rep-share-wrap">
        <button type="button" id="rep-share-btn" class="rep-btn rep-btn-share" onclick="__repToggleShare(event)"><i class="fas fa-share-alt"></i> اشتراک‌گذاری</button>
        <div id="rep-share-menu" class="rep-share-menu">
            <button type="button" class="rep-menu-item rep-menu-pdf" onclick="__repDownloadPdf()"><i class="fas fa-file-pdf"></i> دانلود PDF</button>
            <button type="button" class="rep-menu-item rep-menu-wa" onclick="__repShareWa()"><i class="fab fa-whatsapp"></i> ارسال به واتساپ</button>
            <div style="font-size:10.5px;color:#64748b;text-align:right;line-height:1.7;padding:2px 8px;">پس از ذخیرهٔ PDF، واتساپِ کامپیوتر باز می‌شود؛ مخاطب را انتخاب و فایلِ PDF را پیوست و ارسال کنید.</div>
            <button type="button" class="rep-menu-item rep-menu-excel" onclick="__repDownloadExcel()"><i class="fas fa-file-excel"></i> دانلود اکسل</button>
        </div>
    </span>
</div>

<div class="bill-wrap">
    <div class="rep-hdr">
        <div class="rep-logo">${logoHtml}</div>
        <div class="rep-center">
            <div class="rep-name">${esc(storeName)}</div>
            ${storeNameEn ? `<div class="rep-name-en">${esc(storeNameEn)}</div>` : ''}
            <div class="rep-diamond">◆</div>
            <div class="rep-slogan"><i class="fas fa-gem"></i> ${esc(storeSlogan)} <i class="fas fa-gem"></i></div>
        </div>
        <div class="rep-label">
            <div class="lbl">گزارش</div>
            <div class="val">معاملات حساب</div>
        </div>
    </div>

    <div class="datetime-row">
        <div class="dt-item"><i class="fas fa-clock"></i> ساعت : <span>${reportTime}</span></div>
        <div class="dt-item"><i class="fas fa-calendar-alt"></i> تاریخ گزارش : <span>${reportDate}</span></div>
    </div>

    <div class="person-info-section">
        <div class="person-info-grid">
            <div class="field-line"><span class="fi-ico"><i class="fas fa-cash-register"></i></span><span class="field-label">نام حساب :</span> <span class="field-val">${esc(cashbox.name || '---')}</span></div>
            <div class="field-line"><span class="fi-ico"><i class="fas fa-coins"></i></span><span class="field-label">ارزها :</span> <span class="field-val">${esc(_curListHtml)}</span></div>
            <div class="field-line"><span class="fi-ico"><i class="fas fa-map-marker-alt"></i></span><span class="field-label">موقعیت :</span> <span class="field-val">${esc(cashbox.location || '---')}</span></div>
            <div class="field-line"><span class="fi-ico"><i class="fas fa-star"></i></span><span class="field-label">وضعیت :</span> <span class="field-val">${cashbox.isDefault ? 'پیش‌فرض' : 'عادی'}</span></div>
            <div class="field-line"><span class="fi-ico"><i class="fas fa-wallet"></i></span><span class="field-label">موجودی فعلی :</span> <span class="field-val" style="font-weight:700;color:${navy};">${_finalBalHtml}</span></div>
            <div class="field-line"><span class="fi-ico"><i class="fas fa-calendar-plus"></i></span><span class="field-label">تاریخ ایجاد :</span> <span class="field-val">${esc(cashbox.createdAt || '---')}</span></div>
            <div class="field-line"><span class="fi-ico"><i class="fas fa-exchange-alt"></i></span><span class="field-label">تعداد معاملات :</span> <span class="field-val">${allItems.length}</span></div>
            <div class="field-line"><span class="fi-ico"><i class="fas fa-sticky-note"></i></span><span class="field-label">توضیحات :</span> <span class="field-val">${esc(cashbox.notes || cashbox.description || '---')}</span></div>
        </div>
    </div>

    <div class="summary-section">
        <div class="summary-grid">
            <div class="summary-card">
                <div class="s-label"><i class="fas fa-exchange-alt"></i> تعداد معاملات</div>
                <div class="s-value">${allItems.length}</div>
            </div>
            <div class="summary-card">
                <div class="s-label"><i class="fas fa-arrow-up"></i> مجموع ورودی</div>
                <div class="s-value" style="color:#10b981;font-size:11px;">${_totalInHtml}</div>
            </div>
            <div class="summary-card">
                <div class="s-label"><i class="fas fa-arrow-down"></i> مجموع خروجی</div>
                <div class="s-value" style="color:#ef4444;font-size:11px;">${_totalOutHtml}</div>
            </div>
            <div class="summary-card" style="border:1.5px solid ${navy};background:#eef3fb;">
                <div class="s-label" style="color:${navy};font-weight:700;"><i class="fas fa-wallet"></i> موجودی نهایی</div>
                <div class="s-value" style="color:${navy};font-size:11px;">${_finalBalHtml}</div>
            </div>
        </div>
    </div>

    <table class="items-table">
        <thead>
            <tr>
                <th style="width:5%"><i class="fas fa-hashtag"></i>ردیف</th>
                <th style="width:14%"><i class="fas fa-calendar-alt"></i>تاریخ</th>
                <th style="width:13%"><i class="fas fa-exchange-alt"></i>نوع</th>
                <th style="width:15%"><i class="fas fa-user"></i>فرد / مرجع</th>
                <th style="width:20%"><i class="fas fa-info-circle"></i>شرح</th>
                <th style="width:15%"><i class="fas fa-coins"></i>مبلغ</th>
                <th style="width:18%"><i class="fas fa-balance-scale"></i>مانده حساب</th>
            </tr>
        </thead>
        <tbody>
            ${txRowsHTML}
            <tr style="background:#eef3fb;font-weight:bold;border-top:2px solid ${navy};">
                <td colspan="5" style="text-align:left;color:${navy};padding:6px;">موجودی نهایی حساب</td>
                <td style="text-align:center;padding:6px;color:${navy};font-size:12px;font-weight:900;">${_finalBalHtml}</td>
                <td style="text-align:center;padding:6px;color:${navy};font-size:12px;font-weight:900;">${_finalBalHtml}</td>
            </tr>
        </tbody>
    </table>

    <div class="bill-ft">
        <div class="ft-thanks">
            <div class="t1">${esc(footerTitle)}</div>
            ${footerSubtitle ? `<div class="t2">${esc(footerSubtitle)}</div>` : ''}
        </div>
        <div class="ft-contact">
            ${storePhone ? `<div class="ft-line"><i class="fas fa-phone-alt"></i><span>${esc(storePhone)}${storePhone2 ? ' - ' + esc(storePhone2) : ''}</span></div>` : ''}
            ${storeAddress ? `<div class="ft-line"><i class="fas fa-map-marker-alt"></i><span>${esc(storeAddress)}</span></div>` : ''}
            ${storeWebsite ? `<div class="ft-line"><i class="fas fa-globe"></i><span>${esc(storeWebsite)}</span></div>` : ''}
        </div>
    </div>
</div>
</body>
</html>`;

    // اسکریپتِ پنجرهٔ گزارش: منوی اشتراک‌گذاری + چاپ/PDF (یکنواخت با گزارشِ شخص)
    var scriptBlock = '<scr' + 'ipt>'
        + 'function __repToggleShare(ev){ if(ev){ev.stopPropagation();} var m=document.getElementById("rep-share-menu"); if(m){ m.classList.toggle("open"); } }'
        + 'function __repCloseShare(){ var m=document.getElementById("rep-share-menu"); if(m){ m.classList.remove("open"); } }'
        + 'function __repDownloadPdf(){ __repCloseShare(); window.print(); }'
        + 'function __repShareWa(){ __repCloseShare(); try{ if(typeof __EXCEL_NAME!=="undefined" && __EXCEL_NAME) document.title=__EXCEL_NAME; }catch(e){} try{ if(window.opener && typeof window.opener.__jouyaSharePdfToWhatsApp==="function"){ window.opener.__jouyaSharePdfToWhatsApp("<!DOCTYPE html>"+document.documentElement.outerHTML, (typeof __EXCEL_NAME!=="undefined" && __EXCEL_NAME ? __EXCEL_NAME : (document.title||"report"))); return; } }catch(e){} window.print(); try{ var a=document.createElement("a"); a.href="whatsapp://send"; document.body.appendChild(a); a.click(); document.body.removeChild(a); }catch(e){} }'
        + 'function __repDownloadExcel(){ __repCloseShare(); try {'
        +   'var wrap=document.querySelector(".bill-wrap"); var tbl=wrap?wrap.outerHTML:document.body.innerHTML;'
        +   'var xls="<html xmlns:o=\\"urn:schemas-microsoft-com:office:office\\" xmlns:x=\\"urn:schemas-microsoft-com:office:excel\\" xmlns=\\"http://www.w3.org/TR/REC-html40\\"><head><meta charset=\\"UTF-8\\"></head><body>"+tbl+"</body></html>";'
        +   'var blob=new Blob(["\\ufeff"+xls],{type:"application/vnd.ms-excel;charset=utf-8"});'
        +   'var url=URL.createObjectURL(blob); var a=document.createElement("a"); a.href=url; a.download="گزارش-حساب.xls";'
        +   'document.body.appendChild(a); a.click(); document.body.removeChild(a); setTimeout(function(){URL.revokeObjectURL(url);},1500);'
        + ' } catch(e){ alert("خطا در ساخت فایل اکسل"); } }'
        + 'document.addEventListener("click",function(ev){ var m=document.getElementById("rep-share-menu"); var b=document.getElementById("rep-share-btn"); if(!m||!m.classList.contains("open")) return; if(m.contains(ev.target)) return; if(b&&b.contains(ev.target)) return; m.classList.remove("open"); });'
        + '</scr' + 'ipt>';

    // موبایل: به‌جای پنجرهٔ جدا، در اورلیِ درون‌برنامه (اشتراکِ فایلِ سالم)
    if (__jouyaMaybeMobilePreview(html, 'گزارش-حساب-' + ((typeof cashbox !== 'undefined' && cashbox) ? (cashbox.name || '') : ''))) return;

    var finalHtml = html.replace('</body>', scriptBlock + '</body>');

    var w = window.open('', '_blank', 'width=1150,height=880');
    if (!w) {
        try { showMessage('خطا', 'پنجره گزارش مسدود شد. لطفاً pop-up را در مرورگر مجاز کنید.'); }
        catch (e) { alert('پنجره گزارش مسدود شد. لطفاً pop-up را مجاز کنید.'); }
        return;
    }
    w.document.write(finalHtml);
    w.document.close();
    w.focus();
}

// ==================== اصلاح ثبت فروش (پیام + شرط چاپ) ====================
// این تابع را جایگزین تابع قبلی ثبت فروش کنید (معمولاً saveAndPrint یا مشابه)
function registerSale() {
    const customerSelect = document.getElementById('sales-customer');
    if (!customerSelect || !customerSelect.value) {
        showMessage('خطا', 'لطفاً مشتری را انتخاب یا وارد کنید.');
        return;
    }
    
    // ... (بقیه کد ساخت transaction همان‌طور که قبلاً داشتید)
    
    const result = db.saveTransaction(transactionObject);
    
    if (result.success) {
        showMessage('موفقیت', 'فروش با موفقیت ثبت شد.'); if(typeof addChangelog==='function') addChangelog('ثبت', 'فروش', result.data||{}, 'ثبت فروش جدید');
        
        // ریست فرم برای فروش جدید
        document.getElementById('salesForm').reset();
        clearSalesItemsTable(); // اگر تابعی برای پاک کردن جدول آیتم‌ها دارید
        loadDashboard(); // به‌روزرسانی آمار
        
        const settings = db.getSettings();
        if (settings.autoPrint) {
            printInvoice(result.data.id);
        }
    } else {
        showMessage('خطا', result.error || 'خطا در ثبت فروش');
    }
}

// توابع تاریخ و عمومی
function updateCurrentDate() {
    try {
        const dateElement = document.getElementById('current-date');
        if (dateElement) {
            const afghDate = _getAfghNow();
            const persianDate = new PersianDate(afghDate);
            dateElement.textContent = persianDate.format('dddd DD MMMM YYYY');
        }
    } catch (error) {
        console.error('خطا در به‌روزرسانی تاریخ:', error);
    }
}

function _attachDatePickerToInput(input) {
    // ===== یکپارچه‌سازی: همه فیلدهای تاریخ از date+time picker واحد استفاده می‌کنند =====
    // منطق قدیمی به طور کامل به سیستم datetime جدید هدایت می‌شود
    if (typeof _attachDateTimePickerToInput === 'function') {
        return _attachDateTimePickerToInput(input);
    }
    // ===== fallback (در عمل هرگز اجرا نمی‌شود چون _attachDateTimePickerToInput همیشه موجود است) =====
    if (!input) return;
    try {
        var _afghFb = _getAfghNow();
        var _todayVal = new PersianDate(_afghFb).format('YYYY/MM/DD');
        var _h24 = _afghFb.getHours();
        var _ampm = _h24 >= 12 ? 'PM' : 'AM';
        var _h12 = _h24 % 12; if (_h12 === 0) _h12 = 12;
        var _mm = _afghFb.getMinutes() < 10 ? '0' + _afghFb.getMinutes() : '' + _afghFb.getMinutes();
        var _ss = _afghFb.getSeconds() < 10 ? '0' + _afghFb.getSeconds() : '' + _afghFb.getSeconds();
        var _todayDateTimeVal = _todayVal + ' ' + _h12 + ':' + _mm + ':' + _ss + ' ' + _ampm;
    } catch(e) {
        var _todayVal = '';
        var _todayDateTimeVal = '';
    }
    if (input.type === 'date') {
        input.type = 'text';
        input.classList.add('jalali-date');
    }
    var skipDefault = input.dataset.noDefault === '1'
        || input.classList.contains('jalali-date-optional');
    if (!input.value && _todayDateTimeVal && !skipDefault) {
        input.value = _todayDateTimeVal;
    }
    input.removeAttribute('readonly');
    if (!input.placeholder || input.placeholder === 'YYYY/MM/DD') {
        input.placeholder = _todayDateTimeVal || '1404/01/01 12:00:00 AM';
    }
}

function initDatePickers() {
    // از _attachDateTimePickerToInput برای همه فیلدهای تاریخ استفاده می‌کنیم
    // تا همه آیکن‌ها تاریخ + ساعت داشته باشند و از یک طراحی یکسان پیروی کنند
    var _attachFn = (typeof _attachDateTimePickerToInput === 'function')
        ? _attachDateTimePickerToInput
        : _attachDatePickerToInput;

    document.querySelectorAll('input[type="date"], .jalali-date').forEach(function(input) {
        _attachFn(input);
    });

    // MutationObserver برای فیلدهای تاریخ که بصورت داینامیک اضافه می‌شوند
    if (!window._dpObserver) {
        window._dpObserver = new MutationObserver(function(mutations) {
            mutations.forEach(function(mutation) {
                mutation.addedNodes.forEach(function(node) {
                    if (node.nodeType !== 1) return;
                    var inputs = [];
                    if (node.matches && (node.matches('input[type="date"]') || node.matches('.jalali-date'))) {
                        inputs.push(node);
                    }
                    node.querySelectorAll && node.querySelectorAll('input[type="date"], .jalali-date').forEach(function(inp) {
                        inputs.push(inp);
                    });
                    inputs.forEach(function(inp) {
                        var _fn = (typeof _attachDateTimePickerToInput === 'function')
                            ? _attachDateTimePickerToInput
                            : _attachDatePickerToInput;
                        _fn(inp);
                    });
                });
            });
        });
        window._dpObserver.observe(document.body, { childList: true, subtree: true });
    }
}

// ===== تقویم شمسی =====
var _dpTarget = null;

function showDatePicker(el) {
    // یکپارچه‌سازی: همه آیکن‌های تاریخ از date+time picker استفاده می‌کنند
    if (typeof _showDateTimePicker === 'function') {
        _showDateTimePicker(el);
        return;
    }
    var existing = document.getElementById('_dp_wrap');
    if (existing) {
        if (_dpTarget === el) { _closeDp(); return; }
        _closeDp();
    }
    _dpTarget = el;
    var parts = (el.value || '').split('/');
    var _todayFmt = new PersianDate(new Date()).format('YYYY/MM/DD').split('/');
    var y = parseInt(parts[0]) || parseInt(_todayFmt[0]);
    var m = parseInt(parts[1]) || parseInt(_todayFmt[1]);
    var d = parseInt(parts[2]) || parseInt(_todayFmt[2]);
    _renderDp(y, m, d);
}

function _closeDp() {
    var w = document.getElementById('_dp_wrap');
    var o = document.getElementById('_dp_overlay');
    var b = document.getElementById('_dp_backdrop');
    if (w) w.remove();
    if (o) o.remove();
    if (b) b.remove();
    _dpTarget = null;
}

function _renderDp(year, month, activeDay) {
    var el = _dpTarget;
    var old = document.getElementById('_dp_wrap');
    if (old) old.remove();
    var ov = document.getElementById('_dp_overlay');
    if (ov) ov.remove();

    var MONTHS = ['حمل','ثور','جوزا','سرطان','اسد','سنبله','میزان','عقرب','قوس','جدی','دلو','حوت'];
    var DAYS   = ['ش','ی','د','س','چ','پ','ج'];

    // overlay برای بستن با کلیک بیرون
    var overlay = document.createElement('div');
    overlay.id = '_dp_overlay';
    overlay.style.cssText = 'position:fixed;inset:0;z-index:88888;';
    overlay.onclick = _closeDp;
    document.body.appendChild(overlay);

    var wrap = document.createElement('div');
    wrap.id = '_dp_wrap';
    wrap.onclick = function(e){ e.stopPropagation(); };

    // موقعیت کلیندر - همیشه در مرکز صفحه به صورت مودال
    var calW = 270;

    wrap.style.cssText = [
        'position:fixed',
        'top:50%',
        'left:50%',
        'transform:translate(-50%,-50%)',
        'z-index:99999',
        'width:' + calW + 'px',
        'background:#fff',
        'border-radius:14px',
        'box-shadow:0 12px 40px rgba(0,0,0,0.18)',
        'overflow-x:hidden',
        'overflow-y:auto',
        'max-height:90vh',
        'direction:rtl',
        'font-family:inherit',
        'border:1px solid #e8e8e8',
        'animation:_dpIn .15s ease'
    ].join(';');

    // انیمیشن
    if (!document.getElementById('_dp_style')) {
        var st = document.createElement('style');
        st.id = '_dp_style';
        st.textContent = '@keyframes _dpIn{from{opacity:0;transform:translateY(-8px)}to{opacity:1;transform:translateY(0)}}';
        document.head.appendChild(st);
    }

    // ===== هدر =====
    var hdr = document.createElement('div');
    hdr.style.cssText = 'background:linear-gradient(135deg,#5b4fcf,#7c6fef);padding:12px 10px;display:flex;align-items:center;justify-content:space-between;gap:4px;';

    function navBtn(html, fn) {
        var b = document.createElement('button');
        b.innerHTML = html;
        b.style.cssText = 'background:rgba(255,255,255,0.18);border:none;color:#fff;width:26px;height:26px;border-radius:50%;cursor:pointer;font-size:15px;display:flex;align-items:center;justify-content:center;flex-shrink:0;';
        b.onmouseover = function(){ this.style.background='rgba(255,255,255,0.32)'; };
        b.onmouseout  = function(){ this.style.background='rgba(255,255,255,0.18)'; };
        b.onclick = fn;
        return b;
    }

    function styledSel(opts, cur, fn) {
        var s = document.createElement('select');
        s.style.cssText = 'background:rgba(255,255,255,0.15);border:none;color:#fff;font-size:13px;border-radius:8px;padding:2px 6px;cursor:pointer;font-family:inherit;flex:1;min-width:0;text-align:center;';
        opts.forEach(function(o){ var el=document.createElement('option'); el.value=o.v; el.textContent=o.t; if(o.v===cur)el.selected=true; s.appendChild(el); });
        s.onchange = function(){ fn(parseInt(this.value)); };
        return s;
    }

    var prevM = navBtn('›', function(){ var nm=month-1,ny=year; if(nm<1){nm=12;ny--;} _dpTarget=el; _renderDp(ny,nm,null); });
    var nextM = navBtn('‹', function(){ var nm=month+1,ny=year; if(nm>12){nm=1;ny++;} _dpTarget=el; _renderDp(ny,nm,null); });

    var mOpts = MONTHS.map(function(n,i){ return {v:i+1, t:n}; });
    var yOpts = [];
    for(var yi=year-10; yi<=year+5; yi++) yOpts.push({v:yi, t:yi});

    var mSel = styledSel(mOpts, month, function(v){ _dpTarget=el; _renderDp(year,v,null); });
    var ySel = styledSel(yOpts, year,  function(v){ _dpTarget=el; _renderDp(v,month,null); });

    var mid = document.createElement('div');
    mid.style.cssText = 'display:flex;gap:4px;flex:1;min-width:0;';
    mid.appendChild(mSel);
    mid.appendChild(ySel);

    hdr.appendChild(prevM);
    hdr.appendChild(mid);
    hdr.appendChild(nextM);
    wrap.appendChild(hdr);

    // ===== نام روزهای هفته =====
    var dRow = document.createElement('div');
    dRow.style.cssText = 'display:grid;grid-template-columns:repeat(7,1fr);background:#f4f3ff;';
    DAYS.forEach(function(d){
        var c = document.createElement('div');
        c.textContent = d;
        c.style.cssText = 'text-align:center;padding:7px 0;font-size:11px;color:#8b83d4;font-weight:700;';
        dRow.appendChild(c);
    });
    wrap.appendChild(dRow);

    // ===== گرید روزها =====
    var grid = document.createElement('div');
    grid.style.cssText = 'display:grid;grid-template-columns:repeat(7,1fr);padding:6px 8px 8px;gap:2px;';

    // اولین روز هفته ماه - تبدیل شمسی به میلادی بدون کتابخانه
    function _jalaliToGregorian(jy, jm, jd) {
        var jy2 = jy - 979, jm2 = jm - 1, jd2 = jd - 1;
        var j_day_no = 365*jy2 + Math.floor(jy2/4)*8 - Math.floor(jy2/100) + Math.floor(jy2/400);
        for (var i=0; i<jm2; ++i) j_day_no += [31,28,31,30,31,30,31,31,30,31,30,31][i] + (i===1 && ((jy2+979)%4===0 && ((jy2+979)%100!==0 || (jy2+979)%400===0)) ? 1 : 0);
        j_day_no += jd2;
        var i_day_no = j_day_no + 79;
        var i_np = Math.floor(i_day_no/12053); i_day_no %= 12053;
        var iy = 979 + 33*i_np + 4*Math.floor(i_day_no/1461); i_day_no %= 1461;
        if (i_day_no >= 366) { iy += Math.floor((i_day_no-1)/365); i_day_no = (i_day_no-1)%365; }
        var mi_days = [31,28,31,30,31,30,31,31,30,31,30,31];
        if ((iy%4===0 && iy%100!==0) || iy%400===0) mi_days[1] = 29;
        var im = 0;
        for (var j=0; j<12; j++) { if (i_day_no < mi_days[j]) { im=j; break; } i_day_no -= mi_days[j]; }
        return new Date(iy, im, i_day_no+1);
    }
    // قابل دسترس از خارج تابع برای نمایش معادل میلادی در picker
    if (typeof window !== 'undefined' && !window._jalaliToGregorian) window._jalaliToGregorian = _jalaliToGregorian;
    var _firstGreg = _jalaliToGregorian(year, month, 1);
    var _gregDay = _firstGreg.getDay(); // 0=Sun, 6=Sat
    // شنبه=0، یکشنبه=1، ...، جمعه=6
    var firstDay = (_gregDay + 1) % 7;
    // تعداد روزهای ماه شمسی افغانستانی
    var daysInM = month <= 6 ? 31 : (month <= 11 ? 30 : 29);

    var today = new PersianDate(_getAfghNow()).format('YYYY/MM/DD').split('/');
    var tY = parseInt(today[0]), tM = parseInt(today[1]), tD = parseInt(today[2]);

    // خانه‌های خالی
    for(var i=0; i<firstDay; i++){
        grid.appendChild(document.createElement('div'));
    }

    // خواندن روز انتخاب‌شده از مقدار فعلی فیلد
    var curParts = (el.value||'').split('/');
    var cY=parseInt(curParts[0]), cM=parseInt(curParts[1]), cD=parseInt(curParts[2]);

    for(var day=1; day<=daysInM; day++){
        (function(d){
            var cell = document.createElement('div');
            cell.textContent = d;

            var isSel   = (year===cY && month===cM && d===cD);
            var isToday = (year===tY && month===tM && d===tD);

            var base = 'text-align:center;padding:5px 2px;border-radius:50%;cursor:pointer;font-size:12px;line-height:1.6;transition:all .12s;';
            if(isSel){
                cell.style.cssText = base + 'background:linear-gradient(135deg,#5b4fcf,#7c6fef);color:#fff;font-weight:700;';
            } else if(isToday){
                cell.style.cssText = base + 'background:#ede9ff;color:#5b4fcf;font-weight:700;';
            } else {
                cell.style.cssText = base + 'color:#444;';
            }

            if(!isSel){
                cell.onmouseover = function(){ this.style.background='#ede9ff'; this.style.color='#5b4fcf'; };
                cell.onmouseout  = function(){
                    if(isToday){ this.style.background='#ede9ff'; this.style.color='#5b4fcf'; }
                    else { this.style.background=''; this.style.color='#444'; }
                };
            }

            cell.onclick = function(){
                var mm = month<10?'0'+month:''+month;
                var dd = d<10?'0'+d:''+d;
                if (el && el._isDateTime) {
                    var _hourEl = document.getElementById('_dp_hour');
                    var _minEl = document.getElementById('_dp_min');
                    var _secEl = document.getElementById('_dp_sec');
                    var _apEl = document.getElementById('_dp_ampm');
                    var _h12v, _mVal, _sVal, _ap;
                    if (_hourEl && _minEl && _apEl) {
                        _h12v = parseInt(_hourEl.value);
                        _mVal = parseInt(_minEl.value);
                        _sVal = _secEl ? parseInt(_secEl.value) : 0;
                        _ap = _apEl.value;
                    } else {
                        var _nNow = _getAfghNow();
                        var _h24 = _nNow.getHours();
                        _ap = _h24 >= 12 ? 'PM' : 'AM';
                        _h12v = _h24 % 12; if (_h12v === 0) _h12v = 12;
                        _mVal = _nNow.getMinutes();
                        _sVal = _nNow.getSeconds();
                    }
                    if (isNaN(_h12v) || _h12v < 1 || _h12v > 12) _h12v = 12;
                    if (isNaN(_mVal) || _mVal < 0 || _mVal > 59) _mVal = 0;
                    if (isNaN(_sVal) || _sVal < 0 || _sVal > 59) _sVal = 0;
                    var _minStr = _mVal < 10 ? '0' + _mVal : '' + _mVal;
                    var _secStr = _sVal < 10 ? '0' + _sVal : '' + _sVal;
                    el.value = year + '/' + mm + '/' + dd + ' ' + _h12v + ':' + _minStr + ':' + _secStr + ' ' + _ap;
                } else {
                    el.value = year+'/'+mm+'/'+dd;
                }
                if(el.onchange) el.onchange();
                _closeDp();
            };

            grid.appendChild(cell);
        })(day);
    }
    wrap.appendChild(grid);

    // ===== فوتر: دکمه امروز =====
    var ftr = document.createElement('div');
    ftr.style.cssText = 'padding:6px 10px 10px;text-align:center;';
    var todayBtn = document.createElement('button');
    todayBtn.textContent = '📅 امروز';
    todayBtn.style.cssText = 'background:linear-gradient(135deg,#5b4fcf,#7c6fef);color:#fff;border:none;border-radius:20px;padding:5px 22px;cursor:pointer;font-family:inherit;font-size:12px;width:100%;';
    todayBtn.onmouseover = function(){ this.style.opacity='0.88'; };
    todayBtn.onmouseout  = function(){ this.style.opacity='1'; };
    todayBtn.onclick = function(){
        var _n = _getAfghNow();
        var _todayJ = new PersianDate(_n).format('YYYY/MM/DD');
        // اگر فیلد datetime است، ساعت ۱۲ ساعته با ثانیه را هم اضافه کن
        if (el && el._isDateTime) {
            var _hourEl = document.getElementById('_dp_hour');
            var _minEl = document.getElementById('_dp_min');
            var _secEl = document.getElementById('_dp_sec');
            var _apEl = document.getElementById('_dp_ampm');
            var _h12v, _mVal, _sVal, _ap;
            if (_hourEl && _minEl && _apEl) {
                _h12v = parseInt(_hourEl.value);
                _mVal = parseInt(_minEl.value);
                _sVal = _secEl ? parseInt(_secEl.value) : 0;
                _ap = _apEl.value;
            } else {
                var _h24 = _n.getHours();
                _ap = _h24 >= 12 ? 'PM' : 'AM';
                _h12v = _h24 % 12; if (_h12v === 0) _h12v = 12;
                _mVal = _n.getMinutes();
                _sVal = _n.getSeconds();
            }
            if (isNaN(_h12v) || _h12v < 1 || _h12v > 12) _h12v = 12;
            if (isNaN(_mVal) || _mVal < 0 || _mVal > 59) _mVal = 0;
            if (isNaN(_sVal) || _sVal < 0 || _sVal > 59) _sVal = 0;
            var _minStr = _mVal < 10 ? '0' + _mVal : '' + _mVal;
            var _secStr = _sVal < 10 ? '0' + _sVal : '' + _sVal;
            el.value = _todayJ + ' ' + _h12v + ':' + _minStr + ':' + _secStr + ' ' + _ap;
        } else {
            el.value = _todayJ;
        }
        if(el.onchange) el.onchange();
        _closeDp();
    };
    ftr.appendChild(todayBtn);
    wrap.appendChild(ftr);

    // backdrop برای بستن با کلیک بیرون از مودال
    var backdrop = document.createElement('div');
    backdrop.id = '_dp_backdrop';
    backdrop.style.cssText = 'position:fixed;inset:0;z-index:99998;background:rgba(0,0,0,0.35);';
    backdrop.onclick = _closeDp;
    document.body.appendChild(backdrop);

    document.body.appendChild(wrap);
}
function showMessage(title, message) {
    if (title === 'موفقیت') {
        showToast(message, 'success');
        return;
    }
    const modal = document.getElementById('messageModal');
    const modalTitle = document.getElementById('modalTitle');
    const modalBody = document.getElementById('modalBody');
    
    modalTitle.innerHTML = `<i class="fas fa-info-circle"></i> ${title}`;
    
    // تبدیل خطوط جدید به <br>
    const formattedMessage = message.replace(/\n/g, '<br>');
    modalBody.innerHTML = formattedMessage;
    
    modal.style.display = 'block';
}

function showToast(message, type) {
    var existing = document.getElementById('app-toast');
    if (existing) existing.remove();
    var icons = { success: 'fa-check-circle', error: 'fa-times-circle', info: 'fa-info-circle', warning: 'fa-exclamation-triangle' };
    var accents = { success: '#34d399', error: '#f87171', info: '#60a5fa', warning: '#fbbf24' };
    var accent = accents[type] || accents.info;
    var toast = document.createElement('div');
    toast.id = 'app-toast';
    toast.style.cssText = 'position:fixed;bottom:30px;left:50%;transform:translateX(-50%) translateY(12px);z-index:99999;'
        + 'display:flex;align-items:center;gap:11px;padding:13px 24px;'
        + 'background:#1e3a5f;border-radius:14px;border-right:5px solid ' + accent + ';'
        + 'box-shadow:0 12px 34px rgba(15,23,42,0.38);opacity:0;transition:opacity .3s ease, transform .3s ease;'
        + 'direction:rtl;max-width:92%;font-family:inherit;pointer-events:none;';
    toast.innerHTML = '<i class="fas ' + (icons[type] || icons.info) + '" style="font-size:20px;color:' + accent + ';"></i>'
        + '<span style="font-size:14px;font-weight:700;color:#fff;letter-spacing:.2px;">' + message + '</span>';
    document.body.appendChild(toast);
    setTimeout(function () { toast.style.opacity = '1'; toast.style.transform = 'translateX(-50%) translateY(0)'; }, 10);
    setTimeout(function () { toast.style.opacity = '0'; toast.style.transform = 'translateX(-50%) translateY(12px)'; setTimeout(function () { if (toast.parentNode) toast.remove(); }, 300); }, 2600);
}
function closeModal() {
    document.getElementById('messageModal').style.display = 'none';
}

function showConfirm(title, message, callback) {
    // اجرای مستقیم بدون دیالوگ تایید
    callback();
}

function closeConfirmModal() {
    document.getElementById('confirmModal').style.display = 'none';
}

// توابع حذف داده‌ها
function deletePerson(id) {
    showConfirm('تایید حذف', 'حذف فرد و تمام معاملات و داده‌های مرتبط با او؟', function() {
        var ps = db.getPersons(); var p = ps.find(function(x){return x.id==id;});
        if(p) addChangelog('حذف','شخص',p,'حذف شخص و تمام معاملات مرتبط: '+(p.name||''));

        // ── حذف تمام تراکنش‌ها/معاملات این فرد از همه بخش‌ها و برگشت اثر آن‌ها روی انبار و حساب ──
        try {
            var _allTx = db.getTransactions() || [];
            var _personTx = _allTx.filter(function(tx){
                return (tx.personId == id || tx.customerId == id || tx.supplierId == id);
            });
            _personTx.forEach(function(tx) {
                var txType = tx.type || '';
                // برگشت موجودی حساب
                if (tx.cashboxId) {
                    var _txCur = tx.currency || _baseCur();
                    var _refundAmt = 0;
                    // اصلاحِ باگِ داده: ارزِ تراکنش (_txCur) به updateCashboxBalance پاس داده
                    //  می‌شود تا برگشتِ اثر روی «همان ارز» بنشیند، نه ارزِ بومیِ حساب.
                    //  برای صرافی، هر دو طرفِ ارز جداگانه برگردانده می‌شود.
                    if (txType === 'فروش') {
                        // نقدِ دریافتیِ همان ارز از تابعِ مرکزی (Map پویا + fallback قدیمی)
                        _refundAmt = (typeof _engCashPaidFor === 'function') ? _engCashPaidFor(tx, 'cash') : 0;
                        if (_refundAmt > 0) db.updateCashboxBalance(tx.cashboxId, _refundAmt, 'out', _txCur);
                    } else if (txType === 'خرید') {
                        _refundAmt = (typeof _engCashPaidFor === 'function') ? _engCashPaidFor(tx, 'paid') : 0;
                        if (_refundAmt > 0) db.updateCashboxBalance(tx.cashboxId, _refundAmt, 'in', _txCur);
                    } else if (txType === 'دریافت') {
                        _refundAmt = parseFloat(tx.amount)||0;
                        if (_refundAmt > 0) db.updateCashboxBalance(tx.cashboxId, _refundAmt, 'out', _txCur);
                    } else if (txType === 'پرداخت') {
                        _refundAmt = parseFloat(tx.amount)||0;
                        if (_refundAmt > 0) db.updateCashboxBalance(tx.cashboxId, _refundAmt, 'in', _txCur);
                    } else if (txType === 'صرافی') {
                        var _fromCur = tx.fromCurrency || _txCur, _toCur = tx.toCurrency || _txCur;
                        var _fromAmt = parseFloat(tx.fromAmount)||0, _toAmt = parseFloat(tx.toAmount)||0;
                        if (_fromAmt > 0) db.updateCashboxBalance(tx.cashboxId, _fromAmt, 'in', _fromCur);   // برگشتِ خروج
                        if (_toAmt > 0)   db.updateCashboxBalance(tx.cashboxId, _toAmt, 'out', _toCur);       // برگشتِ ورود
                    } else if (txType === 'برگشت') {
                        _refundAmt = (tx.cashAmounts != null)
                            ? ((tx.cashAmounts[_txCur] != null) ? (parseFloat(tx.cashAmounts[_txCur]) || 0) : 0)
                            : (parseFloat(tx.totalAmount||tx.amount)||0);
                        if (_refundAmt > 0) {
                            if (tx.returnType === 'فروش') db.updateCashboxBalance(tx.cashboxId, _refundAmt, 'in', _txCur);
                            else if (tx.returnType === 'خرید') db.updateCashboxBalance(tx.cashboxId, _refundAmt, 'out', _txCur);
                        }
                    }
                }
                // برگشت موجودی انبار (روردی/خروجی جنس)
                if (txType === 'فروش' && Array.isArray(tx.items)) {
                    tx.items.forEach(function(i){ db.updateProductStock(i.productId, _itemStockQty(i), 'in'); });
                } else if (txType === 'خرید' && Array.isArray(tx.items)) {
                    tx.items.forEach(function(i){ db.updateProductStock(i.productId, _itemStockQty(i), 'out'); });
                } else if (txType === 'برگشت' && Array.isArray(tx.items)) {
                    tx.items.forEach(function(i){
                        if (i && i.isService) return;
                        if (tx.returnType === 'فروش') db.updateProductStock(i.productId, _itemStockQty(i), 'out');
                        else if (tx.returnType === 'خرید') db.updateProductStock(i.productId, _itemStockQty(i), 'in');
                    });
                }
            });
            // حذف تراکنش‌های فرد از لیست
            var _remainingTx = _allTx.filter(function(tx){
                return !(tx.personId == id || tx.customerId == id || tx.supplierId == id);
            });
            localStorage.setItem('transactions', JSON.stringify(_remainingTx));
        } catch(e) { console.error('خطا در حذف معاملات فرد:', e); }

        // ── حذف مصارف مرتبط با این فرد و برگشت اثر حساب ──
        try {
            var _allExp = db.getExpenses() || [];
            var _hadPersonExp = false;
            _allExp.forEach(function(exp){
                if (exp.personId == id) {
                    _hadPersonExp = true;
                    if (exp.cashboxId) db.updateCashboxBalance(exp.cashboxId, parseFloat(exp.amount||0), 'in');
                }
            });
            if (_hadPersonExp) {
                var _remainingExp = _allExp.filter(function(exp){ return exp.personId != id; });
                localStorage.setItem('expenses', JSON.stringify(_remainingExp));
            }
        } catch(e) { console.error('خطا در حذف مصارف فرد:', e); }

        db.deletePerson(id);
        loadPersonsList();
        if (typeof loadProductsList === 'function') loadProductsList();
        if (typeof loadSalesList === 'function') loadSalesList();
        if (typeof loadPurchasesList === 'function') loadPurchasesList();
        if (typeof loadReceiptsList === 'function') loadReceiptsList();
        if (typeof loadPaymentsList === 'function') loadPaymentsList();
        if (typeof loadExpensesList === 'function') loadExpensesList();
        if (typeof loadDashboard === 'function') loadDashboard();
        if (typeof refreshOpenReport === 'function') refreshOpenReport();
        showMessage('موفقیت', 'فرد و تمام معاملات مرتبط با او حذف شد.');
    });
}

function deleteProduct(id) {
    showConfirm('تایید حذف', 'حذف جنس', function() {
        var pid = id;
        var prs = db.getProducts(); var pr = prs.find(function(x){return x.id==pid;});
        if(pr) addChangelog('حذف','جنس',pr,'حذف جنس: '+(pr.name||''));

        // ---- پاک‌سازیِ اثرِ این جنس از بل‌های خرید/فروش ----
        // کارت‌ها (رکوردِ معامله در لیستِ فروش/خرید) حفظ می‌شوند، اما ارقام و فایدهٔ مربوط به این جنس
        // حذف می‌گردد: بلِ تک‌جنسی کاملاً صفر می‌شود و بلِ چندجنسی فقط سهمِ این جنس را از دست می‌دهد.
        // کاربر می‌تواند این کارت‌های صفرشده را در صورت تمایل خودش حذف کند.
        try {
            var _txs = db.getTransactions() || [];
            var _changed = false;
            _txs.forEach(function(t) {
                if (!t || (t.type !== 'فروش' && t.type !== 'خرید') || !Array.isArray(t.items) || t.items.length === 0) return;
                var _hasThis = t.items.some(function(it){ return it && it.productId == pid; });
                if (!_hasThis) return;
                _changed = true;
                var _cur = t.currency || _baseCur();
                var _kept = t.items.filter(function(it){ return !(it && it.productId == pid); });

                if (_kept.length === 0) {
                    // بلِ تک‌جنسی → کاملاً صفر شود + برگشتِ اثرِ نقدِ آن روی حساب (مانندِ حذفِ معامله)
                    if (t.cashboxId) {
                        var _refund = 0;
                        if (t.type === 'فروش') {
                            _refund = _cur === 'USD' ? (parseFloat(t.cashUsd) || 0) : (parseFloat(t.cashAfn) || 0);
                            if (_refund > 0 && db.updateCashboxBalance) db.updateCashboxBalance(t.cashboxId, _refund, 'out');
                        } else {
                            _refund = _cur === 'USD' ? (parseFloat(t.paidUsd) || parseFloat(t.cashUsd) || 0) : (parseFloat(t.paidAfn) || parseFloat(t.cashAfn) || 0);
                            if (_refund > 0 && db.updateCashboxBalance) db.updateCashboxBalance(t.cashboxId, _refund, 'in');
                        }
                    }
                    // حذفِ هزینهٔ حمل‌ونقلِ بلِ خریدِ صفرشده (با برگشتِ اثرِ حساب)
                    if (t.type === 'خرید' && typeof _syncPurchaseShippingExpense === 'function') {
                        try { _syncPurchaseShippingExpense(t.id, 0); } catch(e) {}
                    }
                    t.items = [];
                    t.subTotal = 0; t.totalDiscount = 0; t.totalAmount = 0;
                    t.cashAfn = 0; t.cashUsd = 0; t.paidAfn = 0; t.paidUsd = 0;
                    t.remaining = 0; t.profit = 0; t.shipping = 0;
                    t.status = 'تسویه‌شده';
                    t._emptiedByProductDelete = true;
                } else {
                    // بلِ چندجنسی → فقط سهمِ این جنس حذف و ارقام از نو محاسبه شود
                    t.items = _kept;
                    var _sub = _kept.reduce(function(s,it){ return s + ((parseFloat(it.quantity)||0)*(parseFloat(it.price)||0)); }, 0);
                    var _disc = _kept.reduce(function(s,it){ return s + (parseFloat(it.discount)||0); }, 0);
                    t.subTotal = _sub;
                    t.totalDiscount = _disc;
                    t.totalAmount = _sub - _disc;
                    var _paid = 0;
                    if (t.type === 'فروش') _paid = _cur === 'USD' ? (parseFloat(t.cashUsd)||0) : (parseFloat(t.cashAfn)||0);
                    else _paid = _cur === 'USD' ? (parseFloat(t.paidUsd)||parseFloat(t.cashUsd)||0) : (parseFloat(t.paidAfn)||parseFloat(t.cashAfn)||0);
                    var _rem = t.totalAmount - _paid;
                    t.remaining = _rem > 0 ? _rem : 0;
                    t.status = t.remaining > 0 ? 'باقی‌مانده' : 'تسویه‌شده';
                    // فایدهٔ ذخیره‌شدهٔ فروش را از نو حساب کن (موتورِ FIFO زندهٔ گزارش‌ها هم دوباره محاسبه می‌کند)
                    if (t.type === 'فروش') {
                        var _pf = 0;
                        _kept.forEach(function(it){
                            if (it.isService) return;
                            var _pp = _cur === 'USD' ? (parseFloat(it.purchasePriceUSD)||0) : (parseFloat(it.purchasePriceAFN)||0);
                            _pf += ((parseFloat(it.price)||0) - _pp) * (parseFloat(it.quantity)||0) - (parseFloat(it.discount)||0);
                        });
                        t.profit = _pf;
                    }
                }
            });
            if (_changed) localStorage.setItem('transactions', JSON.stringify(_txs));
        } catch(e) { console.error('پاک‌سازی بل‌های جنسِ حذف‌شده ناکام ماند:', e); }

        db.deleteProduct(pid);

        // رفرشِ کاملِ دیتابیس‌محور: فایده، سرمایه، گزارش‌ها و لیست‌ها هماهنگ شوند
        loadProductsList();
        if (typeof loadSalesList === 'function') loadSalesList();
        if (typeof loadPurchasesList === 'function') loadPurchasesList();
        if (typeof loadDashboard === 'function') loadDashboard();
        if (typeof window._instantUpdateAll === 'function') { try { window._instantUpdateAll('deleteProduct'); } catch(e) {} }
        if (typeof refreshOpenReport === 'function') refreshOpenReport();
        showMessage('موفقیت', 'جنس حذف شد و ارقامِ آن از بل‌های خرید/فروش پاک شد (کارت‌ها حفظ شدند).');
    });
}

function editExpense(id) {
    try {
        const expenses = db.getExpenses ? db.getExpenses() : [];
        const expense = expenses.find(e => e.id == id);
        if (!expense) { showMessage('خطا', 'مصرف یافت نشد.'); return; }
        // باز کردن فرم مصرف با showExpenseForm
        showExpenseForm(id);
    } catch(e) {
        console.error('editExpense error:', e);
    }
}

function editTransaction(id) {
    try {
        const transactions = db.getTransactions ? db.getTransactions() : [];
        const tx = transactions.find(t => t.id == id);
        if (!tx) { showMessage('خطا', 'معامله یافت نشد.'); return; }
        // بر اساس نوع معامله فرم مناسب باز کن
        if (tx.type === 'فروش' || tx.type === 'پیش‌فاکتور') {
            showSection('sales-form');
            setTimeout(() => {
                window._billHydrating = true;   // بارگذاریِ بلِ ذخیره‌شده — قیمت‌ها بازنویسی نشوند
                initSalesForm();
                // پر کردن فیلدهای اصلی فرم فروش
                const dateEl = document.getElementById('sales-date');
                if (dateEl) dateEl.value = tx.date || '';
                const billEl = document.getElementById('sales-bill-number');
                if (billEl) billEl.value = tx.billNumber || '';
                const currencyEl = document.getElementById('sales-currency');
                if (currencyEl) currencyEl.value = tx.currency || _baseCur();
                const typeEl = document.getElementById('sales-type');
                if (typeEl) typeEl.value = tx.saleType || 'نقد';
                const notesEl = document.getElementById('sales-notes');
                if (notesEl) notesEl.value = tx.notes || tx.description || '';
                // پر کردن مشتری
                const hiddenCustomer = document.getElementById('qs-customer');
                const searchCustomer = document.getElementById('qs-customer-search');
                if (hiddenCustomer) hiddenCustomer.value = tx.customerId || tx.personId || '';
                if (searchCustomer) searchCustomer.value = tx.customerName || tx.personName || '';
                // پر کردن آیتم‌ها
                if (tx.items && Array.isArray(tx.items) && tx.items.length > 0) {
                    const tbody = document.getElementById('sales-items-body');
                    if (tbody) {
                        tbody.innerHTML = '';
                        tx.items.forEach((item, idx) => {
                            const row = addSalesItem();
                            if (row) {
                                const productInput = row.querySelector('.item-product');
                                const searchInput = row.querySelector('.product-search-input');
                                const qtyInput = row.querySelector('.item-quantity');
                                const priceInput = row.querySelector('.item-price');
                                const discountInput = row.querySelector('.item-discount');
                                const unitSpan = row.querySelector('.item-unit');
                                if (productInput) productInput.value = item.productId || '';
                                if (searchInput) searchInput.value = item.productName || '';
                                if (qtyInput) qtyInput.value = item.quantity || 1;
                                if (priceInput) priceInput.value = item.price || 0;
                                if (discountInput) discountInput.value = item.discount || 0;
                                if (unitSpan) unitSpan.textContent = item.unit || 'عدد';
                                // ===== بازگردانی اطلاعات واحد فرعی =====
                                row.dataset.unitType = item.unitType || 'primary';
                                row.dataset.secondaryFactor = (item.secondaryFactor !== undefined && item.secondaryFactor !== null) ? String(item.secondaryFactor) : '';
                                try {
                                    if (item.productId && typeof db !== 'undefined' && db.getProducts) {
                                        var _prods = db.getProducts();
                                        var _p = _prods.find(function(pp){ return pp.id == item.productId; });
                                        if (typeof _updateUnitSwitchVisibility === 'function') _updateUnitSwitchVisibility(row, _p);
                                    }
                                } catch(_e) {}
                                if (priceInput) updateItemTotal(priceInput);
                            }
                        });
                    }
                }
                // ═══ بازیابیِ کاملِ وضعیتِ پرداختیِ ذخیره‌شده (Hydration) ═══
                //  اصل: مقادیر از خودِ سند خوانده می‌شوند، نه محاسبهٔ مجدد از صفر.
                //  ارزِ سند تعیین می‌کند کدام فیلد پر شود — شاملِ ارزهای سوم به بعد
                //  (فیلدِ sales-cash-foreign که قبلاً هرگز پر نمی‌شد ⇒ باقی‌ماندهٔ اشتباه).
                (function _hydrateSalePayments() {
                    var _txCur = tx.currency || _baseCur();
                    var _base = _baseCur();
                    var _map = (tx.cashAmounts && typeof tx.cashAmounts === 'object' && !Array.isArray(tx.cashAmounts))
                        ? tx.cashAmounts : null;
                    // مبلغِ پرداختیِ هر ارز — اولویت با نگاشتِ چند-ارزی، سپس فیلدهای قدیمی (سازگاری)
                    function _paidFor(code) {
                        if (_map && _map[code] != null) return parseFloat(_map[code]) || 0;
                        if (code === _base && _base !== 'USD') return parseFloat(tx.cashAfn) || 0;
                        if (code === 'USD') return parseFloat(tx.cashUsd) || 0;
                        if (code === 'AFN') return parseFloat(tx.cashAfn) || 0;
                        if (code === _txCur) return parseFloat(tx.cashForeign) || 0;
                        return 0;
                    }
                    var cashAfnEl     = document.getElementById('sales-cash-afn');
                    var cashUsdEl     = document.getElementById('sales-cash-usd');
                    var cashForeignEl = document.getElementById('sales-cash-foreign');
                    // فیلدِ اصلی = مبلغِ ارزِ پایه؛ فیلدِ foreign = مبلغِ ارزِ سند اگر غیرپایه باشد
                    if (cashAfnEl)     cashAfnEl.value     = _paidFor(_base) || 0;
                    if (cashUsdEl)     cashUsdEl.value     = '';
                    if (cashForeignEl) {
                        cashForeignEl.value = (_txCur !== _base) ? (_paidFor(_txCur) || 0) : '';
                    }
                    // نمایشِ فیلدِ متناسب با ارزِ همین بل (شاملِ ارزِ سوم)
                    updateSalesCurrencyFields();
                    // اگر بل قبلاً تسویهٔ کامل بوده، وضعیتِ دکمهٔ تسویه هم بازگردانده شود
                    try {
                        var _rem = (typeof calculateTxRemaining === 'function') ? calculateTxRemaining(tx) : parseFloat(tx.remaining || 0);
                        var _chk = document.getElementById('full-payment-checkbox');
                        var _icon = document.getElementById('sales-fullpay-icon');
                        var _isSettled = (Math.abs(_rem) < 0.005) && (parseFloat(tx.totalAmount || 0) > 0);
                        if (_chk) _chk.checked = _isSettled;
                        if (_icon) _icon.classList.toggle('is-active', _isSettled);
                    } catch (e) {}
                })();
                // پر کردن حساب (اصلاح شده - قبلاً پر نمی‌شد)
                const salesCashbox = document.getElementById('sales-cashbox');
                if (salesCashbox && tx.cashboxId) salesCashbox.value = String(tx.cashboxId);
                // بازگردانیِ تخفیف کلیِ بل (تفاوتِ تخفیف کل و تخفیف اقلام) تا در ویرایش حفظ شود
                try {
                    var _txTotDisc = parseFloat(tx.totalDiscount || 0) || 0;
                    var _itemsDisc = (tx.items || []).reduce(function (s, it) { return s + (parseFloat(it.discount) || 0); }, 0);
                    var _overallDisc = _txTotDisc - _itemsDisc;
                    var _sDi = document.getElementById('sales-discount-input');
                    if (_sDi) {
                        if (_overallDisc > 0.0001) {
                            _sDi.value = _overallDisc;
                            var _amtR = document.querySelector('input[name="sales-discount-type"][value="amount"]');
                            if (_amtR) _amtR.checked = true;
                        } else {
                            _sDi.value = 0;
                        }
                    }
                } catch (e) {}
                calculateSalesTotal();
                calculateRemaining();
                // تنظیم حالت ویرایش
                const form = document.getElementById('salesForm');
                if (form) form.dataset.editId = id;
                // تغییر دکمه‌ها به حالت ویرایش
                const submitBtn = document.getElementById('sales-submit-btn');
                const printBtn = document.getElementById('sales-print-btn');
                if (submitBtn) submitBtn.innerHTML = '<i class="fas fa-save"></i> ذخیره تغییرات';
                if (printBtn) printBtn.style.display = 'none';
                window._billHydrating = false;   // پایانِ بارگذاری — رفتارِ عادیِ قیمت‌گذاری برگردد
            }, 200);
        } else if (tx.type === 'خرید') {
            showSection('purchase-form');
            setTimeout(() => {
                window._billHydrating = true;   // بارگذاریِ بلِ ذخیره‌شده — قیمت‌ها بازنویسی نشوند
                initPurchaseForm();
                if (document.getElementById('purchase-date')) document.getElementById('purchase-date').value = tx.date || '';
                if (document.getElementById('purchase-bill-number')) document.getElementById('purchase-bill-number').value = tx.billNumber || '';
                const hiddenSupplier = document.getElementById('qp-supplier');
                const searchSupplier = document.getElementById('qp-supplier-search');
                if (hiddenSupplier) hiddenSupplier.value = tx.supplierId || tx.personId || '';
                if (searchSupplier) searchSupplier.value = tx.supplierName || tx.personName || '';
                if (document.getElementById('purchase-currency')) document.getElementById('purchase-currency').value = tx.currency || _baseCur();
                if (document.getElementById('purchase-shipping')) document.getElementById('purchase-shipping').value = tx.shipping || 0;
                // بازگردانیِ ورودیِ پنلِ حمل‌ونقل و روشِ تقسیمِ ذخیره‌شده (پیش‌فرض: ارزش خرید)
                if (document.getElementById('purchase-shipping-input')) document.getElementById('purchase-shipping-input').value = tx.shipping || 0;
                var _editShipMethod = tx.shippingMethod || 'value';
                var _shipRadio = document.querySelector('input[name="purchase-shipping-method"][value="' + _editShipMethod + '"]');
                if (_shipRadio) _shipRadio.checked = true;
                // اگر این بل هزینه حمل دارد، پنلِ حمل‌ونقل را باز کن تا مبلغ و روش نمایان باشد
                if ((parseFloat(tx.shipping) || 0) > 0) {
                    var _shipPanelEl = document.getElementById('purchase-shipping-panel');
                    if (_shipPanelEl) _shipPanelEl.classList.add('open');
                }
                if (document.getElementById('purchase-notes')) document.getElementById('purchase-notes').value = tx.notes || tx.description || '';
                // پر کردن آیتم‌ها
                if (tx.items && Array.isArray(tx.items) && tx.items.length > 0) {
                    const tbody = document.getElementById('purchase-items-body');
                    if (tbody) {
                        tbody.innerHTML = '';
                        tx.items.forEach((item) => {
                            const row = addPurchaseItem();
                            if (row) {
                                const productInput = row.querySelector('.purchase-item-product');
                                const searchInput = row.querySelector('.product-search-input');
                                const qtyInput = row.querySelector('.purchase-item-quantity');
                                const priceInput = row.querySelector('.purchase-item-price');
                                const unitInput = row.querySelector('.purchase-item-unit');
                                const discountInput = row.querySelector('.purchase-item-discount');
                                if (productInput) productInput.value = item.productId || '';
                                if (searchInput) searchInput.value = item.productName || '';
                                if (qtyInput) qtyInput.value = item.quantity || 1;
                                if (priceInput) priceInput.value = item.price || 0;
                                if (unitInput) unitInput.value = item.unit || 'عدد';
                                if (discountInput) discountInput.value = item.discount || 0;
                                // ===== بازگردانی اطلاعات واحد فرعی =====
                                row.dataset.unitType = item.unitType || 'primary';
                                row.dataset.secondaryFactor = (item.secondaryFactor !== undefined && item.secondaryFactor !== null) ? String(item.secondaryFactor) : '';
                                try {
                                    if (item.productId && typeof db !== 'undefined' && db.getProducts) {
                                        var _prods2 = db.getProducts();
                                        var _p2 = _prods2.find(function(pp){ return pp.id == item.productId; });
                                        if (typeof _updateUnitSwitchVisibility === 'function') _updateUnitSwitchVisibility(row, _p2);
                                    }
                                } catch(_e) {}
                                if (priceInput) updatePurchaseItemTotal(priceInput);
                            }
                        });
                    }
                }
                // پر کردن حساب (اصلاح شده)
                const purchaseCashbox = document.getElementById('purchase-cashbox');
                if (purchaseCashbox && tx.cashboxId) purchaseCashbox.value = String(tx.cashboxId);
                // ═══ بازیابیِ کاملِ وضعیتِ پرداختیِ ذخیره‌شده (Hydration) ═══
                //  همان اصلِ فروش: مقادیر از خودِ سند خوانده می‌شوند و ارزِ سند تعیین
                //  می‌کند کدام فیلد پر شود — شاملِ ارزهای سوم به بعد.
                (function _hydratePurchasePayments() {
                    var _pCurTx = tx.currency || _baseCur();
                    var _pBaseH = _baseCur();
                    var _pMap = (tx.paidAmounts && typeof tx.paidAmounts === 'object' && !Array.isArray(tx.paidAmounts))
                        ? tx.paidAmounts : null;
                    function _paidForP(code) {
                        if (_pMap && _pMap[code] != null) return parseFloat(_pMap[code]) || 0;
                        if (code === _pBaseH && _pBaseH !== 'USD') return parseFloat(tx.paidAfn != null ? tx.paidAfn : tx.cashAfn) || 0;
                        if (code === 'USD') return parseFloat(tx.paidUsd != null ? tx.paidUsd : tx.cashUsd) || 0;
                        if (code === 'AFN') return parseFloat(tx.paidAfn != null ? tx.paidAfn : tx.cashAfn) || 0;
                        if (code === _pCurTx) return parseFloat(tx.paidForeign) || 0;
                        return 0;
                    }
                    var paidAfnEl     = document.getElementById('purchase-paid-afn');
                    var paidUsdEl     = document.getElementById('purchase-paid-usd');
                    var paidForeignEl = document.getElementById('purchase-paid-foreign');
                    if (paidAfnEl)     paidAfnEl.value     = _paidForP(_pBaseH) || 0;
                    if (paidUsdEl)     paidUsdEl.value     = '';
                    if (paidForeignEl) {
                        paidForeignEl.value = (_pCurTx !== _pBaseH) ? (_paidForP(_pCurTx) || 0) : '';
                    }
                    updatePurchaseCurrencyFields();
                    try {
                        var _remP = (typeof calculateTxRemaining === 'function') ? calculateTxRemaining(tx) : parseFloat(tx.remaining || 0);
                        var _chkP = document.getElementById('purchase-full-payment-checkbox');
                        var _iconP = document.getElementById('purchase-fullpay-icon');
                        var _isSettledP = (Math.abs(_remP) < 0.005) && (parseFloat(tx.totalAmount || 0) > 0);
                        if (_chkP) _chkP.checked = _isSettledP;
                        if (_iconP) _iconP.classList.toggle('is-active', _isSettledP);
                    } catch (e) {}
                })();
                // بازگردانیِ تخفیف کلیِ بل (تفاوتِ تخفیف کل و تخفیف اقلام) تا در ویرایش حفظ شود
                try {
                    var _pTotDisc = parseFloat(tx.totalDiscount || 0) || 0;
                    var _pItemsDisc = (tx.items || []).reduce(function (s, it) { return s + (parseFloat(it.discount) || 0); }, 0);
                    var _pOverallDisc = _pTotDisc - _pItemsDisc;
                    var _pDi = document.getElementById('purchase-discount-input');
                    if (_pDi) {
                        if (_pOverallDisc > 0.0001) {
                            _pDi.value = _pOverallDisc;
                            var _pAmtR = document.querySelector('input[name="purchase-discount-type"][value="amount"]');
                            if (_pAmtR) _pAmtR.checked = true;
                        } else {
                            _pDi.value = 0;
                        }
                    }
                } catch (e) {}
                // محاسبه مجدد باقی‌مانده
                calculatePurchaseTotal();
                calculatePurchaseRemaining();
                document.getElementById('purchaseForm') && (document.getElementById('purchaseForm').dataset.editId = id);
                const submitBtn = document.querySelector('#purchaseForm button[type="submit"]');
                if (submitBtn) submitBtn.textContent = 'ذخیره تغییرات خرید';
                window._billHydrating = false;   // پایانِ بارگذاری — رفتارِ عادیِ قیمت‌گذاری برگردد
            }, 200);
        } else if (tx.type === 'دریافت') {
            // تعیینِ editId پیش از showSection تا هوکِ نمایشِ بخش فرم را ریست نکند و مقادیرِ پرشده حفظ شوند
            var _rcFormPre = document.getElementById('receiptForm'); if (_rcFormPre) _rcFormPre.dataset.editId = id;
            showSection('receipt-form');
            setTimeout(() => {
                initReceiptForm();
                if (document.getElementById('receipt-date')) document.getElementById('receipt-date').value = tx.date || '';
                const hiddenFrom = document.getElementById('receive-from');
                const searchFrom = document.getElementById('receive-from-search');
                if (hiddenFrom) hiddenFrom.value = tx.personId || '';
                if (searchFrom) searchFrom.value = tx.personName || '';
                if (document.getElementById('receipt-amount')) document.getElementById('receipt-amount').value = tx.amount || tx.totalAmount || '';
                if (document.getElementById('receipt-currency')) document.getElementById('receipt-currency').value = tx.currency || _baseCur();
                if (document.getElementById('receipt-cashbox')) document.getElementById('receipt-cashbox').value = String(tx.cashboxId || '');
                if (document.getElementById('receipt-type')) document.getElementById('receipt-type').value = tx.receiptType || 'نقد';
                if (document.getElementById('receipt-description')) document.getElementById('receipt-description').value = (typeof _stripReceiptAutoNote === 'function' ? _stripReceiptAutoNote(tx.description || tx.notes || '') : (tx.description || tx.notes || ''));
                if (document.getElementById('receipt-reference')) document.getElementById('receipt-reference').value = tx.reference || '';
                document.getElementById('receiptForm') && (document.getElementById('receiptForm').dataset.editId = id);
                const submitBtn = document.querySelector('#receiptForm button[type="submit"]');
                if (submitBtn) submitBtn.textContent = 'ذخیره تغییرات دریافت';
                // بازگردانیِ تبِ مقصد (بدون ریست) + نشانه‌گذاریِ گروه برای به‌روزرسانیِ رکوردهای مرتبط
                try {
                    var _rForm = document.getElementById('receiptForm');
                    if (tx.expenseGroup) {
                        if (typeof _receiptInitExpenseCategory === 'function') _receiptInitExpenseCategory();
                        if (typeof _receiptSwitchTab === 'function') _receiptSwitchTab('expense');
                        var _catSel = document.getElementById('receipt-expense-category');
                        var _cat = tx.category || '';
                        if (!_cat) { try { var _le = (db.getExpenses() || []).find(function (e) { return e.expenseGroup === tx.expenseGroup; }); if (_le) _cat = _le.category || ''; } catch (e) {} }
                        if (_catSel && _cat) { if (!Array.prototype.some.call(_catSel.options, function (o) { return o.value === _cat; })) { var _op = document.createElement('option'); _op.value = _cat; _op.textContent = _cat; _catSel.appendChild(_op); } _catSel.value = _cat; }
                        if (_rForm) { _rForm.dataset.editGroupKey = 'expenseGroup'; _rForm.dataset.editGroupId = tx.expenseGroup; }
                    } else if (tx.transferGroup) {
                        if (typeof _receiptSwitchTab === 'function') _receiptSwitchTab('person');
                        var _isRecv = (tx.type === 'دریافت');
                        var _bId = _isRecv ? tx.personId : tx.counterpartyId, _bName = _isRecv ? tx.personName : tx.counterpartyName;
                        var _aId = _isRecv ? tx.counterpartyId : tx.personId, _aName = _isRecv ? tx.counterpartyName : tx.personName;
                        if (hiddenFrom) hiddenFrom.value = _aId || '';
                        if (searchFrom) searchFrom.value = _aName || '';
                        var _dpn = document.getElementById('receipt-dest-person'), _dps = document.getElementById('receipt-dest-person-search');
                        if (_dpn) _dpn.value = _bId || ''; if (_dps) _dps.value = _bName || '';
                        if (_rForm) { _rForm.dataset.editGroupKey = 'transferGroup'; _rForm.dataset.editGroupId = tx.transferGroup; }
                    } else {
                        if (typeof _receiptSwitchTab === 'function') _receiptSwitchTab('cashbox');
                    }
                } catch (e) {}
                // بازگردانیِ حالتِ «دریافت بدون پیگیری»
                var _ntrE = document.getElementById('receipt-notrack');
                if (_ntrE) _ntrE.checked = !!tx.noTrack;
                if (typeof _toggleReceiptNoTrack === 'function') _toggleReceiptNoTrack();
            }, 200);
        } else if (tx.type === 'پرداخت') {
            // تعیینِ editId پیش از showSection تا هوکِ نمایشِ بخش فرمِ پرداخت را ریست نکند و مقادیرِ پرشده حفظ شوند
            var _pyFormPre = document.getElementById('paymentForm'); if (_pyFormPre) _pyFormPre.dataset.editId = id;
            showSection('payment-form');
            setTimeout(() => {
                initPaymentForm();
                if (document.getElementById('payment-date')) document.getElementById('payment-date').value = tx.date || '';
                const hiddenTo = document.getElementById('pay-to');
                const searchTo = document.getElementById('pay-to-search');
                if (hiddenTo) hiddenTo.value = tx.personId || '';
                if (searchTo) searchTo.value = tx.personName || '';
                if (document.getElementById('payment-amount')) document.getElementById('payment-amount').value = tx.amount || tx.totalAmount || '';
                if (document.getElementById('payment-currency')) document.getElementById('payment-currency').value = tx.currency || _baseCur();
                if (document.getElementById('payment-cashbox')) document.getElementById('payment-cashbox').value = String(tx.cashboxId || '');
                if (document.getElementById('payment-type')) document.getElementById('payment-type').value = tx.paymentType || 'نقد';
                if (document.getElementById('payment-description')) document.getElementById('payment-description').value = (typeof _stripReceiptAutoNote === 'function' ? _stripReceiptAutoNote(tx.description || tx.notes || '') : (tx.description || tx.notes || ''));
                if (document.getElementById('payment-reference')) document.getElementById('payment-reference').value = tx.reference || '';
                document.getElementById('paymentForm') && (document.getElementById('paymentForm').dataset.editId = id);
                const submitBtn = document.querySelector('#paymentForm button[type="submit"]');
                if (submitBtn) submitBtn.textContent = 'ذخیره تغییرات پرداخت';
                // بازگردانیِ حالتِ «پرداخت بدون پیگیری»
                var _ntpE = document.getElementById('payment-notrack');
                if (_ntpE) _ntpE.checked = !!tx.noTrack;
                if (typeof _togglePaymentNoTrack === 'function') _togglePaymentNoTrack();
            }, 200);
        } else {
            showMessage('اطلاع', `ویرایش معامله نوع "${tx.type}" از این بخش امکان‌پذیر نیست.`);
        }
    } catch(e) {
        console.error('editTransaction error:', e);
    }
}

function deleteExpense(id) {
    showConfirm('تایید حذف', 'آیا از حذف این مصرف مطمئن هستید؟', function() {
        var expenses = db.getExpenses();
        var exp = expenses.find(function(e) { return e.id == id; });
        if (exp) {
            // برگشت موجودی حساب
            if (exp.cashboxId) db.updateCashboxBalance(exp.cashboxId, parseFloat(exp.amount || 0), 'in');
            addChangelog('حذف', 'مصرف', exp, 'حذف مصرف: ' + (exp.title || '') + ' - ' + (exp.amount || 0));
        }
        // حذف مستقیم از localStorage (db.deleteExpense وجود ندارد)
        var remaining = expenses.filter(function(e) { return e.id != id; });
        localStorage.setItem('expenses', JSON.stringify(remaining));
        // حذفِ آبشاری: تراکنشِ شخصِ مرتبط (هم‌گروهِ مصرف) نیز حذف شود تا هماهنگی حفظ شود
        if (exp && exp.expenseGroup) {
            try {
                var _txs = db.getTransactions ? db.getTransactions() : [];
                var _txFiltered = _txs.filter(function (t) { return t.expenseGroup !== exp.expenseGroup; });
                if (_txFiltered.length !== _txs.length) localStorage.setItem('transactions', JSON.stringify(_txFiltered));
            } catch (e) {}
        }
        loadExpensesList();
        showToast('مصرف حذف شد', 'success');
        if (typeof loadDashboard === 'function') loadDashboard();
        if (typeof instantUpdateAll === 'function') instantUpdateAll();
        if (typeof refreshOpenReport === 'function') refreshOpenReport();
    });
}

function deleteTransaction(id) {
    showConfirm('تایید حذف', 'آیا از حذف این معامله مطمئن هستید؟', function() {
        var transactions = db.getTransactions();
        var tx = transactions.find(function(t) { return t.id == id; });
        if (!tx) return;
        var txType = tx.type || '';
        // برگشت موجودی حساب
        // برای فروش/خرید فقط مبلغ نقدی واقعی (cashAfn/cashUsd یا paidAfn/paidUsd) باید برگردانده شود
        // — نه مبلغ کل بل — تا با اثر اصلی در saveTransaction سازگار باشد و حساب دقیق بماند.
        if (tx.cashboxId) {
            var _txCur = tx.currency || _baseCur();
            var _refundAmt = 0;
            if (txType === 'فروش') {
                _refundAmt = _txCur === 'USD' ? (parseFloat(tx.cashUsd) || 0) : (parseFloat(tx.cashAfn) || 0);
                if (_refundAmt > 0) db.updateCashboxBalance(tx.cashboxId, _refundAmt, 'out');
            } else if (txType === 'خرید') {
                _refundAmt = _txCur === 'USD' ? (parseFloat(tx.paidUsd) || parseFloat(tx.cashUsd) || 0) : (parseFloat(tx.paidAfn) || parseFloat(tx.cashAfn) || 0);
                if (_refundAmt > 0) db.updateCashboxBalance(tx.cashboxId, _refundAmt, 'in');
            } else if (txType === 'دریافت') {
                _refundAmt = parseFloat(tx.amount) || 0;
                if (_refundAmt > 0) db.updateCashboxBalance(tx.cashboxId, _refundAmt, 'out');
            } else if (txType === 'پرداخت') {
                _refundAmt = parseFloat(tx.amount) || 0;
                if (_refundAmt > 0) db.updateCashboxBalance(tx.cashboxId, _refundAmt, 'in');
            } else if (txType === 'برگشت') {
                var _retTxCur = tx.currency || _baseCur();
                _refundAmt = (tx.cashAmounts != null)
                    ? ((tx.cashAmounts[_retTxCur] != null) ? (parseFloat(tx.cashAmounts[_retTxCur]) || 0) : 0)
                    : (parseFloat(tx.totalAmount || tx.amount) || 0);
                if (_refundAmt > 0) {
                    if (tx.returnType === 'فروش') db.updateCashboxBalance(tx.cashboxId, _refundAmt, 'in', _retTxCur);
                    else if (tx.returnType === 'خرید') db.updateCashboxBalance(tx.cashboxId, _refundAmt, 'out', _retTxCur);
                }
            }
        }
        // برگشت موجودی انبار
        if ((txType === 'فروش') && Array.isArray(tx.items)) {
            tx.items.forEach(function(i) { db.updateProductStock(i.productId, _itemStockQty(i), 'in'); });
        } else if ((txType === 'خرید') && Array.isArray(tx.items)) {
            tx.items.forEach(function(i) { db.updateProductStock(i.productId, _itemStockQty(i), 'out'); });
        } else if ((txType === 'برگشت') && Array.isArray(tx.items)) {
            // معکوسِ اثرِ برگشت روی موجودی هنگام حذفِ سندِ برگشت
            tx.items.forEach(function(i) {
                if (i && i.isService) return;
                if (tx.returnType === 'فروش') db.updateProductStock(i.productId, _itemStockQty(i), 'out');
                else if (tx.returnType === 'خرید') db.updateProductStock(i.productId, _itemStockQty(i), 'in');
            });
        }
        // حذف هزینه حمل و نقلِ مرتبط با این بل خرید (با برگشتِ اثرِ حساب)
        if (txType === 'خرید' && typeof _syncPurchaseShippingExpense === 'function') {
            _syncPurchaseShippingExpense(id, 0);
        }
        // ثبت در تاریخچه تغییرات
        addChangelog('حذف', txType, tx, 'حذف ' + txType + (tx.billNumber ? ' شماره ' + tx.billNumber : '') + (tx.customerName || tx.supplierName || tx.personName ? ' - ' + (tx.customerName || tx.supplierName || tx.personName) : ''));
        // حذف از لیست + حذفِ آبشاریِ رکوردهای مرتبط (هم‌گروه) تا سیستم مالی هماهنگ و بدون دوگانگی بماند
        var _grpKeys = ['transferGroup', 'expenseGroup', 'convGroup'];
        var _grpId = null, _grpKey = null;
        for (var _gk = 0; _gk < _grpKeys.length; _gk++) { if (tx[_grpKeys[_gk]]) { _grpId = tx[_grpKeys[_gk]]; _grpKey = _grpKeys[_gk]; break; } }
        // برگشتِ اثرِ حسابِ رکوردهای هم‌گروه که حساب دارند (در صورت وجود)
        if (_grpId) {
            transactions.forEach(function (t) {
                if (t.id == id || t[_grpKey] !== _grpId) return;
                if (t.cashboxId) {
                    var _a = parseFloat(t.amount || t.totalAmount) || 0;
                    if (_a > 0) {
                        if (t.type === 'دریافت') db.updateCashboxBalance(t.cashboxId, _a, 'out');
                        else if (t.type === 'پرداخت') db.updateCashboxBalance(t.cashboxId, _a, 'in');
                    }
                }
            });
        }
        var filtered = transactions.filter(function(t) {
            if (t.id == id) return false;
            if (_grpId && t[_grpKey] === _grpId) return false;   // همهٔ رکوردهای هم‌گروه حذف شوند
            return true;
        });
        localStorage.setItem('transactions', JSON.stringify(filtered));
        // حذفِ ردیفِ مصرفِ مرتبط (اگر این معامله بخشی از یک گروهِ مصرف بود)
        if (_grpKey === 'expenseGroup' && _grpId) {
            try {
                var _exps = db.getExpenses ? db.getExpenses() : (JSON.parse(localStorage.getItem('expenses') || '[]'));
                var _expFiltered = _exps.filter(function (e) { return e.expenseGroup !== _grpId; });
                localStorage.setItem('expenses', JSON.stringify(_expFiltered));
            } catch (e) {}
        }
        showToast(txType + ' با موفقیت حذف شد', 'success');
        // بارگذاری مجدد
        if (txType === 'پیش‌فاکتور' || (tx && tx.isProforma)) { loadProformaList(); }
        else if (txType === 'فروش') { if (typeof loadSalesList === 'function') loadSalesList(); }
        else if (txType === 'خرید') { if (typeof loadPurchasesList === 'function') loadPurchasesList(); }
        else if (txType === 'دریافت') { if (typeof loadReceiptsList === 'function') loadReceiptsList(); }
        else if (txType === 'پرداخت') { if (typeof loadPaymentsList === 'function') loadPaymentsList(); }
        else { loadTransactionsList(); }
        if (typeof loadDashboard === 'function') loadDashboard();
        if (typeof refreshOpenReport === 'function') refreshOpenReport();
    });
}

// حذف معامله از داخل لیست معاملات فرد — wrapper اطراف deleteTransaction
// که بعد از حذف، لیست معاملات همان فرد را رفرش می‌کند.
function deletePersonTransaction(txId, personId) {
    // فراخوانی deleteTransaction اصلی (که خودش showConfirm، برگشت موجودی، changelog
    // و رفرش لیست‌های مرتبط را انجام می‌دهد)
    deleteTransaction(txId);
    // بعد از تأیید کاربر و انجام حذف، لیست معاملات این فرد را هم رفرش کن
    setTimeout(function() {
        var section = document.getElementById('person-transactions-list');
        if (section && section.classList.contains('active') && typeof loadPersonTransactions === 'function') {
            loadPersonTransactions(personId);
        }
    }, 350);
}

// ثبت تغییرات در تاریخچه (تابع موجود — تغییری ندارد)
function addChangelog(action, type, data, description) {
    try {
        var logs = JSON.parse(localStorage.getItem('changelog') || '[]');
        logs.push({
            id: Date.now(),
            date: (typeof PersianDate !== 'undefined') ? new PersianDate().format('YYYY/MM/DD HH:mm') : new Date().toLocaleString('fa-IR'),
            action: action,
            type: type,
            dataSnapshot: JSON.parse(JSON.stringify(data)),
            description: description || (action + ' ' + type)
        });
        // حداکثر 500 تغییر نگه دار
        if (logs.length > 500) logs = logs.slice(-500);
        localStorage.setItem('changelog', JSON.stringify(logs));
    } catch (e) { console.error('addChangelog error:', e); }
}

// برگشت از تغییر
function undoChange(changeId) {
    try {
        var logs = JSON.parse(localStorage.getItem('changelog') || '[]');
        var log = logs.find(function(l) { return l.id == changeId; });
        if (!log || !log.dataSnapshot) { showToast('اطلاعات برگشت یافت نشد', 'error'); return; }
        var data = log.dataSnapshot;

        if (log.action === 'حذف') {
            // بازگردانی آیتم حذف شده
            if (log.type === 'مصرف') {
                var expenses = db.getExpenses();
                expenses.push(data);
                localStorage.setItem('expenses', JSON.stringify(expenses));
                if (data.cashboxId) db.updateCashboxBalance(data.cashboxId, parseFloat(data.amount || 0), 'out');
            } else {
                var transactions = db.getTransactions();
                transactions.push(data);
                localStorage.setItem('transactions', JSON.stringify(transactions));
                // بازگردانی موجودی حساب
                if (data.cashboxId) {
                    var amt = parseFloat(data.totalAmount || data.amount || 0);
                    if (amt > 0) {
                        if (data.type === 'فروش' || data.type === 'دریافت') db.updateCashboxBalance(data.cashboxId, amt, 'in');
                        else if (data.type === 'خرید' || data.type === 'پرداخت') db.updateCashboxBalance(data.cashboxId, amt, 'out');
                    }
                }
                // بازگردانی موجودی انبار
                if (data.type === 'فروش' && Array.isArray(data.items)) {
                    data.items.forEach(function(i) { db.updateProductStock(i.productId, _itemStockQty(i), 'out'); });
                } else if (data.type === 'خرید' && Array.isArray(data.items)) {
                    data.items.forEach(function(i) { db.updateProductStock(i.productId, _itemStockQty(i), 'in'); });
                }
            }
        } else if (log.action === 'ویرایش') {
            // بازگردانی نسخه قبلی
            if (log.type === 'مصرف') {
                var expenses2 = db.getExpenses();
                var idx2 = expenses2.findIndex(function(e) { return e.id == data.id; });
                if (idx2 !== -1) { expenses2[idx2] = data; localStorage.setItem('expenses', JSON.stringify(expenses2)); }
            } else {
                var txs = db.getTransactions();
                var idx = txs.findIndex(function(t) { return t.id == data.id; });
                if (idx !== -1) { txs[idx] = data; localStorage.setItem('transactions', JSON.stringify(txs)); }
            }
        } else if (log.action === 'ثبت') {
            // برگشت از ثبت = حذف آیتم ایجادشده
            if (log.type === 'مصرف') {
                var expenses3 = db.getExpenses();
                var filtered3 = expenses3.filter(function(e) { return e.id != data.id; });
                localStorage.setItem('expenses', JSON.stringify(filtered3));
                if (data.cashboxId) db.updateCashboxBalance(data.cashboxId, parseFloat(data.amount || 0), 'in');
            } else if (log.type === 'شخص') {
                var ps = db.getPersons(); localStorage.setItem('persons', JSON.stringify(ps.filter(function(p){return p.id!=data.id;})));
            } else if (log.type === 'جنس') {
                var prs = (typeof db.getAllProducts === 'function' ? db.getAllProducts() : db.getProducts()); localStorage.setItem('products', JSON.stringify(prs.filter(function(p){return p.id!=data.id;})));
            } else if (log.type === 'صندوق') {
                db.deleteCashbox(data.id);
            } else {
                var txs2 = db.getTransactions();
                var filtered2 = txs2.filter(function(t) { return t.id != data.id; });
                localStorage.setItem('transactions', JSON.stringify(filtered2));
                if (data.cashboxId) {
                    var amt2 = parseFloat(data.totalAmount || data.amount || 0);
                    if (amt2 > 0) {
                        if (data.type === 'فروش' || data.type === 'دریافت') db.updateCashboxBalance(data.cashboxId, amt2, 'out');
                        else if (data.type === 'خرید' || data.type === 'پرداخت') db.updateCashboxBalance(data.cashboxId, amt2, 'in');
                    }
                }
                if (data.type === 'فروش' && Array.isArray(data.items)) {
                    data.items.forEach(function(i) { db.updateProductStock(i.productId, _itemStockQty(i), 'in'); });
                } else if (data.type === 'خرید' && Array.isArray(data.items)) {
                    data.items.forEach(function(i) { db.updateProductStock(i.productId, _itemStockQty(i), 'out'); });
                }
            }
        }

        // حذف این لاگ از تاریخچه (علامت‌گذاری به عنوان برگشت‌شده)
        log.undone = true;
        log.undoneAt = new Date().toISOString();
        localStorage.setItem('changelog', JSON.stringify(logs));

        // بازسازیِ کاملِ دادهٔ مشتق از دیتای خام تا موجودی/بهای خرید/مفادِ FIFO/مانده‌ها
        // پس از برگشت، دقیق و در همهٔ بخش‌ها هماهنگ شوند (بدونِ تداخل یا بی‌نظمی).
        try { if (typeof rebuildAllDerivedData === 'function') rebuildAllDerivedData(); } catch (e) {}

        showToast('تغییر با موفقیت برگشت داده شد', 'success');
        if (typeof loadDashboard === 'function') loadDashboard();
        if (typeof loadChangelogList === 'function') loadChangelogList();
        // رفرش لیست مرتبط
        if (data.type === 'فروش' && typeof loadSalesList === 'function') loadSalesList();
        else if (data.type === 'خرید' && typeof loadPurchasesList === 'function') loadPurchasesList();
        else if (data.type === 'دریافت' && typeof loadReceiptsList === 'function') loadReceiptsList();
        else if (data.type === 'پرداخت' && typeof loadPaymentsList === 'function') loadPaymentsList();
    } catch (e) {
        console.error('undoChange error:', e);
        showToast('خطا در برگشت تغییر', 'error');
    }
}

