// گزارش‌گیری
function initReports() {
    const today = new PersianDate();
    const firstDayOfMonth = new PersianDate([today.year, today.month, 1]);
    const fromEl = document.getElementById('report-from');
    const toEl = document.getElementById('report-to');
    if (fromEl) fromEl.value = firstDayOfMonth.format('YYYY/MM/DD');
    if (toEl) toEl.value = today.format('YYYY/MM/DD');

    // ── بهبودِ عملکردِ باز شدنِ بخشِ گزارش (بدونِ هیچ تغییری در منطق/محاسبه) ──
    // محاسباتِ سنگینِ گزارش (generateReport + رندرِ زندهٔ کارت + مفاد/FIFO) پیش‌تر
    // «همزمان» با کلیک اجرا می‌شد و باعث می‌شد بخش دیر و سنگین باز شود. اکنون همان
    // توابع با همان ورودی/خروجی، فقط «پس از رنگ‌آمیزیِ صفحه» (دو فریمِ بعد) اجرا می‌شوند
    // تا بخشِ گزارش فوری باز شود و تجربهٔ کاربری روان بماند. نتیجهٔ گزارش دقیقاً یکسان است.
    var _rpInitRun = function () {
        try { generateReport(); } catch (e) { console.error('initReports(generate):', e); }
        try {
            // ریست‌کردنِ فیلترها و انتخاب‌ها هنگامِ ورود مجدد (قفل‌نشدنِ حالتِ قبلی).
            // استثنا: وقتی از «انتخابگرِ حساب/اجناسِ» گزارشِ مفاد برمی‌گردیم، این ریستِ
            // async نباید انتخابِ تازه‌اعمال‌شده را پاک کند؛ یک پرچمِ یک‌بارمصرف آن را رد می‌کند.
            if (window._rpSkipNextInitReset) { window._rpSkipNextInitReset = false; }
            else if (typeof _rpResetReportFilters === 'function') _rpResetReportFilters();
            var _sec = document.getElementById('report-section-select');
            if (_sec) {
                if (typeof onReportSectionChange === 'function') onReportSectionChange(_sec.value);
                if (typeof _rpPopulateCurOne === 'function') _rpPopulateCurOne();
                if (typeof _rpLive === 'function') _rpLive();
            }
        } catch (e) { console.error('initReports(new):', e); }
    };
    if (typeof requestAnimationFrame === 'function') {
        requestAnimationFrame(function () { requestAnimationFrame(_rpInitRun); });
    } else {
        setTimeout(_rpInitRun, 0);
    }
}

// ریستِ کاملِ فیلترها و انتخاب‌های گزارش (هنگام ورود مجدد به بخش)
function _rpResetReportFilters() {
    // ارز → همه ارزها
    var cm = document.getElementById('rp-cur-mode'); if (cm) cm.value = 'all';
    document.querySelectorAll('.rp-cur-btn').forEach(function (b) { b.classList.toggle('active', b.getAttribute('data-mode') === 'all'); });
    var onePills = document.getElementById('rp-cur-one-pills'); if (onePills) onePills.style.display = 'none';
    // زمان → همه
    var ts = document.getElementById('report-time-select'); if (ts) ts.value = 'all';
    var df = document.getElementById('rp-date-from-wrap'), dt = document.getElementById('rp-date-to-wrap');
    if (df) df.classList.add('rp-date-hidden'); if (dt) dt.classList.add('rp-date-hidden');
    var dfi = document.getElementById('report-date-from'); if (dfi) dfi.value = '';
    var dti = document.getElementById('report-date-to'); if (dti) dti.value = '';
    // اشخاص
    if (typeof _rpSelectedPersons !== 'undefined') { _rpSelectedPersons = []; if (typeof _rpRenderPersonChips === 'function') _rpRenderPersonChips(); }
    var apc = document.getElementById('rp-all-persons'); if (apc) apc.checked = true;
    var psw = document.getElementById('rp-person-select-wrap'); if (psw) psw.style.display = 'none';
    // اجناس
    if (typeof _rpSelectedProducts !== 'undefined') { _rpSelectedProducts = []; if (typeof _rpRenderProductChips === 'function') _rpRenderProductChips(); }
    var psAll = document.querySelector('input[name="rp-product-scope"][value="all"]'); if (psAll) psAll.checked = true;
    var wh = document.getElementById('rp-warehouse-select'); if (wh) wh.value = '';
    // مصارف: تمام کتگوری‌ها
    var allCat = document.getElementById('rp-all-categories'); if (allCat) allCat.checked = true;
    var catWrap = document.getElementById('rp-category-select-wrap'); if (catWrap) catWrap.style.display = 'none';
    var catSel = document.getElementById('rp-category-select'); if (catSel) catSel.value = '';
    // مفاد و سرمایه: پاک‌کردنِ انتخاب‌ها
    if (typeof _rpPsPersons !== 'undefined') _rpPsPersons = [];
    if (typeof _rpPsProducts !== 'undefined') _rpPsProducts = [];
    if (typeof _rpPsServices !== 'undefined') _rpPsServices = false;
    if (typeof _rpPsRenderChips === 'function') _rpPsRenderChips();
    if (typeof _rpPsSyncChipButtons === 'function') _rpPsSyncChipButtons();
    var aw = document.getElementById('rp-ps-account-wrap'); if (aw) aw.style.display = 'none';
    var gw = document.getElementById('rp-ps-goods-wrap'); if (gw) gw.style.display = 'none';
}
if (typeof window !== 'undefined') window._rpResetReportFilters = _rpResetReportFilters;

function generateReport() {
    try { window._rpRerunLast = generateReport; } catch (e) {}
    const reportType = (document.getElementById('report-type') || {}).value || 'sales';
    const fromDate = (document.getElementById('report-from') || {}).value || '';
    const toDate = (document.getElementById('report-to') || {}).value || '';

    const cashboxes = db.getCashboxes() || [];
    const getCashboxName = (id) => {
        const cb = cashboxes.find(c => c.id == id);
        return cb ? cb.name : (id || '---');
    };

    const inRange = (date) => {
        if (!date) return true;
        if (fromDate && date < fromDate) return false;
        if (toDate && date > toDate) return false;
        return true;
    };

    const tbody = document.querySelector('#detailed-report-table tbody');
    if (!tbody) return;
    tbody.innerHTML = '';

    let totalAFN = 0, totalUSD = 0, count = 0;
    var totalXtra = {}; // جمعِ ارزهای سوم به بعد در گزارش‌های فروش/خرید/مصارف

    if (reportType === 'profit') {
        // گزارش سود خالص
        const sales = db.getTransactions().filter(t => t.type === 'فروش' && inRange(t.date));
        const purchases = db.getTransactions().filter(t => t.type === 'خرید' && inRange(t.date));
        const expenses = db.getExpenses().filter(e => inRange(e.date));
        const receipts = db.getTransactions().filter(t => t.type === 'دریافت' && inRange(t.date));
        const payments = db.getTransactions().filter(t => t.type === 'پرداخت' && inRange(t.date));

        let salesAFN = 0, salesUSD = 0;
        let purchaseAFN = 0, purchaseUSD = 0;
        let expenseAFN = 0, expenseUSD = 0;
        var salesXtra = {}, purchaseXtra = {}, expenseXtra = {};
        var _finBaseC = _baseCur();
        // ستونِ اول = ارزِ پایه؛ ستونِ دوم = هر ارزِ غیرپایه (پویا)
        var _xtraCell = function (cur, amt) { return ((cur || _finBaseC) === _finBaseC) ? formatAmountWithCurrency(amt, _finBaseC) : '---'; };
        var _usdCell = function (cur, amt) { return ((cur || _finBaseC) !== _finBaseC) ? formatAmountWithCurrency(amt, cur) : '---'; };

        sales.forEach(t => {
            const amt = parseFloat(t.totalAmount || t.amount || 0);
            var _sc = t.currency || _finBaseC; if (_sc === _finBaseC) salesAFN += amt; else salesXtra[_sc] = (salesXtra[_sc] || 0) + amt;
            const row = document.createElement('tr');
            row.innerHTML = `<td>${t.date || t.createdAt || '-'}</td><td><span class="badge badge-success">فروش</span></td><td>${t.customerName || t.personName || '---'}</td><td>${_xtraCell(t.currency, amt)}</td><td>${_usdCell(t.currency, amt)}</td><td>${getCashboxName(t.cashboxId)}</td>`;
            tbody.appendChild(row);
        });
        purchases.forEach(t => {
            const amt = parseFloat(t.totalAmount || t.amount || 0);
            var _pc = t.currency || _finBaseC; if (_pc === _finBaseC) purchaseAFN += amt; else purchaseXtra[_pc] = (purchaseXtra[_pc] || 0) + amt;
            const row = document.createElement('tr');
            row.innerHTML = `<td>${t.date || t.createdAt || '-'}</td><td><span class="badge badge-primary">خرید</span></td><td>${t.supplierName || t.personName || '---'}</td><td>${_xtraCell(t.currency, amt)}</td><td>${_usdCell(t.currency, amt)}</td><td>${getCashboxName(t.cashboxId)}</td>`;
            tbody.appendChild(row);
        });
        expenses.forEach(e => {
            const amt = parseFloat(e.amount || 0);
            var _ec = e.currency || _finBaseC; if (_ec === _finBaseC) expenseAFN += amt; else expenseXtra[_ec] = (expenseXtra[_ec] || 0) + amt;
            const row = document.createElement('tr');
            row.innerHTML = `<td>${e.date || e.createdAt || '-'}</td><td><span class="badge badge-danger">مصرف</span></td><td>${e.title || '---'} ${e.category ? '(' + e.category + ')' : ''}</td><td>${_xtraCell(e.currency, amt)}</td><td>${_usdCell(e.currency, amt)}</td><td>${e.cashboxName || getCashboxName(e.cashboxId)}</td>`;
            tbody.appendChild(row);
        });

        // اصلاحِ ج-۵: «سودِ خالص» دیگر فروش−خرید−مصرف (جریانِ نقدی) نیست؛ سودِ واقعیِ
        //  عملیاتی از موتورِ FIFO محاسبه می‌شود (بهای تمام‌شدهٔ همان اقلامِ فروخته‌شده، نه
        //  کلِ خریدِ بازه) و مصارف از آن کسر می‌شود. ارزهای مختلف دیگر مستقیماً از هم کم
        //  نمی‌شوند؛ هر ارز جدا، و جمعِ کل به ارزِ مرجع نمایش داده می‌شود.
        var _ps1 = (typeof _computeProfitSummary === 'function')
            ? _computeProfitSummary(sales, expenses, null)
            : { netByCur: {}, netBase: 0, base: 'AFN', estimated: false };
        var _net1 = _ps1.netByCur || {};
        count = sales.length + purchases.length + expenses.length;
        totalAFN = _net1.AFN || 0;
        totalUSD = _net1.USD || 0;

        // سطر جمع‌بندیِ سود (AFN/USD ثابت)
        const summaryRow = document.createElement('tr');
        summaryRow.style.fontWeight = 'bold';
        summaryRow.style.background = (totalAFN >= 0) ? '#d4edda' : '#f8d7da';
        var _estMark = _ps1.estimated ? ' <span title="شاملِ سودِ تخمینی (سندِ بدونِ نرخِ ثبت‌شده)" style="color:#d97706;">*</span>' : '';
        summaryRow.innerHTML = `<td colspan="3"><strong>سود خالص${_estMark}</strong></td><td>${formatCurrency(totalAFN)}</td><td>${formatCurrency(totalUSD)}</td><td>---</td>`;
        tbody.appendChild(summaryRow);

        // سطرهای سود برای ارزهای سوم به بعد (پویا)
        Object.keys(_net1).forEach(function (c) {
            if (c === 'AFN' || c === 'USD') return;
            var pf = _net1[c] || 0; if (!pf) return;
            var r = document.createElement('tr');
            r.style.fontWeight = 'bold';
            r.style.background = pf >= 0 ? '#d4edda' : '#f8d7da';
            r.innerHTML = '<td colspan="3"><strong>سود خالص (' + _curLabelGlobal(c) + ')</strong></td><td>' + formatNumber(pf) + ' ' + _curSymGlobal(c) + '</td><td>---</td><td>---</td>';
            tbody.appendChild(r);
        });

        // سطرِ «جمعِ کل به ارزِ مرجع» — تنها جمعِ درستِ بینِ ارزها (اصلاحِ ج-۵)
        if (Object.keys(_net1).filter(function (c) { return _net1[c]; }).length > 1) {
            var _bsym1 = (typeof _curSymGlobal === 'function') ? _curSymGlobal(_ps1.base) : _ps1.base;
            var rBase = document.createElement('tr');
            rBase.style.fontWeight = 'bold';
            rBase.style.background = (_ps1.netBase >= 0) ? '#d1ecf1' : '#f8d7da';
            rBase.innerHTML = '<td colspan="3"><strong>سود خالص (معادلِ ' + _curLabelGlobal(_ps1.base) + ')</strong></td><td>' + formatNumber(_ps1.netBase) + ' ' + _bsym1 + '</td><td>---</td><td>---</td>';
            tbody.appendChild(rBase);
        }

    } else if (reportType === 'sales') {
        const data = db.getTransactions().filter(t => t.type === 'فروش' && inRange(t.date));
        count = data.length;
        data.forEach(t => {
            const amt = parseFloat(t.totalAmount || t.amount || 0);
            var _tc2 = t.currency || _finBaseC; if (_tc2 === _finBaseC) totalAFN += amt; else totalXtra[_tc2] = (totalXtra[_tc2] || 0) + amt;
            const row = document.createElement('tr');
            row.innerHTML = `<td>${t.date || t.createdAt || '-'}</td><td><span class="badge badge-success">فروش</span></td><td>${t.customerName || t.personName || '---'} ${t.billNumber ? '| بل: ' + t.billNumber : ''}</td><td>${t.currency === 'USD' ? '---' : formatCurrency(amt, t.currency || _baseCur())}</td><td>${t.currency === 'USD' ? formatCurrency(amt) : '---'}</td><td>${getCashboxName(t.cashboxId)}</td>`;
            tbody.appendChild(row);
        });

    } else if (reportType === 'purchases') {
        const data = db.getTransactions().filter(t => t.type === 'خرید' && inRange(t.date));
        count = data.length;
        data.forEach(t => {
            const amt = parseFloat(t.totalAmount || t.amount || 0);
            var _tc2 = t.currency || _finBaseC; if (_tc2 === _finBaseC) totalAFN += amt; else totalXtra[_tc2] = (totalXtra[_tc2] || 0) + amt;
            const row = document.createElement('tr');
            row.innerHTML = `<td>${t.date || t.createdAt || '-'}</td><td><span class="badge badge-primary">خرید</span></td><td>${t.supplierName || t.personName || '---'} ${t.billNumber ? '| بل: ' + t.billNumber : ''}</td><td>${t.currency === 'USD' ? '---' : formatCurrency(amt, t.currency || _baseCur())}</td><td>${t.currency === 'USD' ? formatCurrency(amt) : '---'}</td><td>${getCashboxName(t.cashboxId)}</td>`;
            tbody.appendChild(row);
        });

    } else if (reportType === 'expenses') {
        const data = db.getExpenses().filter(e => inRange(e.date));
        count = data.length;
        data.forEach(e => {
            const amt = parseFloat(e.amount || 0);
            var _ec2 = e.currency || _finBaseC; if (_ec2 === _finBaseC) totalAFN += amt; else totalXtra[_ec2] = (totalXtra[_ec2] || 0) + amt;
            const row = document.createElement('tr');
            row.innerHTML = `<td>${e.date || e.createdAt || '-'}</td><td><span class="badge badge-danger">مصرف</span></td><td>${e.title || '---'} ${e.category ? '(' + e.category + ')' : ''}</td><td>${e.currency === 'USD' ? '---' : formatCurrency(amt, e.currency || _baseCur())}</td><td>${e.currency === 'USD' ? formatCurrency(amt) : '---'}</td><td>${e.cashboxName || getCashboxName(e.cashboxId)}</td>`;
            tbody.appendChild(row);
        });
    }

    if (tbody.children.length === 0) {
        const emptyRow = document.createElement('tr');
        emptyRow.innerHTML = `<td colspan="6" style="text-align:center; color:#999; padding:20px;">هیچ داده‌ای برای این بازه زمانی یافت نشد</td>`;
        tbody.appendChild(emptyRow);
    }

    const totalEl = document.getElementById('report-total-sales');
    const countEl = document.getElementById('report-invoice-count');
    const avgEl = document.getElementById('report-average-invoice');

    if (totalEl) {
        var _xtraStr = '';
        Object.keys(totalXtra).forEach(function (c) { var v = totalXtra[c] || 0; if (v) _xtraStr += ' | ' + formatNumber(v) + ' ' + _curSymGlobal(c); });
        if (totalUSD !== 0) {
            totalEl.textContent = formatCurrencyAFN(totalAFN) + ' | ' + formatNumber(totalUSD) + ' دالر' + _xtraStr;
        } else {
            totalEl.textContent = formatCurrencyAFN(totalAFN) + _xtraStr;
        }
    }
    if (countEl) countEl.textContent = count;
    if (avgEl) {
        const avg = count > 0 ? totalAFN / count : 0;
        avgEl.textContent = formatCurrencyAFN(avg);
    }
}

