// تابع رفرش بخش گزارشات (مورد نیاز loadReports در instantUpdateAll)
function loadReports() {
    // هیچ اقدامی لازم نیست - فیلترها توسط کاربر تنظیم می‌شوند
}

// هنگام تغییر بخش، فیلترهای پویا را نمایش/پنهان کن
function onReportSectionChange(value) {
    var personsOptions   = document.getElementById('rp-persons-options');
    var financialOptions = document.getElementById('rp-financial-options');
    var productsOptions  = document.getElementById('rp-products-options');
    var profitOptions    = document.getElementById('rp-profit-options');
    var resultsContainer = document.getElementById('rp-results-container');

    if (personsOptions)   personsOptions.style.display   = (value === 'persons')   ? 'block' : 'none';
    if (financialOptions) financialOptions.style.display  = (value === 'financial') ? 'block' : 'none';
    if (productsOptions)  productsOptions.style.display   = (value === 'products')  ? 'block' : 'none';
    if (profitOptions)    profitOptions.style.display     = (value === 'profit')    ? 'block' : 'none';
    if (resultsContainer) resultsContainer.style.display  = 'none';
    var _rpCardWrap = document.getElementById('rp-persons-card-wrap');
    if (_rpCardWrap) _rpCardWrap.style.display = (value === 'all' || value === 'persons' || value === 'products' || value === 'financial' || value === 'profit') ? 'block' : 'none';

    if (value === 'persons')   { loadPersonsForReportSelect(); if (typeof _rpPopulateCurOne === 'function') _rpPopulateCurOne(); }
    if (value === 'products')  { if (typeof _rpPopulateWarehouses === 'function') _rpPopulateWarehouses(); if (typeof _rpPopulateCurOne === 'function') _rpPopulateCurOne(); }
    if (value === 'financial') { if (typeof _rpPopulateCurOne === 'function') _rpPopulateCurOne(); }
    if (value === 'profit')    { if (typeof _rpPopulateCurOne === 'function') _rpPopulateCurOne(); }
    if (value === 'all')       { if (typeof _rpPopulateCurOne === 'function') _rpPopulateCurOne(); if (typeof _rpPopulateWarehouses === 'function') _rpPopulateWarehouses(); }
    if (value === 'financial') loadCategoriesForReportSelect();
    if (value === 'products') {
        // reset radio to default
        var radios = document.querySelectorAll('input[name="rp-product-scope"]');
        radios.forEach(function(r){ if (r.value === 'all') r.checked = true; });
        onProductScopeChange('all');
    }
}

