        try { ws['!views'] = [{ RTL: true }]; } catch (e) {}
        // عرضِ ستون‌ها
        var cols = []; for (var k = 0; k < ncols; k++) cols.push({ wch: k === 0 ? 20 : 14 }); ws['!cols'] = cols;
        // ادغام‌ها: عنوانِ سربرگ در ردیفِ ۰ + ادغام‌های نامِ اشخاص (با offset)
        var merges = [{ s: { r: 0, c: 0 }, e: { r: 0, c: ncols - 1 } }];
        (built.merges || []).forEach(function (m) { merges.push({ s: { r: m.r0 + offset, c: m.c }, e: { r: m.r1 + offset, c: m.c } }); });
        ws['!merges'] = merges;
