        wb.Workbook = { Views: [{ RTL: true }] };
        XLSX.utils.book_append_sheet(wb, ws, 'گزارش');
        var fname = _rpKindTitle(kind).replace(/[\\/\\\\ ]/g, '_');
        try { fname = fname + '_' + new PersianDate().format('YYYYMMDD_HHmmss'); } catch (e) { fname = fname + '_' + Date.now(); }
        XLSX.writeFile(wb, fname + '.xlsx');
