function _rpSyncSelectedProductsFromHidden() {
    var hid = document.getElementById('rp-product-single-id');
    var inp = document.getElementById('rp-product-single-search');
    var sid = hid ? hid.value : '';
    if (!Array.isArray(_rpSelectedProducts)) _rpSelectedProducts = [];
    if (sid && !_rpSelectedProducts.some(function (p) { return String(p.id) === String(sid); })) {
        var name = (inp && inp.value) ? inp.value : '';
        if (!name) { var pp = (db.getProducts() || []).find(function (x) { return String(x.id) === String(sid); }); name = pp ? pp.name : sid; }
        _rpSelectedProducts.push({ id: sid, name: name });
    }
    if (hid) hid.value = '';
    if (inp) inp.value = '';
    _rpRenderProductChips();
}
function _rpRemoveProduct(id) {
    _rpSelectedProducts = _rpSelectedProducts.filter(function (p) { return String(p.id) !== String(id); });
    _rpRenderProductChips();
    if (typeof _rpLive === 'function') _rpLive();
}
if (typeof window !== 'undefined') window._rpRemoveProduct = _rpRemoveProduct;
function _rpRenderProductChips() {
    var box = document.getElementById('rp-product-chips'); if (!box) return;
    if (!Array.isArray(_rpSelectedProducts)) _rpSelectedProducts = [];
    box.innerHTML = _rpSelectedProducts.map(function (p) {
        return '<span class="rp-chip">' + p.name + '<i class="fas fa-times" onclick="_rpRemoveProduct(\'' + String(p.id).replace(/'/g, "") + '\')"></i></span>';
    }).join('');
}

// ========================================================================
// انتخابِ چندگانهٔ اجناس از «گدام» برای بخشِ گزارش (اجناس + مفاد و سرمایه)
