if (typeof window !== 'undefined') window._rpConfirmProductPick = _rpConfirmProductPick;

function _rpCancelProductPick() { _rpExitProductPick(); }
if (typeof window !== 'undefined') window._rpCancelProductPick = _rpCancelProductPick;

function _rpExitProductPick() {
    var _wasTransfer = (_rpProductPick && _rpProductPick.target === 'transfer');
    _rpProductPick = null;
    _productPickerInput = null;
    _productPickerIsPurchase = false;
    _productPickerReturnSection = null;
    _rpRemoveProductPickBar();
    if (typeof _restorePickerBackButton === 'function') _restorePickerBackButton();
    if (_wasTransfer) {
        // بازگشت به فورمِ انتقال (بدونِ افزودنِ چیزِ جدید) — وضعیتِ قبلی بازسازی می‌شود
        if (typeof window._whReopenAfterPick === 'function') { window._whReopenAfterPick([]); return; }
    }
    if (typeof showSection === 'function') showSection('reports');
}
if (typeof window !== 'undefined') window._rpExitProductPick = _rpExitProductPick;

// تجمیعِ N-ارزیِ گزارشِ اجناس (scope: تمام/کتگوری/جنس مشخص + گدام)
