            var pUnit = np.unit;
            if (!pUnit) { try { pUnit = (typeof db.getPurchasePrice === 'function') ? (parseFloat(db.getPurchasePrice(p, np.cur)) || 0) : 0; } catch (e) {} }
            purchaseValByCur[np.cur] = (purchaseValByCur[np.cur] || 0) + stock * pUnit;
            var ns = _nativePrice(p.salePrices, 'salePriceAFN', 'sale');
            var sUnit = ns.unit;
            if (!sUnit) { try { sUnit = (typeof db.getSalePrice === 'function') ? (parseFloat(db.getSalePrice(p, ns.cur)) || 0) : 0; } catch (e) {} }
            saleValByCur[ns.cur] = (saleValByCur[ns.cur] || 0) + stock * sUnit;
