function cleanupOldData() {
    try {
        // حذف معاملات قدیمی تر از 1 سال
        const transactions = db.getTransactions();
        const oneYearAgo = new Date();
        oneYearAgo.setFullYear(oneYearAgo.getFullYear() - 1);
        
        const filteredTransactions = transactions.filter(t => {
            const transDate = new Date(t.createdAt || t.date);
            return transDate >= oneYearAgo;
        });
        
        localStorage.setItem('transactions', JSON.stringify(filteredTransactions));
        showMessage('موفقیت', `پاکسازی انجام شد. ${transactions.length - filteredTransactions.length} تراکنش حذف شد.`);
    } catch (error) {
        console.error('خطا در پاکسازی:', error);
        showMessage('خطا', 'خطا در پاکسازی داده‌ها');
    }
}

