// تابع applyGlobalDiscount
function applyGlobalDiscount() {
    const discountPercent = prompt('لطفاً درصد تخفیف عمومی را وارد کنید:', '5');
    
    if (discountPercent !== null) {
        const discount = parseFloat(discountPercent);
        if (!isNaN(discount) && discount >= 0 && discount <= 100) {
            const rows = document.querySelectorAll('#sales-items-body .item-row');
            rows.forEach(row => {
                const priceInput = row.querySelector('.item-price');
                const quantityInput = row.querySelector('.item-quantity');
                const discountInput = row.querySelector('.item-discount');
                
                const price = parseFormattedNumber(priceInput.value);
                const quantity = parseFormattedNumber(quantityInput.value);
                
                if (price > 0 && quantity > 0) {
                    const newDiscount = (price * quantity * discount) / 100;
                    discountInput.value = newDiscount;
                    updateItemTotal(discountInput);
                }
            });
            showMessage('موفقیت', `تخفیف ${discount}% اعمال شد.`);
        } else {
            showMessage('خطا', 'لطفاً یک درصد معتبر وارد کنید (0-100)');
        }
    }
}

