// تابع مشاهده معامله
function viewTransaction(id) {
    try {
        const tx = (db.getTransactions ? db.getTransactions() : []).find(t => t.id == id);
        if (!tx) { showMessage('خطا', 'معامله یافت نشد.'); return; }
        // فروش/خرید/دریافت/پرداخت → نمای کاملِ اطلاعات
        if ((tx.type === 'فروش' || tx.type === 'خرید' || tx.type === 'پیش‌فاکتور' || tx.type === 'دریافت' || tx.type === 'پرداخت') && typeof showTxDetail === 'function') {
            showTxDetail(id);
            return;
        }
        const formatAmt = (v) => new Intl.NumberFormat((typeof getNumberSystem === 'function' && getNumberSystem() === 'en') ? 'en-US' : 'fa-IR').format(parseFloat(v) || 0);
        let itemsHtml = '';
        if (tx.items && tx.items.length > 0) {
            itemsHtml = '<hr><strong>اقلام:</strong><ul style="margin:6px 0;padding-right:18px;">';
            tx.items.forEach((item, i) => {
                itemsHtml += '<li>' + (i+1) + '. ' + (item.productName || item.name || '-') + ' — تعداد: ' + (item.qty || item.quantity || 0) + ' × ' + formatAmt(item.price) + '</li>';
            });
            itemsHtml += '</ul>';
        }
        const details = [
            'نوع: ' + (tx.type || '-'),
            'تاریخ: ' + (tx.date || (tx.createdAt || '-').split(' ')[0]),
            'شماره بل: ' + (tx.billNumber || '-'),
            'طرف حساب: ' + (tx.customerName || tx.personName || tx.supplierName || '-'),
            'مبلغ کل: ' + formatAmt(tx.totalAmount || tx.amount) + ' ' + (tx.currency || _baseCur()),
        ];
        // نمایش وضعیت بر اساس باقی‌مانده واقعی (همسان با لیست‌ها)
        if (tx.type === 'فروش' || tx.type === 'خرید') {
            var txRem = calculateTxRemaining(tx);
            if (txRem > 0) {
                details.push('وضعیت: باقی‌دار: ' + formatAmt(txRem) + ' ' + (tx.currency || _baseCur()));
            } else if (txRem < 0) {
                details.push('وضعیت: اضافه پرداخت: ' + formatAmt(Math.abs(txRem)) + ' ' + (tx.currency || _baseCur()));
            } else {
                details.push('وضعیت: تسویه');
            }
        } else {
            if (tx.status) details.push('وضعیت: ' + tx.status);
        }
        if (tx.notes || tx.description) details.push('یادداشت: ' + (tx.notes || tx.description));
        showMessage('جزئیات معامله', '<div style="text-align:right;direction:rtl;line-height:2">' + details.filter(Boolean).join('<br>') + itemsHtml + '</div>');
    } catch(e) {
        console.error('viewTransaction error:', e);
        showMessage('خطا', 'خطا در نمایش جزئیات معامله');
    }
}

