function formatNumber(num) {
    var sys = (typeof getNumberSystem === 'function') ? getNumberSystem() : 'fa';
    if (sys === 'en') return new Intl.NumberFormat('en-US').format(num || 0);
    return new Intl.NumberFormat('fa-IR').format(num || 0);
}
