// نمایش منوی عملیات افراد
function showPersonActionsMenu(personId) {
    const menuId = `person-actions-menu-${personId}`;
    let menu = document.getElementById(menuId);
    
    if (!menu) {
        const person = db.getPersons().find(p => p.id == personId);
        if (!person) return;
        
        menu = document.createElement('div');
        menu.id = menuId;
        menu.className = 'person-actions-menu';
        menu.innerHTML = `
            <a href="#" onclick="startNewSaleForPerson(${personId}); return false;">
                <i class="fas fa-cart-plus"></i> فروش جدید
            </a>
            <a href="#" onclick="startNewPurchaseForPerson(${personId}); return false;">
                <i class="fas fa-shopping-basket"></i> خرید جدید
            </a>
            <a href="#" onclick="startNewReceiptForPerson(${personId}); return false;">
                <i class="fas fa-hand-holding-usd"></i> دریافتی جدید
            </a>
            <a href="#" onclick="startNewPaymentForPerson(${personId}); return false;">
                <i class="fas fa-money-check-alt"></i> پرداختی جدید
            </a>
            <a href="#" onclick="showPersonTransactions(${personId}); return false;">
                <i class="fas fa-history"></i> لیست معاملات
            </a>
            <a href="#" onclick="sendAccountSummary(${personId}); return false;">
                <i class="fas fa-sms"></i> ارسال پیام (نهایت حساب)
            </a>
            <a href="#" onclick="generatePersonReport(${personId}); return false;">
                <i class="fas fa-file-alt"></i> گزارش معاملات شخص
            </a>
            <a href="#" onclick="openCurrencyConversion('inside_person', {personId: ${personId}}); return false;">
                <i class="fas fa-right-left"></i> تبدیل ارز داخل حساب مشتری
            </a>
            <a href="#" onclick="editPerson(${personId}); return false;">
                <i class="fas fa-edit"></i> ویرایش
            </a>
            <a href="#" onclick="deletePerson(${personId}); return false;">
                <i class="fas fa-trash"></i> حذف شخص
            </a>
        `;
        
        document.body.appendChild(menu);
    }
    
    // موقعیت منو
    const btn = event.target.closest('button');
    const rect = btn.getBoundingClientRect();
    menu.style.top = (rect.bottom + window.scrollY) + 'px';
    menu.style.right = (window.innerWidth - rect.right) + 'px';
    
    // نمایش/پنهان
    document.querySelectorAll('.person-actions-menu').forEach(m => {
        if (m.id !== menuId) m.style.display = 'none';
    });
    
    menu.style.display = menu.style.display === 'block' ? 'none' : 'block';
}

