// ===== نمایش معلومات کامل یک فرد در یک جدول منظم =====
function showPersonInfo(personId) {
    const person = db.getPersons().find(p => p.id == personId);
    if (!person) { showMessage('خطا', 'فرد یافت نشد'); return; }

    showSection('person-info-list');

    const nameEl = document.getElementById('person-info-name');
    if (nameEl) nameEl.textContent = person.name || '';

    const tbody = document.querySelector('#person-info-table tbody');
    if (!tbody) return;
    tbody.innerHTML = '';

    // محاسبه طلبکار/بدهکار جاری از روی معاملات
    var allTx = db.getTransactions() || [];
    var personTxs = allTx.filter(function(t) { return t.personId == person.id || t.customerId == person.id || t.supplierId == person.id; });
    var balanceAFN = 0, balanceUSD = 0;
    var balMap = {}; function _shBal(c, v){ balMap[c] = (balMap[c] || 0) + v; }
    if (person.previousAccount) {
        var prev = parseFloat(person.previousAccount) || 0;
        var prevCur = person.currency || _baseCur();
        if (person.accountType === 'بدهکار') { _shBal(prevCur, prev); }
        else if (person.accountType === 'طلبکار') { _shBal(prevCur, -prev); }
    }
    personTxs.forEach(function(tx) {
        var totalAmount = parseFloat(tx.totalAmount || tx.amount || 0);
        var remaining = (typeof calculateTxRemaining === 'function') ? calculateTxRemaining(tx) : (parseFloat(tx.remaining) || 0);
        var cur = tx.currency || _baseCur();
        var effect = 0;
        switch(tx.type) {
            case 'فروش':  effect = remaining; break;
            case 'خرید':  effect = -remaining; break;
            case 'دریافت': effect = -totalAmount; break;
            case 'پرداخت': effect = totalAmount; break;
            case 'برگشت':
                if (tx.returnType === 'فروش') effect = -(tx.remaining != null ? parseFloat(tx.remaining) : totalAmount);
                else if (tx.returnType === 'خرید') effect = (tx.remaining != null ? parseFloat(tx.remaining) : totalAmount);
                break;
        }
        _shBal(cur, effect);
    });
    // مشتق‌سازیِ ماندهٔ نمایشیِ افغانی/دالر از نقشه (منبعِ حقیقت) — بدونِ انباشتِ ثابت‌ارز.
    balanceAFN = balMap['AFN'] || 0; balanceUSD = balMap['USD'] || 0;

    function balanceCellHTML(amount, symbol) {
        if (Math.abs(amount) < 0.005) return '<span class="badge badge-secondary">تسویه</span>';
        if (amount > 0) {
            return '<span style="color:#dc2626;font-weight:700;">' + formatNumber(amount) + ' ' + symbol + ' (بدهکار)</span>';
        } else {
            return '<span style="color:#16a34a;font-weight:700;">' + formatNumber(Math.abs(amount)) + ' ' + symbol + ' (طلبکار)</span>';
        }
    }

    // داده‌های ردیف
    var rows = [
        { label: 'نام', value: person.name || '---' },
        { label: 'دسته بندی', value: '<span class="badge badge-info">' + (person.category || '---') + '</span>' },
        { label: 'شماره تماس', value: person.phone || '---' },
        { label: 'شماره تذکره/شناسایی', value: person.idNumber || '---' },
        { label: 'آدرس', value: person.address || '---' },
        { label: 'ارز اصلی', value: (typeof getCurrencyLabel === 'function' ? getCurrencyLabel(person.currency || _baseCur()) : (person.currency || _baseCur())) },
        { label: 'وضعیت حساب اولیه', value: person.accountType || 'بدون حساب' },
        { label: 'حساب قبلی', value: person.previousAccount ? formatNumber(person.previousAccount) + ' ' + _curSymGlobal(person.currency || _baseCur()) : '---' },
        { label: 'مانده فعلی (افغانی)', value: balanceCellHTML(balanceAFN, '؋') },
        { label: 'مانده فعلی (دالر)', value: balanceCellHTML(balanceUSD, '$') },
        ...(function(){ var r=[]; Object.keys(balMap).forEach(function(c){ if(c==='AFN'||c==='USD')return; var v=balMap[c]||0; if(!v)return; r.push({ label: 'مانده فعلی ('+_curLabelGlobal(c)+')', value: balanceCellHTML(v, _curSymGlobal(c)) }); }); return r; })(),
        { label: 'تعداد معاملات', value: personTxs.length },
        { label: 'تاریخ ثبت', value: person.createdAt || '---' },
        { label: 'یادداشت‌ها', value: person.notes || person.description || '---' }
    ];

    rows.forEach(function(r) {
        var tr = document.createElement('tr');
        tr.innerHTML = '<td style="font-weight:600;color:var(--text-main);width:30%;">' + r.label + '</td>' +
                       '<td>' + r.value + '</td>';
        tbody.appendChild(tr);
    });
}

// نگاشتِ وضعیتِ مالیِ کارت به کلاسِ رنگِ آیکنِ تیک (فقط رنگ؛ بدونِ اثر بر محاسبات)
// ورودی یکی از: 'is-remaining' (باقی‌مانده→قرمز)، 'is-overpaid' (اضافه→آبی)،
//   'is-settled' (تسویه→سبز)، 'is-creditor' (طلبکار→سبز)، 'is-none' (بدون وضعیت→سیاه)
function _statusBadgeColorClass(statusCls) {
    switch (statusCls) {
        case 'is-remaining': return 'badge-red';
        case 'is-overpaid':  return 'badge-blue';
        case 'is-settled':   return 'badge-green';
        case 'is-creditor':  return 'badge-green';
        case 'is-none':      return 'badge-black';
        default:             return 'badge-black';
    }
}

// ساختِ HTMLِ کارتِ معاملهٔ شخص با همان استایلِ «لیستِ سریعِ فروش‌ها» (sales-card)
// فقط ظاهر است؛ داده‌ها و محاسبات از بیرون داده می‌شوند و تغییری نمی‌کنند.
function _ptxSalesCardHtml(o) {
    // o: { icon, typeText, billNo, timeText, amountText, balanceHtml, balanceCls, moreHtml, kebabHtml, badgeCls }
    var _metaMore = (o.moreHtml && o.moreHtml !== '-' && o.moreHtml !== '—')
        ? '<span class="sales-card-meta-item"><b class="sales-meta-label">اطلاعات:</b><span class="sales-meta-val">' + o.moreHtml + '</span></span>'
        : '';
    return '<td class="sales-card-cell">' +
                '<div class="sales-card ptx-sales-card">' +
                    '<div class="sales-card-main">' +
                        '<span class="sales-card-icon">' + (o.icon || '<i class="fas fa-exchange-alt"></i>') + '</span>' +
                        '<span class="sales-card-name">' + (o.typeText || '-') + '</span>' +
                    '</div>' +
                    '<div class="sales-card-meta">' +
                        '<span class="sales-card-meta-item"><b class="sales-meta-label">بل نمبر:</b><span class="sales-meta-val">' + (o.billNo || '-') + '</span></span>' +
                        '<span class="sales-card-meta-item"><b class="sales-meta-label">زمان:</b><span class="sales-meta-val">' + (o.timeText || '-') + '</span></span>' +
                        _metaMore +
                    '</div>' +
                    '<div class="sales-card-amount">مبلغ: <span>' + (o.amountText || '-') + '</span></div>' +
                    '<div class="sales-card-remaining ' + (o.balanceCls || 'is-settled') + '">مانده: <span>' + (o.balanceHtml || '-') + '</span></div>' +
                    '<div class="sales-card-actions">' +
                        '<span class="sales-card-status-badge ' + (o.badgeCls || 'badge-black') + '"><i class="fas fa-check"></i></span>' +
                        (o.kebabHtml || '') +
                    '</div>' +
                '</div>' +
            '</td>' +
            '<td class="sales-card-hidden-cell" aria-hidden="true"></td>';
}

// آیکنِ متناسب با نوعِ معاملهٔ شخص (هماهنگ با رنگ‌بندیِ لیست‌ها)
function _ptxTypeIcon(type) {
    switch(type) {
        case 'فروش':  return '<i class="fas fa-cart-plus"></i>';
        case 'خرید':  return '<i class="fas fa-shopping-basket"></i>';
        case 'دریافت': return '<i class="fas fa-hand-holding-usd"></i>';
        case 'پرداخت': return '<i class="fas fa-money-check-alt"></i>';
        case 'برگشت':  return '<i class="fas fa-rotate-left"></i>';
        default:       return '<i class="fas fa-wallet"></i>';
    }
}

// بارگذاری معاملات شخص
function loadPersonTransactions(personId) {
    const transactions = db.getTransactions();
    const person = db.getPersons().find(p => p.id == personId);
    const personTransactions = transactions.filter(t =>
        t.personId == personId ||
        (t.customerId == personId) ||
        (t.supplierId == personId)
    );

    // مرتب‌سازی از قدیمی‌ترین به جدیدترین برای محاسبه مانده تجمعی
    personTransactions.sort(function(a, b) {
        var da = a.createdAt || a.date || '';
        var db_ = b.createdAt || b.date || '';
        return da.localeCompare(db_);
    });

    const tbody = document.getElementById('person-transactions-table').querySelector('tbody');
    if (!tbody) return;
    tbody.innerHTML = '';

    // مانده حساب تفکیک بر اساس ارز
    // مثبت = شخص بدهکار ما (ما طلبکار)
    // منفی = ما بدهکار شخص (شخص طلبکار)
    var balMap = {}; function _ptBal(c, v){ balMap[c] = (balMap[c] || 0) + v; }

    // ===== ساختِ فهرستِ یکپارچهٔ ورودی‌ها (شاملِ «حساب قبلی» به‌عنوان یک ردیفِ عادی) =====
    // نکتهٔ مهم: هیچ تغییری در منطقِ محاسبات ایجاد نمی‌شود؛ «حساب قبلی» صرفاً از لحاظِ چیدمان
    // دیگر به‌صورتِ ثابت در بالا قرار نمی‌گیرد، بلکه مانندِ سایر ردیف‌ها بر اساسِ زمانِ ثبتِ شخص
    // در ترتیب قرار می‌گیرد. مقدارِ اثرِ آن بر مانده دقیقاً همان منطقِ قبلی است.
    var _entries = [];

    // ورودیِ «حساب قبلی» (اگر موجود باشد) — با زمانِ ثبتِ شخص تا در ترتیبِ زمانی درست بنشیند
    if (person && person.previousAccount) {
        var _prevAmount = parseFloat(person.previousAccount) || 0;
        if (_prevAmount !== 0) {
            _entries.push({
                kind: 'prev',
                sortKey: (person.createdAt || person.date || ''),
                prevAmount: _prevAmount,
                prevCurrency: person.currency || _baseCur(),
                prevAccountType: person.accountType || ''
            });
        }
    }

    // ورودی‌های معاملات
    personTransactions.forEach(function(tx) {
        _entries.push({
            kind: 'tx',
            sortKey: (tx.createdAt || tx.date || ''),
            tx: tx
        });
    });

    // مرتب‌سازیِ کلِ ورودی‌ها از قدیمی‌ترین به جدیدترین (برای محاسبهٔ مانده تجمعی)
    _entries.sort(function(a, b) {
        return String(a.sortKey).localeCompare(String(b.sortKey));
    });

    // ===== ساختِ ردیف‌های نمایشی (کارت‌ها) با محاسبهٔ مانده تجمعی — منطق دست‌نخورده =====
    var _renderedRows = []; // {type, html} به‌ترتیبِ قدیمی→جدید

    _entries.forEach(function(entry) {
        if (entry.kind === 'prev') {
            var prevAmount = entry.prevAmount;
            var prevCurrency = entry.prevCurrency;
            var prevSymbol = _curSymGlobal(prevCurrency);
            if (entry.prevAccountType === 'بدهکار') {
                _ptBal(prevCurrency, prevAmount);
            } else if (entry.prevAccountType === 'طلبکار') {
                _ptBal(prevCurrency, -prevAmount);
            }
            var currentBal = (balMap[prevCurrency] || 0);
            var balColor = currentBal > 0 ? '#ef4444' : (currentBal < 0 ? '#10b981' : '#64748b');
            var balCls = currentBal > 0 ? 'is-remaining' : (currentBal < 0 ? 'is-settled' : 'is-settled');
            var balLabel = currentBal > 0 ? 'بدهکار' : (currentBal < 0 ? 'طلبکار' : 'تسویه');
            var balDisp = formatNumber(Math.abs(currentBal)) + ' ' + prevSymbol + ' (' + balLabel + ')';
            // رنگِ آیکنِ تیک: بدهکار→قرمز، طلبکار→سبز، تسویه→سبز
            var _prevBadgeCls = _statusBadgeColorClass(currentBal > 0 ? 'is-remaining' : (currentBal < 0 ? 'is-creditor' : 'is-settled'));

            var _prevHtml = _ptxSalesCardHtml({
                icon: '<i class="fas fa-wallet"></i>',
                typeText: 'حساب قبلی',
                billNo: '—',
                timeText: (person.createdAt || '---'),
                amountText: '(' + (prevCurrency || _baseCur()) + ')' + formatNumber(prevAmount),
                balanceHtml: balDisp,
                balanceCls: balCls,
                moreHtml: '—',
                kebabHtml: '',
                badgeCls: _prevBadgeCls
            });
            _renderedRows.push({ typeClass: 'ptx-prev', html: _prevHtml });
            return;
        }

        // ---- ورودیِ معامله ----
        var tx = entry.tx;

        // ---- تبدیل ارز (صرافی): دو ردیفِ جدا «تبدیل ارز رفت» (خروج) و «تبدیل ارز آمد» (ورود) ----
        if (tx.type === 'صرافی') {
            var _sBaseCur = tx.currency || _baseCur();
            var _sfc = tx.fromCurrency || _sBaseCur, _stc = tx.toCurrency || _sBaseCur;
            var _sfa = parseFloat(tx.fromAmount || 0) || 0, _sta = parseFloat(tx.toAmount || 0) || 0;
            var _scs = (tx.convSign != null ? tx.convSign : 1);   // علامتِ حساب (طلبکار/بدهکار)
            var _buildLegRow = function (legCur, legAmt, legTitle) {
                _ptBal(legCur, legTitle === 'تبدیل ارز رفت' ? (-_scs * legAmt) : (+_scs * legAmt));
                var _cb = (balMap[legCur] || 0);
                var _bcls = _cb > 0 ? 'is-remaining' : 'is-settled';
                var _blab = _cb > 0 ? 'بدهکار' : (_cb < 0 ? 'طلبکار' : 'تسویه');
                var _bdisp = formatNumber(Math.abs(_cb)) + ' ' + _curSymGlobal(legCur) + ' (' + _blab + ')';
                var _bbadge = _statusBadgeColorClass(_cb > 0 ? 'is-remaining' : (_cb < 0 ? 'is-creditor' : 'is-settled'));
                var _kebab2 = '<button class="sales-card-kebab action-trigger-btn" type="button"' +
                    ' onmouseenter="showPersonTxActionBar(event, ' + tx.id + ', ' + personId + ')"' +
                    ' onmouseleave="handleActionButtonMouseLeave(event)" title="عملیات"><i class="fas fa-ellipsis-v"></i></button>';
                return {
                    typeClass: 'ptx-neutral', txId: tx.id,
                    html: _ptxSalesCardHtml({
                        icon: '<i class="fas fa-right-left"></i>', typeText: legTitle,
                        billNo: (tx.billNumber || 'ندارد'),
                        timeText: (formatAfghanDateTime(tx.date, tx.createdAt) || '---'),
                        amountText: '(' + legCur + ')' + formatNumber(legAmt),
                        balanceHtml: _bdisp, balanceCls: _bcls, moreHtml: '-',
                        kebabHtml: _kebab2, badgeCls: _bbadge
                    })
                };
            };
            // «رفت» اول اعمال و ثبت می‌شود، سپس «آمد»؛ ترتیبِ درج طبیعی است تا پس از reverse سراسری «آمد» بالای «رفت» بماند
            if (_sfa) _renderedRows.push(_buildLegRow(_sfc, _sfa, 'تبدیل ارز رفت'));
            if (_sta) _renderedRows.push(_buildLegRow(_stc, _sta, 'تبدیل ارز آمد'));
            return;
        }

        var totalAmount = parseFloat(tx.totalAmount || tx.amount || 0);
        var remaining = calculateTxRemaining(tx);
        var currency = tx.currency || _baseCur();
        // برای «صرافی» مبلغِ نمایشی = مبلغِ نتیجه (toAmount) تا ستونِ مبلغ صفر نشان ندهد
        if (tx.type === 'صرافی') { totalAmount = parseFloat(tx.toAmount || tx.fromAmount || 0) || 0; }
        var effect = 0;
        switch(tx.type) {
            case 'فروش':
                effect = remaining;
                break;
            case 'خرید':
                effect = -remaining;
                break;
            case 'دریافت':
                effect = -totalAmount;
                break;
            case 'پرداخت':
                effect = totalAmount;
                break;
            case 'پرداخت از حساب قبلی':
                if (person && person.accountType === 'طلبکار') {
                    effect = totalAmount;
                } else {
                    effect = -totalAmount;
                }
                break;
            case 'برگشت':
                if (tx.returnType === 'فروش') {
                    effect = -(tx.remaining != null ? parseFloat(tx.remaining) : totalAmount);
                } else if (tx.returnType === 'خرید') {
                    effect = (tx.remaining != null ? parseFloat(tx.remaining) : totalAmount);
                }
                break;
            default:
                effect = 0;
        }

        _ptBal(currency, effect);

        // تبدیل ارز (صرافی) روی حساب شخص: هر دو لِنگ روی ماندهٔ همان شخص اعمال شود
        if (tx.type === 'صرافی') {
            var _lfc = tx.fromCurrency || currency, _ltc = tx.toCurrency || currency;
            var _lfa = parseFloat(tx.fromAmount || 0) || 0, _lta = parseFloat(tx.toAmount || 0) || 0;
            // effect در سوییچ برای «صرافی» صفر است؛ پس _ptBal بالا چیزی نیفزوده — حالا دو لِنگ را می‌افزاییم
            if (_lfa) _ptBal(_lfc, -_lfa);
            if (_lta) _ptBal(_ltc, +_lta);
            currency = _lta ? _ltc : _lfc;   // ماندهٔ نمایشیِ این ردیف = ارزِ نتیجه
        }

        var currentBalance = (balMap[currency] || 0);
        var balanceCls = currentBalance > 0 ? 'is-remaining' : (currentBalance < 0 ? 'is-settled' : 'is-settled');
        var balanceLabel = '';
        if (currentBalance > 0) balanceLabel = 'بدهکار';
        else if (currentBalance < 0) balanceLabel = 'طلبکار';
        else balanceLabel = 'تسویه';

        var balanceDisplay = formatNumber(Math.abs(currentBalance)) + ' ' + _curSymGlobal(currency) + ' (' + balanceLabel + ')';
        // رنگِ آیکنِ تیک: بدهکار→قرمز، طلبکار→سبز، تسویه→سبز
        var _txBadgeCls = _statusBadgeColorClass(currentBalance > 0 ? 'is-remaining' : (currentBalance < 0 ? 'is-creditor' : 'is-settled'));

        // ===== محاسبه اطلاعات بیشتر (دقیقاً مطابقِ منطقِ قبلی) =====
        var _moreInfoCell = '-';
        if (tx.type === 'فروش') {
            var _recvAmt = (tx.cashAmounts && tx.cashAmounts[currency] != null) ? parseFloat(tx.cashAmounts[currency]) : (currency === 'USD' ? parseFloat(tx.cashUsd || 0) : (currency === 'AFN' ? parseFloat(tx.cashAfn || 0) : parseFloat(tx.cashForeign || 0)));
            _moreInfoCell = 'دریافت ' + formatNumber(_recvAmt);
        } else if (tx.type === 'خرید') {
            var _payAmt = (tx.paidAmounts && tx.paidAmounts[currency] != null) ? parseFloat(tx.paidAmounts[currency]) : (currency === 'USD' ? parseFloat(tx.paidUsd || tx.cashUsd || 0) : (currency === 'AFN' ? parseFloat(tx.paidAfn || tx.cashAfn || 0) : parseFloat(tx.paidForeign || 0)));
            _moreInfoCell = 'پرداخت ' + formatNumber(_payAmt);
        }

        // نوعِ نمایشی برای برگشت‌ها (برگشت از فروش / برگشت از خرید)
        var _typeText = tx.type;
        if (tx.type === 'برگشت') {
            _typeText = (tx.returnType === 'فروش') ? 'برگشت از فروش' : (tx.returnType === 'خرید' ? 'برگشت از خرید' : 'برگشت');
        }

        // رنگِ نوارِ کناری بر اساسِ نوعِ معامله (مطابقِ تصویر)
        var _borderClass = _ptxBorderClass(tx.type, tx.returnType);

        // ===== دکمهٔ سه‌نقطه: ویرایش + حذف (مطابقِ لیستِ سریعِ فروش‌ها) =====
        var _kebab =
            '<button class="sales-card-kebab action-trigger-btn" type="button"' +
            ' onmouseenter="showPersonTxActionBar(event, ' + tx.id + ', ' + personId + ')"' +
            ' onmouseleave="handleActionButtonMouseLeave(event)" title="عملیات">' +
            '<i class="fas fa-ellipsis-v"></i></button>';

        var _txHtml = _ptxSalesCardHtml({
            icon: _ptxTypeIcon(tx.type),
            typeText: _typeText,
            billNo: (tx.billNumber || 'ندارد'),
            timeText: (formatAfghanDateTime(tx.date, tx.createdAt) || '---'),
            amountText: '(' + (currency || _baseCur()) + ')' + formatNumber(totalAmount),
            balanceHtml: balanceDisplay,
            balanceCls: balanceCls,
            moreHtml: _moreInfoCell,
            kebabHtml: _kebab,
            badgeCls: _txBadgeCls
        });

        _renderedRows.push({ typeClass: _borderClass, html: _txHtml, txId: tx.id });
    });

    // ===== درج در DOM به‌ترتیبِ جدیدترین در بالا =====
    _renderedRows.reverse();
    _renderedRows.forEach(function(r) {
        var row = document.createElement('tr');
        row.className = 'sales-card-row ptx-row ' + r.typeClass;
        row.innerHTML = r.html;
        row.style.cursor = 'pointer';
        if (r.txId != null) row.dataset.txId = r.txId;
        (function(txId){ row.onclick = function(){ if (typeof viewTransaction === 'function') viewTransaction(txId); }; })(r.txId);
        tbody.appendChild(row);
    });

    // حالتِ «انتخاب برای برگشت» — اگر از فورمِ برگشت (فروش/خرید) وارد شده باشیم
    if (typeof _srDecoratePersonTxPick === 'function' && typeof _srTxPick !== 'undefined' && _srTxPick) {
        try { _srDecoratePersonTxPick(personId); } catch (e) { console.error('sr tx pick decorate:', e); }
    }
}

// رنگِ نوارِ کناریِ کارت بر اساسِ نوعِ معامله (هماهنگ با تصویر)
function _ptxBorderClass(type, returnType) {
    switch(type) {
        case 'فروش':  return 'ptx-sale';
        case 'خرید':  return 'ptx-purchase';
        case 'دریافت': return 'ptx-receipt';
        case 'پرداخت': return 'ptx-payment';
        case 'برگشت':  return 'ptx-return';
        default:       return 'ptx-neutral';
    }
}

// ===== دکمهٔ سه‌نقطهٔ عملیات برای لیستِ معاملاتِ فرد — فقط «ویرایش» و «حذف» =====
// از همان منطقِ ویرایشِ لیستِ سریعِ فروش‌ها (editTransaction) استفاده می‌کند و پس از حذف،
// لیستِ همان فرد را رفرش می‌کند (deletePersonTransaction).
function showPersonTxActionBar(event, id, personId) {
    if (typeof closeToolbarTimer !== 'undefined' && closeToolbarTimer) {
        clearTimeout(closeToolbarTimer);
        closeToolbarTimer = null;
    }
    if (typeof currentToolbar !== 'undefined' && currentToolbar) {
        currentToolbar.remove();
        currentToolbar = null;
    }

    var transactions = db.getTransactions ? db.getTransactions() : [];
    var tx = transactions.find(function(t){ return t.id == id; });
    if (!tx) return;

    var toolbar = document.createElement('div');
    toolbar.className = 'floating-action-toolbar';
    toolbar.setAttribute('data-tx-id', id);
    Object.assign(toolbar.style, {
        position: 'absolute', display: 'flex', flexDirection: 'column', alignItems: 'stretch',
        gap: '4px', backgroundColor: '#ffffff', padding: '8px', borderRadius: '12px',
        boxShadow: '0 5px 20px rgba(0,0,0,0.2)', border: '1px solid #cbd5e1',
        zIndex: '9999', whiteSpace: 'nowrap', minWidth: '170px'
    });

    var actions = [
        { icon: 'fa-edit',  color: '#d97706', title: 'ویرایش', action: 'edit' },
        { icon: 'fa-trash', color: '#dc2626', title: 'حذف',    action: 'delete' }
    ];

    actions.forEach(function(item) {
        var btn = document.createElement('button');
        btn.title = item.title;
        btn.innerHTML = '<i class="fas ' + item.icon + '" style="width:18px;text-align:center;color:' + item.color + ';"></i><span style="margin-right:10px;font-size:13px;color:#1e293b;font-weight:500;">' + item.title + '</span>';
        Object.assign(btn.style, {
            background: 'transparent', border: 'none', cursor: 'pointer', padding: '8px 10px',
            transition: 'background 0.2s', display: 'flex', alignItems: 'center',
            justifyContent: 'flex-start', borderRadius: '6px', textAlign: 'right', fontFamily: 'inherit'
        });
        btn.onmouseenter = function(){ btn.style.background = '#f1f5f9'; };
        btn.onmouseleave = function(){ btn.style.background = 'transparent'; };
        btn.onclick = function(e) {
            e.stopPropagation();
            if (typeof closeAllActionMenus === 'function') closeAllActionMenus();
            if (item.action === 'edit') {
                // پس از ویرایش باید به همان لیستِ معاملاتِ همین فرد برگردد (نه لیستِ فروش/خرید)
                _setFormReturn({ section: 'person-transactions-list', personId: personId });
                if (typeof editTransaction === 'function') editTransaction(id);
            } else if (item.action === 'delete') {
                if (typeof deletePersonTransaction === 'function') deletePersonTransaction(id, personId);
                else if (typeof deleteTransaction === 'function') deleteTransaction(id);
            }
        };
        toolbar.appendChild(btn);
    });

    toolbar.addEventListener('mouseenter', function() {
        if (typeof closeToolbarTimer !== 'undefined' && closeToolbarTimer) {
            clearTimeout(closeToolbarTimer);
            closeToolbarTimer = null;
        }
    });
    toolbar.addEventListener('mouseleave', function() {
        if (typeof startCloseToolbarTimer === 'function') startCloseToolbarTimer();
    });

    document.body.appendChild(toolbar);
    currentToolbar = toolbar;

    var rect = event.currentTarget.getBoundingClientRect();
    var scrollTop = window.pageYOffset || document.documentElement.scrollTop;
    var scrollLeft = window.pageXOffset || document.documentElement.scrollLeft;
    toolbar.style.top = (rect.top + scrollTop) + 'px';
    toolbar.style.left = (rect.right + scrollLeft + 10) + 'px';

    toolbar.animate([
        { opacity: 0, transform: 'scale(0.8)' },
        { opacity: 1, transform: 'scale(1)' }
    ], { duration: 200, easing: 'cubic-bezier(0.175, 0.885, 0.32, 1.275)' });
}

// ============================================================================
//  کارتِ «ورودی و خروجی جنس» — دقیقاً با همان کلاس‌ها/طرحِ لیستِ معاملاتِ شخص
//  (فقط داده و برچسب‌ها مطابقِ محتوای این لیست است؛ هیچ منطقِ محاسباتی اینجا نیست)
// ============================================================================
function _inoutSalesCardHtml(o) {
    var _metaParty = (o.partyText && o.partyText !== '-' && o.partyText !== '—')
        ? '<span class="sales-card-meta-item"><b class="sales-meta-label">طرف معامله:</b><span class="sales-meta-val">' + o.partyText + '</span></span>'
        : '';
    return '<td class="sales-card-cell">' +
                '<div class="sales-card ptx-sales-card">' +
                    '<div class="sales-card-main">' +
                        '<span class="sales-card-icon">' + (o.icon || '<i class="fas fa-exchange-alt"></i>') + '</span>' +
                        '<span class="sales-card-name">' + (o.moveText || '-') + '</span>' +
                    '</div>' +
                    '<div class="sales-card-meta">' +
                        '<span class="sales-card-meta-item"><b class="sales-meta-label">تاریخ:</b><span class="sales-meta-val">' + (o.dateText || '-') + '</span></span>' +
                        '<span class="sales-card-meta-item"><b class="sales-meta-label">نمبر بل:</b><span class="sales-meta-val">' + (o.billNo || '-') + '</span></span>' +
                        '<span class="sales-card-meta-item"><b class="sales-meta-label">تعداد:</b><span class="sales-meta-val">' + (o.qtyText || '-') + '</span></span>' +
                        _metaParty +
                    '</div>' +
                    '<div class="sales-card-amount">قیمت واحد: <span>' + (o.priceText || '-') + '</span></div>' +
                    '<div class="sales-card-remaining ' + (o.stockCls || 'is-settled') + '">موجودی: <span>' + (o.stockHtml || '-') + '</span></div>' +
                    '<div class="sales-card-actions">' +
                        '<span class="sales-card-status-badge ' + (o.badgeCls || 'badge-black') + '"><i class="fas fa-check"></i></span>' +
                        (o.kebabHtml || '') +
                    '</div>' +
                '</div>' +
            '</td>' +
            '<td class="sales-card-hidden-cell" aria-hidden="true"></td>';
}

// نوارِ عملیاتِ کارتِ ورودی/خروجی — ویرایش + حذف (کلونِ نوارِ معاملاتِ شخص)
// حذف/ویرایش از همین‌جا مستقیماً روی خودِ بلِ فروش/خرید اعمال می‌شود؛ پس تغییرات
// به‌صورتِ آنی در سراسرِ دیتابیس هماهنگ می‌ماند (همان مسیرِ editTransaction/deleteTransaction).
// جای‌گذاریِ نوارِ عملیاتِ شناور داخلِ مرزِ Viewport (اصلاحِ ریشه‌ایِ #7):
// نوار روی document.body است (پس overflowِ کارت/کانتینر آن را نمی‌بُرد)، اما بدونِ کنترلِ
// مرز از راست/پایینِ صفحه بیرون می‌زد. اینجا با اندازهٔ واقعیِ نوار (پس از append) موقعیت را
// طوری تنظیم می‌کنیم که همیشه کامل دیده شود: افقی طبیعیِ RTL = سمتِ چپِ دکمه، در نبودِ فضا
// سمتِ راست، و در نهایت clamp؛ عمودی اگر پایین جا نبود رو به بالا flip و سپس clamp.
function _placeInoutToolbar(toolbar, event) {
    try {
        var target = event && (event.currentTarget || event.target);
        if (!target || !target.getBoundingClientRect) return;
        var rect = target.getBoundingClientRect();
        var scrollTop = window.pageYOffset || document.documentElement.scrollTop || 0;
        var scrollLeft = window.pageXOffset || document.documentElement.scrollLeft || 0;
        var vw = window.innerWidth || document.documentElement.clientWidth || 0;
        var vh = window.innerHeight || document.documentElement.clientHeight || 0;
        var tw = toolbar.offsetWidth || 180;
        var th = toolbar.offsetHeight || 90;
        var margin = 8;

        // افقی — مثلِ منوی «اشخاص» که پایدار کار می‌کند: اولویت با سمتِ راستِ دکمه (rect.right+10)
        // تا پلِ hover بینِ دکمه و منو همان رفتارِ اشخاص را داشته باشد؛ فقط کنارِ لبه به چپ/clamp.
        var left;
        if (rect.right + 10 + tw <= vw - margin) {
            left = rect.right + 10;                  // سمتِ راستِ دکمه (رفتارِ منوی اشخاص)
        } else if (rect.left - 10 - tw >= margin) {
            left = rect.left - 10 - tw;              // اگر راست جا نبود، سمتِ چپ
        } else {
            left = Math.max(margin, Math.min(rect.left, vw - tw - margin));
        }

        // عمودی
        var top = rect.top;
        if (top + th > vh - margin) {
            top = rect.bottom - th;                  // flip رو به بالا
            if (top < margin) top = vh - th - margin;
        }
        if (top < margin) top = margin;

        toolbar.style.left = (left + scrollLeft) + 'px';
        toolbar.style.top = (top + scrollTop) + 'px';
    } catch (e) {}
}
if (typeof window !== 'undefined') window._placeInoutToolbar = _placeInoutToolbar;

// شبکهٔ ایمنیِ سراسری برای منوهای عملیاتِ شناور (یک‌بار نصب می‌شود). ریشه‌ایِ «گیرکردنِ کارت
// تا restart»: اگر رویدادِ mouseleaveِ دکمه/کارت به هر دلیلی fire نشود (کارت روی دکمه/ردیف بیفتد
// یا رویداد از دست برود)، تایمرِ بستن هرگز شروع نمی‌شد. این handlerِ سراسری تضمین می‌کند هر وقت
// کرسر «نه روی کارت و نه روی دکمهٔ سه‌نقطه» باشد، همان تایمرِ مشترکِ ۳۰۰msِ بستن شروع شود؛ و اگر
// روی کارت/دکمه باشد تایمر لغو شود. با زیرساختِ مشترکِ همان منوی اشخاص کار می‌کند و منطقِ سالمِ
// اشخاص را بازنویسی نمی‌کند (فقط تضمینِ بسته‌شدن را قوی‌تر می‌کند).
function _ensureActionMenuSafetyNet() {
    if (typeof window === 'undefined' || window.__actionMenuSafetyNet) return;
    window.__actionMenuSafetyNet = true;
    document.addEventListener('mouseover', function (e) {
        if (typeof currentToolbar === 'undefined' || !currentToolbar) return;
        var t = e.target;
        var onMenu = t && t.closest && (t.closest('.floating-action-toolbar') || t.closest('.action-trigger-btn'));
        if (onMenu) {
            if (typeof closeToolbarTimer !== 'undefined' && closeToolbarTimer) { clearTimeout(closeToolbarTimer); closeToolbarTimer = null; }
            return;
        }
        if (typeof startCloseToolbarTimer === 'function') startCloseToolbarTimer();
    }, true);
    // اگر پنجره focus را از دست داد (مثلاً جابجایی به برنامهٔ دیگر)، کارت باقی نماند.
    window.addEventListener('blur', function () { if (typeof closeAllActionMenus === 'function') closeAllActionMenus(); });
}
if (typeof window !== 'undefined') window._ensureActionMenuSafetyNet = _ensureActionMenuSafetyNet;

function showProductInoutActionBar(event, id, type, productId) {
    _ensureActionMenuSafetyNet();
    if (typeof closeToolbarTimer !== 'undefined' && closeToolbarTimer) { clearTimeout(closeToolbarTimer); closeToolbarTimer = null; }
    if (typeof currentToolbar !== 'undefined' && currentToolbar) { currentToolbar.remove(); currentToolbar = null; }

    var transactions = db.getTransactions ? db.getTransactions() : [];
    var tx = transactions.find(function(t){ return t.id == id; });
    if (!tx) return;

    var toolbar = document.createElement('div');
    toolbar.className = 'floating-action-toolbar';
    toolbar.setAttribute('data-tx-id', id);
    Object.assign(toolbar.style, {
        position: 'absolute', display: 'flex', flexDirection: 'column', alignItems: 'stretch',
        gap: '4px', backgroundColor: '#ffffff', padding: '8px', borderRadius: '12px',
        boxShadow: '0 5px 20px rgba(0,0,0,0.2)', border: '1px solid #cbd5e1',
        zIndex: '9999', whiteSpace: 'nowrap', minWidth: '170px'
    });

    var actions = [
        { icon: 'fa-edit',  color: '#d97706', title: 'ویرایش', action: 'edit' },
        { icon: 'fa-trash', color: '#dc2626', title: 'حذف',    action: 'delete' }
    ];

    actions.forEach(function(item) {
        var btn = document.createElement('button');
        btn.title = item.title;
        btn.innerHTML = '<i class="fas ' + item.icon + '" style="width:18px;text-align:center;color:' + item.color + ';"></i><span style="margin-right:10px;font-size:13px;color:#1e293b;font-weight:500;">' + item.title + '</span>';
        Object.assign(btn.style, {
            background: 'transparent', border: 'none', cursor: 'pointer', padding: '8px 10px',
            transition: 'background 0.2s', display: 'flex', alignItems: 'center',
            justifyContent: 'flex-start', borderRadius: '6px', textAlign: 'right', fontFamily: 'inherit'
        });
        btn.onmouseenter = function(){ btn.style.background = '#f1f5f9'; };
        btn.onmouseleave = function(){ btn.style.background = 'transparent'; };
        btn.onclick = function(e) {
            e.stopPropagation();
            if (typeof closeAllActionMenus === 'function') closeAllActionMenus();
            if (item.action === 'edit') {
                // پس از ویرایش باید به همین لیستِ ورودی/خروجیِ همین جنس برگردد
                _setFormReturn({ section: 'product-inout-list', productId: productId });
                if (typeof editTransaction === 'function') editTransaction(id);
            } else if (item.action === 'delete') {
                if (typeof deleteProductInoutTransaction === 'function') deleteProductInoutTransaction(id, productId);
                else if (typeof deleteTransaction === 'function') deleteTransaction(id);
            }
        };
        toolbar.appendChild(btn);
    });

    toolbar.addEventListener('mouseenter', function() {
        if (typeof closeToolbarTimer !== 'undefined' && closeToolbarTimer) { clearTimeout(closeToolbarTimer); closeToolbarTimer = null; }
    });
    toolbar.addEventListener('mouseleave', function() {
        if (typeof startCloseToolbarTimer === 'function') startCloseToolbarTimer();
    });

    document.body.appendChild(toolbar);
    currentToolbar = toolbar;

    _placeInoutToolbar(toolbar, event);

    toolbar.animate([
        { opacity: 0, transform: 'scale(0.8)' },
        { opacity: 1, transform: 'scale(1)' }
    ], { duration: 200, easing: 'cubic-bezier(0.175, 0.885, 0.32, 1.275)' });
}

// حذفِ یک ورودی/خروجی از داخلِ همین لیست — wrapper اطرافِ deleteTransaction که
// پس از حذف، همین لیستِ جنس را رفرش می‌کند (مانندِ deletePersonTransaction).
function deleteProductInoutTransaction(txId, productId) {
    deleteTransaction(txId);
    setTimeout(function() {
        var section = document.getElementById('product-inout-list');
        if (section && section.classList.contains('active') && typeof showProductInOutList === 'function') {
            showProductInOutList(productId);
        }
    }, 350);
}
if (typeof window !== 'undefined') {
    window._inoutSalesCardHtml = _inoutSalesCardHtml;
    window.showProductInoutActionBar = showProductInoutActionBar;
    window.deleteProductInoutTransaction = deleteProductInoutTransaction;
}

// ---------------------------------------------------------------------------
//  نوارِ عملیاتِ شناور برای ردیفِ «انتقال» در لیستِ ورودی/خروجی — مشاهده/ویرایش/حذف
//  (همان استایل و ساختارِ showProductInoutActionBar؛ فقط اکشن‌ها مخصوصِ انتقال است)
// ---------------------------------------------------------------------------
function _buildInoutFloatingBar(event, actions) {
    _ensureActionMenuSafetyNet();
    if (typeof closeToolbarTimer !== 'undefined' && closeToolbarTimer) { clearTimeout(closeToolbarTimer); closeToolbarTimer = null; }
    if (typeof currentToolbar !== 'undefined' && currentToolbar) { currentToolbar.remove(); currentToolbar = null; }
    var toolbar = document.createElement('div');
    toolbar.className = 'floating-action-toolbar';
    Object.assign(toolbar.style, {
        position: 'absolute', display: 'flex', flexDirection: 'column', alignItems: 'stretch',
        gap: '4px', backgroundColor: '#ffffff', padding: '8px', borderRadius: '12px',
        boxShadow: '0 5px 20px rgba(0,0,0,0.2)', border: '1px solid #cbd5e1',
        zIndex: '9999', whiteSpace: 'nowrap', minWidth: '170px'
    });
    actions.forEach(function (item) {
        var btn = document.createElement('button');
        btn.title = item.title;
        btn.innerHTML = '<i class="fas ' + item.icon + '" style="width:18px;text-align:center;color:' + item.color + ';"></i><span style="margin-right:10px;font-size:13px;color:#1e293b;font-weight:500;">' + item.title + '</span>';
        Object.assign(btn.style, {
            background: 'transparent', border: 'none', cursor: 'pointer', padding: '8px 10px',
            transition: 'background 0.2s', display: 'flex', alignItems: 'center',
            justifyContent: 'flex-start', borderRadius: '6px', textAlign: 'right', fontFamily: 'inherit'
        });
        btn.onmouseenter = function () { btn.style.background = '#f1f5f9'; };
        btn.onmouseleave = function () { btn.style.background = 'transparent'; };
        btn.onclick = function (e) { e.stopPropagation(); if (typeof closeAllActionMenus === 'function') closeAllActionMenus(); item.run(); };
        toolbar.appendChild(btn);
    });
    toolbar.addEventListener('mouseenter', function () { if (typeof closeToolbarTimer !== 'undefined' && closeToolbarTimer) { clearTimeout(closeToolbarTimer); closeToolbarTimer = null; } });
    toolbar.addEventListener('mouseleave', function () { if (typeof startCloseToolbarTimer === 'function') startCloseToolbarTimer(); });
    document.body.appendChild(toolbar);
    // ست‌کردنِ بدونِ‌شرطِ currentToolbar (مثلِ showProductInoutActionBar). شرطِ قبلیِ
    // «if (typeof currentToolbar !== 'undefined')» چون var currentToolbar بعد از throwِ سطح‌بالا
    // مقداردهی نمی‌شود، در حالتِ اولیه undefined می‌ماند و شرط FALSE می‌شد → currentToolbar ست
    // نمی‌شد و منوی موجودی‌اولیه/انتقال «گیر» می‌کرد (نه safety-net نه تایمر آن را می‌بست).
    currentToolbar = toolbar;
    _placeInoutToolbar(toolbar, event);
    toolbar.animate([{ opacity: 0, transform: 'scale(0.8)' }, { opacity: 1, transform: 'scale(1)' }], { duration: 200, easing: 'cubic-bezier(0.175, 0.885, 0.32, 1.275)' });
    return toolbar;
}

function showTransferActionBar(event, transferId, productId) {
    _buildInoutFloatingBar(event, [
        { icon: 'fa-edit',  color: '#d97706', title: 'ویرایش', run: function () { editWarehouseTransfer(transferId); } },
        { icon: 'fa-trash', color: '#dc2626', title: 'حذف',    run: function () { deleteWarehouseTransfer(transferId, productId); } }
    ]);
}

function editWarehouseTransfer(id) {
    var rec = (db.getTransfers && db.getTransfers() || []).find(function (t) { return t.id == id; });
    if (!rec) { showMessage('خطا', 'انتقال یافت نشد'); return; }
    if (typeof openTransferForm === 'function') openTransferForm(rec.fromId, rec);
}

function deleteWarehouseTransfer(id, productId) {
    if (!confirm('این انتقال حذف شود؟ موجودیِ گدام‌های مبدأ و مقصد دوباره و دقیق محاسبه می‌شود.')) return;
    var res = db.deleteTransfer ? db.deleteTransfer(id) : { success: false };
    if (!res || !res.success) { showMessage('خطا', (res && res.error) || 'حذف انتقال ناموفق بود'); return; }
    // بازمحاسبهٔ دقیقِ موجودی از دادهٔ خام (انتقالِ حذف‌شده دیگر اعمال نمی‌شود)
    if (typeof rebuildAllDerivedData === 'function') { try { rebuildAllDerivedData(); } catch (e) {} }
    try { window.dispatchEvent(new CustomEvent('jouya-data-change', { detail: { reason: 'transfer-delete' } })); } catch (e) {}
    if (typeof loadProductsList === 'function') { try { loadProductsList(); } catch (e) {} }
    if (typeof loadDashboard === 'function') { try { loadDashboard(); } catch (e) {} }
    setTimeout(function () {
        var pid = (productId != null) ? productId : window._currentInoutProductId;
        var section = document.getElementById('product-inout-list');
        if (section && section.classList.contains('active') && pid != null && typeof showProductInOutList === 'function') showProductInOutList(pid);
    }, 200);
    showMessage('موفقیت', 'انتقال حذف و موجودی بازمحاسبه شد');
}

// ---------------------------------------------------------------------------
//  نوارِ عملیاتِ ردیفِ «موجودی اولیه» — ویرایش/حذف (حذف = صفرکردنِ موجودیِ اولیه + بازمحاسبه)
// ---------------------------------------------------------------------------
function showInitialStockActionBar(event, productId) {
    _buildInoutFloatingBar(event, [
        { icon: 'fa-edit',  color: '#d97706', title: 'ویرایش موجودی اولیه', run: function () { if (typeof showProductForm === 'function') showProductForm(productId, { editInitialStock: true }); } },
        { icon: 'fa-trash', color: '#dc2626', title: 'حذف موجودی اولیه',   run: function () { deleteInitialStock(productId); } }
    ]);
}

function deleteInitialStock(productId) {
    if (!confirm('موجودی اولیهٔ این جنس صفر شود؟ تمامِ معاملات مطابقِ موجودیِ اولیهٔ جدید (صفر) دوباره و دقیق محاسبه می‌شوند.')) return;
    try {
        var products = db.getAllProducts ? db.getAllProducts() : (JSON.parse(localStorage.getItem('products') || '[]') || []);
        var idx = products.findIndex(function (p) { return p.id == productId; });
        if (idx === -1) { showMessage('خطا', 'جنس یافت نشد'); return; }
        products[idx].initialStock = 0;
        // پاک‌سازیِ قیمتِ خریدِ «سری اولِ» موجودیِ اولیه تا FIFO مفادِ آن را صفر بگیرد
        products[idx]._batchInitialCostAFN = 0;
        products[idx]._batchInitialCostUSD = 0;
        products[idx].updatedAt = (typeof db.getCurrentDate === 'function') ? db.getCurrentDate() : '';
        localStorage.setItem('products', JSON.stringify(products));
    } catch (e) { showMessage('خطا', 'حذف موجودی اولیه ناموفق بود'); return; }
    // بازمحاسبهٔ کاملِ مشتقات (موجودی، FIFO/مفاد، سرمایه، حساب) از دادهٔ خام
    if (typeof rebuildAllDerivedData === 'function') { try { rebuildAllDerivedData(); } catch (e) {} }
    try { window.dispatchEvent(new CustomEvent('jouya-data-change', { detail: { reason: 'initial-stock-delete' } })); } catch (e) {}
    if (typeof loadProductsList === 'function') { try { loadProductsList(); } catch (e) {} }
    if (typeof loadDashboard === 'function') { try { loadDashboard(); } catch (e) {} }
    setTimeout(function () {
        var section = document.getElementById('product-inout-list');
        if (section && section.classList.contains('active') && typeof showProductInOutList === 'function') showProductInOutList(productId);
    }, 200);
    showMessage('موفقیت', 'موجودی اولیه صفر و همه‌چیز بازمحاسبه شد');
}

if (typeof window !== 'undefined') {
    window.showTransferActionBar = showTransferActionBar;
    window.editWarehouseTransfer = editWarehouseTransfer;
    window.deleteWarehouseTransfer = deleteWarehouseTransfer;
    window.showInitialStockActionBar = showInitialStockActionBar;
    window.deleteInitialStock = deleteInitialStock;
}

// ارسال خلاصه حساب
function sendAccountSummary(personId) {
    const person = db.getPersons().find(p => p.id == personId);
    if (!person) return;
    
    const transactions = db.getTransactions();
    const personTransactions = transactions.filter(t => 
        t.personId == personId || 
        (t.customerId == personId) || 
        (t.supplierId == personId)
    );
    
    let totalAFN = 0;
    let totalUSD = 0;
    var _accByCur = {};  // جمعِ معاملات به تفکیکِ هر ارز (پویا)
    var _accBase = _baseCur();
    
    personTransactions.forEach(tx => {
        var _c = tx.currency || _accBase;
        _accByCur[_c] = (_accByCur[_c] || 0) + (tx.amount || 0);
    });
    totalAFN = _accByCur[_accBase] || 0;
    // اولین ارزِ غیرپایه برای سازگاریِ نمایشِ قدیمی
    var _accCol2 = Object.keys(_accByCur).filter(function (c) { return c !== _accBase; })[0] || null;
    totalUSD = _accCol2 ? (_accByCur[_accCol2] || 0) : 0;
    // سطرهای پویای همهٔ ارزها برای نمایش در modal
    var _accRowsHtml = Object.keys(_accByCur).map(function (c) {
        var lbl = (typeof getCurrencyLabel === 'function') ? getCurrencyLabel(c) : c;
        return '<p>جمع کل معاملات ' + lbl + ': <strong>' + formatAmountWithCurrency(_accByCur[c] || 0, c) + '</strong></p>';
    }).join('');
    
    showModal('خلاصه حساب', `
        <div class="account-summary">
            <h4>${person.name}</h4>
            <p>کتگوری: ${person.category}</p>
            <div class="summary-totals">
                ${_accRowsHtml}
                <p>شماره تماس: ${person.phone || 'ندارد'}</p>
            </div>
            <p class="message-preview">
                <strong>پیش‌نمایش پیام:</strong><br>
                ${person.name} عزیز، حساب شما به شرح زیر است:<br>
                ${Object.keys(_accByCur).map(function(c){ var lbl=(typeof getCurrencyLabel==='function')?getCurrencyLabel(c):c; return 'جمع معاملات ' + lbl + ': ' + formatAmountWithCurrency(_accByCur[c]||0, c); }).join('<br>')}<br>
                با تشکر
            </p>
        </div>
    `);
}
/* ==========================================================================

   بخش اصلاح شده و نهایی مدیریت افراد (نوار ابزار افقی آیکن‌دار)

   ========================================================================== */

// بارگذاری لیست افراد
function loadPersonsList() {
    const persons = db.getPersons();
    renderPersonsTable(persons);
}

// فیلتر اشخاص

// تابع رندر جدول (بدون کدهای HTML اضافه برای منو)
/* ==========================================================================

   بخش اصلاح شده و نهایی مدیریت افراد (نوار ابزار افقی آیکن‌دار)

   ========================================================================== */

// بارگذاری لیست افراد
function loadPersonsList() {
    // ریست حالت انتخاب (picker) اگر هنوز فعال است
    if (!_personPickerCallback) {
        _personPickerCallback = null;
        _personPickerCategory = null;
        _personPickerReturnSection = null;
    }
    const persons = db.getPersons();
    // اگر در حالت picker هستیم، جدول picker رندر شود
    if ((typeof _rpPersonPick !== 'undefined' && _rpPersonPick) || _personPickerCallback) {
        renderPersonsTablePickerMode(persons);
    } else {
        renderPersonsTable(persons);
    }
}

// فیلتر اشخاص
function filterPersons() {
    try {
        const persons = db.getPersons();
        const typeEl = document.getElementById('filter-person-type');
        const balanceEl = document.getElementById('filter-person-balance');
        const searchEl = document.getElementById('global-search-persons');
        const typeFilter = typeEl ? typeEl.value : 'all';
        const balanceFilter = balanceEl ? balanceEl.value : 'all';
        const searchText = searchEl ? searchEl.value.toLowerCase() : '';
        
        const filtered = persons.filter(person => {
            if (typeFilter !== 'all') {
                const catMap = { customer: 'مشتری', supplier: 'تامین کننده' };
                const target = catMap[typeFilter] || typeFilter;
                if (person.category !== target) return false;
            }
            if (balanceFilter !== 'all') {
                if (balanceFilter === 'debt' && person.accountType !== 'بدهکار') return false;
                if (balanceFilter === 'credit' && person.accountType !== 'طلبکار') return false;
                if (balanceFilter === 'balanced' && person.accountType !== 'بدون حساب') return false;
            }
            if (searchText) {
                const nameMatch = person.name && person.name.toLowerCase().includes(searchText);
                const phoneMatch = person.phone && person.phone.includes(searchText);
                const idMatch = person.idNumber && person.idNumber.includes(searchText);
                const addrMatch = person.address && person.address.toLowerCase().includes(searchText);
                if (!nameMatch && !phoneMatch && !idMatch && !addrMatch) return false;
            }
            return true;
        });
        
        renderPersonsTable(filtered);
    } catch (error) {
        console.error('خطا در فیلتر اشخاص:', error);
    }
}

// تابع رندر جدول - محاسبه مانده واقعی از تراکنش‌ها
// محاسبهٔ مشترکِ «باقیداری/طلب» برای کارتِ شخص — تا نمای عادی و نمای انتخاب (picker) دقیقاً
// یک ظاهر و یک منطق داشته باشند (یکپارچگیِ رابط کاربری در همهٔ فورم‌ها).
function _computePersonCardBalance(person, allTransactions) {
    var balMap = {}; var _rtBal = function (c, v) { balMap[c] = (balMap[c] || 0) + v; };
    if (person.previousAccount) {
        var prevAmount = parseFloat(person.previousAccount) || 0;
        if (prevAmount !== 0) {
            var prevCurrency = person.currency || _baseCur();
            if (person.accountType === 'بدهکار') _rtBal(prevCurrency, prevAmount);
            else if (person.accountType === 'طلبکار') _rtBal(prevCurrency, -prevAmount);
        }
    }
    var personTxs = (allTransactions || []).filter(function (t) {
        return t.personId == person.id || t.customerId == person.id || t.supplierId == person.id;
    });
    personTxs.forEach(function (tx) {
        var totalAmount = parseFloat(tx.totalAmount || tx.amount || 0);
        var remaining = (typeof calculateTxRemaining === 'function') ? calculateTxRemaining(tx) : (parseFloat(tx.remaining) || 0);
        var currency = tx.currency || _baseCur();
        var effect = 0;
        if (tx.type === 'صرافی') {
            var _lfc = tx.fromCurrency || currency, _ltc = tx.toCurrency || currency;
            var _lfa = parseFloat(tx.fromAmount || 0) || 0, _lta = parseFloat(tx.toAmount || 0) || 0;
            var _lcs = (tx.convSign != null ? tx.convSign : 1);
            if (_lfa) _rtBal(_lfc, -_lcs * _lfa);
            if (_lta) _rtBal(_ltc, +_lcs * _lta);
            return;
        }
        switch (tx.type) {
            case 'فروش': effect = remaining; break;
            case 'خرید': effect = -remaining; break;
            case 'دریافت': effect = -totalAmount; break;
            case 'پرداخت': effect = totalAmount; break;
            case 'پرداخت از حساب قبلی':
                if (person.accountType === 'طلبکار') effect = totalAmount; else effect = -totalAmount; break;
            case 'برگشت':
                if (tx.returnType === 'فروش') effect = -(tx.remaining != null ? parseFloat(tx.remaining) : totalAmount);
                else if (tx.returnType === 'خرید') effect = (tx.remaining != null ? parseFloat(tx.remaining) : totalAmount);
                break;
        }
        _rtBal(currency, effect);
    });
    var balanceAFN = balMap['AFN'] || 0, balanceUSD = balMap['USD'] || 0;
    var _fnum = function (v) { return (typeof formatNumber === 'function') ? formatNumber(Math.abs(parseFloat(v) || 0)) : Math.abs(parseFloat(v) || 0); };
    var _dualCond = function (afn, usd, map, sign) {
        var parts = [];
        if (Math.abs(parseFloat(usd) || 0) > 0.005) parts.push(_fnum(usd) + '($)');
        if (Math.abs(parseFloat(afn) || 0) > 0.5) parts.push(_fnum(afn) + '(AFN)');
        if (map) {
            Object.keys(map).forEach(function (c) {
                if (c === 'AFN' || c === 'USD') return;
                var v = parseFloat(map[c]) || 0;
                if (sign > 0 ? v > 0.005 : v < -0.005) parts.push(_fnum(v) + '(' + _curLabelGlobal(c) + ')');
            });
        }
        return parts.join('-');
    };
    var debtAFN = (balanceAFN > 0.5) ? balanceAFN : 0, debtUSD = (balanceUSD > 0.005) ? balanceUSD : 0;
    var credAFN = (balanceAFN < -0.5) ? -balanceAFN : 0, credUSD = (balanceUSD < -0.005) ? -balanceUSD : 0;
    var baqi = _dualCond(debtAFN, debtUSD, balMap, 1);
    var talab = _dualCond(credAFN, credUSD, balMap, -1);
    return {
        baqiHtml: baqi ? '<div class="person-card-balance">باقیداری: <span>' + baqi + '</span></div>' : '',
        talabHtml: talab ? '<div class="person-card-debt">طلب: <span>' + talab + '</span></div>' : '',
        balMap: balMap
    };
}
if (typeof window !== 'undefined') window._computePersonCardBalance = _computePersonCardBalance;

function renderPersonsTable(personsList) {
    const tbody = document.querySelector('#persons-table tbody');
    if (!tbody) return;

    // پنهان کردن عنوان ستون‌های جدول
    const thead = document.querySelector('#persons-table thead');
    if (thead) thead.style.display = 'none';

    tbody.innerHTML = '';

    const allTransactions = db.getTransactions() || [];

    personsList.forEach(person => {
        let balanceAFN = 0;
        let balanceUSD = 0;
        var balMap = {}; var _rtBal = function(c, v){ balMap[c] = (balMap[c] || 0) + v; };

        // حساب قبلی شخص
        if (person.previousAccount) {
            const prevAmount = parseFloat(person.previousAccount) || 0;
            if (prevAmount !== 0) {
                const prevCurrency = person.currency || _baseCur();
                if (person.accountType === 'بدهکار') {
                    _rtBal(prevCurrency, prevAmount);
                } else if (person.accountType === 'طلبکار') {
                    _rtBal(prevCurrency, -prevAmount);
                }
            }
        }

        const personTxs = allTransactions.filter(t =>
            t.personId == person.id || t.customerId == person.id || t.supplierId == person.id
        );

        personTxs.forEach(tx => {
            const totalAmount = parseFloat(tx.totalAmount || tx.amount || 0);
            const remaining = calculateTxRemaining(tx);
            const currency = tx.currency || _baseCur();
            let effect = 0;

            // تبدیل ارز (صرافی): دو-لِنگ — با حفظِ علامتِ حساب (طلبکار/بدهکار)
            if (tx.type === 'صرافی') {
                var _lfc = tx.fromCurrency || currency, _ltc = tx.toCurrency || currency;
                var _lfa = parseFloat(tx.fromAmount || 0) || 0, _lta = parseFloat(tx.toAmount || 0) || 0;
                var _lcs = (tx.convSign != null ? tx.convSign : 1);
                if (_lfa) _rtBal(_lfc, -_lcs * _lfa);
                if (_lta) _rtBal(_ltc, +_lcs * _lta);
                return;
            }

            switch(tx.type) {
                case 'فروش': effect = remaining; break;
                case 'خرید': effect = -remaining; break;
                case 'دریافت': effect = -totalAmount; break;
                case 'پرداخت': effect = totalAmount; break;
                case 'پرداخت از حساب قبلی':
                    // این نوع تراکنش فقط برای تغییرات بعدی در حساب قبلی (ویرایش) ثبت می‌شود
                    // نه برای ثبت اولیه — پس همیشه در محاسبه لحاظ می‌شود
                    if (person.accountType === 'طلبکار') effect = totalAmount;
                    else effect = -totalAmount;
                    break;
                case 'برگشت':
                    if (tx.returnType === 'فروش') effect = -(tx.remaining != null ? parseFloat(tx.remaining) : totalAmount);
                    else if (tx.returnType === 'خرید') effect = (tx.remaining != null ? parseFloat(tx.remaining) : totalAmount);
                    break;
            }

            _rtBal(currency, effect);
        });
        balanceAFN = balMap['AFN'] || 0; balanceUSD = balMap['USD'] || 0;

        // ===== باقیداری = بدهکاری (مانده مثبت) | طلب = طلبکاری (مانده منفی) — از دیتای واقعی =====
        var _fnum = function (v) { return (typeof formatNumber === 'function') ? formatNumber(Math.abs(parseFloat(v) || 0)) : Math.abs(parseFloat(v) || 0); };
        // فقط ارزی که مقدار داشته باشد نمایش داده می‌شود (نمایش شرطی) — شاملِ ارزِ سوم
        var _dualCond = function (afn, usd, map, sign) {
            var parts = [];
            if (Math.abs(parseFloat(usd) || 0) > 0.005) parts.push(_fnum(usd) + '($)');
            if (Math.abs(parseFloat(afn) || 0) > 0.5)   parts.push(_fnum(afn) + '(AFN)');
            if (map) {
                Object.keys(map).forEach(function (c) {
                    if (c === 'AFN' || c === 'USD') return;
                    var v = parseFloat(map[c]) || 0;
                    // sign>0 ⇒ فقط مثبت‌ها (باقیداری) ، sign<0 ⇒ فقط منفی‌ها (طلب)
                    if (sign > 0 ? v > 0.005 : v < -0.005) parts.push(_fnum(v) + '(' + _curLabelGlobal(c) + ')');
                });
            }
            return parts.join('-');
        };
        // بدهکاری شخص به ما (مانده مثبت) → باقیداری
        var debtAFN = (balanceAFN > 0.5) ? balanceAFN : 0;
        var debtUSD = (balanceUSD > 0.005) ? balanceUSD : 0;
        // طلبکاری شخص از ما (مانده منفی) → طلب
        var credAFN = (balanceAFN < -0.5) ? -balanceAFN : 0;
        var credUSD = (balanceUSD < -0.005) ? -balanceUSD : 0;
        var baqi  = _dualCond(debtAFN, debtUSD, balMap, 1);
        var talab = _dualCond(credAFN, credUSD, balMap, -1);
        // ردیفِ آمار فقط در صورت داشتنِ مقدار در همان جای قبلیِ کارت نمایش داده می‌شود؛ در غیر آن نمایش داده نمی‌شود
        var baqiHtml  = baqi  ? '<div class="person-card-balance">باقیداری: <span>' + baqi + '</span></div>' : '';
        var talabHtml = talab ? '<div class="person-card-debt">طلب: <span>' + talab + '</span></div>' : '';

        const row = document.createElement('tr');
        row.className = 'person-card-row';
        row.innerHTML = `
            <td class="person-card-cell">
                <div class="person-card" onclick="showPersonTransactions(${person.id})" style="cursor:pointer;">
                    <div class="person-card-main">
                        <span class="person-card-avatar"><i class="fas fa-user"></i></span>
                        <span class="person-card-name">${person.name}</span>
                    </div>
                    ${baqiHtml}
                    ${talabHtml}
                    <div class="person-card-actions" onclick="event.stopPropagation()">
                        <button class="person-card-kebab action-trigger-btn" type="button"
                                onmouseenter="showHorizontalActionBar(event, ${person.id})"
                                onmouseleave="handleActionButtonMouseLeave(event)"
                                title="عملیات">
                            <i class="fas fa-ellipsis-v"></i>
                        </button>
                    </div>
                </div>
            </td>
        `;
        tbody.appendChild(row);
    });
}

/* ==========================================================================

   توابع مدیریت نوار ابزار شناور عمودی (Floating Vertical Toolbar)
   ========================================================================== */

// متغیرهای سراسری برای مدیریت نوار ابزار
var currentToolbar = null;
var closeToolbarTimer = null;

// نمایش نوار ابزار عمودی با هاور
function showHorizontalActionBar(event, id) {
    if (typeof _ensureActionMenuSafetyNet === 'function') _ensureActionMenuSafetyNet();
    // اگر تایمر بستن وجود دارد، آن را لغو کن
    if (closeToolbarTimer) {
        clearTimeout(closeToolbarTimer);
        closeToolbarTimer = null;
    }

    // بستن نوار ابزار قبلی
    if (currentToolbar) {
        currentToolbar.remove();
        currentToolbar = null;
    }

    const person = db.getPersons().find(p => p.id == id);
    if (!person) return;

    // ساخت کانتینر نوار ابزار
    const toolbar = document.createElement('div');
    toolbar.className = 'floating-action-toolbar';
    toolbar.setAttribute('data-person-id', id);
    
    // استایل‌دهی مستقیم برای اطمینان از نمایش صحیح (عمودی و شناور — با لیبل کنار آیکن)
    Object.assign(toolbar.style, {
        position: 'absolute',
        display: 'flex',
        flexDirection: 'column',
        alignItems: 'stretch',
        gap: '4px',
        backgroundColor: '#ffffff',
        padding: '8px',
        borderRadius: '12px',
        boxShadow: '0 5px 20px rgba(0,0,0,0.2)',
        border: '1px solid #cbd5e1',
        zIndex: '9999',
        whiteSpace: 'nowrap',
        minWidth: '180px'
    });

    // تعریف دکمه‌های عملیات (آیکن + عنوان نمایشی)
    const actions = [
        { icon: 'fa-cart-plus', color: '#16a34a', title: 'فروش جدید', action: 'new-sale' },
        { icon: 'fa-shopping-basket', color: '#2563eb', title: 'خرید جدید', action: 'new-purchase' },
        { icon: 'fa-hand-holding-usd', color: '#0891b2', title: 'دریافتی جدید', action: 'new-receipt' },
        { icon: 'fa-money-check-alt', color: '#d97706', title: 'پرداختی جدید', action: 'new-payment' },
        { icon: 'fa-address-card', color: '#0ea5e9', title: 'مشخصات شخص', action: 'person-detail' },
        { icon: 'fa-right-left', color: '#0891b2', title: 'تبدیل ارز داخل حساب مشتری', action: 'convert-currency' },
        { icon: 'fa-list-alt', color: '#4f46e5', title: 'لیست معاملات', action: 'transactions' },
        { icon: 'fa-file-alt', color: '#0ea5e9', title: 'گزارش معاملات شخص', action: 'report' },
        { icon: 'fa-envelope', color: '#475569', title: 'ارسال پیام', action: 'send-message' },
        { icon: 'fa-edit', color: '#334155', title: 'ویرایش', action: 'edit' },
        { icon: 'fa-trash', color: '#dc2626', title: 'حذف', action: 'delete' }
    ];

    // ساخت دکمه‌ها داخل نوار
    actions.forEach(item => {
        const btn = document.createElement('button');
        btn.title = item.title;
        btn.innerHTML = `<i class="fas ${item.icon}" style="width:18px;text-align:center;color:${item.color};"></i><span style="margin-right:10px;font-size:13px;color:#1e293b;font-weight:500;">${item.title}</span>`;
        
        // استایل دکمه‌ها (افقی: آیکن + متن)
        Object.assign(btn.style, {
            background: 'transparent',
            border: 'none',
            cursor: 'pointer',
            padding: '8px 10px',
            transition: 'background 0.2s',
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'flex-start',
            borderRadius: '6px',
            textAlign: 'right',
            fontFamily: 'inherit'
        });

        // افکت هاور
        btn.onmouseenter = () => btn.style.background = '#f1f5f9';
        btn.onmouseleave = () => btn.style.background = 'transparent';

        // اکشن کلیک
        if (item.action === 'transactions') {
            btn.onclick = (e) => {
                e.stopPropagation();
                closeAllActionMenus();
                showPersonTransactions(id);
            };
        } else {
            btn.onclick = (e) => {
                e.stopPropagation();
                closeAllActionMenus();
                performPersonAction(id, item.action);
            };
        }

        toolbar.appendChild(btn);
    });

    // رویدادها برای نوار ابزار
    toolbar.addEventListener('mouseenter', () => {
        // اگر موس وارد نوار ابزار شد، تایمر بستن را لغو کن
        if (closeToolbarTimer) {
            clearTimeout(closeToolbarTimer);
            closeToolbarTimer = null;
        }
    });

    toolbar.addEventListener('mouseleave', (e) => {
        // اگر موس از نوار ابزار خارج شد، نوار را با تاخیر ببند
        startCloseToolbarTimer();
    });

    document.body.appendChild(toolbar);
    currentToolbar = toolbar;

    // محاسبه موقعیت دقیق (شناور کنار دکمه کلیک شده)
    const rect = event.currentTarget.getBoundingClientRect();
    const scrollTop = window.pageYOffset || document.documentElement.scrollTop;
    const scrollLeft = window.pageXOffset || document.documentElement.scrollLeft;

    // تنظیم موقعیت نوار ابزار: سمت راست دکمه سه نقطه و هم‌تراز با آن
    toolbar.style.top = (rect.top + scrollTop) + 'px';
    toolbar.style.left = (rect.right + scrollLeft + 10) + 'px';

    // انیمیشن ورود
    toolbar.animate([
        { opacity: 0, transform: 'scale(0.8)' },
        { opacity: 1, transform: 'scale(1)' }
    ], { duration: 200, easing: 'cubic-bezier(0.175, 0.885, 0.32, 1.275)' });
}

// وقتی موس از دکمه سه نقطه خارج شد
function handleActionButtonMouseLeave(event) {
    // وقتی موس از دکمه سه نقطه خارج شد، اگر وارد نوار ابزار نشدیم، نوار ابزار را بعد از تاخیر ببند
    startCloseToolbarTimer();
}

// شروع تایمر برای بستن نوار ابزار
function startCloseToolbarTimer() {
    // اگر تایمری از قبل بود، پاکش کن
    if (closeToolbarTimer) {
        clearTimeout(closeToolbarTimer);
    }
    // تنظیم تایمر برای بستن نوار ابزار بعد از 300 میلی‌ثانیه
    closeToolbarTimer = setTimeout(() => {
        if (currentToolbar) {
            currentToolbar.remove();
            currentToolbar = null;
        }
        closeToolbarTimer = null;
    }, 300);
}

// بستن تمام منوها
function closeAllActionMenus() {
    if (currentToolbar) {
        currentToolbar.remove();
        currentToolbar = null;
    }
    if (closeToolbarTimer) {
        clearTimeout(closeToolbarTimer);
        closeToolbarTimer = null;
    }
}

// مدیریت منطق عملیات (بدون تغییر در منطق اصلی، فقط فراخوانی فرم‌ها)
function performPersonAction(id, action) {
    const person = db.getPersons().find(p => p.id == id);
    if (!person) return;

    switch(action) {
        case 'new-sale':
            showSalesForm();
            setTimeout(() => {
                const hiddenInput = document.getElementById('qs-customer');
                const searchInput = document.getElementById('qs-customer-search');
                if (hiddenInput) hiddenInput.value = id;
                if (searchInput) searchInput.value = person.name;
            }, 150);
            break;
            
        case 'new-purchase':
            showPurchaseForm();
            setTimeout(() => {
                const hiddenInput = document.getElementById('qp-supplier');
                const searchInput = document.getElementById('qp-supplier-search');
                if (hiddenInput) hiddenInput.value = id;
                if (searchInput) searchInput.value = person.name;
            }, 150);
            break;
            
        case 'new-receipt':
            showReceiptForm();
            setTimeout(() => {
                const hiddenInput = document.getElementById('receive-from');
                const searchInput = document.getElementById('receive-from-search');
                if (hiddenInput) hiddenInput.value = id;
                if (searchInput) searchInput.value = person.name;
            }, 150);
            break;
            
        case 'new-payment':
            showPaymentForm();
            setTimeout(() => {
                const hiddenInput = document.getElementById('pay-to');
                const searchInput = document.getElementById('pay-to-search');
                if (hiddenInput) hiddenInput.value = id;
                if (searchInput) searchInput.value = person.name;
            }, 150);
            break;

        case 'send-message':
            let balanceText = person.previousAccount ? `مانده: ${formatCurrency(person.previousAccount)}` : 'حساب تسویه';
            alert(`پیام به ${person.name}:\n${balanceText}`);
            break;

        case 'person-detail':
            if (typeof showPersonDetail === 'function') showPersonDetail(id);
            break;

        case 'convert-currency':
            openCurrencyConversion('inside_person', { personId: id });
            break;

        case 'report':
            generatePersonReport(id);
            break;

        case 'edit':
            showPersonForm(id);
            break;

        case 'delete':
            deletePerson(id);
            break;
    }
}

// =============================================================================
// ===== مشخصات کامل شخص (Person Detail) =====
// نمایش «مشخصات شخص» + «خلاصه معاملات» با ارقام دقیق و لحظه‌ای.
// هیچ داده‌ای ذخیره نمی‌شود؛ همه‌چیز از db خوانده و محاسبه می‌شود تا با هر ویرایش/ثبت
// به‌صورت آنی هماهنگ بماند. بلانس دقیقاً با همان منطقِ «لیست معاملات شخص» محاسبه می‌شود
// و مفاد از موتور FIFO موجود (saleMap) گرفته می‌شود تا با گزارش‌ها یکسان باشد.
// از کمکی‌های مشترکِ مشخصات جنس (_pdRound2, _pdFmt, _pdAFN, _pdUSD, _pdText, _pdEsc,
// _pdCurrentUserName, _pdDateTimeStr, _pdRow) استفاده می‌شود.
// =============================================================================
var _currentPersonDetailId = null;
var _personDetailReturnForForm = null;  // شناسهٔ شخصی که باید از فورم ثبت به مشخصات برگردد
var _personDetailReturnForTx = null;     // شناسهٔ شخصی که باید از لیست معاملات به مشخصات برگردد
var _ptxReturnToTxDetailId = null;       // اگر از «اطلاعات فروش/خرید» به لیست معاملات رفتیم، برگشت به همان

// ساعت زندهٔ فوتر مشخصات شخص (مستقل، مانند مشخصات جنس)
function _psdClockTick() {
    var sec = document.getElementById('person-detail');
    if (!sec || sec.style.display === 'none' || !sec.classList.contains('active')) return;
    var el = document.getElementById('psd-datetime');
    if (el && typeof _pdDateTimeStr === 'function') { var s = _pdDateTimeStr(); if (el.textContent !== s) el.textContent = s; }
}
if (typeof window !== 'undefined' && !window._psdClockTimer) {
    window._psdClockTimer = setInterval(_psdClockTick, 1000);
}

// موتور محاسبه و نمایش کامل مشخصات یک شخص
function _renderPersonDetail(personId) {
    if (typeof db === 'undefined') return;
    var person = (db.getPersons() || []).find(function (p) { return p.id == personId; });
    if (!person) return;

    // نشان بالا
    var badgeImg = document.getElementById('psd-badge-img');
    if (badgeImg) badgeImg.innerHTML = person.image ? ('<img src="' + _pdEsc(person.image) + '" alt="">') : '<i class="fas fa-camera"></i>';
    var nameEl = document.getElementById('psd-name'); if (nameEl) nameEl.textContent = person.name || 'بدون نام';
    var catEl = document.getElementById('psd-cat'); if (catEl) catEl.textContent = (person.category && String(person.category).trim()) ? person.category : 'بدون کتگوری';

    // ---- جعبهٔ معلومات پایه ----
    var infoRows = '';
    infoRows += _pdRow('شماره تماس', _pdText(person.phone));
    infoRows += _pdRow('شماره تذکره', _pdText(person.idNumber));
    infoRows += _pdRow('آدرس', _pdText(person.address));
    infoRows += _pdRow('جزئیات بیشتر', '<span class="pdc-row-cta">ویرایش</span>', { click: 'openPersonEditFromDetail(' + personId + ')' });
    var infoEl = document.getElementById('psd-rows-info'); if (infoEl) infoEl.innerHTML = infoRows;

    // ---- گردآوری خلاصهٔ معاملات ----
    var allTx = db.getTransactions() || [];
    var personTxs = allTx.filter(function (t) { return t.personId == personId || t.customerId == personId || t.supplierId == personId; });
    var fmaps = (typeof _getFifoMaps === 'function') ? _getFifoMaps() : { saleMap: {} };
    var saleMap = (fmaps && fmaps.saleMap) ? fmaps.saleMap : {};

    // نگاشتِ واحدِ چند-ارزی برای همهٔ ارزها (شاملِ AFN/USD) — بدونِ هیچ اسکالرِ ثابت‌ارز.
    var M = {};
    function _M(c){ c=c||_baseCur(); if(!M[c]) M[c]={buy:0,sell:0,pay:0,recv:0,retBuy:0,retSell:0,profit:0,bal:0}; return M[c]; }

    // بلانس اولیه از «حساب قبلی» — دقیقاً مطابق منطق لیست معاملات
    if (person.previousAccount) {
        var prev = parseFloat(person.previousAccount) || 0;
        var prevCur = person.currency || _baseCur();
        if (person.accountType === 'بدهکار') { _M(prevCur).bal += prev; }
        else if (person.accountType === 'طلبکار') { _M(prevCur).bal -= prev; }
    }

    personTxs.forEach(function (tx) {
        var cur = tx.currency || _baseCur();
        var total = parseFloat(tx.totalAmount || tx.amount || 0);
        var remaining = (typeof calculateTxRemaining === 'function') ? calculateTxRemaining(tx) : (parseFloat(tx.remaining) || 0);

        // جمع‌های خلاصه بر اساس نوع — همه از نگاشتِ چند-ارزی (بدونِ هاردکدِ AFN/USD)
        // تابعِ کمکی: نقدِ چند-ارزیِ یک سند را از نگاشتِ پویا جمع می‌کند (با fallback به فیلدهای قدیمی)
        function _accCash(mapKey, legacyBase, legacyUsd, legacyForeign, bucketKey) {
            var _m = tx[mapKey];
            if (_m && typeof _m === 'object' && !Array.isArray(_m)) {
                // منبعِ پویا: هر ارزی که در سند ثبت شده
                Object.keys(_m).forEach(function (cc) {
                    var v = parseFloat(_m[cc]) || 0;
                    if (v) _M(cc)[bucketKey] += v;
                });
            } else {
                // سازگاریِ عقب‌رو با اسنادِ قدیمی (فیلدهای AFN/USD/Foreign جدا)
                var _b = _baseCur();
                var a = parseFloat(legacyBase) || 0; if (a) _M(_b === 'USD' ? 'AFN' : _b)[bucketKey] += a;
                var u = parseFloat(legacyUsd) || 0;  if (u) _M('USD')[bucketKey] += u;
                var f = parseFloat(legacyForeign) || 0; if (f && cur !== 'AFN' && cur !== 'USD') _M(cur)[bucketKey] += f;
            }
        }

        switch (tx.type) {
            case 'خرید':
                _M(cur).buy += total;
                // نقدِ پرداخت‌شده در خودِ بلِ خرید — کاملاً پویا از نگاشتِ paidAmounts
                _accCash('paidAmounts',
                    (tx.paidAfn != null ? tx.paidAfn : tx.cashAfn),
                    (tx.paidUsd != null ? tx.paidUsd : tx.cashUsd),
                    tx.paidForeign, 'pay');
                break;
            case 'فروش':
                _M(cur).sell += total;
                var sp = saleMap[tx.id];
                if (typeof sp === 'number' && !isNaN(sp)) _M(cur).profit += sp;
                // نقدِ دریافت‌شده در خودِ بلِ فروش — کاملاً پویا از نگاشتِ cashAmounts
                _accCash('cashAmounts', tx.cashAfn, tx.cashUsd, tx.cashForeign, 'recv');
                break;
            case 'پرداخت':
                _M(cur).pay += total;
                break;
            case 'دریافت':
                _M(cur).recv += total;
                break;
            case 'برگشت':
                if (tx.returnType === 'خرید') _M(cur).retBuy += total;
                else if (tx.returnType === 'فروش') _M(cur).retSell += total;
                break;
        }

        // اثر بر بلانس — دقیقاً مطابق منطق لیست معاملات شخص
        var effect = 0;
        switch (tx.type) {
            case 'فروش': effect = remaining; break;
            case 'خرید': effect = -remaining; break;
            case 'دریافت': effect = -total; break;
            case 'پرداخت': effect = total; break;
            case 'پرداخت از حساب قبلی': effect = (person.accountType === 'طلبکار') ? total : -total; break;
            case 'برگشت':
                if (tx.returnType === 'فروش') effect = -total;
                else if (tx.returnType === 'خرید') effect = total;
                break;
        }
        if (tx.type === 'صرافی') {
            var _rfc = tx.fromCurrency || cur, _rtc = tx.toCurrency || cur;
            var _rfa = parseFloat(tx.fromAmount || 0) || 0, _rta = parseFloat(tx.toAmount || 0) || 0;
            var _rcs = (tx.convSign != null ? tx.convSign : 1);
            if (_rfa) _M(_rfc).bal += -_rcs * _rfa;
            if (_rta) _M(_rtc).bal += +_rcs * _rta;
            return;
        }
        _M(cur).bal += effect;
    });

    // نمایش بلانس با برچسب بدهکار/طلبکار/تسویه
    function _balHtml(amount, symbol) {
        if (Math.abs(amount) < 0.005) return { text: 'تسویه', cls: 'pdc-v-blue' };
        if (amount > 0) return { text: _pdFmt(_pdRound2(amount)) + ' ' + symbol + ' (بدهکار)', cls: 'pdc-v-red' };
        return { text: _pdFmt(_pdRound2(Math.abs(amount))) + ' ' + symbol + ' (طلبکار)', cls: 'pdc-v-green' };
    }
    // ── نمایشِ پویا: ستونِ اول = ارزِ پایه، ستونِ دوم = اولین ارزِ غیرپایه، بقیه پویا ──
    var _plBase = _baseCur();
    // فهرستِ ارزهایی که در این دفتر داده دارند، با اولویتِ ارزِ پایه در ابتدا
    var _plCodes = Object.keys(M);
    _plCodes.sort(function (a, b) {
        if (a === _plBase) return -1; if (b === _plBase) return 1; return 0;
    });
    var _col1 = _plBase;                                   // ستونِ اول همیشه ارزِ پایه
    var _col2 = _plCodes.filter(function (c) { return c !== _plBase; })[0] || null; // اولین ارزِ غیرپایه

    function _renderLedgerColumn(code) {
        if (!code) return '';
        var m = _M(code);
        var lbl = _curLabelGlobal(code);
        var sym = _curSymGlobal(code);
        var _pdX = function (v) { return _pdFmt(_pdRound2(parseFloat(v) || 0)) + ' ' + sym; };
        var bal = _balHtml(m.bal, sym);
        var r = '';
        r += _pdRow('مجموعه خرید ' + lbl, _pdX(m.buy));
        r += _pdRow('مجموعه فروش ' + lbl, _pdX(m.sell));
        r += _pdRow('مجموعه پرداختی ' + lbl, _pdX(m.pay), { valueClass: 'pdc-v-red' });
        r += _pdRow('مجموعه دریافتی ' + lbl, _pdX(m.recv), { valueClass: 'pdc-v-green' });
        r += _pdRow('برگشت از خرید ' + lbl, _pdX(m.retBuy));
        r += _pdRow('برگشت از فروش ' + lbl, _pdX(m.retSell));
        r += _pdRow('مفاد ' + lbl, _pdX(m.profit), { valueClass: (m.profit < 0 ? 'pdc-v-red' : 'pdc-v-green'), strong: true });
        r += _pdRow('بلانس ' + lbl, bal.text, { valueClass: bal.cls, strong: true });
        return r;
    }

    var afnEl = document.getElementById('psd-rows-afn'); if (afnEl) afnEl.innerHTML = _renderLedgerColumn(_col1);
    var usdEl = document.getElementById('psd-rows-usd'); if (usdEl) usdEl.innerHTML = _col2 ? _renderLedgerColumn(_col2) : '';

    // ---- ستون‌های پویا برای ارزهای سوم به بعد (الحاق به ستونِ دوم) ----
    (function () {
        if (!usdEl) return;
        Object.keys(M).forEach(function (c) {
            if (c === _col1 || c === _col2) return;   // دو ستونِ اصلی قبلاً رندر شدند
            var m = M[c];
            if (!(m.buy || m.sell || m.pay || m.recv || m.retBuy || m.retSell || m.profit || m.bal)) return;
            var lbl = _curLabelGlobal(c);
            var b = _balHtml(m.bal, _curSymGlobal(c));
            var _pdX = function (v) { return _pdFmt(_pdRound2(parseFloat(v) || 0)) + ' ' + _curSymGlobal(c); };
            var xr = '';
            xr += _pdRow('— ' + lbl + ' —', '', { strong: true });
            xr += _pdRow('مجموعه خرید ' + lbl, _pdX(m.buy));
            xr += _pdRow('مجموعه فروش ' + lbl, _pdX(m.sell));
            xr += _pdRow('مجموعه پرداختی ' + lbl, _pdX(m.pay), { valueClass: 'pdc-v-red' });
            xr += _pdRow('مجموعه دریافتی ' + lbl, _pdX(m.recv), { valueClass: 'pdc-v-green' });
            xr += _pdRow('برگشت از خرید ' + lbl, _pdX(m.retBuy));
            xr += _pdRow('برگشت از فروش ' + lbl, _pdX(m.retSell));
            xr += _pdRow('مفاد ' + lbl, _pdX(m.profit), { valueClass: (m.profit < 0 ? 'pdc-v-red' : 'pdc-v-green'), strong: true });
            xr += _pdRow('بلانس ' + lbl, b.text, { valueClass: b.cls, strong: true });
            usdEl.innerHTML += xr;
        });
    })();

    // ---- ردیف «مشاهده لیست معاملات» ----
    var viewEl = document.getElementById('psd-rows-viewtx');
    if (viewEl) viewEl.innerHTML = _pdRow('مشاهده لیست معاملات', '<span class="pdc-row-cta">باز کردن</span>', { click: 'openPersonTxFromDetail(' + personId + ')' });

    // فوتر
    var userEl = document.getElementById('psd-user'); if (userEl && typeof _pdCurrentUserName === 'function') userEl.textContent = _pdCurrentUserName();
    var dtEl = document.getElementById('psd-datetime'); if (dtEl && typeof _pdDateTimeStr === 'function') dtEl.textContent = _pdDateTimeStr();
}

// نمایش بخش مشخصات شخص
function showPersonDetail(personId) {
    if (typeof db === 'undefined') return;
    var person = (db.getPersons() || []).find(function (p) { return p.id == personId; });
    if (!person) { if (typeof showMessage === 'function') showMessage('خطا', 'فرد یافت نشد'); return; }
    _currentPersonDetailId = personId;
    var c = document.getElementById('psd-card-summary'); if (c) c.classList.remove('collapsed');
    showSection('person-detail');
    _renderPersonDetail(personId);
    _psdClockTick();
}

// بازکردن ویرایش شخص از داخل مشخصات (پس از برگشت/ثبت به مشخصات برمی‌گردد)
function openPersonEditFromDetail(personId) {
    _personDetailReturnForForm = personId;
    if (typeof showPersonForm === 'function') showPersonForm(personId, { fromDetail: true });
}
// بازکردن لیست معاملات از داخل مشخصات (پس از برگشت به مشخصات برمی‌گردد)
function openPersonTxFromDetail(personId) {
    if (typeof showPersonTransactions === 'function') showPersonTransactions(personId, true);
}
// دکمهٔ برگشتِ فورم ثبت شخص: اگر از مشخصات آمده به مشخصات، وگرنه به لیست اشخاص
function personFormGoBack() {
    if (_personDetailReturnForForm != null) {
        var id = _personDetailReturnForForm; _personDetailReturnForForm = null;
        if (typeof showPersonDetail === 'function') { showPersonDetail(id); return; }
    }
    if (typeof showSection === 'function') showSection('persons-list');
}
// دکمهٔ برگشتِ لیست معاملات شخص: اگر از مشخصات آمده به مشخصات، وگرنه به لیست اشخاص
function personTxGoBack() {
    if (_ptxReturnToTxDetailId != null) {
        var tid = _ptxReturnToTxDetailId; _ptxReturnToTxDetailId = null;
        if (typeof showTxDetail === 'function') { showTxDetail(tid); return; }
    }
    if (_personDetailReturnForTx != null) {
        var id = _personDetailReturnForTx; _personDetailReturnForTx = null;
        if (typeof showPersonDetail === 'function') { showPersonDetail(id); return; }
    }
    if (typeof showSection === 'function') showSection('persons-list');
}

if (typeof window !== 'undefined') {
    window.showPersonDetail = showPersonDetail;
    window._renderPersonDetail = _renderPersonDetail;
    window.openPersonEditFromDetail = openPersonEditFromDetail;
    window.openPersonTxFromDetail = openPersonTxFromDetail;
    window.personFormGoBack = personFormGoBack;
    window.personTxGoBack = personTxGoBack;
}

// تابع کمکی برای ست کردن سلکت‌ها
function setSelectValue(selectId, personId, personName) {
    const select = document.getElementById(selectId);
    if (select) {
        if (!select.querySelector(`option[value="${personId}"]`)) {
            const option = document.createElement('option');
            option.value = personId;
            option.textContent = personName;
            select.appendChild(option);
        }
        select.value = personId;
    }
}
// محاسبه جمع کل معامله
function calculateTransactionTotal(transaction) {
    let total = 0;
    if (transaction.amount) {
        total = transaction.amount;
    } else if (transaction.items && Array.isArray(transaction.items)) {
        transaction.items.forEach(item => {
            const itemTotal = (item.quantity || 1) * (item.price || 0) - (item.discount || 0);
            total += itemTotal;
        });
    }
    return total;
}

// بدست آوردن کلاس نوع معامله
function getTransactionTypeBadge(type) {
    const badges = {
        'فروش': 'badge-success',
        'خرید': 'badge-primary',
        'دریافت': 'badge-info',
        'پرداخت': 'badge-warning',
        'برگشت': 'badge-danger'
    };
    return badges[type] || 'badge-secondary';
}

// ویرایش تابع loadPersonsTable در script.js:
// پیدا کردن تابع loadPersonsTable و تغییر سلول عملیات
// (اگر تابع loadPersonsTable دارید، این بخش را تغییر دهید)
function loadPersonsTable() {
    const persons = db.getPersons();
    const tbody = document.getElementById('persons-table').querySelector('tbody');
    tbody.innerHTML = '';
    
    persons.forEach(person => {
        const row = document.createElement('tr');
        row.innerHTML = `
            <td>${person.name}</td>
            <td>${person.category}</td>
            <td>${person.phone || '-'}</td>
            <td>${person.idNumber || '-'}</td>
            <td>${person.accountType || 'بدون حساب'}</td>
            <td>${person.accountAmount ? formatCurrency(person.accountAmount) : '۰'}</td>
            <td class="actions-cell">
                <button class="btn-icon btn-primary" onclick="showPersonActionsMenu(${person.id}, event)">
                    <i class="fas fa-ellipsis-v"></i>
                </button>
                <button class="btn-icon btn-edit" onclick="editPerson(${person.id})">
                    <i class="fas fa-edit"></i>
                </button>
                <button class="btn-icon btn-danger" onclick="deletePerson(${person.id})">
                    <i class="fas fa-trash"></i>
                </button>
            </td>
        `;
        tbody.appendChild(row);
    });
}

// ==================== فیلتر معاملات شخص ====================
function filterPersonTransactions() {
    const personId = document.getElementById('person-transactions-list').getAttribute('data-person-id');
    if (!personId) return;
    
    const typeFilter = document.getElementById('filter-person-transaction-type').value;
    const currencyFilter = document.getElementById('filter-person-transaction-currency').value;
    const fromDate = document.getElementById('filter-person-transaction-from').value;
    const toDate = document.getElementById('filter-person-transaction-to').value;
    
    const transactions = db.getTransactions();
    let filteredTransactions = transactions.filter(t => 
        t.personId == personId || 
        (t.customerId == personId) || 
        (t.supplierId == personId)
    );
    
    // فیلتر بر اساس نوع
    if (typeFilter !== 'all') {
        filteredTransactions = filteredTransactions.filter(t => t.type === typeFilter);
    }
    
    // فیلتر بر اساس ارز
    if (currencyFilter !== 'all') {
        filteredTransactions = filteredTransactions.filter(t => t.currency === currencyFilter);
    }
    
    // فیلتر بر اساس تاریخ
    if (fromDate) {
        filteredTransactions = filteredTransactions.filter(t => {
            const txDate = t.date || t.createdAt;
            return compareDates(txDate, fromDate) >= 0;
        });
    }
    
    if (toDate) {
        filteredTransactions = filteredTransactions.filter(t => {
            const txDate = t.date || t.createdAt;
            return compareDates(txDate, toDate) <= 0;
        });
    }
    
    // نمایش نتایج
    displayPersonTransactions(filteredTransactions);
}

// تابع کمکی برای مقایسه تاریخ‌ها
function compareDates(dateStr1, dateStr2) {
    try {
        const d1 = new Date(dateStr1);
        const d2 = new Date(dateStr2);
        return d1 - d2;
    } catch {
        // اگر تاریخ‌ها فرمت متفاوتی دارند، از مقایسه رشته‌ای استفاده می‌کنیم
        return dateStr1.localeCompare(dateStr2);
    }
}

// نمایش معاملات فیلتر شده
function displayPersonTransactions(transactions) {
    const tbody = document.getElementById('person-transactions-table').querySelector('tbody');
    if (!tbody) return;
    tbody.innerHTML = '';

    // مرتب‌سازی از قدیمی‌ترین به جدیدترین برای محاسبه صحیح مانده تجمعی
    transactions = transactions.slice().sort(function(a, b) {
        var da = a.createdAt || a.date || '';
        var db_ = b.createdAt || b.date || '';
        return da.localeCompare(db_);
    });

    // مانده حساب نظر به ارز (مثبت=بدهکار، منفی=طلبکار)
    var balMap = {}; function _dpBal(c, v){ balMap[c] = (balMap[c] || 0) + v; }

    // شخصِ جاری + ورودیِ «حساب قبلی» (به‌عنوان یک ردیفِ عادی در ترتیبِ زمانی، نه ثابت در بالا)
    const personId = document.getElementById('person-transactions-list') ? document.getElementById('person-transactions-list').getAttribute('data-person-id') : null;
    const person = personId ? db.getPersons().find(p => p.id == personId) : null;

    // ===== ساختِ فهرستِ یکپارچهٔ ورودی‌ها =====
    var _entries = [];
    if (person && person.previousAccount) {
        var _prevAmount = parseFloat(person.previousAccount) || 0;
        if (_prevAmount !== 0) {
            _entries.push({
                kind: 'prev',
                sortKey: (person.createdAt || person.date || ''),
                prevAmount: _prevAmount,
                prevCurrency: person.currency || _baseCur(),
                prevAccountType: person.accountType || ''
            });
        }
    }
    transactions.forEach(function(tx) {
        _entries.push({ kind: 'tx', sortKey: (tx.createdAt || tx.date || ''), tx: tx });
    });
    _entries.sort(function(a, b) { return String(a.sortKey).localeCompare(String(b.sortKey)); });

    var _renderedRows = [];

    _entries.forEach(function(entry) {
        if (entry.kind === 'prev') {
            var prevAmount = entry.prevAmount;
            var prevCurrency = entry.prevCurrency;
            var prevSymbol = _curSymGlobal(prevCurrency);
            if (entry.prevAccountType === 'بدهکار') {
                _dpBal(prevCurrency, prevAmount);
            } else if (entry.prevAccountType === 'طلبکار') {
                _dpBal(prevCurrency, -prevAmount);
            }
            var currentBal = (balMap[prevCurrency] || 0);
            var balCls = currentBal > 0 ? 'is-remaining' : 'is-settled';
            var balLabel = currentBal > 0 ? 'بدهکار' : (currentBal < 0 ? 'طلبکار' : 'تسویه');
            var balDisp = formatNumber(Math.abs(currentBal)) + ' ' + prevSymbol + ' (' + balLabel + ')';
            var _prevBadgeCls2 = _statusBadgeColorClass(currentBal > 0 ? 'is-remaining' : (currentBal < 0 ? 'is-creditor' : 'is-settled'));
            var _prevHtml = _ptxSalesCardHtml({
                icon: '<i class="fas fa-wallet"></i>',
                typeText: 'حساب قبلی',
                billNo: '—',
                timeText: ((person && person.createdAt) || '---'),
                amountText: '(' + (prevCurrency || _baseCur()) + ')' + formatNumber(prevAmount),
                balanceHtml: balDisp,
                balanceCls: balCls,
                moreHtml: '—',
                kebabHtml: '',
                badgeCls: _prevBadgeCls2
            });
            _renderedRows.push({ typeClass: 'ptx-prev', html: _prevHtml });
            return;
        }

        var tx = entry.tx;
        const totalAmount = parseFloat(tx.totalAmount || tx.amount || 0);
        const remaining = calculateTxRemaining(tx);
        const currency = tx.currency || _baseCur();

        // منطقِ اثر — دقیقاً همان منطقِ قبلیِ این تابع (بدونِ تغییر)
        let effect = 0;
        switch(tx.type) {
            case 'فروش': effect = remaining > 0 ? remaining : totalAmount; break;
            case 'خرید': effect = -(remaining > 0 ? remaining : totalAmount); break;
            case 'دریافت': effect = -totalAmount; break;
            case 'پرداخت': effect = totalAmount; break;
            case 'برگشت':
                if (tx.returnType === 'فروش') effect = -(tx.remaining != null ? parseFloat(tx.remaining) : totalAmount);
                else if (tx.returnType === 'خرید') effect = (tx.remaining != null ? parseFloat(tx.remaining) : totalAmount);
                break;
        }

        _dpBal(currency, effect);

        let currentBalance = (balMap[currency] || 0);
        let balanceCls = currentBalance > 0 ? 'is-remaining' : 'is-settled';
        let balanceLabel = currentBalance > 0 ? 'بدهکار' : (currentBalance < 0 ? 'طلبکار' : 'تسویه');
        let balanceDisplay = formatNumber(Math.abs(currentBalance)) + ' ' + _curSymGlobal(currency) + ' (' + balanceLabel + ')';
        var _txBadgeCls2 = _statusBadgeColorClass(currentBalance > 0 ? 'is-remaining' : (currentBalance < 0 ? 'is-creditor' : 'is-settled'));

        var _moreInfoCell2 = '-';
        if (tx.type === 'فروش') {
            var _recvAmt2 = (tx.cashAmounts && tx.cashAmounts[currency] != null) ? parseFloat(tx.cashAmounts[currency]) : (currency === 'USD' ? parseFloat(tx.cashUsd || 0) : (currency === 'AFN' ? parseFloat(tx.cashAfn || 0) : parseFloat(tx.cashForeign || 0)));
            _moreInfoCell2 = 'دریافت ' + formatNumber(_recvAmt2);
        } else if (tx.type === 'خرید') {
            var _payAmt2 = (tx.paidAmounts && tx.paidAmounts[currency] != null) ? parseFloat(tx.paidAmounts[currency]) : (currency === 'USD' ? parseFloat(tx.paidUsd || tx.cashUsd || 0) : (currency === 'AFN' ? parseFloat(tx.paidAfn || tx.cashAfn || 0) : parseFloat(tx.paidForeign || 0)));
            _moreInfoCell2 = 'پرداخت ' + formatNumber(_payAmt2);
        }

        var _typeText = tx.type;
        if (tx.type === 'برگشت') {
            _typeText = (tx.returnType === 'فروش') ? 'برگشت از فروش' : (tx.returnType === 'خرید' ? 'برگشت از خرید' : 'برگشت');
        }
        var _borderClass = _ptxBorderClass(tx.type, tx.returnType);

        var _pid = personId || (tx.personId || tx.customerId || tx.supplierId || '');
        var _kebab =
            '<button class="sales-card-kebab action-trigger-btn" type="button"' +
            ' onmouseenter="showPersonTxActionBar(event, ' + tx.id + ', ' + _pid + ')"' +
            ' onmouseleave="handleActionButtonMouseLeave(event)" title="عملیات">' +
            '<i class="fas fa-ellipsis-v"></i></button>';

        var _txHtml = _ptxSalesCardHtml({
            icon: _ptxTypeIcon(tx.type),
            typeText: _typeText,
            billNo: (tx.billNumber || 'ندارد'),
            timeText: (formatAfghanDateTime(tx.date, tx.createdAt) || '---'),
            amountText: '(' + (currency || _baseCur()) + ')' + formatNumber(totalAmount),
            balanceHtml: balanceDisplay,
            balanceCls: balanceCls,
            moreHtml: _moreInfoCell2,
            kebabHtml: _kebab,
            badgeCls: _txBadgeCls2
        });

        _renderedRows.push({ typeClass: _borderClass, html: _txHtml, txId: tx.id });
    });

    // درج به‌ترتیبِ جدیدترین در بالا
    _renderedRows.reverse();
    _renderedRows.forEach(function(r) {
        var row = document.createElement('tr');
        row.className = 'sales-card-row ptx-row ' + r.typeClass;
        row.innerHTML = r.html;
        row.style.cursor = 'pointer';
        (function(txId){ row.onclick = function(){ if (typeof viewTransaction === 'function') viewTransaction(txId); }; })(r.txId);
        tbody.appendChild(row);
    });
}

