// تابع اصلی برای بارگذاری آمار امروز
function loadTodayStatistics() {
    try {
        console.log('🔍 بارگذاری آمار امروز شروع شد...');
        
        // دریافت داده‌ها از دیتابیس
        const transactions = db.getTransactions();
        console.log('📊 تعداد کل تراکنش‌ها:', transactions.length);
        
        // تاریخ امروز به شمسی
        const todayShamsi = getTodayShamsi();
        console.log('📅 امروز (شمسی):', todayShamsi);
        
        // تاریخ دیروز به شمسی
        const yesterdayShamsi = getYesterdayShamsi();
        console.log('📅 دیروز (شمسی):', yesterdayShamsi);
        
        // فیلتر تراکنش‌های امروز
        const todayTransactions = transactions.filter(t => {
            const transactionDate = extractShamsiDate(t);
            return transactionDate === todayShamsi;
        });
        console.log('✅ تعداد تراکنش‌های امروز:', todayTransactions.length);
        
        // فیلتر تراکنش‌های دیروز
        const yesterdayTransactions = transactions.filter(t => {
            const transactionDate = extractShamsiDate(t);
            return transactionDate === yesterdayShamsi;
        });
        
        // محاسبه آمار
        const stats = calculateDailyStats(todayTransactions, yesterdayTransactions);
        console.log('📈 آمار محاسبه شده:', stats);
        
        // نمایش آمار
        updateStatsDisplay(stats);
        
        console.log('🎉 آمار امروز با موفقیت بارگذاری شد');
        
        // برگرداندن آمار برای دیباگ
        return stats;
        
    } catch (error) {
        console.error('❌ خطا در بارگذاری آمار امروز:', error);
        showDefaultStats();
        return null;
    }
}

// استخراج تاریخ شمسی از تراکنش
function extractShamsiDate(transaction) {
    try {
        // اولویت 1: فیلد date
        if (transaction.date && typeof transaction.date === 'string') {
            const dateStr = transaction.date.trim();
            // جدا کردن تاریخ از زمان
            const datePart = dateStr.split(' ')[0];
            // استاندارد کردن فرمت: YYYY/MM/DD
            const parts = datePart.split('/');
            if (parts.length >= 3) {
                const year = parts[0].padStart(4, '0');
                const month = parts[1].padStart(2, '0');
                const day = parts[2].padStart(2, '0');
                return `${year}/${month}/${day}`;
            }
            return datePart;
        }
        
        // اولویت 2: فیلد createdAt
        if (transaction.createdAt && typeof transaction.createdAt === 'string') {
            const dateStr = transaction.createdAt.trim();
            const datePart = dateStr.split(' ')[0];
            const parts = datePart.split('/');
            if (parts.length >= 3) {
                const year = parts[0].padStart(4, '0');
                const month = parts[1].padStart(2, '0');
                const day = parts[2].padStart(2, '0');
                return `${year}/${month}/${day}`;
            }
        }
        
        return '';
    } catch (e) {
        console.error('خطا در استخراج تاریخ:', e);
        return '';
    }
}

// دریافت تاریخ امروز به شمسی
function getTodayShamsi() {
    try {
        // روش 1: استفاده از PersianDate اگر موجود باشد
        if (typeof PersianDate !== 'undefined') {
            const today = new PersianDate();
            const formatted = today.format('YYYY/MM/DD');
            console.log('📅 امروز با PersianDate:', formatted);
            return formatted;
        }
        
        // روش 2: از تاریخ نمونه استفاده کن (از دیتای شما)
        console.log('📅 استفاده از تاریخ نمونه: 1404/10/28');
        return '1404/10/28';
        
    } catch (error) {
        console.error('خطا در دریافت تاریخ:', error);
        return '1404/10/28';
    }
}

// دریافت تاریخ دیروز به شمسی
function getYesterdayShamsi() {
    try {
        // اگر PersianDate موجود است
        if (typeof PersianDate !== 'undefined') {
            const yesterday = new PersianDate();
            yesterday.subtract(1, 'day');
            return yesterday.format('YYYY/MM/DD');
        }
        
        // محاسبه دستی: از تاریخ امروز یک روز کم کن
        const today = '1404/10/28';
        const parts = today.split('/');
        let year = parseInt(parts[0]);
        let month = parseInt(parts[1]);
        let day = parseInt(parts[2]);
        
        // کم کردن یک روز
        day--;
        if (day < 1) {
            month--;
            if (month < 1) {
                year--;
                month = 12;
            }
            // آخرین روز ماه قبل
            day = daysInShamsiMonth(year, month);
        }
        
        const yesterday = `${year}/${month.toString().padStart(2, '0')}/${day.toString().padStart(2, '0')}`;
        console.log('📅 دیروز محاسبه شده:', yesterday);
        return yesterday;
        
    } catch (error) {
        console.error('خطا در دریافت تاریخ دیروز:', error);
        return '1404/10/27';
    }
}

// تعداد روزهای یک ماه شمسی
function daysInShamsiMonth(year, month) {
    // ماه‌های 31 روزه: 1-6
    // ماه‌های 30 روزه: 7-11 (ماه 12 بستگی به سال دارد)
    if (month >= 1 && month <= 6) return 31;
    if (month >= 7 && month <= 11) return 30;
    if (month === 12) {
        // بررسی سال کبیسه
        const isLeap = isShamsiLeapYear(year);
        return isLeap ? 30 : 29;
    }
    return 30;
}

// بررسی سال کبیسه شمسی
function isShamsiLeapYear(year) {
    // الگوریتم ساده برای بررسی کبیسه
    const remainder = (year - 474) % 128;
    return remainder < 29;
}

// محاسبه آمار روزانه
function calculateDailyStats(todayTrans, yesterdayTrans) {
    let todayIncome = 0;    // عواید (فروش + دریافتی)
    let todaySales = 0;     // فروش
    let todayPurchases = 0; // خرید (مصارف)
    let todayReceipts = 0;  // دریافتی‌ها
    
    console.log('🧮 محاسبه آمار برای', todayTrans.length, 'تراکنش امروز');
    
    // محاسبه امروز
    todayTrans.forEach(t => {
        const amount = parseFloat(t.amount) || 0;
        const totalAmount = parseFloat(t.totalAmount) || 0;
        const finalAmount = totalAmount > 0 ? totalAmount : amount;
        
        console.log(`   ${t.type}: ${finalAmount}`);
        
        if (t.type === 'فروش' || t.type === 'sale') {
            todaySales += finalAmount;
            todayIncome += finalAmount;
        } 
        else if (t.type === 'خرید' || t.type === 'purchase') {
            todayPurchases += finalAmount;
        }
        else if (t.type === 'دریافت' || t.type === 'دریافتی' || t.type === 'receipt') {
            todayReceipts += finalAmount;
            todayIncome += finalAmount;
        }
        else if (t.type === 'پرداخت' || t.type === 'پرداختی' || t.type === 'payment') {
            // پرداختی‌ها جزو مصارف هستند
            todayPurchases += finalAmount;
        }
        else if (t.type === 'برگشت') {
            // اثرِ واقعیِ برگشت (هماهنگ با گزارشِ سود): برگشتِ‌فروش، فروش و درآمدِ خالصِ روز را
            // کم می‌کند؛ برگشتِ‌خرید، خرید/مصارفِ روز را. یک بار کسر می‌شود (بدونِ double-counting).
            if (t.returnType === 'فروش') { todaySales -= finalAmount; todayIncome -= finalAmount; }
            else if (t.returnType === 'خرید') { todayPurchases -= finalAmount; }
        }
    });
    
    // محاسبه دیروز
    let yesterdayIncome = 0;
    let yesterdaySales = 0;
    let yesterdayPurchases = 0;
    
    yesterdayTrans.forEach(t => {
        const amount = parseFloat(t.amount) || 0;
        const totalAmount = parseFloat(t.totalAmount) || 0;
        const finalAmount = totalAmount > 0 ? totalAmount : amount;
        
        if (t.type === 'فروش' || t.type === 'sale') {
            yesterdaySales += finalAmount;
            yesterdayIncome += finalAmount;
        } 
        else if (t.type === 'خرید' || t.type === 'purchase') {
            yesterdayPurchases += finalAmount;
        }
        else if (t.type === 'دریافت' || t.type === 'دریافتی' || t.type === 'receipt') {
            yesterdayIncome += finalAmount;
        }
        else if (t.type === 'پرداخت' || t.type === 'پرداختی' || t.type === 'payment') {
            yesterdayPurchases += finalAmount;
        }
        else if (t.type === 'برگشت') {
            if (t.returnType === 'فروش') { yesterdaySales -= finalAmount; yesterdayIncome -= finalAmount; }
            else if (t.returnType === 'خرید') { yesterdayPurchases -= finalAmount; }
        }
    });
    
    // محاسبه سود
    // اصلاحِ باگ: سودِ خالص = سودِ واقعیِ کالا (موتورِ FIFO: فروش − بهای تمام‌شده، به ارزِ
    // پایه) − مصارفاتِ امروز. نه «درآمد − خرید» (که بهای تمام‌شدهٔ کالای فروخته‌شده را کسر
    // نمی‌کرد و ارزهای مختلف را خام جمع می‌زد).
    var _fifoDS = (typeof _getFifoMaps === 'function') ? _getFifoMaps() : null;
    var _saleBaseDS = (_fifoDS && _fifoDS.saleMapBase) ? _fifoDS.saleMapBase : {};
    var _goodsProfitDS = 0;
    todayTrans.forEach(function (t) {
        if (t.type === 'فروش' || t.type === 'sale') _goodsProfitDS += (parseFloat(_saleBaseDS[t.id]) || 0);
    });
    var _expDS = 0;
    try {
        var _bDS = _baseCur();
        var _todayS = new PersianDate().format('YYYY/MM/DD');
        var _exps = (typeof db !== 'undefined' && db.getExpenses) ? (db.getExpenses() || []) : [];
        _exps.forEach(function (e) {
            var d = (e.date || e.createdAt || '').split(' ')[0];
            if (d !== _todayS) return;
            var a = parseFloat(e.amount) || 0; var c = e.currency || _bDS;
            if (a && c !== _bDS && typeof CurrencySystem !== 'undefined' && CurrencySystem.convert) {
                var cv = CurrencySystem.convert(a, c, _bDS, 'rate'); a = (cv != null) ? cv : a;
            }
            _expDS += a;
        });
    } catch (e) {}
    const todayProfit = _goodsProfitDS - _expDS;
    const yesterdayProfit = yesterdayIncome - yesterdayPurchases;
    
    // تعداد معاملات فروش امروز
    const todaySalesCount = todayTrans.filter(t => 
        t.type === 'فروش' || t.type === 'sale'
    ).length;
    
    return {
        todayIncome,
        yesterdayIncome,
        todaySales,
        yesterdaySales,
        todayPurchases,
        yesterdayPurchases,
        todayProfit,
        yesterdayProfit,
        todaySalesCount,
        todayReceipts,
        transactionCount: todayTrans.length
    };
}

// نمایش آمار در کارت‌ها
function updateStatsDisplay(stats) {
    console.log('🔄 به‌روزرسانی نمایش آمار...');
    
    // لیست تمام المان‌هایی که باید به‌روزرسانی شوند
    const elements = [
        { id: 'today-income', value: formatCurrencyAFN(stats.todayIncome) },
        { id: 'today-sales', value: formatCurrencyAFN(stats.todaySales) },
        { id: 'today-expenses', value: formatCurrencyAFN(stats.todayPurchases) },
        { id: 'today-profit', value: formatCurrencyAFN(stats.todayProfit) },
        { id: 'today-sales-count', value: `${stats.todaySalesCount} معامله` },
        { id: 'income-trend', html: getTrendHTML(calculateTrend(stats.todayIncome, stats.yesterdayIncome), 'عواید') }
    ];
    
    // به‌روزرسانی هر المان
    elements.forEach(item => {
        const element = document.getElementById(item.id);
        if (element) {
            if (item.html) {
                element.innerHTML = item.html;
            } else {
                element.textContent = item.value;
            }
            console.log(`   ✓ ${item.id}: ${item.value || item.html}`);
        } else {
            console.error(`   ✗ المان با id "${item.id}" یافت نشد!`);
        }
    });
    
    // همچنین المان‌های جایگزین را بررسی کن
    checkAlternativeElements(stats);
    
    // اگر داشبورد خلاصه موجود است، آن را هم به‌روزرسانی کن
    const summaryElement = document.getElementById('dashboard-summary');
    if (summaryElement) {
        summaryElement.textContent = `${stats.transactionCount} تراکنش امروز | سود خالص: ${formatCurrencyAFN(stats.todayProfit)}`;
    }
}

// بررسی المان‌های جایگزین (اگر IDها متفاوت باشند)
function checkAlternativeElements(stats) {
    // اگر المان‌های اصلی یافت نشدند، المان‌های کلاس‌دار را بررسی کن
    const classElements = {
        'stat-card:nth-child(1) .stat-value': formatCurrencyAFN(stats.todayProfit),
        'stat-card:nth-child(2) .stat-value': formatCurrencyAFN(stats.todayPurchases),
        'stat-card:nth-child(3) .stat-value': formatCurrencyAFN(stats.todaySales),
        'stat-card:nth-child(4) .stat-value': formatCurrencyAFN(stats.todayIncome)
    };
    
    Object.keys(classElements).forEach(selector => {
        const element = document.querySelector(selector);
        if (element) {
            element.textContent = classElements[selector];
            console.log(`   ✓ ${selector}: ${classElements[selector]}`);
        }
    });
}

// فرمت مبلغ به افغانی
function formatCurrencyAFN(amount) {
    const num = parseFloat(amount) || 0;
    var sys = (typeof getNumberSystem === 'function') ? getNumberSystem() : 'fa';
    var locale = (sys === 'en') ? 'en-US' : 'fa-IR';
    var _lbl = 'افغانی';
    try { if (typeof getCurrencyLabel === 'function') _lbl = getCurrencyLabel(null); } catch (e) {}
    return num.toLocaleString(locale) + ' ' + _lbl;
}

// محاسبه روند تغییر
function calculateTrend(today, yesterday) {
    if (yesterday === 0) {
        if (today === 0) return 0;
        return 100;
    }
    
    const change = ((today - yesterday) / Math.abs(yesterday)) * 100;
    return Math.round(change * 10) / 10;
}

// تولید HTML برای روند
function getTrendHTML(change, label) {
    const absChange = Math.abs(change);
    
    if (change > 0) {
        return `<i class="fas fa-arrow-up" style="color: #10b981;"></i> ${absChange}٪ بیشتر از دیروز`;
    } else if (change < 0) {
        return `<i class="fas fa-arrow-down" style="color: #ef4444;"></i> ${absChange}٪ کمتر از دیروز`;
    } else {
        return 'بدون تغییر نسبت به دیروز';
    }
}

// نمایش مقادیر پیش‌فرض در صورت خطا
