function loadReturns() {
    const tbody = document.querySelector('#returns-table tbody');
    if (!tbody) return;

    const transactions = (db.getTransactions() || []).filter(t => t.type === 'برگشت');
    tbody.innerHTML = '';

    if (transactions.length === 0) {
        tbody.innerHTML = '<tr><td colspan="7" style="text-align:center;padding:20px;">هیچ معامله برگشتی ثبت نشده است</td></tr>';
        return;
    }

    transactions.slice().reverse().forEach(ret => {
        const row = document.createElement('tr');
        const returnTypeLabel = ret.returnType === 'فروش' ? 'برگشت از فروش' : (ret.returnType === 'خرید' ? 'برگشت از خرید' : (ret.type || '-'));
        row.innerHTML = `
            <td>${(ret.date || ret.createdAt || '-').split(' ')[0]}</td>
            <td>${returnTypeLabel}</td>
            <td>${ret.originalBillNumber || ret.relatedBill || '-'}</td>
            <td>${ret.personName || ret.customerName || ret.supplierName || '-'}</td>
            <td>${formatCurrency(ret.totalAmount || ret.amount || 0)} ${ret.currency || ''}</td>
            <td>${ret.reason || '-'}</td>
            <td>${getActionButtons(ret.id, 'برگشت')}</td>
        `;
        tbody.appendChild(row);
    });
}
