// ====== نمایش لیست برگشتی‌ها ======
// ========================================================================
// «برگشت از فروش» — هستهٔ منطق (مرحلهٔ ۱–۳)
// ------------------------------------------------------------------------
// _saleReturnInfo(saleId): برای یک فروشِ اصلی، برای هر قلم مقدارِ فروخته‌شده،
//   قبلاً برگشت‌شده و «قابلِ برگشت» را برمی‌گرداند (مبنای اعتبارسنجی و فرم).
//   واحدها به «واحدِ همان قلمِ فروش» است (برگشت با همان واحدِ فروش ثبت می‌شود).
// ------------------------------------------------------------------------
function _saleReturnInfo(saleId) {
    try {
        var txs = (typeof db !== 'undefined' && db.getTransactions) ? (db.getTransactions() || []) : [];
        var sale = txs.find(function (t) { return t.id == saleId && t.type === 'فروش'; });
        if (!sale) return null;
        // مجموعِ مقدارِ برگشت‌شدهٔ قبلی برای هر «شمارهٔ قلمِ فروشِ اصلی»
        // (مرجعِ فروش می‌تواند سطحِ قلم origSaleId یا سطحِ سند originalSaleId باشد)
        var returnedByIdx = {};
        txs.forEach(function (t) {
            if (t.type !== 'برگشت' || t.returnType !== 'فروش') return;
            if (!Array.isArray(t.items)) return;
            t.items.forEach(function (ri, k) {
                var rs = (ri && ri.origSaleId != null) ? ri.origSaleId : t.originalSaleId;
                if (rs == null || rs != saleId) return;
                var oi = (ri && ri.origItemIndex != null) ? ri.origItemIndex : k;
                returnedByIdx[oi] = (returnedByIdx[oi] || 0) + (parseFloat(ri.quantity) || 0);
            });
        });
        var items = (sale.items || []).map(function (it, idx) {
            var sold = parseFloat(it.quantity) || 0;
            var ret = returnedByIdx[idx] || 0;
            var returnable = sold - ret; if (returnable < 0) returnable = 0;
            return {
                index: idx,
                productId: it.productId,
                productName: it.productName,
                isService: !!it.isService,
                unit: it.unit,
                price: parseFloat(it.price) || 0,
                discount: parseFloat(it.discount) || 0,
                unitType: it.unitType || 'primary',
                secondaryFactor: parseFloat(it.secondaryFactor) || 0,
                purchasePrices: (it.purchasePrices && typeof it.purchasePrices === 'object') ? it.purchasePrices : null,
                purchasePriceAFN: it.purchasePriceAFN,
                purchasePriceUSD: it.purchasePriceUSD,
                soldQty: sold,
                returnedQty: ret,
                returnableQty: returnable
            };
        });
        return { sale: sale, currency: sale.currency || _baseCur(), customerId: sale.customerId, customerName: sale.customerName, items: items };
    } catch (e) { console.error('_saleReturnInfo:', e); return null; }
}
if (typeof window !== 'undefined') window._saleReturnInfo = _saleReturnInfo;

// ------------------------------------------------------------------------
// _commitSaleReturn(payload): هستهٔ ثبتِ «برگشت از فروش» (مستقل از DOM تا آزمون‌پذیر باشد).
//   payload = {
//     originalSaleId, customerId, customerName, date, billNumber?, currency?,
//     cashboxId?, cashRefund? (مبلغِ نقدیِ بازپرداخت), notes?,
//     items: [ { origItemIndex, quantity } ]   // quantity به واحدِ همان قلمِ فروش
//   }
//   کارها: اعتبارسنجیِ «بیش از قابلِ برگشت»، ساختِ سندِ برگشت با ارجاع به فروشِ اصلی،
//   کپیِ قیمت/تخفیف/واحد و snapshotِ بهای تمام‌شده از قلمِ فروشِ اصلی، و ثبت از طریقِ
//   db.saveTransaction (که موجودی را +، و بخشِ نقدی را از حساب کم می‌کند). سودِ همان
//   بخش از فروش به‌صورت خودکار در موتورِ FIFO معکوس می‌شود؛ حسابِ مشتری (مشتق) نیز
//   با «بخشِ نسیه» اصلاح می‌گردد. خروجی: { success, error?, tx? }.
// ------------------------------------------------------------------------
function _commitSaleReturn(payload) {
    try {
        if (!payload) return { success: false, error: 'اطلاعاتِ برگشت ناقص است.' };
        var reqItems = Array.isArray(payload.items) ? payload.items : [];
        if (reqItems.length === 0) return { success: false, error: 'حداقل یک قلم برای برگشت لازم است.' };

        // کشِ اطلاعاتِ هر فروشِ اصلی (برای اعتبارسنجیِ قابلِ برگشت)
        var infoCache = {};
        function infoFor(sid) {
            if (sid == null) return null;
            if (!infoCache[sid]) infoCache[sid] = _saleReturnInfo(sid);
            return infoCache[sid];
        }

        var currency = payload.currency || null;
        var primarySaleId = null;
        var outItems = [];
        var totalAmount = 0;

        for (var i = 0; i < reqItems.length; i++) {
            var r = reqItems[i];
            if (!r) continue;
            var qty = parseFloat(r.quantity) || 0;
            if (qty <= 0) continue;
            var sid = (r.origSaleId != null) ? r.origSaleId : payload.originalSaleId;
            var info = infoFor(sid);
            if (!info) return { success: false, error: 'فروشِ اصلی یافت نشد (برای یکی از اقلام).' };
            if (primarySaleId == null) primarySaleId = sid;
            if (!currency) currency = info.currency || _baseCur();
            // هشدارِ ناسازگاریِ ارز بین فروش‌های انتخاب‌شده
            if (currency && info.currency && info.currency !== currency) {
                return { success: false, error: 'همهٔ اقلامِ برگشت باید از فروش‌هایی با ارزِ یکسان («' + currency + '») باشند.' };
            }
            var src = info.items.find(function (x) { return x.index == r.origItemIndex; });
            if (!src) return { success: false, error: 'قلمِ انتخاب‌شده در فروشِ اصلی وجود ندارد.' };
            if (src.isService) return { success: false, error: 'خدمات قابلِ برگشت نیست.' };
            if (qty > src.returnableQty + 1e-9) {
                return { success: false, error: 'مقدارِ برگشت برای «' + (src.productName || '') + '» بیش از قابلِ برگشت (' + src.returnableQty + ') است.' };
            }
            var soldQty = src.soldQty || 0;
            var lineDisc = (soldQty > 0) ? (src.discount * (qty / soldQty)) : 0;
            // قیمتِ واحدِ برگشت: اگر کاربر در فورم ویرایش کرده باشد همان (مبنای رفاند/بدهیِ شخص)،
            // وگرنه قیمتِ سندِ اصلی. بها/سود (purchasePrices) از سندِ اصلی دست‌نخورده می‌ماند تا
            // حسابداریِ FIFO/سود مطابقِ معماریِ فعلی و لنگرِ سندِ اصلی بماند.
            var _retUnit = (r.price != null && r.price !== '' && !isNaN(parseFloat(r.price))) ? parseFloat(r.price) : src.price;
            var lineTotal = qty * _retUnit - lineDisc;
            var item = {
                productId: src.productId,
                productName: src.productName,
                isService: false,
                quantity: qty,
                unit: src.unit,
                price: _retUnit,
                discount: lineDisc,
                total: lineTotal,
                unitType: src.unitType,
                secondaryFactor: src.secondaryFactor,
                origSaleId: sid,
                origItemIndex: src.index
            };
            if (src.purchasePrices) item.purchasePrices = src.purchasePrices;
            if (src.purchasePriceAFN != null) item.purchasePriceAFN = src.purchasePriceAFN;
            if (src.purchasePriceUSD != null) item.purchasePriceUSD = src.purchasePriceUSD;
            outItems.push(item);
            totalAmount += lineTotal;
        }
        if (outItems.length === 0) return { success: false, error: 'حداقل یک قلم با مقدارِ معتبر برای برگشت لازم است.' };
        if (!currency) currency = _baseCur();

        var primaryInfo = infoFor(primarySaleId);
        var sale = primaryInfo ? primaryInfo.sale : null;

        var cashRefund = parseFloat(payload.cashRefund) || 0;
        if (cashRefund < 0) cashRefund = 0;
        if (cashRefund > totalAmount) cashRefund = totalAmount;
        var creditPortion = totalAmount - cashRefund;
        var cashAmounts = {}; cashAmounts[currency] = cashRefund;

        var billNumber = payload.billNumber;
        if (!billNumber) {
            var _txs = (typeof db !== 'undefined' && db.getTransactions) ? (db.getTransactions() || []) : [];
            var _cnt = _txs.filter(function (t) { return t.type === 'برگشت'; }).length;
            billNumber = 'RET-' + String(_cnt + 1).padStart(4, '0');
        }

        var custId = (payload.customerId != null && payload.customerId !== '') ? parseInt(payload.customerId)
                    : (sale && sale.customerId != null ? sale.customerId : null);
        var custName = payload.customerName || (sale ? sale.customerName : '') || '';

        var tx = {
            type: 'برگشت',
            returnType: 'فروش',
            originalSaleId: primarySaleId,
            originalBillNumber: sale ? (sale.billNumber || '') : '',
            relatedBill: sale ? (sale.billNumber || '') : '',
            customerId: custId,
            personId: custId,
            customerName: custName,
            personName: custName,
            date: payload.date || (sale ? (sale.date || '') : ''),
            billNumber: billNumber,
            currency: currency,
            items: outItems,
            totalAmount: totalAmount,
            amount: totalAmount,
            cashAmounts: cashAmounts,
            remaining: creditPortion,
            cashboxId: (payload.cashboxId != null && payload.cashboxId !== '') ? parseInt(payload.cashboxId) : null,
            rateUsed: (sale && sale.rateUsed != null) ? sale.rateUsed : (typeof _dayRateFor === 'function' ? _dayRateFor(currency) : null),
            baseCurrency: (typeof CurrencySystem !== 'undefined' && CurrencySystem.getBaseCode) ? CurrencySystem.getBaseCode() : 'AFN',
            reason: payload.reason || '',
            notes: payload.notes || '',
            status: 'تایید شده',
            createdAt: new Date().toISOString()
        };

        var result = db.saveTransaction(tx);
        if (!result || result.success === false) {
            return { success: false, error: (result && result.error) || 'خطا در ثبتِ برگشت.' };
        }
        var saved = result.data || tx;
        if (typeof _logCashboxTransaction === 'function' && saved.cashboxId && cashRefund > 0) {
            try {
                _logCashboxTransaction(parseInt(saved.cashboxId), {
                    type: 'return', amount: -cashRefund, currency: currency,
                    datetime: tx.date, notes: tx.notes,
                    description: 'برگشت از فروش — بل ' + billNumber + (tx.customerName ? ' — ' + tx.customerName : '')
                });
            } catch (e) {}
        }
        if (typeof addChangelog === 'function') addChangelog('ثبت', 'برگشت', saved, 'ثبتِ برگشت از فروش — بل ' + billNumber);
        // بازمحاسبهٔ قطعیِ همهٔ مشتقات (موجودی/FIFO/سود/حساب) از دادهٔ خام — تا اثرِ برگشت
        // فوری و دقیق در سراسرِ سیستم بنشیند (idempotent؛ منطقِ محاسباتیِ جدیدی ساخته نمی‌شود).
        if (typeof rebuildAllDerivedData === 'function') { try { rebuildAllDerivedData(); } catch (e) {} }
        try { window.dispatchEvent(new CustomEvent('jouya-data-change', { detail: { reason: 'return-sale' } })); } catch (e) {}
        if (typeof loadProductsList === 'function') { try { loadProductsList(); } catch (e) {} }
        if (typeof loadDashboard === 'function') { try { loadDashboard(); } catch (e) {} }
        if (typeof refreshOpenReport === 'function') { try { refreshOpenReport(); } catch (e) {} }
        return { success: true, tx: saved };
    } catch (e) {
        console.error('_commitSaleReturn:', e);
        return { success: false, error: 'خطا در ثبتِ برگشت: ' + (e && e.message ? e.message : e) };
    }
}
if (typeof window !== 'undefined') window._commitSaleReturn = _commitSaleReturn;

// ========================================================================
// «برگشت از خرید» — هستهٔ منطق (متقارنِ برگشت از فروش، با منطقِ خرید)
// ------------------------------------------------------------------------
function _purchaseReturnInfo(purchaseId) {
    try {
        var txs = (typeof db !== 'undefined' && db.getTransactions) ? (db.getTransactions() || []) : [];
        var pur = txs.find(function (t) { return t.id == purchaseId && t.type === 'خرید'; });
        if (!pur) return null;
        var returnedByIdx = {};
        txs.forEach(function (t) {
            if (t.type !== 'برگشت' || t.returnType !== 'خرید' || !Array.isArray(t.items)) return;
            t.items.forEach(function (ri, k) {
                var rs = (ri && ri.origPurchaseId != null) ? ri.origPurchaseId : t.originalPurchaseId;
                if (rs == null || rs != purchaseId) return;
                var oi = (ri && ri.origItemIndex != null) ? ri.origItemIndex : k;
                returnedByIdx[oi] = (returnedByIdx[oi] || 0) + (parseFloat(ri.quantity) || 0);
            });
        });
        var items = (pur.items || []).map(function (it, idx) {
            var bought = parseFloat(it.quantity) || 0;
            var ret = returnedByIdx[idx] || 0;
            var returnable = bought - ret; if (returnable < 0) returnable = 0;
            return {
                index: idx, productId: it.productId, productName: it.productName, isService: !!it.isService,
                unit: it.unit, price: parseFloat(it.price) || 0, discount: parseFloat(it.discount) || 0,
                unitType: it.unitType || 'primary', secondaryFactor: parseFloat(it.secondaryFactor) || 0,
                purchasePrices: (it.purchasePrices && typeof it.purchasePrices === 'object') ? it.purchasePrices : null,
                purchasePriceAFN: it.purchasePriceAFN, purchasePriceUSD: it.purchasePriceUSD,
                soldQty: bought, returnedQty: ret, returnableQty: returnable
            };
        });
        return { purchase: pur, sale: pur, currency: pur.currency || _baseCur(), supplierId: pur.supplierId, supplierName: pur.supplierName, items: items };
    } catch (e) { console.error('_purchaseReturnInfo:', e); return null; }
}
if (typeof window !== 'undefined') window._purchaseReturnInfo = _purchaseReturnInfo;

function _commitPurchaseReturn(payload) {
    try {
        if (!payload) return { success: false, error: 'اطلاعاتِ برگشت ناقص است.' };
        var reqItems = Array.isArray(payload.items) ? payload.items : [];
        if (reqItems.length === 0) return { success: false, error: 'حداقل یک قلم برای برگشت لازم است.' };
        var infoCache = {};
        function infoFor(pid) { if (pid == null) return null; if (!infoCache[pid]) infoCache[pid] = _purchaseReturnInfo(pid); return infoCache[pid]; }

        var currency = payload.currency || null;
        var primaryId = null, outItems = [], totalAmount = 0;
        for (var i = 0; i < reqItems.length; i++) {
            var r = reqItems[i]; if (!r) continue;
            var qty = parseFloat(r.quantity) || 0; if (qty <= 0) continue;
            var pid = (r.origPurchaseId != null) ? r.origPurchaseId : payload.originalPurchaseId;
            var info = infoFor(pid);
            if (!info) return { success: false, error: 'خریدِ اصلی یافت نشد (برای یکی از اقلام).' };
            if (primaryId == null) primaryId = pid;
            if (!currency) currency = info.currency || _baseCur();
            if (currency && info.currency && info.currency !== currency) return { success: false, error: 'همهٔ اقلامِ برگشت باید از خریدهایی با ارزِ یکسان («' + currency + '») باشند.' };
            var src = info.items.find(function (x) { return x.index == r.origItemIndex; });
            if (!src) return { success: false, error: 'قلمِ انتخاب‌شده در خریدِ اصلی وجود ندارد.' };
            if (src.isService) return { success: false, error: 'خدمات قابلِ برگشت نیست.' };
            if (qty > src.returnableQty + 1e-9) return { success: false, error: 'مقدارِ برگشت برای «' + (src.productName || '') + '» بیش از قابلِ برگشت (' + src.returnableQty + ') است.' };
            var boughtQty = src.soldQty || 0;
            var lineDisc = (boughtQty > 0) ? (src.discount * (qty / boughtQty)) : 0;
            var _retUnitP = (r.price != null && r.price !== '' && !isNaN(parseFloat(r.price))) ? parseFloat(r.price) : src.price;
            var lineTotal = qty * _retUnitP - lineDisc;
            var item = {
                productId: src.productId, productName: src.productName, isService: false,
                quantity: qty, unit: src.unit, price: _retUnitP, discount: lineDisc, total: lineTotal,
                unitType: src.unitType, secondaryFactor: src.secondaryFactor,
                origPurchaseId: pid, origItemIndex: src.index
            };
            if (src.purchasePrices) item.purchasePrices = src.purchasePrices;
            if (src.purchasePriceAFN != null) item.purchasePriceAFN = src.purchasePriceAFN;
            if (src.purchasePriceUSD != null) item.purchasePriceUSD = src.purchasePriceUSD;
            outItems.push(item); totalAmount += lineTotal;
        }
        if (outItems.length === 0) return { success: false, error: 'حداقل یک قلم با مقدارِ معتبر برای برگشت لازم است.' };
        if (!currency) currency = _baseCur();

        var pInfo = infoFor(primaryId);
        var pur = pInfo ? pInfo.purchase : null;
        var cashBack = parseFloat(payload.cashRefund) || 0;   // نقدی که از فروشنده پس می‌گیریم
        if (cashBack < 0) cashBack = 0; if (cashBack > totalAmount) cashBack = totalAmount;
        var creditPortion = totalAmount - cashBack;
        var cashAmounts = {}; cashAmounts[currency] = cashBack;

        var billNumber = payload.billNumber;
        if (!billNumber) {
            var _txs = (typeof db !== 'undefined' && db.getTransactions) ? (db.getTransactions() || []) : [];
            var _cnt = _txs.filter(function (t) { return t.type === 'برگشت'; }).length;
            billNumber = 'RETP-' + String(_cnt + 1).padStart(4, '0');
        }
        var supId = (payload.customerId != null && payload.customerId !== '') ? parseInt(payload.customerId) : (pur && pur.supplierId != null ? pur.supplierId : (pur && pur.personId != null ? pur.personId : null));
        var supName = payload.customerName || (pur ? (pur.supplierName || pur.personName) : '') || '';

        var tx = {
            type: 'برگشت', returnType: 'خرید',
            originalPurchaseId: primaryId,
            originalBillNumber: pur ? (pur.billNumber || '') : '',
            relatedBill: pur ? (pur.billNumber || '') : '',
            supplierId: supId, personId: supId,
            supplierName: supName, personName: supName, customerName: supName,
            date: payload.date || (pur ? (pur.date || '') : ''),
            billNumber: billNumber, currency: currency,
            items: outItems, totalAmount: totalAmount, amount: totalAmount,
            cashAmounts: cashAmounts, remaining: creditPortion,
            cashboxId: (payload.cashboxId != null && payload.cashboxId !== '') ? parseInt(payload.cashboxId) : null,
            rateUsed: (pur && pur.rateUsed != null) ? pur.rateUsed : (typeof _dayRateFor === 'function' ? _dayRateFor(currency) : null),
            baseCurrency: (typeof CurrencySystem !== 'undefined' && CurrencySystem.getBaseCode) ? CurrencySystem.getBaseCode() : 'AFN',
            reason: payload.reason || '', notes: payload.notes || '',
            status: 'تایید شده', createdAt: new Date().toISOString()
        };

        var result = db.saveTransaction(tx);
        if (!result || result.success === false) return { success: false, error: (result && result.error) || 'خطا در ثبتِ برگشت.' };
        var saved = result.data || tx;
        if (typeof _logCashboxTransaction === 'function' && saved.cashboxId && cashBack > 0) {
            try { _logCashboxTransaction(parseInt(saved.cashboxId), { type: 'return', amount: cashBack, currency: currency, datetime: tx.date, notes: tx.notes, description: 'برگشت از خرید — بل ' + billNumber + (supName ? ' — ' + supName : '') }); } catch (e) {}
        }
        if (typeof addChangelog === 'function') addChangelog('ثبت', 'برگشت', saved, 'ثبتِ برگشت از خرید — بل ' + billNumber);
        if (typeof rebuildAllDerivedData === 'function') { try { rebuildAllDerivedData(); } catch (e) {} }
        try { window.dispatchEvent(new CustomEvent('jouya-data-change', { detail: { reason: 'return-purchase' } })); } catch (e) {}
        if (typeof loadProductsList === 'function') { try { loadProductsList(); } catch (e) {} }
        if (typeof loadDashboard === 'function') { try { loadDashboard(); } catch (e) {} }
        if (typeof refreshOpenReport === 'function') { try { refreshOpenReport(); } catch (e) {} }
        return { success: true, tx: saved };
    } catch (e) {
        console.error('_commitPurchaseReturn:', e);
        return { success: false, error: 'خطا در ثبتِ برگشت: ' + (e && e.message ? e.message : e) };
    }
}
if (typeof window !== 'undefined') window._commitPurchaseReturn = _commitPurchaseReturn;


// ========================================================================
// «برگشت از فروش» — رابط کاربری (مرحلهٔ ۴–۵)
// فورم هم‌سبکِ «فروش فوری»: انتخاب خریدار/ارز، جدولِ اجناس با «قابلِ برگشت»،
// دکمهٔ «لیست معاملات» (انتخابِ چند فروشِ خریدار و افزودنِ اقلام‌شان)، پرداختی/حساب/
// باقی‌مانده، ثبت (→ _commitSaleReturn) و چاپِ بلِ برگشت.
// ========================================================================
var _srReturnCtx = null;

function showSaleReturnForm(customerId) {
    try {
        // مبدأِ بازگشت = سکشنِ فعالِ فعلی (نه همیشه داشبورد). سکشن‌های خودِ فرم/پیکر
        // مبدأِ معتبر نیستند؛ در آن حالت به داشبورد برمی‌گردیم.
        var _act = document.querySelector('.section.active');
        var _oid = _act ? _act.id : 'dashboard';
        if (!_oid || _oid === 'sale-return-form' || _oid === 'purchase-return-form' || _oid === 'products-list' || _oid === 'person-transactions-list') _oid = 'dashboard';
        _setFormReturn && _setFormReturn({ section: _oid });
    } catch (e) {}
    showSection('sale-return-form');
    // ارز
    if (typeof _populateCurrencySelect === 'function') _populateCurrencySelect('sr-currency', _baseCur());
    // خریدار
    var cs = document.getElementById('sr-customer-search'); if (cs) cs.value = '';
    var ch = document.getElementById('sr-customer'); if (ch) ch.value = '';
    if (customerId != null) {
        var _p = (db.getPersons() || []).find(function (x) { return x.id == customerId; });
        if (_p) { if (ch) ch.value = _p.id; if (cs) cs.value = _p.name; }
    }
    // تاریخ + بل نمبر
    var d = document.getElementById('sr-date'); if (d) d.value = (typeof _nowJalaliDateTime === 'function') ? _nowJalaliDateTime() : '';
    var bn = document.getElementById('sr-bill-number');
    if (bn) {
        var _txs = db.getTransactions() || [];
        var _cnt = _txs.filter(function (t) { return t.type === 'برگشت'; }).length;
        bn.value = 'RET-' + String(_cnt + 1).padStart(4, '0');
    }
    // اقلام + مبالغ
    var body = document.getElementById('sr-items-body'); if (body) body.innerHTML = '';
    var cr = document.getElementById('sr-cash-refund'); if (cr) cr.value = '';
    var nt = document.getElementById('sr-notes'); if (nt) nt.value = '';
    loadCashboxesForSaleReturn();
    onSaleReturnCurrencyChange();
    srRecalc();
}
if (typeof window !== 'undefined') window.showSaleReturnForm = showSaleReturnForm;

function goBackFromSaleReturn() {
    if (typeof _consumeFormReturn === 'function' && _consumeFormReturn()) return;
    showSection('dashboard');
}
if (typeof window !== 'undefined') window.goBackFromSaleReturn = goBackFromSaleReturn;

function searchSaleReturnCustomer(inputElement) {
    var query = (inputElement.value || '').toLowerCase();
    var listContainer = document.getElementById('sr-customer-results');
    var hiddenInput = document.getElementById('sr-customer');
    if (query === '') { showAllPersonsForField(inputElement, 'sr-customer-results', 'sr-customer', 'مشتری'); return; }
    var persons = db.getPersons();
    var filtered = persons.filter(function (p) {
        return p.category === 'مشتری' && ((p.name && p.name.toLowerCase().includes(query)) || (p.phone && p.phone.includes(query)));
    });
    renderSearchResults(filtered, listContainer, inputElement, hiddenInput);
}
if (typeof window !== 'undefined') window.searchSaleReturnCustomer = searchSaleReturnCustomer;

function loadCashboxesForSaleReturn() {
    var sel = document.getElementById('sr-cashbox');
    if (!sel) return;
    var boxes = db.getCashboxes() || [];
    sel.innerHTML = '<option value="">حساب</option>';
    boxes.forEach(function (cb) {
        var o = document.createElement('option');
        o.value = cb.id;
        o.textContent = cb.name + (cb.isDefault ? ' ★' : '');
        sel.appendChild(o);
    });
    var curEl = document.getElementById('sr-currency');
    var cur = curEl ? curEl.value : _baseCur();
    if (typeof getDefaultCashboxIdForCurrency === 'function') {
        var defId = getDefaultCashboxIdForCurrency(cur);
        if (defId) sel.value = String(defId);
    }
}

function onSaleReturnCurrencyChange() {
    var curEl = document.getElementById('sr-currency');
    var cur = curEl ? curEl.value : _baseCur();
    var lbl = document.getElementById('sr-total-currency'); if (lbl) lbl.textContent = cur;
    loadCashboxesForSaleReturn();
    srRecalc();
}
if (typeof window !== 'undefined') window.onSaleReturnCurrencyChange = onSaleReturnCurrencyChange;

// افزودنِ یک ردیفِ برگشت. data: { productId, productName, unit, price, discount,
//   returnable, origSaleId?, origItemIndex?, unitType?, secondaryFactor?, linked }
function srAddReturnRow(data) {
    var body = document.getElementById('sr-items-body');
    if (!body) return null;
    data = data || {};
    var tr = document.createElement('tr');
    tr.className = 'sr-item-row';
    tr.dataset.productId = (data.productId != null ? data.productId : '');
    tr.dataset.origSaleId = (data.origSaleId != null ? data.origSaleId : '');
    tr.dataset.origItemIndex = (data.origItemIndex != null ? data.origItemIndex : '');
    tr.dataset.returnable = (data.returnable != null ? data.returnable : '');
    tr.dataset.unitType = data.unitType || 'primary';
    tr.dataset.secondaryFactor = (data.secondaryFactor != null ? data.secondaryFactor : 0);
    tr.dataset.price = (data.price != null ? data.price : 0);
    tr.dataset.discountFull = (data.discount != null ? data.discount : 0);
    tr.dataset.soldQty = (data.soldQty != null ? data.soldQty : (data.returnable != null ? data.returnable : 0));
    var num = body.querySelectorAll('.sr-item-row').length + 1;
    var linked = (data.origSaleId != null && data.origSaleId !== '') || !!data.lockName;
    var qtyInit = (data.quantity != null) ? data.quantity : (data.returnable != null ? data.returnable : 1);
    var nameCell = linked
        ? '<span class="sr-item-name">' + (data.productName || '') + '</span>'
        : '<div class="product-search-wrapper" style="position:relative;">'
            + '<input type="text" class="sr-product-search form-control" placeholder="نام جنس..." autocomplete="off" onkeyup="srProductSearch(this)">'
            + '<div class="sr-product-results product-search-results"></div></div>';
    tr.innerHTML =
        '<td style="text-align:center;">' + num + '</td>' +
        '<td>' + nameCell + '</td>' +
        '<td><input type="number" class="sr-qty bill-cell-input" value="' + qtyInit + '" min="0" step="any" oninput="srUpdateRow(this)" onchange="srUpdateRow(this)" style="width:100%;"></td>' +
        '<td><span class="sr-unit">' + (data.unit || 'عدد') + '</span></td>' +
        '<td><input type="number" class="sr-price bill-cell-input" step="0.01" value="' + (data.price != null ? data.price : '') + '" oninput="srUpdateRow(this)" onchange="srUpdateRow(this)" style="width:100%;"></td>' +
        '<td><input type="number" class="sr-disc bill-cell-input" step="0.01" value="' + (data.discount != null ? data.discount : 0) + '" readonly style="width:100%;"></td>' +
        '<td style="text-align:center;"><span class="sr-returnable">' + (data.returnable != null ? formatNumber(data.returnable) : '—') + '</span></td>' +
        '<td><span class="sr-total">۰</span></td>' +
        '<td><button type="button" class="btn-icon btn-danger" onclick="srRemoveRow(this)"><i class="fas fa-trash"></i></button></td>';
    body.appendChild(tr);
    srUpdateRowByTr(tr);
    return tr;
}

function srRemoveRow(btn) {
    var tr = btn.closest('.sr-item-row');
    if (tr) tr.remove();
    // شماره‌گذاری مجدد
    var rows = document.querySelectorAll('#sr-items-body .sr-item-row');
    rows.forEach(function (r, i) { var c = r.querySelector('td'); if (c) c.textContent = (i + 1); });
    srRecalc();
}
if (typeof window !== 'undefined') window.srRemoveRow = srRemoveRow;

function srUpdateRow(input) { srUpdateRowByTr(input.closest('.sr-item-row')); }
if (typeof window !== 'undefined') window.srUpdateRow = srUpdateRow;

function srUpdateRowByTr(tr) {
    if (!tr) return;
    var qEl = tr.querySelector('.sr-qty');
    var pEl = tr.querySelector('.sr-price');
    var dEl = tr.querySelector('.sr-disc');
    var qty = parseFloat(qEl ? qEl.value : 0) || 0;
    var returnable = parseFloat(tr.dataset.returnable);
    // محدودسازی به «قابلِ برگشت» (فقط برای ردیف‌های مرتبط با یک فروشِ مشخص)
    if (!isNaN(returnable) && tr.dataset.origSaleId && qty > returnable) {
        qty = returnable; if (qEl) qEl.value = returnable;
        if (typeof showToast === 'function') showToast('بیش از قابلِ برگشت نمی‌شود', 'warning');
    }
    var price = parseFloat(pEl ? pEl.value : 0) || 0;
    // تخفیفِ متناسب با مقدارِ برگشت (سهمِ همین بخش از تخفیفِ قلمِ اصلی)
    var soldQty = parseFloat(tr.dataset.soldQty) || 0;
    var fullDisc = parseFloat(tr.dataset.discountFull) || 0;
    var lineDisc = (soldQty > 0) ? (fullDisc * (qty / soldQty)) : 0;
    if (dEl) dEl.value = _srRound(lineDisc);
    var total = qty * price - lineDisc;
    var tEl = tr.querySelector('.sr-total'); if (tEl) tEl.textContent = formatNumber(_srRound(total));
    srRecalc();
}

function _srRound(v) {
    if (typeof CurrencySystem !== 'undefined' && CurrencySystem.round) return CurrencySystem.round(v);
    return Math.round((parseFloat(v) || 0) * 100) / 100;
}

function srRecalc() {
    var rows = document.querySelectorAll('#sr-items-body .sr-item-row');
    var sub = 0;
    rows.forEach(function (tr) {
        var qty = parseFloat(tr.querySelector('.sr-qty') ? tr.querySelector('.sr-qty').value : 0) || 0;
        var price = parseFloat(tr.querySelector('.sr-price') ? tr.querySelector('.sr-price').value : 0) || 0;
        var disc = parseFloat(tr.querySelector('.sr-disc') ? tr.querySelector('.sr-disc').value : 0) || 0;
        sub += (qty * price - disc);
    });
    sub = _srRound(sub);
    var subEl = document.getElementById('sr-subtotal'); if (subEl) subEl.textContent = formatNumber(sub);
    var gEl = document.getElementById('sr-grand-total'); if (gEl) gEl.textContent = formatNumber(sub);
    calculateSaleReturnRemaining();
}
if (typeof window !== 'undefined') window.srRecalc = srRecalc;

function calculateSaleReturnRemaining() {
    var grand = _srParse(document.getElementById('sr-grand-total'));
    var refund = parseFloat((document.getElementById('sr-cash-refund') || {}).value) || 0;
    if (refund < 0) refund = 0;
    if (refund > grand) { refund = grand; var cr = document.getElementById('sr-cash-refund'); if (cr && cr.value !== '') cr.value = grand; }
    var remaining = _srRound(grand - refund);
    var disp = document.getElementById('sr-remaining-display'); if (disp) disp.textContent = formatNumber(remaining);
}
if (typeof window !== 'undefined') window.calculateSaleReturnRemaining = calculateSaleReturnRemaining;

function _srParse(el) { if (!el) return 0; return parseFloat(String(el.textContent).replace(/[^\d.-]/g, '')) || 0; }

function srFullRefund() {
    var grand = _srParse(document.getElementById('sr-grand-total'));
    var cr = document.getElementById('sr-cash-refund'); if (cr) cr.value = grand;
    calculateSaleReturnRemaining();
}
if (typeof window !== 'undefined') window.srFullRefund = srFullRefund;

// ---- جستجوی جنس در ردیف (ردیف‌های دستی از گدام) ----
function srProductSearch(input) {
    var wrap = input.closest('.product-search-wrapper');
    var box = wrap ? wrap.querySelector('.sr-product-results') : null;
    if (!box) return;
    var q = (input.value || '').toLowerCase();
    if (!q) { box.style.display = 'none'; box.innerHTML = ''; return; }
    var prods = (db.getProducts() || []).filter(function (p) { return p.name && p.name.toLowerCase().includes(q); }).slice(0, 12);
    if (!prods.length) { box.innerHTML = '<div class="result-item" style="color:#94a3b8;">یافت نشد</div>'; box.style.display = 'block'; return; }
    box.innerHTML = prods.map(function (p) {
        return '<div class="result-item" onclick="srSelectRowProduct(this,' + p.id + ')">' + p.name + '</div>';
    }).join('');
    box.style.display = 'block';
}
if (typeof window !== 'undefined') window.srProductSearch = srProductSearch;

function srSelectRowProduct(el, productId) {
    var tr = el.closest('.sr-item-row');
    if (!tr) return;
    var custId = (document.getElementById('sr-customer') || {}).value;
    if (!custId) { showMessage('خطا', 'ابتدا خریدار را انتخاب کنید.'); return; }
    // مجموعِ قابلِ برگشتِ این جنس در فروش‌های همین خریدار + قیمتِ اولین فروشِ قابلِ برگشت
    var agg = _srCustomerReturnableForProduct(custId, productId);
    if (!agg || agg.returnable <= 0) { showMessage('اطلاع', 'برای این خریدار موردِ قابلِ برگشتی از این جنس یافت نشد.'); return; }
    var prod = (db.getProducts() || []).find(function (p) { return p.id == productId; });
    tr.dataset.productId = productId;
    tr.dataset.returnable = agg.returnable;
    tr.dataset.price = agg.price;
    tr.dataset.soldQty = agg.returnable;   // برای ردیف دستی، تخفیفِ متناسب صفر می‌ماند مگر لینک شود
    tr.dataset.discountFull = 0;
    tr.dataset.origSaleId = '';            // دستی: در زمانِ ثبت به‌صورتِ FIFO به فروش‌ها نسبت داده می‌شود
    tr.dataset.origItemIndex = '';
    tr.dataset.unitType = 'primary';
    // جایگزینیِ سلولِ نام با نامِ جنس (قفل)
    var nameTd = tr.children[1];
    if (nameTd) nameTd.innerHTML = '<span class="sr-item-name">' + (prod ? prod.name : (agg.productName || '')) + '</span>';
    var unitEl = tr.querySelector('.sr-unit'); if (unitEl) unitEl.textContent = (prod && prod.unit) ? prod.unit : 'عدد';
    var pEl = tr.querySelector('.sr-price'); if (pEl) { pEl.value = agg.price; pEl.setAttribute('readonly', 'readonly'); }
    var retEl = tr.querySelector('.sr-returnable'); if (retEl) retEl.textContent = formatNumber(agg.returnable);
    var qEl = tr.querySelector('.sr-qty'); if (qEl && (!qEl.value || parseFloat(qEl.value) <= 0)) qEl.value = 1;
    srUpdateRowByTr(tr);
}
if (typeof window !== 'undefined') window.srSelectRowProduct = srSelectRowProduct;

// مجموعِ قابلِ برگشتِ یک جنس در همهٔ فروش‌های یک خریدار + قیمتِ نمونه (اولین قلمِ قابلِ برگشت)
function _srCustomerReturnableForProduct(customerId, productId) {
    var txs = db.getTransactions() || [];
    var sales = txs.filter(function (t) { return t.type === 'فروش' && t.customerId == customerId; })
                   .sort(function (a, b) { return (a.createdAt || '') < (b.createdAt || '') ? -1 : 1; });
    var total = 0, price = 0, name = '', found = false;
    sales.forEach(function (s) {
        var info = _saleReturnInfo(s.id);
        if (!info) return;
        info.items.forEach(function (it) {
            if (it.isService || it.productId != productId) return;
            if (it.returnableQty > 0) {
                total += it.returnableQty;
                if (!found) { price = it.price; name = it.productName; found = true; }
            }
        });
    });
    return { returnable: total, price: price, productName: name };
}

// ========================================================================
// انتخاب‌گرها برای فورم برگشت — «لیست معاملات» و «گدام» دقیقاً همان لیست‌های اصلی
// (لیست معاملاتِ شخص و لیستِ اجناس) را در «حالتِ انتخاب» باز می‌کنند.
// ========================================================================
var _srTxPick = null;       // { kind:'sale'|'purchase', returnType, section, customerId, selected:{} }
var _srProductPick = null;  // { kind:'sale'|'purchase', section }

// ---------- گدام: بازکردنِ لیستِ واقعیِ اجناس در حالتِ انتخاب ----------
function srPickProductFromWarehouse() {
    var custId = (document.getElementById('sr-customer') || {}).value;
    if (!custId) { showMessage('خطا', 'ابتدا خریدار را انتخاب کنید.'); return; }
    _srOpenProductPicker({ kind: 'sale', section: 'sale-return-form' });
}
if (typeof window !== 'undefined') window.srPickProductFromWarehouse = srPickProductFromWarehouse;

function _srOpenProductPicker(ctx) {
    _srProductPick = ctx;
    _productPickerReturnSection = ctx.section;
    _productPickerInput = { __srReturn: true };   // فعال‌سازیِ حالتِ انتخاب در لیستِ اجناس
    _productPickerIsPurchase = false;
    showSection('products-list');
    if (typeof loadProductsList === 'function') loadProductsList();
    setTimeout(function () { if (typeof _setupPickerBackButton === 'function') _setupPickerBackButton('products-list', ctx.section); }, 0);
}

// درجِ جنسِ انتخاب‌شده از لیستِ اجناس در فورمِ برگشت (ردیفِ دستی؛ در زمانِ ثبت به فروش‌ها/خریدها نسبت داده می‌شود)
function _srInsertProductFromPicker(product) {
    var ctx = _srProductPick; _srProductPick = null;
    if (!ctx || !product) return;
    if (ctx.kind === 'purchase') { if (typeof _prInsertProductFromPicker === 'function') _prInsertProductFromPicker(product); return; }
    var custId = (document.getElementById('sr-customer') || {}).value;
    var agg = _srCustomerReturnableForProduct(custId, product.id);
    if (!agg || agg.returnable <= 0) { showMessage('اطلاع', 'برای این خریدار موردِ قابلِ برگشتی از این جنس یافت نشد.'); return; }
    srAddReturnRow({
        productId: product.id, productName: product.name || agg.productName, unit: product.unit || 'عدد',
        price: agg.price, discount: 0, returnable: agg.returnable, soldQty: agg.returnable,
        quantity: 1, lockName: true
    });
    srRecalc();
}
if (typeof window !== 'undefined') window._srInsertProductFromPicker = _srInsertProductFromPicker;

// ---------- لیست معاملات: بازکردنِ لیستِ واقعیِ معاملاتِ شخص در حالتِ انتخاب ----------
function openSaleReturnTxPicker() {
    var custId = (document.getElementById('sr-customer') || {}).value;
    if (!custId) { showMessage('خطا', 'ابتدا خریدار را انتخاب کنید.'); return; }
    _srOpenTxPicker({ kind: 'sale', returnType: 'فروش', section: 'sale-return-form', customerId: custId, selected: {} });
}
if (typeof window !== 'undefined') window.openSaleReturnTxPicker = openSaleReturnTxPicker;

function _srOpenTxPicker(ctx) {
    _srTxPick = ctx;
    if (typeof showPersonTransactions === 'function') showPersonTransactions(ctx.customerId);
    setTimeout(function () { if (_srTxPick) _srDecoratePersonTxPick(ctx.customerId); }, 60);
}

// اطلاعاتِ «قابلِ برگشت» برای یک معامله، بسته به نوعِ برگشت
function _srReturnInfoForTx(tx) {
    if (!_srTxPick) return null;
    if (_srTxPick.returnType === 'فروش') return (tx.type === 'فروش') ? _saleReturnInfo(tx.id) : null;
    if (_srTxPick.returnType === 'خرید') return (tx.type === 'خرید' && typeof _purchaseReturnInfo === 'function') ? _purchaseReturnInfo(tx.id) : null;
    return null;
}

// آراستنِ ردیف‌های لیستِ معاملاتِ شخص برای انتخاب (بدونِ تغییرِ ظاهرِ کارت‌ها)
function _srDecoratePersonTxPick(personId) {
    var sec = document.getElementById('person-transactions-list');
    if (!sec) return;
    // دکمهٔ برگشتِ بخش → لغوِ انتخاب و برگشت به فورم
    var back = sec.querySelector('.btn-back-header');
    if (back) { back.setAttribute('onclick', '_srCancelTxPick()'); back.title = 'برگشت به فورمِ برگشت'; }
    // عنوان راهنما
    var titleEl = sec.querySelector('.section-title-in-filter');
    var rows = sec.querySelectorAll('#person-transactions-table tbody tr[data-tx-id]');
    var allTx = db.getTransactions ? db.getTransactions() : [];
    rows.forEach(function (row) {
        var txId = row.dataset.txId;
        var tx = allTx.find(function (t) { return t.id == txId; });
        if (!tx) return;
        var info = _srReturnInfoForTx(tx);
        var selectable = !!(info && info.items && info.items.some(function (it) { return !it.isService && it.returnableQty > 0; }));
        // پاک‌سازیِ حالتِ قبلی
        row.classList.remove('sr-pick-selectable', 'sr-pick-selected', 'sr-pick-disabled');
        var card = row.querySelector('.sales-card');
        var oldChk = row.querySelector('.sr-pick-check'); if (oldChk) oldChk.remove();
        if (selectable) {
            row.classList.add('sr-pick-selectable');
            if (_srTxPick.selected[txId]) row.classList.add('sr-pick-selected');
            // نشانِ انتخاب
            if (card) {
                var chk = document.createElement('span');
                chk.className = 'sr-pick-check';
                chk.style.cssText = 'position:absolute;top:8px;inset-inline-start:8px;width:22px;height:22px;border-radius:50%;border:2px solid #1e3a5f;display:flex;align-items:center;justify-content:center;background:' + (_srTxPick.selected[txId] ? '#1e3a5f' : '#fff') + ';color:#fff;font-size:12px;z-index:5;';
                chk.innerHTML = _srTxPick.selected[txId] ? '<i class="fas fa-check"></i>' : '';
                card.style.position = 'relative';
                card.appendChild(chk);
            }
            row.onclick = function (e) {
                if (e && e.target && e.target.closest && e.target.closest('.sales-card-kebab')) return;
                _srToggleTxPick(txId);
            };
            row.style.cursor = 'pointer';
        } else {
            row.classList.add('sr-pick-disabled');
            row.style.opacity = '0.45';
            row.onclick = function () { if (typeof showToast === 'function') showToast('این معامله قابلِ برگشت نیست', 'info'); };
        }
    });
    _srRenderTxPickBar();
}
if (typeof window !== 'undefined') window._srDecoratePersonTxPick = _srDecoratePersonTxPick;

function _srToggleTxPick(txId) {
    if (!_srTxPick) return;
    if (_srTxPick.selected[txId]) delete _srTxPick.selected[txId];
    else _srTxPick.selected[txId] = true;
    // به‌روزرسانیِ ظاهرِ همان ردیف
    var row = document.querySelector('#person-transactions-table tbody tr[data-tx-id="' + txId + '"]');
    if (row) {
        var card = row.querySelector('.sales-card');
        var chk = row.querySelector('.sr-pick-check');
        var on = !!_srTxPick.selected[txId];
        row.classList.toggle('sr-pick-selected', on);
        if (chk) { chk.style.background = on ? '#1e3a5f' : '#fff'; chk.innerHTML = on ? '<i class="fas fa-check"></i>' : ''; }
    }
    _srRenderTxPickBar();
}

function _srRenderTxPickBar() {
    var sec = document.getElementById('person-transactions-list');
    if (!sec) return;
    var bar = document.getElementById('sr-txpick-bar');
    var n = _srTxPick ? Object.keys(_srTxPick.selected).length : 0;
    if (!bar) {
        bar = document.createElement('div');
        bar.id = 'sr-txpick-bar';
        bar.style.cssText = 'position:fixed;bottom:0;inset-inline:0;z-index:9998;background:#1e3a5f;color:#fff;display:flex;align-items:center;justify-content:space-between;gap:12px;padding:12px 18px;box-shadow:0 -4px 16px rgba(0,0,0,.2);font-family:inherit;';
        bar.innerHTML =
            '<span id="sr-txpick-count"></span>' +
            '<span style="display:flex;gap:8px;">' +
            '<button type="button" onclick="_srCancelTxPick()" style="background:transparent;border:1px solid #fff;color:#fff;border-radius:8px;padding:8px 16px;cursor:pointer;font-family:inherit;">لغو</button>' +
            '<button type="button" onclick="_srConfirmTxPick()" style="background:#fff;border:none;color:#1e3a5f;border-radius:8px;padding:8px 18px;cursor:pointer;font-weight:bold;font-family:inherit;"><i class="fas fa-plus"></i> افزودن به برگشت</button>' +
            '</span>';
        document.body.appendChild(bar);
    }
    var cnt = document.getElementById('sr-txpick-count');
    if (cnt) cnt.textContent = n > 0 ? ('انتخاب‌شده: ' + n + ' معامله') : 'یک یا چند معامله را انتخاب کنید';
}

function _srRemoveTxPickBar() { var bar = document.getElementById('sr-txpick-bar'); if (bar) bar.remove(); }

function _srConfirmTxPick() {
    if (!_srTxPick) return;
    var ids = Object.keys(_srTxPick.selected);
    var ctx = _srTxPick;
    ids.forEach(function (id) {
        var info = _srReturnInfoForTx((db.getTransactions() || []).find(function (t) { return t.id == id; }));
        if (!info) return;
        info.items.forEach(function (it) {
            if (it.isService || it.returnableQty <= 0) return;
            _srAddLinkedItemToForm(ctx.kind, id, it);
        });
    });
    _srExitTxPick(ctx.section);
}
if (typeof window !== 'undefined') window._srConfirmTxPick = _srConfirmTxPick;

function _srCancelTxPick() { var s = _srTxPick ? _srTxPick.section : 'sale-return-form'; _srExitTxPick(s); }
if (typeof window !== 'undefined') window._srCancelTxPick = _srCancelTxPick;

function _srExitTxPick(section) {
    _srTxPick = null;
    _srRemoveTxPickBar();
    // بازگردانیِ دکمهٔ برگشتِ لیستِ معاملات
    var sec = document.getElementById('person-transactions-list');
    if (sec) { var back = sec.querySelector('.btn-back-header'); if (back) { back.setAttribute('onclick', 'personTxGoBack()'); back.title = 'برگشت'; } }
    if (typeof showSection === 'function') showSection(section || 'sale-return-form');
    if (section === 'sale-return-form' && typeof srRecalc === 'function') srRecalc();
    if (section === 'purchase-return-form' && typeof prRecalc === 'function') prRecalc();
}

// افزودنِ یک قلمِ قابلِ برگشت (مرتبط با معاملهٔ اصلی) به فورمِ فعال
function _srAddLinkedItemToForm(kind, origId, it) {
    if (kind === 'purchase') {
        if (typeof prAddReturnRow !== 'function') return;
        var pExists = Array.prototype.some.call(document.querySelectorAll('#pr-items-body .pr-item-row'), function (tr) {
            return tr.dataset.origPurchaseId == origId && tr.dataset.origItemIndex == it.index;
        });
        if (pExists) return;
        prAddReturnRow({
            productId: it.productId, productName: it.productName, unit: it.unit,
            price: it.price, discount: 0, returnable: it.returnableQty, soldQty: it.soldQty,
            origPurchaseId: origId, origItemIndex: it.index,
            unitType: it.unitType, secondaryFactor: it.secondaryFactor, quantity: it.returnableQty
        });
        return;
    }
    var exists = Array.prototype.some.call(document.querySelectorAll('#sr-items-body .sr-item-row'), function (tr) {
        return tr.dataset.origSaleId == origId && tr.dataset.origItemIndex == it.index;
    });
    if (exists) return;
    srAddReturnRow({
        productId: it.productId, productName: it.productName, unit: it.unit,
        price: it.price, discount: 0, returnable: it.returnableQty, soldQty: it.soldQty,
        origSaleId: origId, origItemIndex: it.index,
        unitType: it.unitType, secondaryFactor: it.secondaryFactor, quantity: it.returnableQty
    });
}

// ---- ثبت ----
function _buildSaleReturnPayload() {
    var custId = (document.getElementById('sr-customer') || {}).value;
    var custName = (document.getElementById('sr-customer-search') || {}).value || '';
    var currency = (document.getElementById('sr-currency') || {}).value || _baseCur();
    var date = (document.getElementById('sr-date') || {}).value || '';
    var billNumber = (document.getElementById('sr-bill-number') || {}).value || '';
    var cashboxId = (document.getElementById('sr-cashbox') || {}).value || '';
    var cashRefund = parseFloat((document.getElementById('sr-cash-refund') || {}).value) || 0;
    var notes = (document.getElementById('sr-notes') || {}).value || '';
    if (!custId) return { error: 'لطفاً خریدار را انتخاب کنید.' };

    var rows = document.querySelectorAll('#sr-items-body .sr-item-row');
    if (!rows.length) return { error: 'حداقل یک قلم برای برگشت اضافه کنید.' };

    // برای ردیف‌های دستی (بدون origSaleId) مقدارِ برگشت به‌صورتِ FIFO بین فروش‌های خریدار تقسیم می‌شود.
    var usedByKey = {};   // 'saleId|idx' → مقدارِ مصرف‌شده در همین فورم
    var items = [];
    for (var i = 0; i < rows.length; i++) {
        var tr = rows[i];
        var qty = parseFloat((tr.querySelector('.sr-qty') || {}).value) || 0;
        if (qty <= 0) continue;
        var pid = tr.dataset.productId;
        if (!pid) return { error: 'برای ردیف ' + (i + 1) + ' جنس انتخاب نشده است.' };
        // قیمتِ واحدِ ویرایش‌شدهٔ همین ردیف (اگر کاربر تغییر داده باشد) — مبنای مبلغِ برگشت/رفاند
        var _rpRaw = (tr.querySelector('.sr-price') || {}).value;
        var _rpEdited = (_rpRaw !== '' && _rpRaw != null && !isNaN(parseFloat(_rpRaw))) ? parseFloat(_rpRaw) : undefined;
        if (tr.dataset.origSaleId) {
            var key = tr.dataset.origSaleId + '|' + tr.dataset.origItemIndex;
            usedByKey[key] = (usedByKey[key] || 0) + qty;
            items.push({ origSaleId: parseInt(tr.dataset.origSaleId), origItemIndex: parseInt(tr.dataset.origItemIndex), quantity: qty, price: _rpEdited });
        } else {
            // تخصیصِ FIFO روی فروش‌های خریدار برای این جنس
            var alloc = _srAllocate(custId, pid, qty, usedByKey);
            if (alloc.error) return { error: alloc.error };
            alloc.parts.forEach(function (pt) { if (_rpEdited !== undefined) pt.price = _rpEdited; items.push(pt); });
        }
    }
    if (!items.length) return { error: 'مقدارِ معتبری برای برگشت وارد نشده است.' };
    return {
        payload: {
            customerId: custId, customerName: custName, currency: currency, date: date,
            billNumber: billNumber, cashboxId: cashboxId, cashRefund: cashRefund, notes: notes,
            items: items
        }
    };
}

// تخصیصِ مقدارِ برگشتِ یک جنس به فروش‌های خریدار (قدیمی‌ترین اول)، با در نظر گرفتنِ
// آنچه در همین فورم قبلاً مصرف شده (usedByKey).
function _srAllocate(customerId, productId, qty, usedByKey) {
    var txs = db.getTransactions() || [];
    var sales = txs.filter(function (t) { return t.type === 'فروش' && t.customerId == customerId; })
                   .sort(function (a, b) { return (a.createdAt || '') < (b.createdAt || '') ? -1 : 1; });
    var remaining = qty;
    var parts = [];
    for (var s = 0; s < sales.length && remaining > 1e-9; s++) {
        var info = _saleReturnInfo(sales[s].id);
        if (!info) continue;
        for (var k = 0; k < info.items.length && remaining > 1e-9; k++) {
            var it = info.items[k];
            if (it.isService || it.productId != productId) continue;
            var key = sales[s].id + '|' + it.index;
            var avail = it.returnableQty - (usedByKey[key] || 0);
            if (avail <= 1e-9) continue;
            var take = Math.min(avail, remaining);
            parts.push({ origSaleId: sales[s].id, origItemIndex: it.index, quantity: take });
            usedByKey[key] = (usedByKey[key] || 0) + take;
            remaining -= take;
        }
    }
    if (remaining > 1e-6) return { error: 'مقدارِ برگشتِ این جنس بیش از قابلِ برگشتِ فروش‌های خریدار است.' };
    return { parts: parts };
}

function saveSaleReturn() {
    var built = _buildSaleReturnPayload();
    if (built.error) { showMessage('خطا', built.error); return null; }
    var res = _commitSaleReturn(built.payload);
    if (!res.success) { showMessage('خطا', res.error || 'خطا در ثبت برگشت'); return null; }
    showMessage('موفقیت', 'برگشت از فروش با موفقیت ثبت شد.');
    // بازگشت به همان بخشی که فرم از آنجا باز شده بود؛ اگر context موجود نبود، رفتارِ قبلی (لیستِ برگشت‌ها).
    if (!(typeof _consumeFormReturn === 'function' && _consumeFormReturn())) {
        if (typeof loadSaleReturnsList === 'function') { try { loadSaleReturnsList(); } catch (e) {} }
    }
    return res.tx;
}
if (typeof window !== 'undefined') window.saveSaleReturn = saveSaleReturn;

function saveAndPrintSaleReturn() {
    var tx = saveSaleReturn();
    if (tx) setTimeout(function () { printSaleReturnBill(tx); }, 400);
}
if (typeof window !== 'undefined') window.saveAndPrintSaleReturn = saveAndPrintSaleReturn;

// چاپِ بلِ برگشت از فروش — هم‌سبکِ بلِ فروش، با جزئیاتِ برگشت.
function printSaleReturnBill(tx) {
    try {
        if (!tx) return;
        // از همان مولدِ حرفه‌ایِ بلِ فروش/خرید استفاده می‌کنیم تا طرح، هدر و جزئیات دقیقاً یکی باشد
        var settings = (db.getSettings ? db.getSettings() : {}) || {};
        var _psz = document.getElementById('print-paper-size');
        var _por = document.getElementById('print-orientation');
        var _pmg = document.getElementById('print-margin');
        var _pfs = document.getElementById('print-font-size');
        var _plg = document.getElementById('print-store-logo');
        var _pbc = document.getElementById('print-barcode');
        var _pcc = document.getElementById('print-currency-conversion');
        var printSettings = {
            paperSize: (_psz ? _psz.value : 'A4'),
            orientation: (_por ? _por.value : 'portrait'),
            margin: (_pmg ? _pmg.value : '10') + 'mm',
            fontSize: (_pfs ? _pfs.value : 'medium'),
            printLogo: (_plg ? _plg.checked : true),
            printBarcode: (_pbc ? _pbc.checked : false),
            printCurrencyConversion: (_pcc ? _pcc.checked : false)
        };
        var isSale = (tx.returnType === 'فروش');
        var title = (isSale ? 'بل برگشت از فروش ' : 'بل برگشت از خرید ') + (tx.billNumber || '');
        var invoiceHTML = generateProfessionalInvoiceHTML(tx, settings, printSettings);
        if (typeof __openPrintPreview === 'function') {
            __openPrintPreview(invoiceHTML, { title: title, text: title, assets: true, topBar: true, billShare: true, pdfName: title });
        } else {
            var w = window.open('', '_blank', 'width=950,height=900');
            if (w) { w.document.open(); w.document.write(invoiceHTML); w.document.close(); }
        }
    } catch (e) { console.error('printSaleReturnBill:', e); }
}
if (typeof window !== 'undefined') window.printSaleReturnBill = printSaleReturnBill;

// ========================================================================
// «برگشت از خرید» — رابط کاربری (متقارنِ برگشت از فروش)
// ========================================================================
function showPurchaseReturnForm(supplierId) {
    try {
        var _act = document.querySelector('.section.active');
        var _oid = _act ? _act.id : 'dashboard';
        if (!_oid || _oid === 'sale-return-form' || _oid === 'purchase-return-form' || _oid === 'products-list' || _oid === 'person-transactions-list') _oid = 'dashboard';
        _setFormReturn && _setFormReturn({ section: _oid });
    } catch (e) {}
    showSection('purchase-return-form');
    if (typeof _populateCurrencySelect === 'function') _populateCurrencySelect('pr-currency', _baseCur());
    var ss = document.getElementById('pr-supplier-search'); if (ss) ss.value = '';
    var sh = document.getElementById('pr-supplier'); if (sh) sh.value = '';
    if (supplierId != null) {
        var _p = (db.getPersons() || []).find(function (x) { return x.id == supplierId; });
        if (_p) { if (sh) sh.value = _p.id; if (ss) ss.value = _p.name; }
    }
    var d = document.getElementById('pr-date'); if (d) d.value = (typeof _nowJalaliDateTime === 'function') ? _nowJalaliDateTime() : '';
    var bn = document.getElementById('pr-bill-number');
    if (bn) { var _txs = db.getTransactions() || []; var _cnt = _txs.filter(function (t) { return t.type === 'برگشت'; }).length; bn.value = 'RETP-' + String(_cnt + 1).padStart(4, '0'); }
    var body = document.getElementById('pr-items-body'); if (body) body.innerHTML = '';
    var cr = document.getElementById('pr-cash-refund'); if (cr) cr.value = '';
    var nt = document.getElementById('pr-notes'); if (nt) nt.value = '';
    loadCashboxesForPurchaseReturn();
    onPurchaseReturnCurrencyChange();
    prRecalc();
}
if (typeof window !== 'undefined') window.showPurchaseReturnForm = showPurchaseReturnForm;

function goBackFromPurchaseReturn() {
    if (typeof _consumeFormReturn === 'function' && _consumeFormReturn()) return;
    showSection('dashboard');
}
if (typeof window !== 'undefined') window.goBackFromPurchaseReturn = goBackFromPurchaseReturn;

function searchPurchaseReturnSupplier(inputElement) {
    var query = (inputElement.value || '').toLowerCase();
    var listContainer = document.getElementById('pr-supplier-results');
    var hiddenInput = document.getElementById('pr-supplier');
    if (query === '') { showAllPersonsForField(inputElement, 'pr-supplier-results', 'pr-supplier', 'تامین کننده'); return; }
    var persons = db.getPersons();
    var filtered = persons.filter(function (p) {
        return (p.category === 'تامین کننده' || p.category === 'فروشنده') && ((p.name && p.name.toLowerCase().includes(query)) || (p.phone && p.phone.includes(query)));
    });
    renderSearchResults(filtered, listContainer, inputElement, hiddenInput);
}
if (typeof window !== 'undefined') window.searchPurchaseReturnSupplier = searchPurchaseReturnSupplier;

function loadCashboxesForPurchaseReturn() {
    var sel = document.getElementById('pr-cashbox'); if (!sel) return;
    var boxes = db.getCashboxes() || [];
    sel.innerHTML = '<option value="">حساب</option>';
    boxes.forEach(function (cb) { var o = document.createElement('option'); o.value = cb.id; o.textContent = cb.name + (cb.isDefault ? ' \u2605' : ''); sel.appendChild(o); });
    var curEl = document.getElementById('pr-currency'); var cur = curEl ? curEl.value : _baseCur();
    if (typeof getDefaultCashboxIdForCurrency === 'function') { var defId = getDefaultCashboxIdForCurrency(cur); if (defId) sel.value = String(defId); }
}

function onPurchaseReturnCurrencyChange() {
    var curEl = document.getElementById('pr-currency'); var cur = curEl ? curEl.value : _baseCur();
    var lbl = document.getElementById('pr-total-currency'); if (lbl) lbl.textContent = cur;
    loadCashboxesForPurchaseReturn(); prRecalc();
}
if (typeof window !== 'undefined') window.onPurchaseReturnCurrencyChange = onPurchaseReturnCurrencyChange;

function prAddReturnRow(data) {
    var body = document.getElementById('pr-items-body'); if (!body) return null;
    data = data || {};
    var tr = document.createElement('tr'); tr.className = 'pr-item-row';
    tr.dataset.productId = (data.productId != null ? data.productId : '');
    tr.dataset.origPurchaseId = (data.origPurchaseId != null ? data.origPurchaseId : '');
    tr.dataset.origItemIndex = (data.origItemIndex != null ? data.origItemIndex : '');
    tr.dataset.returnable = (data.returnable != null ? data.returnable : '');
    tr.dataset.unitType = data.unitType || 'primary';
    tr.dataset.secondaryFactor = (data.secondaryFactor != null ? data.secondaryFactor : 0);
    tr.dataset.price = (data.price != null ? data.price : 0);
    tr.dataset.discountFull = (data.discount != null ? data.discount : 0);
    tr.dataset.soldQty = (data.soldQty != null ? data.soldQty : (data.returnable != null ? data.returnable : 0));
    var num = body.querySelectorAll('.pr-item-row').length + 1;
    var linked = (data.origPurchaseId != null && data.origPurchaseId !== '') || !!data.lockName;
    var qtyInit = (data.quantity != null) ? data.quantity : (data.returnable != null ? data.returnable : 1);
    var nameCell = linked
        ? '<span class="pr-item-name">' + (data.productName || '') + '</span>'
        : '<div class="product-search-wrapper" style="position:relative;"><input type="text" class="pr-product-search form-control" placeholder="نام جنس..." autocomplete="off" onkeyup="prProductSearch(this)"><div class="pr-product-results product-search-results"></div></div>';
    tr.innerHTML =
        '<td style="text-align:center;">' + num + '</td>' +
        '<td>' + nameCell + '</td>' +
        '<td><input type="number" class="pr-qty bill-cell-input" value="' + qtyInit + '" min="0" step="any" oninput="prUpdateRow(this)" onchange="prUpdateRow(this)" style="width:100%;"></td>' +
        '<td><span class="pr-unit">' + (data.unit || 'عدد') + '</span></td>' +
        '<td><input type="number" class="pr-price bill-cell-input" step="0.01" value="' + (data.price != null ? data.price : '') + '" oninput="prUpdateRow(this)" onchange="prUpdateRow(this)" style="width:100%;"></td>' +
        '<td><input type="number" class="pr-disc bill-cell-input" step="0.01" value="' + (data.discount != null ? data.discount : 0) + '" readonly style="width:100%;"></td>' +
        '<td style="text-align:center;"><span class="pr-returnable">' + (data.returnable != null ? formatNumber(data.returnable) : '\u2014') + '</span></td>' +
        '<td><span class="pr-total">۰</span></td>' +
        '<td><button type="button" class="btn-icon btn-danger" onclick="prRemoveRow(this)"><i class="fas fa-trash"></i></button></td>';
    body.appendChild(tr);
    prUpdateRowByTr(tr);
    return tr;
}
if (typeof window !== 'undefined') window.prAddReturnRow = prAddReturnRow;

function prRemoveRow(btn) {
    var tr = btn.closest('.pr-item-row'); if (tr) tr.remove();
    var rows = document.querySelectorAll('#pr-items-body .pr-item-row');
    rows.forEach(function (r, i) { var c = r.querySelector('td'); if (c) c.textContent = (i + 1); });
    prRecalc();
}
if (typeof window !== 'undefined') window.prRemoveRow = prRemoveRow;

function prUpdateRow(input) { prUpdateRowByTr(input.closest('.pr-item-row')); }
if (typeof window !== 'undefined') window.prUpdateRow = prUpdateRow;

function prUpdateRowByTr(tr) {
    if (!tr) return;
    var qEl = tr.querySelector('.pr-qty'), pEl = tr.querySelector('.pr-price'), dEl = tr.querySelector('.pr-disc');
    var qty = parseFloat(qEl ? qEl.value : 0) || 0;
    var returnable = parseFloat(tr.dataset.returnable);
    if (!isNaN(returnable) && tr.dataset.origPurchaseId && qty > returnable) { qty = returnable; if (qEl) qEl.value = returnable; if (typeof showToast === 'function') showToast('بیش از قابلِ برگشت نمی‌شود', 'warning'); }
    var price = parseFloat(pEl ? pEl.value : 0) || 0;
    var soldQty = parseFloat(tr.dataset.soldQty) || 0, fullDisc = parseFloat(tr.dataset.discountFull) || 0;
    var lineDisc = (soldQty > 0) ? (fullDisc * (qty / soldQty)) : 0;
    if (dEl) dEl.value = _srRound(lineDisc);
    var total = qty * price - lineDisc;
    var tEl = tr.querySelector('.pr-total'); if (tEl) tEl.textContent = formatNumber(_srRound(total));
    prRecalc();
}

function prRecalc() {
    var rows = document.querySelectorAll('#pr-items-body .pr-item-row'); var sub = 0;
    rows.forEach(function (tr) {
        var qty = parseFloat(tr.querySelector('.pr-qty') ? tr.querySelector('.pr-qty').value : 0) || 0;
        var price = parseFloat(tr.querySelector('.pr-price') ? tr.querySelector('.pr-price').value : 0) || 0;
        var disc = parseFloat(tr.querySelector('.pr-disc') ? tr.querySelector('.pr-disc').value : 0) || 0;
        sub += (qty * price - disc);
    });
    sub = _srRound(sub);
    var subEl = document.getElementById('pr-subtotal'); if (subEl) subEl.textContent = formatNumber(sub);
    var gEl = document.getElementById('pr-grand-total'); if (gEl) gEl.textContent = formatNumber(sub);
    calculatePurchaseReturnRemaining();
}
if (typeof window !== 'undefined') window.prRecalc = prRecalc;

function calculatePurchaseReturnRemaining() {
    var grand = _srParse(document.getElementById('pr-grand-total'));
    var refund = parseFloat((document.getElementById('pr-cash-refund') || {}).value) || 0;
    if (refund < 0) refund = 0;
    if (refund > grand) { refund = grand; var cr = document.getElementById('pr-cash-refund'); if (cr && cr.value !== '') cr.value = grand; }
    var remaining = _srRound(grand - refund);
    var disp = document.getElementById('pr-remaining-display'); if (disp) disp.textContent = formatNumber(remaining);
}
if (typeof window !== 'undefined') window.calculatePurchaseReturnRemaining = calculatePurchaseReturnRemaining;

function prFullRefund() {
    var grand = _srParse(document.getElementById('pr-grand-total'));
    var cr = document.getElementById('pr-cash-refund'); if (cr) cr.value = grand;
    calculatePurchaseReturnRemaining();
}
if (typeof window !== 'undefined') window.prFullRefund = prFullRefund;

function prProductSearch(input) {
    var wrap = input.closest('.product-search-wrapper');
    var box = wrap ? wrap.querySelector('.pr-product-results') : null; if (!box) return;
    var q = (input.value || '').toLowerCase();
    if (!q) { box.style.display = 'none'; box.innerHTML = ''; return; }
    var prods = (db.getProducts() || []).filter(function (p) { return p.name && p.name.toLowerCase().includes(q); }).slice(0, 12);
    if (!prods.length) { box.innerHTML = '<div class="result-item" style="color:#94a3b8;">یافت نشد</div>'; box.style.display = 'block'; return; }
    box.innerHTML = prods.map(function (p) { return '<div class="result-item" onclick="prSelectRowProduct(this,' + p.id + ')">' + p.name + '</div>'; }).join('');
    box.style.display = 'block';
}
if (typeof window !== 'undefined') window.prProductSearch = prProductSearch;

function prSelectRowProduct(el, productId) {
    var tr = el.closest('.pr-item-row'); if (!tr) return;
    var supId = (document.getElementById('pr-supplier') || {}).value;
    if (!supId) { showMessage('خطا', 'ابتدا فروشنده را انتخاب کنید.'); return; }
    var agg = _prSupplierReturnableForProduct(supId, productId);
    if (!agg || agg.returnable <= 0) { showMessage('اطلاع', 'برای این فروشنده موردِ قابلِ برگشتی از این جنس یافت نشد.'); return; }
    var prod = (db.getProducts() || []).find(function (p) { return p.id == productId; });
    tr.dataset.productId = productId; tr.dataset.returnable = agg.returnable; tr.dataset.price = agg.price;
    tr.dataset.soldQty = agg.returnable; tr.dataset.discountFull = 0; tr.dataset.origPurchaseId = ''; tr.dataset.origItemIndex = ''; tr.dataset.unitType = 'primary';
    var nameTd = tr.children[1]; if (nameTd) nameTd.innerHTML = '<span class="pr-item-name">' + (prod ? prod.name : (agg.productName || '')) + '</span>';
    var unitEl = tr.querySelector('.pr-unit'); if (unitEl) unitEl.textContent = (prod && prod.unit) ? prod.unit : 'عدد';
    var pEl = tr.querySelector('.pr-price'); if (pEl) { pEl.value = agg.price; pEl.removeAttribute('readonly'); }
    var retEl = tr.querySelector('.pr-returnable'); if (retEl) retEl.textContent = formatNumber(agg.returnable);
    var qEl = tr.querySelector('.pr-qty'); if (qEl && (!qEl.value || parseFloat(qEl.value) <= 0)) qEl.value = 1;
    prUpdateRowByTr(tr);
}
if (typeof window !== 'undefined') window.prSelectRowProduct = prSelectRowProduct;

function _prSupplierReturnableForProduct(supplierId, productId) {
    var txs = db.getTransactions() || [];
    var purs = txs.filter(function (t) { return t.type === 'خرید' && (t.supplierId == supplierId || t.personId == supplierId); })
                  .sort(function (a, b) { return (a.createdAt || '') < (b.createdAt || '') ? -1 : 1; });
    var total = 0, price = 0, name = '', found = false;
    purs.forEach(function (s) {
        var info = _purchaseReturnInfo(s.id); if (!info) return;
        info.items.forEach(function (it) {
            if (it.isService || it.productId != productId) return;
            if (it.returnableQty > 0) { total += it.returnableQty; if (!found) { price = it.price; name = it.productName; found = true; } }
        });
    });
    return { returnable: total, price: price, productName: name };
}

function prPickProductFromWarehouse() {
    var supId = (document.getElementById('pr-supplier') || {}).value;
    if (!supId) { showMessage('خطا', 'ابتدا فروشنده را انتخاب کنید.'); return; }
    _srOpenProductPicker({ kind: 'purchase', section: 'purchase-return-form' });
}
if (typeof window !== 'undefined') window.prPickProductFromWarehouse = prPickProductFromWarehouse;

function _prInsertProductFromPicker(product) {
    var supId = (document.getElementById('pr-supplier') || {}).value;
    var agg = _prSupplierReturnableForProduct(supId, product.id);
    if (!agg || agg.returnable <= 0) { showMessage('اطلاع', 'برای این فروشنده موردِ قابلِ برگشتی از این جنس یافت نشد.'); return; }
    prAddReturnRow({ productId: product.id, productName: product.name || agg.productName, unit: product.unit || 'عدد', price: agg.price, discount: 0, returnable: agg.returnable, soldQty: agg.returnable, quantity: 1, lockName: true });
    prRecalc();
}
if (typeof window !== 'undefined') window._prInsertProductFromPicker = _prInsertProductFromPicker;

function openPurchaseReturnTxPicker() {
    var supId = (document.getElementById('pr-supplier') || {}).value;
    if (!supId) { showMessage('خطا', 'ابتدا فروشنده را انتخاب کنید.'); return; }
    _srOpenTxPicker({ kind: 'purchase', returnType: 'خرید', section: 'purchase-return-form', customerId: supId, selected: {} });
}
if (typeof window !== 'undefined') window.openPurchaseReturnTxPicker = openPurchaseReturnTxPicker;

function _buildPurchaseReturnPayload() {
    var supId = (document.getElementById('pr-supplier') || {}).value;
    var supName = (document.getElementById('pr-supplier-search') || {}).value || '';
    var currency = (document.getElementById('pr-currency') || {}).value || _baseCur();
    var date = (document.getElementById('pr-date') || {}).value || '';
    var billNumber = (document.getElementById('pr-bill-number') || {}).value || '';
    var cashboxId = (document.getElementById('pr-cashbox') || {}).value || '';
    var cashRefund = parseFloat((document.getElementById('pr-cash-refund') || {}).value) || 0;
    var notes = (document.getElementById('pr-notes') || {}).value || '';
    if (!supId) return { error: 'لطفاً فروشنده را انتخاب کنید.' };
    var rows = document.querySelectorAll('#pr-items-body .pr-item-row');
    if (!rows.length) return { error: 'حداقل یک قلم برای برگشت اضافه کنید.' };
    var usedByKey = {}; var items = [];
    for (var i = 0; i < rows.length; i++) {
        var tr = rows[i];
        var qty = parseFloat((tr.querySelector('.pr-qty') || {}).value) || 0; if (qty <= 0) continue;
        var pid = tr.dataset.productId; if (!pid) return { error: 'برای ردیف ' + (i + 1) + ' جنس انتخاب نشده است.' };
        var _prpRaw = (tr.querySelector('.pr-price') || {}).value;
        var _prpEdited = (_prpRaw !== '' && _prpRaw != null && !isNaN(parseFloat(_prpRaw))) ? parseFloat(_prpRaw) : undefined;
        if (tr.dataset.origPurchaseId) {
            var key = tr.dataset.origPurchaseId + '|' + tr.dataset.origItemIndex;
            usedByKey[key] = (usedByKey[key] || 0) + qty;
            items.push({ origPurchaseId: parseInt(tr.dataset.origPurchaseId), origItemIndex: parseInt(tr.dataset.origItemIndex), quantity: qty, price: _prpEdited });
        } else {
            var alloc = _prAllocate(supId, pid, qty, usedByKey);
            if (alloc.error) return { error: alloc.error };
            alloc.parts.forEach(function (pt) { if (_prpEdited !== undefined) pt.price = _prpEdited; items.push(pt); });
        }
    }
    if (!items.length) return { error: 'مقدارِ معتبری برای برگشت وارد نشده است.' };
    return { payload: { customerId: supId, customerName: supName, currency: currency, date: date, billNumber: billNumber, cashboxId: cashboxId, cashRefund: cashRefund, notes: notes, items: items } };
}

function _prAllocate(supplierId, productId, qty, usedByKey) {
    var txs = db.getTransactions() || [];
    var purs = txs.filter(function (t) { return t.type === 'خرید' && (t.supplierId == supplierId || t.personId == supplierId); })
                  .sort(function (a, b) { return (a.createdAt || '') < (b.createdAt || '') ? -1 : 1; });
    var remaining = qty, parts = [];
    for (var s = 0; s < purs.length && remaining > 1e-9; s++) {
        var info = _purchaseReturnInfo(purs[s].id); if (!info) continue;
        for (var k = 0; k < info.items.length && remaining > 1e-9; k++) {
            var it = info.items[k];
            if (it.isService || it.productId != productId) continue;
            var key = purs[s].id + '|' + it.index;
            var avail = it.returnableQty - (usedByKey[key] || 0);
            if (avail <= 1e-9) continue;
            var take = Math.min(avail, remaining);
            parts.push({ origPurchaseId: purs[s].id, origItemIndex: it.index, quantity: take });
            usedByKey[key] = (usedByKey[key] || 0) + take; remaining -= take;
        }
    }
    if (remaining > 1e-6) return { error: 'مقدارِ برگشتِ این جنس بیش از قابلِ برگشتِ خریدهای فروشنده است.' };
    return { parts: parts };
}

function savePurchaseReturn() {
    var built = _buildPurchaseReturnPayload();
    if (built.error) { showMessage('خطا', built.error); return null; }
    var res = _commitPurchaseReturn(built.payload);
    if (!res.success) { showMessage('خطا', res.error || 'خطا در ثبت برگشت'); return null; }
    showMessage('موفقیت', 'برگشت از خرید با موفقیت ثبت شد.');
    // بازگشت به همان بخشی که فرم از آنجا باز شده بود (اگر context موجود بود).
    if (typeof _consumeFormReturn === 'function') { try { _consumeFormReturn(); } catch (e) {} }
    return res.tx;
}
if (typeof window !== 'undefined') window.savePurchaseReturn = savePurchaseReturn;

function saveAndPrintPurchaseReturn() {
    var tx = savePurchaseReturn();
    if (tx) setTimeout(function () { printSaleReturnBill(tx); }, 400);
}
if (typeof window !== 'undefined') window.saveAndPrintPurchaseReturn = saveAndPrintPurchaseReturn;


if (typeof window !== 'undefined') window._commitSaleReturn = _commitSaleReturn;

function showReturnForm(transactionId = null) {
    try {
        // بازکردنِ تازه از دکمهٔ سریع (بدونِ شناسه) → پس از ثبت/برگشت به داشبورد برگردد
        if (transactionId == null) _setFormReturn({ section: 'dashboard' });
        showSection('return-transactions');
        loadCashboxesForReturn();
        loadPersonsForReturn();

        const form = document.getElementById('return-form-container');
        const tableWrapper = document.getElementById('returns-table-wrapper');
        if (form) form.style.display = 'block';
        if (tableWrapper) tableWrapper.style.display = 'none';
        // نمایش دکمه برگشت فقط در حالت فرم
        const backBtn = document.getElementById('return-form-back-btn');
        if (backBtn) backBtn.style.display = 'inline-flex';

        // پاک کردن فرم
        const returnForm = document.getElementById('returnForm');
        if (returnForm) {
            returnForm.reset();
            delete returnForm.dataset.editId;
            delete returnForm.dataset.sourceReturnType;
        }

        // تنظیم تاریخ امروز
        try {
            const dateInput = document.getElementById('return-date');
            if (dateInput) dateInput.value = _nowJalaliDateTime();
        } catch(e) {}

        // اگر از معامله خاصی فراخوانی شده، اطلاعات را پر کن
        if (transactionId) {
            const transactions = db.getTransactions();
            const tx = transactions.find(t => t.id == transactionId);
            if (tx) {
                const typeEl = document.getElementById('return-type');
                if (typeEl) {
                    typeEl.value = tx.type === 'فروش' ? 'برگشت از فروش' : 'برگشت از خرید';
                }
                const billEl = document.getElementById('return-original-bill');
                if (billEl) billEl.value = tx.billNumber || '';
                const amountEl = document.getElementById('return-amount');
                if (amountEl) amountEl.value = tx.totalAmount || tx.amount || '';
                const personEl = document.getElementById('return-person-hidden');
                if (personEl) personEl.value = tx.personId || '';
                const personSearchEl = document.getElementById('return-person-search');
                if (personSearchEl) personSearchEl.value = tx.personName || tx.customerName || tx.supplierName || '';
                const currencyEl = document.getElementById('return-currency');
                if (currencyEl) currencyEl.value = tx.currency || _baseCur();
                // ذخیره نوع منبع برای دکمه بک
                if (returnForm) returnForm.dataset.sourceReturnType = tx.type === 'فروش' ? 'فروش' : 'خرید';
            }
        }
    } catch (e) {
        console.error('showReturnForm error:', e);
    }
}

// دکمه بک در فرم برگشت — بر اساس نوع برگشت به لیست مناسب برمی‌گردد
function goBackFromReturn() {
    try {
        // اگر از دکمهٔ سریعِ داشبورد آمده، به داشبورد برگردد
        if (_consumeFormReturn()) return;
        const returnTypeEl = document.getElementById('return-type');
        const returnForm = document.getElementById('returnForm');
        const sourceType = returnForm ? returnForm.dataset.sourceReturnType : null;
        const selectedType = returnTypeEl ? returnTypeEl.value : '';

        const isSales = selectedType === 'برگشت از فروش' || sourceType === 'فروش';
        const isPurchase = selectedType === 'برگشت از خرید' || sourceType === 'خرید';

        if (isSales) {
            showSection('sales-returns-list');
        } else if (isPurchase) {
            showSection('purchase-returns-list');
        } else {
            // اگر نوع انتخاب نشده، به لیست برگشت از فروش برو
            showSection('sales-returns-list');
        }
    } catch (e) {
        showSection('sales-returns-list');
    }
}

function loadCashboxesForReturn() {
    const cashboxSelect = document.getElementById('return-cashbox');
    if (!cashboxSelect) return;
    const cashboxes = db.getCashboxes();
    cashboxSelect.innerHTML = '<option value="">انتخاب حساب</option>';
    cashboxes.forEach(cashbox => {
        const option = document.createElement('option');
        option.value = cashbox.id;
        option.textContent = _cashboxOptLabel(cashbox);
        cashboxSelect.appendChild(option);
    });
    // انتخاب خودکار حساب پیش‌فرض بر اساس ارز فرم
    const curEl = document.getElementById('return-currency');
    const cur = curEl ? curEl.value : 'AFN';
    const defId = getDefaultCashboxIdForCurrency(cur);
    if (defId) cashboxSelect.value = String(defId);
}

function loadPersonsForReturn() {
    const personSearch = document.getElementById('return-person-search');
    if (!personSearch) return;
    personSearch.setAttribute('autocomplete', 'off');
}

function searchReturnPerson(input) {
    const query = input.value.toLowerCase();
    const results = document.getElementById('return-person-results');
    if (!results) return;
    if (!query) { results.style.display = 'none'; return; }
    const persons = db.getPersons().filter(p => p.name.toLowerCase().includes(query));
    if (persons.length === 0) { results.style.display = 'none'; return; }
    results.innerHTML = persons.map(p => `<div class="result-item" onclick="selectReturnPerson(${p.id}, '${p.name}')">${p.name} - ${p.category}</div>`).join('');
    results.style.display = 'block';
}

function selectReturnPerson(id, name) {
    const hiddenInput = document.getElementById('return-person-hidden');
    const searchInput = document.getElementById('return-person-search');
    const results = document.getElementById('return-person-results');
    if (hiddenInput) hiddenInput.value = id;
    if (searchInput) searchInput.value = name;
    if (results) results.style.display = 'none';
}

function saveReturn() {
    try {
        const returnType = document.getElementById('return-type').value;
        const originalBill = document.getElementById('return-original-bill').value;
        const personId = document.getElementById('return-person-hidden').value;
        const personName = document.getElementById('return-person-search').value;
        const amount = parseFloat(document.getElementById('return-amount').value) || 0;
        const currency = document.getElementById('return-currency').value;
        const cashboxId = document.getElementById('return-cashbox').value;
        const reason = document.getElementById('return-reason').value;
        const notes = document.getElementById('return-notes').value;
        const date = document.getElementById('return-date').value;

        if (!returnType) { showMessage('خطا', 'لطفاً نوع برگشت را انتخاب کنید.'); return; }
        if (amount <= 0) { showMessage('خطا', 'لطفاً مبلغ معتبر وارد کنید.'); return; }
        if (!cashboxId) { showMessage('خطا', 'لطفاً حساب را انتخاب کنید.'); return; }
        if (!date) { showMessage('خطا', 'لطفاً تاریخ را وارد کنید.'); return; }

        const isSalesReturn = returnType === 'برگشت از فروش';
        const billPrefix = isSalesReturn ? 'RET-' : 'RETP-';
        const transactions = db.getTransactions() || [];
        const existingReturns = transactions.filter(t => t.type === 'برگشت').length;
        const billNumber = billPrefix + String(existingReturns + 1).padStart(4, '0');

        const transaction = {
            type: 'برگشت',
            returnType: isSalesReturn ? 'فروش' : 'خرید',
            billNumber,
            originalBillNumber: originalBill || '',
            relatedBill: originalBill || '',
            personId: personId ? parseInt(personId) : null,
            personName: personName || '',
            customerName: isSalesReturn ? (personName || '') : '',
            supplierName: !isSalesReturn ? (personName || '') : '',
            amount,
            totalAmount: amount,
            currency: currency || _baseCur(),
            cashboxId: parseInt(cashboxId),
            reason: reason || '',
            notes: notes || '',
            date,
            status: 'تایید شده'
        };

        const result = db.saveTransaction(transaction);
        if (!result.success) { showMessage('خطا', result.error || 'خطا در ثبت برگشت'); return; }

        showMessage('موفقیت', 'معامله برگشتی با موفقیت ثبت شد.');

        // انتقال به لیست برگشت نظر به نوعیت برگشت (یا داشبورد اگر از دکمهٔ سریع آمده)
        setTimeout(() => {
            if (_consumeFormReturn()) return;
            if (isSalesReturn) {
                showSection('sales-returns-list');
            } else {
                showSection('purchase-returns-list');
            }
        }, 1000);
    } catch (e) {
        console.error('saveReturn error:', e);
        showMessage('خطا', 'خطا در ثبت برگشت: ' + e.message);
    }
}

function showReturnsList() {
    const form = document.getElementById('return-form-container');
    const tableWrapper = document.getElementById('returns-table-wrapper');
    if (form) form.style.display = 'none';
    if (tableWrapper) tableWrapper.style.display = 'block';
    // پنهان کردن دکمه برگشت در حالت لیست
    const backBtn = document.getElementById('return-form-back-btn');
    if (backBtn) backBtn.style.display = 'none';
    loadReturns();
}

