// توابع بارگذاری لیست‌های اخیر
function loadRecentLists() {
    loadRecent('sales', 'فروش');
    loadRecent('purchases', 'خرید');
    loadRecent('receipts', 'دریافت');
    loadRecent('payments', 'پرداخت');
    loadRecent('return-sales', 'برگشتی فروش');
    loadRecent('return-purchases', 'برگشتی خرید');
}

function loadRecent(idSuffix, typeFilter) {
    const transactions = (db.getTransactions() || [])
        .filter(tx => {
            if (typeFilter.includes('برگشتی')) {
                return tx.type === 'برگشتی' && tx.originalType === typeFilter.replace('برگشتی ', '');
            }
            return tx.type === typeFilter;
        })
        .sort((a, b) => new Date(b.createdAt || b.date) - new Date(a.createdAt || a.date))
        .slice(0, 5);

    const tbody = document.getElementById(`recent-${idSuffix}-body`);
    if (!tbody) return;

    tbody.innerHTML = '';
    if (transactions.length === 0) {
        tbody.innerHTML = '<tr><td colspan="4">موردی یافت نشد</td></tr>';
        return;
    }

    transactions.forEach(tx => {
        const person = db.getPersons().find(p => p.id == tx.personId) || { name: 'نامشخص' };
        const row = document.createElement('tr');
        row.innerHTML = `
            <td>${formatAfghanDateTime(tx.date, tx.createdAt) || '-'}</td>
            <td>${person.name}</td>
            <td>${formatCurrencyAFN(tx.totalAmount || tx.amount || 0)}</td>
            <td><i class="fas fa-chevron-left" style="color:#94a3b8;"></i></td>
        `;
        row.style.cursor = 'pointer';
        (function(txId){ row.onclick = function(){ viewTransaction(txId); }; })(tx.id);
        tbody.appendChild(row);
    });
}

