/** باز کردن سایدبار تنظیمات */
function openSidebar() {
    const sidebar = document.getElementById('settings-sidebar');
    const overlay = document.getElementById('settings-overlay');
    const main    = document.querySelector('.main-content');
    if (sidebar) sidebar.classList.add('open');
    if (overlay) {
        overlay.classList.add('open');
        overlay.onclick = function() { closeSidebar(); };
    }
    if (main)    main.classList.add('sidebar-blurred');
    ssbResetList();
}

/** بستن سایدبار تنظیمات */
function closeSidebar() {
    const sidebar = document.getElementById('settings-sidebar');
    const overlay = document.getElementById('settings-overlay');
    const main    = document.querySelector('.main-content');
    if (sidebar) sidebar.classList.remove('open');
    if (overlay) overlay.classList.remove('open');
    if (main)    main.classList.remove('sidebar-blurred');
}

// بستن سایدبار با کلیک بیرون از آن (capture=true تا قبل از پردازش داخلی اجرا شود)
document.addEventListener('click', function(e) {
    const sidebar = document.getElementById('settings-sidebar');
    if (!sidebar || !sidebar.classList.contains('open')) return;

    // اگر کلیک داخل سایدبار بود، نادیده بگیر
    if (sidebar.contains(e.target)) return;

    // اگر کلیک روی دکمه‌ای که سایدبار را باز/بسته می‌کند بود، نادیده بگیر
    const toggleBtn = document.getElementById('settings-toggle');
    if (toggleBtn && toggleBtn.contains(e.target)) return;

    // در غیر این صورت سایدبار را ببند
    closeSidebar();
}, true);
/** سازگاری با کدهای قدیمی که closeSettingsSidebar صدا می‌زنند */
function closeSettingsSidebar() { closeSidebar(); }

/** برگشت به لیست اصلی از زیربخش */
function ssbGoBack() {
    ssbResetList();
}

/** نمایش دوباره لیست اصلی */
function ssbResetList() {
    const mainList  = document.getElementById('ssb-main-list');
    const subCont   = document.getElementById('ssb-sub-content');
    const backBtn   = document.getElementById('ssb-back-btn');
    const title     = document.getElementById('ssb-title');
    if (mainList)  mainList.style.display = '';
    if (subCont)   { subCont.style.display = 'none'; subCont.innerHTML = ''; }
    if (backBtn)   backBtn.classList.remove('visible');
    if (title)     title.innerHTML = '<i class="fas fa-cog"></i> تنظیمات';
}

/** باز کردن یک زیربخش */
function ssbOpenSub(key) {
    const mainList = document.getElementById('ssb-main-list');
    const subCont  = document.getElementById('ssb-sub-content');
    const backBtn  = document.getElementById('ssb-back-btn');
    const title    = document.getElementById('ssb-title');
    if (!subCont) return;

    if (mainList)  mainList.style.display = 'none';
    if (backBtn)   backBtn.classList.add('visible');
    if (title)     title.innerHTML = ssbGetTitle(key);

    subCont.style.display = '';
    subCont.innerHTML = ssbLoadSubContent(key);

    // به‌روز کردن مقادیر فرم از db
    ssbPopulateForm(key);
}

/** عنوان هر زیربخش */
function ssbGetTitle(key) {
    const titles = {
        store:    '<i class="fas fa-store"></i> اطلاعات فروشگاه',
        backup:   '<i class="fas fa-database"></i> پشتیبان‌گیری',
        display:  '<i class="fas fa-eye"></i> نمایش',
        invoice:  '<i class="fas fa-file-invoice-dollar"></i> تنظیمات بل',
        numsys:   '<i class="fas fa-sort-numeric-down"></i> سیستم اعداد',
        currency: '<i class="fas fa-coins"></i> واحد پول',
        notes:    '<i class="fas fa-bell"></i> مرکز پیام',
        excel:    '<i class="fas fa-file-excel"></i> اکسل',
        security: '<i class="fas fa-lock"></i> امنیت',
        dbinit:   '<i class="fas fa-tools"></i> تصحیح دیتابیس',
        delete:   '<i class="fas fa-trash-alt"></i> حذف داده‌ها',
        datasettings: '<i class="fas fa-cogs"></i> تنظیمات اطلاعات',
    };
    return titles[key] || '<i class="fas fa-cog"></i> تنظیمات';
}

