// نمایش نوار عملیات شناور برای فروش/خرید (مشابه showHorizontalActionBar در بخش افراد)
function showTransactionActionBar(event, id, type) {
    if (closeToolbarTimer) {
        clearTimeout(closeToolbarTimer);
        closeToolbarTimer = null;
    }
    if (currentToolbar) {
        currentToolbar.remove();
        currentToolbar = null;
    }

    const transactions = db.getTransactions ? db.getTransactions() : [];
    const tx = transactions.find(t => t.id == id);
    if (!tx) return;

    const toolbar = document.createElement('div');
    toolbar.className = 'floating-action-toolbar';
    toolbar.setAttribute('data-tx-id', id);

    Object.assign(toolbar.style, {
        position: 'absolute',
        display: 'flex',
        flexDirection: 'column',
        alignItems: 'stretch',
        gap: '4px',
        backgroundColor: '#ffffff',
        padding: '8px',
        borderRadius: '12px',
        boxShadow: '0 5px 20px rgba(0,0,0,0.2)',
        border: '1px solid #cbd5e1',
        zIndex: '9999',
        whiteSpace: 'nowrap',
        minWidth: '180px'
    });

    const actions = [
        { icon: 'fa-edit', color: '#d97706', title: 'ویرایش', action: 'edit' },
        { icon: 'fa-print', color: '#7c3aed', title: 'چاپ فاکتور', action: 'print-invoice' },
        { icon: 'fa-trash', color: '#dc2626', title: 'حذف', action: 'delete' }
    ];

    actions.forEach(item => {
        const btn = document.createElement('button');
        btn.title = item.title;
        btn.innerHTML = `<i class="fas ${item.icon}" style="width:18px;text-align:center;color:${item.color};"></i><span style="margin-right:10px;font-size:13px;color:#1e293b;font-weight:500;">${item.title}</span>`;
        Object.assign(btn.style, {
            background: 'transparent',
            border: 'none',
            cursor: 'pointer',
            padding: '8px 10px',
            transition: 'background 0.2s',
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'flex-start',
            borderRadius: '6px',
            textAlign: 'right',
            fontFamily: 'inherit'
        });
        btn.onmouseenter = () => btn.style.background = '#f1f5f9';
        btn.onmouseleave = () => btn.style.background = 'transparent';
        btn.onclick = (e) => {
            e.stopPropagation();
            closeAllActionMenus();
            performTransactionAction(id, item.action, type);
        };
        toolbar.appendChild(btn);
    });

    toolbar.addEventListener('mouseenter', () => {
        if (closeToolbarTimer) {
            clearTimeout(closeToolbarTimer);
            closeToolbarTimer = null;
        }
    });
    toolbar.addEventListener('mouseleave', () => { startCloseToolbarTimer(); });

    document.body.appendChild(toolbar);
    currentToolbar = toolbar;

    const rect = event.currentTarget.getBoundingClientRect();
    const scrollTop = window.pageYOffset || document.documentElement.scrollTop;
    const scrollLeft = window.pageXOffset || document.documentElement.scrollLeft;
    toolbar.style.top = (rect.top + scrollTop) + 'px';
    toolbar.style.left = (rect.right + scrollLeft + 10) + 'px';

    toolbar.animate([
        { opacity: 0, transform: 'scale(0.8)' },
        { opacity: 1, transform: 'scale(1)' }
    ], { duration: 200, easing: 'cubic-bezier(0.175, 0.885, 0.32, 1.275)' });
}

// انجام عملیات انتخاب‌شده برای فروش/خرید
function performTransactionAction(id, action, type) {
    const transactions = db.getTransactions ? db.getTransactions() : [];
    const tx = transactions.find(t => t.id == id);
    if (!tx) return;

    switch(action) {
        case 'view':
            viewTransaction(id);
            break;
        case 'edit':
            editTransaction(id);
            break;
        case 'delete':
            deleteTransaction(id);
            break;
        case 'print-invoice':
            if (tx.type === 'خرید') {
                if (typeof printPurchaseBill === 'function') printPurchaseBill(tx.id, tx);
            } else {
                if (typeof printInvoice === 'function') printInvoice(tx.id);
            }
            break;
    }
}

function printTransaction(id) {
    window.print();
}

