function _populateInjectedPanel() {
    var boxes = (db && db.getCashboxes) ? db.getCashboxes() : [];
    var fromSel = document.getElementById('inj-cb-from');
    var toSel   = document.getElementById('inj-cb-to');
    if (!fromSel || !toSel) return;
    var optionsHTML = '<option value="">انتخاب حساب</option>';
    boxes.forEach(function(b) {
        var label = b.name + ' (' + getCurrencyLabel(b.currency) + ') — موجودی: ' + formatAmountWithCurrency(_cbBalInCur(b, b.currency), b.currency);
        optionsHTML += '<option value="' + b.id + '">' + label + '</option>';
    });
    fromSel.innerHTML = optionsHTML;
    toSel.innerHTML = optionsHTML;
    var amt = document.getElementById('inj-cb-amount'); if (amt) amt.value = '';
    var rate = document.getElementById('inj-cb-rate'); if (rate) rate.value = '';
    var res = document.getElementById('inj-cb-result'); if (res) res.value = '';
}

function _recalcInjected() {
    var amount = parseFloat(document.getElementById('inj-cb-amount').value) || 0;
    var rate = parseFloat(document.getElementById('inj-cb-rate').value) || 0;
    var opEl = document.querySelector('input[name="inj-cb-op"]:checked');
    var op = opEl ? opEl.value : 'multiply';
    var result = 0;
    if (rate > 0 && amount > 0) {
        result = (op === 'divide') ? (amount / rate) : (amount * rate);
    } else if (rate === 0 && amount > 0) {
        result = amount;
    }
    var resEl = document.getElementById('inj-cb-result');
    if (resEl) resEl.value = result ? formatNumber(Math.round(result * 100) / 100) : '';
}

function _executeInjectedTransfer() {
    var fromId = document.getElementById('inj-cb-from').value;
    var toId = document.getElementById('inj-cb-to').value;
    var amount = parseFloat(document.getElementById('inj-cb-amount').value) || 0;
    var rate = parseFloat(document.getElementById('inj-cb-rate').value) || 0;
    var opEl = document.querySelector('input[name="inj-cb-op"]:checked');
    var op = opEl ? opEl.value : 'multiply';

    if (!fromId)  { showMessage('خطا', 'لطفاً حساب اول را انتخاب کنید.'); return; }
    if (!toId)    { showMessage('خطا', 'لطفاً حساب مقصد را انتخاب کنید.'); return; }
    if (fromId == toId) { showMessage('خطا', 'حساب مبدأ و مقصد نمی‌توانند یکی باشند.'); return; }
    if (amount <= 0) { showMessage('خطا', 'مبلغ باید بزرگ‌تر از صفر باشد.'); return; }

    var boxes = db.getCashboxes() || [];
    var fromBox = boxes.find(function(b) { return b.id == fromId; });
    var toBox = boxes.find(function(b) { return b.id == toId; });
    if (!fromBox || !toBox) { showMessage('خطا', 'حساب یافت نشد.'); return; }
    if ((parseFloat(fromBox.balance) || 0) < amount) { showMessage('خطا', 'موجودی کافی نیست.'); return; }

    var finalAmount = (rate > 0) ? (op === 'divide' ? (amount / rate) : (amount * rate)) : amount;
    var newFromBalance = (parseFloat(fromBox.balance) || 0) - amount;
    var newToBalance = (parseFloat(toBox.balance) || 0) + finalAmount;

    var doUpdate = function(id, patch) {
        if (typeof db.updateCashbox === 'function') return db.updateCashbox(id, patch);
        var box = (db.getCashboxes() || []).find(function(c) { return c.id == id; });
        if (!box) return { success: false };
        return db.saveCashbox(Object.assign({}, box, patch));
    };

    var r1 = doUpdate(fromBox.id, { balance: newFromBalance });
    if (!r1 || r1.success === false) { showMessage('خطا', 'خطا در حساب مبدأ'); return; }
    var r2 = doUpdate(toBox.id, { balance: newToBalance });
    if (!r2 || r2.success === false) {
        doUpdate(fromBox.id, { balance: parseFloat(fromBox.balance) || 0 });
        showMessage('خطا', 'خطا در حساب مقصد');
        return;
    }

    if (typeof addChangelog === 'function') {
        addChangelog('انتقال', 'صندوق', {
            fromId: fromBox.id, fromName: fromBox.name, toId: toBox.id, toName: toBox.name,
            amount: amount, rate: rate, op: op, finalAmount: finalAmount
        }, 'انتقال ' + formatAmountWithCurrency(amount, fromBox.currency) + ' از ' + fromBox.name + ' به ' + toBox.name);
    }

    showMessage('موفقیت', 'انتقال با موفقیت انجام شد.');
    _showInjectedTransferPanel(); // close
    if (typeof loadCashboxes === 'function') loadCashboxes();
    if (typeof renderCashboxesList === 'function') renderCashboxesList();
}

// 3. تزریق دکمه‌های برگشت در همه section‌هایی که ندارند
function _injectMissingBackButtons() {
    var sectionsNeedingBack = {
        'financial': 'dashboard',
        'expenses': 'dashboard',
        'cash-boxes': 'dashboard',
        'reports': 'dashboard',
        'employee-management': 'dashboard',
        'settings': 'dashboard',
        'backup': 'dashboard',
        'print-settings': 'dashboard'
    };

    Object.keys(sectionsNeedingBack).forEach(function(sectionId) {
        var section = document.getElementById(sectionId);
        if (!section) return;

        // اگر دکمه برگشت در این section از قبل وجود دارد، رد شو
        if (section.querySelector('.btn-back-header')) return;

        var returnTo = sectionsNeedingBack[sectionId];

        // پیدا کردن اولین h2 یا h3 برای اضافه کردن دکمه به ابتدای آن
        var titleEl = section.querySelector('.section-header h2, .section-title-in-filter');
        if (!titleEl) {
            // اگر هیچ عنوانی نیست، یک header جدید درج کن
            var newHeader = document.createElement('div');
            newHeader.className = 'section-header';
            newHeader.style.cssText = 'padding:14px 20px;display:flex;align-items:center;gap:10px;';
            newHeader.innerHTML = '<button class="btn-back-header" onclick="showSection(\'' + returnTo + '\')" title="برگشت" style="background:#6366f1;color:#fff;border:1px solid #6366f1;width:36px;height:36px;border-radius:8px;display:inline-flex;align-items:center;justify-content:center;cursor:pointer;flex-shrink:0;box-shadow:0 2px 6px rgba(99,102,241,0.25);padding:0;"><i class="fas fa-arrow-right" style="color:#fff;font-size:14px;"></i></button>';
            section.insertBefore(newHeader, section.firstChild);
            return;
        }

        // درج دکمه به ابتدای عنوان
        var btnHTML = '<button class="btn-back-header" onclick="showSection(\'' + returnTo + '\')" title="برگشت" style="background:#6366f1;color:#fff;border:1px solid #6366f1;width:36px;height:36px;border-radius:8px;margin-left:10px;display:inline-flex;align-items:center;justify-content:center;cursor:pointer;flex-shrink:0;box-shadow:0 2px 6px rgba(99,102,241,0.25);padding:0;vertical-align:middle;"><i class="fas fa-arrow-right" style="color:#fff;font-size:14px;"></i></button>';
        titleEl.insertAdjacentHTML('afterbegin', btnHTML);
    });
}

// اجرای همه تزریق‌ها — چندین بار برای اطمینان
function _runAllInjections() {
    // هنگامِ تایپِ کاربر اجرا نشو — تزریقِ DOM باعثِ از دست رفتنِ فوکوس و
    // «هنگ کردنِ» ظاهریِ فرم می‌شد.
    try {
        var _ae = document.activeElement;
        if (_ae) {
            var _t = (_ae.tagName || '').toLowerCase();
            if (_t === 'input' || _t === 'textarea' || _ae.isContentEditable) return;
        }
        if (window._lastTypingAt && (Date.now() - window._lastTypingAt) < 600) return;
    } catch (e) {}
    try { _injectFinTransferButton(); } catch(e) { console.error('inject transfer btn:', e); }
    try { _injectMissingBackButtons(); } catch(e) { console.error('inject back btns:', e); }
    try { _ensureBackButtonsVisible(); } catch(e) {}
}

