// --- مدیریت حالت Picker برای انتخاب جنس ---
let currentPickerCallback = null;
let previousSectionForPicker = 'dashboard';

// این تابع را زمانی که کاربر روی دکمه "انتخاب جنس از فهرست" کلیک می‌کند صدا بزنید
function openProductPicker(returnSection, callback) {
    previousSectionForPicker = returnSection;
    currentPickerCallback = callback;
    
    // باز کردن صفحه لیست اجناس
    showSection('products-list');
    
    // پیدا کردن دکمه برگشت در هدر لیست اجناس
    const backBtn = document.querySelector('#products-list .btn-back-header');
    if (backBtn) {
        // ذخیره رویداد کلیک اصلی تا بعداً برگردانده شود
        backBtn.dataset.originalOnclick = backBtn.getAttribute('onclick') || "showSection('dashboard')";
        
        // اضافه کردن کلاس انیمیشن و تغییر رویداد کلیک
        backBtn.classList.add('picker-mode-active');
        backBtn.setAttribute('onclick', `cancelProductPicker('${returnSection}')`);
        backBtn.title = 'برگشت به فرم قبلی';
    }
}

// لغو حالت انتخاب و برگشت به فرم قبلی
function cancelProductPicker(returnSection) {
    resetProductPickerMode();
    showSection(returnSection);
}

// بازگردانی دکمه برگشت به حالت عادی
function resetProductPickerMode() {
    const backBtn = document.querySelector('#products-list .btn-back-header');
    if (backBtn && backBtn.classList.contains('picker-mode-active')) {
        backBtn.classList.remove('picker-mode-active');
        const origOnclick = backBtn.dataset.originalOnclick;
        backBtn.setAttribute('onclick', origOnclick);
        backBtn.title = 'برگشت';
    }
    currentPickerCallback = null;
}

// در تابعِ موجودِ شما که روی ردیف‌های جدول برای انتخاب کلیک می‌شود، این را اضافه کنید:
function selectProductFromPicker(productData) {
    if (currentPickerCallback) {
        currentPickerCallback(productData); // ارسال دیتا به فرم قبلی
        let returnTo = previousSectionForPicker;
        resetProductPickerMode(); // خاموش کردن انیمیشن
        showSection(returnTo);    // برگشت به فرم
    }
}


