function showCashboxWithdrawForm(cashboxId) {
    const cashboxes = db.getCashboxes() || [];
    const sourceBox = cashboxes.find(function(c){ return c.id == cashboxId; });
    if (!sourceBox) { showMessage('خطا', 'حساب یافت نشد'); return; }

    const section = document.getElementById('cashbox-withdraw-form-section');
    if (!section) return;
    section.setAttribute('data-source-cashbox-id', cashboxId);

    showSection('cashbox-withdraw-form-section');

    // پرکردنِ انتخابگرِ ارز با ارزهای تعریف‌شدهٔ سیستم (حساب دیگر ارزِ ثابت ندارد)
    if (typeof _populateCurrencySelect === 'function') _populateCurrencySelect('withdraw-currency');

    // پر کردن لیست حساب منبع
    const fromSel = document.getElementById('withdraw-from-cashbox');
    if (fromSel) {
        fromSel.innerHTML = '<option value="">انتخاب حساب</option>';
        cashboxes.forEach(function(c) {
            const opt = document.createElement('option');
            opt.value = c.id;
            opt.textContent = c.name + ' (' + (typeof getCurrencyLabel === 'function' ? getCurrencyLabel(c.currency) : c.currency) + ') — موجودی: ' + (typeof formatAmountWithCurrency === 'function' ? formatAmountWithCurrency(_cbBalInCur(c, c.currency), c.currency) : c.balance);
            if (c.id == cashboxId) opt.selected = true;
            fromSel.appendChild(opt);
        });
    }

    // پر کردن لیست «به حساب» (اختیاری) — اگر انتخاب شود، برداشت به انتقال تبدیل می‌شود
    const toSel = document.getElementById('withdraw-to-cashbox');
    if (toSel) {
        toSel.innerHTML = '<option value="">بدون انتقال (برداشت بیرونی)</option>';
        cashboxes.forEach(function(c) {
            if (c.id == cashboxId) return; // حساب منبع را در مقصد نگذار
            const opt = document.createElement('option');
            opt.value = c.id;
            opt.textContent = c.name + ' (' + (typeof getCurrencyLabel === 'function' ? getCurrencyLabel(c.currency) : c.currency) + ') — موجودی: ' + (typeof formatAmountWithCurrency === 'function' ? formatAmountWithCurrency(_cbBalInCur(c, c.currency), c.currency) : c.balance);
            toSel.appendChild(opt);
        });
    }

    // خالی کردن فیلدها
    var amtEl = document.getElementById('withdraw-amount');
    if (amtEl) amtEl.value = '';
    var notesEl = document.getElementById('withdraw-notes');
    if (notesEl) notesEl.value = '';

    // مقداردهی تاریخ و ساعت فعلی به‌صورت پیش‌فرض
    // فرمت کامل با ثانیه و AM/PM — همانند سایر فرم‌ها
    var dtEl = document.getElementById('withdraw-datetime');
    if (dtEl) {
        try {
            dtEl.value = (typeof _nowJalaliDateTime === 'function') ? _nowJalaliDateTime() : '';
        } catch(e) { dtEl.value = ''; }
        if (!dtEl._dpAttached) {
            if (typeof _attachDateTimePickerToInput === 'function') {
                _attachDateTimePickerToInput(dtEl);
                dtEl._dpAttached = true;
            }
        }
    }
}

function executeCashboxWithdraw() {
    const sourceId = document.getElementById('withdraw-from-cashbox').value;
    const amount = parseFloat(document.getElementById('withdraw-amount').value) || 0;
    const dt = document.getElementById('withdraw-datetime').value || '';
    const notes = document.getElementById('withdraw-notes').value || '';
    const _wCurEl = document.getElementById('withdraw-currency');
    const wCurrency = _wCurEl ? _wCurEl.value : '';

    if (!sourceId) { showMessage('خطا', 'لطفاً حساب منبع را انتخاب کنید'); return; }
    if (amount <= 0) { showMessage('خطا', 'لطفاً مبلغ معتبر وارد کنید'); return; }
    if (!wCurrency) { showMessage('خطا', 'لطفاً ارز را انتخاب کنید (اگر ارزی تعریف نشده، از کارت نرخ ارز اضافه کنید)'); return; }

    const cashboxes = db.getCashboxes() || [];
    const sourceBox = cashboxes.find(function(c){ return c.id == sourceId; });
    if (!sourceBox) { showMessage('خطا', 'حساب منبع یافت نشد'); return; }

    // اگر «به حساب» انتخاب شده باشد، برداشت به انتقالِ همان ارز بین دو حساب تبدیل می‌شود
    const _toEl = document.getElementById('withdraw-to-cashbox');
    const destId = _toEl ? _toEl.value : '';
    if (destId) {
        if (destId == sourceId) { showMessage('خطا', 'حساب مبدأ و مقصد نمی‌توانند یکی باشند'); return; }
        const destBox = cashboxes.find(function(c){ return c.id == destId; });
        if (!destBox) { showMessage('خطا', 'حساب مقصد یافت نشد'); return; }
        // کسر از مبدأ و افزودن به مقصد با همان ارز
        db.updateCashboxBalance(parseInt(sourceId), amount, 'out', wCurrency);
        db.updateCashboxBalance(parseInt(destId), amount, 'in', wCurrency);
        if (typeof _logCashboxTransaction === 'function') {
            _logCashboxTransaction(parseInt(sourceId), {
                type: 'transfer_out', amount: amount, currency: wCurrency, datetime: dt,
                relatedCashboxId: parseInt(destId), relatedCashboxName: destBox.name, notes: notes,
                description: 'انتقال به صندوق ' + destBox.name
            });
            _logCashboxTransaction(parseInt(destId), {
                type: 'transfer_in', amount: amount, currency: wCurrency, datetime: dt,
                relatedCashboxId: parseInt(sourceId), relatedCashboxName: sourceBox.name, notes: notes,
                description: 'دریافت از صندوق ' + sourceBox.name
            });
        }
        if (typeof addChangelog === 'function') {
            addChangelog('ثبت', 'انتقال بین حساب‌ها', { amount: amount, source: sourceBox.name, dest: destBox.name, currency: wCurrency }, 'انتقال از ' + sourceBox.name + ' به ' + destBox.name);
        }
        showMessage('موفقیت', 'مبلغ با موفقیت از حساب ' + sourceBox.name + ' به حساب ' + destBox.name + ' انتقال یافت.');
        setTimeout(function() {
            showSection('financial');
            setTimeout(function(){ if (typeof switchFinancialTab === 'function') switchFinancialTab('cashbox'); }, 100);
        }, 800);
        return;
    }

    // برداشت بدون توقف به‌خاطر کمبود موجودی انجام می‌شود؛ موجودی می‌تواند منفی شود (به درخواست کاربر).
    // کسر از حساب با ارزِ انتخابی
    db.updateCashboxBalance(parseInt(sourceId), amount, 'out', wCurrency);
    // ثبت در معاملات حساب (دقیقاً برعکس deposit_external)
    if (typeof _logCashboxTransaction === 'function') {
        _logCashboxTransaction(parseInt(sourceId), {
            type: 'withdraw_external',
            amount: amount,
            currency: wCurrency,
            datetime: dt,
            notes: notes,
            description: 'برداشت مبلغ از حساب (خروج خارجی)'
        });
    }

    if (typeof addChangelog === 'function') {
        addChangelog('ثبت', 'برداشت مبلغ از حساب', { amount: amount, source: sourceBox.name, sourceId: sourceBox.id, currency: wCurrency }, 'برداشت مبلغ از حساب ' + sourceBox.name);
    }
    showMessage('موفقیت', 'مبلغ با موفقیت از حساب ' + sourceBox.name + ' برداشت شد.');
    setTimeout(function() {
        showSection('financial');
        setTimeout(function(){ if (typeof switchFinancialTab === 'function') switchFinancialTab('cashbox'); }, 100);
    }, 800);
}

/**
 * ثبت یک رکورد در معاملات حساب (cashboxTransactions در localStorage)
 * این تابع برای deposit/transfer/expense/etc استفاده می‌شود
 */
function _logCashboxTransaction(cashboxId, txData) {
    try {
        var key = 'cashboxTransactions';
        var list = [];
        try { list = JSON.parse(localStorage.getItem(key) || '[]'); } catch(e) { list = []; }
        if (!Array.isArray(list)) list = [];
        var rec = Object.assign({
            id: Date.now() + Math.floor(Math.random() * 1000),
            cashboxId: cashboxId,
            createdAt: new Date().toISOString()
        }, txData || {});
        list.push(rec);
        localStorage.setItem(key, JSON.stringify(list));
    } catch(e) { console.error('logCashboxTransaction error:', e); }
}

/**
 * Picker تاریخ و ساعت برای فیلد datetime
 * این تابع از datepicker شمسی موجود استفاده می‌کند و یک selector ساعت اضافه می‌کند
 */
function _attachDateTimePickerToInput(input) {
    if (!input) return;
    // ===== تبدیل input[type=date] به متنی =====
    if (input.type === 'date') {
        input.type = 'text';
        input.classList.add('jalali-date');
    }

    // ===== ست کردن مقدار پیش‌فرض و placeholder (فرمت ۱۲ ساعته افغانستان با ثانیه) =====
    try {
        var _afghD = _getAfghNow();
        var _todayVal = new PersianDate(_afghD).format('YYYY/MM/DD');
        var _h24 = _afghD.getHours();
        var _ampm = _h24 >= 12 ? 'PM' : 'AM';
        var _h12 = _h24 % 12; if (_h12 === 0) _h12 = 12;
        var _mm = _afghD.getMinutes() < 10 ? '0' + _afghD.getMinutes() : '' + _afghD.getMinutes();
        var _ss = _afghD.getSeconds() < 10 ? '0' + _afghD.getSeconds() : '' + _afghD.getSeconds();
        var _todayDateTimeVal = _todayVal + ' ' + _h12 + ':' + _mm + ':' + _ss + ' ' + _ampm;
        // اگر فیلد خالی است و فیلد اختیاری/no-default نیست، تاریخ + ساعت امروز را درج کن
        var _skipDefault = input.dataset.noDefault === '1'
            || input.classList.contains('jalali-date-optional');
        if (!input.value && !_skipDefault) {
            input.value = _todayDateTimeVal;
        }
        if (!input.placeholder || input.placeholder === 'YYYY/MM/DD') {
            input.placeholder = _todayDateTimeVal || '1404/01/01 12:00:00 AM';
        }
    } catch(e) {}
    input.removeAttribute('readonly');

    // ===== keyup: فقط ارقام، AM/PM، اسلش، دونقطه و فاصله مجاز (و نشانگر م برای تاریخ میلادی) =====
    if (!input._dpKeyupBound) {
        input._dpKeyupBound = true;
        input.addEventListener('keyup', function() {
            this.value = this.value.replace(/[^0-9۰-۹٠-٩APMapmم\/: ]/g, '');
        });
    }

    // ساخت آیکن تاریخ مشابه jalali-date
    var wrap = input.parentElement;
    if (!wrap) return;
    if (wrap.classList && wrap.classList.contains('jalali-datetime-wrapper')) return; // قبلاً نصب شده
    // اگر در والد یک دکمه‌ی تقویم با عملکرد موجود است (HTML اصلی)، آیکن تزئینی اضافه نکن
    // تا فیلد دارای دو آیکن تکراری نشود — فقط دکمه عملکرددار حفظ شود
    if (wrap.querySelector && wrap.querySelector('button[onclick*="openDualCalendarPicker"], button[onclick*="openDateOnlyCalendarPicker"]')) {
        return;
    }

    // ایجاد wrapper
    var wrapper = document.createElement('div');
    wrapper.className = 'jalali-datetime-wrapper';
    wrapper.style.cssText = 'position:relative;display:flex;align-items:center;';
    input.parentNode.insertBefore(wrapper, input);
    wrapper.appendChild(input);
    input.style.flex = '1';
    input.style.paddingLeft = '36px';

    // دکمه آیکن تاریخ — فقط نمایشی، بدون عملکرد (کاربر مستقیم تایپ می‌کند)
    var btn = document.createElement('button');
    btn.type = 'button';
    btn.className = 'jalali-datetime-btn';
    btn.innerHTML = '<i class="fas fa-calendar-alt"></i>';
    btn.style.cssText = 'position:absolute;left:6px;top:50%;transform:translateY(-50%);background:transparent;border:none;color:var(--primary,#6366f1);padding:4px 8px;font-size:14px;cursor:default;pointer-events:none;';
    wrapper.appendChild(btn);
}

/**
 * نمایش picker تاریخ + ساعت برای یک input
 * فرمت ساعت: ۱۲ ساعته افغانستان با ثانیه — H:MM:SS AM/PM
 */
function _showDateTimePicker(input) {
    // باز کردن datepicker شمسی موجود — ولی فقط بخش تاریخ
    // پس از انتخاب تاریخ، یک panel ساعت کوچک اضافه می‌کنیم
    _dpTarget = input;
    var existing = document.getElementById('_dp_wrap');
    if (existing) { _closeDp(); return; }

    // بخش‌بندی مقدار فعلی: «YYYY/MM/DD H:MM:SS AM/PM» (یا «YYYY/MM/DD HH:MM» قدیمی)
    var raw = (input.value || '').trim();
    // تبدیل ارقام فارسی/عربی به انگلیسی برای پارس مطمئن
    var rawEn = raw;
    try { if (typeof toEnglishDigits === 'function') rawEn = toEnglishDigits(raw); } catch(_) {}
    var firstSpace = rawEn.indexOf(' ');
    var dStr = firstSpace === -1 ? rawEn : rawEn.substring(0, firstSpace);
    var tStr = firstSpace === -1 ? '' : rawEn.substring(firstSpace + 1).trim();
    var dParts = dStr.split('/');
    var todayP = new PersianDate(_getAfghNow()).format('YYYY/MM/DD').split('/');
    var y = parseInt(dParts[0]) || parseInt(todayP[0]);
    var m = parseInt(dParts[1]) || parseInt(todayP[1]);
    var d = parseInt(dParts[2]) || parseInt(todayP[2]);

    // فلگ ویژه برای datetime: بعد از انتخاب تاریخ، ساعت را هم اضافه کن
    input._isDateTime = true;

    _renderDp(y, m, d);

    // پس از رندر datepicker، تب میلادی + سکشن ساعت اضافه کن
    setTimeout(function() {
        var wrap = document.getElementById('_dp_wrap');
        if (!wrap || wrap.querySelector('.dp-time-section')) return;

        // ====== تب‌های Jalali / Gregorian — در بالای کلیندر ======
        var tabBar = document.createElement('div');
        tabBar.className = 'dp-tab-bar';
        tabBar.style.cssText = 'display:flex;background:#f4f3ff;border-bottom:1px solid #e0e7ff;';
        tabBar.innerHTML =
            '<button type="button" class="dp-tab-jalali" style="flex:1;padding:8px;background:linear-gradient(135deg,#5b4fcf,#7c6fef);color:#fff;border:none;cursor:pointer;font-family:inherit;font-size:12px;font-weight:700;">' +
                '<i class="fas fa-calendar-alt"></i> افغانستان' +
            '</button>' +
            '<button type="button" class="dp-tab-gregorian" style="flex:1;padding:8px;background:transparent;color:#5b4fcf;border:none;cursor:pointer;font-family:inherit;font-size:12px;font-weight:700;">' +
                '<i class="fas fa-globe"></i> میلادی' +
            '</button>';
        // درج tabBar در ابتدای wrap (قبل از هدر)
        wrap.insertBefore(tabBar, wrap.firstChild);

        // ====== سکشن ساعت (همیشه پایین) — ۱۲ ساعته با ثانیه ======
        var timeSec = document.createElement('div');
        timeSec.className = 'dp-time-section';
        timeSec.style.cssText = 'padding:10px;border-top:1px solid #e8e8e8;background:#f8fafc;';

        // پارس ساعت + دقیقه + ثانیه + AM/PM
        // پشتیبانی از فرمت‌های: «3:24:22 PM»، «03:24 PM»، «14:30» (۲۴ ساعته قدیمی)، «14:30:45»
        var _h12 = NaN, _mm = NaN, _ss = NaN, _isPM = false;
        var _ampmFound = false;
        if (tStr) {
            // جدا کردن قسمت AM/PM (به انگلیسی یا فارسی)
            var _ampmMatch = tStr.match(/\b(AM|PM|am|pm)\b/);
            if (_ampmMatch) {
                _ampmFound = true;
                _isPM = (_ampmMatch[1].toUpperCase() === 'PM');
            } else if (tStr.indexOf('بعد') > -1) {
                _ampmFound = true; _isPM = true;
            } else if (tStr.indexOf('قبل') > -1) {
                _ampmFound = true; _isPM = false;
            }
            // استخراج عدد ساعت/دقیقه/ثانیه
            var _timeOnly = tStr.replace(/\b(AM|PM|am|pm)\b/g, '').replace(/[^\d:]/g, '').trim();
            var _tParts = _timeOnly.split(':');
            var _hRaw = parseInt(_tParts[0]);
            _mm = parseInt(_tParts[1]);
            _ss = parseInt(_tParts[2]);
            if (!isNaN(_hRaw)) {
                if (_ampmFound) {
                    // ۱۲ ساعته
                    _h12 = _hRaw % 12; if (_h12 === 0) _h12 = 12;
                } else {
                    // ۲۴ ساعته قدیمی — تبدیل به ۱۲ ساعته
                    _isPM = _hRaw >= 12;
                    _h12 = _hRaw % 12; if (_h12 === 0) _h12 = 12;
                }
            }
        }
        if (isNaN(_h12)) {
            var _nowFb = _getAfghNow();
            var _h24Fb = _nowFb.getHours();
            _isPM = _h24Fb >= 12;
            _h12 = _h24Fb % 12; if (_h12 === 0) _h12 = 12;
            _mm = _nowFb.getMinutes();
            _ss = _nowFb.getSeconds();
        }
        if (isNaN(_mm)) _mm = 0;
        if (isNaN(_ss)) _ss = 0;

        timeSec.innerHTML =
            '<div style="display:flex;align-items:center;gap:5px;flex-wrap:wrap;justify-content:center;">' +
                '<i class="fas fa-clock" style="color:#6366f1;"></i>' +
                '<span style="font-weight:700;font-size:12px;color:#334155;">ساعت:</span>' +
                '<input type="number" id="_dp_hour" min="1" max="12" value="' + _h12 + '" style="width:46px;padding:4px 4px;border:1px solid #cbd5e1;border-radius:6px;text-align:center;">' +
                '<span style="font-weight:700;color:#334155;">:</span>' +
                '<input type="number" id="_dp_min" min="0" max="59" value="' + _mm + '" style="width:46px;padding:4px 4px;border:1px solid #cbd5e1;border-radius:6px;text-align:center;">' +
                '<span style="font-weight:700;color:#334155;">:</span>' +
                '<input type="number" id="_dp_sec" min="0" max="59" value="' + _ss + '" style="width:46px;padding:4px 4px;border:1px solid #cbd5e1;border-radius:6px;text-align:center;">' +
                '<select id="_dp_ampm" style="padding:4px 6px;border:1px solid #cbd5e1;border-radius:6px;font-family:inherit;font-size:12px;">' +
                    '<option value="AM"' + (!_isPM ? ' selected' : '') + '>AM</option>' +
                    '<option value="PM"' + (_isPM ? ' selected' : '') + '>PM</option>' +
                '</select>' +
            '</div>';
        wrap.appendChild(timeSec);

        // ====== نمایش معادل میلادی ماه/سال جاری (همیشه پایین، در تب جلالی) ======
        var gregSec = document.createElement('div');
        gregSec.className = 'dp-greg-section';
        gregSec.style.cssText = 'padding:6px 10px;background:#eef2ff;border-top:1px solid #e0e7ff;text-align:center;font-size:11px;color:#4f46e5;font-weight:600;';
        try {
            var _gregMonthNames = ['جنوری','فبروری','مارچ','اپریل','می','جون','جولای','آگست','سپتمبر','اکتبر','نوامبر','دسمبر'];
            var _jtg = (typeof window !== 'undefined' && typeof window._jalaliToGregorian === 'function') ? window._jalaliToGregorian : null;
            var _gregFirst = _jtg ? _jtg(y, m, 1) : null;
            var _gregLast = _jtg ? _jtg(y, m, (m <= 6 ? 31 : (m <= 11 ? 30 : 29))) : null;
            if (_gregFirst && _gregLast) {
                var _g1mn = _gregMonthNames[_gregFirst.getMonth()];
                var _g2mn = _gregMonthNames[_gregLast.getMonth()];
                var _gregLabel = (_g1mn === _g2mn)
                    ? (_g1mn + ' ' + _gregFirst.getFullYear())
                    : (_g1mn + '/' + _g2mn + ' ' + _gregFirst.getFullYear());
                gregSec.innerHTML = '<i class="fas fa-globe" style="margin-left:4px;"></i> میلادی: ' + _gregLabel;
            }
        } catch(e) {}
        wrap.appendChild(gregSec);

        // ====== Override رفتار خانه‌های روز در گرید جلالی — درج تاریخ + ساعت ======
        var _attachJalaliCellHandlers = function() {
            var grid = wrap.querySelector('div[style*="grid-template-columns: repeat(7"]');
            if (!grid) return;
            var cells = grid.querySelectorAll('div[style*="cursor:pointer"]');
            cells.forEach(function(cell) {
                cell.onclick = function() {
                    var dayText = cell.textContent.trim();
                    var dayN = parseInt(dayText);
                    if (isNaN(dayN)) return;
                    var mmStr = m < 10 ? '0' + m : '' + m;
                    var ddStr = dayN < 10 ? '0' + dayN : '' + dayN;
                    var hourEl = document.getElementById('_dp_hour');
                    var minEl = document.getElementById('_dp_min');
                    var secEl = document.getElementById('_dp_sec');
                    var apEl = document.getElementById('_dp_ampm');
                    var h12v = hourEl ? parseInt(hourEl.value) : 12;
                    var mVal = minEl ? parseInt(minEl.value) : 0;
                    var sVal = secEl ? parseInt(secEl.value) : 0;
                    var ap = apEl ? apEl.value : 'AM';
                    if (isNaN(h12v) || h12v < 1 || h12v > 12) h12v = 12;
                    if (isNaN(mVal) || mVal < 0 || mVal > 59) mVal = 0;
                    if (isNaN(sVal) || sVal < 0 || sVal > 59) sVal = 0;
                    var minStr = mVal < 10 ? '0' + mVal : '' + mVal;
                    var secStr = sVal < 10 ? '0' + sVal : '' + sVal;
                    // فرمت ۱۲ ساعته: H:MM:SS AM/PM
                    input.value = y + '/' + mmStr + '/' + ddStr + ' ' + h12v + ':' + minStr + ':' + secStr + ' ' + ap;
                    if (input.onchange) input.onchange();
                    _closeDp();
                };
            });
        };
        _attachJalaliCellHandlers();

        // ====== تب میلادی: ساخت کلیندر میلادی داخل همان wrap ======
        var jalaliTab = tabBar.querySelector('.dp-tab-jalali');
        var gregorianTab = tabBar.querySelector('.dp-tab-gregorian');

        // نگاشت بخش‌های جلالی برای پنهان/نمایش هنگام تعویض تب
        var jalaliHeader = wrap.children[1]; // بعد از tabBar اولین فرزند هدر است
        var jalaliDaysRow = wrap.children[2]; // ردیف نام روزهای هفته
        var jalaliGrid = wrap.children[3]; // گرید روزها
        var jalaliFooter = wrap.children[4]; // فوتر (دکمه امروز)

        var _renderGregorianView = function(gy, gmIdx, activeGd) {
            // پاک کردن المان‌های میلادی قبلی
            var oldG = wrap.querySelector('.dp-greg-view');
            if (oldG) oldG.remove();

            var gView = document.createElement('div');
            gView.className = 'dp-greg-view';

            // هدر میلادی
            var GMONTHS = ['January','February','March','April','May','June','July','August','September','October','November','December'];
            var GDAYS = ['Sun','Mon','Tue','Wed','Thu','Fri','Sat'];

            var gHdr = document.createElement('div');
            gHdr.style.cssText = 'background:linear-gradient(135deg,#5b4fcf,#7c6fef);padding:12px 10px;display:flex;align-items:center;justify-content:space-between;gap:4px;direction:ltr;';

            var gPrev = document.createElement('button');
            gPrev.innerHTML = '‹';
            gPrev.style.cssText = 'background:rgba(255,255,255,0.18);border:none;color:#fff;width:26px;height:26px;border-radius:50%;cursor:pointer;font-size:15px;display:flex;align-items:center;justify-content:center;flex-shrink:0;';
            gPrev.onclick = function() {
                var nm = gmIdx - 1, ny = gy;
                if (nm < 0) { nm = 11; ny--; }
                _renderGregorianView(ny, nm, null);
            };

            var gNext = document.createElement('button');
            gNext.innerHTML = '›';
            gNext.style.cssText = 'background:rgba(255,255,255,0.18);border:none;color:#fff;width:26px;height:26px;border-radius:50%;cursor:pointer;font-size:15px;display:flex;align-items:center;justify-content:center;flex-shrink:0;';
            gNext.onclick = function() {
                var nm = gmIdx + 1, ny = gy;
                if (nm > 11) { nm = 0; ny++; }
                _renderGregorianView(ny, nm, null);
            };

            var gmSel = document.createElement('select');
            gmSel.style.cssText = 'background:rgba(255,255,255,0.15);border:none;color:#fff;font-size:13px;border-radius:8px;padding:2px 6px;cursor:pointer;font-family:inherit;flex:1;min-width:0;text-align:center;';
            GMONTHS.forEach(function(name, idx) {
                var opt = document.createElement('option');
                opt.value = idx; opt.textContent = name;
                if (idx === gmIdx) opt.selected = true;
                gmSel.appendChild(opt);
            });
            gmSel.onchange = function() { _renderGregorianView(gy, parseInt(this.value), null); };

            var gySel = document.createElement('select');
            gySel.style.cssText = 'background:rgba(255,255,255,0.15);border:none;color:#fff;font-size:13px;border-radius:8px;padding:2px 6px;cursor:pointer;font-family:inherit;flex:1;min-width:0;text-align:center;';
            for (var yi = gy - 10; yi <= gy + 10; yi++) {
                var opt = document.createElement('option');
                opt.value = yi; opt.textContent = yi;
                if (yi === gy) opt.selected = true;
                gySel.appendChild(opt);
            }
            gySel.onchange = function() { _renderGregorianView(parseInt(this.value), gmIdx, null); };

            var gMid = document.createElement('div');
            gMid.style.cssText = 'display:flex;gap:4px;flex:1;min-width:0;';
            gMid.appendChild(gmSel);
            gMid.appendChild(gySel);

            gHdr.appendChild(gPrev);
            gHdr.appendChild(gMid);
            gHdr.appendChild(gNext);
            gView.appendChild(gHdr);

            // ردیف نام روزها
            var gDayRow = document.createElement('div');
            gDayRow.style.cssText = 'display:grid;grid-template-columns:repeat(7,1fr);background:#f4f3ff;direction:ltr;';
            GDAYS.forEach(function(name) {
                var c = document.createElement('div');
                c.textContent = name;
                c.style.cssText = 'text-align:center;padding:7px 0;font-size:10px;color:#8b83d4;font-weight:700;';
                gDayRow.appendChild(c);
            });
            gView.appendChild(gDayRow);

            // گرید روزها
            var gGrid = document.createElement('div');
            gGrid.style.cssText = 'display:grid;grid-template-columns:repeat(7,1fr);padding:6px 8px 8px;gap:2px;direction:ltr;';

            var firstOfMonth = new Date(gy, gmIdx, 1);
            var firstDay = firstOfMonth.getDay(); // 0=Sunday
            var daysInMonth = new Date(gy, gmIdx + 1, 0).getDate();

            // امروز
            var tNow = new Date();
            var tGy = tNow.getFullYear(), tGm = tNow.getMonth(), tGd = tNow.getDate();

            // خانه‌های خالی
            for (var i = 0; i < firstDay; i++) {
                gGrid.appendChild(document.createElement('div'));
            }

            for (var dn = 1; dn <= daysInMonth; dn++) {
                (function(dd) {
                    var cell = document.createElement('div');
                    cell.textContent = dd;
                    var isToday = (gy === tGy && gmIdx === tGm && dd === tGd);
                    var isSel = (activeGd && gy === activeGd[0] && gmIdx === activeGd[1] && dd === activeGd[2]);
                    var base = 'text-align:center;padding:5px 2px;border-radius:50%;cursor:pointer;font-size:12px;line-height:1.6;transition:all .12s;';
                    if (isSel) {
                        cell.style.cssText = base + 'background:linear-gradient(135deg,#5b4fcf,#7c6fef);color:#fff;font-weight:700;';
                    } else if (isToday) {
                        cell.style.cssText = base + 'background:#ede9ff;color:#5b4fcf;font-weight:700;';
                    } else {
                        cell.style.cssText = base + 'color:#444;';
                        cell.onmouseover = function() { this.style.background = '#ede9ff'; this.style.color = '#5b4fcf'; };
                        cell.onmouseout = function() { this.style.background = ''; this.style.color = '#444'; };
                    }
                    cell.onclick = function() {
                        // ذخیره به فرمت میلادی (مطابق درخواست کاربر): YYYY/MM/DD H:MM:SS AM/PM
                        var gmStr = (gmIdx + 1) < 10 ? '0' + (gmIdx + 1) : '' + (gmIdx + 1);
                        var gdStr = dd < 10 ? '0' + dd : '' + dd;
                        var hourEl = document.getElementById('_dp_hour');
                        var minEl = document.getElementById('_dp_min');
                        var secEl = document.getElementById('_dp_sec');
                        var apEl = document.getElementById('_dp_ampm');
                        var h12v = hourEl ? parseInt(hourEl.value) : 12;
                        var mVal = minEl ? parseInt(minEl.value) : 0;
                        var sVal = secEl ? parseInt(secEl.value) : 0;
                        var ap = apEl ? apEl.value : 'AM';
                        if (isNaN(h12v) || h12v < 1 || h12v > 12) h12v = 12;
                        if (isNaN(mVal) || mVal < 0 || mVal > 59) mVal = 0;
                        if (isNaN(sVal) || sVal < 0 || sVal > 59) sVal = 0;
                        var minStr = mVal < 10 ? '0' + mVal : '' + mVal;
                        var secStr = sVal < 10 ? '0' + sVal : '' + sVal;
                        input.value = gy + '/' + gmStr + '/' + gdStr + ' ' + h12v + ':' + minStr + ':' + secStr + ' ' + ap;
                        if (input.onchange) input.onchange();
                        _closeDp();
                    };
                    gGrid.appendChild(cell);
                })(dn);
            }
            gView.appendChild(gGrid);

            // فوتر — دکمه امروز
            var gFtr = document.createElement('div');
            gFtr.style.cssText = 'padding:6px 10px 10px;text-align:center;';
            var gTodayBtn = document.createElement('button');
            gTodayBtn.textContent = '📅 Today';
            gTodayBtn.style.cssText = 'background:linear-gradient(135deg,#5b4fcf,#7c6fef);color:#fff;border:none;border-radius:20px;padding:5px 22px;cursor:pointer;font-family:inherit;font-size:12px;width:100%;';
            gTodayBtn.onclick = function() {
                var n = _getAfghNow();
                var gy2 = n.getFullYear();
                var gm2 = n.getMonth() + 1;
                var gd2 = n.getDate();
                var gmStr = gm2 < 10 ? '0' + gm2 : '' + gm2;
                var gdStr = gd2 < 10 ? '0' + gd2 : '' + gd2;
                var h24 = n.getHours();
                var ap = h24 >= 12 ? 'PM' : 'AM';
                var h12 = h24 % 12; if (h12 === 0) h12 = 12;
                var mn = n.getMinutes();
                var sc = n.getSeconds();
                var minStr = mn < 10 ? '0' + mn : '' + mn;
                var secStr = sc < 10 ? '0' + sc : '' + sc;
                input.value = gy2 + '/' + gmStr + '/' + gdStr + ' ' + h12 + ':' + minStr + ':' + secStr + ' ' + ap;
                if (input.onchange) input.onchange();
                _closeDp();
            };
            gFtr.appendChild(gTodayBtn);
            gView.appendChild(gFtr);

            // درج بعد از tabBar (در جای هدر جلالی)
            wrap.insertBefore(gView, timeSec);
        };

        // عملکرد تب‌ها
        var _switchToJalali = function() {
            jalaliTab.style.background = 'linear-gradient(135deg,#5b4fcf,#7c6fef)';
            jalaliTab.style.color = '#fff';
            gregorianTab.style.background = 'transparent';
            gregorianTab.style.color = '#5b4fcf';
            if (jalaliHeader) jalaliHeader.style.display = '';
            if (jalaliDaysRow) jalaliDaysRow.style.display = '';
            if (jalaliGrid) jalaliGrid.style.display = '';
            if (jalaliFooter) jalaliFooter.style.display = '';
            gregSec.style.display = '';
            var gView = wrap.querySelector('.dp-greg-view');
            if (gView) gView.remove();
        };

        var _switchToGregorian = function() {
            gregorianTab.style.background = 'linear-gradient(135deg,#5b4fcf,#7c6fef)';
            gregorianTab.style.color = '#fff';
            jalaliTab.style.background = 'transparent';
            jalaliTab.style.color = '#5b4fcf';
            if (jalaliHeader) jalaliHeader.style.display = 'none';
            if (jalaliDaysRow) jalaliDaysRow.style.display = 'none';
            if (jalaliGrid) jalaliGrid.style.display = 'none';
            if (jalaliFooter) jalaliFooter.style.display = 'none';
            gregSec.style.display = 'none';
            // محاسبه میلادی متناظر از روی جلالی فعلی
            var _jtg = (typeof window !== 'undefined' && typeof window._jalaliToGregorian === 'function') ? window._jalaliToGregorian : null;
            if (_jtg) {
                var gd = _jtg(y, m, d);
                _renderGregorianView(gd.getFullYear(), gd.getMonth(), [gd.getFullYear(), gd.getMonth(), gd.getDate()]);
            } else {
                var n = new Date();
                _renderGregorianView(n.getFullYear(), n.getMonth(), null);
            }
        };

        jalaliTab.onclick = _switchToJalali;
        gregorianTab.onclick = _switchToGregorian;
    }, 50);
}

// =============================================================================
// ===== نمایش لیست معاملات حساب (همه ورودی/خروجی) =====
// =============================================================================

/**
 * نمایش معاملات یک حساب — این تابع از قبل (showCashboxTransactions) فراخوانی می‌شود
 * در صورت موجود نبودن، یک نسخه پیش‌فرض ارائه می‌دهیم که از cashboxTransactions می‌خواند
 */
if (typeof window.showCashboxTransactions !== 'function') {
    window.showCashboxTransactions = function(cashboxId) {
        var list = [];
        try { list = JSON.parse(localStorage.getItem('cashboxTransactions') || '[]'); } catch(e) { list = []; }
        var related = list.filter(function(t){ return t.cashboxId == cashboxId; });
        var box = (db.getCashboxes() || []).find(function(c){ return c.id == cashboxId; });
        var boxName = box ? box.name : ('حساب ' + cashboxId);

        var html = '<div style="padding:20px;direction:rtl;">';
        html += '<h3 style="margin:0 0 12px;"><i class="fas fa-history"></i> معاملات حساب: ' + boxName + '</h3>';
        if (!related.length) {
            html += '<p style="color:#94a3b8;text-align:center;padding:30px;">هنوز معامله‌ای ثبت نشده است</p>';
        } else {
            html += '<table class="data-table" style="width:100%;border-collapse:collapse;"><thead><tr>'
                + '<th style="padding:8px;border-bottom:2px solid #e2e8f0;">تاریخ</th>'
                + '<th style="padding:8px;border-bottom:2px solid #e2e8f0;">نوع</th>'
                + '<th style="padding:8px;border-bottom:2px solid #e2e8f0;">مبلغ</th>'
                + '<th style="padding:8px;border-bottom:2px solid #e2e8f0;">شرح</th>'
                + '</tr></thead><tbody>';
            related.sort(function(a,b){ return (b.createdAt || '').localeCompare(a.createdAt || ''); });
            related.forEach(function(t) {
                var typeLabel = ({
                    'deposit_in': 'ورود',
                    'deposit_out': 'برداشت',
                    'deposit_external': 'ورود خارجی',
                    'withdraw_external': 'برداشت مبلغ از حساب',
                    'shipping_charge': 'هزینه حمل و نقل',
                    'transfer_in': 'انتقال ورودی',
                    'transfer_out': 'انتقال خروجی',
                    'expense': 'مصرف',
                    'sale': 'فروش',
                    'purchase': 'خرید'
                })[t.type] || t.type || '---';
                var color = (t.type === 'deposit_out' || t.type === 'withdraw_external' || t.type === 'transfer_out' || t.type === 'expense' || t.type === 'purchase' || t.type === 'shipping_charge') ? '#dc2626' : '#10b981';
                html += '<tr>'
                    + '<td style="padding:8px;border-bottom:1px solid #f1f5f9;">' + (t.datetime || (t.createdAt ? t.createdAt.substr(0, 16).replace('T', ' ') : '---')) + '</td>'
                    + '<td style="padding:8px;border-bottom:1px solid #f1f5f9;color:' + color + ';font-weight:600;">' + typeLabel + '</td>'
                    + '<td style="padding:8px;border-bottom:1px solid #f1f5f9;color:' + color + ';font-weight:700;">' + formatNumber(t.amount || 0) + ' ' + getCurrencyLabel(t.currency || _baseCur()) + '</td>'
                    + '<td style="padding:8px;border-bottom:1px solid #f1f5f9;font-size:0.88rem;color:#64748b;">' + (t.description || t.notes || '---') + '</td>'
                    + '</tr>';
            });
            html += '</tbody></table>';
        }
        html += '</div>';

        // نمایش در یک مودال ساده
        var existing = document.getElementById('cashbox-tx-modal');
        if (existing) existing.remove();
        var ov = document.createElement('div');
        ov.id = 'cashbox-tx-modal';
        ov.style.cssText = 'position:fixed;inset:0;background:rgba(15,23,42,0.55);z-index:99998;display:flex;align-items:center;justify-content:center;padding:20px;';
        ov.onclick = function(e) { if (e.target === ov) ov.remove(); };
        var box2 = document.createElement('div');
        box2.style.cssText = 'background:#fff;border-radius:14px;max-width:780px;width:100%;max-height:80vh;overflow:auto;box-shadow:0 12px 40px rgba(0,0,0,0.25);';
        box2.innerHTML = html + '<div style="text-align:center;padding:14px;"><button class="btn-secondary" onclick="document.getElementById(\'cashbox-tx-modal\').remove()" style="padding:8px 24px;">بستن</button></div>';
        ov.appendChild(box2);
        document.body.appendChild(ov);
    };
}


// =============================================================================
// ===== Picker انتخاب معامله برای فرم برگشت =====
// =============================================================================

/**
 * نمایش مودال انتخاب معامله (فروش یا خرید) بر اساس نوع برگشت
 * پس از انتخاب، مبلغ، تاریخ، شماره بل، طرف حساب و ارز خودکار پر می‌شوند
 */
function openReturnTransactionPicker() {
    var returnTypeEl = document.getElementById('return-type');
    var returnType = returnTypeEl ? returnTypeEl.value : '';
    if (!returnType) {
        if (typeof showToast === 'function') showToast('ابتدا نوع برگشت را انتخاب کنید', 'warning');
        else alert('ابتدا نوع برگشت را انتخاب کنید');
        return;
    }
    // تشخیص نوع معامله مرجع
    var txType = (returnType === 'برگشت از فروش') ? 'فروش' : (returnType === 'برگشت از خرید' ? 'خرید' : '');
    if (!txType) {
        if (typeof showToast === 'function') showToast('نوع برگشت نامعتبر', 'error');
        return;
    }

    // گرفتن لیست معاملات
    var transactions = [];
    try {
        transactions = ((typeof db !== 'undefined' && db.getTransactions) ? (db.getTransactions() || []) : [])
            .filter(function(t){ return t.type === txType; });
    } catch(e) { transactions = []; }

    // حذف مودال قبلی
    var existing = document.getElementById('return-tx-picker-modal');
    if (existing) existing.remove();

    var overlay = document.createElement('div');
    overlay.id = 'return-tx-picker-modal';
    overlay.style.cssText = 'position:fixed;inset:0;background:rgba(15,23,42,0.55);z-index:99998;display:flex;align-items:center;justify-content:center;padding:20px;direction:rtl;';
    overlay.onclick = function(e) { if (e.target === overlay) overlay.remove(); };

    var box = document.createElement('div');
    box.style.cssText = 'background:#fff;border-radius:14px;max-width:700px;width:100%;max-height:85vh;display:flex;flex-direction:column;box-shadow:0 12px 40px rgba(0,0,0,0.25);overflow:hidden;';

    // هدر
    var header = document.createElement('div');
    header.style.cssText = 'background:linear-gradient(135deg,#6366f1,#8b5cf6);color:#fff;padding:14px 18px;display:flex;align-items:center;justify-content:space-between;';
    header.innerHTML = '<h3 style="margin:0;font-size:1.05rem;"><i class="fas fa-list"></i> انتخاب ' + (txType === 'فروش' ? 'فروش' : 'خرید') + ' برای برگشت (اختیاری)</h3>'
        + '<button type="button" onclick="document.getElementById(\'return-tx-picker-modal\').remove()" style="background:rgba(255,255,255,0.2);border:none;color:#fff;width:30px;height:30px;border-radius:50%;cursor:pointer;font-size:14px;"><i class="fas fa-times"></i></button>';
    box.appendChild(header);

    // جستجو
    var searchBar = document.createElement('div');
    searchBar.style.cssText = 'padding:10px 14px;border-bottom:1px solid #e2e8f0;';
    searchBar.innerHTML = '<input type="text" id="return-picker-search" placeholder="جستجو در شماره بل، نام طرف حساب، تاریخ..." style="width:100%;padding:8px 12px;border:1px solid #cbd5e1;border-radius:6px;font-family:inherit;">';
    box.appendChild(searchBar);

    // لیست
    var listBox = document.createElement('div');
    listBox.id = 'return-picker-list';
    listBox.style.cssText = 'flex:1;overflow-y:auto;padding:10px 14px;';
    box.appendChild(listBox);

    // فوتر
    var footer = document.createElement('div');
    footer.style.cssText = 'padding:12px 14px;border-top:1px solid #e2e8f0;text-align:center;';
    footer.innerHTML = '<button type="button" class="btn-secondary" onclick="document.getElementById(\'return-tx-picker-modal\').remove()" style="padding:8px 22px;"><i class="fas fa-arrow-right"></i> برگشت بدون انتخاب</button>';
    box.appendChild(footer);

    overlay.appendChild(box);
    document.body.appendChild(overlay);

    // تابع رندر کردن لیست
    function renderList(searchVal) {
        var sv = (searchVal || '').trim().toLowerCase();
        var filtered = transactions;
        if (sv) {
            filtered = transactions.filter(function(t){
                return ((t.billNumber || '').toLowerCase().indexOf(sv) >= 0)
                    || ((t.customerName || t.supplierName || t.personName || '').toLowerCase().indexOf(sv) >= 0)
                    || ((t.date || t.createdAt || '').toLowerCase().indexOf(sv) >= 0);
            });
        }
        if (!filtered.length) {
            listBox.innerHTML = '<p style="color:#94a3b8;text-align:center;padding:20px;">'
                + (transactions.length === 0 ? 'هنوز ' + (txType === 'فروش' ? 'فروشی' : 'خریدی') + ' ثبت نشده است' : 'موردی با این مشخصات یافت نشد')
                + '</p>';
            return;
        }
        // مرتب‌سازی نزولی بر اساس تاریخ
        filtered = filtered.slice().sort(function(a, b) {
            return (b.createdAt || b.date || '').localeCompare(a.createdAt || a.date || '');
        });
        var html = '';
        filtered.forEach(function(t) {
            var amount = parseFloat(t.totalAmount || t.amount || 0);
            var currency = t.currency || _baseCur();
            var curFa = getCurrencyLabel(currency);
            var personName = t.customerName || t.supplierName || t.personName || '---';
            var billNum = t.billNumber || '---';
            var dateStr = (t.date || t.createdAt || '').split(' ')[0] || '---';
            var itemCount = (t.items && t.items.length) ? t.items.length : 0;
            html += '<div class="ret-picker-row" data-tx-id="' + t.id + '" '
                + 'onclick="_selectReturnTransaction(' + t.id + ');" '
                + 'style="padding:10px 12px;border:1px solid #e2e8f0;border-radius:8px;margin-bottom:6px;cursor:pointer;display:flex;align-items:center;justify-content:space-between;transition:all 0.15s;" '
                + 'onmouseover="this.style.background=\'#eef2ff\';this.style.borderColor=\'#6366f1\';" '
                + 'onmouseout="this.style.background=\'\';this.style.borderColor=\'#e2e8f0\';">'
                +   '<div>'
                +     '<div style="font-weight:700;color:#0f172a;font-size:0.95rem;">'
                +       '<i class="fas fa-receipt" style="color:#6366f1;margin-left:5px;"></i> بل ' + billNum + ' — ' + personName
                +     '</div>'
                +     '<div style="font-size:0.78rem;color:#64748b;margin-top:3px;">'
                +       '<i class="fas fa-calendar-alt" style="margin-left:3px;"></i> ' + dateStr
                +       (itemCount ? ' &nbsp;|&nbsp; <i class="fas fa-box"></i> ' + itemCount + ' قلم' : '')
                +     '</div>'
                +   '</div>'
                +   '<div style="text-align:left;">'
                +     '<div style="font-weight:700;color:#10b981;font-size:0.95rem;">' + formatNumber(amount) + ' ' + curFa + '</div>'
                +   '</div>'
                + '</div>';
        });
        listBox.innerHTML = html;
    }
    renderList('');
    var searchInp = document.getElementById('return-picker-search');
    if (searchInp) {
        searchInp.addEventListener('input', function() { renderList(this.value); });
        setTimeout(function(){ searchInp.focus(); }, 50);
    }
}

/**
 * هنگام انتخاب یک معامله، فیلدهای فرم برگشت را خودکار پر می‌کند
 */
function _selectReturnTransaction(txId) {
    var transactions = [];
    try { transactions = (typeof db !== 'undefined' && db.getTransactions) ? (db.getTransactions() || []) : []; } catch(e) { transactions = []; }
    var t = transactions.find(function(x){ return x.id == txId; });
    if (!t) return;

    // پر کردن فیلدها
    var amountEl = document.getElementById('return-amount');
    if (amountEl) amountEl.value = parseFloat(t.totalAmount || t.amount || 0);

    var currencyEl = document.getElementById('return-currency');
    if (currencyEl) currencyEl.value = t.currency || _baseCur();

    var billEl = document.getElementById('return-original-bill');
    if (billEl) billEl.value = t.billNumber || '';

    var dateEl = document.getElementById('return-date');
    if (dateEl && (t.date || t.createdAt)) {
        var dStr = (t.date || t.createdAt || '').split(' ')[0];
        dateEl.value = dStr;
    }

    // پر کردن طرف حساب
    var personSearchEl = document.getElementById('return-person-search');
    var personHiddenEl = document.getElementById('return-person-hidden');
    var personName = t.customerName || t.supplierName || t.personName || '';
    var personId = t.customerId || t.supplierId || t.personId || '';
    if (personSearchEl) personSearchEl.value = personName;
    if (personHiddenEl) personHiddenEl.value = personId;

    // پر کردن حساب اگر معامله حساب داشت
    var cashboxEl = document.getElementById('return-cashbox');
    if (cashboxEl && t.cashboxId) {
        cashboxEl.value = String(t.cashboxId);
    }

    // بستن مودال
    var modal = document.getElementById('return-tx-picker-modal');
    if (modal) modal.remove();

    if (typeof showToast === 'function') {
        showToast('اطلاعات معامله بارگذاری شد', 'success');
    }
}


// =============================================================================
// ===== Picker: انتخاب معامله قبلی برای فرم برگشتی‌ها =====
// =============================================================================

/**
 * نمایش یک مودال شامل معاملات قبلی (فروش یا خرید) بر اساس نوع برگشت.
 * کاربر یک معامله را انتخاب می‌کند و فرم به‌طور خودکار پر می‌شود.
 * با کلیک روی X یا بیرون مودال، فرم دست‌نخورده باقی می‌ماند.
 */
function openReturnTransactionPicker() {
    var typeEl = document.getElementById('return-type');
    var returnType = typeEl ? typeEl.value : '';
    if (!returnType) {
        showMessage('پیغام', 'لطفاً ابتدا نوع برگشت (از فروش / از خرید) را انتخاب کنید');
        return;
    }
    // تعیین نوع معاملات هدف
    var txType = (returnType === 'برگشت از فروش') ? 'فروش' : 'خرید';
    var allTx = (db.getTransactions() || []).filter(function(t){ return t.type === txType; });

    // حذف مودال قبلی اگر باز است
    var existing = document.getElementById('return-tx-picker-modal');
    if (existing) existing.remove();

    var overlay = document.createElement('div');
    overlay.id = 'return-tx-picker-modal';
    overlay.style.cssText = 'position:fixed;inset:0;background:rgba(15,23,42,0.55);z-index:99998;display:flex;align-items:center;justify-content:center;padding:20px;direction:rtl;';
    overlay.onclick = function(e) { if (e.target === overlay) overlay.remove(); };

    var box = document.createElement('div');
    box.style.cssText = 'background:#fff;border-radius:14px;max-width:760px;width:100%;max-height:80vh;display:flex;flex-direction:column;box-shadow:0 12px 40px rgba(0,0,0,0.25);overflow:hidden;';

    // هدر
    var header = document.createElement('div');
    var headerColor = (txType === 'فروش') ? 'linear-gradient(135deg,#3b82f6,#2563eb)' : 'linear-gradient(135deg,#f59e0b,#d97706)';
    header.style.cssText = 'background:' + headerColor + ';color:#fff;padding:14px 18px;display:flex;align-items:center;justify-content:space-between;';
    header.innerHTML = '<h3 style="margin:0;font-size:1.05rem;"><i class="fas fa-list"></i> انتخاب از ' + (txType === 'فروش' ? 'فروش‌های قبلی' : 'خریدهای قبلی') + '</h3>'
        + '<button type="button" onclick="document.getElementById(\'return-tx-picker-modal\').remove()" style="background:rgba(255,255,255,0.2);border:none;color:#fff;width:30px;height:30px;border-radius:50%;cursor:pointer;font-size:14px;"><i class="fas fa-times"></i></button>';
    box.appendChild(header);

    // جستجو
    var searchBar = document.createElement('div');
    searchBar.style.cssText = 'padding:10px 14px;border-bottom:1px solid #e2e8f0;';
    searchBar.innerHTML = '<input type="text" id="return-tx-picker-search" placeholder="جستجوی شماره بل، نام طرف حساب یا جنس..." style="width:100%;padding:8px 12px;border:1px solid #cbd5e1;border-radius:6px;font-family:inherit;">';
    box.appendChild(searchBar);

    // لیست
    var listBox = document.createElement('div');
    listBox.id = 'return-tx-picker-list';
    listBox.style.cssText = 'flex:1;overflow-y:auto;padding:10px 14px;';
    box.appendChild(listBox);

    // فوتر — برگشت بدون انتخاب
    var footer = document.createElement('div');
    footer.style.cssText = 'padding:12px 14px;border-top:1px solid #e2e8f0;text-align:center;display:flex;gap:10px;justify-content:center;';
    footer.innerHTML = '<button type="button" class="btn-secondary" onclick="document.getElementById(\'return-tx-picker-modal\').remove()" style="padding:8px 24px;"><i class="fas fa-arrow-right"></i> برگشت بدون انتخاب</button>';
    box.appendChild(footer);

    overlay.appendChild(box);
    document.body.appendChild(overlay);

    function renderList(searchVal) {
        var sv = (searchVal || '').trim().toLowerCase();
        var filtered = allTx;
        if (sv) {
            filtered = allTx.filter(function(t) {
                var personName = ((txType === 'فروش' ? t.customerName : t.supplierName) || t.personName || '').toLowerCase();
                var bill = (t.billNumber || '').toLowerCase();
                var itemNames = (t.items || []).map(function(it){ return (it.productName || '').toLowerCase(); }).join(' ');
                return bill.indexOf(sv) >= 0 || personName.indexOf(sv) >= 0 || itemNames.indexOf(sv) >= 0;
            });
        }
        if (!filtered.length) {
            listBox.innerHTML = '<p style="color:#94a3b8;text-align:center;padding:20px;">'
                + (allTx.length === 0 ? 'هیچ معامله‌ای ثبت نشده است' : 'موردی با این جستجو یافت نشد')
                + '</p>';
            return;
        }
        // مرتب‌سازی: جدیدترین اول
        filtered.sort(function(a, b) { return (b.createdAt || '').localeCompare(a.createdAt || ''); });
        var html = '';
        filtered.forEach(function(t) {
            var personName = (txType === 'فروش' ? t.customerName : t.supplierName) || t.personName || '---';
            var amount = parseFloat(t.totalAmount || t.amount || 0);
            var curFa = getCurrencyLabel(t.currency || _baseCur());
            var dateStr = (t.date || t.createdAt || '').split('T')[0].split(' ')[0];
            var itemSummary = '';
            if (t.items && Array.isArray(t.items) && t.items.length) {
                var firstItem = t.items[0];
                itemSummary = (firstItem.productName || '') + (t.items.length > 1 ? ' و ' + (t.items.length - 1) + ' جنس دیگر' : '');
            }
            // داده‌ها به‌صورت data-attribute برای انتخاب
            var dataStr = JSON.stringify({
                id: t.id,
                billNumber: t.billNumber || '',
                personName: personName,
                personId: txType === 'فروش' ? (t.customerId || '') : (t.supplierId || ''),
                amount: amount,
                currency: t.currency || _baseCur(),
                items: t.items || []
            }).replace(/"/g, '&quot;');
            html += '<div class="return-tx-picker-row" data-tx="' + dataStr + '" '
                + 'style="padding:10px 12px;border:1px solid #e2e8f0;border-radius:8px;margin-bottom:6px;cursor:pointer;display:flex;align-items:center;justify-content:space-between;transition:all 0.15s;" '
                + 'onmouseover="this.style.background=\'#f0f9ff\';this.style.borderColor=\'#3b82f6\';" '
                + 'onmouseout="this.style.background=\'\';this.style.borderColor=\'#e2e8f0\';" '
                + 'onclick="_selectReturnTransaction(this)">'
                +   '<div style="flex:1;">'
                +     '<div style="font-weight:700;color:#0f172a;font-size:0.95rem;">'
                +       '<span style="color:#6366f1;">بل ' + (t.billNumber || '---') + '</span>'
                +       ' — ' + personName
                +     '</div>'
                +     '<div style="font-size:0.78rem;color:#64748b;margin-top:2px;">'
                +       (dateStr || '---') + (itemSummary ? ' — ' + itemSummary : '')
                +     '</div>'
                +   '</div>'
                +   '<div style="text-align:left;">'
                +     '<div style="font-weight:700;color:#10b981;font-size:0.95rem;">' + formatNumber(amount) + ' ' + curFa + '</div>'
                +   '</div>'
                + '</div>';
        });
        listBox.innerHTML = html;
    }
    renderList('');
    var searchInp = document.getElementById('return-tx-picker-search');
    if (searchInp) {
        searchInp.addEventListener('input', function() { renderList(this.value); });
        setTimeout(function(){ try { searchInp.focus(); } catch(e){} }, 50);
    }
}

/**
 * انتخاب یک معامله از picker — یک sub-modal باز می‌کند تا کاربر یک جنس خاص از آن معامله را انتخاب کند
 */
function _selectReturnTransaction(rowEl) {
    if (!rowEl) return;
    var dataStr = rowEl.getAttribute('data-tx');
    if (!dataStr) return;
    // decode HTML entities back
    var raw = dataStr.replace(/&quot;/g, '"');
    var data;
    try { data = JSON.parse(raw); } catch(e) { console.error('Failed to parse return tx data:', e); return; }

    // اگر معامله اقلام دارد، به کاربر اجازه انتخاب جنس خاص بدهد
    if (data.items && Array.isArray(data.items) && data.items.length > 0) {
        _showReturnItemPicker(data);
        return;
    }
    // اگر اقلام موجود نیست، کل معامله را به‌عنوان مرجع تنظیم کن
    _applyReturnTransactionToForm(data, null);
}

/**
 * نمایش مودال انتخاب جنس خاص از یک معامله (sub-picker)
 */
function _showReturnItemPicker(txData) {
    // حذف مودال picker معامله (اگر باز است)
    var prevModal = document.getElementById('return-tx-picker-modal');
    if (prevModal) prevModal.remove();

    // حذف هرگونه sub-modal قبلی
    var existing = document.getElementById('return-item-picker-modal');
    if (existing) existing.remove();

    var overlay = document.createElement('div');
    overlay.id = 'return-item-picker-modal';
    overlay.style.cssText = 'position:fixed;inset:0;background:rgba(15,23,42,0.55);z-index:99998;display:flex;align-items:center;justify-content:center;padding:20px;direction:rtl;';
    overlay.onclick = function(e) { if (e.target === overlay) overlay.remove(); };

    var box = document.createElement('div');
    box.style.cssText = 'background:#fff;border-radius:14px;max-width:600px;width:100%;max-height:80vh;display:flex;flex-direction:column;box-shadow:0 12px 40px rgba(0,0,0,0.25);overflow:hidden;';

    // هدر
    var header = document.createElement('div');
    header.style.cssText = 'background:linear-gradient(135deg,#8b5cf6,#7c3aed);color:#fff;padding:14px 18px;display:flex;align-items:center;justify-content:space-between;';
    header.innerHTML = '<h3 style="margin:0;font-size:1.05rem;"><i class="fas fa-box"></i> انتخاب جنس برگشتی از بل ' + (txData.billNumber || '') + '</h3>'
        + '<button type="button" onclick="document.getElementById(\'return-item-picker-modal\').remove()" style="background:rgba(255,255,255,0.2);border:none;color:#fff;width:30px;height:30px;border-radius:50%;cursor:pointer;font-size:14px;"><i class="fas fa-times"></i></button>';
    box.appendChild(header);

    // اطلاعات معامله
    var infoBar = document.createElement('div');
    infoBar.style.cssText = 'padding:10px 14px;border-bottom:1px solid #e2e8f0;background:#f8fafc;font-size:0.85rem;color:#64748b;';
    var curFa = getCurrencyLabel(txData.currency || _baseCur());
    infoBar.innerHTML = '<strong>' + (txData.personName || '---') + '</strong> — مبلغ کل: <strong>' + formatNumber(txData.amount || 0) + ' ' + curFa + '</strong>';
    box.appendChild(infoBar);

    // لیست اقلام
    var listBox = document.createElement('div');
    listBox.style.cssText = 'flex:1;overflow-y:auto;padding:10px 14px;';
    var html = '';
    txData.items.forEach(function(it, idx) {
        var lineTotal = (parseFloat(it.price) || 0) * (parseFloat(it.quantity) || 0) - (parseFloat(it.discount) || 0);
        var itemDataStr = JSON.stringify({
            txId: txData.id,
            txBillNumber: txData.billNumber,
            txPersonName: txData.personName,
            txPersonId: txData.personId,
            txCurrency: txData.currency,
            itemIndex: idx,
            productId: it.productId,
            productName: it.productName,
            quantity: it.quantity,
            unit: it.unit,
            price: it.price,
            discount: it.discount,
            total: lineTotal
        }).replace(/"/g, '&quot;');
        html += '<div class="return-item-picker-row" data-item="' + itemDataStr + '" '
            + 'style="padding:10px 12px;border:1px solid #e2e8f0;border-radius:8px;margin-bottom:6px;cursor:pointer;display:flex;align-items:center;justify-content:space-between;transition:all 0.15s;" '
            + 'onmouseover="this.style.background=\'#f5f3ff\';this.style.borderColor=\'#8b5cf6\';" '
            + 'onmouseout="this.style.background=\'\';this.style.borderColor=\'#e2e8f0\';" '
            + 'onclick="_selectReturnItem(this)">'
            +   '<div style="flex:1;">'
            +     '<div style="font-weight:700;color:#0f172a;font-size:0.95rem;">' + (it.productName || '---') + '</div>'
            +     '<div style="font-size:0.78rem;color:#64748b;margin-top:2px;">'
            +       'تعداد: ' + (it.quantity || 1) + ' ' + (it.unit || '') + ' — قیمت واحد: ' + formatNumber(it.price || 0) + ' ' + curFa
            +     '</div>'
            +   '</div>'
            +   '<div style="text-align:left;">'
            +     '<div style="font-weight:700;color:#10b981;font-size:0.95rem;">' + formatNumber(lineTotal) + ' ' + curFa + '</div>'
            +   '</div>'
            + '</div>';
    });
    listBox.innerHTML = html;
    box.appendChild(listBox);

    // فوتر — انتخاب کل معامله یا برگشت بدون انتخاب
    var footer = document.createElement('div');
    footer.style.cssText = 'padding:12px 14px;border-top:1px solid #e2e8f0;text-align:center;display:flex;gap:8px;justify-content:center;flex-wrap:wrap;';
    var txDataStr = JSON.stringify(txData).replace(/"/g, '&quot;');
    footer.innerHTML = ''
        + '<button type="button" class="btn-primary" onclick="_selectAllReturnItems(\'' + encodeURIComponent(JSON.stringify(txData)) + '\')" style="padding:8px 18px;"><i class="fas fa-check-double"></i> کل معامله</button>'
        + '<button type="button" class="btn-secondary" onclick="document.getElementById(\'return-item-picker-modal\').remove(); openReturnTransactionPicker();" style="padding:8px 18px;"><i class="fas fa-arrow-right"></i> برگشت به لیست</button>'
        + '<button type="button" class="btn-secondary" onclick="document.getElementById(\'return-item-picker-modal\').remove()" style="padding:8px 18px;">بستن</button>';
    box.appendChild(footer);

    overlay.appendChild(box);
    document.body.appendChild(overlay);
}

/**
 * انتخاب یک جنس خاص از معامله — فرم را با مبلغ همان جنس پر می‌کند
 */
function _selectReturnItem(rowEl) {
    if (!rowEl) return;
    var dataStr = rowEl.getAttribute('data-item');
    if (!dataStr) return;
    var raw = dataStr.replace(/&quot;/g, '"');
    var item;
    try { item = JSON.parse(raw); } catch(e) { console.error('Failed to parse item data:', e); return; }

    // پر کردن فرم با اطلاعات جنس انتخاب شده
    var billEl = document.getElementById('return-original-bill');
    if (billEl) billEl.value = item.txBillNumber || '';

    var personSearchEl = document.getElementById('return-person-search');
    var personHiddenEl = document.getElementById('return-person-hidden');
    if (personSearchEl) personSearchEl.value = item.txPersonName || '';
    if (personHiddenEl) personHiddenEl.value = item.txPersonId || '';

    var amountEl = document.getElementById('return-amount');
    if (amountEl) amountEl.value = item.total || 0;

    var currencyEl = document.getElementById('return-currency');
    if (currencyEl) currencyEl.value = item.txCurrency || _baseCur();

    // افزودن جزئیات جنس به فیلد توضیحات
    var notesEl = document.getElementById('return-description') || document.getElementById('return-notes');
    if (notesEl) {
        var detail = 'جنس برگشتی: ' + (item.productName || '') + ' × ' + (item.quantity || 1) + ' ' + (item.unit || '') + ' — قیمت واحد: ' + (item.price || 0);
        if (!notesEl.value || notesEl.value.indexOf(detail.substr(0, 30)) < 0) {
            notesEl.value = detail + (notesEl.value ? '\n\n' + notesEl.value : '');
        }
    }

    // بستن مودال
    var modal = document.getElementById('return-item-picker-modal');
    if (modal) modal.remove();

    if (typeof showToast === 'function') showToast('جنس "' + (item.productName || '') + '" انتخاب شد — فرم پر شد', 'success');
}

/**
 * انتخاب کل اقلام معامله — مبلغ کل را در فرم می‌گذارد و همه اقلام را در توضیحات ذکر می‌کند
 */
function _selectAllReturnItems(encodedTxData) {
    try {
        var txData = JSON.parse(decodeURIComponent(encodedTxData));
        _applyReturnTransactionToForm(txData, null);
        var modal = document.getElementById('return-item-picker-modal');
        if (modal) modal.remove();
    } catch(e) { console.error('Failed to apply all items:', e); }
}

/**
 * پر کردن فرم برگشت با یک معامله کامل
 */
function _applyReturnTransactionToForm(data, specificItem) {
    var billEl = document.getElementById('return-original-bill');
    if (billEl) billEl.value = data.billNumber || '';

    var personSearchEl = document.getElementById('return-person-search');
    var personHiddenEl = document.getElementById('return-person-hidden');
    if (personSearchEl) personSearchEl.value = data.personName || '';
    if (personHiddenEl) personHiddenEl.value = data.personId || '';

    var amountEl = document.getElementById('return-amount');
    if (amountEl) amountEl.value = data.amount || 0;

    var currencyEl = document.getElementById('return-currency');
    if (currencyEl) currencyEl.value = data.currency || _baseCur();

    var notesEl = document.getElementById('return-description') || document.getElementById('return-notes');
    if (notesEl && data.items && data.items.length) {
        var itemsList = data.items.map(function(it){
            return '• ' + (it.productName || '') + ' × ' + (it.quantity || 1) + ' ' + (it.unit || '');
        }).join('\n');
        var prefix = 'اقلام بل ' + (data.billNumber || '') + ' (کل معامله):\n' + itemsList;
        if (!notesEl.value || notesEl.value.indexOf(prefix.substr(0, 40)) < 0) {
            notesEl.value = prefix + (notesEl.value ? '\n\n' + notesEl.value : '');
        }
    }

    if (typeof showToast === 'function') showToast('معامله انتخاب شد — فرم پر شد', 'success');
}

// =============================================================================
// ===== اعمال سیستم اعداد روی یک المان خاص (اعمال فوری) =====
// =============================================================================
function applyNumSysToEl(el) {
    if (!el) return;
    var sys = (typeof getNumberSystem === 'function') ? getNumberSystem() : 'fa';
    var val = el.value;
    if (!val || !/[0-9۰-۹٠-٩]/.test(val)) return;
    var en = (typeof toEnglishDigits === 'function') ? toEnglishDigits(val) : val;
    el.value = (sys === 'fa') ? ((typeof toPersianDigits === 'function') ? toPersianDigits(en) : val) : en;
}

// =============================================================================
// ===== واحد پول پیش‌فرض از تنظیمات در همه فرم‌ها =====
// این تابع ارز پیش‌فرض را از تنظیمات می‌خواند و در فرم‌های فعال اعمال می‌کند
// =============================================================================
function applyDefaultCurrencyToForms() {
    try {
        var settings = (typeof db !== 'undefined' && db.getSettings) ? db.getSettings() : {};
        var defaultCurrency = settings.defaultCurrency || _baseCur();
        // فرم‌هایی که select ارز دارند
        var currencySelects = [
            'sales-currency',
            'purchase-currency',
            'receipt-currency',
            'payment-currency',
            'expense-currency',
            'return-currency'
        ];
        currencySelects.forEach(function(id) {
            var el = document.getElementById(id);
            if (el && el.value === '' || (el && el.value === 'AFN' && defaultCurrency !== 'AFN')) {
                // فقط اگر هنوز مقدار خاصی انتخاب نشده یا AFN است
                if (el.querySelector('option[value="' + defaultCurrency + '"]')) {
                    el.value = defaultCurrency;
                }
            }
        });
    } catch(e) { console.error('applyDefaultCurrencyToForms error:', e); }
}

// =============================================================================
// ===== به‌روزرسانی آنی همه بخش‌های UI پس از تغییر در دیتابیس =====
// این تابع wrapper اصلی برای همه عملیات تغییر داده است
// =============================================================================
function _notifyDataChange(type) {
    // به‌روزرسانی داشبورد
    try { if (typeof loadDashboard === 'function') loadDashboard(); } catch(e) {}
    // به‌روزرسانی بخش فعال
    try {
        var activeSection = document.querySelector('.section.active');
        if (!activeSection) return;
        var sid = activeSection.id;
        switch(sid) {
            case 'sales-list': if (typeof loadSalesList === 'function') loadSalesList(); break;
            case 'purchases-list': if (typeof loadPurchasesList === 'function') loadPurchasesList(); break;
            case 'receipts-list': if (typeof loadReceiptsList === 'function') loadReceiptsList(); break;
            case 'payments-list': if (typeof loadPaymentsList === 'function') loadPaymentsList(); break;
            case 'transactions-list': if (typeof loadTransactionsList === 'function') loadTransactionsList(); break;
            case 'products-list': if (typeof loadProductsList === 'function') loadProductsList(); break;
            case 'product-detail': if (typeof _renderProductDetail === 'function' && _currentProductDetailId != null) _renderProductDetail(_currentProductDetailId); break;
            case 'persons-list': if (typeof loadPersonsList === 'function') loadPersonsList(); break;
            case 'person-detail': if (typeof _renderPersonDetail === 'function' && _currentPersonDetailId != null) _renderPersonDetail(_currentPersonDetailId); break;
            case 'changelog-list': if (typeof loadChangelogList === 'function') loadChangelogList(); break;
            case 'financial':
                var activeTab = document.querySelector('.fin-tab.active');
                var tabName = activeTab ? activeTab.getAttribute('data-tab') : 'expenses';
                if (typeof loadFinancialTabContent === 'function') loadFinancialTabContent(tabName);
                break;
        }
    } catch(e) {}
}

// patch کردن undoChange برای اعمال تغییرات آنی
(function() {
    if (window._undoChangePatchedV2) return;
    window._undoChangePatchedV2 = true;
    if (typeof window.undoChange === 'function') {
        var _origUndo = window.undoChange;
        window.undoChange = function(changeId) {
            _origUndo.call(this, changeId);
            // اعمال آنی
            setTimeout(function() {
                try { _notifyDataChange('undo'); } catch(e) {}
                try { if (typeof loadChangelogList === 'function') loadChangelogList(); } catch(e) {}
            }, 100);
        };
    }
})();

// patch کردن saveTransaction برای اعمال تغییرات آنی
(function() {
    if (window._dbPatchedV2 || typeof db === 'undefined') return;
    window._dbPatchedV2 = true;
    var _origSaveTx = db.saveTransaction.bind(db);
    db.saveTransaction = function(tx) {
        var result = _origSaveTx(tx);
        if (result && result.success !== false) {
            setTimeout(function() {
                try { _notifyDataChange('transaction'); } catch(e) {}
            }, 50);
        }
        return result;
    };
    var _origSaveExp = db.saveExpense.bind(db);
    db.saveExpense = function(exp) {
        var result = _origSaveExp(exp);
        if (result && result.success !== false) {
            setTimeout(function() {
                try { _notifyDataChange('expense'); } catch(e) {}
            }, 50);
        }
        return result;
    };
})();

// اعمال خودکار ارز پیش‌فرض در هر بار باز شدن فرم‌ها
document.addEventListener('sectionChanged', function(e) {
    if (!e.detail || !e.detail.sectionId) return;
    var sid = e.detail.sectionId;
    if (['sales-form','purchase-form','receipt-form','payment-form','expense-form'].indexOf(sid) >= 0) {
        setTimeout(applyDefaultCurrencyToForms, 80);
    }
});

console.log('%c✅ پچ یکپارچه‌سازی اعمال شد (ارز پیش‌فرض + آپدیت آنی)', 'background:#059669;color:#fff;padding:6px 12px;border-radius:6px;');

// =============================================================================
// ===== پچ تقویتی: اعمال آنی سیستم اعداد در همه نقاط حساس =====
// این بخش تضمین می‌کند که اعداد در تاریخ، شماره بل، گراف و سایر موقعیت‌ها
// به‌محض هر گونه تغییر، فوراً به سیستم انتخابی کاربر تبدیل شوند.
// =============================================================================
(function() {
    if (window._numSysHardenPatch) return;
    window._numSysHardenPatch = true;

    // تابع جامع: اعمال فوری سیستم اعداد روی کل صفحه
    window.applyNumberSystemNow = function() {
        try {
            if (typeof convertNumberInputsToText === 'function') {
                convertNumberInputsToText(document.body);
            }
            if (typeof applyNumberSystemToDocument === 'function') {
                applyNumberSystemToDocument();
            }
        } catch(e) {}
    };

    // 1) اعمال در زمان تغییر section (داشبورد، فرم‌ها، لیست‌ها)
    document.addEventListener('sectionChanged', function() {
        // چند مرحله‌ای — تا handler های دیگر تمام شوند
        setTimeout(window.applyNumberSystemNow, 30);
        setTimeout(window.applyNumberSystemNow, 200);
        setTimeout(window.applyNumberSystemNow, 600);
    });

    // 2) hook کردن توابع loader های اصلی تا بعد از رندر اعمال شود
    var loaderNames = [
        'loadDashboard', 'loadSalesList', 'loadPurchasesList',
        'loadReceiptsList', 'loadPaymentsList', 'loadTransactionsList',
        'loadProductsList', 'loadPersonsList', 'loadChangelogList',
        'loadServicesList', 'loadProformasList', 'loadFinancialTabContent',
        'loadExpensesList', 'loadCashboxesList', 'loadReturnsList',
        'renderDailyChart', 'renderProfitChart', 'renderInventoryChart'
    ];
    loaderNames.forEach(function(fname) {
        try {
            if (typeof window[fname] === 'function' && !window[fname]._numSysHooked) {
                var orig = window[fname];
                window[fname] = function() {
                    var r = orig.apply(this, arguments);
                    setTimeout(window.applyNumberSystemNow, 20);
                    return r;
                };
                window[fname]._numSysHooked = true;
            }
        } catch(e) {}
    });

    // 3) hook کردن showSection — تا بعد از تغییر بخش بلافاصله اعمال شود
    try {
        if (typeof window.showSection === 'function' && !window.showSection._numSysHooked) {
            var origShowSection = window.showSection;
            window.showSection = function() {
                var r = origShowSection.apply(this, arguments);
                setTimeout(window.applyNumberSystemNow, 30);
                setTimeout(window.applyNumberSystemNow, 250);
                return r;
            };
            window.showSection._numSysHooked = true;
        }
    } catch(e) {}

    // 4) MutationObserver روی attribute changes (value attribute) برای پوشش
    //    موقعیت‌هایی که عدد به‌صورت programmatic در input تنظیم می‌شود
    if (!window._numSysAttrObserver) {
        try {
            window._numSysAttrObserver = new MutationObserver(function(muts) {
                var needs = false;
                muts.forEach(function(m) {
                    if (m.type === 'attributes' && (m.attributeName === 'value' || m.attributeName === 'data-raw')) {
                        needs = true;
                    }
                });
                if (needs) {
                    clearTimeout(window._numSysAttrTimer);
                    window._numSysAttrTimer = setTimeout(window.applyNumberSystemNow, 40);
                }
            });
            window._numSysAttrObserver.observe(document.body, {
                attributes: true,
                subtree: true,
                attributeFilter: ['value', 'data-raw']
            });
        } catch(e) {}
    }

    // 5) hook کردن persian-datepicker (وقتی تاریخ انتخاب می‌شود، فوراً تبدیل کن)
    try {
        if (typeof jQuery !== 'undefined' && jQuery.fn.persianDatepicker) {
            // event delegation: هر تغییر در input.jalali-date را بگیر
            jQuery(document).on('change input', '.jalali-date, input[id$="-date"]', function() {
                setTimeout(window.applyNumberSystemNow, 20);
            });
        }
    } catch(e) {}

    // 6) فراخوانی فوری در زمان لود
    setTimeout(window.applyNumberSystemNow, 0);
    setTimeout(window.applyNumberSystemNow, 300);
    setTimeout(window.applyNumberSystemNow, 1000);
    setTimeout(window.applyNumberSystemNow, 2000);

    console.log('%c✅ پچ تقویت سیستم اعداد فعال شد', 'background:#7c3aed;color:#fff;padding:4px 10px;border-radius:4px;');
})();

// =============================================================================
// ===== پچ تقویتی: آپدیت آنی همه بخش‌ها هنگام تغییر، حذف، ویرایش، و undo =====
// این بخش تضمین می‌کند که تمام لیست‌ها، گراف‌ها و آمارها در همان لحظه
// تغییر آپدیت شوند، بدون نیاز به ریفرش یا بستن اپلیکیشن.
// =============================================================================
(function() {
    if (window._instantUpdatePatch) return;
    window._instantUpdatePatch = true;

    // تابع جامع آپدیت: همه چیز در لحظه — لیست فعال، داشبورد، گراف‌ها
    window._instantUpdateAll = function() {
        try {
            // 1) داشبورد (شامل کارت‌های آمار، گراف‌ها، لیست‌های سریع)
            if (typeof loadDashboard === 'function') {
                try { loadDashboard(); } catch(e) {}
            }
            // 2) چارت‌ها — هر کدام که موجود است
            ['renderDailyChart', 'renderProfitChart', 'renderInventoryChart',
             'renderSalesChart', 'renderTrendChart'].forEach(function(fn){
                try { if (typeof window[fn] === 'function') window[fn](); } catch(e) {}
            });
            // 3) لیست بخش فعال
            var activeSection = document.querySelector('.section.active');
            if (activeSection) {
                var sid = activeSection.id;
                var loaderMap = {
                    'sales-list': 'loadSalesList',
                    'purchases-list': 'loadPurchasesList',
                    'receipts-list': 'loadReceiptsList',
                    'payments-list': 'loadPaymentsList',
                    'transactions-list': 'loadTransactionsList',
                    'products-list': 'loadProductsList',
                    'persons-list': 'loadPersonsList',
                    'changelog-list': 'loadChangelogList',
                    'services-list': 'loadServicesList',
                    'proformas-list': 'loadProformasList',
                    'returns-list': 'loadReturnsList'
                };
                if (loaderMap[sid] && typeof window[loaderMap[sid]] === 'function') {
                    try { window[loaderMap[sid]](); } catch(e) {}
                }
                // مالی — تب فعال
                if (sid === 'financial') {
                    try {
                        var activeTab = document.querySelector('.fin-tab.active');
                        var tabName = activeTab ? activeTab.getAttribute('data-tab') : 'expenses';
                        if (typeof loadFinancialTabContent === 'function') {
                            loadFinancialTabContent(tabName);
                        }
                    } catch(e) {}
                }
                // گزارش — اگر گزارشی در حال نمایش است، با دادهٔ زندهٔ فعلی دوباره تولید شود
                // (بدونِ نیاز به Refresh دستی؛ پس از Import/Restore/Sync/ویرایش خودکار به‌روز می‌شود).
                if (sid === 'reports') {
                    try {
                        if (typeof window._rpRerunLast === 'function') {
                            window._rpRerunLast();
                        } else {
                            var _dt = document.querySelector('#detailed-report-table tbody');
                            if (_dt && _dt.children.length && typeof generateReport === 'function') generateReport();
                        }
                    } catch(e) {}
                }
            }
            // 4) شمارنده موجودی کم
            try { if (db && typeof db.updateLowStockCount === 'function') db.updateLowStockCount(); } catch(e) {}
            // 5) اعمال سیستم اعداد روی محتوای جدید
            setTimeout(function() {
                try { if (typeof window.applyNumberSystemNow === 'function') window.applyNumberSystemNow(); } catch(e) {}
            }, 30);
        } catch(e) { console.error('_instantUpdateAll error:', e); }
    };

    // hook کردن متدهای کلیدی db برای آپدیت آنی
    if (typeof db !== 'undefined') {
        var dbMethods = [
            'saveProduct', 'deleteProduct', 'updateProductStock',
            'savePerson', 'deletePerson',
            'saveTransaction', 'deleteTransaction',
            'saveExpense', 'deleteExpense',
            'saveCashbox', 'deleteCashbox', 'updateCashboxBalance',
            'saveReturn', 'deleteReturn'
        ];
        dbMethods.forEach(function(m) {
            try {
                if (typeof db[m] === 'function' && !db[m]._instantPatched) {
                    var origFn = db[m].bind(db);
                    db[m] = function() {
                        var result = origFn.apply(db, arguments);
                        // اگر موفق بود، آپدیت آنی
                        if (result && (result.success !== false)) {
                            setTimeout(window._instantUpdateAll, 30);
                        } else if (result === undefined) {
                            // برخی متدها چیزی برنمی‌گردانند — بازهم آپدیت کن
                            setTimeout(window._instantUpdateAll, 30);
                        }
                        return result;
                    };
                    db[m]._instantPatched = true;
                }
            } catch(e) {}
        });
    }

    // اتصالِ رویدادِ مشترکِ «تغییرِ داده» به همان مکانیزمِ به‌روزرسانیِ فوری. این رویداد از سوی
    // Import (json-import)، Restore بکاپ (restore-backup)، Sync Pullِ ابری (sync-pull, در sync-layer)
    // و ثبت/حذفِ برگشت‌ها فرستاده می‌شود. با این اتصال، پس از هر ورود/بازیابی/سینک، داشبورد،
    // لیستِ بخشِ فعال و «گزارشِ در حال نمایش» بدونِ Refresh دستی و از همان Source of Truth به‌روز
    // می‌شوند (Debounce برای جلوگیری از اجرای پی‌درپی هنگامِ ورودِ انبوهِ داده در Sync).
    if (!window._jouyaDataChangeWired) {
        window._jouyaDataChangeWired = true;
        var _iuDebounce = null;
        window.addEventListener('jouya-data-change', function () {
            if (_iuDebounce) clearTimeout(_iuDebounce);
            _iuDebounce = setTimeout(function () {
                _iuDebounce = null;
                try { if (typeof window._instantUpdateAll === 'function') window._instantUpdateAll(); } catch (e) {}
            }, 150);
        });
    }
    // hook کردن undoChange — آپدیت کامل بعد از برگشت
    try {
        if (typeof window.undoChange === 'function' && !window.undoChange._instantPatchedV3) {
            var _origUndoV3 = window.undoChange;
            window.undoChange = function(changeId) {
                _origUndoV3.call(this, changeId);
                // آپدیت کامل با تاخیر کم تا سایر hookها فعال شوند
                setTimeout(window._instantUpdateAll, 60);
                setTimeout(window._instantUpdateAll, 250);
            };
            window.undoChange._instantPatchedV3 = true;
        }
    } catch(e) {}

    // hook کردن editPerson, editProduct, editCashbox, editService — برای آپدیت
    // پس از ویرایش از طریق UI
    var editFns = ['editPerson', 'editProduct', 'editCashbox', 'editService',
                   'editTransaction', 'editExpense', 'editReturn',
                   'deletePersonHandler', 'deleteProductHandler', 'deleteServiceHandler'];
    editFns.forEach(function(fn) {
        try {
            if (typeof window[fn] === 'function' && !window[fn]._instantPatched) {
                var orig = window[fn];
                window[fn] = function() {
                    var r = orig.apply(this, arguments);
                    setTimeout(window._instantUpdateAll, 80);
                    return r;
                };
                window[fn]._instantPatched = true;
            }
        } catch(e) {}
    });

    // hook کردن localStorage.setItem برای کلیدهای داده — هر بار داده تغییر کرد، آپدیت کن
    try {
        var origSetItem = localStorage.setItem.bind(localStorage);
        var dataKeys = ['transactions','products','persons','expenses','cashboxes','returns','services','proformas','changelog'];
        var _instantPending = false;
        localStorage.setItem = function(key, value) {
            origSetItem(key, value);
            if (dataKeys.indexOf(key) >= 0 && !_instantPending) {
                _instantPending = true;
                setTimeout(function() {
                    _instantPending = false;
                    try { window._instantUpdateAll(); } catch(e) {}
                }, 50);
            }
        };
    } catch(e) {}

    console.log('%c✅ پچ آپدیت آنی فعال شد (لحظه‌ای — بدون نیاز به ریفرش)', 'background:#0891b2;color:#fff;padding:4px 10px;border-radius:4px;');
})();

// =============================================================================
// ===== درخواست ۳: وارد کردن اجناس انبار از فایل اکسل =====
// این بخش امکان دانلود قالب اکسل + وارد کردن اجناس از فایل اکسل را فراهم می‌کند.
// اجناس وارد شده به انبار موجود اضافه می‌شوند (نه جایگزین).
// =============================================================================

/**
 * دانلود قالب اکسل برای ورود اجناس انبار
 * ستون‌ها دقیقاً مطابق فیلدهای فرم ثبت جنس جدید است.
 */
function ssbDownloadProductsExcelTemplate() {
    try {
        if (typeof XLSX === 'undefined') {
            ssbShowMsg('کتابخانه اکسل لود نشده — لطفاً اتصال اینترنت را بررسی کنید', true);
            return;
        }

        // ستون‌های قالب (مطابق فرم ثبت جنس)
        var headers = [
            'نام جنس',
            'کد یا بارکد',
            'کتگوری اصلی',
            'کتگوری فرعی',
            'واحد شمارش',
            'ضریب تبدیل',
            'موجودی اولیه',
            'حد اقل روز انقضاء',
            'قیمت خرید (افغانی)',
            'قیمت خرید (دالر)',
            'قیمت فروش (افغانی)',
            'قیمت فروش (دالر)',
            'شرح در فاکتور',
            'اطلاعات بیشتر'
        ];

        // چند سطر نمونه برای راهنمایی کاربر
        var sampleRows = [
            ['برنج هندی', 'BR001', 'مواد غذایی', 'برنج', 'کیلوگرم', '', 100, '', 80, 1, 100, 1.2, 'برنج درجه یک', ''],
            ['روغن خوراکی', 'OL001', 'مواد غذایی', 'روغن', 'لیتر', '', 50, 180, 200, 2.5, 250, 3, '', ''],
            ['شامپو', 'SH001', 'لوازم بهداشتی', 'شامپو', 'عدد', '', 30, '', 120, 1.5, 150, 1.8, '', '']
        ];

        var aoa = [headers].concat(sampleRows);
        var ws = XLSX.utils.aoa_to_sheet(aoa);

        // تنظیم عرض ستون‌ها
        ws['!cols'] = headers.map(function(h) { return { wch: Math.max(h.length + 4, 14) }; });

        // RTL برای ورق
        if (!ws['!props']) ws['!props'] = {};
        ws['!props'].RTL = true;

        var wb = XLSX.utils.book_new();
        XLSX.utils.book_append_sheet(wb, ws, 'اجناس انبار');

        // ساخت ورق راهنما
        var helpData = [
            ['راهنمای پر کردن قالب اجناس انبار'],
            [''],
            ['۱- ستون «نام جنس» اجباری است.'],
            ['۲- ستون «واحد شمارش» اجباری است (مثل: عدد، کیلوگرم، لیتر، متر، بسته، حلقه، کارتن، گرم، سانتی‌متر، جریب).'],
            ['۳- اعداد را به انگلیسی یا فارسی وارد کنید — هر دو پشتیبانی می‌شود.'],
            ['۴- اگر کد بارکد نداشتید، خالی بگذارید.'],
            ['۵- اگر جنس همنام در انبار موجود باشد، موجودی به آن اضافه می‌شود (به‌جای ایجاد دوبل).'],
            ['۶- بعد از پر کردن، فایل را ذخیره کنید و از بخش «اکسل/وارد کردن داده» بارگذاری کنید.'],
            [''],
            ['ستون‌های اجباری: نام جنس، واحد شمارش'],
            ['ستون‌های اختیاری: بقیه ستون‌ها — اگر مقدار نداشتید خالی بگذارید.']
        ];
        var wsHelp = XLSX.utils.aoa_to_sheet(helpData);
        wsHelp['!cols'] = [{ wch: 80 }];
        XLSX.utils.book_append_sheet(wb, wsHelp, 'راهنما');

        // تولید فایل و دانلود
        var fileName = 'قالب_اجناس_انبار_' + Date.now() + '.xlsx';
        XLSX.writeFile(wb, fileName);
        ssbShowMsg('قالب اکسل دانلود شد ✓ — لطفاً پر کنید و بارگذاری نمایید');
    } catch(e) {
        console.error('ssbDownloadProductsExcelTemplate error:', e);
        ssbShowMsg('خطا در ساخت قالب: ' + (e.message || ''), true);
    }
}

/**
 * وارد کردن اجناس انبار از فایل اکسل (xlsx یا csv)
 * اجناس به فهرست موجود اضافه می‌شوند، نه جایگزین.
 */
function ssbImportProductsFromExcel() {
    try {
        if (typeof XLSX === 'undefined') {
            ssbShowMsg('کتابخانه اکسل لود نشده', true);
            return;
        }
        var fileInput = document.getElementById('ssb-products-excel-file');
        if (!fileInput || !fileInput.files[0]) {
            ssbShowMsg('فایلی انتخاب نشده!', true);
            return;
        }

        var file = fileInput.files[0];
        var reader = new FileReader();

        reader.onload = function(e) {
            try {
                var data = new Uint8Array(e.target.result);
                var wb = XLSX.read(data, { type: 'array' });
                if (!wb.SheetNames.length) {
                    ssbShowMsg('فایل اکسل خالی است!', true);
                    return;
                }
                // اولین ورق را بخوان (یا «اجناس انبار» اگر موجود است)
                var sheetName = wb.SheetNames[0];
                if (wb.SheetNames.indexOf('اجناس انبار') >= 0) {
                    sheetName = 'اجناس انبار';
                }
                var ws = wb.Sheets[sheetName];
                var rows = XLSX.utils.sheet_to_json(ws, {
                    header: 1,
                    defval: '',
                    raw: false,
                    blankrows: false
                });

                if (!rows.length || rows.length < 2) {
                    ssbShowMsg('فایل خالی است یا فقط هدر دارد!', true);
                    return;
                }

                // پیدا کردن سطر هدر و map ستون‌ها
                var headerRow = rows[0].map(function(c) { return String(c || '').trim(); });

                // map نام ستون‌ها به field key
                var fieldMap = {
                    'نام جنس': 'name',
                    'نام': 'name',
                    'name': 'name',
                    'کد یا بارکد': 'code',
                    'کد': 'code',
                    'بارکد': 'code',
                    'code': 'code',
                    'barcode': 'code',
                    'کتگوری اصلی': 'categoryMain',
                    'کتگوری': 'categoryMain',
                    'category': 'categoryMain',
                    'کتگوری فرعی': 'categorySub',
                    'subcategory': 'categorySub',
                    'واحد شمارش': 'unit',
                    'واحد': 'unit',
                    'unit': 'unit',
                    'ضریب تبدیل': 'conversionFactor',
                    'conversion': 'conversionFactor',
                    'موجودی اولیه': 'initialStock',
                    'موجودی': 'initialStock',
                    'stock': 'initialStock',
                    'حد اقل روز انقضاء': 'minExpiryDays',
                    'روز انقضاء': 'minExpiryDays',
                    'expiry': 'minExpiryDays',
                    'قیمت خرید (افغانی)': 'purchasePriceAFN',
                    'قیمت خرید افغانی': 'purchasePriceAFN',
                    'purchase_afn': 'purchasePriceAFN',
                    'قیمت خرید (دالر)': 'purchasePriceUSD',
                    'قیمت خرید دالر': 'purchasePriceUSD',
                    'purchase_usd': 'purchasePriceUSD',
                    'قیمت فروش (افغانی)': 'salePriceAFN',
                    'قیمت فروش افغانی': 'salePriceAFN',
                    'sale_afn': 'salePriceAFN',
                    'قیمت فروش (دالر)': 'salePriceUSD',
                    'قیمت فروش دالر': 'salePriceUSD',
                    'sale_usd': 'salePriceUSD',
                    'شرح در فاکتور': 'description',
                    'شرح': 'description',
                    'description': 'description',
                    'اطلاعات بیشتر': 'notes',
                    'یادداشت': 'notes',
                    'notes': 'notes'
                };

                var colIdx = {};
                headerRow.forEach(function(h, i) {
                    var key = fieldMap[h] || fieldMap[h.toLowerCase()];
                    if (key) colIdx[key] = i;
                });

                if (colIdx.name === undefined) {
                    ssbShowMsg('ستون «نام جنس» در فایل پیدا نشد!', true);
                    return;
                }

                // helper برای تبدیل عدد فارسی به انگلیسی و parse
                function parseNum(v) {
                    if (v === '' || v === null || v === undefined) return undefined;
                    var s = String(v);
                    if (typeof toEnglishDigits === 'function') s = toEnglishDigits(s);
                    s = s.replace(/[,\s]/g, '');
                    var n = parseFloat(s);
                    return isNaN(n) ? undefined : n;
                }
                function parseStr(v) {
                    if (v === null || v === undefined) return '';
                    return String(v).trim();
                }

                // خواندن اجناس موجود برای تطبیق همنام
                var existing = [];
                try { existing = db.getProducts() || []; } catch(_) { existing = []; }

                var added = 0, merged = 0, skipped = 0, errors = 0;
                var errorDetails = [];

                for (var i = 1; i < rows.length; i++) {
                    var row = rows[i];
                    if (!row || row.every(function(c) { return c === '' || c === null || c === undefined; })) continue;

                    var name = parseStr(row[colIdx.name]);
                    if (!name) { skipped++; continue; }

                    var unit = colIdx.unit !== undefined ? parseStr(row[colIdx.unit]) : '';
                    if (!unit) unit = 'عدد';

                    var stock = colIdx.initialStock !== undefined ? parseNum(row[colIdx.initialStock]) : undefined;
                    if (stock === undefined) stock = 0;

                    var productData = {
                        name: name,
                        unit: unit,
                        code: colIdx.code !== undefined ? parseStr(row[colIdx.code]) : '',
                        categoryMain: colIdx.categoryMain !== undefined ? parseStr(row[colIdx.categoryMain]) : '',
                        categorySub: colIdx.categorySub !== undefined ? parseStr(row[colIdx.categorySub]) : '',
                        conversionFactor: colIdx.conversionFactor !== undefined ? parseNum(row[colIdx.conversionFactor]) : undefined,
                        initialStock: stock,
                        minExpiryDays: colIdx.minExpiryDays !== undefined ? parseNum(row[colIdx.minExpiryDays]) : undefined,
                        purchasePriceAFN: colIdx.purchasePriceAFN !== undefined ? parseNum(row[colIdx.purchasePriceAFN]) : undefined,
                        purchasePriceUSD: colIdx.purchasePriceUSD !== undefined ? parseNum(row[colIdx.purchasePriceUSD]) : undefined,
                        salePriceAFN: colIdx.salePriceAFN !== undefined ? parseNum(row[colIdx.salePriceAFN]) : undefined,
                        salePriceUSD: colIdx.salePriceUSD !== undefined ? parseNum(row[colIdx.salePriceUSD]) : undefined,
                        description: colIdx.description !== undefined ? parseStr(row[colIdx.description]) : '',
                        notes: colIdx.notes !== undefined ? parseStr(row[colIdx.notes]) : ''
                    };

                    // پاک‌سازی فیلدهای undefined
                    Object.keys(productData).forEach(function(k) {
                        if (productData[k] === undefined) delete productData[k];
                    });

                    // بررسی همنام بودن: اگر جنس با همان نام و واحد موجود است، موجودی را اضافه کن
                    var matchIdx = existing.findIndex(function(p) {
                        return p.name && p.name.trim().toLowerCase() === name.toLowerCase()
                               && (p.unit || 'عدد') === unit;
                    });

                    try {
                        if (matchIdx >= 0) {
                            // ادغام: افزایش موجودی + به‌روزرسانی قیمت‌ها در صورت داشتن
                            var existingProduct = existing[matchIdx];
                            var newStock = (parseFloat(existingProduct.stock) || 0) + (parseFloat(stock) || 0);
                            var updateData = {
                                id: existingProduct.id,
                                name: existingProduct.name,
                                unit: existingProduct.unit,
                                initialStock: newStock,
                                stock: newStock
                            };
                            // فقط فیلدهایی که در اکسل پر بودند را آپدیت کن
                            ['code','categoryMain','categorySub','conversionFactor','minExpiryDays',
                             'purchasePriceAFN','purchasePriceUSD','salePriceAFN','salePriceUSD',
                             'description','notes'].forEach(function(f) {
                                if (productData[f] !== undefined && productData[f] !== '') {
                                    updateData[f] = productData[f];
                                }
                            });
                            var res = db.saveProduct(updateData);
                            if (res && res.success) {
                                merged++;
                                // به‌روزرسانی existing برای match های بعدی
                                existing[matchIdx] = res.data;
                            } else {
                                errors++;
                                errorDetails.push('سطر ' + (i+1) + ': ' + (res && res.error ? res.error : 'خطا'));
                            }
                        } else {
                            var res2 = db.saveProduct(productData);
                            if (res2 && res2.success) {
                                added++;
                                existing.push(res2.data);
                            } else {
                                errors++;
                                errorDetails.push('سطر ' + (i+1) + ': ' + (res2 && res2.error ? res2.error : 'خطا'));
                            }
                        }
                    } catch(rowErr) {
                        errors++;
                        errorDetails.push('سطر ' + (i+1) + ': ' + (rowErr.message || ''));
                    }
                }

                // پاک‌سازی input
                fileInput.value = '';

                // پیام نتیجه
                var msg = '✓ پایان: ' + added + ' جنس جدید اضافه شد';
                if (merged > 0) msg += ' • ' + merged + ' جنس موجود به‌روز شد';
                if (skipped > 0) msg += ' • ' + skipped + ' سطر خالی';
                if (errors > 0) msg += ' • ' + errors + ' خطا';
                ssbShowMsg(msg);

                if (errors > 0 && errorDetails.length) {
                    console.warn('خطاهای ورود اکسل:\n' + errorDetails.join('\n'));
                }

                // آپدیت آنی همه چیز
                setTimeout(function() {
                    try { if (typeof window._instantUpdateAll === 'function') window._instantUpdateAll(); } catch(_) {}
                    try { if (typeof loadProductsList === 'function') loadProductsList(); } catch(_) {}
                }, 80);
            } catch(parseErr) {
                console.error('Excel parse error:', parseErr);
                ssbShowMsg('خطا در خواندن فایل اکسل: ' + (parseErr.message || ''), true);
            }
        };

        reader.onerror = function() {
            ssbShowMsg('خطا در خواندن فایل', true);
        };

        reader.readAsArrayBuffer(file);
    } catch(e) {
        console.error('ssbImportProductsFromExcel error:', e);
        ssbShowMsg('خطا: ' + (e.message || ''), true);
    }
}

console.log('%c✅ ورود اجناس از اکسل آماده است', 'background:#dc2626;color:#fff;padding:4px 10px;border-radius:4px;');

// ===== وارد کردن افراد از فایل اکسل (مطابق فیلدهای بخش افراد) =====
/**
 * دانلود قالب اکسل برای ورود افراد
 * ستون‌ها دقیقاً مطابق فیلدهای فرم ثبت فرد جدید است.
 */
function ssbDownloadPersonsExcelTemplate() {
    try {
        if (typeof XLSX === 'undefined') {
            ssbShowMsg('کتابخانه اکسل لود نشده — لطفاً اتصال اینترنت را بررسی کنید', true);
            return;
        }
        var headers = [
            'نام و تخلص',
            'کتگوری',
            'شماره تماس',
            'نمبر تذکره',
            'آدرس',
            'حساب قبلی',
            'نوع حساب',
            'ارز حساب',
            'اطلاعات بیشتر'
        ];
        var sampleRows = [
            ['احمد احمدی', 'مشتری', '0700000000', '1390-1234567', 'کابل، کارته نو', 0, 'بدون حساب', 'افغانی', ''],
            ['شرکت تجارتی نور', 'تامین کننده', '0780000000', '', 'هرات', 5000, 'بدهکار', 'افغانی', 'تامین‌کننده مواد غذایی'],
            ['کریم کریمی', 'فروشنده', '0744444444', '', 'مزار شریف', 120, 'طلبکار', 'دالر', '']
        ];
        var aoa = [headers].concat(sampleRows);
        var ws = XLSX.utils.aoa_to_sheet(aoa);
        ws['!cols'] = headers.map(function(h) { return { wch: Math.max(h.length + 4, 14) }; });
        if (!ws['!props']) ws['!props'] = {};
        ws['!props'].RTL = true;

        var wb = XLSX.utils.book_new();
        XLSX.utils.book_append_sheet(wb, ws, 'افراد');

        var helpData = [
            ['راهنمای پر کردن قالب افراد'],
            [''],
            ['۱- ستون «نام و تخلص» اجباری است.'],
            ['۲- ستون «کتگوری» اجباری است (مقادیر مجاز: مشتری، فروشنده، کارمند، تامین کننده).'],
            ['۳- ستون «نوع حساب» یکی از: بدون حساب، بدهکار، طلبکار.'],
            ['۴- ستون «ارز حساب» یکی از: افغانی، دالر.'],
            ['۵- اگر «حساب قبلی» بزرگ‌تر از صفر باشد، «نوع حساب» را بدهکار یا طلبکار انتخاب کنید.'],
            ['۶- ستون‌های دیگر اختیاری هستند؛ اگر مقدار نداشتید خالی بگذارید.'],
            [''],
            ['ستون‌های اجباری: نام و تخلص، کتگوری'],
            ['ستون‌های اختیاری: بقیه ستون‌ها']
        ];
        var wsHelp = XLSX.utils.aoa_to_sheet(helpData);
        wsHelp['!cols'] = [{ wch: 80 }];
        XLSX.utils.book_append_sheet(wb, wsHelp, 'راهنما');

        var fileName = 'قالب_افراد_' + Date.now() + '.xlsx';
        XLSX.writeFile(wb, fileName);
        ssbShowMsg('قالب اکسل افراد دانلود شد ✓ — لطفاً پر کنید و بارگذاری نمایید');
    } catch(e) {
        console.error('ssbDownloadPersonsExcelTemplate error:', e);
        ssbShowMsg('خطا در ساخت قالب: ' + (e.message || ''), true);
    }
}

/**
 * وارد کردن افراد از فایل اکسل (xlsx یا csv)
 * افراد به فهرست موجود اضافه می‌شوند.
 */
function ssbImportPersonsFromExcel() {
    try {
        if (typeof XLSX === 'undefined') {
            ssbShowMsg('کتابخانه اکسل لود نشده', true);
            return;
        }
        var fileInput = document.getElementById('ssb-persons-excel-file');
        if (!fileInput || !fileInput.files[0]) {
            ssbShowMsg('فایلی انتخاب نشده!', true);
            return;
        }
        var file = fileInput.files[0];
        var reader = new FileReader();

        reader.onload = function(e) {
            try {
                var data = new Uint8Array(e.target.result);
                var wb = XLSX.read(data, { type: 'array' });
                if (!wb.SheetNames.length) { ssbShowMsg('فایل اکسل خالی است!', true); return; }
                var sheetName = wb.SheetNames[0];
                if (wb.SheetNames.indexOf('افراد') >= 0) sheetName = 'افراد';
                var ws = wb.Sheets[sheetName];
                var rows = XLSX.utils.sheet_to_json(ws, { header: 1, defval: '', raw: false, blankrows: false });
                if (!rows.length || rows.length < 2) { ssbShowMsg('فایل خالی است یا فقط هدر دارد!', true); return; }

                var headerRow = rows[0].map(function(c) { return String(c || '').trim(); });
                var fieldMap = {
                    'نام و تخلص': 'name', 'نام': 'name', 'name': 'name',
                    'کتگوری': 'category', 'کتگوری افراد': 'category', 'category': 'category',
                    'شماره تماس': 'phone', 'تلفن': 'phone', 'phone': 'phone',
                    'نمبر تذکره': 'idNumber', 'تذکره': 'idNumber', 'id': 'idNumber', 'idnumber': 'idNumber',
                    'آدرس': 'address', 'address': 'address',
                    'حساب قبلی': 'previousAccount', 'حساب قبلی فرد': 'previousAccount', 'previousaccount': 'previousAccount',
                    'نوع حساب': 'accountType', 'accounttype': 'accountType',
                    'ارز حساب': 'currency', 'ارز': 'currency', 'currency': 'currency',
                    'اطلاعات بیشتر': 'notes', 'یادداشت': 'notes', 'notes': 'notes'
                };
                var colIdx = {};
                headerRow.forEach(function(h, i) {
                    var key = fieldMap[h] || fieldMap[h.toLowerCase()];
                    if (key) colIdx[key] = i;
                });
                if (colIdx.name === undefined) { ssbShowMsg('ستون «نام و تخلص» در فایل پیدا نشد!', true); return; }

                function parseNum(v) {
                    if (v === '' || v === null || v === undefined) return 0;
                    var s = String(v);
                    if (typeof toEnglishDigits === 'function') s = toEnglishDigits(s);
                    s = s.replace(/[,\s]/g, '');
                    var n = parseFloat(s);
                    return isNaN(n) ? 0 : n;
                }
                function parseStr(v) { return (v === null || v === undefined) ? '' : String(v).trim(); }
                function normCurrency(v) {
                    var s = parseStr(v).toLowerCase();
                    if (s === 'usd' || s.indexOf('دالر') >= 0 || s === '$') return 'USD';
                    return 'AFN';
                }
                function normAccountType(v) {
                    var s = parseStr(v);
                    if (s === 'بدهکار' || s === 'طلبکار') return s;
                    return 'بدون حساب';
                }

                var added = 0, skipped = 0, errors = 0;
                var errorDetails = [];

                for (var i = 1; i < rows.length; i++) {
                    var row = rows[i];
                    if (!row || row.every(function(c) { return c === '' || c === null || c === undefined; })) continue;

                    var name = parseStr(row[colIdx.name]);
                    if (!name) { skipped++; continue; }

                    var personData = {
                        name: name,
                        category: colIdx.category !== undefined ? parseStr(row[colIdx.category]) : '',
                        phone: colIdx.phone !== undefined ? parseStr(row[colIdx.phone]) : '',
                        idNumber: colIdx.idNumber !== undefined ? parseStr(row[colIdx.idNumber]) : '',
                        address: colIdx.address !== undefined ? parseStr(row[colIdx.address]) : '',
                        accountType: colIdx.accountType !== undefined ? normAccountType(row[colIdx.accountType]) : 'بدون حساب',
                        currency: colIdx.currency !== undefined ? normCurrency(row[colIdx.currency]) : 'AFN',
                        previousAccount: colIdx.previousAccount !== undefined ? parseNum(row[colIdx.previousAccount]) : 0,
                        notes: colIdx.notes !== undefined ? parseStr(row[colIdx.notes]) : ''
                    };

                    try {
                        var res = db.savePerson(personData);
                        if (res && res.success) { added++; }
                        else { errors++; errorDetails.push('سطر ' + (i+1) + ': ' + (res && res.error ? res.error : 'خطا')); }
                    } catch(rowErr) {
                        errors++; errorDetails.push('سطر ' + (i+1) + ': ' + (rowErr.message || ''));
                    }
                }

                fileInput.value = '';

                var msg = '✓ پایان: ' + added + ' فرد جدید اضافه شد';
                if (skipped > 0) msg += ' • ' + skipped + ' سطر خالی';
                if (errors > 0) msg += ' • ' + errors + ' خطا';
                ssbShowMsg(msg);

                if (errors > 0 && errorDetails.length) {
                    console.warn('خطاهای ورود افراد از اکسل:\n' + errorDetails.join('\n'));
                }

                // آپدیت آنی
                setTimeout(function() {
                    try { if (typeof window._instantUpdateAll === 'function') window._instantUpdateAll(); } catch(_) {}
                    try { if (typeof loadPersonsList === 'function') loadPersonsList(); } catch(_) {}
                    try { if (typeof loadDashboard === 'function') loadDashboard(); } catch(_) {}
                }, 80);
            } catch(parseErr) {
                console.error('Persons excel parse error:', parseErr);
                ssbShowMsg('خطا در خواندن فایل اکسل: ' + (parseErr.message || ''), true);
            }
        };
        reader.onerror = function() { ssbShowMsg('خطا در خواندن فایل', true); };
        reader.readAsArrayBuffer(file);
    } catch(e) {
        console.error('ssbImportPersonsFromExcel error:', e);
        ssbShowMsg('خطا: ' + (e.message || ''), true);
    }
}
console.log('%c✅ ورود افراد از اکسل آماده است', 'background:#3b82f6;color:#fff;padding:4px 10px;border-radius:4px;');


// =============================================================================
// ===== سیستم آپدیت آنی کامل + تقویت سیستم اعداد فارسی  =====================
// این بخش در انتهای فایل قرار می‌گیرد تا روی همه توابع قبلی patch بزند.
// =============================================================================

(function _setupInstantUpdateAndNumSysReinforcement() {
    if (window._instantUpdateAndNumSysInstalled) return;
    window._instantUpdateAndNumSysInstalled = true;

    /* ----------------------------------------------------------------------
     * بخش ۱ — سیستم آپدیت آنی همه‌جانبه
     * هر تغییر در دیتابیس (ثبت/ویرایش/حذف/برگشت) باید در همان لحظه
     * در داشبورد، نمودارها، لیست‌ها، آمارها و سایدبار منعکس شود.
     * -------------------------------------------------------------------- */

    /**
     * این تابع یک "همه‌چیز را آپدیت کن" است:
     * - داشبورد و نمودارهای آن
     * - بخش فعال (sales-list, purchases-list, …)
     * - لیست‌های وابسته (مثل اجناس کم‌موجود، اشخاص بدهکار، …)
     * - changelog
     * - badge های سایدبار
     */
    window._instantUpdateAll = function _instantUpdateAll(reason) {
        try {
            // 1) داشبورد و نمودارها
            try { if (typeof loadDashboard === 'function') loadDashboard(); } catch(_) {}
            try { if (typeof renderDashboardCharts === 'function') renderDashboardCharts(); } catch(_) {}
            try { if (typeof updateDashboardStats === 'function') updateDashboardStats(); } catch(_) {}
            try { if (typeof refreshQuickLists === 'function') refreshQuickLists(); } catch(_) {}
            try { if (typeof loadRecentActivity === 'function') loadRecentActivity(); } catch(_) {}
            try { if (typeof loadDashboardWidgets === 'function') loadDashboardWidgets(); } catch(_) {}

            // 2) بخش فعال
            var activeSection = document.querySelector('.section.active');
            if (activeSection) {
                var sid = activeSection.id;
                var refreshers = {
                    'sales-list':         'loadSalesList',
                    'purchases-list':     'loadPurchasesList',
                    'receipts-list':      'loadReceiptsList',
                    'payments-list':      'loadPaymentsList',
                    'transactions-list':  'loadTransactionsList',
                    'products-list':      'loadProductsList',
                    'persons-list':       'loadPersonsList',
                    'changelog-list':     'loadChangelogList',
                    'services-list':      'loadServicesList',
                    'returns-list':       'loadReturnsList',
                    'reports':            'loadReports',
                    'cashbox-list':       'loadCashboxList',
                    'expenses':           'loadExpensesList',
                    'employee-management':'loadEmployeesList'
                };
                var fn = refreshers[sid];
                if (fn && typeof window[fn] === 'function') {
                    try { window[fn](); } catch(_) {}
                }
                // financial تب‌ها
                if (sid === 'financial') {
                    var activeTab = document.querySelector('.fin-tab.active');
                    var tabName = activeTab ? activeTab.getAttribute('data-tab') : 'expenses';
                    try { if (typeof loadFinancialTabContent === 'function') loadFinancialTabContent(tabName); } catch(_) {}
                }
            }

            // 3) همیشه changelog و آمار جانبی را آپدیت کن (اگر تابع‌شان موجود است)
            try { if (typeof loadChangelogList === 'function' && document.getElementById('changelog-list-tbody')) loadChangelogList(); } catch(_) {}
            try { if (typeof updateLowStockBadge === 'function') updateLowStockBadge(); } catch(_) {}
            try { if (typeof updateSidebarBadges === 'function') updateSidebarBadges(); } catch(_) {}
            // اگر گزارشی باز است (سود و سرمایه، همه بخش‌ها، …) نتایجش را زنده به‌روزرسانی کن
            try { if (typeof refreshOpenReport === 'function') refreshOpenReport(); } catch(_) {}

            // 4) اعمال مجدد سیستم اعداد روی همه چیز
            try {
                if (typeof applyNumberSystemToDocument === 'function') {
                    applyNumberSystemToDocument();
                }
            } catch(_) {}
        } catch(e) {
            console.warn('_instantUpdateAll error:', e);
        }
    };

    // alias کوتاه برای استفاده داخلی
    var _bump = function(reason) {
        // در همان tick بعدی اجرا کن تا state دیتابیس کامل ذخیره شده باشد
        setTimeout(function() { window._instantUpdateAll(reason); }, 0);
        // دو بار دیگر هم برای مطمئن شدن از پوشش async ها
        setTimeout(function() { window._instantUpdateAll(reason); }, 60);
        setTimeout(function() { window._instantUpdateAll(reason); }, 250);
    };

    // patch کردن متدهای دیتابیس
    if (typeof db !== 'undefined' && db) {
        var dbMethodsToWrap = [
            'saveTransaction', 'deleteTransaction',
            'saveExpense', 'deleteExpense',
            'saveProduct', 'deleteProduct', 'updateProductStock',
            'savePerson', 'deletePerson',
            'saveCashbox', 'deleteCashbox', 'updateCashboxBalance',
            'saveReturn', 'deleteReturn',
            'saveSettings', 'updateSettings',
            'saveService', 'deleteService'
        ];
        dbMethodsToWrap.forEach(function(m) {
            if (typeof db[m] === 'function' && !db[m]._instantPatched) {
                var orig = db[m].bind(db);
                db[m] = function() {
                    var result = orig.apply(null, arguments);
                    try { _bump(m); } catch(_) {}
                    return result;
                };
                db[m]._instantPatched = true;
            }
        });
    }

    // patch توابع بالاتر سطح
    var topLevelFnsToWrap = [
        'saveSale', 'savePurchase', 'saveReceipt', 'savePayment',
        'saveExpense', 'saveProduct', 'savePerson', 'saveService',
        'saveCashbox', 'saveReturn',
        'undoChange'
    ];
    topLevelFnsToWrap.forEach(function(name) {
        if (typeof window[name] === 'function' && !window[name]._instantPatched) {
            var orig = window[name];
            window[name] = function() {
                var result = orig.apply(this, arguments);
                try { _bump(name); } catch(_) {}
                return result;
            };
            window[name]._instantPatched = true;
        }
    });

    /* ----------------------------------------------------------------------
     * بخش ۲ — تقویت سیستم اعداد فارسی
     * مشکل قبلی: interval ۲۵۰ms بعضی موقعیت‌ها (تاریخ، شماره بل، نمودارها،
     * بعضی span های programmatic) را با تأخیر می‌گرفت یا اصلاً نمی‌گرفت.
     * راه‌حل:
     *   • interval را به ۱۵۰ms کاهش می‌دهیم
     *   • MutationObserver را روی characterData هم گوش می‌دهیم
     *   • یک تابع forceApplyNumberSystem می‌سازیم که در نقاط حساس فراخوانی شود
     *   • patch کردن showSection / loadDashboard / loadXxxList تا فوراً اعداد تبدیل شوند
     *   • patch کردن innerHTML/textContent setter ها روی المنت‌های کلیدی نیست (overhead)،
     *     ولی hook روی functions اصلی می‌گذاریم
     * -------------------------------------------------------------------- */

    /**
     * اعمال فوری و کامل سیستم اعداد روی کل صفحه — بدون تأخیر.
     * چندبار با delay مختلف اجرا می‌شود تا async render های در حال انجام را هم پوشش دهد.
     */
    window.forceApplyNumberSystem = function forceApplyNumberSystem() {
        try {
            if (typeof applyNumberSystemToDocument !== 'function') return;
            applyNumberSystemToDocument();
            // برای پوشش render های async که هنوز تمام نشده‌اند
            setTimeout(function() {
                try { applyNumberSystemToDocument(); } catch(_) {}
            }, 30);
            setTimeout(function() {
                try { applyNumberSystemToDocument(); } catch(_) {}
            }, 120);
            setTimeout(function() {
                try { applyNumberSystemToDocument(); } catch(_) {}
            }, 350);
        } catch(_) {}
    };

    // کاهش interval موجود به ۱۵۰ms برای پاسخ‌دهی سریع‌تر
    try {
        if (window._numSysInterval) {
            clearInterval(window._numSysInterval);
            window._numSysInterval = null;
        }
        window._numSysInterval = setInterval(function() {
            try {
                if (document.hidden) return;
                if (typeof convertNumberInputsToText === 'function') convertNumberInputsToText(document.body);
                if (typeof applyNumberSystemToDocument === 'function') applyNumberSystemToDocument();
            } catch(_) {}
        }, 150);
    } catch(_) {}

    // patch کردن showSection برای اعمال فوری اعداد بعد از تغییر بخش
    if (typeof window.showSection === 'function' && !window.showSection._numSysPatched) {
        var _origShowSection = window.showSection;
        window.showSection = function() {
            var result = _origShowSection.apply(this, arguments);
            try { window.forceApplyNumberSystem(); } catch(_) {}
            return result;
        };
        window.showSection._numSysPatched = true;
    }

    // patch کردن لودرهای لیست‌ها و داشبورد برای اعمال فوری اعداد
    var listLoadersToPatch = [
        'loadDashboard', 'loadSalesList', 'loadPurchasesList',
        'loadReceiptsList', 'loadPaymentsList', 'loadTransactionsList',
        'loadProductsList', 'loadPersonsList', 'loadChangelogList',
        'loadServicesList', 'loadReturnsList', 'loadFinancialTabContent',
        'loadReports', 'loadCashboxList',
        'renderDashboardCharts', 'updateDashboardStats',
        'loadRecentActivity', 'loadDashboardWidgets',
        'refreshQuickLists'
    ];
    listLoadersToPatch.forEach(function(name) {
        if (typeof window[name] === 'function' && !window[name]._numSysPatched) {
            var orig = window[name];
            window[name] = function() {
                var result = orig.apply(this, arguments);
                try {
                    // در همان tick: بلافاصله یک بار
                    if (typeof applyNumberSystemToDocument === 'function') {
                        applyNumberSystemToDocument();
                    }
                    // و یک بار با تأخیر برای پوشش async ها
                    setTimeout(function() {
                        try { if (typeof applyNumberSystemToDocument === 'function') applyNumberSystemToDocument(); } catch(_) {}
                    }, 50);
                } catch(_) {}
                return result;
            };
            window[name]._numSysPatched = true;
        }
    });

    // patch کردن jalali datepicker — وقتی تاریخ انتخاب می‌شود، فوراً ارقام را تبدیل کن
    try {
        if (typeof jQuery !== 'undefined' && jQuery.fn && jQuery.fn.persianDatepicker) {
            // اضافه کردن listener سراسری روی blur/change فیلدهای jalali-date
            jQuery(document).on('change blur', '.jalali-date', function() {
                try { window.forceApplyNumberSystem(); } catch(_) {}
            });
        }
    } catch(_) {}

    // patch کردن showToast/showMessage — پیام‌های شامل عدد را فارسی کن
    if (typeof window.showToast === 'function' && !window.showToast._numSysPatched) {
        var _origToast = window.showToast;
        window.showToast = function(msg, type) {
            var result = _origToast.apply(this, arguments);
            setTimeout(function() {
                try { if (typeof applyNumberSystemToDocument === 'function') applyNumberSystemToDocument(); } catch(_) {}
            }, 30);
            return result;
        };
        window.showToast._numSysPatched = true;
    }

    // در صورت تغییر سیستم اعداد، فوراً همه چیز را آپدیت کن
    try {
        var _origSetNumSys = window.setNumberSystem;
        if (typeof _origSetNumSys === 'function' && !_origSetNumSys._patched) {
            window.setNumberSystem = function(sys) {
                var r = _origSetNumSys.apply(this, arguments);
                try { window.forceApplyNumberSystem(); } catch(_) {}
                try { window._instantUpdateAll('numsys'); } catch(_) {}
                return r;
            };
            window.setNumberSystem._patched = true;
        }
    } catch(_) {}

    // یک observer سبک‌تر و کامل‌تر برای پوشش تغییرات text node و attribute
    try {
        if (window._numSysObserverV2) {
            try { window._numSysObserverV2.disconnect(); } catch(_) {}
        }
        window._numSysObserverV2 = new MutationObserver(function(mutations) {
            var needsApply = false;
            for (var i = 0; i < mutations.length; i++) {
                var m = mutations[i];
                // ===== رد کردن تغییرات داخل dropdown جستجوی جنس و picker تاریخ (علت لرزش) =====
                var _t = m.target;
                if (_t && _t.nodeType === 1 && _t.closest && (
                    _t.closest('.product-search-results') ||
                    _t.closest('#_dp_wrap') ||
                    _t.closest('.jalali-datetime-wrapper')
                )) continue;
                if (_t && _t.nodeType === 3 && _t.parentElement && _t.parentElement.closest && (
                    _t.parentElement.closest('.product-search-results') ||
                    _t.parentElement.closest('#_dp_wrap') ||
                    _t.parentElement.closest('.jalali-datetime-wrapper')
                )) continue;
                if (m.type === 'childList' && m.addedNodes && m.addedNodes.length) {
                    needsApply = true;
                    // برای node های جدید، input[type=number] را به text تبدیل کن
                    for (var j = 0; j < m.addedNodes.length; j++) {
                        var n = m.addedNodes[j];
                        if (n.nodeType === 1) {
                            // اگر گره جدید داخل dropdown یا picker است، رد شو
                            if (n.closest && (
                                n.closest('.product-search-results') ||
                                n.closest('#_dp_wrap') ||
                                n.closest('.jalali-datetime-wrapper')
                            )) continue;
                            try { if (typeof convertNumberInputsToText === 'function') convertNumberInputsToText(n); } catch(_) {}
                        }
                    }
                } else if (m.type === 'characterData') {
                    if (m.target && m.target.nodeValue && /[0-9۰-۹٠-٩]/.test(m.target.nodeValue)) {
                        needsApply = true;
                    }
                }
            }
            if (needsApply) {
                clearTimeout(window._numSysApplyTimerV2);
                window._numSysApplyTimerV2 = setTimeout(function() {
                    try { if (typeof applyNumberSystemToDocument === 'function') applyNumberSystemToDocument(); } catch(_) {}
                }, 25);
            }
        });
        window._numSysObserverV2.observe(document.body, {
            childList: true,
            subtree: true,
            characterData: true
        });
    } catch(_) {}

    // اعمال اولیه چندباره برای پوشش رندرهای async اولیه
    setTimeout(function() { try { window.forceApplyNumberSystem(); } catch(_) {} }, 200);
    setTimeout(function() { try { window.forceApplyNumberSystem(); } catch(_) {} }, 800);
    setTimeout(function() { try { window.forceApplyNumberSystem(); } catch(_) {} }, 2000);

    console.log('%c✅ سیستم آپدیت آنی + تقویت اعداد فارسی فعال شد', 'background:#1e40af;color:#fff;padding:6px 12px;border-radius:6px;font-weight:bold;');
})();

// ===== بستن dropdown جستجوی جنس با کلیک خارج از آن =====
(function() {
    document.addEventListener('mousedown', function(e) {
        var bdd = document.getElementById('_psr_body_dd');
        if (!bdd || bdd.style.display === 'none') return;
        // اگر کلیک روی خود dropdown یا روی input جستجو بود، نبند
        if (bdd.contains(e.target)) return;
        if (e.target && e.target.classList && e.target.classList.contains('product-search-input')) return;
        bdd.style.display = 'none';
        bdd.innerHTML = '';
        if (bdd._scrollHandler) {
            window.removeEventListener('scroll', bdd._scrollHandler, true);
            bdd._scrollHandler = null;
        }
        bdd._activeWrapper = null;
        bdd._activeInput = null;
    }, true);
})();

/* ============================================================
   ===== توابع کمکی ظاهری برای طرح بل فروش/خرید =====
   فقط نمایش/پنهان‌سازی و فراخوانی توابع موجود. هیچ منطق دیتابیسی تغییر نمی‌کند.
   به‌صورت تعریف تابع سراسری (hoisted) تا همیشه در دسترس باشند.
   ============================================================ */

// ---- تخفیف: باز/بسته کردن پاپ‌اور ----
function billToggleDiscount(which) {
    var id = (which === 'purchase') ? 'purchase-discount-panel' : 'sales-discount-panel';
    var panel = document.getElementById(id);
    if (!panel) return;
    var otherId = (which === 'purchase') ? 'sales-discount-panel' : 'purchase-discount-panel';
    var other = document.getElementById(otherId);
    if (other) other.classList.remove('open');
    panel.classList.toggle('open');
}

// ---- هزینه حمل و نقل: نمایش/پنهانِ پنل (مشابه تخفیف) ----
function billToggleShipping() {
    var panel = document.getElementById('purchase-shipping-panel');
    if (!panel) return;
    var other = document.getElementById('purchase-discount-panel');
    if (other) other.classList.remove('open');
    // هم‌گام‌سازیِ مقدارِ پنل با فیلدِ اصلیِ حمل‌ونقل هنگام باز شدن
    var main = document.getElementById('purchase-shipping');
    var pInput = document.getElementById('purchase-shipping-input');
    if (main && pInput) pInput.value = main.value || '0';
    panel.classList.toggle('open');
}

// ورودیِ پنلِ حمل‌ونقل → فیلدِ اصلیِ purchase-shipping (تا کدِ موجود بدونِ تغییر کار کند)
function syncShippingFromPanel() {
    var pInput = document.getElementById('purchase-shipping-input');
    var main = document.getElementById('purchase-shipping');
    if (pInput && main) {
        main.value = pInput.value || '0';
        if (typeof calculatePurchaseTotal === 'function') calculatePurchaseTotal();
    }
}

// خواندنِ روشِ تقسیمِ هزینه حمل و نقلِ انتخاب‌شده در فرمِ خرید (پیش‌فرض: ارزش خرید)
function _getShippingMethod() {
    var el = document.querySelector('input[name="purchase-shipping-method"]:checked');
    return el ? el.value : 'value';
}

// ════════════════════════════════════════════════════════════════════════
//  محاسبهٔ تقسیمِ هزینه حمل و نقل بینِ اقلامِ خرید بر اساسِ روشِ انتخاب‌شده.
//  خروجی: آرایه‌ای هم‌طول با items که برای هر قلم مقادیرِ زیر را می‌دهد:
//    { shippingShare, shippingUnitCost, landedUnitCost }
//  • shippingShare      = سهمِ کلِ آن قلم از هزینه حمل
//  • shippingUnitCost   = سهمِ هر واحدِ آن قلم (share ÷ تعداد)
//  • landedUnitCost     = قیمتِ تمام‌شدهٔ هر واحد (قیمتِ خرید + shippingUnitCost)
//  روش‌ها به‌صورتِ نگاشتِ توسعه‌پذیر تعریف شده‌اند تا افزودنِ روشِ جدید ساده باشد.
//  هیچ اثری روی مبلغِ بل، حساب، موجودی یا FIFO ندارد؛ فقط داده‌های تقسیم را می‌سازد.
// ════════════════════════════════════════════════════════════════════════

// نگاشتِ توسعه‌پذیرِ روش‌های تقسیم — به‌صورتِ تابع تا همیشه در دسترس باشد
function _shippingMethodsMap() {
    return {
        // بر اساس تعداد: وزنِ هر قلم = تعداد
        quantity: function (it) { return _shipQty(it); },
        // بر اساس ارزش خرید: وزنِ هر قلم = تعداد × قیمت خرید
        value: function (it) { return _shipQty(it) * (parseFloat(it.price) || 0); },
        // بر اساس وزن: وزنِ هر قلم = تعداد × وزنِ واحدِ کالا (از ثبتِ جنس)
        weight: function (it) { return _shipQty(it) * _shipUnitWeight(it); }
    };
}

// تعدادِ واقعیِ قلم برای تقسیم (با درنظرگرفتنِ واحدِ فرعی، هماهنگ با _qtyForStock)
function _shipQty(it) {
    var q = parseFloat(it.quantity) || 0;
    if (it.unitType === 'secondary') {
        var f = parseFloat(it.secondaryFactor) || 0;
        if (f > 0) return q * f;
    }
    return q;
}

// وزنِ واحدِ کالا برای روشِ «بر اساس وزن».
//  ۱) اگر روی جنس فیلدِ صریحِ وزن (weight/unitWeight) ثبت شده باشد، همان استفاده می‌شود.
//  ۲) در غیرِ این‌صورت از روی «واحدِ» همان قلم (گرام/کیلوگرام/تن/…) به گرم تبدیل می‌شود،
//     تا اگر واحدِ کالا وزنی باشد، محاسبه دقیقاً بر اساسِ همان واحد انجام شود.
//  نبودِ وزن یا واحدِ غیروزنی = 0 (یعنی آن قلم در تقسیمِ وزنی سهمی نمی‌گیرد).
function _shipUnitWeight(it) {
    try {
        var prods = (db.getProducts && db.getProducts()) || [];
        var p = prods.find(function (x) { return x.id == it.productId; });
        // (۱) وزنِ صریحِ ثبت‌شده روی جنس
        if (p) {
            var w = parseFloat(p.weight != null ? p.weight : (p.unitWeight != null ? p.unitWeight : 0)) || 0;
            if (w > 0) return w;
        }
        // (۲) استنتاج از روی نامِ واحد (به گرم)
        var unit = String((it.unit != null ? it.unit : (p && p.unit) || '')).trim().toLowerCase();
        var map = {
            'گرام': 1, 'گرم': 1, 'g': 1, 'gr': 1, 'gram': 1, 'grams': 1,
            'کیلوگرام': 1000, 'کیلو گرام': 1000, 'کیلو': 1000, 'kg': 1000, 'kgs': 1000, 'kilo': 1000, 'kilogram': 1000, 'kilograms': 1000,
            'تن': 1000000, 'ton': 1000000, 'tonne': 1000000, 'tonnes': 1000000,
            'میلی‌گرام': 0.001, 'میلی گرام': 0.001, 'mg': 0.001,
            'پوند': 453.592, 'lb': 453.592, 'lbs': 453.592, 'pound': 453.592, 'pounds': 453.592
        };
        if (map[unit] != null) return map[unit];
        return 0;
    } catch (e) { return 0; }
}

function _computeShippingDistribution(items, shippingTotal, method) {
    var out = [];
    var n = (items || []).length;
    for (var i = 0; i < n; i++) out.push({ shippingShare: 0, shippingUnitCost: 0, landedUnitCost: (parseFloat(items[i].price) || 0) });
    var ship = parseFloat(shippingTotal) || 0;
    if (!(ship > 0) || n === 0) return out;
    var _methods = _shippingMethodsMap();
    var fn = _methods[method] || _methods.value;
    // مجموعِ وزن‌ها
    var weights = [];
    var totalW = 0;
    for (var j = 0; j < n; j++) {
        var w = fn(items[j]) || 0;
        if (w < 0) w = 0;
        weights.push(w);
        totalW += w;
    }
    if (!(totalW > 0)) return out; // اگر مبنای تقسیم صفر بود (مثلاً وزن ثبت نشده)، سهمی اعمال نمی‌شود
    // گِردکردنِ قیمتِ تمام‌شده به یک رقمِ اعشار (برای هر ارز، یکسان)
    var _round1 = function (x) { var v = parseFloat(x); return isNaN(v) ? 0 : Math.round(v * 10) / 10; };
    for (var k = 0; k < n; k++) {
        var share = (weights[k] / totalW) * ship;
        var qty = _shipQty(items[k]) || 0;
        var unitCost = qty > 0 ? (share / qty) : 0;
        var basePrice = parseFloat(items[k].price) || 0;
        out[k] = {
            shippingShare: share,
            shippingUnitCost: unitCost,
            landedUnitCost: _round1(basePrice + unitCost)
        };
    }
    return out;
}
if (typeof window !== 'undefined') {
    window._computeShippingDistribution = _computeShippingDistribution;
    window._getShippingMethod = _getShippingMethod;
}

// ---- اطلاعات بیشتر: نمایش/پنهان ----
function billToggleMore(which) {
    var id = which + '-more-panel';
    var panel = document.getElementById(id);
    if (panel) panel.classList.toggle('open');
}

// ====== فرم ثبت جنس: افزودن مقدار از داخل خود دراپ‌داون ======
// به‌جای دکمهٔ + جداگانه، یک گزینهٔ «➕ اضافه کردن {label}» در انتهای دراپ‌داون قرار می‌گیرد.
// با انتخاب آن، یک ردیف ورودی کوچک زیر فیلد باز می‌شود تا کاربر مقدار جدید را تایپ و ذخیره کند.
// مقادیر در همان localStorage قبلی ذخیره می‌شوند (بدون تغییر در منطق ذخیره‌سازی).
function setupProductAddSelect(selectElement, storageKey, label) {
    if (!selectElement) return;
    var ADD_VALUE = '__ADD_NEW__';
    // کلیدِ ذخیره را در هر فراخوانی روی خودِ select نگه‌دار تا بستهٔ _commit (که فقط یک‌بار
    // ساخته می‌شود) همیشه روی کلیدِ جاری بنویسد، نه کلیدِ قفل‌شدهٔ بارِ اول.
    selectElement._addStorageKey = storageKey;

    // گزینهٔ placeholder (نام فیلد داخل خود فیلد) — هنگام انتخاب مقدار، ناپدید می‌شود
    if (selectElement.options.length === 0 || selectElement.options[0].value !== '') {
        var ph = document.createElement('option');
        ph.value = '';
        ph.textContent = label;
        selectElement.insertBefore(ph, selectElement.firstChild);
    } else {
        selectElement.options[0].textContent = label;
    }

    // افزودن/به‌روزرسانی گزینهٔ «اضافه کردن»
    var addOpt = Array.prototype.find.call(selectElement.options, function (o) { return o.value === ADD_VALUE; });
    if (!addOpt) {
        addOpt = document.createElement('option');
        addOpt.value = ADD_VALUE;
        selectElement.appendChild(addOpt);
    } else {
        // همیشه آخر باشد
        selectElement.appendChild(addOpt);
    }
    addOpt.textContent = '➕ اضافه کردن ' + label;

    // ساخت ردیف ورودی inline (یک‌بار)
    var field = selectElement.closest('.bill-field') || selectElement.parentElement;
    var host = field ? field.parentElement : selectElement.parentElement;
    var inputRow = selectElement._addInputRow;
    if (!inputRow && host) {
        inputRow = document.createElement('div');
        inputRow.className = 'product-add-row';
        inputRow.style.display = 'none';
        inputRow.innerHTML =
            '<input type="text" class="product-add-input" placeholder="' + label + ' جدید...">' +
            '<button type="button" class="product-add-ok" title="تایید"><i class="fas fa-check"></i></button>' +
            '<button type="button" class="product-add-cancel" title="لغو"><i class="fas fa-times"></i></button>';
        // درج بعد از فیلد
        if (field && field.nextSibling) host.insertBefore(inputRow, field.nextSibling);
        else host.appendChild(inputRow);
        selectElement._addInputRow = inputRow;

        var inp = inputRow.querySelector('.product-add-input');
        var okBtn = inputRow.querySelector('.product-add-ok');
        var cancelBtn = inputRow.querySelector('.product-add-cancel');

        var _commit = function () {
            var val = (inp.value || '').trim();
            var _key = selectElement._addStorageKey || storageKey;
            if (!val) { inputRow.style.display = 'none'; selectElement.value = ''; return; }
            var customs = JSON.parse(localStorage.getItem(_key) || '[]');
            if (!customs.includes(val)) { customs.push(val); localStorage.setItem(_key, JSON.stringify(customs)); }
            // درج گزینه قبل از گزینهٔ «اضافه کردن»
            if (!Array.prototype.find.call(selectElement.options, function (o) { return o.value === val; })) {
                var opt = document.createElement('option'); opt.value = val; opt.textContent = val;
                var addO = Array.prototype.find.call(selectElement.options, function (o) { return o.value === ADD_VALUE; });
                if (addO) selectElement.insertBefore(opt, addO); else selectElement.appendChild(opt);
            }
            selectElement.value = val;
            inp.value = '';
            inputRow.style.display = 'none';
            // آتش‌کردنِ رویدادِ change تا هندلرهای وابسته (مثلاً updateSubCategories روی کتگوریِ
            // اصلی) اجرا شوند و کلیدِ ذخیرهٔ فیلدهای وابسته به مقدارِ جدید به‌روز شود. بدونِ این،
            // ست‌کردنِ برنامه‌ایِ مقدار رویداد نمی‌داد و کتگوریِ فرعی زیرِ کلیدِ اصلیِ کهنه ذخیره می‌شد.
            try { selectElement.dispatchEvent(new Event('change', { bubbles: true })); } catch (e) {
                try { var _ev = document.createEvent('HTMLEvents'); _ev.initEvent('change', true, false); selectElement.dispatchEvent(_ev); } catch (e2) {}
            }
        };
        okBtn.onclick = _commit;
        cancelBtn.onclick = function () { inp.value = ''; inputRow.style.display = 'none'; selectElement.value = ''; };
        inp.onkeydown = function (e) { if (e.key === 'Enter') { e.preventDefault(); _commit(); } };
    }

    // رویداد تغییر: اگر «اضافه کردن» انتخاب شد، ردیف ورودی را باز کن
    if (selectElement._addOnChange) {
        selectElement.removeEventListener('change', selectElement._addOnChange);
    }
    selectElement._addOnChange = function () {
        if (selectElement.value === ADD_VALUE) {
            if (selectElement._addInputRow) {
                selectElement._addInputRow.style.display = 'flex';
                var i = selectElement._addInputRow.querySelector('.product-add-input');
                if (i) { try { i.focus(); } catch (e) {} }
            }
            selectElement.value = '';
        }
    };
    selectElement.addEventListener('change', selectElement._addOnChange);
}

// ---- آیکن ➕ : نمایش فیلد نقدی ارز دیگر (همان فیلد موجود) ----
// ---- آیکن ➕ : افزودن یک ردیف مبلغ + انتخاب حساب (نظر به ارز) ----
// این فیلدها فقط ظاهری‌اند و کاربر می‌تواند مبلغ و حساب دیگری یادداشت کند.
// منطق ذخیرهٔ اصلی بل دست‌نخورده است.
// ---- آیکن ✏️ : باز/بستن فورم دریافتی/پرداختی همین بل (inline) ----
// این فورم مبلغ و حسابِ همان بل را نشان می‌دهد؛ سند دریافت/پرداخت مرتبط هنگام ثبت بل
// به‌صورت یک سند مرتبط (بدون اثر روی حساب) ذخیره می‌شود.
function billToggleReceiveEdit(isPurchase) {
    var which = isPurchase ? 'purchase' : 'sales';
    var panel = document.getElementById(which + '-receive-edit');
    if (!panel) return;
    var willOpen = !panel.classList.contains('open');
    panel.classList.toggle('open', willOpen);
    if (willOpen) {
        // مبلغ فعلی دریافتی/پرداختی را در فورم نشان بده (نظر به ارز)
        var curId = isPurchase ? 'purchase-currency' : 'sales-currency';
        var cur = (document.getElementById(curId) || {}).value || _baseCur();
        var srcId = isPurchase
            ? (cur === 'USD' ? 'purchase-paid-usd' : 'purchase-paid-afn')
            : (cur === 'USD' ? 'sales-cash-usd' : 'sales-cash-afn');
        var src = document.getElementById(srcId);
        var amt = document.getElementById(which + '-receive-edit-amount');
        if (src && amt && src.value) amt.value = src.value;
        if (amt) { try { amt.focus(); } catch (e) {} }
    }
}

// ---- همگام‌سازی مبلغ فورم دریافتی با فیلد اصلی دریافتی/پرداختی (نظر به ارز) ----
function billReceiveEditSync(isPurchase) {
    var which = isPurchase ? 'purchase' : 'sales';
    var curId = isPurchase ? 'purchase-currency' : 'sales-currency';
    var cur = (document.getElementById(curId) || {}).value || _baseCur();
    var dstId = isPurchase
        ? (cur === 'USD' ? 'purchase-paid-usd' : 'purchase-paid-afn')
        : (cur === 'USD' ? 'sales-cash-usd' : 'sales-cash-afn');
    var amt = document.getElementById(which + '-receive-edit-amount');
    var dst = document.getElementById(dstId);
    if (amt && dst) {
        dst.disabled = false;
        dst.value = amt.value;
        if (isPurchase) {
            if (typeof calculatePurchaseRemaining === 'function') calculatePurchaseRemaining();
        } else {
            if (typeof calculateRemaining === 'function') calculateRemaining();
        }
    }
}

// ---- آیکن ✓ : تسویه کامل (همان منطق toggleFullPayment) ----
function billFullPayIcon(isPurchase) {
    var checkId = isPurchase ? 'purchase-full-payment-checkbox' : 'full-payment-checkbox';
    var iconId = isPurchase ? 'purchase-fullpay-icon' : 'sales-fullpay-icon';
    var chk = document.getElementById(checkId);
    var icon = document.getElementById(iconId);
    if (!chk) return;
    chk.checked = !chk.checked;
    if (icon) icon.classList.toggle('is-active', chk.checked);
    if (isPurchase) {
        if (typeof togglePurchaseFullPayment === 'function') togglePurchaseFullPayment(chk);
    } else {
        if (typeof toggleFullPayment === 'function') toggleFullPayment(chk);
    }
}

// ---- لیست تسلیم دهی ----
// منطق اصلی تسلیم‌دهی در delivery-list.js است و هنگام ذخیره، چک‌باکس
// «add-to-delivery-checkbox» را می‌خواند. چون طراحی جدید دکمهٔ .btn-service-add را ندارد،
// این تابع همان چک‌باکس را (در صورت نبود می‌سازد) تغییر وضعیت می‌دهد و دکمه را سبز می‌کند.
// بدین ترتیب منطق اصلی تسلیم‌دهی دست‌نخورده باقی می‌ماند.
function billAddToDelivery(isPurchase) {
    // تسلیم‌دهی فقط برای فروش فعال است (مطابق منطق اصلی delivery-list.js)
    if (isPurchase) {
        if (typeof showMessage === 'function') {
            showMessage('لیست تسلیم دهی', 'لیست تسلیم‌دهی فقط برای فروش فعال است.');
        }
        return;
    }
    var cb = document.getElementById('add-to-delivery-checkbox');
    if (!cb) {
        // ساخت چک‌باکس مخفی که هوک ذخیرهٔ delivery-list.js آن را می‌خواند
        cb = document.createElement('input');
        cb.type = 'checkbox';
        cb.id = 'add-to-delivery-checkbox';
        cb.style.display = 'none';
        var form = document.getElementById('salesForm');
        (form || document.body).appendChild(cb);
    }
    cb.checked = !cb.checked;
    var btn = document.getElementById('sales-delivery-btn');
    if (btn) btn.classList.toggle('bill-pill-active', cb.checked);
}

// ---- دکمهٔ «تصحیح» — باز کردن قفل فرم برای ویرایش ----
function billEnableEdit(which) {
    var layout = document.getElementById(which + '-bill-layout');
    var correctBtn = document.getElementById(which + '-correct-btn');
    if (layout) layout.classList.remove('bill-locked');
    if (correctBtn) correctBtn.style.display = 'none';
}

/* ---- بخش wrapper برای همگام‌سازی نمایش و حالت ارز ----
   این بخش توابع موجود را می‌پیچد (wrap) بدون تغییر در منطق آن‌ها. */
(function () {
    'use strict';

    function _fmt(n) {
        if (typeof formatNumber === 'function') return formatNumber(n);
        return String(n);
    }

    // بستن پاپ‌اور تخفیف با کلیک بیرون
    document.addEventListener('click', function (e) {
        var pops = document.querySelectorAll('.bill-discount-pop');
        pops.forEach(function (pop) {
            if (!pop.contains(e.target)) {
                var panel = pop.querySelector('.bill-discount-panel');
                if (panel) panel.classList.remove('open');
            }
        });
    });

    // نمایش/پنهان فیلد دریافتی نظر به ارز (افغانی → فیلد افغانی، دالر → فیلد دالر)
    function _applyCurrencyVisibility(isPurchase) {
        var curId = isPurchase ? 'purchase-currency' : 'sales-currency';
        var afnId = isPurchase ? 'purchase-paid-afn' : 'sales-cash-afn';
        var usdId = isPurchase ? 'purchase-paid-usd' : 'sales-cash-usd';
        var frnId = isPurchase ? 'purchase-paid-foreign' : 'sales-cash-foreign';
        var cur = (document.getElementById(curId) || {}).value || _baseCur();
        var afn = document.getElementById(afnId);
        var usd = document.getElementById(usdId);
        var frn = document.getElementById(frnId);
        // هر ارزی که در سیستم تعریف شده، فیلدِ دریافتی/پرداختیِ خودش را می‌گیرد
        if (cur === 'USD') {
            if (usd) usd.style.display = 'block';
            if (afn) afn.style.display = 'none';
            if (frn) frn.style.display = 'none';
        } else if (cur === 'AFN') {
            if (afn) afn.style.display = 'block';
            if (usd) usd.style.display = 'none';
            if (frn) frn.style.display = 'none';
        } else {
            // ارزِ سوم به بعد → فیلدِ اختصاصی با برچسبِ نامِ همان ارز
            if (frn) {
                frn.style.display = 'block';
                var _lbl = cur;
                try {
                    if (typeof CurrencySystem !== 'undefined' && CurrencySystem.getCurrency) {
                        var _c = CurrencySystem.getCurrency(cur);
                        if (_c) _lbl = _c.nameLocal || cur;
                    }
                } catch (e) {}
                frn.placeholder = (isPurchase ? 'پرداختی (' : 'دریافتی (') + _lbl + ')';
            }
            if (afn) afn.style.display = 'none';
            if (usd) usd.style.display = 'none';
        }
    }

    // یادداشت: نمایش «مبلغ باقی مانده» در نوار پایین اکنون مستقیماً داخل توابع
    // اصلی calculateRemaining و calculatePurchaseRemaining انجام می‌شود تا روی
    // همهٔ مسیرهای فراخوانی (از جمله تسویه کامل) درست کار کند.

    // بازمحاسبهٔ قیمتِ همهٔ ردیف‌های موجود هنگامِ تعویضِ ارز.
    //  این تضمین می‌کند در هر دو حالت درست کار کند: چه ارز را قبل از انتخابِ جنس
    //  عوض کنیم، چه بعد از آن. قیمتِ فروش/خرید از حل‌کنندهٔ مرکزی (قیمتِ صریحِ همان
    //  ارز، وگرنه تبدیلِ نرخِ روز) خوانده می‌شود.
    //  قیمت‌هایی که کاربر دستی تغییر داده باشد حفظ می‌شوند (پرچمِ dataset.manualPrice).
    function _refreshRowPricesForCurrency(isPurchase) {
        try {
            // هنگام بارگذاریِ بلِ ذخیره‌شده برای ویرایش، قیمت‌های ذخیره‌شده نباید بازنویسی شوند.
            if (window._billHydrating) return;
            var curId = isPurchase ? 'purchase-currency' : 'sales-currency';
            var cur = (document.getElementById(curId) || {}).value || _baseCur();
            var rowSel = isPurchase ? '#purchase-items-body .item-row' : '#sales-items-body .item-row';
            var priceSel = isPurchase ? '.purchase-item-price' : '.item-price';
            var prodSel = isPurchase ? '.purchase-item-product' : '.item-product';
            var rows = document.querySelectorAll(rowSel);
            if (!rows || !rows.length) return;
            var prods = (typeof db !== 'undefined' && db.getProducts) ? (db.getProducts() || []) : [];
            rows.forEach(function (row) {
                var pEl = row.querySelector(prodSel);
                var priceEl = row.querySelector(priceSel);
                if (!pEl || !priceEl) return;
                var pid = pEl.value;
                if (!pid) return;                       // ردیفِ خالی — کاری نکن
                if (priceEl.dataset && priceEl.dataset.manualPrice === '1') return;  // قیمتِ دستیِ کاربر
                var prod = prods.find(function (x) { return x.id == pid; });
                if (!prod) return;
                var unitType = (row.dataset && row.dataset.unitType === 'secondary') ? 'secondary' : 'primary';
                var kind = isPurchase ? 'purchase' : 'sale';
                var res = (typeof _resolveProductPrice === 'function')
                    ? _resolveProductPrice(prod, cur, kind, unitType) : null;
                if (!res) return;
                priceEl.value = res.price || 0;
                try { if (typeof _markSuggestedPrice === 'function') _markSuggestedPrice(priceEl, res, cur); } catch (e) {}
                // به‌روزرسانیِ جمعِ همان ردیف
                try {
                    if (isPurchase && typeof updatePurchaseItemTotal === 'function') updatePurchaseItemTotal(priceEl);
                    else if (!isPurchase && typeof updateItemTotal === 'function') updateItemTotal(priceEl);
                } catch (e) {}
            });
            // جمع کلِ بل و باقی‌مانده
            try {
                if (isPurchase) {
                    if (typeof calculatePurchaseTotal === 'function') calculatePurchaseTotal();
                    if (typeof calculatePurchaseRemaining === 'function') calculatePurchaseRemaining();
                } else {
                    if (typeof calculateSalesTotal === 'function') calculateSalesTotal();
                    if (typeof calculateRemaining === 'function') calculateRemaining();
                }
            } catch (e) {}
        } catch (e) { console.warn('refresh row prices:', e); }
    }
    window._refreshRowPricesForCurrency = _refreshRowPricesForCurrency;

    // ثبتِ «قیمتِ دستی» وقتی کاربر خودش عدد را عوض می‌کند (تا با تعویضِ ارز بازنویسی نشود)
    document.addEventListener('input', function (ev) {
        var t = ev.target;
        if (!t || !t.classList) return;
        if (t.classList.contains('item-price') || t.classList.contains('purchase-item-price')) {
            if (t.dataset) t.dataset.manualPrice = '1';
        }
    }, true);

    // wrap updateSalesCurrencyFields — افزودن نمایش/پنهان فیلد نظر به ارز
    if (typeof window.updateSalesCurrencyFields === 'function') {
        var _origUSC = window.updateSalesCurrencyFields;
        window.updateSalesCurrencyFields = function () {
            var r = _origUSC.apply(this, arguments);
            _applyCurrencyVisibility(false);
            _refreshRowPricesForCurrency(false);
            return r;
        };
    }
    // wrap updatePurchaseCurrencyFields
    if (typeof window.updatePurchaseCurrencyFields === 'function') {
        var _origUPC = window.updatePurchaseCurrencyFields;
        window.updatePurchaseCurrencyFields = function () {
            var r = _origUPC.apply(this, arguments);
            _applyCurrencyVisibility(true);
            _refreshRowPricesForCurrency(true);
            return r;
        };
    }

    // wrap reset — پاک‌سازی حالت ظاهری هنگام شروع فروش/خرید جدید
    if (typeof window.resetSalesForm === 'function') {
        var _origRS = window.resetSalesForm;
        window.resetSalesForm = function () {
            var r = _origRS.apply(this, arguments);
            billEnableEdit('sales');
            var icon = document.getElementById('sales-fullpay-icon');
            if (icon) icon.classList.remove('is-active');
            var more = document.getElementById('sales-more-panel');
            if (more) more.classList.remove('open');
            var wrap = document.getElementById('sales-remaining-wrap');
            if (wrap) { wrap.textContent = 'مبلغ باقی مانده: ' + _fmt(0); wrap.style.color = ''; }
            // پاک‌سازی وضعیت لیست تسلیم‌دهی
            var dcb = document.getElementById('add-to-delivery-checkbox');
            if (dcb) dcb.checked = false;
            var dbtn = document.getElementById('sales-delivery-btn');
            if (dbtn) dbtn.classList.remove('bill-pill-active');
            // بستن پنل تخفیف و فورم دریافتی inline
            var dpanel = document.getElementById('sales-discount-panel');
            if (dpanel) dpanel.classList.remove('open');
            var recEdit = document.getElementById('sales-receive-edit');
            if (recEdit) recEdit.classList.remove('open');
            ['sales-receive-edit-amount', 'sales-receive-edit-desc'].forEach(function (id) {
                var el = document.getElementById(id); if (el) el.value = '';
            });
            var rt = document.getElementById('sales-receive-edit-type'); if (rt) rt.value = 'نقد';
            _applyCurrencyVisibility(false);
            return r;
        };
    }
    if (typeof window.resetPurchaseForm === 'function') {
        var _origRP = window.resetPurchaseForm;
        window.resetPurchaseForm = function () {
            var r = _origRP.apply(this, arguments);
            billEnableEdit('purchase');
            var icon = document.getElementById('purchase-fullpay-icon');
            if (icon) icon.classList.remove('is-active');
            var more = document.getElementById('purchase-more-panel');
            if (more) more.classList.remove('open');
            var wrap = document.getElementById('purchase-remaining-wrap');
            if (wrap) { wrap.textContent = 'مبلغ باقی مانده: ' + _fmt(0); wrap.style.color = ''; }
            // بستن پنل تخفیف و فورم پرداختی inline
            var pdpanel = document.getElementById('purchase-discount-panel');
            if (pdpanel) pdpanel.classList.remove('open');
            var precEdit = document.getElementById('purchase-receive-edit');
            if (precEdit) precEdit.classList.remove('open');
            ['purchase-receive-edit-amount', 'purchase-receive-edit-desc'].forEach(function (id) {
                var el = document.getElementById(id); if (el) el.value = '';
            });
            var prt = document.getElementById('purchase-receive-edit-type'); if (prt) prt.value = 'نقد';
            _applyCurrencyVisibility(true);
            return r;
        };
    }
    // پاک‌سازی ظاهری فرم دریافتی هنگام reset
    if (typeof window.resetReceiptForm === 'function') {
        var _origRR = window.resetReceiptForm;
        window.resetReceiptForm = function () {
            var r = _origRR.apply(this, arguments);
            var mp = document.getElementById('receipt-more-panel');
            if (mp) mp.classList.remove('open');
            var hr = document.getElementById('receipt-hawala-commission-row');
            if (hr) hr.style.display = 'none';
            billEnableEdit('receipt');
            return r;
        };
    }
    // پاک‌سازی ظاهری فرم پرداختی هنگام reset
    if (typeof window.resetPaymentForm === 'function') {
        var _origRPay = window.resetPaymentForm;
        window.resetPaymentForm = function () {
            var r = _origRPay.apply(this, arguments);
            var mp = document.getElementById('payment-more-panel');
            if (mp) mp.classList.remove('open');
            var hr = document.getElementById('payment-hawala-commission-row');
            if (hr) hr.style.display = 'none';
            billEnableEdit('payment');
            return r;
        };
    }
    // پاک‌سازی ظاهری فرم ثبت جنس هنگام reset
    if (typeof window.resetProductForm === 'function') {
        var _origRProd = window.resetProductForm;
        window.resetProductForm = function () {
            var r = _origRProd.apply(this, arguments);
            var mp = document.getElementById('product-more-panel');
            if (mp) mp.classList.remove('open');
            var nm = document.getElementById('product-image-name');
            if (nm) nm.textContent = '';
            _pendingProductImageData = null;
            return r;
        };
    }
    // نمایش نام فایل تصویر انتخاب‌شده کنار آیکن کامره
    document.addEventListener('DOMContentLoaded', function () {
        var img = document.getElementById('product-image');
        if (img) {
            img.addEventListener('change', function () {
                var nm = document.getElementById('product-image-name');
                if (nm) nm.textContent = (img.files && img.files[0]) ? img.files[0].name : '';
                // خواندن عکس به‌صورت base64 برای ذخیره و نمایش در لیست اجناس
                if (img.files && img.files[0]) {
                    try {
                        var _rdr = new FileReader();
                        _rdr.onload = function (e) { _pendingProductImageData = e.target.result; };
                        _rdr.readAsDataURL(img.files[0]);
                    } catch (err) { _pendingProductImageData = null; }
                } else {
                    _pendingProductImageData = null;
                }
            });
        }
        var pimg = document.getElementById('person-image');
        if (pimg) {
            pimg.addEventListener('change', function () {
                var nm = document.getElementById('person-image-name');
                if (nm) nm.textContent = (pimg.files && pimg.files[0]) ? pimg.files[0].name : '';
            });
        }
    });
    // پاک‌سازی ظاهری فرم ثبت شخص هنگام reset
    if (typeof window.resetPersonForm === 'function') {
        var _origRPerson = window.resetPersonForm;
        window.resetPersonForm = function () {
            var r = _origRPerson.apply(this, arguments);
            var mp = document.getElementById('person-more-panel');
            if (mp) mp.classList.remove('open');
            var nm = document.getElementById('person-image-name');
            if (nm) nm.textContent = '';
            return r;
        };
    }

    // هنگام ویرایش بل از لیست، فرم را قفل کن (تا کاربر «تصحیح» را بزند)
    if (typeof window.editTransaction === 'function') {
        var _origET = window.editTransaction;
        window.editTransaction = function (id) {
            var r = _origET.apply(this, arguments);
            try {
                var txs = (typeof db !== 'undefined' && db.getTransactions) ? db.getTransactions() : [];
                var tx = txs.find(function (t) { return t.id == id; });
                if (tx) {
                    if (tx.type === 'فروش' || tx.type === 'پیش‌فاکتور') {
                        setTimeout(function () {
                            var l = document.getElementById('sales-bill-layout');
                            var b = document.getElementById('sales-correct-btn');
                            if (l) l.classList.add('bill-locked');
                            if (b) b.style.display = 'inline-flex';
                        }, 250);
                    } else if (tx.type === 'خرید') {
                        setTimeout(function () {
                            var l = document.getElementById('purchase-bill-layout');
                            var b = document.getElementById('purchase-correct-btn');
                            if (l) l.classList.add('bill-locked');
                            if (b) b.style.display = 'inline-flex';
                        }, 250);
                    }
                }
            } catch (e) {}
            return r;
        };
    }

    // اعمال اولیهٔ نمایش ارز پس از بارگذاری
    document.addEventListener('DOMContentLoaded', function () {
        _applyCurrencyVisibility(false);
        _applyCurrencyVisibility(true);
    });

    // =====================================================================
    // درخواست ۲: ساخت «سند دریافت/پرداخت مرتبط با بل»
    // - بل مثل قبل حساب را شارژ می‌کند (پول یک‌بار شمرده می‌شود).
    // - سند دریافت/پرداخت مرتبط فقط برای نمایش/ویرایش ذخیره می‌شود و
    //   cashboxId ندارد، پس روی موجودی حساب هیچ اثری نمی‌گذارد (بدون دوباره‌شماری).
    // - این سند با reference به شماره بل مرتبط می‌شود و با دکمهٔ «ویرایش دریافتی»
    //   فورم آن باز می‌شود.
    // =====================================================================
    (function _installLinkedReceiptHook() {
        if (typeof db === 'undefined' || !db || typeof db.saveTransaction !== 'function') {
            // اگر هنوز db آماده نیست، کمی بعد دوباره تلاش کن
            setTimeout(_installLinkedReceiptHook, 300);
            return;
        }
        if (db.saveTransaction._jouyaLinkedReceiptPatched) return;

        var origSave = db.saveTransaction.bind(db);

        db.saveTransaction = function (transaction) {
            var result = origSave(transaction);

            try {
                if (!result || result.success === false || !result.data) return result;
                var tx = result.data;
                // فقط برای فروش/خرید جدید (نه ویرایش، چون آنجا سند قبلاً ساخته شده)
                var isSale = tx.type === 'فروش';
                var isPurchase = tx.type === 'خرید';
                if (!isSale && !isPurchase) return result;

                var cur = tx.currency || _baseCur();
                var cashAmt = isSale
                    ? (cur === 'USD' ? (parseFloat(tx.cashUsd) || 0) : (parseFloat(tx.cashAfn) || 0))
                    : (cur === 'USD' ? (parseFloat(tx.paidUsd) || 0) : (parseFloat(tx.paidAfn) || 0));
                if (!(cashAmt > 0)) return result;

                var personId = isSale ? tx.customerId : tx.supplierId;
                var personName = isSale ? tx.customerName : (tx.supplierName || tx.customerName);
                var billNo = tx.billNumber || '';

                // نوع و توضیحات از فورم inline دریافتی/پرداختی
                var typeEl = document.getElementById((isSale ? 'sales' : 'purchase') + '-receive-edit-type');
                var descEl = document.getElementById((isSale ? 'sales' : 'purchase') + '-receive-edit-desc');
                var rType = (typeEl && typeEl.value) ? typeEl.value : 'نقد';
                var rDesc = (descEl && descEl.value) ? descEl.value : '';

                // جلوگیری از ساخت تکراری برای همان بل (در صورت ذخیرهٔ مجدد)
                var existing = (db.getTransactions ? db.getTransactions() : []).find(function (t) {
                    return t && t.linkedBillId && t.linkedBillId == tx.id;
                });

                var linkedDoc = {
                    type: isSale ? 'دریافت' : 'پرداخت',
                    personId: personId ? parseInt(personId) : null,
                    personName: personName || '',
                    date: tx.date,
                    amount: cashAmt,
                    currency: cur,
                    cashboxId: null,            // ← بدون اثر روی حساب (پول از طریق بل شمرده شده)
                    reference: billNo,
                    linkedBillId: tx.id,        // ارتباط با بل
                    description: rDesc || ('سند مرتبط با بل ' + billNo),
                    status: 'انجام شد'
                };
                if (isSale) linkedDoc.receiptType = rType; else linkedDoc.paymentType = rType;
                if (existing && existing.id) linkedDoc.id = existing.id;

                // ذخیرهٔ سند مرتبط بدون فعال‌کردن دوبارهٔ همین هوک (origSave مستقیم)
                origSave(linkedDoc);
            } catch (e) {
                console.warn('[linked-receipt] خطا در ساخت سند مرتبط:', e);
            }
            return result;
        };

        db.saveTransaction._jouyaLinkedReceiptPatched = true;
    })();

})();

/* ============================================================
   ساعت و تاریخ زندهٔ هدر داشبورد
   - فرمت دقیقاً مثل فیلدهای تاریخ: «روزِ‌هفته  YYYY/MM/DD  H:MM:SS AM/PM»
   - فقط متنِ یک المان را به‌روز می‌کند؛ هیچ منطق دیگری تغییر نمی‌کند
   ============================================================ */
(function () {
    var _DASH_WEEKDAYS = ['یکشنبه', 'دوشنبه', 'سه‌شنبه', 'چهارشنبه', 'پنجشنبه', 'جمعه', 'شنبه'];

    function _dashTopbarTick() {
        var el = document.getElementById('dash-topbar-datetime');
        if (!el) return;
        try {
            var d = (typeof _getAfghNow === 'function') ? _getAfghNow() : new Date();

            // نام روز هفته (مستقل از کتابخانه، هماهنگ با ساعت افغانستان)
            var wd = _DASH_WEEKDAYS[d.getDay()] || '';

            // بخش تاریخ شمسی — دقیقاً مثل مقدار پیش‌فرض فیلدهای تاریخ
            var datePart = '';
            try {
                if (typeof PersianDate !== 'undefined') {
                    datePart = new PersianDate(d).format('YYYY/MM/DD');
                }
            } catch (e) { datePart = ''; }

            // بخش ساعت ۱۲ساعته با ثانیه و AM/PM — دقیقاً مثل فیلدهای تاریخ
            var h24 = d.getHours();
            var ampm = h24 >= 12 ? 'PM' : 'AM';
            var h12 = h24 % 12; if (h12 === 0) h12 = 12;
            var mm = d.getMinutes() < 10 ? '0' + d.getMinutes() : '' + d.getMinutes();
            var ss = d.getSeconds() < 10 ? '0' + d.getSeconds() : '' + d.getSeconds();
            var timePart = h12 + ':' + mm + ':' + ss + ' ' + ampm;

            var out = wd + '  ' + datePart + '  ' + timePart;

            // هماهنگی با سیستم اعداد فعلی برنامه
            try {
                if (typeof getNumberSystem === 'function' && getNumberSystem() === 'fa'
                    && typeof toPersianDigits === 'function') {
                    out = toPersianDigits(out);
                }
            } catch (e) {}

            if (el.textContent !== out) el.textContent = out;
        } catch (e) {}
    }

    function _dashTopbarStart() {
        _dashTopbarTick();
        if (!window._dashTopbarTimer) {
            window._dashTopbarTimer = setInterval(_dashTopbarTick, 1000);
        }
    }

    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', _dashTopbarStart);
    } else {
        _dashTopbarStart();
    }
})();

// =============================================================================
// ===== سیستم چند گدام (انبار) — انتخاب، افزودن، ویرایش، حذف، انتقال =====
// (افزوده‌شده بدون تغییر در محاسبات سایر بخش‌ها — db.getProducts روی گدام فعال فیلتر می‌شود)
// توابع به‌صورت اعلان سطح‌بالا تعریف شده‌اند تا مثل بقیهٔ کد از onclick سراسری در دسترس باشند.
// =============================================================================
    function _whEsc(s) {
        return String(s == null ? '' : s)
            .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
            .replace(/"/g, '&quot;').replace(/'/g, '&#39;');
    }

    // ---------- زیرساخت مودال (هماهنگ با کلاس‌های مودال موجود) ----------
    function _whCloseModal() {
        _whEditingTransferId = null;                 // لغوِ حالتِ ویرایش هنگامِ بستن/لغو
        var _bulk = document.getElementById('wh-bulk-overlay');
        if (_bulk) _bulk.remove();
        var m = document.getElementById('wh-modal');
        if (m && m.parentNode) m.parentNode.removeChild(m);
        // بستن هر picker تاریخ باز
        var cal = document.getElementById('_dual_cal_overlay');
        if (cal && cal.parentNode) cal.parentNode.removeChild(cal);
        // بستن dropdown جستجوی body-level (در صورت باز بودن)
        var dd = document.getElementById('_psr_body_dd');
        if (dd) {
            dd.style.display = 'none';
            dd.innerHTML = '';
            if (dd._scrollHandler) { window.removeEventListener('scroll', dd._scrollHandler, true); dd._scrollHandler = null; }
            dd._activeWrapper = null;
            dd._activeInput = null;
        }
    }
    window._whCloseModal = _whCloseModal;

    function _whModal(opts) {
        _whCloseModal();
        opts = opts || {};
        var overlay = document.createElement('div');
        overlay.className = 'modal';
        overlay.id = 'wh-modal';
        overlay.style.display = 'block';
        overlay.innerHTML =
            '<div class="modal-content wh-modal-content">' +
                '<div class="modal-header">' +
                    '<h3>' + (opts.title || '') + '</h3>' +
                    '<span class="close-modal" onclick="_whCloseModal()">&times;</span>' +
                '</div>' +
                '<div class="modal-body">' + (opts.body || '') + '</div>' +
                '<div class="modal-footer">' + (opts.footer || '') + '</div>' +
            '</div>';
        // کلیک روی پس‌زمینهٔ تیره مودال را می‌بندد
        overlay.addEventListener('click', function (e) {
            if (e.target === overlay) _whCloseModal();
        });
        document.body.appendChild(overlay);
        if (typeof applyNumberSystemToDocument === 'function') {
            try { applyNumberSystemToDocument(); } catch (e) {}
        }
        return overlay;
    }

    // مودال ورودی متن (افزودن/ویرایش نام گدام) — با طراحی فورم‌های موجود
    function _whPromptModal(title, label, defaultValue, onSubmit) {
        _whModal({
            title: title,
            body:
                '<div class="wh-form-grid" style="grid-template-columns:1fr;">' +
                    '<div class="wh-field full">' +
                        '<label>' + _whEsc(label) + '</label>' +
                        '<input type="text" id="wh-prompt-input" value="' + _whEsc(defaultValue || '') + '" autocomplete="off">' +
                    '</div>' +
                '</div>',
            footer:
                '<button class="btn-secondary" onclick="_whCloseModal()">لغو</button>' +
                '<button class="btn-primary" id="wh-prompt-ok">تایید</button>'
        });
        var input = document.getElementById('wh-prompt-input');
        var ok = document.getElementById('wh-prompt-ok');
        if (input) { input.focus(); try { input.select(); } catch (e) {} }
        function submit() {
            var val = input ? input.value.trim() : '';
            if (!val) { showMessage('خطا', 'لطفاً یک نام معتبر وارد کنید'); return; }
            _whCloseModal();
            if (onSubmit) onSubmit(val);
        }
        if (ok) ok.onclick = submit;
        if (input) input.addEventListener('keydown', function (e) { if (e.key === 'Enter') submit(); });
    }

    // مودال تایید واقعی (showConfirm موجود بدون دیالوگ اجرا می‌شود) — از مودال تایید موجود استفاده می‌کند
    function _whConfirm(title, message, onYes) {
        var modal = document.getElementById('confirmModal');
        var t = document.getElementById('confirmTitle');
        var b = document.getElementById('confirmBody');
        var act = document.getElementById('confirmAction');
        if (!modal || !act) { if (onYes) onYes(); return; }
        if (t) t.innerHTML = '<i class="fas fa-exclamation-triangle"></i> ' + (title || 'تایید');
        if (b) b.innerHTML = message || '';
        // پاک کردن هندلرهای قبلی با جایگزینی دکمه
        var fresh = act.cloneNode(true);
        act.parentNode.replaceChild(fresh, act);
        fresh.onclick = function () {
            modal.style.display = 'none';
            if (onYes) onYes();
        };
        modal.style.display = 'block';
    }

    // ---------- برچسب گدام فعال کنار عنوان ----------
    function _updateActiveWarehouseLabel() {
        var el = document.getElementById('active-warehouse-label');
        if (!el) return;
        try {
            var list = db.getWarehouses();
            var id = db.getActiveWarehouseId();
            var wh = list.find(function (w) { return w.id == id; }) || list[0];
            el.textContent = wh ? wh.name : '';
        } catch (e) { el.textContent = ''; }
    }
    window._updateActiveWarehouseLabel = _updateActiveWarehouseLabel;

    // ---------- منوی انتخاب گدام ----------
    function renderWarehouseMenu() {
        var menu = document.getElementById('warehouse-menu-products');
        if (!menu) return;
        var list = db.getWarehouses();
        var activeId = db.getActiveWarehouseId();
        var allProducts = (typeof db.getAllProducts === 'function') ? db.getAllProducts() : [];

        var rows = list.map(function (w) {
            var count = allProducts.filter(function (p) { return (p.warehouseId || 'wh_main') == w.id; }).length;
            var isActive = (w.id == activeId);
            return '' +
                '<div class="wh-row' + (isActive ? ' active' : '') + '">' +
                    '<button type="button" class="wh-pick" onclick="switchWarehouse(\'' + _whEsc(w.id) + '\')">' +
                        '<i class="fas fa-check wh-check' + (isActive ? '' : ' hidden') + '"></i>' +
                        '<i class="fas fa-warehouse" style="color:var(--text-muted);font-size:13px;"></i>' +
                        '<span style="flex:1;">' + _whEsc(w.name) + '</span>' +
                        '<small style="color:var(--text-muted);font-weight:600;">' + count + ' جنس</small>' +
                    '</button>' +
                    '<button type="button" class="wh-dots" title="عملیات" onclick="openWarehouseRowMenu(event, \'' + _whEsc(w.id) + '\')">' +
                        '<i class="fas fa-ellipsis-v"></i>' +
                    '</button>' +
                '</div>';
        }).join('');

        menu.innerHTML =
            '<div class="wh-menu-head" style="display:flex;align-items:center;gap:8px;">' +
                '<button type="button" class="wh-transfer-iconbtn sales-card-kebab" title="تراکنش میان گدام‌ها" onclick="openTransferFromMenu()" ' +
                    'style="width:34px;height:34px;border:none;border-radius:8px;background:transparent;color:#7c3aed;cursor:pointer;display:inline-flex;align-items:center;justify-content:center;font-size:15px;flex:0 0 auto;">' +
                    '<i class="fas fa-right-left"></i>' +
                '</button>' +
                '<h4 style="margin:0;flex:1;">انتخاب گدام</h4>' +
            '</div>' +
            '<div class="wh-list">' + rows + '</div>' +
            '<button type="button" class="wh-add" onclick="promptAddWarehouse()">' +
                '<i class="fas fa-plus"></i> اضافه کردن انبار' +
            '</button>';

        if (typeof applyNumberSystemToDocument === 'function') {
            try { applyNumberSystemToDocument(); } catch (e) {}
        }
    }
    window.renderWarehouseMenu = renderWarehouseMenu;

    function toggleWarehouseMenu() {
        if (typeof _attachFsCloseHandler === 'function') _attachFsCloseHandler();
        var menu = document.getElementById('warehouse-menu-products');
        if (!menu) return;
        var isOpen = menu.style.display === 'block';
        // بستن همهٔ منوهای دیگر (مثل toggleSortMenu)
        document.querySelectorAll('.sort-menu, .filter-menu').forEach(function (m) { m.style.display = 'none'; });
        // بستن منوی شناور سه‌نقطه اگر باز است
        _closeWarehouseRowMenu();
        if (!isOpen) {
            renderWarehouseMenu();
            menu.style.display = 'block';
        }
    }
    window.toggleWarehouseMenu = toggleWarehouseMenu;

    function switchWarehouse(id) {
        db.setActiveWarehouseId(id);

        // ریست فیلترهای انبار تا با گدام جدید هماهنگ شوند (دستهٔ کالا به‌صورت تنبل دوباره پر می‌شود)
        var catEl = document.getElementById('filter-product-category');
        if (catEl) { catEl.innerHTML = '<option value="all">همه</option>'; catEl.value = 'all'; }
        var stockEl = document.getElementById('filter-stock-status');
        if (stockEl) stockEl.value = 'all';
        var searchEl = document.getElementById('global-search-products');
        if (searchEl) searchEl.value = '';

        if (typeof loadProductsList === 'function') loadProductsList();
        if (typeof loadDashboard === 'function') { try { loadDashboard(); } catch (e) {} }
        if (typeof applyNumberSystemToDocument === 'function') { try { applyNumberSystemToDocument(); } catch (e) {} }
        _updateActiveWarehouseLabel();

        // بستن منو
        var menu = document.getElementById('warehouse-menu-products');
        if (menu) menu.style.display = 'none';
        _closeWarehouseRowMenu();
    }
    window.switchWarehouse = switchWarehouse;

    function promptAddWarehouse() {
        var menu = document.getElementById('warehouse-menu-products');
        if (menu) menu.style.display = 'none';
        _whPromptModal('اضافه کردن انبار', 'نام گدام', '', function (name) {
            var res = db.addWarehouse(name);
            if (res && res.success) {
                switchWarehouse(res.data.id);
                showMessage('موفقیت', 'گدام جدید اضافه شد');
            } else {
                showMessage('خطا', (res && res.error) || 'افزودن گدام ناموفق بود');
            }
        });
    }
    window.promptAddWarehouse = promptAddWarehouse;

    // بازکردنِ فورمِ «تراکنش میان گدام‌ها» از آیکنِ هدرِ دیالوگِ انتخاب گدام.
    // گدامِ فعال را به‌عنوانِ مبدأِ پیش‌فرض می‌گیرد (کاربر می‌تواند داخلِ فورم مبدأ/مقصد را عوض کند).
    function openTransferFromMenu() {
        var menu = document.getElementById('warehouse-menu-products');
        if (menu) menu.style.display = 'none';
        var id = null;
        try { id = (db && db.getActiveWarehouseId) ? db.getActiveWarehouseId() : null; } catch (e) {}
        if (!id) { try { var ws = db.getWarehouses(); id = ws && ws[0] && ws[0].id; } catch (e) {} }
        if (typeof openTransferForm === 'function') openTransferForm(id);
    }
    window.openTransferFromMenu = openTransferFromMenu;

    // ---------- منوی شناور سه‌نقطهٔ هر گدام ----------
    function _closeWarehouseRowMenu() {
        var m = document.getElementById('wh-row-menu');
        if (m && m.parentNode) m.parentNode.removeChild(m);
        document.removeEventListener('click', _whRowMenuOutside, true);
    }
    function _whRowMenuOutside(e) {
        var m = document.getElementById('wh-row-menu');
        if (!m) return;
        if (!m.contains(e.target) && !e.target.closest('.wh-dots')) {
            _closeWarehouseRowMenu();
        }
    }

    function openWarehouseRowMenu(event, id) {
        if (event) { event.stopPropagation(); event.preventDefault(); }
        _closeWarehouseRowMenu();

        var btn = event ? event.currentTarget : null;
        var menu = document.createElement('div');
        menu.className = 'wh-row-menu';
        menu.id = 'wh-row-menu';
        menu.innerHTML =
            '<button type="button" onclick="renameWarehousePrompt(\'' + _whEsc(id) + '\')">' +
                '<i class="fas fa-pen" style="color:#2563eb;"></i> ویرایش نام</button>' +
            '<button type="button" onclick="deleteWarehouseConfirm(\'' + _whEsc(id) + '\')">' +
                '<i class="fas fa-trash" style="color:#dc2626;"></i> حذف انبار</button>';
        document.body.appendChild(menu);

        // موقعیت‌دهی زیر دکمهٔ سه‌نقطه
        if (btn) {
            var rect = btn.getBoundingClientRect();
            var mw = menu.offsetWidth || 190;
            var left = rect.right - mw;
            if (left < 6) left = 6;
            var top = rect.bottom + 4;
            if (top + menu.offsetHeight > window.innerHeight - 6) {
                top = Math.max(6, rect.top - menu.offsetHeight - 4);
            }
            menu.style.left = left + 'px';
            menu.style.top = top + 'px';
        }
        setTimeout(function () { document.addEventListener('click', _whRowMenuOutside, true); }, 0);
    }
    window.openWarehouseRowMenu = openWarehouseRowMenu;

    function renameWarehousePrompt(id) {
        _closeWarehouseRowMenu();
        var list = db.getWarehouses();
        var wh = list.find(function (w) { return w.id == id; });
        if (!wh) { showMessage('خطا', 'گدام یافت نشد'); return; }
        _whPromptModal('ویرایش نام گدام', 'نام جدید گدام', wh.name, function (name) {
            var res = db.renameWarehouse(id, name);
            if (res && res.success) {
                _updateActiveWarehouseLabel();
                var menu = document.getElementById('warehouse-menu-products');
                if (menu && menu.style.display === 'block') renderWarehouseMenu();
                showMessage('موفقیت', 'نام گدام ویرایش شد');
            } else {
                showMessage('خطا', (res && res.error) || 'ویرایش ناموفق بود');
            }
        });
    }
    window.renameWarehousePrompt = renameWarehousePrompt;

    function deleteWarehouseConfirm(id) {
        _closeWarehouseRowMenu();
        var list = db.getWarehouses();
        if (list.length <= 1) {
            showMessage('خطا', 'حداقل یک گدام باید باقی بماند و قابل حذف نیست');
            return;
        }
        var wh = list.find(function (w) { return w.id == id; });
        if (!wh) { showMessage('خطا', 'گدام یافت نشد'); return; }
        var allProducts = (typeof db.getAllProducts === 'function') ? db.getAllProducts() : [];
        var count = allProducts.filter(function (p) { return (p.warehouseId || 'wh_main') == id; }).length;

        _whConfirm(
            'حذف انبار',
            'آیا از حذف کامل گدام «' + _whEsc(wh.name) + '» مطمئن هستید؟<br>' +
            'با حذف این گدام، <b>' + count + ' جنس</b> و انتقال‌های مرتبط با آن برای همیشه حذف می‌شوند. این عمل قابل بازگشت نیست.',
            function () {
                var res = db.deleteWarehouse(id);
                if (res && res.success) {
                    // بازخوانی کامل با گدام فعال جدید
                    var catEl = document.getElementById('filter-product-category');
                    if (catEl) { catEl.innerHTML = '<option value="all">همه</option>'; catEl.value = 'all'; }
                    var stockEl = document.getElementById('filter-stock-status');
                    if (stockEl) stockEl.value = 'all';
                    if (typeof loadProductsList === 'function') loadProductsList();
                    if (typeof loadDashboard === 'function') { try { loadDashboard(); } catch (e) {} }
                    if (typeof applyNumberSystemToDocument === 'function') { try { applyNumberSystemToDocument(); } catch (e) {} }
                    _updateActiveWarehouseLabel();
                    var menu = document.getElementById('warehouse-menu-products');
                    if (menu && menu.style.display === 'block') renderWarehouseMenu();
                    showMessage('موفقیت', 'گدام حذف شد');
                } else {
                    showMessage('خطا', (res && res.error) || 'حذف ناموفق بود');
                }
            }
        );
    }
    window.deleteWarehouseConfirm = deleteWarehouseConfirm;

    // ---------- فورم انتقال میان گدام‌ها ----------
    var _whTransferFromId = null;
    var _whEditingTransferId = null;   // اگر مقدار داشته باشد، فورم در حالتِ «ویرایشِ انتقال» است
    var _whTransferSavedState = null;  // وضعیتِ فورمِ انتقال هنگامِ رفتن به پیکرِ لیستِ اجناس (A#1)

    function _whSourceProducts() {
        var srcEl = document.getElementById('wh-transfer-source');
        var srcId = (srcEl && srcEl.value) ? srcEl.value : _whTransferFromId;
        var all = (typeof db.getAllProducts === 'function') ? db.getAllProducts() : [];
        return all.filter(function (p) { return (p.warehouseId || 'wh_main') == srcId; });
    }

    function _whProductOptions() {
        var prods = _whSourceProducts();
        if (!prods.length) return '<option value="">— جنسی در این گدام نیست —</option>';
        var opts = '<option value="">انتخاب جنس...</option>';
        opts += prods.map(function (p) {
            return '<option value="' + _whEsc(p.id) + '">' + _whEsc(p.name) +
                ' (موجودی: ' + formatNumber(parseFloat(p.stock) || 0) + ' ' + _whEsc(p.unit || 'عدد') + ')</option>';
        }).join('');
        return opts;
    }

    function _whItemRowHtml() {
        return '' +
            '<tr class="wh-item-row">' +
                '<td class="wh-tr-num" style="text-align:center;">1</td>' +
                '<td>' +
                    '<div class="wh-search-wrap" style="position:relative;">' +
                        '<input type="text" class="wh-search-input product-search-input" placeholder="جستجوی اجناس و خدمات" autocomplete="off" onkeyup="_whItemSearch(this)" onfocus="_whItemSearch(this)">' +
                        '<input type="hidden" class="wh-item-product">' +
                        '<div class="wh-search-results"></div>' +
                    '</div>' +
                    '<div class="wh-stock-hint"></div>' +
                '</td>' +
                '<td><input type="number" class="wh-item-qty" min="0" step="any" placeholder="تعداد"></td>' +
                '<td style="text-align:center;"><span class="wh-item-unit">—</span></td>' +
                '<td style="text-align:center;"><button type="button" class="wh-row-del" onclick="_whTransferRemoveRow(this)"><i class="fas fa-times"></i></button></td>' +
            '</tr>';
    }

    function openTransferForm(fromId, editRec) {
        _closeWarehouseRowMenu();
        var menu = document.getElementById('warehouse-menu-products');
        if (menu) menu.style.display = 'none';

        _whEditingTransferId = (editRec && editRec.id != null) ? editRec.id : null;
        if (editRec && editRec.fromId != null) fromId = editRec.fromId;
        _whTransferFromId = fromId;
        var list = db.getWarehouses();
        var fromWh = list.find(function (w) { return w.id == fromId; });
        if (!fromWh) { showMessage('خطا', 'گدام مبدأ یافت نشد'); return; }
        if (!list || list.length < 2) {
            showMessage('خطا', 'برای انتقال باید حداقل یک گدام دیگر وجود داشته باشد. ابتدا یک گدام اضافه کنید.');
            return;
        }

        var srcOptions = list.map(function (w) {
            return '<option value="' + _whEsc(w.id) + '"' + (w.id == fromId ? ' selected' : '') + '>' + _whEsc(w.name) + '</option>';
        }).join('');
        var firstDest = list.find(function (w) { return w.id != fromId; });
        var destOptions = list.filter(function (w) { return w.id != fromId; }).map(function (w) {
            return '<option value="' + _whEsc(w.id) + '"' + (firstDest && w.id == firstDest.id ? ' selected' : '') + '>' + _whEsc(w.name) + '</option>';
        }).join('');

        var today = (typeof db.getCurrentDate === 'function') ? db.getCurrentDate() : '';

        // مودال مرکزی با پس‌زمینهٔ بلور (نه تمام‌صفحه) — رنگ/آیکن مطابق فورم بل فروش
        _whCloseModal();
        var overlay = document.createElement('div');
        overlay.className = 'wh-transfer-overlay';
        overlay.id = 'wh-modal';
        overlay.innerHTML =
            '<div class="wh-transfer-box">' +
                '<div class="wh-transfer-head">' +
                    '<span class="wh-transfer-title">انتقال اجناس میان گدام</span>' +
                    '<button type="button" class="wh-transfer-x" onclick="_whCloseModal()" title="لغو"><i class="fas fa-times"></i></button>' +
                '</div>' +
                '<div class="wh-transfer-bodyc">' +
                    '<div class="wh-tr-row3">' +
                        '<div class="wh-tr-field">' +
                            '<label><i class="fas fa-warehouse"></i> گدام مبدأ</label>' +
                            '<select id="wh-transfer-source" onchange="_whSourceChanged()">' + srcOptions + '</select>' +
                        '</div>' +
                        '<div class="wh-tr-field">' +
                            '<label><i class="fas fa-warehouse"></i> گدام مقصد</label>' +
                            '<select id="wh-transfer-dest">' + destOptions + '</select>' +
                        '</div>' +
                        '<div class="wh-tr-field">' +
                            '<label><i class="fas fa-calendar-alt"></i> تاریخ</label>' +
                            '<div class="wh-date-wrap">' +
                                '<input type="text" id="wh-transfer-date" value="' + _whEsc(today) + '" readonly>' +
                                '<button type="button" onclick="openDualCalendarPicker(\'wh-transfer-date\', this)"><i class="fas fa-calendar-alt"></i></button>' +
                            '</div>' +
                        '</div>' +
                    '</div>' +
                    '<div class="wh-tr-tablebox">' +
                        '<div class="wh-tr-tabletitle">اجناس و خدمات</div>' +
                        '<div class="wh-tr-tablescroll">' +
                        '<table class="wh-tr-table">' +
                            '<thead><tr>' +
                                '<th style="width:64px;">شماره</th>' +
                                '<th>جستجوی اجناس و خدمات</th>' +
                                '<th style="width:130px;">تعداد</th>' +
                                '<th style="width:120px;">واحد</th>' +
                                '<th style="width:54px;"></th>' +
                            '</tr></thead>' +
                            '<tbody id="wh-transfer-items">' + _whItemRowHtml() + '</tbody>' +
                        '</table>' +
                        '</div>' +
                        '<div class="wh-tr-addbar" style="display:flex;gap:8px;flex-wrap:wrap;">' +
                            '<button type="button" class="wh-tr-addbtn" onclick="_whTransferAddRow()"><i class="fas fa-plus"></i> افزودن جنس</button>' +
                            '<button type="button" class="wh-tr-addbtn wh-tr-whbtn" title="انتخاب چند جنس از گدام مبدأ" onclick="_whOpenBulkPicker()"><i class="fas fa-warehouse"></i> انتخاب از گدام</button>' +
                        '</div>' +
                    '</div>' +
                    '<div class="wh-tr-field">' +
                        '<label>اطلاعات بیشتر</label>' +
                        '<textarea id="wh-transfer-note" rows="2" placeholder="اطلاعات بیشتر..."></textarea>' +
                    '</div>' +
                '</div>' +
                '<div class="wh-transfer-foot">' +
                    '<button type="button" class="wh-tr-cancel" onclick="_whCloseModal()"><i class="fas fa-times"></i> لغو</button>' +
                    '<button type="button" class="wh-tr-submit" onclick="submitWarehouseTransfer()"><i class="fas fa-check"></i> ثبت</button>' +
                '</div>' +
            '</div>';
        overlay.addEventListener('click', function (e) { if (e.target === overlay) _whCloseModal(); });
        document.body.appendChild(overlay);
        if (typeof applyNumberSystemToDocument === 'function') { try { applyNumberSystemToDocument(); } catch (e) {} }
        if (editRec) { try { _whApplyEditRecord(editRec); } catch (e) {} }
    }
    window.openTransferForm = openTransferForm;

    // پرکردنِ فورم برای «ویرایشِ انتقال»: مبدأ/مقصد/تاریخ/توضیح + ردیف‌های اجناسِ رکورد.
    function _whApplyEditRecord(rec) {
        var srcEl = document.getElementById('wh-transfer-source');
        if (srcEl) srcEl.value = rec.fromId;
        _whSourceChanged();                       // بازسازیِ مقصد (بدونِ مبدأ) + پاک‌سازیِ ردیف‌ها
        var destEl = document.getElementById('wh-transfer-dest');
        if (destEl) destEl.value = rec.toId;
        var dateEl = document.getElementById('wh-transfer-date');
        if (dateEl && rec.date) dateEl.value = rec.date;
        var noteEl = document.getElementById('wh-transfer-note');
        if (noteEl) noteEl.value = rec.note || '';
        var tbody = document.getElementById('wh-transfer-items');
        if (tbody) {
            tbody.innerHTML = '';
            var srcProducts = _whSourceProducts();
            (rec.items || []).forEach(function (it) {
                var prod = srcProducts.find(function (p) { return String(p.id) === String(it.srcProductId); });
                _whTransferAddRow();
                var tr = tbody.lastElementChild;
                if (!tr) return;
                var input = tr.querySelector('.wh-search-input');
                var hidden = tr.querySelector('.wh-item-product');
                var unitSpan = tr.querySelector('.wh-item-unit');
                var qtyEl = tr.querySelector('.wh-item-qty');
                var hint = tr.querySelector('.wh-stock-hint');
                if (input) input.value = (prod && prod.name) || it.name || '';
                if (hidden) hidden.value = it.srcProductId;
                if (unitSpan) unitSpan.textContent = (prod && prod.unit) || it.unit || 'عدد';
                if (qtyEl) qtyEl.value = it.quantity;
                if (hint && prod) hint.textContent = 'موجودی فعلی: ' + (typeof _formatQtyWithUnits==='function' ? _formatQtyWithUnits(prod.stock, prod) : (formatNumber(parseFloat(prod.stock) || 0) + ' ' + (prod.unit || 'عدد')));
            });
            if (!tbody.children.length) tbody.innerHTML = _whItemRowHtml();
            _whUpdateRowNumbers();
        }
        var t = document.querySelector('.wh-transfer-title');
        if (t) t.textContent = 'ویرایش انتقال میان گدام';
        var sub = document.querySelector('.wh-tr-submit');
        if (sub) sub.innerHTML = '<i class="fas fa-check"></i> ذخیرهٔ ویرایش';
        if (typeof applyNumberSystemToDocument === 'function') { try { applyNumberSystemToDocument(); } catch (e) {} }
    }
    window._whApplyEditRecord = _whApplyEditRecord;

    // انتخابِ چند جنس از گدام مبدأ (همان رویکردِ انتخاب از گدام) → افزودنِ ردیف‌ها به لیستِ انتقال.
    // A#1 — «انتخاب از گدام» با همان رویکردِ «فروش فوری»: رفتن به همان لیستِ اجناسِ سیستم در
    // حالتِ انتخابِ چندگانه (سازوکارِ موجودِ _rpProductPick)، انتخابِ چند جنس، تأیید، و بازگشتِ
    // خودکار به فورمِ انتقال با افزودنِ اجناس. هیچ Picker/فرمِ جدیدی ساخته نمی‌شود.
    function _whOpenBulkPicker() {
        var srcEl = document.getElementById('wh-transfer-source');
        var destEl = document.getElementById('wh-transfer-dest');
        var dateEl = document.getElementById('wh-transfer-date');
        var noteEl = document.getElementById('wh-transfer-note');
        var fromId = (srcEl && srcEl.value) ? srcEl.value : _whTransferFromId;
        if (!fromId) { showMessage('خطا', 'ابتدا گدام مبدأ را انتخاب کنید'); return; }
        // ذخیرهٔ کاملِ وضعیتِ فورم تا پس از انتخاب بازسازی شود
        var items = [];
        document.querySelectorAll('#wh-transfer-items tr').forEach(function (tr) {
            var pid = (tr.querySelector('.wh-item-product') || {}).value;
            var qty = (tr.querySelector('.wh-item-qty') || {}).value;
            if (pid) items.push({ productId: pid, quantity: qty });
        });
        _whTransferSavedState = {
            fromId: fromId,
            toId: destEl ? destEl.value : '',
            date: dateEl ? dateEl.value : '',
            note: noteEl ? noteEl.value : '',
            editId: _whEditingTransferId,
            items: items,
            prevActiveWh: (db.getActiveWarehouseId ? db.getActiveWarehouseId() : null)
        };
        // پیش‌انتخابِ اجناسِ موجود در لیست
        var selected = {};
        items.forEach(function (it) {
            var p = (db.getAllProducts ? db.getAllProducts() : []).find(function (x) { return String(x.id) === String(it.productId); });
            selected[String(it.productId)] = { id: String(it.productId), name: p ? p.name : String(it.productId) };
        });
        // سوییچِ موقتِ گدامِ فعال به مبدأ تا «همان لیستِ اجناس» اجناسِ مبدأ را نشان دهد
        try { if (fromId && db.getActiveWarehouseId && db.getActiveWarehouseId() != fromId && db.setActiveWarehouseId) db.setActiveWarehouseId(fromId); } catch (e) {}
        _whCloseModal();   // بستنِ مودال (وضعیت قبلاً ذخیره شد؛ _whEditingTransferId داخلِ state است)
        // فعال‌سازیِ همان سازوکارِ چندانتخابیِ سیستم با هدفِ transfer
        _rpProductPick = { target: 'transfer', selected: selected };
        _productPickerReturnSection = 'products-list';
        _productPickerInput = { __rpMulti: true };
        _productPickerIsPurchase = false;
        if (typeof showSection === 'function') showSection('products-list');
        if (typeof loadProductsList === 'function') loadProductsList();
        setTimeout(function () { if (typeof _rpDecorateProductPick === 'function') _rpDecorateProductPick(); }, 0);
    }
    window._whOpenBulkPicker = _whOpenBulkPicker;

    // بازگشت از پیکر به فورمِ انتقال: بازگرداندنِ گدامِ فعال + وضعیتِ فورم + افزودنِ اجناسِ انتخاب‌شده
    function _whReopenAfterPick(pickedList) {
        var st = _whTransferSavedState || {};
        _whTransferSavedState = null;
        try { if (st.prevActiveWh != null && db.getActiveWarehouseId && db.getActiveWarehouseId() != st.prevActiveWh && db.setActiveWarehouseId) db.setActiveWarehouseId(st.prevActiveWh); } catch (e) {}
        // مودالِ تازه با مبدأ
        openTransferForm(st.fromId);
        var destEl = document.getElementById('wh-transfer-dest'); if (destEl && st.toId) destEl.value = st.toId;
        var dateEl = document.getElementById('wh-transfer-date'); if (dateEl && st.date) dateEl.value = st.date;
        var noteEl = document.getElementById('wh-transfer-note'); if (noteEl) noteEl.value = st.note || '';
        var tbody = document.getElementById('wh-transfer-items'); if (tbody) tbody.innerHTML = '';
        // ادغامِ ردیف‌های قبلی + انتخاب‌های جدید (بدونِ تکرار)
        var order = [], qtyMap = {};
        (st.items || []).forEach(function (it) { var k = String(it.productId); if (!(k in qtyMap)) { qtyMap[k] = it.quantity; order.push(k); } });
        (pickedList || []).forEach(function (p) { var k = String(p.id); if (!(k in qtyMap)) { qtyMap[k] = ''; order.push(k); } });
        var srcProducts = _whSourceProducts();
        order.forEach(function (pid) {
            var prod = srcProducts.find(function (p) { return String(p.id) === pid; });
            if (!prod) return;   // فقط اجناسِ گدامِ مبدأ
            _whTransferAddRow();
            var tr = tbody.lastElementChild; if (!tr) return;
            var input = tr.querySelector('.wh-search-input'), hidden = tr.querySelector('.wh-item-product');
            var unitSpan = tr.querySelector('.wh-item-unit'), qtyEl = tr.querySelector('.wh-item-qty'), hint = tr.querySelector('.wh-stock-hint');
            if (input) input.value = prod.name || '';
            if (hidden) hidden.value = prod.id;
            if (unitSpan) unitSpan.textContent = prod.unit || 'عدد';
            if (qtyEl && qtyMap[pid] !== '' && qtyMap[pid] != null) qtyEl.value = qtyMap[pid];
            if (hint) hint.textContent = 'موجودی فعلی: ' + (typeof _formatQtyWithUnits==='function' ? _formatQtyWithUnits(prod.stock, prod) : (formatNumber(parseFloat(prod.stock) || 0) + ' ' + (prod.unit || 'عدد')));
        });
        if (!tbody.children.length) tbody.innerHTML = _whItemRowHtml();
        _whUpdateRowNumbers();
        // بازگردانیِ حالتِ ویرایش
        if (st.editId != null) {
            _whEditingTransferId = st.editId;
            var t = document.querySelector('.wh-transfer-title'); if (t) t.textContent = 'ویرایش انتقال میان گدام';
            var sub = document.querySelector('.wh-tr-submit'); if (sub) sub.innerHTML = '<i class="fas fa-check"></i> ذخیرهٔ ویرایش';
        }
        if (typeof applyNumberSystemToDocument === 'function') { try { applyNumberSystemToDocument(); } catch (e) {} }
    }
    window._whReopenAfterPick = _whReopenAfterPick;

    // افزودنِ یک جنسِ انتخاب‌شده به‌عنوانِ ردیفِ انتقال (ردیفِ خالیِ اول را بازاستفاده می‌کند).
    function _whAddPickedProduct(prod) {
        var tbody = document.getElementById('wh-transfer-items');
        if (!tbody) return;
        var tr = null;
        var rows = tbody.querySelectorAll('tr');
        for (var i = 0; i < rows.length; i++) {
            var h = rows[i].querySelector('.wh-item-product');
            if (h && !h.value) { tr = rows[i]; break; }   // ردیفِ خالیِ موجود
        }
        if (!tr) { _whTransferAddRow(); tr = tbody.lastElementChild; }
        if (!tr) return;
        var input = tr.querySelector('.wh-search-input');
        var hidden = tr.querySelector('.wh-item-product');
        var unitSpan = tr.querySelector('.wh-item-unit');
        var hint = tr.querySelector('.wh-stock-hint');
        if (input) input.value = prod.name || '';
        if (hidden) hidden.value = prod.id;
        if (unitSpan) unitSpan.textContent = prod.unit || 'عدد';
        if (hint) hint.textContent = 'موجودی فعلی: ' + (typeof _formatQtyWithUnits==='function' ? _formatQtyWithUnits(prod.stock, prod) : (formatNumber(parseFloat(prod.stock) || 0) + ' ' + (prod.unit || 'عدد')));
        _whUpdateRowNumbers();
        if (typeof applyNumberSystemToDocument === 'function') { try { applyNumberSystemToDocument(); } catch (e) {} }
    }
    window._whAddPickedProduct = _whAddPickedProduct;

    function _whUpdateRowNumbers() {
        var rows = document.querySelectorAll('#wh-transfer-items tr');
        for (var i = 0; i < rows.length; i++) {
            var c = rows[i].querySelector('.wh-tr-num');
            if (c) c.textContent = (i + 1);
        }
    }
    window._whUpdateRowNumbers = _whUpdateRowNumbers;

    function _whTransferAddRow() {
        var tbody = document.getElementById('wh-transfer-items');
        if (!tbody) return;
        var tmp = document.createElement('tbody');
        tmp.innerHTML = _whItemRowHtml();
        var tr = tmp.querySelector('tr');
        if (tr) tbody.appendChild(tr);
        _whUpdateRowNumbers();
        if (typeof applyNumberSystemToDocument === 'function') { try { applyNumberSystemToDocument(); } catch (e) {} }
    }
    window._whTransferAddRow = _whTransferAddRow;

    function _whTransferRemoveRow(btn) {
        var tbody = document.getElementById('wh-transfer-items');
        var tr = btn.closest('tr');
        if (tr && tbody && tbody.children.length > 1) {
            tr.parentNode.removeChild(tr);
        } else if (tr) {
            // اگر آخرین ردیف بود، فقط مقادیر را پاک کن
            var inp = tr.querySelector('.wh-search-input');
            var hid = tr.querySelector('.wh-item-product');
            var qty = tr.querySelector('.wh-item-qty');
            var unit = tr.querySelector('.wh-item-unit');
            var hint = tr.querySelector('.wh-stock-hint');
            var res = tr.querySelector('.wh-search-results');
            if (inp) inp.value = '';
            if (hid) hid.value = '';
            if (qty) qty.value = '';
            if (unit) unit.textContent = '—';
            if (hint) hint.textContent = '';
            if (res) { res.style.display = 'none'; res.innerHTML = ''; }
        }
        _whUpdateRowNumbers();
    }
    window._whTransferRemoveRow = _whTransferRemoveRow;

    // وقتی گدام مبدأ عوض شد: ردیف‌های اجناس پاک و dropdown مقصد بدون گدام مبدأ بازسازی می‌شود
    function _whSourceChanged() {
        var tbody = document.getElementById('wh-transfer-items');
        if (tbody) tbody.innerHTML = _whItemRowHtml();
        var srcEl = document.getElementById('wh-transfer-source');
        var destEl = document.getElementById('wh-transfer-dest');
        if (srcEl && destEl) {
            var srcId = srcEl.value;
            var prevDest = destEl.value;
            var list = db.getWarehouses();
            var opts = list.filter(function (w) { return w.id != srcId; }).map(function (w) {
                var sel = (String(w.id) === String(prevDest) && String(w.id) !== String(srcId)) ? ' selected' : '';
                return '<option value="' + _whEsc(w.id) + '"' + sel + '>' + _whEsc(w.name) + '</option>';
            }).join('');
            destEl.innerHTML = opts;
        }
        _whUpdateRowNumbers();
        if (typeof applyNumberSystemToDocument === 'function') { try { applyNumberSystemToDocument(); } catch (e) {} }
    }
    window._whSourceChanged = _whSourceChanged;

    // جستجوی اجناس از گدام مبدأ (آفلاین، فقط اجناس همان گدام)
    // جستجوی اجناس از گدام مبدأ — دقیقاً با همان منطقِ dropdownِ بل فروش.
    // نتایج در یک container سراسری در body با position:fixed نمایش داده می‌شوند تا
    // از کلیپِ overflow مودال خارج باشند و پیش از انتخاب کاملاً قابل‌نمایش شوند.
    function _whItemSearch(input) {
        var wrap = input.closest('.wh-search-wrap');
        var hidden = wrap ? wrap.querySelector('.wh-item-product') : null;
        var tr = input.closest('tr');
        var unitSpan = tr ? tr.querySelector('.wh-item-unit') : null;
        var hint = tr ? tr.querySelector('.wh-stock-hint') : null;
        if (hidden) hidden.value = '';
        if (unitSpan) unitSpan.textContent = '—';
        if (hint) hint.textContent = '';

        // بستن container body-level قبلی (همان عنصرِ بل فروش)
        var _existDD = document.getElementById('_psr_body_dd');
        if (_existDD) {
            _existDD.style.display = 'none';
            _existDD.innerHTML = '';
            if (_existDD._scrollHandler) { window.removeEventListener('scroll', _existDD._scrollHandler, true); _existDD._scrollHandler = null; }
        }

        var q = (input.value || '').toLowerCase().trim();
        if (q.length === 0) return;

        // جستجوی substring روی اجناس گدام مبدأ (همان منطقِ بل فروش)
        var matches = _whSourceProducts().filter(function (p) {
            var nameMatch = (p.name || '').toLowerCase().indexOf(q) !== -1;
            var codeMatch = p.code && String(p.code).toLowerCase().indexOf(q) !== -1;
            return nameMatch || codeMatch;
        });
        matches.sort(function (a, b) {
            var aN = (a.name || '').toLowerCase(), bN = (b.name || '').toLowerCase();
            var aP = aN.indexOf(q) === 0 ? 0 : 1, bP = bN.indexOf(q) === 0 ? 0 : 1;
            if (aP !== bP) return aP - bP;
            return aN.localeCompare(bN);
        });
        if (!matches.length) return;

        // تزریق یک‌بارهٔ CSS هاور (همان عنصرِ بل فروش)
        if (!document.getElementById('_psr_hover_style')) {
            var _psrStyle = document.createElement('style');
            _psrStyle.id = '_psr_hover_style';
            _psrStyle.textContent =
                '.product-search-results{contain:layout style;-webkit-user-select:none;user-select:none;pointer-events:auto;}' +
                '.product-search-result-item{transition:background-color .08s;will-change:auto;}' +
                '.product-search-result-item:hover{background:#f0f7ff !important;}';
            document.head.appendChild(_psrStyle);
        }

        var limited = matches.slice(0, 5);
        var html = '';
        limited.forEach(function (p) {
            var name = p.name || '';
            var lowerName = name.toLowerCase();
            var matchIdx = lowerName.indexOf(q);
            var displayName = _whEsc(name);
            if (matchIdx !== -1) {
                displayName = _whEsc(name.substring(0, matchIdx))
                    + '<strong style="color:var(--primary,#6366f1);">' + _whEsc(name.substring(matchIdx, matchIdx + q.length)) + '</strong>'
                    + _whEsc(name.substring(matchIdx + q.length));
            }
            var codeStr = p.code ? '<span style="color:#94a3b8;font-size:10.5px;margin-right:6px;">' + _whEsc(String(p.code)) + '</span>' : '';
            var stockStr = '<span style="color:#64748b;font-size:10.5px;margin-right:auto;white-space:nowrap;">' + formatNumber(parseFloat(p.stock) || 0) + ' ' + _whEsc(p.unit || 'عدد') + '</span>';
            html += '<div class="product-search-result-item" '
                + 'style="padding:6px 10px;cursor:pointer;border-bottom:1px solid #f1f5f9;font-size:12.5px;display:flex;align-items:center;gap:6px;line-height:1.4;" '
                + 'onmousedown="event.preventDefault();_whSelectFromDD(this,' + p.id + ')">'
                + '<span style="font-weight:500;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;min-width:0;">' + displayName + '</span>'
                + codeStr + stockStr
                + '</div>';
        });

        // container سراسری در body (مثل بل فروش) برای جلوگیری از کلیپِ overflow/transform
        var _bodyDD = document.getElementById('_psr_body_dd');
        if (!_bodyDD) {
            _bodyDD = document.createElement('div');
            _bodyDD.id = '_psr_body_dd';
            _bodyDD.className = 'product-search-results';
            _bodyDD.style.cssText = 'display:none;position:fixed;z-index:99999;border-radius:8px;' +
                'box-shadow:0 6px 20px rgba(15,23,42,0.15);background:#fff;overflow-y:auto;' +
                'contain:layout style;-webkit-user-select:none;user-select:none;pointer-events:auto;';
            document.body.appendChild(_bodyDD);
        }
        _bodyDD.innerHTML = html;
        _bodyDD._activeWrapper = wrap;
        _bodyDD._activeInput = input;

        // موقعیت‌دهیِ هوشمند: پایینِ input یا بالای آن اگر فضای پایین کافی نباشد
        function _positionBodyDD() {
            var r = (_bodyDD._activeInput || input).getBoundingClientRect();
            var spaceBelow = window.innerHeight - r.bottom - 6;
            var spaceAbove = r.top - 6;
            var maxH = 220;
            _bodyDD.style.left = r.left + 'px';
            _bodyDD.style.width = r.width + 'px';
            _bodyDD.style.right = 'auto';
            if (spaceBelow >= 120 || spaceBelow >= spaceAbove) {
                _bodyDD.style.top = (r.bottom + 2) + 'px';
                _bodyDD.style.bottom = 'auto';
                _bodyDD.style.maxHeight = Math.min(maxH, Math.max(spaceBelow, 80)) + 'px';
            } else {
                _bodyDD.style.top = 'auto';
                _bodyDD.style.bottom = (window.innerHeight - r.top + 2) + 'px';
                _bodyDD.style.maxHeight = Math.min(maxH, Math.max(spaceAbove, 80)) + 'px';
            }
        }
        _positionBodyDD();
        _bodyDD.style.display = 'block';

        // ردیابیِ اسکرول با rAF برای به‌روزرسانیِ موقعیت
        if (_bodyDD._scrollHandler) window.removeEventListener('scroll', _bodyDD._scrollHandler, true);
        var _rafId = null;
        _bodyDD._scrollHandler = function () {
            if (_rafId) return;
            _rafId = requestAnimationFrame(function () {
                _rafId = null;
                if (!_bodyDD || _bodyDD.style.display === 'none') return;
                _positionBodyDD();
            });
        };
        window.addEventListener('scroll', _bodyDD._scrollHandler, true);
    }
    window._whItemSearch = _whItemSearch;

    function _whSelectFromDD(itemEl, pid) {
        var _bodyDD = document.getElementById('_psr_body_dd');
        var wrap = (itemEl && itemEl.closest) ? itemEl.closest('.wh-search-wrap') : null;
        if (!wrap && _bodyDD) wrap = _bodyDD._activeWrapper;
        // بستن container body-level
        if (_bodyDD) {
            _bodyDD.style.display = 'none';
            _bodyDD.innerHTML = '';
            if (_bodyDD._scrollHandler) { window.removeEventListener('scroll', _bodyDD._scrollHandler, true); _bodyDD._scrollHandler = null; }
            _bodyDD._activeWrapper = null;
            _bodyDD._activeInput = null;
        }
        if (!wrap) return;
        var tr = wrap.closest('tr');
        var prod = _whSourceProducts().find(function (p) { return String(p.id) === String(pid); });
        if (!prod || !tr) return;
        var input = tr.querySelector('.wh-search-input');
        var hidden = tr.querySelector('.wh-item-product');
        var unitSpan = tr.querySelector('.wh-item-unit');
        var hint = tr.querySelector('.wh-stock-hint');
        if (input) input.value = prod.name || '';
        if (hidden) hidden.value = prod.id;
        if (unitSpan) unitSpan.textContent = prod.unit || 'عدد';
        if (hint) hint.textContent = 'موجودی فعلی: ' + (typeof _formatQtyWithUnits==='function' ? _formatQtyWithUnits(prod.stock, prod) : (formatNumber(parseFloat(prod.stock) || 0) + ' ' + (prod.unit || 'عدد')));
        if (typeof applyNumberSystemToDocument === 'function') { try { applyNumberSystemToDocument(); } catch (e) {} }
    }
    window._whSelectFromDD = _whSelectFromDD;

    function submitWarehouseTransfer() {
        var destSel = document.getElementById('wh-transfer-dest');
        var dateEl = document.getElementById('wh-transfer-date');
        var noteEl = document.getElementById('wh-transfer-note');
        var srcSel = document.getElementById('wh-transfer-source');
        var fromId = (srcSel && srcSel.value) ? srcSel.value : _whTransferFromId;
        var toId = destSel ? destSel.value : '';

        if (!fromId || !toId) { showMessage('خطا', 'گدام مبدأ یا مقصد نامعتبر است'); return; }
        if (fromId == toId) { showMessage('خطا', 'گدام مبدأ و مقصد نمی‌توانند یکی باشند'); return; }

        var list = db.getWarehouses();
        var fromWh = list.find(function (w) { return w.id == fromId; });
        var toWh = list.find(function (w) { return w.id == toId; });
        if (!fromWh || !toWh) { showMessage('خطا', 'گدام یافت نشد'); return; }

        // جمع‌آوری ردیف‌ها
        var rows = Array.prototype.slice.call(document.querySelectorAll('#wh-transfer-items tr'));
        var srcProducts = _whSourceProducts();
        var requested = []; // {srcProduct, qty}
        var totalByProduct = {};

        for (var i = 0; i < rows.length; i++) {
            var sel = rows[i].querySelector('.wh-item-product');
            var qtyInput = rows[i].querySelector('.wh-item-qty');
            var pid = sel ? sel.value : '';
            var qty = qtyInput ? parseFloat(qtyInput.value) : 0;
            if (!pid) continue;
            if (!qty || qty <= 0) { showMessage('خطا', 'تعداد هر ردیف باید بزرگ‌تر از صفر باشد'); return; }
            var prod = srcProducts.find(function (p) { return p.id == pid; });
            if (!prod) { showMessage('خطا', 'جنس انتخاب‌شده در گدام مبدأ یافت نشد'); return; }
            totalByProduct[pid] = (totalByProduct[pid] || 0) + qty;
            requested.push({ srcProduct: prod, qty: qty });
        }

        if (!requested.length) { showMessage('خطا', 'حداقل یک جنس را برای انتقال انتخاب کنید'); return; }

        // در حالتِ ویرایش، مقدارِ قبلیِ همین انتقال قبلاً از موجودیِ مبدأ کسر شده؛ برای بررسیِ
        // کفایت آن را به موجودیِ در دسترس بازمی‌گردانیم تا ویرایش با همان/کمترین مقادیر رد نشود.
        var _editOldSrcQty = {};
        if (_whEditingTransferId) {
            try {
                var _oldRec = (db.getTransfers() || []).find(function (t) { return t.id == _whEditingTransferId; });
                if (_oldRec && Array.isArray(_oldRec.items)) _oldRec.items.forEach(function (it) {
                    if (it.srcProductId != null) _editOldSrcQty[String(it.srcProductId)] = (_editOldSrcQty[String(it.srcProductId)] || 0) + (parseFloat(it.quantity) || 0);
                });
            } catch (e) {}
        }

        // بررسی کفایت موجودی (مجموع هر جنس)
        for (var pid2 in totalByProduct) {
            if (!totalByProduct.hasOwnProperty(pid2)) continue;
            var p2 = srcProducts.find(function (p) { return p.id == pid2; });
            var avail = (p2 ? (parseFloat(p2.stock) || 0) : 0) + (_editOldSrcQty[String(pid2)] || 0);
            if (totalByProduct[pid2] > avail) {
                showMessage('خطا', 'موجودی «' + (p2 ? p2.name : '') + '» کافی نیست (موجودی: ' +
                    formatNumber(avail) + '، درخواست: ' + formatNumber(totalByProduct[pid2]) + ')');
                return;
            }
        }

        var allProducts = (typeof db.getAllProducts === 'function') ? db.getAllProducts() : [];
        var recItems = [];

        requested.forEach(function (r) {
            var src = r.srcProduct;
            var qty = r.qty;

            // کاهش موجودی مبدأ (در حالتِ ویرایش این کار را نمی‌کنیم؛ rebuild موجودی را از صفر
            // و از روی رکوردِ ویرایش‌شده بازمحاسبه می‌کند تا دوبار کسر نشود)
            if (!_whEditingTransferId) db.adjustProductStockById(src.id, -qty);

            // یافتن جنس متناظر در گدام مقصد (نام + واحد یکسان)
            var dest = allProducts.find(function (p) {
                return (p.warehouseId || 'wh_main') == toId &&
                    (p.name || '') == (src.name || '') &&
                    (p.unit || '') == (src.unit || '');
            });

            var destId;
            if (dest) {
                if (!_whEditingTransferId) {
                    // حفظ ارزش دارایی (سرمایه): انتقال فقط جابه‌جایی فیزیکی است و نباید مجموع سرمایه را
                    // تغییر دهد. جنس به ارزش «قیمت خرید مبدأ» منتقل می‌شود؛ اگر قیمت خرید جنس در گدام
                    // مقصد با مبدأ فرق داشته باشد، قیمت خرید مقصد به «میانگین وزنی» موجودی قبلی و مقدار
                    // واردشده به‌روز می‌شود تا مجموع سرمایه دقیقاً ثابت بماند. اگر قیمت‌ها برابر باشند هیچ
                    // تغییری رخ نمی‌دهد (رفتار قبلی بدون تغییر).
                    var _raw = db.getAllProducts();
                    var _di = _raw.findIndex(function (p) { return p.id == dest.id; });
                    if (_di !== -1) {
                        var _dStock = parseFloat(_raw[_di].stock) || 0; // موجودی مقصد پیش از افزودن
                        var _denom = _dStock + qty;
                        if (_denom > 0) {
                            var _sAfn = parseFloat(src.purchasePriceAFN) || 0, _sUsd = parseFloat(src.purchasePriceUSD) || 0;
                            var _dAfn = parseFloat(_raw[_di].purchasePriceAFN) || 0, _dUsd = parseFloat(_raw[_di].purchasePriceUSD) || 0;
                            var _chg = false;
                            if (_dAfn !== _sAfn) { _raw[_di].purchasePriceAFN = (_dStock * _dAfn + qty * _sAfn) / _denom; _chg = true; }
                            if (_dUsd !== _sUsd) { _raw[_di].purchasePriceUSD = (_dStock * _dUsd + qty * _sUsd) / _denom; _chg = true; }
                            if (_chg) localStorage.setItem('products', JSON.stringify(_raw));
                        }
                    }
                    db.adjustProductStockById(dest.id, qty);
                }
                destId = dest.id;
            } else {
                // ساخت جنس جدید در گدام مقصد با همان مشخصات (موجودی اولیه صفر تا در ورود/خروج دوبار شمرده نشود)
                var copy = Object.assign({}, src);
                delete copy.id;
                delete copy.warehouseId;
                delete copy.createdAt;
                delete copy.updatedAt;
                copy.stock = qty;
                copy.initialStock = 0;
                var res = db.addProductToWarehouse(copy, toId);
                destId = (res && res.data) ? res.data.id : null;
                // به‌روزرسانی فهرست محلی برای ردیف‌های بعدی همین انتقال
                if (res && res.data) allProducts.push(res.data);
            }

            recItems.push({
                srcProductId: src.id,
                destProductId: destId,
                name: src.name || '',
                unit: src.unit || '',
                quantity: qty
            });
        });

        var rec = {
            date: (dateEl && dateEl.value) ? dateEl.value : (typeof db.getCurrentDate === 'function' ? db.getCurrentDate() : ''),
            fromId: fromId,
            fromName: fromWh.name,
            toId: toId,
            toName: toWh.name,
            note: noteEl ? noteEl.value.trim() : '',
            items: recItems
        };
        var _wasEdit = !!_whEditingTransferId;
        if (_wasEdit) {
            rec.id = _whEditingTransferId;
            db.updateTransfer(rec);
            // بازمحاسبهٔ دقیقِ موجودی از رکوردِ ویرایش‌شده (انتقال‌ها به‌صورت idempotent بازپخش می‌شوند)
            if (typeof rebuildAllDerivedData === 'function') { try { rebuildAllDerivedData(); } catch (e) {} }
        } else {
            db.saveTransfer(rec);
        }
        _whEditingTransferId = null;

        // بازخوانی هماهنگ
        if (typeof loadProductsList === 'function') loadProductsList();
        if (typeof loadDashboard === 'function') { try { loadDashboard(); } catch (e) {} }
        if (typeof applyNumberSystemToDocument === 'function') { try { applyNumberSystemToDocument(); } catch (e) {} }
        _updateActiveWarehouseLabel();
        // اگر از داخلِ «لیستِ ورودی و خروجی» آمده‌ایم، همان لیست را تازه کن
        try {
            var _inoutSec = document.getElementById('product-inout-list');
            if (_inoutSec && _inoutSec.classList.contains('active') && window._currentInoutProductId != null && typeof showProductInOutList === 'function') {
                showProductInOutList(window._currentInoutProductId);
            }
        } catch (e) {}

        _whCloseModal();
        showMessage('موفقیت', _wasEdit ? 'انتقال ویرایش شد' : 'انتقال با موفقیت ثبت شد');
    }
    window.submitWarehouseTransfer = submitWarehouseTransfer;

    // ---------- نمایش جزئیات یک انتقال (فقط‌خواندنی) ----------
    function openTransferDetail(transferId) {
        var trs = (typeof db.getTransfers === 'function') ? db.getTransfers() : [];
        var rec = trs.find(function (t) { return t.id == transferId; });
        if (!rec) { showMessage('خطا', 'انتقال یافت نشد'); return; }

        var itemsHtml = (rec.items || []).map(function (it, idx) {
            return '<tr>' +
                '<td>' + (idx + 1) + '</td>' +
                '<td>' + _whEsc(it.name || '') + '</td>' +
                '<td>' + formatNumber(parseFloat(it.quantity) || 0) + ' ' + _whEsc(it.unit || 'عدد') + '</td>' +
            '</tr>';
        }).join('');

        _whModal({
            title: '<i class="fas fa-right-left"></i> جزئیات انتقال',
            body:
                '<div class="wh-form-grid">' +
                    '<div class="wh-field"><label>از گدام</label><input type="text" value="' + _whEsc(rec.fromName || '') + '" readonly style="background:var(--bg-body);"></div>' +
                    '<div class="wh-field"><label>به گدام</label><input type="text" value="' + _whEsc(rec.toName || '') + '" readonly style="background:var(--bg-body);"></div>' +
                    '<div class="wh-field full"><label>تاریخ</label><input type="text" value="' + _whEsc(formatAfghanDateTime(rec.date, rec.createdAt)) + '" readonly style="background:var(--bg-body);"></div>' +
                    (rec.note ? '<div class="wh-field full"><label>یادداشت</label><textarea rows="2" readonly style="background:var(--bg-body);">' + _whEsc(rec.note) + '</textarea></div>' : '') +
                '</div>' +
                '<table class="wh-items-table">' +
                    '<thead><tr><th>#</th><th>جنس</th><th>تعداد</th></tr></thead>' +
                    '<tbody>' + itemsHtml + '</tbody>' +
                '</table>',
            footer: '<button class="btn-secondary" onclick="_whCloseModal()">بستن</button>'
        });
    }
    window.openTransferDetail = openTransferDetail;

    // ---------- مقداردهی اولیه ----------
    window.addEventListener('load', function () {
        setTimeout(_updateActiveWarehouseLabel, 200);
        setTimeout(_updateActiveWarehouseLabel, 700);
    });

// =============================================================================
// ===== راه‌اندازی قفل دیتابیس هنگام باز شدن برنامه ============================
// مستقل از سیستم احراز هویت لایسنس؛ فقط یک لایهٔ رمز کاربر روی ورود به برنامه.
// =============================================================================
(function _setupAppLockOnStartup() {
    if (window.__appLockStartupInstalled) return;
    window.__appLockStartupInstalled = true;
    function run() { try { if (typeof _enforceAppLock === 'function') _enforceAppLock(); } catch(_) {} }
    // اجرای فوری (المان قفل پیش از این اسکریپت در DOM قرار دارد)
    run();
    document.addEventListener('DOMContentLoaded', run);
    window.addEventListener('load', function(){ run(); setTimeout(run, 120); });
})();

/* ══════════════════════════════════════════════════════════════════════════
   موتورِ مقیاسِ خودکارِ صفحه (Auto-Fit Display Engine)
   --------------------------------------------------------------------------
   هدف: هنگامِ باز شدنِ برنامه، کلِ محتوا مطابقِ رزولوشنِ همان کامپیوتر تنظیم
   شود تا نیازی به اسکرولِ افقی یا zoom in/out دستی نباشد.

   روش: عرضِ مبنای طراحی با عرضِ واقعیِ پنجره مقایسه و یک ضریبِ مقیاس محاسبه
   می‌شود؛ سپس روی متغیرِ CSS ‏--app-auto-zoom نوشته می‌شود (html { zoom: … }).
   با تغییرِ اندازهٔ پنجره دوباره محاسبه می‌شود (با debounce تا کارایی حفظ شود).

   کاربر می‌تواند با Ctrl + / Ctrl − مقیاس را دستی تغییر دهد؛ در آن صورت
   مقیاسِ خودکار غیرفعال می‌شود و انتخابِ کاربر باقی می‌ماند (Ctrl+0 = بازگشت).
   ══════════════════════════════════════════════════════════════════════════ */
(function () {
    'use strict';

    var DESIGN_WIDTH  = 1600;   // عرضِ مبنای طراحیِ برنامه
    var DESIGN_HEIGHT = 900;    // ارتفاعِ مبنا (برای جلوگیری از بریدگیِ عمودی)
    var MIN_SCALE     = 0.55;   // کمترین مقیاسِ قابلِ‌خواندن
    var MAX_SCALE     = 1.35;   // بیشترین مقیاس روی نمایشگرهای بزرگ
    var LS_KEY        = 'jouya-manual-zoom';

    function _manualZoom() {
        try {
            var v = parseFloat(localStorage.getItem(LS_KEY));
            return (!isNaN(v) && v > 0) ? v : null;
        } catch (e) { return null; }
    }

    function _computeScale() {
        var vw = window.innerWidth  || document.documentElement.clientWidth  || DESIGN_WIDTH;
        var vh = window.innerHeight || document.documentElement.clientHeight || DESIGN_HEIGHT;
        // ضریب بر اساسِ عرض (اصلی) و ارتفاع (محافظ) — کوچک‌ترین انتخاب می‌شود
        var byW = vw / DESIGN_WIDTH;
        var byH = vh / DESIGN_HEIGHT;
        var s = Math.min(byW, byH * 1.08);   // وزنِ کمترِ ارتفاع تا متن خیلی ریز نشود
        if (isNaN(s) || !isFinite(s) || s <= 0) s = 1;
        if (s < MIN_SCALE) s = MIN_SCALE;
        if (s > MAX_SCALE) s = MAX_SCALE;
        return Math.round(s * 100) / 100;    // گردکردن به ۲ رقم (پرشِ رندر کمتر)
    }

    function _applyAutoFitScale(force) {
        try {
            var manual = _manualZoom();
            var s = (manual && !force) ? manual : _computeScale();
            document.documentElement.style.setProperty('--app-auto-zoom', String(s));
            window._appCurrentZoom = s;
        } catch (e) {}
    }
    window._applyAutoFitScale = _applyAutoFitScale;

    // اجرای اولیه — در اولین ورود، پیش از رنگ‌آمیزیِ صفحه
    _applyAutoFitScale();
    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', function () { _applyAutoFitScale(); });
    }
    window.addEventListener('load', function () { _applyAutoFitScale(); });

    // بازمحاسبه با تغییرِ اندازهٔ پنجره (debounce شده تا کارایی حفظ شود)
    var _rzTimer = null;
    window.addEventListener('resize', function () {
        if (_rzTimer) clearTimeout(_rzTimer);
        _rzTimer = setTimeout(function () { _applyAutoFitScale(); }, 180);
    });

    // ── کنترلِ دستیِ کاربر: Ctrl + / Ctrl − / Ctrl 0 ──
    function _setManual(v) {
        try {
            if (v == null) localStorage.removeItem(LS_KEY);
            else localStorage.setItem(LS_KEY, String(v));
        } catch (e) {}
        _applyAutoFitScale(v == null);
    }
    document.addEventListener('keydown', function (ev) {
        if (!ev.ctrlKey && !ev.metaKey) return;
        var cur = window._appCurrentZoom || 1;
        if (ev.key === '+' || ev.key === '=') {
            ev.preventDefault(); _setManual(Math.min(MAX_SCALE, Math.round((cur + 0.05) * 100) / 100));
        } else if (ev.key === '-' || ev.key === '_') {
            ev.preventDefault(); _setManual(Math.max(MIN_SCALE, Math.round((cur - 0.05) * 100) / 100));
        } else if (ev.key === '0') {
            ev.preventDefault(); _setManual(null);   // بازگشت به مقیاسِ خودکار
        }
    });
})();

// ============================================================================
//  تبدیل ارز بین حساب‌ها — ۴ حالت: بین حساب‌ها / بین اشخاص / داخل حساب / داخل مشتری
//  توجه: این توابع به‌صورت «تعریف تابع» (hoisted) نوشته شده‌اند تا حتی اگر اجرای
//  سطح‌بالای اسکریپت جایی متوقف شود، در دسترس بمانند (نقاط ورود همیشه کار کنند).
//  حساب‌ها: updateCashboxBalance + لاگِ transfer_in/out (نمایش و ماندهٔ درست).
//  اشخاص: تراکنشِ «صرافی» (بدون cashboxId → روی حساب اثر نمی‌گذارد) + موتور دفتر.
// ============================================================================
var _ccReturn = 'financial';

function _ccCurLabel(code) {
    try { if (typeof getCurrencyLabel === 'function') return getCurrencyLabel(code); } catch (e) {}
    return code;
}
function _ccFmt(v) {
    try { return (typeof formatNumber === 'function') ? formatNumber(v) : v; } catch (e) { return v; }
}
function _ccV(id) { var e = document.getElementById(id); return e ? e.value : ''; }
function _ccShow(id, on) { var e = document.getElementById(id); if (e) e.style.display = on ? '' : 'none'; }
function _ccBoxOptions(selectId, selectedId) {
    var sel = document.getElementById(selectId); if (!sel) return;
    var boxes = (typeof db !== 'undefined' && db.getCashboxes) ? (db.getCashboxes() || []) : [];
    var html = '<option value="">انتخاب حساب</option>';
    boxes.forEach(function (b) {
        html += '<option value="' + b.id + '"' + ((selectedId != null && b.id == selectedId) ? ' selected' : '') + '>' + b.name + '</option>';
    });
    sel.innerHTML = html;
}

function openCurrencyConversion(lockType, preset) {
    preset = preset || null;
    var active = document.querySelector('.section.active');
    _ccReturn = (preset && preset.returnSection) ? preset.returnSection : (active ? active.id : 'financial');

    showSection('currency-convert-form');

    if (typeof _populateCurrencySelect === 'function') {
        _populateCurrencySelect('cc-from-cur');
        _populateCurrencySelect('cc-to-cur');
    }
    _ccBoxOptions('cc-from-cashbox', preset && preset.cashboxId);
    _ccBoxOptions('cc-to-cashbox');

    var typeSel = document.getElementById('cc-type');
    var t = lockType || 'between_cashbox';
    if (typeSel) { typeSel.value = t; typeSel.disabled = !!lockType; }

    ['cc-amount', 'cc-rate', 'cc-final', 'cc-notes', 'cc-from-person', 'cc-to-person',
     'cc-from-person-search', 'cc-to-person-search'].forEach(function (id) {
        var e = document.getElementById(id); if (e) e.value = '';
    });
    var opM = document.querySelector('input[name="cc-op"][value="multiply"]'); if (opM) opM.checked = true;

    if (preset && preset.personId && typeof db !== 'undefined') {
        var p = (db.getPersons() || []).find(function (x) { return x.id == preset.personId; });
        if (p) {
            var fh = document.getElementById('cc-from-person'), fs = document.getElementById('cc-from-person-search');
            if (fh) fh.value = p.id; if (fs) fs.value = p.name;
        }
    }

    var dt = document.getElementById('cc-datetime');
    if (dt) {
        try { dt.value = (typeof _nowJalaliDateTime === 'function') ? _nowJalaliDateTime() : ''; } catch (e) { dt.value = ''; }
        if (!dt._dpAttached && typeof _attachDateTimePickerToInput === 'function') { _attachDateTimePickerToInput(dt); dt._dpAttached = true; }
    }

    _ccSetType(t);
    _ccAutoRate();
}

function _ccBack() {
    var r = _ccReturn || 'financial';
    if (r === 'financial' || r === 'currency-convert-form') {
        showSection('financial');
        setTimeout(function () { if (typeof switchFinancialTab === 'function') switchFinancialTab('cashbox'); }, 100);
    } else {
        showSection(r);
    }
}

function _ccSetType(type) {
    var titles = {
        between_cashbox: 'تبدیل ارز بین صندوق‌ها',
        between_person: 'تبدیل ارز بین حساب اشخاص',
        inside_cashbox: 'تبدیل ارز داخل صندوق',
        inside_person: 'تبدیل ارز داخل حساب مشتری'
    };
    var ttl = document.getElementById('cc-title'); if (ttl) ttl.textContent = titles[type] || 'تبدیل ارز';

    var isPerson = (type === 'between_person' || type === 'inside_person');
    var isBetween = (type === 'between_cashbox' || type === 'between_person');

    _ccShow('cc-field-from-cashbox', !isPerson);
    _ccShow('cc-field-from-person', isPerson);
    _ccShow('cc-field-to-cashbox', isBetween && !isPerson);
    _ccShow('cc-field-to-person', isBetween && isPerson);

    var fromCbLbl = document.getElementById('cc-from-cashbox-label');
    var fromPrLbl = document.getElementById('cc-from-person-label');
    if (fromCbLbl) fromCbLbl.textContent = (type === 'inside_cashbox') ? 'انتخاب حساب' : 'از حساب';
    if (fromPrLbl) fromPrLbl.textContent = (type === 'inside_person') ? 'انتخاب شخص' : 'از شخص';
}

function _ccAutoRate() {
    var from = _ccV('cc-from-cur'), to = _ccV('cc-to-cur');
    var rateEl = document.getElementById('cc-rate');
    if (from && to && from !== to && typeof CurrencySystem !== 'undefined' && CurrencySystem.convert) {
        var r = CurrencySystem.convert(1, from, to, 'rate');
        if (r != null && r > 0 && rateEl) {
            rateEl.value = (Math.round(r * 10000) / 10000);
            var opM = document.querySelector('input[name="cc-op"][value="multiply"]'); if (opM) opM.checked = true;
        }
    } else if (from && to && from === to && rateEl) {
        rateEl.value = 1;
    }
    _ccRecalc();
}

function _ccRecalc() {
    var amt = parseFloat(_ccV('cc-amount')) || 0;
    var rate = parseFloat(_ccV('cc-rate')) || 0;
    var op = (document.querySelector('input[name="cc-op"]:checked') || {}).value || 'multiply';
    var out = 0;
    if (amt > 0) { out = (rate > 0) ? ((op === 'divide') ? (amt / rate) : (amt * rate)) : amt; }
    var fe = document.getElementById('cc-final');
    if (fe) fe.value = out ? _ccFmt(Math.round(out * 100) / 100) : '';
}

function _ccSubmit() {
    var type = _ccV('cc-type');
    var fromCur = _ccV('cc-from-cur'), toCur = _ccV('cc-to-cur');
    var amt = parseFloat(_ccV('cc-amount')) || 0;
    var rate = parseFloat(_ccV('cc-rate')) || 0;
    var op = (document.querySelector('input[name="cc-op"]:checked') || {}).value || 'multiply';
    var dt = _ccV('cc-datetime') || '';
    var notes = _ccV('cc-notes') || '';
    var finalAmt = amt > 0 ? (rate > 0 ? ((op === 'divide') ? (amt / rate) : (amt * rate)) : amt) : 0;
    finalAmt = Math.round(finalAmt * 100) / 100;

    if (!fromCur || !toCur) { showMessage('خطا', 'لطفاً نوع ارز (از/به) را انتخاب کنید.'); return; }
    if (amt <= 0) { showMessage('خطا', 'مقدار باید بزرگ‌تر از صفر باشد.'); return; }
    if (finalAmt <= 0) { showMessage('خطا', 'مبلغ نهایی نامعتبر است.'); return; }
    var rateUsed = (amt > 0) ? (finalAmt / amt) : 0;

    if (type === 'between_cashbox') {
        var fId = _ccV('cc-from-cashbox'), tId = _ccV('cc-to-cashbox');
        if (!fId) { showMessage('خطا', 'حساب مبدأ را انتخاب کنید.'); return; }
        if (!tId) { showMessage('خطا', 'حساب مقصد را انتخاب کنید.'); return; }
        if (fId === tId) { showMessage('خطا', 'حساب مبدأ و مقصد نباید یکی باشند.'); return; }
        var boxes = db.getCashboxes() || [];
        var fb = boxes.find(function (b) { return b.id == fId; });
        var tb = boxes.find(function (b) { return b.id == tId; });
        db.updateCashboxBalance(parseInt(fId), amt, 'out', fromCur);
        db.updateCashboxBalance(parseInt(tId), finalAmt, 'in', toCur);
        if (typeof _logCashboxTransaction === 'function') {
            _logCashboxTransaction(parseInt(fId), { type: 'transfer_out', amount: amt, currency: fromCur, datetime: dt,
                relatedCashboxId: parseInt(tId), relatedCashboxName: tb ? tb.name : '', notes: notes,
                description: 'تبدیل ارز به حساب ' + (tb ? tb.name : '') + ' (' + _ccFmt(finalAmt) + ' ' + _ccCurLabel(toCur) + ')' });
            _logCashboxTransaction(parseInt(tId), { type: 'transfer_in', amount: finalAmt, currency: toCur, datetime: dt,
                relatedCashboxId: parseInt(fId), relatedCashboxName: fb ? fb.name : '', notes: notes,
                description: 'تبدیل ارز از حساب ' + (fb ? fb.name : '') + ' (' + _ccFmt(amt) + ' ' + _ccCurLabel(fromCur) + ')' });
        }
        if (typeof addChangelog === 'function') addChangelog('ثبت', 'تبدیل ارز بین صندوق‌ها',
            { fromCur: fromCur, amount: amt, toCur: toCur, finalAmount: finalAmt }, 'تبدیل ارز از ' + (fb ? fb.name : '') + ' به ' + (tb ? tb.name : ''));
    }
    else if (type === 'inside_cashbox') {
        var cId = _ccV('cc-from-cashbox');
        if (!cId) { showMessage('خطا', 'حساب را انتخاب کنید.'); return; }
        if (fromCur === toCur) { showMessage('خطا', 'برای تبدیل داخل حساب باید دو ارزِ متفاوت انتخاب شود.'); return; }
        db.updateCashboxBalance(parseInt(cId), amt, 'out', fromCur);
        db.updateCashboxBalance(parseInt(cId), finalAmt, 'in', toCur);
        if (typeof _logCashboxTransaction === 'function') {
            _logCashboxTransaction(parseInt(cId), { type: 'transfer_out', amount: amt, currency: fromCur, datetime: dt, notes: notes,
                description: 'تبدیل ارز داخل صندوق: ' + _ccFmt(amt) + ' ' + _ccCurLabel(fromCur) + ' → ' + _ccFmt(finalAmt) + ' ' + _ccCurLabel(toCur) });
            _logCashboxTransaction(parseInt(cId), { type: 'transfer_in', amount: finalAmt, currency: toCur, datetime: dt, notes: notes,
                description: 'تبدیل ارز داخل صندوق: ' + _ccFmt(amt) + ' ' + _ccCurLabel(fromCur) + ' → ' + _ccFmt(finalAmt) + ' ' + _ccCurLabel(toCur) });
        }
        if (typeof addChangelog === 'function') addChangelog('ثبت', 'تبدیل ارز داخل صندوق',
            { fromCur: fromCur, amount: amt, toCur: toCur, finalAmount: finalAmt }, 'تبدیل ارز داخل صندوق');
    }
    else if (type === 'inside_person') {
        var pId = _ccV('cc-from-person');
        if (!pId) { showMessage('خطا', 'شخص را انتخاب کنید.'); return; }
        if (fromCur === toCur) { showMessage('خطا', 'برای تبدیل داخل حساب باید دو ارزِ متفاوت انتخاب شود.'); return; }
        // علامتِ حساب: طلبکار(-1) یا بدهکار(+1) در ارزِ مبدأ — تا تبدیل، ماهیتِ حساب را حفظ کند
        var _csIn = _ccPersonSign(pId, fromCur);
        db.saveTransaction({ type: 'صرافی', personId: parseInt(pId), currency: fromCur,
            fromCurrency: fromCur, fromAmount: amt, toCurrency: toCur, toAmount: finalAmt, convSign: _csIn,
            rateUsed: rateUsed, date: dt, createdAt: dt || undefined, notes: notes,
            description: 'تبدیل ارز داخل حساب مشتری: ' + _ccFmt(amt) + ' ' + _ccCurLabel(fromCur) + ' → ' + _ccFmt(finalAmt) + ' ' + _ccCurLabel(toCur) });
        if (typeof addChangelog === 'function') addChangelog('ثبت', 'تبدیل ارز داخل حساب مشتری',
            { personId: pId, fromCur: fromCur, amount: amt, toCur: toCur, finalAmount: finalAmt }, 'تبدیل ارز داخل حساب مشتری');
    }
    else if (type === 'between_person') {
        var aId = _ccV('cc-from-person'), bId = _ccV('cc-to-person');
        if (!aId) { showMessage('خطا', 'شخص مبدأ را انتخاب کنید.'); return; }
        if (!bId) { showMessage('خطا', 'شخص مقصد را انتخاب کنید.'); return; }
        if (aId === bId) { showMessage('خطا', 'شخص مبدأ و مقصد نباید یکی باشند.'); return; }
        var _grp = 'ccx_' + Date.now();
        db.saveTransaction({ type: 'صرافی', personId: parseInt(aId), currency: fromCur,
            fromCurrency: fromCur, fromAmount: amt, toCurrency: fromCur, toAmount: 0, convSign: -1,
            rateUsed: rateUsed, convGroup: _grp, date: dt, createdAt: dt || undefined, notes: notes,
            description: 'تبدیل ارز بین حساب اشخاص (مبدأ): کسرِ ' + _ccFmt(amt) + ' ' + _ccCurLabel(fromCur) });
        db.saveTransaction({ type: 'صرافی', personId: parseInt(bId), currency: toCur,
            fromCurrency: toCur, fromAmount: 0, toCurrency: toCur, toAmount: finalAmt, convSign: -1,
            rateUsed: rateUsed, convGroup: _grp, date: dt, createdAt: dt || undefined, notes: notes,
            description: 'تبدیل ارز بین حساب اشخاص (مقصد): افزودنِ ' + _ccFmt(finalAmt) + ' ' + _ccCurLabel(toCur) });
        if (typeof addChangelog === 'function') addChangelog('ثبت', 'تبدیل ارز بین حساب اشخاص',
            { fromId: aId, toId: bId, fromCur: fromCur, amount: amt, toCur: toCur, finalAmount: finalAmt }, 'تبدیل ارز بین حساب اشخاص');
    }

    showMessage('موفقیت', 'تبدیل ارز با موفقیت ثبت شد.');
    try { if (typeof loadCashboxes === 'function') loadCashboxes(); } catch (e) {}
    try { if (typeof loadPersonsList === 'function') loadPersonsList(); } catch (e) {}
    setTimeout(function () { _ccBack(); }, 700);
}

// نمایش به‌صورت global (سازگاری با فراخوانی از onclickهای HTML)
if (typeof window !== 'undefined') {
    window.openCurrencyConversion = openCurrencyConversion;
    window._ccBack = _ccBack; window._ccSetType = _ccSetType;
    window._ccAutoRate = _ccAutoRate; window._ccRecalc = _ccRecalc; window._ccSubmit = _ccSubmit;
}

// تاشو کردن «اطلاعات بیشتر» در فرم‌های حساب و تبدیل ارز (مانند فرم فروش)
function jfToggleMore(id) {
    var p = document.getElementById(id);
    if (p) p.classList.toggle('jf-more-open');
}
if (typeof window !== 'undefined') window.jfToggleMore = jfToggleMore;

// ============================================================================
//  نمای «اطلاعات فروش / اطلاعات خرید» (tx-detail) — داده‌های لحظه‌ای از تراکنش
//  توابعِ تعریف‌شده (hoisted) تا مستقل از توقفِ بارگذاری همیشه در دسترس باشند.
// ============================================================================
var _txdCurrentId = null;
var _txdReturn = 'sales-list';

function showTxDetail(id, retSection) {
    var tx;
    if (id && typeof id === 'object') {
        tx = id;   // شیءِ ساختگی (مثلاً دریافتیِ داخلِ بل)
    } else {
        var txs = (typeof db !== 'undefined' && db.getTransactions) ? db.getTransactions() : [];
        tx = txs.find(function (t) { return t.id == id; });
    }
    if (!tx) { showMessage('خطا', 'معامله یافت نشد.'); return; }
    _txdCurrentId = tx.id;
    var active = document.querySelector('.section.active');
    _txdReturn = retSection || (active && active.id !== 'tx-detail' ? active.id : 'sales-list');

    var isSale = (tx.type === 'فروش' || tx.type === 'پیش‌فاکتور');
    var isPurchase = (tx.type === 'خرید');
    var isReceipt = (tx.type === 'دریافت');
    var isPayment = (tx.type === 'پرداخت');
    var isBill = isSale || isPurchase;

    var cur = tx.currency || _baseCur();
    var storeName = '';
    try { var st = db.getSettings ? db.getSettings() : null; storeName = (st && st.storeName) ? st.storeName : ''; } catch (e) {}
    var meLabel = storeName || 'مالک (دخل دکان)';
    var partyName = tx.customerName || tx.supplierName || tx.personName || '—';
    var remaining = (typeof calculateTxRemaining === 'function') ? calculateTxRemaining(tx) : (parseFloat(tx.remaining) || 0);
    var total = parseFloat(tx.totalAmount || tx.amount || 0) || 0;
    var paid = total - remaining;
    var disc = parseFloat(tx.totalDiscount || 0) || 0;

    // نامِ حساب (برای دریافت/پرداخت)
    var boxName = '';
    try {
        if (tx.cashboxId != null) {
            var _bx = (db.getCashboxes ? db.getCashboxes() : []).find(function (b) { return b.id == tx.cashboxId; });
            if (_bx) boxName = _bx.name;
        }
    } catch (e) {}

    var _set = function (elid, val, html) { var e = document.getElementById(elid); if (e) { if (html) e.innerHTML = val; else e.textContent = val; } };
    var _show = function (elid, on) { var e = document.getElementById(elid); if (e) e.style.display = on ? '' : 'none'; };

    var titles = { sale: 'اطلاعات فروش', purchase: 'اطلاعات خرید', receipt: 'اطلاعات دریافتی', payment: 'اطلاعات پرداختی' };
    var sumTitles = { sale: 'خلاصه فروش', purchase: 'خلاصه خرید', receipt: 'خلاصه دریافتی', payment: 'خلاصه پرداختی' };
    var editLabels = { sale: 'تصحیح بل', purchase: 'تصحیح بل', receipt: 'تصحیح دریافتی', payment: 'تصحیح پرداختی' };
    var kind = isSale ? 'sale' : isPurchase ? 'purchase' : isReceipt ? 'receipt' : 'payment';
    _txdCurrentKind = kind;
    if (!_txdCollapse) _txdCollapse = { sale: false, purchase: false, receipt: false, payment: false };
    // اعمالِ حالتِ باز/بستهٔ کارت خلاصه به‌صورت مستقل برای هر نوع
    var _sumCard = document.getElementById('txd-card-summary');
    if (_sumCard) { if (_txdCollapse[kind]) _sumCard.classList.add('collapsed'); else _sumCard.classList.remove('collapsed'); }

    _set('txd-title', titles[kind]);
    _set('txd-summary-title', '<i class="fas fa-file-invoice-dollar"></i> ' + sumTitles[kind], true);
    _set('txd-party', partyName);
    _set('txd-billno', (tx.billNumber || tx.reference) ? ((isBill ? 'بل: ' : 'رسید: ') + (tx.billNumber || tx.reference)) : '');
    _set('txd-print-btn', '<i class="fas fa-print"></i> ' + (isSale ? 'چاپ بل فروش' : 'چاپ بل خرید'), true);
    var _editBtn = document.getElementById('txd-edit-btn');
    if (_editBtn) _editBtn.innerHTML = '<i class="fas fa-edit"></i> ' + editLabels[kind];

    // عرضِ خلاصه: بل‌ها متوسط (متمرکز)، دریافت/پرداخت عریض‌تر؛ جدولِ اجناس همیشه تمام‌عرض
    var sumWrap = document.getElementById('txd-summary-wrap');
    if (sumWrap) sumWrap.className = 'txd-summary-wrap ' + (isBill ? 'txd-narrow' : 'txd-wide');

    // ---- ردیف‌های خلاصه ----
    var r = '';
    if (isBill) {
        r += _pdRow('خریدار', _pdEsc(isSale ? partyName : meLabel));
        r += _pdRow('فروشنده', _pdEsc(isSale ? meLabel : partyName));
        r += _pdRow(isSale ? 'مبلغ فروش' : 'مبلغ خرید', _pdCur(total, cur), { valueClass: 'pdc-v-blue', strong: true });
        r += _pdRow(isSale ? 'دریافتی' : 'پرداختی', _pdCur(paid, cur), { valueClass: 'pdc-v-green' });
        r += _pdRow('تخفیف', disc ? _pdCur(disc, cur) : 'ندارد');
        r += _pdRow('زمان', _pdText(tx.date || (tx.createdAt || '').split(' ')[0]));
        r += _pdRow('شرح بل', _pdText(tx.notes || tx.description));
        r += _pdRow('نمبر بل', _pdText(tx.billNumber));
        r += _pdRow('اطلاعات بیشتر', _pdText(tx.saleType || tx.purchaseType || ''));
        if (isSale) r += _pdRow('مفاد', _pdCur(parseFloat(tx.profit || 0) || 0, cur), { valueClass: 'pdc-v-green' });
    } else {
        // دریافت: پرداخت‌کننده=شخص، دریافت‌کننده=ما، «به حساب»
        // پرداخت: پرداخت‌کننده=ما، دریافت‌کننده=شخص، «از حساب»
        r += _pdRow('پرداخت کننده', _pdEsc(isReceipt ? partyName : meLabel));
        r += _pdRow('دریافت کننده', _pdEsc(isReceipt ? meLabel : partyName));
        r += _pdRow(isReceipt ? 'مبلغ دریافتی' : 'مبلغ پرداختی', _pdCur(total, cur), { valueClass: 'pdc-v-blue', strong: true });
        r += _pdRow(isReceipt ? 'به حساب' : 'از حساب', _pdText(boxName));
        r += _pdRow('روش دریافت', _pdText(tx.receiptType || tx.paymentType || ''));
        r += _pdRow('زمان', _pdText(tx.date || (tx.createdAt || '').split(' ')[0]));
        r += _pdRow('رسید نمبر', _pdText(tx.reference));
        r += _pdRow('اطلاعات بیشتر', _pdText(tx.description || tx.notes));
    }
    _set('txd-rows-summary', r, true);

    // ---- اقلام (فقط بل‌ها) ----
    _show('txd-items-card', isBill);
    _show('txd-viewlist-btn', isBill);       // «مشاهده لیست معاملات» فقط در بل‌ها
    _show('txd-remaining-wrap', isBill);     // باقیمانده فقط در بل‌ها
    if (isBill) {
        var items = Array.isArray(tx.items) ? tx.items : [];
        var ih = '';
        if (!items.length) {
            ih = '<tr><td colspan="7" style="text-align:center;color:#94a3b8;padding:14px;">بدون قلم</td></tr>';
        } else {
            items.forEach(function (it, i) {
                var nm = it.productName || it.name || '—';
                var q = parseFloat(it.qty || it.quantity || 0) || 0;
                var unit = it.unit || '';
                var price = parseFloat(it.price || it.unitPrice || 0) || 0;
                var d = parseFloat(it.discount || it.itemDiscount || 0) || 0;
                var line = (it.total != null) ? (parseFloat(it.total) || 0) : (q * price - d);
                ih += '<tr><td>' + (i + 1) + '</td><td style="text-align:right;">' + _pdEsc(nm) + '</td><td>' + _pdFmt(q) + '</td><td>' + _pdEsc(unit) + '</td><td>' + _pdFmt(price) + '</td><td>' + _pdFmt(d) + '</td><td>' + _pdFmt(line) + '</td></tr>';
            });
        }
        _set('txd-items', ih, true);
    }

    _set('txd-remaining', _pdCur(remaining, cur));
    _set('txd-user', (typeof _pdCurrentUserName === 'function') ? _pdCurrentUserName() : '—');
    _set('txd-datetime', tx.createdAt || tx.date || '');

    showSection('tx-detail');
}

function _txdBack() { showSection(_txdReturn || 'sales-list'); }

function _txdViewPartyList() {
    var txs = (typeof db !== 'undefined' && db.getTransactions) ? db.getTransactions() : [];
    var tx = txs.find(function (t) { return t.id == _txdCurrentId; });
    if (!tx) return;
    var pid = tx.customerId || tx.supplierId || tx.personId;
    if (pid && typeof showPersonTransactions === 'function') {
        _ptxReturnToTxDetailId = _txdCurrentId;   // تا برگشت به همین نما باشد
        showPersonTransactions(pid);
    } else {
        showMessage('توجه', 'این معامله به حسابِ شخصی وصل نیست.');
    }
}

function _txdPrint() {
    if (_txdCurrentId == null) return;
    var txs = (typeof db !== 'undefined' && db.getTransactions) ? db.getTransactions() : [];
    var tx = txs.find(function (t) { return t.id == _txdCurrentId; });
    if (tx && tx.type === 'خرید' && typeof printPurchaseBill === 'function') {
        printPurchaseBill(tx.id, tx);
    } else if (typeof printInvoice === 'function') {
        printInvoice(_txdCurrentId);
    }
}

function _txdEdit() {
    if (_txdCurrentId == null) return;
    // پس از ویرایش، به‌جای بازگشایی دوبارهٔ نمای «tx-detail» (که چون سندِ قبلی هنگام ویرایش
    // حذف/بازساخته می‌شود ممکن است پیام «معامله یافت نشد» بدهد)، مستقیماً به همان لیستی که
    // فرم از آن باز شده بود بازگرد: لیست دریافت‌ها/پرداخت‌ها یا لیست معاملاتِ همان فرد.
    var _retSection = _txdReturn || 'sales-list';
    var _ctx = { section: _retSection };
    if (_retSection === 'person-transactions-list') {
        try {
            var _tx = (typeof db !== 'undefined' && db.getTransactions ? db.getTransactions() : []).find(function (t) { return t.id == _txdCurrentId; });
            if (_tx) _ctx.personId = _tx.personId || _tx.customerId || _tx.supplierId || null;
        } catch (e) {}
    }
    if (typeof _setFormReturn === 'function') _setFormReturn(_ctx);
    if (typeof editTransaction === 'function') editTransaction(_txdCurrentId);
}

if (typeof window !== 'undefined') {
    window.showTxDetail = showTxDetail; window._txdBack = _txdBack;
    window._txdViewPartyList = _txdViewPartyList; window._txdPrint = _txdPrint; window._txdEdit = _txdEdit;
}

// کلیک‌پذیر کردنِ ردیف/کارتِ معامله → نمای اطلاعات (به‌جای دکمهٔ «مشاهده»)
function _txdMakeRowClickable(row, txId) {
    if (!row) return;
    row.style.cursor = 'pointer';
    row.addEventListener('click', function (e) {
        if (e.target.closest('.action-trigger-btn, .sales-card-kebab, .btn-icon, .action-buttons, button, a, .person-kebab, .action-bar')) return;
        if (typeof viewTransaction === 'function') viewTransaction(txId);
    });
}
if (typeof window !== 'undefined') window._txdMakeRowClickable = _txdMakeRowClickable;

// ============================================================================
//  فلتر/مرتب‌سازی — بستن و ریستِ یکپارچه (بدون نقض، هماهنگ در همهٔ بخش‌ها)
//  توابعِ تعریف‌شده (hoisted) تا مستقل از توقفِ بارگذاری همیشه در دسترس باشند.
// ============================================================================
function _resetAllFilterSortMenus() {
    try {
        // ۱) بستنِ همهٔ منوهای باز (فلتر/مرتب/انتخاب گدام)
        document.querySelectorAll('.sort-menu, .filter-menu, .warehouse-menu').forEach(function (m) { m.style.display = 'none'; });

        // ۲) ریستِ مقادیرِ فیلتر به پیش‌فرض (همه/خالی) تا با برگشت به بخش، فلتر از بین رفته باشد
        document.querySelectorAll('.filter-menu select').forEach(function (s) {
            try {
                // ترجیحاً گزینهٔ value="all" وگرنه اولین گزینه
                var allOpt = s.querySelector('option[value="all"]');
                if (allOpt) s.value = 'all'; else s.selectedIndex = 0;
            } catch (e) {}
        });
        document.querySelectorAll('.filter-menu input[type="text"], .filter-menu input[type="number"], .filter-menu input[type="date"], .filter-menu input.jalali-date').forEach(function (inp) {
            try { inp.value = ''; } catch (e) {}
        });
        // مرتب‌سازی: به اولین گزینه (پیش‌فرض) برگردد
        document.querySelectorAll('.sort-menu select').forEach(function (s) {
            try { s.selectedIndex = 0; } catch (e) {}
        });
        // دکمه/آیتم‌های مرتب‌سازیِ «فعال» (اگر با کلاس active کار می‌کنند)
        document.querySelectorAll('.sort-menu .active, .filter-menu .active').forEach(function (b) { b.classList.remove('active'); });
    } catch (e) {}
}

// بستنِ منوها هنگامِ کلیک بیرون (یکپارچه — جایگزینِ هندلرهای پراکنده)
document.addEventListener('click', function (e) {
    if (e.target.closest('.sort-menu') || e.target.closest('.filter-menu') ||
        e.target.closest('.warehouse-menu') || e.target.closest('.filter-icon-btn') ||
        e.target.closest('#warehouse-select-btn')) return;
    var open = document.querySelectorAll('.sort-menu, .filter-menu, .warehouse-menu');
    open.forEach(function (m) { if (m.style.display === 'block') m.style.display = 'none'; });
}, true);

if (typeof window !== 'undefined') window._resetAllFilterSortMenus = _resetAllFilterSortMenus;

// نمای دریافتی/پرداختیِ داخلِ بل (نقدِ ثبت‌شده هنگام فروش/خرید) — شیءِ ساختگی از روی بل
function _txdEmbeddedReceipt(saleId) {
    var sale = (db.getTransactions ? db.getTransactions() : []).find(function (t) { return t.id == saleId; });
    if (!sale) { showMessage('خطا', 'بل یافت نشد.'); return; }
    var cur = sale.currency || _baseCur();
    var recv = (cur === 'USD') ? (parseFloat(sale.cashUsd || 0) || 0) : (parseFloat(sale.cashAfn || 0) || 0);
    showTxDetail({
        id: sale.id, type: 'دریافت',
        personId: sale.customerId, personName: sale.customerName, customerName: sale.customerName,
        date: sale.date, createdAt: sale.createdAt, amount: recv, currency: cur,
        cashboxId: sale.cashboxId, receiptType: 'نقد', reference: '',
        description: 'دریافتِ نقدِ بلِ فروش ' + (sale.billNumber || '')
    }, 'receipts-list');
}
function _txdEmbeddedPayment(purchaseId) {
    var pur = (db.getTransactions ? db.getTransactions() : []).find(function (t) { return t.id == purchaseId; });
    if (!pur) { showMessage('خطا', 'بل یافت نشد.'); return; }
    var cur = pur.currency || _baseCur();
    var paid = (cur === 'USD') ? (parseFloat(pur.cashUsd || 0) || 0) : (parseFloat(pur.cashAfn || 0) || 0);
    showTxDetail({
        id: pur.id, type: 'پرداخت',
        personId: pur.supplierId, personName: pur.supplierName, supplierName: pur.supplierName,
        date: pur.date, createdAt: pur.createdAt, amount: paid, currency: cur,
        cashboxId: pur.cashboxId, paymentType: 'نقد', reference: '',
        description: 'پرداختِ نقدِ بلِ خرید ' + (pur.billNumber || '')
    }, 'payments-list');
}
if (typeof window !== 'undefined') { window._txdEmbeddedReceipt = _txdEmbeddedReceipt; window._txdEmbeddedPayment = _txdEmbeddedPayment; }

// ============================================================================
//  دیالوگِ تاییدِ استایل‌دار (ناهمگام) — جایگزینِ confirm() بومی، هم‌رنگِ بقیه دیالوگ‌ها
// ============================================================================
function showStyledConfirm(title, message, onConfirm) {
    var modal = document.getElementById('confirmModal');
    var titleEl = document.getElementById('confirmTitle');
    var bodyEl = document.getElementById('confirmBody');
    var actionBtn = document.getElementById('confirmAction');
    if (!modal || !actionBtn) { if (window.confirm(String(message).replace(/<br\s*\/?>/g, '\n'))) { if (typeof onConfirm === 'function') onConfirm(); } return; }
    if (titleEl) titleEl.innerHTML = '<i class="fas fa-exclamation-triangle"></i> ' + (title || 'تایید');
    if (bodyEl) bodyEl.innerHTML = String(message).replace(/\n/g, '<br>');
    // پاک‌کردنِ هندلرِ قبلی با جایگزینیِ دکمه
    var fresh = actionBtn.cloneNode(true);
    actionBtn.parentNode.replaceChild(fresh, actionBtn);
    fresh.onclick = function () { if (typeof closeConfirmModal === 'function') closeConfirmModal(); else modal.style.display = 'none'; if (typeof onConfirm === 'function') onConfirm(); };
    modal.style.display = 'block';
}
// پرچمِ «تاییدِ موجودی منفیِ حساب» برای الگوی فراخوانیِ مجدد
var _negBalOK = false;
if (typeof window !== 'undefined') { window.showStyledConfirm = showStyledConfirm; }

// تاییدِ «ادامه با موجودی منفیِ حساب» با دیالوگِ استایل‌دار (الگوی فراخوانیِ مجدد — بدون تغییرِ منطق)
function _confirmNegBalance(message, proceedFn) {
    if (_negBalOK) { _negBalOK = false; return true; }   // قبلاً تایید شده → ادامه بده
    showStyledConfirm('کمبود موجودی حساب', message, function () { _negBalOK = true; if (typeof proceedFn === 'function') proceedFn(); });
    return false;                                          // این بار متوقف شو تا کاربر تصمیم بگیرد
}
if (typeof window !== 'undefined') window._confirmNegBalance = _confirmNegBalance;

// ============================================================================
//  اعتبارسنجیِ درون‌فیلدی — هشدارِ سرخ زیر فیلدِ الزامیِ خالی (بدونِ تغییرِ منطقِ ذخیره)
// ============================================================================
function _setFieldError(el, msg) {
    if (!el) return;
    el.classList.add('field-invalid');
    var wrap = el.closest('.bill-field, .jf-field');
    if (wrap) wrap.classList.add('field-invalid-wrap');
    var host = wrap || el.closest('.product-col, .form-group, .filter-group') || el;
    var errId = '_fe_' + (el.id || (el.name || 'x') + Math.random().toString(36).slice(2, 7));
    if (!el.dataset._feId) el.dataset._feId = errId;
    var existing = document.getElementById(el.dataset._feId);
    if (!existing) {
        existing = document.createElement('span');
        existing.className = 'field-error-msg';
        existing.id = el.dataset._feId;
        if (host && host.parentNode) host.parentNode.insertBefore(existing, host.nextSibling);
        else if (el.parentNode) el.parentNode.appendChild(existing);
    }
    existing.textContent = msg || 'این فیلد الزامی است';
    existing.style.display = 'block';
}
function _clearFieldError(el) {
    if (!el) return;
    el.classList.remove('field-invalid');
    var wrap = el.closest('.bill-field, .jf-field');
    if (wrap) wrap.classList.remove('field-invalid-wrap');
    if (el.dataset && el.dataset._feId) {
        var ex = document.getElementById(el.dataset._feId);
        if (ex) ex.remove();
    }
}
function _validateRequiredFields(container) {
    if (!container) return true;
    var ok = true;
    var list = container.querySelectorAll('[required]');
    Array.prototype.forEach.call(list, function (f) {
        if (f.disabled || f.type === 'hidden' || f.offsetParent === null) return;   // مخفی/غیرفعال را نادیده بگیر
        if (!String(f.value || '').trim()) { _setFieldError(f, f.getAttribute('data-req-msg') || 'این فیلد الزامی است'); ok = false; }
        else { _clearFieldError(f); }
    });
    return ok;
}
// ناپدیدشدنِ خودکارِ هشدار وقتی فیلد پر شد + شنوندهٔ سراسریِ submit
// در یک تابعِ hoist‌شده ثبت می‌شوند و از showSection فراخوانی می‌شوند تا مستقل از
// توقفِ اجرای سطح‌بالا (throw خط ۹۹۹۵) حتماً فعال شوند.
var _ivHandlersAttached = false;
function _attachInlineValidation() {
    if (_ivHandlersAttached) return;
    _ivHandlersAttached = true;
    document.addEventListener('input', function (e) { if (e.target && String(e.target.value || '').trim() && e.target.classList && e.target.classList.contains('field-invalid')) _clearFieldError(e.target); }, true);
    document.addEventListener('change', function (e) { if (e.target && String(e.target.value || '').trim() && e.target.classList && e.target.classList.contains('field-invalid')) _clearFieldError(e.target); }, true);
    document.addEventListener('submit', function (e) {
        var form = e.target;
        if (!form || form.tagName !== 'FORM') return;
        if (!_validateRequiredFields(form)) { e.preventDefault(); e.stopImmediatePropagation(); }
    }, true);
}
if (typeof window !== 'undefined') { window._validateRequiredFields = _validateRequiredFields; window._setFieldError = _setFieldError; window._clearFieldError = _clearFieldError; window._attachInlineValidation = _attachInlineValidation; }

// ============================================================================
//  ثبتِ هندلرِ «بستن با کلیک بیرون» برای منوهای فلتر/مرتب/گدام
//  از داخلِ توابعِ toggle (که hoist‌شده‌اند) فراخوانی می‌شود تا مستقل از توقفِ
//  اجرای سطح‌بالا (throw خط ۹۹۹۵) حتماً ثبت شود. فقط یک‌بار ثبت می‌شود.
// ============================================================================
var _fsCloseHandlerAttached = false;
function _attachFsCloseHandler() {
    if (_fsCloseHandlerAttached) return;
    _fsCloseHandlerAttached = true;
    // فاز capture تا حتی اگر عنصری propagation را متوقف کند، اجرا شود
    document.addEventListener('click', function (e) {
        if (e.target.closest('.sort-menu') || e.target.closest('.filter-menu') ||
            e.target.closest('.warehouse-menu') || e.target.closest('.filter-icon-btn') ||
            e.target.closest('#warehouse-select-btn')) return;
        var menus = document.querySelectorAll('.sort-menu, .filter-menu, .warehouse-menu');
        menus.forEach(function (m) {
            if (m.style.display === 'block' || m.classList.contains('active')) {
                m.style.display = 'none';
                m.classList.remove('active');
            }
        });
    }, true);
}
if (typeof window !== 'undefined') window._attachFsCloseHandler = _attachFsCloseHandler;

// حالتِ باز/بستهٔ کارتِ خلاصه — مستقل برای هر نوعِ نما (فروش/خرید/دریافت/پرداخت)
var _txdCurrentKind = 'sale';
var _txdCollapse = { sale: false, purchase: false, receipt: false, payment: false };
function _txdToggleSummary() {
    var card = document.getElementById('txd-card-summary');
    if (!card) return;
    if (!_txdCollapse) _txdCollapse = { sale: false, purchase: false, receipt: false, payment: false };
    if (!_txdCurrentKind) _txdCurrentKind = 'sale';
    card.classList.toggle('collapsed');
    _txdCollapse[_txdCurrentKind] = card.classList.contains('collapsed');
}
if (typeof window !== 'undefined') window._txdToggleSummary = _txdToggleSummary;

// علامتِ حسابِ شخص در یک ارز: طلبکار(-1) / بدهکار(+1) — از منبعِ واحد buildPersonLedger
function _ccPersonSign(personId, currency) {
    try {
        var p = (db.getPersons ? db.getPersons() : []).find(function (x) { return x.id == personId; });
        if (!p || typeof buildPersonLedger !== 'function') return 1;
        var led = buildPersonLedger(p);
        var bal = (led && led.balances && led.balances[currency] != null) ? parseFloat(led.balances[currency]) : 0;
        return (bal < 0) ? -1 : 1;
    } catch (e) { return 1; }
}
if (typeof window !== 'undefined') window._ccPersonSign = _ccPersonSign;

// ============================================================================
//  لیست آخرین تغییرات — کلیک روی ردیف سند مربوطه را باز می‌کند + منوی سه‌نقطه (برگشت/حذف)
// ============================================================================
function _openChangelogDoc(logId) {
    var logs = [];
    try { logs = JSON.parse(localStorage.getItem('changelog') || '[]'); } catch (e) {}
    var log = logs.find(function (l) { return l.id == logId; });
    if (!log) return;
    var d = log.dataSnapshot || {};
    var t = log.type;
    if ((t === 'فروش' || t === 'خرید' || t === 'دریافت' || t === 'پرداخت') && d.id != null && typeof viewTransaction === 'function') { viewTransaction(d.id); return; }
    if (t === 'شخص' && d.id != null && typeof showPersonDetail === 'function') { showPersonDetail(d.id); return; }
    if (t === 'جنس' && d.id != null && typeof showProductDetail === 'function') { showProductDetail(d.id); return; }
    if (t === 'صندوق') { showSection('financial'); setTimeout(function () { if (typeof switchFinancialTab === 'function') switchFinancialTab('cashbox'); }, 100); return; }
    if (typeof viewChangelogDetail === 'function') viewChangelogDetail(logId);
}
function _deleteChangelog(logId) {
    try {
        var logs = JSON.parse(localStorage.getItem('changelog') || '[]');
        logs = logs.filter(function (l) { return l.id != logId; });
        localStorage.setItem('changelog', JSON.stringify(logs));
        if (typeof loadChangelogList === 'function') loadChangelogList();
        if (typeof showToast === 'function') showToast('رکورد حذف شد', 'success');
    } catch (e) {}
}
function _closeChangelogActionBar() { var b = document.getElementById('_clogActionBar'); if (b) b.remove(); }
function showChangelogActionBar(event, logId) {
    try {
        _closeChangelogActionBar();
        var logs = JSON.parse(localStorage.getItem('changelog') || '[]');
        var log = logs.find(function (l) { return l.id == logId; }) || {};
        var bar = document.createElement('div');
        bar.className = 'clog-action-bar';
        bar.id = '_clogActionBar';
        var undoBtn = (!log.undone) ? '<button type="button" onclick="_closeChangelogActionBar(); undoChange(' + logId + ');"><i class="fas fa-undo"></i> برگشت از تغییر</button>' : '';
        bar.innerHTML = undoBtn + '<button type="button" onclick="_closeChangelogActionBar(); _deleteChangelog(' + logId + ');"><i class="fas fa-trash"></i> حذف</button>';
        document.body.appendChild(bar);
        var r = (event.currentTarget || event.target).getBoundingClientRect();
        bar.style.position = 'fixed';
        bar.style.top = (r.bottom + 4) + 'px';
        bar.style.left = Math.max(8, r.left - 90) + 'px';
        bar.style.zIndex = 99999;
        setTimeout(function () { document.addEventListener('click', _closeChangelogActionBar, { once: true }); }, 10);
    } catch (e) {}
}
if (typeof window !== 'undefined') {
    window._openChangelogDoc = _openChangelogDoc; window._deleteChangelog = _deleteChangelog;
    window.showChangelogActionBar = showChangelogActionBar; window._closeChangelogActionBar = _closeChangelogActionBar;
}

// ============================================================================
//  سه‌تبِ مقصدِ دریافت فوری — حساب‌ها / اشخاص / مصارف (در فضای همان فیلد حساب)
//  تابع‌ها hoisted تا مستقل از توقفِ اجرای سطح‌بالا (throw خط ۹۹۹۵) کار کنند.
// ============================================================================
var _receiptDestTab = 'cashbox';
function _receiptSwitchTab(tab) {
    _receiptDestTab = tab;
    var wrap = document.querySelector('.receipt-dest-wrap');
    if (!wrap) return;
    Array.prototype.forEach.call(wrap.querySelectorAll('.receipt-dest-tab'), function (b) {
        b.classList.toggle('is-active', b.getAttribute('data-tab') === tab);
    });
    Array.prototype.forEach.call(wrap.querySelectorAll('.receipt-dest-pane'), function (p) {
        p.style.display = (p.getAttribute('data-pane') === tab) ? '' : 'none';
    });
    // پرکردنِ کتگوریِ مصرف هنگام نخستین بازکردنِ تبِ مصارف
    if (tab === 'expense') _receiptInitExpenseCategory();
}
function _receiptSearchDestPerson() { /* onfocus خودش به پیکرِ اشخاص می‌رود؛ این no-op برای ایمنی است */ }
function _receiptInitExpenseCategory() {
    try {
        var sel = document.getElementById('receipt-expense-category');
        if (!sel || sel._rdInited) return;
        // کتگوری‌های پیش‌فرض + سفارشی (همان منبعِ فرم مصرف)
        var defaults = ['مصرف روزانه دکان', 'کرایه دکان', 'کرایه اجناس', 'حقوق کارمندان', 'تبلیغات', 'ترانسپورت', 'قرطاسیه', 'مهمانی', 'متفرقه'];
        var customs = [];
        try { customs = JSON.parse(localStorage.getItem('customExpenseCategories') || '[]'); } catch (e) { customs = []; }
        var all = defaults.concat(customs.filter(function (c) { return defaults.indexOf(c) === -1; }));
        all.forEach(function (c) {
            if (!Array.prototype.some.call(sel.options, function (o) { return o.value === c; })) {
                var op = document.createElement('option'); op.value = c; op.textContent = c; sel.appendChild(op);
            }
        });
        if (typeof setupProductAddSelect === 'function') setupProductAddSelect(sel, 'customExpenseCategories', 'کتگوری مصرف');
        sel._rdInited = true;
    } catch (e) {}
}
function _receiptResetDestTabs() {
    _receiptDestTab = 'cashbox';
    var wrap = document.querySelector('.receipt-dest-wrap');
    if (!wrap) return;
    Array.prototype.forEach.call(wrap.querySelectorAll('.receipt-dest-tab'), function (b) { b.classList.toggle('is-active', b.getAttribute('data-tab') === 'cashbox'); });
    Array.prototype.forEach.call(wrap.querySelectorAll('.receipt-dest-pane'), function (p) { p.style.display = (p.getAttribute('data-pane') === 'cashbox') ? '' : 'none'; });
    var dp = document.getElementById('receipt-dest-person'); if (dp) dp.value = '';
    var dps = document.getElementById('receipt-dest-person-search'); if (dps) dps.value = '';
    var ec = document.getElementById('receipt-expense-category'); if (ec) ec.value = '';
}
if (typeof window !== 'undefined') {
    window._receiptSwitchTab = _receiptSwitchTab; window._receiptSearchDestPerson = _receiptSearchDestPerson;
    window._receiptInitExpenseCategory = _receiptInitExpenseCategory; window._receiptResetDestTabs = _receiptResetDestTabs;
}
